INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P1','Nguyễn Minh (阮明)',22,'Du học sinh Việt Nam mới đến Trung Quốc, học Thương mại quốc tế','Lễ phép, hơi rón rén, tiếng Trung mức trung bình, cẩn thận') ON CONFLICT DO NOTHING;
INSERT INTO personas (id,name,age,background,personality_traits) VALUES ('P2','Lâm Vũ (林宇)',23,'Bạn cùng phòng người Trung Quốc','Nhiệt tình, thoải mái, hay giúp đỡ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM01','呀','Hỏi/đáp nhẹ nhàng, giảm cảm giác cứng nhắc') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM02','啦','Nhẹ nhõm, vui vẻ, hoặc dứt điểm một việc') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM03','哦','Chỉnh/bổ sung thông tin nhẹ nhàng, không phủ định gắt') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM04','呢','Bổ sung/giải thích, hoặc thể hiện hơi bối rối/băn khoăn') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM05','啊','Hỏi lịch sự hoặc biểu lộ ngạc nhiên nhẹ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM06','哈','Nhắc nhẹ, thân thiện, kéo gần khoảng cách hội thoại') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM07','吧','Đề nghị/xác nhận mang tính dò hỏi, không chắc chắn tuyệt đối') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM08','嘞','Đáp lời sảng khoái, đậm chất khẩu ngữ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM09','嘛','Giọng hiển nhiên, thân mật, xoa dịu') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM10','哎呀','Tự trách/ngại ngùng bất ngờ') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM11','咯','Xác nhận nhẹ nhàng, coi như hiển nhiên/dứt khoát, giọng thân mật') ON CONFLICT DO NOTHING;
INSERT INTO attitude_markers (id,marker,meaning) VALUES ('AM12','诶','Than nhẹ, nhấn mạnh điều bất tiện/khó xử vừa nói tới') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_A','Gọi lái xe taxi/xe công nghệ là ''thầy'' (师傅) bất kể tuổi','Cách gọi phổ biến, thể hiện sự tôn trọng, không phân biệt tuổi tác. Lặp lại ở các tình huống đi taxi/xe công nghệ.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_B','Ưu tiên thanh toán quét mã; mạng chậm thì chờ, không thúc ép; một số quán chỉ nhận quét mã','Thanh toán điện tử là chủ đạo ở Trung Quốc; tài xế/người bán thường kiên nhẫn chờ khách quét mã, và nhiều cửa hàng nhỏ không nhận tiền mặt.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_C','Ký túc xá quản lý theo quy định thống nhất, không có ngoại lệ','Giờ đóng cửa và quy định khách thăm áp dụng chung cho mọi sinh viên, kể cả sinh viên quốc tế.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_D','Thiết bị công cộng (đèn, máy giặt...) hỏng thì báo quản lý, không tự sửa','Trường/ký túc xá chịu trách nhiệm sửa chữa miễn phí; có thể đổi sang thiết bị khác dùng tạm trong lúc chờ.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_E','Thủ tục hành chính với sinh viên quốc tế cần thêm giấy xác nhận đang học','Chỉ hộ chiếu và visa thường chưa đủ để mở tài khoản ngân hàng hay làm một số thủ tục, cần bổ sung giấy xác nhận đang học.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_F','Thanh toán di động bắt buộc xác thực danh tính thật','Sinh viên nước ngoài dùng hộ chiếu để xác thực, không cần CMND Trung Quốc.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_G','Hồ sơ thiếu giấy tờ thường được cho nộp bổ sung có thời hạn','Chỉ cần thành thật xin lỗi và có kế hoạch bổ sung rõ ràng, không cần quá lo lắng.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_H','Biên phòng/hải quan làm việc theo nguyên tắc trung thực, ngắn gọn','Không cần giải thích dài dòng, chỉ cần trả lời đúng và đủ thông tin được hỏi.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_I','Đi nhầm chiều tàu điện ngầm có thể đổi chiều miễn phí ngay tại sân ga đối diện','Không cần ra cổng mua lại vé, chỉ cần sang sân ga đối diện, việc chuyển tuyến trong nhà ga là miễn phí.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_J','Có thể lịch sự đề nghị lái xe đổi lộ trình khi tắc đường mà không bị phụ thu thêm','Tài xế taxi/xe công nghệ thường chủ động hợp tác khi khách giải thích lý do gấp.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_K','Phí vận chuyển thực tế có thể cao hơn phí dự tính trên app nếu hàng quá cân','Đây là phụ thu hợp lệ theo cân nặng thật, không phải shipper tự ý tính thêm.') ON CONFLICT DO NOTHING;
INSERT INTO cultural_patterns (id,pattern_name,description) VALUES ('CP_M','Nên chủ động hỏi lại nhân viên nếu nghi ngờ thông tin vừa thay đổi (băng chuyền, cổng ra...)','Không nên tự đoán theo đám đông; thông tin sân bay có thể thay đổi tạm thời so với bảng hiển thị ban đầu.') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT201','S1','Điền tờ khai nhập cảnh trên máy bay','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V201','SIT201','P1','suon_se','ban_chinh_thuc','Nhờ tiếp viên hướng dẫn điền tờ khai nhập cảnh','Tiếp viên trên máy bay giữ giọng mềm mỏng, hành khách hỏi thoải mái không cần quá rón rén.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_01','V201','Nguyễn Minh',1,'乘务员您好，我不太会填这个入境登记卡，能麻烦您教教我吗？','chéng wù yuán nín hǎo， wǒ bù tài huì tián zhè ge rù jìng dēng jì kǎ， néng má fán nín jiāo jiāo wǒ ma？','Chào chị tiếp viên, em không rành cách điền tờ khai nhập cảnh này lắm, chị có thể chỉ giúp em được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_02','V201','Tiếp viên',2,'没问题呀，我来跟你说。你护照上的信息照着填就行啦。','méi wèn tí ya， wǒ lái gēn nǐ shuō。 nǐ hù zhào shàng de xìn xī zhào zhe tián jiù xíng la。','Không sao đâu, để chị nói cho em nghe. Cứ theo thông tin trên hộ chiếu mà điền là được nha.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_03','V201','Nguyễn Minh',3,'好的，请问“来华事由”这一栏，我填“留学”就可以了吧？','hǎo de， qǐng wèn “lái huá shì yóu” zhè yī lán， wǒ tián “liú xué” jiù kě yǐ le ba？','Dạ vâng, vậy mục "lý do đến Trung Quốc", em ghi "du học" là được đúng không chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_04','V201','Tiếp viên',4,'对的，完全没问题。停留时间就写你签证上的时长哦。','duì de， wán quán méi wèn tí。 tíng liú shí jiān jiù xiě nǐ qiān zhèng shàng de shí cháng ó。','Đúng rồi, hoàn toàn ổn. Thời gian lưu trú thì ghi theo thời hạn trên visa của em là được nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_05','V201','Nguyễn Minh',5,'那籍贯和出生地，直接填越南可以吗？','nà jí guàn hé chū shēng dì， zhí jiē tián yuè nán kě yǐ ma？','Vậy nguyên quán với nơi sinh, em ghi thẳng Việt Nam là được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_06','V201','Tiếp viên',6,'可以的，不用写太详细，简洁填写就好啦。','kě yǐ de， bù yòng xiě tài xiáng xì， jiǎn jié tián xiě jiù hǎo la。','Được đó, không cần ghi chi tiết quá đâu, điền đơn giản là được nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_07','V201','Nguyễn Minh',7,'太谢谢您了，帮了我大忙！','tài xiè xiè nín le， bāng le wǒ dà máng！','Em cảm ơn chị nhiều lắm, chị giúp em một việc lớn đó!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L201_08','V201','Tiếp viên',8,'不客气哈，有不懂的随时再问我。','bú kè qì hā， yǒu bù dǒng de suí shí zài wèn wǒ。','Không có gì đâu, có gì không hiểu cứ hỏi chị bất cứ lúc nào nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT202','S1','Hỏi lối ra sân bay','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V202','SIT202','P1','suon_se','ban_chinh_thuc','Hỏi hướng ra sân bay sau khi hạ cánh, được chỉ dẫn rõ ràng','Nhân viên sân bay chỉ đường thường dùng cách nói dễ hiểu, không dùng thuật ngữ phức tạp.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_01','V202','Nguyễn Minh',1,'您好，麻烦问一下，机场出口是往这边走吗？','nín hǎo， má fán wèn yī xià， jī chǎng chū kǒu shì wǎng zhè biān zǒu ma？','Chào chị, cho em hỏi lối ra sân bay là đi hướng này ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_02','V202','Nhân viên',2,'不是哦，这边是转机通道，出口在你的左手边呢。','bú shì ó， zhè biān shì zhuǎn jī tōng dào， chū kǒu zài nǐ de zuǒ shǒu biān ne。','Không phải đâu, bên này là lối chuyển tiếp chuyến bay đó, lối ra ở phía tay trái em nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_03','V202','Nguyễn Minh',3,'左手边是吗？一直直走就到了吧？','zuǒ shǒu biān shì ma？ yì zhí zhí zǒu jiù dào le ba？','Tay trái ạ? Cứ đi thẳng là tới đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_04','V202','Nhân viên',4,'对的，直走到底左转，跟着“国内到达”的牌子走就行啦。','duì de， zhí zǒu dào dǐ zuǒ zhuǎn， gēn zhe “guó nèi dào dá” de pái zi zǒu jiù xíng la。','Đúng rồi, đi thẳng đến cuối rồi rẽ trái, cứ theo biển "Đến quốc nội" mà đi là được nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_05','V202','Nguyễn Minh',5,'好的，我明白了，谢谢您！','hǎo de， wǒ míng bái le， xiè xiè nín！','Dạ vâng, em hiểu rồi, cảm ơn chị nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L202_06','V202','Nhân viên',6,'没事的，慢走哈！','méi shì de， màn zǒu hā！','Không có gì đâu, đi cẩn thận nhé!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT203','S1','Hỏi băng chuyền nhận hành lý','Băng chuyền bị đổi tạm thời so với thông tin ban đầu','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V203','SIT203','P1','twist','chinh_thuc','Băng chuyền bị đổi tạm thời so với thông tin ban đầu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_01','V203','Nguyễn Minh',1,'您好，我想请问一下，国际航班的行李在哪里领取啊？','nín hǎo， wǒ xiǎng qǐng wèn yī xià， guó jì háng bān de xíng lǐ zài nǎ lǐ lǐng qǔ a？','Xin chào, tôi muốn hỏi hành lý của chuyến bay quốc tế lấy ở đâu ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_02','V203','Nhân viên',2,'您好，请问你的航班号是多少呢？','nín hǎo， qǐng wèn nǐ de háng bān hào shì duō shǎo ne？','Chào anh, cho tôi hỏi số hiệu chuyến bay của anh là gì ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_03','V203','Nguyễn Minh',3,'是VN520航班，麻烦您查一下。','shì VN520 háng bān， má fán nín chá yī xià。','Là chuyến VN520, phiền chị kiểm tra giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_04','V203','Nhân viên',4,'稍等，这班航班原本在3号转盘，刚刚临时调整到5号转盘了哦。','shāo děng， zhè bān háng bān yuán běn zài 3 hào zhuàn pán， gāng gāng lín shí diào zhěng dào 5 hào zhuàn pán le ó。','Anh đợi chút, chuyến này ban đầu ở băng chuyền số 3, nhưng vừa mới tạm thời chuyển sang băng chuyền số 5 rồi ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_05','V203','Nguyễn Minh',5,'原来是这样，还好我问了，不然就走错啦。','yuán lái shì zhè yàng， hái hǎo wǒ wèn le， bù rán jiù zǒu cuò la。','Thì ra là vậy, may mà tôi hỏi, không thì đi nhầm chỗ mất.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_06','V203','Nhân viên',6,'是的，近期偶尔会调整，你直接去5号转盘等候就行。','shì de， jìn qī ǒu ěr huì tiáo zhěng， nǐ zhí jiē qù 5 hào zhuàn pán děng hòu jiù xíng。','Vâng, gần đây thỉnh thoảng có điều chỉnh, anh cứ ra thẳng băng chuyền số 5 đợi là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L203_07','V203','Nguyễn Minh',7,'好的，非常感谢您！','hǎo de， fēi cháng gǎn xiè nín！','Được rồi, cảm ơn chị rất nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT204','S5','Mua SIM và tư vấn gói cước','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V204','SIT204','P1','twist','tuy_y','Chọn gói data phù hợp, hệ thống cửa hàng chậm phải chờ kích hoạt',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_01','V204','Nguyễn Minh',1,'你好，我是留学生，想办一张流量多的电话卡，有合适的套餐吗？','nǐ hǎo， wǒ shì liú xué shēng， xiǎng bàn yī zhāng liú liàng duō de diàn huà kǎ， yǒu hé shì de tào cān ma？','Chào bạn, mình là du học sinh, muốn mua một cái sim điện thoại nhiều data, có gói nào phù hợp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_02','V204','Nhân viên',2,'有的呀，这款学生套餐性价比超高，每月超多流量呢。','yǒu de ya， zhè kuǎn xué shēng tào cān xìng jià bǐ chāo gāo， měi yuè chāo duō liú liàng ne。','Có chứ, gói sinh viên này giá cả hợp lý lắm, mỗi tháng data siêu nhiều luôn đó.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_03','V204','Nguyễn Minh',3,'那这个套餐可以直接当场激活吧？','nà zhè ge tào cān kě yǐ zhí jiē dāng chǎng jī huó ba？','Vậy gói này kích hoạt luôn tại chỗ được đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_04','V204','Nhân viên',4,'本来可以的，不过今天系统有点卡，需要等两分钟哦。','běn lái kě yǐ de， bù guò jīn tiān xì tǒng yǒu diǎn kǎ， xū yào děng liǎng fēn zhōng ó。','Bình thường thì được, nhưng hôm nay hệ thống hơi lag, phải đợi khoảng hai phút nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_05','V204','Nguyễn Minh',5,'没事的，我可以等，麻烦你啦。','méi shì de， wǒ kě yǐ děng， má fán nǐ la。','Không sao đâu, mình đợi được, phiền bạn nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_06','V204','Nhân viên',6,'不麻烦！马上就好，激活后我帮你调好网络设置哈。','bù má fán！ mǎ shàng jiù hǎo， jī huó hòu wǒ bāng nǐ diào hǎo wǎng luò shè zhì hā。','Không phiền đâu! Xong ngay thôi, kích hoạt xong mình chỉnh mạng luôn cho bạn nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L204_07','V204','Nguyễn Minh',7,'太好了，谢谢你！','tài hǎo le， xiè xiè nǐ！','Tuyệt quá, cảm ơn bạn nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT205','S4','Trả lời biên phòng khi nhập cảnh','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V205','SIT205','P1','suon_se','chinh_thuc','Trình bày mục đích, trường học, chuyên ngành, thời gian học, nguồn tài trợ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_01','V205','Biên phòng',1,'你好，出示一下护照和签证。来华目的是什么？','nǐ hǎo， chū shì yī xià hù zhào hé qiān zhèng。 lái huá mù dì shì shén me？','Chào anh, xuất trình hộ chiếu và visa. Mục đích sang Trung Quốc lần này là gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_02','V205','Nguyễn Minh',2,'您好，我来中国留学的。','nín hǎo， wǒ lái zhōng guó liú xué de。','Chào anh, tôi sang Trung Quốc để du học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_03','V205','Biên phòng',3,'在哪所学校就读？什么专业？','zài nǎ suǒ xué xiào jiù dú？ shén me zhuān yè？','Anh học ở trường nào? Chuyên ngành gì?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_04','V205','Nguyễn Minh',4,'我在省城理工大学，就读国际贸易专业。','wǒ zài shěng chéng lǐ gōng dà xué， jiù dú guó jì mào yì zhuān yè。','Tôi học tại Đại học Bách khoa Tỉnh thành, chuyên ngành Thương mại quốc tế.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_05','V205','Biên phòng',5,'学习时长多久？资金来源是哪里？','xué xí shí cháng duō jiǔ？ zī jīn lái yuán shì nǎ lǐ？','Thời gian học bao lâu? Nguồn tài chính lấy từ đâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_06','V205','Nguyễn Minh',6,'我学习四年，学费和生活费由家里提供。','wǒ xué xí sì nián， xué fèi hé shēng huó fèi yóu jiā lǐ tí gōng。','Tôi học bốn năm, học phí và sinh hoạt phí do gia đình chu cấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_07','V205','Biên phòng',7,'好的，信息核对无误，入境通过。','hǎo de， xìn xī hé duì wú wù， rù jìng tōng guò。','Được rồi, thông tin đối chiếu chính xác, anh được phép nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L205_08','V205','Nguyễn Minh',8,'谢谢工作人员！','xiè xiè gōng zuò rén yuán！','Cảm ơn cán bộ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT206','S4','Xin biên phòng nói chậm/lặp lại','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V206','SIT206','P1','suon_se','chinh_thuc','Nghe không rõ câu hỏi, xin lỗi và đề nghị nói chậm hơn',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_01','V206','Biên phòng',1,'你本次入境是否携带校外兼职相关材料？','nǐ běn cì rù jìng shì fǒu xié dài xiào wài jiān zhí xiāng guān cái liào？','Lần nhập cảnh này anh có mang theo giấy tờ liên quan đến việc làm thêm ngoài trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_02','V206','Nguyễn Minh',2,'不好意思，我没太听懂您的问题呢。','bù hǎo yì sī， wǒ méi tài tīng dǒng nín de wèn tí ne。','Xin lỗi, tôi chưa nghe rõ câu hỏi của anh lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_03','V206','Biên phòng',3,'没关系，那我放慢语速，再说一遍。','méi guān xì， nà wǒ fàng màn yǔ sù， zài shuō yī biàn。','Không sao, để tôi nói chậm lại, hỏi lại lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_04','V206','Nguyễn Minh',4,'麻烦您了，我的中文听力还不太好。','má fán nín le， wǒ de zhōng wén tīng lì hái bù tài hǎo。','Phiền anh quá, khả năng nghe tiếng Trung của tôi chưa được tốt lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_05','V206','Biên phòng',5,'没事，我问你有没有带校外工作、兼职的证明材料？','méi shì， wǒ wèn nǐ yǒu méi yǒu dài xiào wài gōng zuò、 jiān zhí de zhèng míng cái liào？','Không sao, tôi hỏi là anh có mang theo giấy tờ chứng minh làm việc, làm thêm ngoài trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_06','V206','Nguyễn Minh',6,'没有的，我目前只专注学业，没有准备兼职材料。','méi yǒu de， wǒ mù qián zhǐ zhuān zhù xué yè， méi yǒu zhǔn bèi jiān zhí cái liào。','Không có ạ, hiện tại tôi chỉ tập trung học tập, không chuẩn bị giấy tờ làm thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L206_07','V206','Biên phòng',7,'好的，了解了。','hǎo de， liǎo jiě le。','Được rồi, tôi hiểu rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT207','S4','Khai báo hải quan','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V207','SIT207','P1','suon_se','chinh_thuc','Trả lời không có gì khai báo, nhưng vẫn bị mở vali kiểm tra ngẫu nhiên',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_01','V207','Hải quan',1,'你好，请问你本次入境有没有需要申报的物品？','nǐ hǎo， qǐng wèn nǐ běn cì rù jìng yǒu méi yǒu xū yào shēn bào de wù pǐn？','Chào anh, cho hỏi lần nhập cảnh này anh có vật phẩm gì cần khai báo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_02','V207','Nguyễn Minh',2,'您好，我没有贵重物品，也没有超额物品，不需要申报的。','nín hǎo， wǒ méi yǒu guì zhòng wù pǐn， yě méi yǒu chāo é wù pǐn， bù xū yào shēn bào de。','Chào chị, tôi không có đồ giá trị, cũng không có đồ vượt định mức, không cần khai báo ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_03','V207','Hải quan',3,'有没有携带大量现金、电子产品或者管制物品？','yǒu méi yǒu xié dài dà liàng xiàn jīn、 diàn zi chǎn pǐn huò zhě guǎn zhì wù pǐn？','Anh có mang theo nhiều tiền mặt, thiết bị điện tử hay đồ vật thuộc diện quản lý không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_04','V207','Nguyễn Minh',4,'没有的，只带了个人生活用品和少量现金。','méi yǒu de， zhǐ dài le gè rén shēng huó yòng pǐn hé shǎo liàng xiàn jīn。','Không có ạ, tôi chỉ mang đồ dùng cá nhân và một ít tiền mặt thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_05','V207','Hải quan',5,'好的，确认无申报物品，可以通行了。','hǎo de， què rèn wú shēn bào wù pǐn， kě yǐ tōng xíng le。','Được rồi, xác nhận không có đồ cần khai báo, anh có thể đi qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L207_06','V207','Nguyễn Minh',6,'好的，谢谢您！','hǎo de， xiè xiè nín！','Vâng, cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT208','S4','Khai báo thuốc mang theo','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V208','SIT208','P1','twist','chinh_thuc','Phải khai báo thuốc tự dùng, không có đơn thuốc dịch sang tiếng Trung','Có thể mang theo thuốc tự dùng số lượng nhỏ; thuốc kê đơn nên có đơn thuốc dịch sang tiếng Trung và giữ lại vỏ hộp để thuận tiện khi kiểm tra.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_01','V208','Hải quan',1,'除了生活用品，还有其他需要申报的东西吗？','chú le shēng huó yòng pǐn， hái yǒu qí tā xū yào shēn bào de dōng xī ma？','Ngoài đồ dùng sinh hoạt ra, anh còn có gì khác cần khai báo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_02','V208','Nguyễn Minh',2,'有的，我随身带了一些常用感冒药和肠胃药，需要申报吧？','yǒu de， wǒ suí shēn dài le yī xiē cháng yòng gǎn mào yào hé cháng wèi yào， xū yào shēn bào ba？','Có ạ, tôi có mang theo một ít thuốc cảm và thuốc dạ dày thường dùng, chắc phải khai báo đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_03','V208','Hải quan',3,'是的，自用药品需要报备，带了多少数量呢？','shì de， zì yòng yào pǐn xū yào bào bèi， dài le duō shǎo shù liàng ne？','Đúng vậy, thuốc tự dùng cần khai báo, anh mang theo bao nhiêu vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_04','V208','Nguyễn Minh',4,'都是个人短期自用的，没有大批量携带哦。','dōu shì gè rén duǎn qī zì yòng de， méi yǒu dà pī liàng xié dài ó。','Toàn là dùng ngắn ngày cho cá nhân thôi, không mang số lượng lớn đâu ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_05','V208','Hải quan',5,'我看一下，没问题，自用常规药品可以放行，无需登记。','wǒ kàn yī xià， méi wèn tí， zì yòng cháng guī yào pǐn kě yǐ fàng xíng， wú xū dēng jì。','Để tôi xem qua, không vấn đề gì, thuốc thông thường dùng cá nhân được phép mang qua, không cần đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_06','V208','Nguyễn Minh',6,'太好了，谢谢您的耐心核对！','tài hǎo le， xiè xiè nín de nài xīn hé duì！','Tuyệt quá, cảm ơn anh đã kiên nhẫn kiểm tra giúp tôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L208_07','V208','Hải quan',7,'不客气，下次尽量保留药品外包装哦。','bú kè qì， xià cì jǐn liàng bǎo liú yào pǐn wài bāo zhuāng ó。','Không có gì, lần sau anh nhớ giữ lại bao bì thuốc nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT209','S1','Báo hành lý hư hỏng','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V209','SIT209','P1','that_bai_nhe','ban_chinh_thuc','Hành lý bị vỡ, cần đăng ký để xử lý bồi thường','Hành lý hư hỏng ở sân bay được đăng ký bồi thường miễn phí; cần giữ thẻ hành lý và thẻ lên máy bay, không tự bỏ đi rồi mới báo sau.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_01','V209','Nguyễn Minh',1,'您好，麻烦您，我的行李箱好像被摔坏了。','nín hǎo， má fán nín， wǒ de xíng lǐ xiāng hǎo xiàng bèi shuāi huài le。','Chào chị, phiền chị chút, vali của tôi hình như bị va đập hỏng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_02','V209','Nhân viên',2,'别着急，我看一下，是箱体破损还是轮子损坏呀？','bié zháo jí， wǒ kàn yī xià， shì xiāng tǐ pò sǔn hái shì lún zi sǔn huài ya？','Anh đừng lo, để tôi xem, là vỏ vali bị nứt hay bánh xe bị hỏng vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_03','V209','Nguyễn Minh',3,'箱体侧面裂开了，里面的东西没坏，但是箱子没法用了。','xiāng tǐ cè miàn liè kāi le， lǐ miàn de dōng xī méi huài， dàn shì xiāng zi méi fǎ yòng le。','Cạnh bên vali bị nứt, đồ bên trong không sao, nhưng vali thì không dùng được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_04','V209','Nhân viên',4,'我明白了，需要登记你的航班信息和行李牌，后续走理赔流程呢。','wǒ míng bái le， xū yào dēng jì nǐ de háng bān xìn xī hé xíng lǐ pái， hòu xù zǒu lǐ péi liú chéng ne。','Tôi hiểu rồi, cần đăng ký thông tin chuyến bay và thẻ hành lý của anh, sau đó sẽ tiến hành quy trình bồi thường ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_05','V209','Nguyễn Minh',5,'好的，我马上提供，大概多久能处理好呀？','hǎo de， wǒ mǎ shàng tí gōng， dà gài duō jiǔ néng chǔ lǐ hǎo ya？','Được, tôi cung cấp ngay đây, khoảng bao lâu thì xử lý xong vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_06','V209','Nhân viên',6,'三个工作日内会有结果，你耐心等待通知就行。','sān gè gōng zuò rì nèi huì yǒu jié guǒ， nǐ nài xīn děng dài tōng zhī jiù xíng。','Trong vòng ba ngày làm việc sẽ có kết quả, anh cứ kiên nhẫn chờ thông báo nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L209_07','V209','Nguyễn Minh',7,'辛苦您了，谢谢！','xīn kǔ nín le， xiè xiè！','Cảm ơn chị nhiều, chị vất vả rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT210','S6','Đổi tiền và hỏi tỷ giá','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V210','SIT210','P1','twist','ban_chinh_thuc','Đổi tiền tại sân bay, tỷ giá thấp hơn ngân hàng trong thành phố','机场外币兑换汇率略低于市区银行，适合小额应急兑换，大额兑换建议去正规银行；往返双向兑换会产生双重汇兑损耗，尽量按需兑换。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_01','V210','阮明',1,'您好，我刚落地机场，想把随身带的越南盾兑换成人民币。','nín hǎo， wǒ gāng luò dì jī chǎng， xiǎng bǎ suí shēn dài de yuè nán dùn duì huàn chéng rén mín bì。','Chào chị, em vừa hạ cánh xuống sân bay, muốn đổi số tiền đồng mang theo sang nhân dân tệ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_02','V210','职员',2,'您好，先跟您确认一下，您清楚机场兑换点和市区银行汇率有差别吗？','nín hǎo， xiān gēn nín què rèn yī xià， nín qīng chǔ jī chǎng duì huàn diǎn hé shì qū yín háng huì lǜ yǒu chā bié ma？','Chào bạn, để tôi xác nhận trước, bạn có biết tỷ giá đổi tiền ở sân bay và ngân hàng trong thành phố có chênh lệch không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_03','V210','阮明',3,'之前听同学提过一句，但具体差多少我不太了解啊。','zhī qián tīng tóng xué tí guò yī jù， dàn jù tǐ chà duō shǎo wǒ bù tài liǎo jiě a。','Trước đây em có nghe bạn học nhắc qua, nhưng cụ thể chênh bao nhiêu thì em không rõ lắm ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_04','V210','职员',4,'今日实时汇率牌价就在柜台上方，机场汇率会比市区银行低三个点哦。','jīn rì shí shí huì lǜ pái jià jiù zài guì tái shàng fāng， jī chǎng huì lǜ huì bǐ shì qū yín háng dī sān gè diǎn ó。','Bảng tỷ giá thực tế hôm nay ở ngay phía trên quầy đó, tỷ giá ở sân bay sẽ thấp hơn ngân hàng trong thành phố khoảng ba điểm ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_05','V210','阮明',5,'这样啊，差价还挺明显，那我先兑换一千元人民币应急可以吗？','zhè yàng a， chā jià hái tǐng míng xiǎn， nà wǒ xiān duì huàn yī qiān yuán rén mín bì yìng jí kě yǐ ma？','Vậy à, chênh lệch cũng khá rõ đấy, vậy giờ em đổi trước một nghìn tệ để dùng tạm được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_06','V210','职员',6,'兑换外币有流程要求，需要出示护照登记个人信息哈。','duì huàn wài bì yǒu liú chéng yāo qiú， xū yào chū shì hù zhào dēng jì gè rén xìn xī hā。','Đổi ngoại tệ có quy trình yêu cầu, cần xuất trình hộ chiếu để đăng ký thông tin cá nhân nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_07','V210','阮明',7,'没问题，护照我一直随身带着，现在递给您。那手续费是单独收取的吗？','méi wèn tí， hù zhào wǒ yì zhí suí shēn dài zhe， xiàn zài dì gěi nín。 nà shǒu xù fèi shì dān dú shōu qǔ de ma？','Không vấn đề gì, hộ chiếu em luôn mang theo người, giờ em đưa chị đây ạ. Vậy phí dịch vụ có tính riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_08','V210','职员',8,'单笔一千元以内的小额兑换免手续费，系统已经直接帮您核算完毕。','dān bǐ yī qiān yuán yǐ nèi de xiǎo é duì huàn miǎn shǒu xù fèi， xì tǒng yǐ jīng zhí jiē bāng nín hé suàn wán bì。','Giao dịch nhỏ dưới một nghìn tệ thì được miễn phí dịch vụ, hệ thống đã tính toán xong cho bạn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_09','V210','阮明',9,'我再多问一句，如果剩下没花完的人民币，还能在这里换回越南盾吗？','wǒ zài duō wèn yī jù， rú guǒ shèng xià méi huā wán de rén mín bì， hái néng zài zhè lǐ huàn huí yuè nán dùn ma？','Em hỏi thêm một chút, nếu số nhân dân tệ còn dư chưa tiêu hết, thì có thể đổi lại ra tiền đồng ở đây được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_10','V210','职员',10,'可以兑换返程外币，但二次兑换会再收取一笔汇兑差价，不太划算。','kě yǐ duì huàn fǎn chéng wài bì， dàn èr cì duì huàn huì zài shōu qǔ yī bǐ huì duì chā jià， bù tài huá suàn。','Có thể đổi lại ngoại tệ khi về, nhưng đổi lần hai sẽ bị tính thêm một khoản chênh lệch tỷ giá, không được lời lắm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_11','V210','阮明',11,'明白了，那我就只换一千元，够用今天打车吃饭就行。','míng bái le， nà wǒ jiù zhǐ huàn yī qiān yuán， gòu yòng jīn tiān dǎ chē chī fàn jiù xíng。','Em hiểu rồi ạ, vậy em chỉ đổi một nghìn tệ thôi, đủ dùng đi taxi với ăn uống hôm nay là được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_12','V210','职员',12,'好，我现在按实时汇率帮您清点现金，稍等片刻。','hǎo， wǒ xiàn zài àn shí shí huì lǜ bāng nín qīng diǎn xiàn jīn， shāo děng piàn kè。','Được, giờ tôi theo tỷ giá thực tế đếm tiền mặt cho bạn, đợi một chút nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_13','V210','阮明',13,'辛苦您了，汇率有变动也麻烦您再跟我说一声。','xīn kǔ nín le， huì lǜ yǒu biàn dòng yě má fán nín zài gēn wǒ shuō yī shēng。','Cảm ơn chị nhiều ạ, nếu tỷ giá có thay đổi thì phiền chị báo lại em với ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_14','V210','职员',14,'刚刚已经核对过牌价，短时间不会波动，现金给您收好。','gāng gāng yǐ jīng hé duì guò pái jià， duǎn shí jiān bú huì bō dòng， xiàn jīn gěi nín shōu hǎo。','Vừa rồi tôi đã kiểm tra lại bảng giá rồi, trong thời gian ngắn sẽ không biến động đâu, tiền mặt đây bạn cất kỹ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L210_15','V210','阮明',15,'太感谢您耐心讲解，省去我不少麻烦，那就兑换吧！','tài gǎn xiè nín nài xīn jiǎng jiě， shěng qù wǒ bù shǎo má fán， nà jiù duì huàn ba！','Cảm ơn chị đã kiên nhẫn giải thích, đỡ cho em bao nhiêu là phiền phức, vậy mình đổi tiền luôn nhé!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT211','S5','Kết nối WiFi sân bay','Xin mật khẩu wifi, phải xác thực qua số điện thoại','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V211','SIT211','P1','suon_se','tuy_y','Xin mật khẩu wifi, phải xác thực qua số điện thoại',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_01','V211','Nguyễn Minh',1,'你好，请问机场的免费WiFi密码是多少呀？','nǐ hǎo， qǐng wèn jī chǎng de miǎn fèi WiFi mì mǎ shì duō shǎo ya？','Chào bạn, cho mình hỏi mật khẩu wifi miễn phí của sân bay là gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_02','V211','Nhân viên',2,'很简单的，密码是机场全称的首字母加八个八哦。','hěn jiǎn dān de， mì mǎ shì jī chǎng quán chēng de shǒu zì mǔ jiā bā gè bā ó。','Đơn giản lắm, mật khẩu là chữ cái đầu của tên đầy đủ sân bay cộng thêm tám số 8 đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_03','V211','Nguyễn Minh',3,'我试了一下，怎么连不上呢？','wǒ shì le yī xià， zěn me lián bù shàng ne？','Mình thử rồi mà sao không kết nối được nhỉ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_04','V211','Nhân viên',4,'需要先打开浏览器验证一下，登录之后就能用啦。','xū yào xiān dǎ kāi liú lǎn qì yàn zhèng yī xià， dēng lù zhī hòu jiù néng yòng la。','Cần mở trình duyệt lên xác thực trước đã, đăng nhập xong là dùng được ngay thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_05','V211','Nguyễn Minh',5,'原来是这样，太感谢你啦！','yuán lái shì zhè yàng， tài gǎn xiè nǐ la！','Ra là vậy, cảm ơn bạn nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L211_06','V211','Nhân viên',6,'没事哒，有问题再问哈！','méi shì dá， yǒu wèn tí zài wèn hā！','Có gì đâu, có vấn đề gì thì hỏi tiếp nhé!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT212','S1','Gọi người đón, báo vị trí','Báo cho bạn đến đón biết mình đã tới và đang ở đâu','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V212','SIT212','P1','suon_se','tuy_y','Báo cho bạn đến đón biết mình đã tới và đang ở đâu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_01','V212','Nguyễn Minh',1,'宇哥，我已经到机场啦，顺利入境了！','yǔ gē， wǒ yǐ jīng dào jī chǎng la， shùn lì rù jìng le！','Anh Vũ ơi, em đến sân bay rồi nè, nhập cảnh suôn sẻ luôn!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_02','V212','Đón (Trần Vũ)',2,'太好了！你现在在哪个位置呀？','tài hǎo le！ nǐ xiàn zài zài nǎ ge wèi zhì ya？','Tốt quá! Em đang ở chỗ nào vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_03','V212','Nguyễn Minh',3,'我在国内到达出口的问询台旁边呢。','wǒ zài guó nèi dào dá chū kǒu de wèn xún tái páng biān ne。','Em đang đứng cạnh quầy hỏi thông tin ở cửa ra đến trong nước nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_04','V212','Đón (Trần Vũ)',4,'好的，我马上就到，你就在原地等我别乱跑哈。','hǎo de， wǒ mǎ shàng jiù dào， nǐ jiù zài yuán dì děng wǒ bié luàn pǎo hā。','Được rồi, anh tới ngay đây, em cứ đứng yên đó chờ anh, đừng chạy lung tung nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_05','V212','Nguyễn Minh',5,'没问题，我就在这里等你，不着急的。','méi wèn tí， wǒ jiù zài zhè lǐ děng nǐ， bù zháo jí de。','Không sao đâu, em đứng đây chờ anh, không vội đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L212_06','V212','Đón (Trần Vũ)',6,'五分钟就到，一会儿见！','wǔ fēn zhōng jiù dào， yī huì er jiàn！','Năm phút nữa là tới, lát gặp nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT213','S1','Không thấy người đón, gọi xác nhận','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V213','SIT213','P1','twist','tuy_y','Đến nơi nhưng không thấy người đón, hai bên đứng nhầm cổng khác nhau',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_01','V213','Nguyễn Minh',1,'宇哥，我已经在出口等了十分钟了，没看到你呀。','yǔ gē， wǒ yǐ jīng zài chū kǒu děng le shí fēn zhōng le， méi kàn dào nǐ ya。','Anh Vũ ơi, em đứng ở cửa ra chờ mười phút rồi mà chưa thấy anh đâu cả.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_02','V213','Đón (Trần Vũ)',2,'哎呀抱歉！我走错出口了，我在二号出口，你在几号呀？','āi yā bào qiàn！ wǒ zǒu cuò chū kǒu le， wǒ zài èr hào chū kǒu， nǐ zài jǐ hào ya？','Ôi xin lỗi em! Anh đi nhầm cửa ra rồi, anh đang ở cửa số 2, em ở cửa số mấy vậy?','AM10') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_03','V213','Nguyễn Minh',3,'我在一号出口，难怪看不到呢。','wǒ zài yī hào chū kǒu， nán guài kàn bú dào ne。','Em ở cửa số 1, thảo nào không thấy nhau.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_04','V213','Đón (Trần Vũ)',4,'太不好意思了！我马上走通道过来，两分钟就到你那边。','tài bù hǎo yì sī le！ wǒ mǎ shàng zǒu tōng dào guò lái， liǎng fēn zhōng jiù dào nǐ nà biān。','Ngại quá đi! Anh chạy qua lối đi liền, hai phút nữa là tới chỗ em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_05','V213','Nguyễn Minh',5,'没事没事，不着急，我慢慢等你就好啦。','méi shì méi shì， bù zháo jí， wǒ màn màn děng nǐ jiù hǎo la。','Không sao không sao, không vội đâu, em cứ từ từ chờ anh là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L213_06','V213','Đón (Trần Vũ)',6,'辛苦你啦，马上汇合！','xīn kǔ nǐ la， mǎ shàng huì hé！','Vất vả em rồi, gặp nhau ngay đây!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT214','S2','Đặt xe công nghệ, xác nhận tài xế','Xác nhận đúng tài xế và biển số trước khi lên xe','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V214','SIT214','P1','suon_se','tuy_y','Xác nhận đúng tài xế và biển số trước khi lên xe',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_01','V214','Tài xế',1,'你好，是尾号3621的乘客吧？我到机场上车点了。','nǐ hǎo， shì wěi hào 3621 de chéng kè ba？ wǒ dào jī chǎng shàng chē diǎn le。','Chào bạn, có phải khách hàng số điện thoại đuôi 3621 không ạ? Tôi tới điểm đón ở sân bay rồi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_02','V214','Nguyễn Minh',2,'对的是我！麻烦问一下，您的车牌号是多少呀？','duì de shì wǒ！ má fán wèn yī xià， nín de chē pái hào shì duō shǎo ya？','Đúng em đây ạ! Cho em hỏi, biển số xe của anh là gì vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_03','V214','Tài xế',3,'车牌是浙A8523K，黑色轿车，很好认的。','chē pái shì zhè A8523K， hēi sè jiào chē， hěn hǎo rèn de。','Biển số là 浙A8523K, xe con màu đen, dễ nhận ra lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_04','V214','Nguyễn Minh',4,'好的，我看到您的车了，马上走过去哈。','hǎo de， wǒ kàn dào nín de chē le， mǎ shàng zǒu guò qù hā。','Dạ vâng, em thấy xe anh rồi, em qua ngay đây ạ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_05','V214','Tài xế',5,'不急，慢慢走，注意身边行李就行。','bù jí， màn màn zǒu， zhù yì shēn biān xíng lǐ jiù xíng。','Không vội đâu, cứ từ từ, chú ý hành lý bên cạnh là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L214_06','V214','Nguyễn Minh',6,'好嘞，辛苦您等我一下！','hǎo lei， xīn kǔ nín děng wǒ yī xià！','Dạ vâng, phiền anh chờ em một chút nha!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT215','S2','Báo địa chỉ đến cho tài xế','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V215','SIT215','P1','suon_se','tuy_y','Thông báo địa chỉ trường, nhờ tài xế lưu ý vì lần đầu đi',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_01','V215','Tài xế',1,'同学，我们现在出发，你去哪里呀？','tóng xué， wǒ men xiàn zài chū fā， nǐ qù nǎ lǐ ya？','Em ơi, mình xuất phát đây, em đi đâu vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_02','V215','Nguyễn Minh',2,'师傅您好，麻烦去省城理工大学留学生公寓。','shī fù nín hǎo， má fán qù shěng chéng lǐ gōng dà xué liú xué shēng gōng yù。','Chào bác tài, phiền bác chở em đến khu ký túc xá lưu học sinh trường Đại học Bách khoa tỉnh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_03','V215','Tài xế',3,'是新校区那个留学生宿舍吧？','shì xīn xiào qū nà ge liú xué shēng sù shè ba？','Là ký túc xá lưu học sinh ở khu campus mới đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_04','V215','Nguyễn Minh',4,'对的！我第一次去，辛苦您多留意路线呢。','duì de！ wǒ dì yī cì qù， xīn kǔ nín duō liú yì lù xiàn ne。','Dạ đúng rồi ạ! Em đi lần đầu, phiền bác để ý đường đi giúp em với ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_05','V215','Tài xế',5,'放心吧，这条路我常跑，不会走错的。','fàng xīn ba， zhè tiáo lù wǒ cháng pǎo， bú huì zǒu cuò de。','Yên tâm đi, đoạn đường này bác chạy quen rồi, không đi nhầm đâu.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L215_06','V215','Nguyễn Minh',6,'那就太好了，谢谢您！','nà jiù tài hǎo le， xiè xiè nín！','Vậy thì tốt quá, cảm ơn bác nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT216','S2','Thanh toán quét mã sau khi đi taxi','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V216','SIT216','P1','twist','tuy_y','Mạng chậm khi quét mã thanh toán, tài xế kiên nhẫn chờ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_01','V216','Tài xế',1,'同学，我们到学校门口啦，车程结束了。','tóng xué， wǒ men dào xué xiào mén kǒu la， chē chéng jié shù le。','Em ơi, tới cổng trường rồi nè, chuyến xe kết thúc rồi đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_02','V216','Nguyễn Minh',2,'好的！我想扫码支付，可是手机网络有点慢怎么办？','hǎo de！ wǒ xiǎng sǎo mǎ zhī fù， kě shì shǒu jī wǎng luò yǒu diǎn màn zěn me bàn？','Dạ vâng! Em muốn quét mã thanh toán mà mạng điện thoại hơi chậm, phải làm sao đây bác?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_03','V216','Tài xế',3,'没关系呀，不急，你慢慢加载就行。','méi guān xì ya， bù jí， nǐ màn màn jiā zài jiù xíng。','Không sao đâu, không vội đâu, em cứ từ từ để nó tải là được.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_04','V216','Nguyễn Minh',4,'终于好了，已经支付成功啦，您看一下！','zhōng yú hǎo le， yǐ jīng zhī fù chéng gōng la， nín kàn yī xià！','Cuối cùng cũng xong rồi, thanh toán thành công rồi ạ, bác xem qua giúp em!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_05','V216','Tài xế',5,'收到了，没问题。路上辛苦了，欢迎下次坐车哈！','shōu dào le， méi wèn tí。 lù shàng xīn kǔ le， huān yíng xià cì zuò chē hā！','Nhận được rồi, ổn cả. Đường xa vất vả rồi, lần sau đi xe cứ gọi bác nhé!','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L216_06','V216','Nguyễn Minh',6,'谢谢师傅，再见！','xiè xiè shī fù， zài jiàn！','Cảm ơn bác tài, tạm biệt ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT217','S7','Nhận phòng ký túc xá','Xuất trình giấy tờ, nhận phòng và chìa khóa','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V217','SIT217','P1','suon_se','ban_chinh_thuc','Xuất trình giấy tờ, nhận phòng và chìa khóa',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_01','V217','Nguyễn Minh',1,'老师您好，我是新来的留学生，今天来办理宿舍入住。','lǎo shī nín hǎo， wǒ shì xīn lái de liú xué shēng， jīn tiān lái bàn lǐ sù shè rù zhù。','Chào thầy/cô, em là lưu học sinh mới đến, hôm nay em đến làm thủ tục nhận phòng ký túc xá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_02','V217','Tiền sảnh',2,'好的，请出示你的护照和入学通知书哦。','hǎo de， qǐng chū shì nǐ de hù zhào hé rù xué tōng zhī shū ó。','Được, phiền bạn xuất trình hộ chiếu và giấy báo nhập học nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_03','V217','Nguyễn Minh',3,'好的，这是我的证件和录取文件，您看一下。','hǎo de， zhè shì wǒ de zhèng jiàn hé lù qǔ wén jiàn， nín kàn yī xià。','Dạ vâng, đây là giấy tờ và giấy báo trúng tuyển của em, thầy/cô xem giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_04','V217','Tiền sảnh',4,'信息核对无误，这是你的宿舍钥匙和门禁卡。','xìn xī hé duì wú wù， zhè shì nǐ de sù shè yào shi hé mén jìn kǎ。','Thông tin đối chiếu chính xác rồi, đây là chìa khóa phòng và thẻ ra vào của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_05','V217','Nguyễn Minh',5,'请问我的宿舍是几楼几号呀？','qǐng wèn wǒ de sù shè shì jǐ lóu jǐ hào ya？','Cho em hỏi phòng của em ở tầng mấy, số mấy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_06','V217','Tiền sảnh',6,'四楼408室，单人留学生宿舍，条件还不错呢。','sì lóu 408 shì， dān rén liú xué shēng sù shè， tiáo jiàn hái bú cuò ne。','Tầng 4, phòng 408, phòng ký túc xá lưu học sinh một người, điều kiện cũng khá đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L217_07','V217','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn thầy/cô nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT218','S7','Ký hợp đồng ở ký túc xá','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V218','SIT218','P1','suon_se','ban_chinh_thuc','Đọc và ký hợp đồng, hỏi về điều khoản cơ bản',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_01','V218','Tiền sảnh',1,'这是留学生住宿合同，你仔细看一下条款哦。','zhè shì liú xué shēng zhù sù hé tóng， nǐ zǐ xì kàn yī xià tiáo kuǎn ó。','Đây là hợp đồng ký túc xá dành cho lưu học sinh, em xem kỹ các điều khoản nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_02','V218','Nguyễn Minh',2,'好的，请问主要是住宿规定和缴费事项吧？','hǎo de， qǐng wèn zhǔ yào shì zhù sù guī dìng hé jiǎo fèi shì xiàng ba？','Vâng, em hỏi chút là chủ yếu là quy định chỗ ở với các khoản phí phải đóng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_03','V218','Tiền sảnh',3,'对的，还有作息时间、宿舍安全的相关要求呢。','duì de， hái yǒu zuò xī shí jiān、 sù shè ān quán de xiāng guān yāo qiú ne。','Đúng vậy, còn có cả giờ giấc sinh hoạt và yêu cầu về an toàn ký túc xá nữa nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_04','V218','Nguyễn Minh',4,'我看完了，没有疑问，可以签字了吗？','wǒ kàn wán le， méi yǒu yí wèn， kě yǐ qiān zì le ma？','Em xem xong rồi, không có thắc mắc gì, giờ ký được chưa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_05','V218','Tiền sảnh',5,'可以的，在这里签上你的中文或英文姓名就行。','kě yǐ de， zài zhè lǐ qiān shàng nǐ de zhōng wén huò yīng wén xìng míng jiù xíng。','Được rồi, em ký tên bằng tiếng Trung hoặc tiếng Anh ở đây là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_06','V218','Nguyễn Minh',6,'好的，我签好了，交给您。','hǎo de， wǒ qiān hǎo le， jiāo gěi nín。','Vâng, em ký xong rồi, gửi lại cho cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L218_07','V218','Tiền sảnh',7,'手续办完，祝你入住愉快！','shǒu xù bàn wán， zhù nǐ rù zhù yú kuài！','Xong thủ tục rồi, chúc em ở đây vui vẻ nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT219','S7','Hỏi WiFi, phòng giặt, giờ đóng cửa ký túc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V219','SIT219','P1','suon_se','ban_chinh_thuc','Hỏi các thông tin cần thiết ngay khi mới nhận phòng',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_01','V219','Nguyễn Minh',1,'老师您好，我想咨询几个宿舍的相关问题可以吗？','lǎo shī nín hǎo， wǒ xiǎng zī xún jǐ gè sù shè de xiāng guān wèn tí kě yǐ ma？','Chào cô ạ, em muốn hỏi vài vấn đề liên quan đến ký túc xá được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_02','V219','Tiền sảnh',2,'当然可以，你尽管问哈。','dāng rán kě yǐ， nǐ jǐn guǎn wèn hā。','Được chứ, em cứ hỏi thoải mái đi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_03','V219','Nguyễn Minh',3,'请问宿舍WiFi密码是多少？洗衣房在哪个位置啊？','qǐng wèn sù shè WiFi mì mǎ shì duō shǎo？ xǐ yī fáng zài nǎ ge wèi zhì a？','Cho em hỏi mật khẩu WiFi ký túc là gì ạ? Với phòng giặt đồ ở chỗ nào vậy ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_04','V219','Tiền sảnh',4,'WiFi密码贴在房门背后，洗衣房在二楼楼梯口呢。','WiFi mì mǎ tiē zài fáng mén bèi hòu， xǐ yī fáng zài èr lóu lóu tī kǒu ne。','Mật khẩu WiFi dán ở mặt sau cửa phòng, còn phòng giặt thì ở đầu cầu thang tầng hai nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_05','V219','Nguyễn Minh',5,'那宿舍门禁的开关时间是几点呀？','nà sù shè mén jìn de kāi guān shí jiān shì jǐ diǎn ya？','Vậy cổng ký túc mở với đóng cửa vào giờ nào vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_06','V219','Tiền sảnh',6,'早上六点开门，晚上十一点关门，记得按时回寝哦。','zǎo shàng liù diǎn kāi mén， wǎn shàng shí yì diǎn guān mén， jì de àn shí huí qǐn ó。','Sáng sáu giờ mở cửa, tối mười một giờ đóng cửa, nhớ về đúng giờ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L219_07','V219','Nguyễn Minh',7,'好的，我都记住了，谢谢您！','hǎo de， wǒ dōu jì zhù le， xiè xiè nín！','Vâng, em nhớ hết rồi, cảm ơn cô nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT220','S7','Báo hỏng đèn phòng','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V220','SIT220','P1','that_bai_nhe','tuy_y','Đèn phòng hỏng, phải chờ thợ sửa ngày hôm sau',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_01','V220','Nguyễn Minh',1,'阿姨您好，我是408宿舍的同学，房间的顶灯不亮了。','ā yí nín hǎo， wǒ shì 408 sù shè de tóng xué， fáng jiān de dǐng dēng bù liàng le。','Chào cô ạ, em là sinh viên phòng 408, đèn trần trong phòng em không sáng nữa rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_02','V220','Quản lý',2,'是完全不亮，还是一闪一闪的呀？','shì wán quán bù liàng， hái shì yī shǎn yī shǎn de ya？','Là tắt hẳn luôn hay là chớp chớp vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_03','V220','Nguyễn Minh',3,'完全打不开，应该是坏掉了呢。','wán quán dǎ bù kāi， yīng gāi shì huài diào le ne。','Tắt hẳn luôn, chắc là hỏng rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_04','V220','Quản lý',4,'好的，我帮你登记报修，维修师傅明天上午过来修哈。','hǎo de， wǒ bāng nǐ dēng jì bào xiū， wéi xiū shī fù míng tiān shàng wǔ guò lái xiū hā。','Được rồi, cô ghi vào sổ báo sửa cho em, mai sáng thợ sẽ qua sửa nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_05','V220','Nguyễn Minh',5,'好的，今晚只能先开台灯了，麻烦阿姨啦！','hǎo de， jīn wǎn zhǐ néng xiān kāi tái dēng le， má fán ā yí la！','Dạ vâng, tối nay em đành bật đèn bàn tạm vậy, làm phiền cô quá!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L220_06','V220','Quản lý',6,'没事的，小事而已，明天肯定修好。','méi shì de， xiǎo shì ér yǐ， míng tiān kěn dìng xiū hǎo。','Không sao đâu, chuyện nhỏ thôi mà, mai chắc chắn sửa xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT221','S6','Mở tài khoản ngân hàng, lấy số','Lấy số thứ tự và điền đơn mở tài khoản','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V221','SIT221','P1','suon_se','chinh_thuc','Lấy số thứ tự và điền đơn mở tài khoản',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_01','V221','Nguyễn Minh',1,'您好，我想办理银行卡开户业务，请问怎么操作？','nín hǎo， wǒ xiǎng bàn lǐ yín háng kǎ kāi hù yè wù， qǐng wèn zěn me cāo zuò？','Chào chị, em muốn mở tài khoản thẻ ngân hàng, cho em hỏi làm thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_02','V221','Quản lý sảnh',2,'您好，先在取号机取个排队号，再填写这份开户申请表哦。','nín hǎo， xiān zài qǔ hào jī qǔ gè pái duì hào， zài tián xiě zhè fèn kāi hù shēn qǐng biǎo ó。','Chào em, em lấy số thứ tự ở máy lấy số trước, rồi điền vào tờ đơn đăng ký mở tài khoản này nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_03','V221','Nguyễn Minh',3,'好的，表格上的信息我都如实填写就可以吧？','hǎo de， biǎo gé shàng de xìn xī wǒ dōu rú shí tián xiě jiù kě yǐ ba？','Vâng, thông tin trên đơn em chỉ cần điền đúng sự thật là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_04','V221','Quản lý sảnh',4,'对的，姓名、证件信息、住址全部填完整就行。','duì de， xìng míng、 zhèng jiàn xìn xī、 zhù zhǐ quán bù tián wán zhěng jiù xíng。','Đúng vậy, họ tên, thông tin giấy tờ, địa chỉ điền đầy đủ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_05','V221','Nguyễn Minh',5,'表格填好了，号也取到了，接下来等待叫号吗？','biǎo gé tián hǎo le， hào yě qǔ dào le， jiē xià lái děng dài jiào hào ma？','Em điền xong rồi, cũng lấy số rồi, tiếp theo là chờ gọi số ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_06','V221','Quản lý sảnh',6,'是的，轮到你的时候直接去柜台办理即可。','shì de， lún dào nǐ de shí hòu zhí jiē qù guì tái bàn lǐ jí kě。','Đúng rồi, đến lượt em thì ra quầy làm thủ tục là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L221_07','V221','Nguyễn Minh',7,'好的，谢谢您的指导！','hǎo de， xiè xiè nín de zhǐ dǎo！','Vâng, cảm ơn chị đã hướng dẫn ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT222','S6','Xuất trình giấy tờ mở thẻ ngân hàng','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V222','SIT222','P1','twist','chinh_thuc','Nhân viên yêu cầu giấy xác nhận đang học, bản in đen trắng vẫn được chấp nhận',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_01','V222','Nhân viên',1,'您好，请问办理什么业务？','nín hǎo， qǐng wèn bàn lǐ shén me yè wù？','Chào anh, anh cần làm dịch vụ gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_02','V222','Nguyễn Minh',2,'您好，我是留学生，想办理储蓄卡开户。','nín hǎo， wǒ shì liú xué shēng， xiǎng bàn lǐ chǔ xù kǎ kāi hù。','Chào anh, tôi là lưu học sinh, muốn mở thẻ tiết kiệm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_03','V222','Nhân viên',3,'麻烦出示你的护照、签证和学校在读证明哦。','má fán chū shì nǐ de hù zhào、 qiān zhèng hé xué xiào zài dú zhèng míng ó。','Phiền anh xuất trình hộ chiếu, visa và giấy xác nhận đang học ở trường giúp tôi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_04','V222','Nguyễn Minh',4,'证件都在这里，在读证明我打印的黑白版可以吗？','zhèng jiàn dōu zài zhè lǐ， zài dú zhèng míng wǒ dǎ yìn de hēi bái bǎn kě yǐ ma？','Giấy tờ đều ở đây cả, giấy xác nhận đang học em in bản đen trắng có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_05','V222','Nhân viên',5,'可以的，黑白有效，我帮你录入系统信息。','kě yǐ de， hēi bái yǒu xiào， wǒ bāng nǐ lù rù xì tǒng xìn xī。','Được, bản đen trắng vẫn có giá trị, tôi nhập thông tin vào hệ thống cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_06','V222','Nguyễn Minh',6,'好的，辛苦您了！大概多久能办好呀？','hǎo de， xīn kǔ nín le！ dà gài duō jiǔ néng bàn hǎo ya？','Vâng, phiền anh rồi ạ! Cho em hỏi khoảng bao lâu thì xong ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L222_07','V222','Nhân viên',7,'很快的，三分钟就能完成开卡流程。','hěn kuài de， sān fēn zhōng jiù néng wán chéng kāi kǎ liú chéng。','Nhanh thôi, ba phút là xong quy trình mở thẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT223','S6','Kích hoạt thẻ ngân hàng mới','Đổi mật khẩu ban đầu để kích hoạt thẻ','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V223','SIT223','P1','suon_se','chinh_thuc','Đổi mật khẩu ban đầu để kích hoạt thẻ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_01','V223','Nhân viên',1,'银行卡已经办好了，需要现场激活修改初始密码哦。','yín háng kǎ yǐ jīng bàn hǎo le， xū yào xiàn chǎng jī huó xiū gǎi chū shǐ mì mǎ ó。','Thẻ ngân hàng làm xong rồi, giờ cần kích hoạt tại chỗ và đổi mật khẩu ban đầu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_02','V223','Nguyễn Minh',2,'好的，请问我怎么操作呢？我不太会用机器。','hǎo de， qǐng wèn wǒ zěn me cāo zuò ne？ wǒ bù tài huì yòng jī qì。','Vâng, cho em hỏi thao tác thế nào ạ? Em không rành dùng máy lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_03','V223','Nhân viên',3,'没关系，我一步步教你，先输入初始密码，再设置新密码。','méi guān xì， wǒ yí bù bù jiāo nǐ， xiān shū rù chū shǐ mì mǎ， zài shè zhì xīn mì mǎ。','Không sao, tôi hướng dẫn từng bước cho anh, đầu tiên nhập mật khẩu ban đầu, sau đó đặt mật khẩu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_04','V223','Nguyễn Minh',4,'好，我设置好了，这样就激活成功了吧？','hǎo， wǒ shè zhì hǎo le， zhè yàng jiù jī huó chéng gōng le ba？','Vâng, em đặt xong rồi, vậy là kích hoạt thành công rồi đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_05','V223','Nhân viên',5,'对的，现在可以正常存取款、扫码支付了。','duì de， xiàn zài kě yǐ zhèng cháng cún qǔ kuǎn、 sǎo mǎ zhī fù le。','Đúng rồi, giờ anh có thể gửi tiền, rút tiền, quét mã thanh toán bình thường rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L223_06','V223','Nguyễn Minh',6,'太好了，非常感谢您的帮助！','tài hǎo le， fēi cháng gǎn xiè nín de bāng zhù！','Tuyệt quá, cảm ơn chị nhiều lắm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT224','S5','Đăng ký thanh toán điện tử, xác thực danh tính','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V224','SIT224','P1','suon_se','tuy_y','Bạn cùng lớp hướng dẫn đăng ký ví điện tử bằng hộ chiếu',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_01','V224','Nguyễn Minh',1,'小杨，我想注册微信支付，还要实名认证对吧？','xiǎo yáng， wǒ xiǎng zhù cè wēi xìn zhī fù， hái yào shí míng rèn zhèng duì ba？','Tiểu Dương ơi, tớ muốn đăng ký WeChat Pay, còn phải xác thực danh tính nữa đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_02','V224','Bạn (Tiểu Dương)',2,'对呀，不认证没法扫码付钱、转账的。','duì ya， bù rèn zhèng méi fǎ sǎo mǎ fù qián、 zhuǎn zhàng de。','Đúng rồi đó, không xác thực thì không quét mã trả tiền hay chuyển khoản được đâu.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_03','V224','Nguyễn Minh',3,'那留学生用护照也能认证吗？我没有身份证呢。','nà liú xué shēng yòng hù zhào yě néng rèn zhèng ma？ wǒ méi yǒu shēn fèn zhèng ne。','Vậy lưu học sinh dùng hộ chiếu xác thực được không? Tớ đâu có chứng minh thư.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_04','V224','Bạn (Tiểu Dương)',4,'可以的！直接选择护照认证，按提示上传照片就行啦。','kě yǐ de！ zhí jiē xuǎn zé hù zhào rèn zhèng， àn tí shì shàng chuán zhào piān jiù xíng la。','Được chứ! Cứ chọn xác thực bằng hộ chiếu, làm theo hướng dẫn tải ảnh lên là xong thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_05','V224','Nguyễn Minh',5,'原来这么简单，我马上试试！','yuán lái zhè me jiǎn dān， wǒ mǎ shàng shì shì！','Hóa ra đơn giản vậy thôi à, để tớ thử luôn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L224_06','V224','Bạn (Tiểu Dương)',6,'弄不懂随时喊我，我教你哈。','nòng bù dǒng suí shí hǎn wǒ， wǒ jiāo nǐ hā。','Không hiểu gì thì cứ gọi tớ, tớ chỉ cho.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT225','S11','Thanh toán quét mã ở cửa hàng tiện lợi','Thanh toán nhanh bằng ví điện tử khi mua đồ','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V225','SIT225','P1','suon_se','tuy_y','Thanh toán nhanh bằng ví điện tử khi mua đồ',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_01','V225','Nhân viên',1,'一共二十五元，你扫码支付就可以啦。','yī gòng èr shí wǔ yuán， nǐ sǎo mǎ zhī fù jiù kě yǐ la。','Tổng cộng hai mươi lăm tệ, anh quét mã thanh toán là được nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_02','V225','Nguyễn Minh',2,'好的，我打开微信二维码，您扫我吧？','hǎo de， wǒ dǎ kāi wēi xìn èr wéi mǎ， nín sǎo wǒ ba？','Vâng, em mở mã QR WeChat đây, chị quét cho em nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_03','V225','Nhân viên',3,'可以的，或者你扫收银台的码也行哦。','kě yǐ de， huò zhě nǐ sǎo shōu yín tái de mǎ yě xíng ó。','Được đó, hoặc anh quét mã ở quầy thu ngân cũng được nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_04','V225','Nguyễn Minh',4,'我扫好了，支付成功了，您看一下！','wǒ sǎo hǎo le， zhī fù chéng gōng le， nín kàn yī xià！','Em quét xong rồi, thanh toán thành công rồi, chị xem lại giúp em nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_05','V225','Nhân viên',5,'收到啦，没问题！东西拿好，慢走哈。','shōu dào la， méi wèn tí！ dōng xī ná hǎo， màn zǒu hā。','Nhận được rồi nè, không vấn đề gì! Anh cầm đồ cẩn thận, đi cẩn thận nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L225_06','V225','Nguyễn Minh',6,'谢谢！','xiè xiè！','Cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT226','S8','Báo danh văn phòng sinh viên quốc tế','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V226','SIT226','P1','suon_se','ban_chinh_thuc','Nộp hồ sơ báo danh, hoàn tất đăng ký sinh viên mới',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_01','V226','Nguyễn Minh',1,'老师您好，我是新生阮明，今天来国际学生办公室报到。','lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， jīn tiān lái guó jì xué shēng bàn gōng shì bào dào。','Chào cô/thầy, em là sinh viên mới Nguyễn Minh, hôm nay em đến văn phòng sinh viên quốc tế để báo danh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_02','V226','Cán bộ',2,'你好！麻烦提交一下你的护照、签证和录取通知书哦。','nǐ hǎo！ má fán tí jiāo yī xià nǐ de hù zhào、 qiān zhèng hé lù qǔ tōng zhī shū ó。','Chào em! Phiền em nộp giúp hộ chiếu, visa và giấy báo nhập học nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_03','V226','Nguyễn Minh',3,'好的，这是我的全部材料，您查收一下。','hǎo de， zhè shì wǒ de quán bù cái liào， nín chá shōu yī xià。','Dạ vâng, đây là toàn bộ giấy tờ của em, cô/thầy kiểm tra giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_04','V226','Cán bộ',4,'材料齐全无误，这边帮你完成新生注册啦。','cái liào qí quán wú wù， zhè biān bāng nǐ wán chéng xīn shēng zhù cè la。','Giấy tờ đầy đủ và chính xác rồi, để cô/thầy hoàn tất đăng ký sinh viên mới cho em nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_05','V226','Nguyễn Minh',5,'请问接下来还有其他报到流程吗？','qǐng wèn jiē xià lái hái yǒu qí tā bào dào liú chéng ma？','Cho em hỏi sau đó còn thủ tục báo danh nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_06','V226','Cán bộ',6,'基本完成了，后续选课、体检通知会统一发群里呢。','jī běn wán chéng le， hòu xù xuǎn kè、 tǐ jiǎn tōng zhī huì tǒng yī fā qún lǐ ne。','Cơ bản là xong rồi, sau này thông báo chọn môn học và khám sức khỏe sẽ được đăng chung trong nhóm nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L226_07','V226','Nguyễn Minh',7,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn cô/thầy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT227','S8','Thiếu giấy tờ, xin nộp bổ sung','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V227','SIT227','P1','twist','ban_chinh_thuc','Quên mang giấy chứng nhận tiêm vaccine, được cho nộp bổ sung','新生报到材料缺失，多数学校允许限期补交，态度诚恳致歉即可，无需过度紧张；线上截图、电子版打印件大多不具备归档效力，必须纸质复印件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_01','V227','老师',1,'同学你先坐，我们核对一下新生报到需要提交的全套材料。','tóng xué nǐ xiān zuò， wǒ men hé duì yī xià xīn shēng bào dào xū yào tí jiāo de quán tào cái liào。','Em ngồi xuống đi, chúng ta kiểm tra lại toàn bộ giấy tờ cần nộp khi báo danh sinh viên mới nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_02','V227','阮明',2,'好的老师，我把手里的文件都拿出来给您核对。','hǎo de lǎo shī， wǒ bǎ shǒu lǐ de wén jiàn dōu ná chū lái gěi nín hé duì。','Dạ vâng thưa cô/thầy, em lấy hết giấy tờ trong tay ra để cô/thầy kiểm tra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_03','V227','老师',3,'毕业证复印件、签证页、体检表都齐了，还差一份疫苗接种证明，你带过来了吗？','bì yè zhèng fù yìn jiàn、 qiān zhèng yè、 tǐ jiǎn biǎo dōu qí le， hái chà yī fèn yì miáo jiē zhǒng zhèng míng， nǐ dài guò lái le ma？','Bản sao bằng tốt nghiệp, trang visa, phiếu khám sức khỏe đều đủ rồi, còn thiếu giấy chứng nhận tiêm vaccine, em có mang theo không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_04','V227','阮明',4,'不好意思老师，出门收拾行李的时候漏掉这份材料，我完全忘记带了，非常抱歉。','bù hǎo yì sī lǎo shī， chū mén shōu shí xíng lǐ de shí hòu lòu diào zhè fèn cái liào， wǒ wán quán wàng jì dài le， fēi cháng bào qiàn。','Em xin lỗi thầy/cô, lúc thu dọn hành lý em quên mất giấy này, em hoàn toàn quên mang theo, thật sự xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_05','V227','老师',5,'没事的，不用紧张，很多新生都会出现材料遗漏的情况。','méi shì de， bù yòng jǐn zhāng， hěn duō xīn shēng dōu huì chū xiàn cái liào yí lòu de qíng kuàng。','Không sao đâu, em đừng lo lắng, nhiều sinh viên mới cũng gặp tình trạng thiếu giấy tờ như vậy mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_06','V227','阮明',6,'我心里特别着急，怕耽误今天的新生登记流程，影响后续选课住宿。','wǒ xīn lǐ tè bié zháo jí， pà dān wù jīn tiān de xīn shēng dēng jì liú chéng， yǐng xiǎng hòu xù xuǎn kè zhù sù。','Em thấy rất lo trong lòng, sợ làm chậm trễ thủ tục đăng ký sinh viên mới hôm nay, ảnh hưởng đến việc chọn môn và chỗ ở sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_07','V227','老师',7,'我先跟你说明学校的规定，所有材料必须完整归档，不能长期缺件。','wǒ xiān gēn nǐ shuō míng xué xiào de guī dìng， suǒ yǒu cái liào bì xū wán zhěng guī dàng， bù néng cháng qī quē jiàn。','Cô/thầy nói trước với em quy định của trường là tất cả giấy tờ phải nộp đầy đủ, không được thiếu lâu dài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_08','V227','阮明',8,'那请问我明天补交可以吗？明天补交完整不会影响我的新生报到手续吧？','nà qǐng wèn wǒ míng tiān bǔ jiāo kě yǐ ma？ míng tiān bǔ jiāo wán zhěng bú huì yǐng xiǎng wǒ de xīn shēng bào dào shǒu xù ba？','Vậy cho em hỏi ngày mai em nộp bổ sung có được không ạ? Nộp bổ sung đầy đủ vào ngày mai thì không ảnh hưởng đến thủ tục báo danh của em chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_09','V227','老师',9,'正常截止时间是今天下午五点，严格来说逾期不予受理，不过可以给你特殊放宽一天。','zhèng cháng jié zhǐ shí jiān shì jīn tiān xià wǔ wǔ diǎn， yán gé lái shuō yú qī bù yǔ shòu lǐ， bù guò kě yǐ gěi nǐ tè shū fàng kuān yī tiān。','Thời hạn bình thường là năm giờ chiều nay, nói đúng ra thì quá hạn sẽ không được tiếp nhận, nhưng cô/thầy có thể linh động cho em thêm một ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_10','V227','阮明',10,'太感谢老师愿意通融，我明天一早就回家找出证明，复印完整送过来。','tài gǎn xiè lǎo shī yuàn yì tōng róng， wǒ míng tiān yī zǎo jiù huí jiā zhǎo chū zhèng míng， fù yìn wán zhěng sòng guò lái。','Em cảm ơn thầy/cô đã thông cảm nhiều lắm ạ, sáng sớm mai em sẽ về nhà tìm giấy chứng nhận, photo đầy đủ rồi mang đến ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_11','V227','老师',11,'记住一定要带纸质原件复印件，照片截图打印出来是不被认可的。','jì zhù yí dìng yào dài zhǐ zhì yuán jiàn fù yìn jiàn， zhào piān jié tú dǎ yìn chū lái shì bù bèi rèn kě de。','Em nhớ nhé, nhất định phải mang bản gốc giấy và bản photo, ảnh chụp màn hình in ra thì không được chấp nhận đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_12','V227','阮明',12,'我记下这条要求了，明天一定准备规范的纸质文件。','wǒ jì xià zhè tiáo yāo qiú le， míng tiān yí dìng zhǔn bèi guī fàn de zhǐ zhì wén jiàn。','Em ghi nhớ yêu cầu này rồi ạ, ngày mai nhất định em sẽ chuẩn bị giấy tờ đúng chuẩn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_13','V227','老师',13,'行，我先把你现有材料临时存档，等你补齐再统一录入系统。','xíng， wǒ xiān bǎ nǐ xiàn yǒu cái liào lín shí cún dàng， děng nǐ bǔ qí zài tǒng yī lù rù xì tǒng。','Được rồi, trước mắt cô/thầy sẽ lưu tạm hồ sơ hiện có của em, đợi em bổ sung đầy đủ rồi nhập vào hệ thống một thể.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L227_14','V227','阮明',14,'给老师增添额外工作量实在不好意思，我明天准时送来！','gěi lǎo shī zēng tiān é wài gōng zuò liàng shí zài bù hǎo yì sī， wǒ míng tiān zhǔn shí sòng lái！','Em thật sự áy náy vì làm phiền thầy/cô thêm việc, ngày mai em sẽ mang đến đúng giờ ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT228','S9','Chọn môn, lớp đã đầy phải đổi lớp','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V228','SIT228','P1','that_bai_nhe','ban_chinh_thuc','Lớp mong muốn đã đầy, phải chuyển sang lớp giờ khác','Lớp học đông theo nguyên tắc đăng ký trước được trước; lớp đầy thì chỉ có thể đổi sang lớp/giờ khác, không thể xin thêm suất.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_01','V228','Nguyễn Minh',1,'老师您好，我想选的汉语课已经显示满员了。','lǎo shī nín hǎo， wǒ xiǎng xuǎn de hàn yǔ kè yǐ jīng xiǎn shì mǎn yuán le。','Chào cô/thầy, môn tiếng Hán em muốn chọn đã báo đầy lớp rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_02','V228','Giáo vụ',2,'是的，这个热门班级名额已经抢完了呢。','shì de， zhè ge rè mén bān jí míng é yǐ jīng qiǎng wán le ne。','Đúng vậy, lớp hot này hết chỗ nhanh lắm đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_03','V228','Nguyễn Minh',3,'那请问我能不能换到其他时间段的班级呀？','nà qǐng wèn wǒ néng bù néng huàn dào qí tā shí jiān duàn de bān jí ya？','Vậy cho em hỏi em có thể đổi sang lớp học vào khung giờ khác không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_04','V228','Giáo vụ',4,'可以的，还有周三下午的班级有空位，内容是一样的。','kě yǐ de， hái yǒu zhōu sān xià wǔ de bān jí yǒu kòng wèi， nèi róng shì yī yàng de。','Được chứ, còn lớp chiều thứ Tư vẫn còn chỗ trống, nội dung học hoàn toàn giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_05','V228','Nguyễn Minh',5,'那就太好了！我直接改选这个班级就可以吧？','nà jiù tài hǎo le！ wǒ zhí jiē gǎi xuǎn zhè ge bān jí jiù kě yǐ ba？','Vậy thì tốt quá ạ! Em cứ trực tiếp đổi sang lớp này là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L228_06','V228','Giáo vụ',6,'对的，系统直接操作就行，不用额外申请。','duì de， xì tǒng zhí jiē cāo zuò jiù xíng， bù yòng é wài shēn qǐng。','Đúng rồi, em thao tác ngay trên hệ thống là được, không cần xin thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT229','S9','Gặp cố vấn học tập lần đầu','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V229','SIT229','P1','suon_se','ban_chinh_thuc','Tự giới thiệu và hỏi hướng chọn môn cho chuyên ngành','Giảng viên hướng dẫn học tập sẵn sàng tư vấn chọn môn; sinh viên nên chủ động hỏi ngay từ buổi gặp đầu tiên.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_01','V229','Nguyễn Minh',1,'张老师您好，我是新生阮明，来自越南，很高兴成为您的学生。','zhāng lǎo shī nín hǎo， wǒ shì xīn shēng ruǎn míng， lái zì yuè nán， hěn gāo xìng chéng wéi nín de xué shēng。','Chào cô Trương, em là sinh viên mới Nguyễn Minh, đến từ Việt Nam, em rất vui được làm học trò của cô ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_02','V229','Cố vấn',2,'你好！欢迎你来本校就读，适应这边的生活了吗？','nǐ hǎo！ huān yíng nǐ lái běn xiào jiù dú， shì yìng zhè biān de shēng huó le ma？','Chào em! Chào mừng em đến học tại trường mình, em đã quen với cuộc sống ở đây chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_03','V229','Nguyễn Minh',3,'慢慢适应啦，我想咨询一下，本专业选课有什么侧重点呢？','màn màn shì yìng la， wǒ xiǎng zī xún yī xià， běn zhuān yè xuǎn kè yǒu shén me cè zhòng diǎn ne？','Em đang dần quen ạ, em muốn hỏi cô một chút, chọn môn học của ngành mình thì nên chú trọng vào điểm nào ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_04','V229','Cố vấn',4,'优先选专业基础课，选修课可以选贴合国际贸易的课程哦。','yōu xiān xuǎn zhuān yè jī chǔ kè， xuǎn xiū kè kě yǐ xuǎn tiē hé guó jì mào yì de kè chéng ó。','Ưu tiên chọn các môn cơ sở chuyên ngành trước, môn tự chọn thì em nên chọn những môn liên quan đến thương mại quốc tế nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_05','V229','Nguyễn Minh',5,'好的，那大一需要多选公共课吗？','hǎo de， nà dà yī xū yào duō xuǎn gōng gòng kè ma？','Dạ vâng, vậy năm nhất có cần chọn nhiều môn đại cương không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_06','V229','Cố vấn',6,'适当选择即可，不用选课太多，避免压力过大哈。','shì dàng xuǎn zé jí kě， bù yòng xuǎn kè tài duō， bì miǎn yā lì guò dà hā。','Chọn vừa phải thôi, không cần chọn quá nhiều, tránh áp lực quá lớn nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L229_07','V229','Nguyễn Minh',7,'我明白了，谢谢老师指导！','wǒ míng bái le， xiè xiè lǎo shī zhǐ dǎo！','Em hiểu rồi ạ, em cảm ơn cô đã hướng dẫn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT230','S9','Chụp ảnh làm thẻ sinh viên','Chụp ảnh đơn giản để làm thẻ sinh viên','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V230','SIT230','P1','suon_se','tuy_y','Chụp ảnh đơn giản để làm thẻ sinh viên',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_01','V230','Nhân viên',1,'同学，过来拍学生证照片啦。','tóng xué， guò lái pāi xué shēng zhèng zhào piān la。','Em ơi, qua đây chụp ảnh làm thẻ sinh viên nào.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_02','V230','Nguyễn Minh',2,'好的，请问拍照有什么要求吗？我不太清楚呢。','hǎo de， qǐng wèn pāi zhào yǒu shén me yāo qiú ma？ wǒ bù tài qīng chǔ ne。','Dạ vâng, cho em hỏi chụp ảnh có yêu cầu gì không ạ? Em không rõ lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_03','V230','Nhân viên',3,'很简单，不用戴帽子、墨镜，头发露出额头就行哈。','hěn jiǎn dān， bù yòng dài mào zi、 mò jìng， tóu fà lù chū é tóu jiù xíng hā。','Đơn giản thôi, không đội mũ, không đeo kính râm, để lộ trán ra là được.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_04','V230','Nguyễn Minh',4,'好，我整理一下，这样可以了吧？','hǎo， wǒ zhěng lǐ yī xià， zhè yàng kě yǐ le ba？','Vâng, em chỉnh lại một chút, thế này được chưa ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_05','V230','Nhân viên',5,'可以！保持微笑，看镜头，马上就好。','kě yǐ！ bǎo chí wēi xiào， kàn jìng tóu， mǎ shàng jiù hǎo。','Được rồi! Giữ nụ cười, nhìn vào ống kính, xong ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_06','V230','Nguyễn Minh',6,'拍完就可以直接办理学生证了吗？','pāi wán jiù kě yǐ zhí jiē bàn lǐ xué shēng zhèng le ma？','Chụp xong là có thể làm thẻ sinh viên luôn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L230_07','V230','Nhân viên',7,'对的，照片录入系统，一周后就能拿证啦。','duì de， zhào piān lù rù xì tǒng， yī zhōu hòu jiù néng ná zhèng la。','Đúng vậy, ảnh sẽ được nhập vào hệ thống, một tuần sau là lấy thẻ được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT231','S9','Làm thẻ thư viện, mượn sách đầu tiên','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V231','SIT231','P1','suon_se','ban_chinh_thuc','Đăng ký thẻ mượn sách và mượn một cuốn giáo trình',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_01','V231','Nguyễn Minh',1,'老师您好，我是新生，想办理图书馆借书证。','lǎo shī nín hǎo， wǒ shì xīn shēng， xiǎng bàn lǐ tú shū guǎn jiè shū zhèng。','Chào cô/thầy, em là sinh viên mới, em muốn làm thẻ thư viện ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_02','V231','Thủ thư',2,'好的，出示你的学生证就可以免费办理哦。','hǎo de， chū shì nǐ de xué shēng zhèng jiù kě yǐ miǎn fèi bàn lǐ ó。','Được, em đưa thẻ sinh viên ra là làm miễn phí luôn nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_03','V231','Nguyễn Minh',3,'给您，办好之后一次可以借几本书呀？','gěi nín， bàn hǎo zhī hòu yī cì kě yǐ jiè jǐ běn shū ya？','Dạ đây ạ, làm xong thì mỗi lần em mượn được bao nhiêu cuốn ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_04','V231','Thủ thư',4,'留学生一次可以借十本，借阅期限三十天呢。','liú xué shēng yī cì kě yǐ jiè shí běn， jiè yuè qī xiàn sān shí tiān ne。','Sinh viên quốc tế mỗi lần được mượn mười cuốn, thời hạn mượn là ba mươi ngày nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_05','V231','Nguyễn Minh',5,'那我借这本汉语教材可以吧？','nà wǒ jiè zhè běn hàn yǔ jiào cái kě yǐ ba？','Vậy em mượn cuốn giáo trình tiếng Hán này được không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_06','V231','Thủ thư',6,'没问题，我帮你扫码登记，已经借阅成功啦。','méi wèn tí， wǒ bāng nǐ sǎo mǎ dēng jì， yǐ jīng jiè yuè chéng gōng la。','Không vấn đề gì, để cô/thầy quét mã đăng ký giúp em, mượn thành công rồi đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L231_07','V231','Nguyễn Minh',7,'太感谢您了！','tài gǎn xiè nín le！','Em cảm ơn cô/thầy nhiều ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT232','S9','Đổi mật khẩu email trường','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V232','SIT232','P1','twist','tuy_y','Đăng nhập email trường bị lỗi, hoá ra do sai chữ hoa/thường','Tài khoản hệ thống trường phân biệt chữ hoa/thường trong mật khẩu; cần đổi mật khẩu ban đầu ngay lần đăng nhập đầu.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_01','V232','Nguyễn Minh',1,'宇哥，学校邮箱我登不上，初始密码不对呢。','yǔ gē， xué xiào yóu xiāng wǒ dēng bù shàng， chū shǐ mì mǎ bú duì ne。','Anh Vũ ơi, em đăng nhập không được vào email của trường, mật khẩu ban đầu bị sai rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_02','V232','Trần Vũ',2,'是吗？你是不是输错大小写了呀？','shì ma？ nǐ shì bú shì shū cuò dà xiǎo xiě le ya？','Vậy à? Có phải em gõ sai chữ hoa chữ thường không?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_03','V232','Nguyễn Minh',3,'有可能！我一直没注意大小写区分。','yǒu kě néng！ wǒ yì zhí méi zhù yì dà xiǎo xiě qū fēn。','Có thể lắm! Em cứ không để ý phân biệt chữ hoa chữ thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_04','V232','Trần Vũ',4,'没事，我教你，重新输入区分大小写就能登上啦。','méi shì， wǒ jiāo nǐ， chóng xīn shū rù qū fēn dà xiǎo xiě jiù néng dēng shàng la。','Không sao, anh chỉ cho, gõ lại phân biệt hoa thường là đăng nhập được ngay thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_05','V232','Nguyễn Minh',5,'登上了！接下来怎么修改密码呀？','dēng shàng le！ jiē xià lái zěn me xiū gǎi mì mǎ ya？','Đăng nhập được rồi! Tiếp theo đổi mật khẩu như thế nào vậy anh?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_06','V232','Trần Vũ',6,'在个人中心设置新密码，记得设置复杂一点哦。','zài gè rén zhōng xīn shè zhì xīn mì mǎ， jì de shè zhì fù zá yì diǎn ó。','Vào trang cá nhân đặt mật khẩu mới, nhớ đặt phức tạp một chút nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L232_07','V232','Nguyễn Minh',7,'好嘞，我马上改，太谢谢你啦！','hǎo lei， wǒ mǎ shàng gǎi， tài xiè xiè nǐ la！','Dạ được, em đổi ngay đây, cảm ơn anh nhiều lắm!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT233','S9','Nộp bài trên LMS gặp lỗi hệ thống','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V233','SIT233','P1','that_bai_nhe','ban_chinh_thuc','Hệ thống bị lag, nhà trường tự động lùi hạn nộp','Sự cố kỹ thuật trên hệ thống học tập thường được nhà trường tự động gia hạn, không cần làm đơn xin riêng.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_01','V233','Nguyễn Minh',1,'助教您好，我在教学平台提交作业，一直提交失败呢。','zhù jiào nín hǎo， wǒ zài jiào xué píng tái tí jiāo zuò yè， yì zhí tí jiāo shī bài ne。','Chào trợ giảng, em nộp bài trên hệ thống học tập mà cứ nộp không được ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_02','V233','Trợ giảng',2,'是文件上传不了，还是页面卡顿呀？','shì wén jiàn shàng chuán bù liǎo， hái shì yè miàn kǎ dùn ya？','Là file không tải lên được, hay là trang bị đứng vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_03','V233','Nguyễn Minh',3,'页面一直加载，点提交没有任何反应。','yè miàn yì zhí jiā zài， diǎn tí jiāo méi yǒu rèn hé fǎn yìng。','Trang cứ load mãi, bấm nộp bài không có phản hồi gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_04','V233','Trợ giảng',4,'应该是平台晚间系统卡顿，今天很多同学都遇到了。','yīng gāi shì píng tái wǎn jiān xì tǒng kǎ dùn， jīn tiān hěn duō tóng xué dōu yù dào le。','Chắc là do hệ thống bị lag vào buổi tối, hôm nay rất nhiều bạn cũng gặp phải tình trạng này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_05','V233','Nguyễn Minh',5,'那我的作业会不会逾期扣分啊？','nà wǒ de zuò yè huì bú huì yú qī kòu fēn a？','Vậy bài của em có bị trừ điểm vì nộp trễ không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_06','V233','Trợ giảng',6,'不会的，系统问题统一延后提交，明天早上再交就行哈。','bú huì de， xì tǒng wèn tí tǒng yī yán hòu tí jiāo， míng tiān zǎo shàng zài jiāo jiù xíng hā。','Không đâu, lỗi hệ thống thì sẽ gia hạn nộp bài chung cho cả lớp, sáng mai nộp lại là được nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L233_07','V233','Nguyễn Minh',7,'太好了，谢谢您告诉我！','tài hǎo le， xiè xiè nín gào sù wǒ！','Tuyệt quá, em cảm ơn trợ giảng đã báo cho em biết!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT234','S10','Hỏi phạm vi bảo hiểm y tế sinh viên','Hỏi rõ phạm vi được và không được bảo hiểm chi trả','C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V234','SIT234','P1','suon_se','ban_chinh_thuc','Hỏi rõ phạm vi được và không được bảo hiểm chi trả',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_01','V234','Nguyễn Minh',1,'老师您好，我想咨询一下留学生医保的报销范围呢。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià liú xué shēng yī bǎo de bào xiāo fàn wéi ne。','Chào thầy/cô, em muốn hỏi về phạm vi thanh toán bảo hiểm y tế cho lưu học sinh ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_02','V234','Cán bộ',2,'没问题，学校医保主要报销公立医院的门诊和住院费用哦。','méi wèn tí， xué xiào yī bǎo zhǔ yào bào xiāo gōng lì yī yuàn de mén zhěn hé zhù yuàn fèi yòng ó。','Không vấn đề gì, bảo hiểm y tế của trường chủ yếu chi trả cho khám ngoại trú và nội trú tại bệnh viện công đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_03','V234','Nguyễn Minh',3,'那感冒、肠胃炎这类普通小病也能报销吧？','nà gǎn mào、 cháng wèi yán zhè lèi pǔ tōng xiǎo bìng yě néng bào xiāo ba？','Vậy những bệnh thông thường như cảm cúm, viêm dạ dày ruột cũng được chi trả chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_04','V234','Cán bộ',4,'可以的，常规疾病都在报销范围内，意外受伤也能理赔。','kě yǐ de， cháng guī jí bìng dōu zài bào xiāo fàn wéi nèi， yì wài shòu shāng yě néng lǐ péi。','Được chứ, các bệnh thông thường đều nằm trong phạm vi chi trả, tai nạn thương tích cũng được bồi thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_05','V234','Nguyễn Minh',5,'请问有不能报销的项目吗？','qǐng wèn yǒu bù néng bào xiāo de xiàng mù ma？','Cho em hỏi có những khoản nào không được chi trả không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_06','V234','Cán bộ',6,'私立医院、美容整形、牙科美白这些是不报销的哈。','sī lì yī yuàn、 měi róng zhěng xíng、 yá kē měi bái zhè xiē shì bù bào xiāo de hā。','Bệnh viện tư, thẩm mỹ, làm trắng răng thì không được chi trả nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L234_07','V234','Nguyễn Minh',7,'我清楚了，谢谢老师详细讲解！','wǒ qīng chǔ le， xiè xiè lǎo shī xiáng xì jiǎng jiě！','Em hiểu rồi ạ, cảm ơn thầy/cô đã giải thích cặn kẽ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT235','S10','Khám sức khỏe nhập học','Lấy số và điền thông tin cá nhân trước khi khám','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V235','SIT235','P1','suon_se','ban_chinh_thuc','Lấy số và điền thông tin cá nhân trước khi khám','Khám sức khỏe đầu năm là yêu cầu bắt buộc với mọi sinh viên, không riêng sinh viên quốc tế; thông tin sẽ lưu vào hồ sơ sinh viên.') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_01','V235','Nguyễn Minh',1,'您好，我是新生，过来做入学体检，请问怎么办理呀？','nín hǎo， wǒ shì xīn shēng， guò lái zuò rù xué tǐ jiǎn， qǐng wèn zěn me bàn lǐ ya？','Chào anh/chị, em là sinh viên mới, đến khám sức khỏe nhập học, cho em hỏi làm thủ tục thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_02','V235','Nhân viên',2,'先在自助机取个体检号，再填写这份个人信息表哦。','xiān zài zì zhù jī qǔ gè tǐ jiǎn hào， zài tián xiě zhè fèn gè rén xìn xī biǎo ó。','Em lấy số khám ở máy tự phục vụ trước, rồi điền vào tờ thông tin cá nhân này nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_03','V235','Nguyễn Minh',3,'好的，表格里的国籍和证件类型如实填写就可以吧？','hǎo de， biǎo gé lǐ de guó jí hé zhèng jiàn lèi xíng rú shí tián xiě jiù kě yǐ ba？','Vâng ạ, phần quốc tịch và loại giấy tờ trong biểu mẫu cứ điền đúng sự thật là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_04','V235','Nhân viên',4,'对的，信息全部填准确，避免体检单出错呢。','duì de， xìn xī quán bù tián zhǔn què， bì miǎn tǐ jiǎn dān chū cuò ne。','Đúng vậy, thông tin phải điền chính xác hết, tránh để phiếu khám bị sai đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_05','V235','Nguyễn Minh',5,'表格填完、号也取好了，接下来做什么？','biǎo gé tián wán、 hào yě qǔ hǎo le， jiē xià lái zuò shén me？','Em điền xong biểu mẫu và lấy số rồi, tiếp theo làm gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_06','V235','Nhân viên',6,'拿着单据依次做各项检查就行，流程很简单的哈。','ná zhe dān jù yī cì zuò gè xiàng jiǎn chá jiù xíng， liú chéng hěn jiǎn dān de hā。','Em cầm phiếu đi khám lần lượt các mục là được, quy trình đơn giản lắm nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L235_07','V235','Nguyễn Minh',7,'明白了，谢谢您！','míng bái le， xiè xiè nín！','Em hiểu rồi ạ, cảm ơn anh/chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT236','S2','Tắc đường, xin đổi lộ trình vì sắp trễ học','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V236','SIT236','P1','twist','tuy_y','Sắp trễ giờ học, đề nghị tài xế đi đường khác dù xa hơn','早高峰城市主干道普遍拥堵，乘客可礼貌请求司机绕路，司机一般会主动配合，不会额外加价；支路人流密集，司机通常会减速慢行保障安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_01','V236','司机',1,'小伙子，跟你说一下，前方主干道早高峰全线拥堵，车速特别慢哦。','xiǎo huǒ zi， gēn nǐ shuō yī xià， qián fāng zhǔ gàn dào zǎo gāo fēng quán xiàn yōng dǔ， chē sù tè bié màn ó。','Cậu ơi, tôi báo trước, đường chính phía trước đang tắc nghẽn toàn tuyến giờ cao điểm, xe chạy chậm lắm đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_02','V236','阮明',2,'师傅，我上午有专业课，还有十分钟就要上课，再堵下去肯定要迟到了呢！','shī fù， wǒ shàng wǔ yǒu zhuān yè kè， hái yǒu shí fēn zhōng jiù yào shàng kè， zài dǔ xià qù kěn dìng yào chí dào le ne！','Bác tài ơi, sáng nay em có tiết chuyên ngành, chỉ còn mười phút nữa là vào học, cứ tắc thế này chắc chắn trễ mất!','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_03','V236','司机',3,'我打开导航看看路况，主干道三条车道全部堵死，短时间疏通不开。','wǒ dǎ kāi dǎo háng kàn kàn lù kuàng， zhǔ gàn dào sān tiáo chē dào quán bù dǔ sǐ， duǎn shí jiān shū tōng bù kāi。','Để tôi mở bản đồ xem tình hình đường xá, ba làn đường chính đều tắc cứng, khó thông trong thời gian ngắn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_04','V236','阮明',4,'那有没有别的小路可以绕一下，只要能赶在上课前到学校就行呀？','nà yǒu méi yǒu bié de xiǎo lù kě yǐ rào yī xià， zhǐ yào néng gǎn zài shàng kè qián dào xué xiào jiù xíng ya？','Vậy có đường nhỏ nào đi vòng được không ạ, chỉ cần kịp tới trường trước giờ học là được rồi?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_05','V236','司机',5,'倒是有一条居民区小路能绕行，唯一问题是路程会多两公里，稍微远一点。','dǎo shì yǒu yī tiáo jū mín qū xiǎo lù néng rào xíng， wéi yī wèn tí shì lù chéng huì duō liǎng gōng lǐ， shāo wēi yuǎn yì diǎn。','Cũng có một con đường nhỏ trong khu dân cư đi vòng được, chỉ có điều là xa hơn hai cây số, hơi vòng một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_06','V236','阮明',6,'没关系的，多绕一点路完全没问题，只要别耽误上课就好，麻烦您绕路啦！','méi guān xì de， duō rào yì diǎn lù wán quán méi wèn tí， zhǐ yào bié dān wù shàng kè jiù hǎo， má fán nín rào lù la！','Không sao đâu ạ, đi vòng thêm chút cũng được, miễn đừng trễ học là được rồi, phiền bác tài đi vòng giúp em nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_07','V236','司机',7,'绕行小路里面行人、电动车多，车速提不上来，最多只能匀速慢慢开。','rào xíng xiǎo lù lǐ miàn xíng rén、 diàn dòng chē duō， chē sù tí bù shàng lái， zuì duō zhǐ néng yún sù màn màn kāi。','Đường nhỏ đi vòng đó nhiều người đi bộ với xe điện lắm, không chạy nhanh được, chỉ có thể đi đều đều thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_08','V236','阮明',8,'我能理解，安全第一，只要能避开主干道的长堵车我就很满足。','wǒ néng lǐ jiě， ān quán dì yī， zhǐ yào néng bì kāi zhǔ gàn dào de zhǎng dǔ chē wǒ jiù hěn mǎn zú。','Em hiểu mà, an toàn là trên hết, chỉ cần tránh được đoạn tắc dài trên đường chính là em thấy ổn rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_09','V236','司机',9,'没问题，我现在立刻变道下高架，转入旁边的支路绕行。','méi wèn tí， wǒ xiàn zài lì kè biàn dào xià gāo jià， zhuǎn rù páng biān de zhī lù rào xíng。','Được rồi, giờ tôi chuyển làn xuống cầu vượt ngay, rẽ vào đường nhánh bên cạnh để đi vòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_10','V236','阮明',10,'大概还需要几分钟能抵达学校校门，我心里好有个数。','dà gài hái xū yào jǐ fēn zhōng néng dǐ dá xué xiào xiào mén， wǒ xīn lǐ hǎo yǒu gè shù。','Khoảng mấy phút nữa thì tới cổng trường ạ, để em còn biết mà ước lượng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_11','V236','司机',11,'顺利的话七八分钟就能到，比原地干等快二十分钟不止。','shùn lì de huà qī bā fēn zhōng jiù néng dào， bǐ yuán dì gàn děng kuài èr shí fēn zhōng bù zhǐ。','Thuận lợi thì bảy tám phút là tới, nhanh hơn đứng chờ tại chỗ đến gần hai mươi phút đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_12','V236','阮明',12,'太好了，这下不用担心迟到被扣平时分，辛苦您特意绕路！','tài hǎo le， zhè xià bù yòng dān xīn chí dào bèi kòu píng shí fēn， xīn kǔ nín tè yì rào lù！','Tuyệt quá, vậy là khỏi lo bị trễ học mà trừ điểm chuyên cần, cảm ơn bác tài đã cố tình đi vòng giúp em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_13','V236','司机',13,'小事一桩，学生上课要紧，我尽量平稳开车不耽误你。','xiǎo shì yī zhuāng， xué shēng shàng kè yào jǐn， wǒ jǐn liàng píng wěn kāi chē bù dān wù nǐ。','Chuyện nhỏ thôi, sinh viên đi học là quan trọng, tôi sẽ cố lái êm để không làm chậm trễ cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L236_14','V236','阮明',14,'等下车我给您五星好评，真的太感谢您了！','děng xià chē wǒ gěi nín wǔ xīng hǎo píng， zhēn de tài gǎn xiè nín le！','Lát xuống xe em sẽ đánh giá năm sao cho bác, thật sự cảm ơn bác nhiều lắm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT237','S11','Siêu thị không nhận tiền mặt, phải quét mã','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V237','SIT237','P1','twist','tuy_y','Quầy thu ngân từ chối nhận tiền mặt, chỉ nhận thanh toán điện tử',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_01','V237','Thu ngân',1,'一共三十八元，麻烦您结账哦。','yī gòng sān shí bā yuán， má fán nín jié zhàng ó。','Tổng cộng là ba mươi tám tệ, phiền anh/chị thanh toán giúp nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_02','V237','Nguyễn Minh',2,'好的，我给您现金可以吗？我没带手机扫码呢。','hǎo de， wǒ gěi nín xiàn jīn kě yǐ ma？ wǒ méi dài shǒu jī sǎo mǎ ne。','Vâng, em trả tiền mặt được không ạ? Em không mang điện thoại để quét mã.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_03','V237','Thu ngân',3,'不好意思呀，本店现在不收现金，只能微信、支付宝扫码支付。','bù hǎo yì sī ya， běn diàn xiàn zài bù shōu xiàn jīn， zhǐ néng wēi xìn、 zhī fù bǎo sǎo mǎ zhī fù。','Xin lỗi anh/chị nha, cửa hàng hiện giờ không nhận tiền mặt, chỉ nhận quét mã WeChat hoặc Alipay thôi ạ.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_04','V237','Nguyễn Minh',4,'这样啊，那我现在打开手机马上扫码哈。','zhè yàng a， nà wǒ xiàn zài dǎ kāi shǒu jī mǎ shàng sǎo mǎ hā。','Vậy à, để em lấy điện thoại quét mã ngay đây.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_05','V237','Thu ngân',5,'不急，您慢慢操作，支付成功我就出小票。','bù jí， nín màn màn cāo zuò， zhī fù chéng gōng wǒ jiù chū xiǎo piào。','Không vội đâu, anh/chị cứ từ từ thao tác, thanh toán xong em xuất hóa đơn cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L237_06','V237','Nguyễn Minh',6,'付好啦，谢谢您提醒！','fù hǎo la， xiè xiè nín tí xǐng！','Trả xong rồi nè, cảm ơn bạn đã nhắc nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT238','S7','Máy giặt hỏng, đổi sang máy khác','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V238','SIT238','P1','that_bai_nhe','tuy_y','Máy giặt bị kẹt, quản lý hướng dẫn đổi sang máy khác dùng tạm',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_01','V238','Nguyễn Minh',1,'阿姨您好，洗衣房的投币机坏了，投钱没反应呢。','ā yí nín hǎo， xǐ yī fáng de tóu bì jī huài le， tóu qián méi fǎn yìng ne。','Cô ơi, máy giặt bỏ xu ở phòng giặt bị hỏng rồi, bỏ tiền vào không thấy phản ứng gì cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_02','V238','Quản lý',2,'是卡住了吗？我过去看一下哦。','shì kǎ zhù le ma？ wǒ guò qù kàn yī xià ó。','Bị kẹt à? Để cô ra xem thử nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_03','V238','Nguyễn Minh',3,'对的，我试了两次都没用，衣服放进去没法洗。','duì de， wǒ shì le liǎng cì dōu méi yòng， yī fú fàng jìn qù méi fǎ xǐ。','Vâng, con thử hai lần rồi mà không được, quần áo bỏ vào không giặt được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_04','V238','Quản lý',4,'这台机器临时故障了，你换旁边那台用就行哈。','zhè tái jī qì lín shí gù zhàng le， nǐ huàn páng biān nà tái yòng jiù xíng hā。','Máy này đang bị hỏng tạm thời, con qua dùng máy bên cạnh là được nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_05','V238','Nguyễn Minh',5,'好的，那故障机器什么时候能修好呀？','hǎo de， nà gù zhàng jī qì shén me shí hòu néng xiū hǎo ya？','Vâng ạ, vậy máy hỏng bao giờ thì sửa được ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_06','V238','Quản lý',6,'明天师傅过来检修，今晚先用别的机器吧。','míng tiān shī fù guò lái jiǎn xiū， jīn wǎn xiān yòng bié de jī qì ba。','Mai thợ sẽ tới sửa, tối nay con cứ dùng tạm máy khác nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L238_07','V238','Nguyễn Minh',7,'麻烦您了，谢谢阿姨！','má fán nín le， xiè xiè ā yí！','Phiền cô rồi ạ, con cảm ơn cô nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT239','S3','Đi nhầm chiều tàu điện ngầm','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V239','SIT239','P1','twist','ban_chinh_thuc','Ngồi nhầm chiều tàu, được hướng dẫn đổi chiều miễn phí ngay sân ga đối diện',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_01','V239','Nguyễn Minh',1,'您好，不好意思打扰您啦！我好像坐错地铁了。','nín hǎo， bù hǎo yì sī dǎ rǎo nín la！ wǒ hǎo xiàng zuò cuò dì tiě le。','Chào chị, cho em xin lỗi làm phiền chị chút ạ! Hình như em lên nhầm chuyến tàu điện ngầm rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_02','V239','Nhân viên nhà ga',2,'没事的啊，别着急，你要去哪里呀？','méi shì de a， bié zháo jí， nǐ yào qù nǎ lǐ ya？','Không sao đâu, đừng lo, em muốn đi đâu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_03','V239','Nguyễn Minh',3,'我想去大学城校区，刚刚上车坐反方向了，现在不知道怎么换乘呢。','wǒ xiǎng qù dà xué chéng xiào qū， gāng gāng shàng chē zuò fǎn fāng xiàng le， xiàn zài bù zhī dào zěn me huàn chéng ne。','Em muốn đến khu Đại học thành, vừa lên tàu lại đi ngược chiều mất rồi, giờ không biết đổi tàu thế nào ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_04','V239','Nhân viên nhà ga',4,'难怪呢！你不用出站，下一站下车，对面站台坐二号线就可以直达啦。','nán guài ne！ nǐ bù yòng chū zhàn， xià yī zhàn xià chē， duì miàn zhàn tái zuò èr hào xiàn jiù kě yǐ zhí dá la。','Thảo nào! Em không cần ra khỏi ga đâu, xuống ở trạm tiếp theo, sang sân ga đối diện đi tuyến số 2 là tới thẳng luôn nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_05','V239','Nguyễn Minh',5,'好的，那我不用重新买票吧？','hǎo de， nà wǒ bù yòng chóng xīn mǎi piào ba？','Vâng ạ, vậy em không cần mua vé lại đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_06','V239','Nhân viên nhà ga',6,'不用的，站内换乘都免费的，放心坐吧。','bù yòng de， zhàn nèi huàn chéng dōu miǎn fèi de， fàng xīn zuò ba。','Không cần đâu, đổi chuyến trong ga là miễn phí, em cứ yên tâm lên tàu nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_07','V239','Nguyễn Minh',7,'太谢谢您了，真是帮大忙了！','tài xiè xiè nín le， zhēn shì bāng dà máng le！','Em cảm ơn chị nhiều lắm, chị giúp em một việc lớn thật đó!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L239_08','V239','Nhân viên nhà ga',8,'不客气，下次看清楚方向再上车就好啦。','bú kè qì， xià cì kàn qīng chǔ fāng xiàng zài shàng chē jiù hǎo la。','Không có gì, lần sau em nhớ xem kỹ hướng trước khi lên tàu nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT240','S11','Nhận hàng giao COD, đối chiếu thông tin','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V240','SIT240','P1','twist','tuy_y','Cước phí thực tế cao hơn dự tính trên app vì hàng quá cân',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_01','V240','Shipper',1,'你好，是阮明吧？你的到付快递到啦，是被褥和厨具对吧？','nǐ hǎo， shì ruǎn míng ba？ nǐ de dào fù kuài dì dào la， shì bèi rù hé chú jù duì ba？','Chào bạn, có phải Nguyễn Minh không? Kiện hàng thu tiền hộ của bạn tới rồi nè, là chăn ga gối và đồ bếp đúng không?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_02','V240','Nguyễn Minh',2,'对的，麻烦你帮我核对一下信息哈！手机号是尾号3621没错吧？','duì de， má fán nǐ bāng wǒ hé duì yī xià xìn xī hā！ shǒu jī hào shì wěi hào 3621 méi cuò ba？','Đúng rồi, phiền anh kiểm tra lại thông tin giúp em nha! Số điện thoại đuôi 3621 phải không ạ?','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_03','V240','Shipper',3,'没错的！地址也是学校留学生宿舍。运费一共28块哦。','méi cuò de！ dì zhǐ yě shì xué xiào liú xué shēng sù shè。 yùn fèi yī gòng 28 kuài ó。','Đúng rồi đó! Địa chỉ cũng là ký túc xá lưu học sinh của trường. Tiền ship tổng cộng là 28 tệ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_04','V240','Nguyễn Minh',4,'咦？我看页面预估是22块，怎么多了6块呀？','yí？ wǒ kàn yè miàn yù gū shì 22 kuài， zěn me duō le 6 kuài ya？','Ơ? Em thấy trên app dự tính là 22 tệ mà, sao lại dư 6 tệ vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_05','V240','Shipper',5,'你这个被子超重啦，超重部分需要补运费，平台预估不准的。','nǐ zhè ge bèi zi chāo zhòng la， chāo zhòng bù fèn xū yào bǔ yùn fèi， píng tái yù gū bù zhǔn de。','Cái chăn của bạn nặng quá cân rồi, phần vượt cân phải tính thêm phí, ứng dụng dự tính không chuẩn đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_06','V240','Nguyễn Minh',6,'原来是这样，那没问题，我扫码付钱吧。','yuán lái shì zhè yàng， nà méi wèn tí， wǒ sǎo mǎ fù qián ba。','Ra là vậy, thế thì không sao, để em quét mã trả tiền nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_07','V240','Shipper',7,'好嘞！付完我给你签收，东西都完好着呢，你可以检查一下。','hǎo lei！ fù wán wǒ gěi nǐ qiān shōu， dōng xī dōu wán hǎo zhe ne， nǐ kě yǐ jiǎn chá yī xià。','Được rồi đó! Trả xong anh ký nhận cho bạn, đồ đạc còn nguyên vẹn hết, bạn kiểm tra thử xem.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L240_08','V240','Nguyễn Minh',8,'不用检查啦，谢谢你辛苦跑一趟！','bù yòng jiǎn chá la， xiè xiè nǐ xīn kǔ pǎo yī tàng！','Không cần kiểm tra đâu ạ, cảm ơn anh vất vả chạy một chuyến nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT241','S12','Gọi món ở nhà ăn, xin không cay','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp','A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V241','SIT241','P1','suon_se','tuy_y','Yêu cầu món ăn không cay, được nhân viên gợi ý món phù hợp',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_01','V241','Nhân viên nhà ăn',1,'同学，今天想吃点什么呀？米饭还是面条？','tóng xué， jīn tiān xiǎng chī diǎn shén me ya？ mǐ fàn hái shì miàn tiáo？','Em ơi, hôm nay muốn ăn gì nào? Cơm hay mì?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_02','V241','Nguyễn Minh',2,'阿姨，我要一份番茄炒蛋盖饭，谢谢！','ā yí， wǒ yào yī fèn fān qié chǎo dàn gài fàn， xiè xiè！','Cô ơi, cho con một suất cơm trứng chiên cà chua, cảm ơn cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_03','V241','Nhân viên nhà ăn',3,'好嘞！要不要加点配菜？青菜和土豆都新鲜的。','hǎo lei！ yào bù yào jiā diǎn pèi cài？ qīng cài hé tǔ dòu dōu xīn xiān de。','Được rồi đó! Có muốn thêm chút món phụ không? Rau xanh với khoai tây đều tươi cả.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_04','V241','Nguyễn Minh',4,'不用啦阿姨！麻烦您一定不要放辣哦，我完全吃不了辣的。','bù yòng la ā yí！ má fán nín yí dìng bú yào fàng là ó， wǒ wán quán chī bù liǎo là de。','Thôi khỏi cô ơi! Phiền cô nhất định đừng cho cay nha, con hoàn toàn không ăn được cay đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_05','V241','Nhân viên nhà ăn',5,'放心吧！我记住啦，给你做清淡口味的。','fàng xīn ba！ wǒ jì zhù la， gěi nǐ zuò qīng dàn kǒu wèi de。','Yên tâm đi! Cô nhớ rồi, làm cho con phần vị thanh đạm nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_06','V241','Nguyễn Minh',6,'太好啦，谢谢阿姨！','tài hǎo la， xiè xiè ā yí！','Tuyệt quá, con cảm ơn cô!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L241_07','V241','Nhân viên nhà ăn',7,'小事一桩！马上就好，你稍微等一下哈。','xiǎo shì yī zhuāng！ mǎ shàng jiù hǎo， nǐ shāo wēi děng yí xià hā。','Chuyện nhỏ thôi! Xong ngay đây, con đợi một chút nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT242','S13','Xin nghỉ vì thủy thổ bất phục, nhờ bạn cùng phòng thông cảm','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung','B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V242','SIT242','P1','suon_se','tuy_y','Giải thích tình trạng sức khỏe, đề nghị điều chỉnh giờ giấc chung',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_01','V242','Nguyễn Minh',1,'宇哥，我这两天有点难受，想跟你说个事呢。','yǔ gē， wǒ zhè liǎng tiān yǒu diǎn nán shòu， xiǎng gēn nǐ shuō gè shì ne。','Vũ ơi, mấy hôm nay em thấy hơi khó chịu, muốn nói với anh một chuyện.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_02','V242','Lâm Vũ',2,'怎么了？你看着气色不太好，是不舒服吗？','zěn me le？ nǐ kàn zhe qì sè bù tài hǎo， shì bù shū fú ma？','Sao vậy? Nhìn sắc mặt em không được tốt lắm, khó chịu trong người à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_03','V242','Nguyễn Minh',3,'应该是水土不服，晚上总睡不好，白天上课特别困。','yīng gāi shì shuǐ tǔ bù fú， wǎn shàng zǒng shuì bù hǎo， bái tiān shàng kè tè bié kùn。','Chắc là do chưa quen thủy thổ, tối cứ ngủ không ngon, ban ngày đi học lại buồn ngủ kinh khủng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_04','V242','Lâm Vũ',4,'难怪你这两天都没怎么说话！那你打算怎么办呀？','nán guài nǐ zhè liǎng tiān dōu méi zěn me shuō huà！ nà nǐ dǎ suàn zěn me bàn ya？','Thảo nào mấy hôm nay em ít nói hẳn! Vậy em định làm sao đây?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_05','V242','Nguyễn Minh',5,'我想今天下午请假休息，晚上也早点睡觉，咱们作息稍微调整一下可以吗？','wǒ xiǎng jīn tiān xià wǔ qǐng jià xiū xī， wǎn shàng yě zǎo diǎn shuì jiào， zán men zuò xī shāo wēi tiáo zhěng yī xià kě yǐ ma？','Em muốn chiều nay xin nghỉ để nghỉ ngơi, tối cũng ngủ sớm hơn, mình điều chỉnh giờ giấc một chút được không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_06','V242','Lâm Vũ',6,'当然没问题啊！你好好休息就行，我晚上小声一点，不打扰你。','dāng rán méi wèn tí a！ nǐ hǎo hǎo xiū xī jiù xíng， wǒ wǎn shàng xiǎo shēng yì diǎn， bù dǎ rǎo nǐ。','Đương nhiên không vấn đề gì! Em cứ nghỉ ngơi cho khỏe, tối anh nói khẽ lại, không làm phiền em đâu.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_07','V242','Nguyễn Minh',7,'太谢谢你了，真的麻烦你啦！','tài xiè xiè nǐ le， zhēn de má fán nǐ la！','Cảm ơn anh nhiều lắm, thật sự làm phiền anh rồi!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L242_08','V242','Lâm Vũ',8,'客气啥，室友本来就该互相照顾的嘛。','kè qì shá， shì yǒu běn lái jiù gāi hù xiāng zhào gù de ma。','Khách sáo gì chứ, ở chung phòng vốn dĩ phải quan tâm nhau mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT243','S7','Hỏi quy định đăng ký khách đến thăm ký túc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V243','SIT243','P1','twist','ban_chinh_thuc','Có bạn muốn đến thăm buổi tối nhưng ký túc cấm khách ban đêm',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_01','V243','Nguyễn Minh',1,'王阿姨您好，打扰您了！我想咨询一下访客入校的规定。','wáng ā yí nín hǎo， dǎ rǎo nín le！ wǒ xiǎng zī xún yī xià fǎng kè rù xiào de guī dìng。','Cô Vương ơi, làm phiền cô rồi ạ! Em muốn hỏi thăm về quy định khách vào trường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_02','V243','Quản lý',2,'你好，是有朋友要来宿舍找你吗？','nǐ hǎo， shì yǒu péng yǒu yào lái sù shè zhǎo nǐ ma？','Chào em, có bạn muốn đến ký túc tìm em à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_03','V243','Nguyễn Minh',3,'对的，我同学明天想来宿舍找我，需要怎么登记呀？','duì de， wǒ tóng xué míng tiān xiǎng lái sù shè zhǎo wǒ， xū yào zěn me dēng jì ya？','Dạ đúng ạ, bạn học của em mai muốn đến ký túc tìm em, cần đăng ký như thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_04','V243','Quản lý',4,'很简单的，白天来访带身份证，在门卫处登记信息就可以啦。','hěn jiǎn dān de， bái tiān lái fǎng dài shēn fèn zhèng， zài mén wèi chù dēng jì xìn xī jiù kě yǐ la。','Đơn giản thôi, ban ngày đến thăm thì mang theo chứng minh thư, đăng ký thông tin ở chỗ bảo vệ là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_05','V243','Nguyễn Minh',5,'那晚上可以来访吗？我本来约了晚上见面的。','nà wǎn shàng kě yǐ lái fǎng ma？ wǒ běn lái yuē le wǎn shàng jiàn miàn de。','Vậy buổi tối có đến được không ạ? Em vốn đã hẹn gặp vào buổi tối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_06','V243','Quản lý',6,'晚上不行哦，宿舍十点锁门，晚间禁止外来人员入校的。','wǎn shàng bù xíng ó， sù shè shí diǎn suǒ mén， wǎn jiān jìn zhǐ wài lái rén yuán rù xiào de。','Tối thì không được đâu, ký túc khóa cửa lúc mười giờ, buổi tối cấm người ngoài vào trường.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_07','V243','Nguyễn Minh',7,'原来是这样，那我改到白天吧，谢谢您告知我！','yuán lái shì zhè yàng， nà wǒ gǎi dào bái tiān ba， xiè xiè nín gào zhī wǒ！','Thì ra là vậy, vậy em đổi sang ban ngày ạ, cảm ơn cô đã cho em biết!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L243_08','V243','Quản lý',8,'没事的，提前安排好就行，记得让你朋友带证件哈。','méi shì de， tí qián ān pái hǎo jiù xíng， jì de ràng nǐ péng yǒu dài zhèng jiàn hā。','Không sao đâu, sắp xếp trước là được rồi, nhớ nhắc bạn em mang theo giấy tờ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT244','S7','Báo chủ nhà đổi giờ nhận phòng vì chuyến bay trễ','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V244','SIT244','P1','that_bai_nhe','ban_chinh_thuc','Chuyến bay bị hoãn, xin lỗi và thương lượng lại giờ nhận phòng','提前主动告知行程变动，中国人一般不会严厉追责，但短期房屋预留存在时间限制，过夜空置房东有权收取空置费用；诚恳沟通大多可以免除额外收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_01','V244','阮明',1,'刘哥您好，不好意思打扰您休息，有件事需要跟您协商调整。','liú gē nín hǎo， bù hǎo yì sī dǎ rǎo nín xiū xī， yǒu jiàn shì xū yào gēn nín xié shāng diào zhěng。','Chào anh Lưu, xin lỗi vì đã làm phiền anh nghỉ ngơi, có việc em cần trao đổi và điều chỉnh với anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_02','V244','房东',2,'你好同学，我记得咱们约定好今天下午两点过来办理房屋入住的对吧？','nǐ hǎo tóng xué， wǒ jì de zán men yuē dìng hǎo jīn tiān xià wǔ liǎng diǎn guò lái bàn lǐ fáng wū rù zhù de duì ba？','Chào em, anh nhớ là mình hẹn hai giờ chiều nay đến làm thủ tục nhận phòng đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_03','V244','阮明',3,'非常抱歉！我乘坐的入境航班大面积延误，落地时间推迟六个小时，今天肯定赶不过来了呢。','fēi cháng bào qiàn！ wǒ chéng zuò de rù jìng háng bān dà miàn jī yán wù， luò dì shí jiān tuī chí liù gè xiǎo shí， jīn tiān kěn dìng gǎn bù guò lái le ne。','Em xin lỗi anh rất nhiều! Chuyến bay nhập cảnh của em bị hoãn trên diện rộng, giờ hạ cánh trễ mất sáu tiếng, hôm nay chắc chắn không kịp đến được ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_04','V244','房东',4,'这样啊？我今天专门空出一下午在家等你交接，临时变动确实有点麻烦。','zhè yàng a？ wǒ jīn tiān zhuān mén kòng chū yī xià wǔ zài jiā děng nǐ jiāo jiē， lín shí biàn dòng què shí yǒu diǎn má fán。','Vậy à? Hôm nay anh đã đặc biệt để trống cả buổi chiều ở nhà chờ giao nhận nhà cho em, thay đổi đột xuất thế này quả thật hơi phiền.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_05','V244','阮明',5,'我特别理解您的不便，机场工作人员说最快明天下午两点才能抵达市区。','wǒ tè bié lǐ jiě nín de bù biàn， jī chǎng gōng zuò rén yuán shuō zuì kuài míng tiān xià wǔ liǎng diǎn cái néng dǐ dá shì qū。','Em rất hiểu sự bất tiện của anh, nhân viên sân bay nói sớm nhất cũng phải hai giờ chiều mai mới đến được trung tâm thành phố.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_06','V244','房东',6,'我原本计划今天交接完房屋，晚上出门办事，现在行程全部打乱了。','wǒ yuán běn jì huà jīn tiān jiāo jiē wán fáng wū， wǎn shàng chū mén bàn shì， xiàn zài háng chéng quán bù dǎ luàn le。','Anh vốn định hôm nay giao nhận nhà xong thì tối đi có việc, giờ lịch trình bị xáo trộn hết cả rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_07','V244','阮明',7,'能不能麻烦您帮我延后一天入住，明天下午我准时到，绝不再次迟到？','néng bù néng má fán nín bāng wǒ yán hòu yī tiān rù zhù， míng tiān xià wǔ wǒ zhǔn shí dào， jué bù zài cì chí dào？','Anh có thể giúp em dời lại một ngày nhận phòng được không ạ, chiều mai em sẽ đến đúng giờ, tuyệt đối không trễ nữa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_08','V244','房东',8,'按理当天预留的房间只能保留至当日深夜，过夜预留需要额外收取半天空置费。','àn lǐ dàng tiān yù liú de fáng jiān zhǐ néng bǎo liú zhì dāng rì shēn yè， guò yè yù liú xū yào é wài shōu qǔ bàn tiān kōng zhì fèi。','Theo quy định phòng giữ trong ngày chỉ được giữ đến nửa đêm hôm đó thôi, giữ qua đêm thì phải tính thêm phí bỏ trống nửa ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_09','V244','阮明',9,'我明白规则，只要能保留房间，相关费用我可以正常承担。','wǒ míng bái guī zé， zhǐ yào néng bǎo liú fáng jiān， xiāng guān fèi yòng wǒ kě yǐ zhèng cháng chéng dān。','Em hiểu quy định mà, chỉ cần giữ được phòng, chi phí liên quan em sẽ thanh toán bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_10','V244','房东',10,'看你是留学生刚来国内不容易，空置费我就不收了，但今天房间不再单独为你预留。','kàn nǐ shì liú xué shēng gāng lái guó nèi bù róng yì， kōng zhì fèi wǒ jiù bù shōu le， dàn jīn tiān fáng jiān bù zài dān dú wèi nǐ yù liú。','Thấy em là du học sinh mới sang cũng không dễ dàng gì, phí bỏ trống anh sẽ không thu, nhưng hôm nay phòng sẽ không giữ riêng cho em nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_11','V244','阮明',11,'太感谢您的理解和体谅，临时行程变动给您添了不少麻烦，真的不好意思！','tài gǎn xiè nín de lǐ jiě hé tǐ liàng， lín shí xíng chéng biàn dòng gěi nín tiān le bù shǎo má fán， zhēn de bù hǎo yì sī！','Cảm ơn anh rất nhiều vì đã thông cảm và thấu hiểu, việc thay đổi lịch trình đột xuất này gây phiền cho anh không ít, thật sự xin lỗi anh!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_12','V244','房东',12,'不用客气，出门在外难免有突发变动嘛，但是明天抵达前一小时一定要提前跟我说一声。','bù yòng kè qì， chū mén zài wài nán miǎn yǒu tū fā biàn dòng ma， dàn shì míng tiān dǐ dá qián yī xiǎo shí yí dìng yào tí qián gēn wǒ shuō yī shēng。','Không cần khách sáo đâu, đi xa khó tránh khỏi chuyện phát sinh bất ngờ mà, nhưng trước khi đến vào ngày mai một tiếng thì nhất định phải báo trước cho anh một tiếng nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_13','V244','阮明',13,'我一定提前发消息告知您到站时间，方便您提前到家等候。','wǒ yí dìng tí qián fā xiāo xī gào zhī nín dào zhàn shí jiān， fāng biàn nín tí qián dào jiā děng hòu。','Em nhất định sẽ nhắn tin báo trước giờ em đến ga cho anh, để anh tiện về nhà chờ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L244_14','V244','房东',14,'好，那我们就约定明天下午两点办理入住，明天见！','hǎo， nà wǒ men jiù yuē dìng míng tiān xià wǔ liǎng diǎn bàn lǐ rù zhù， míng tiān jiàn！','Được, vậy mình hẹn hai giờ chiều mai làm thủ tục nhận phòng, hẹn gặp em ngày mai!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT301','S101','Hỏi giá và khuyến mãi ở siêu thị',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V301','SIT301','P1','suon_se','tuy_y',NULL,'国内商超日常促销多为即时抵扣、买赠模式，无需凑单，活动规则简单直白。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_01','V301','阮明',1,'你好，请问这款纯牛奶多少钱一箱啊？','nǐ hǎo， qǐng wèn zhè kuǎn chún niú nǎi duō shǎo qián yī xiāng a？','Chào chị, cho em hỏi loại sữa tươi nguyên chất này giá bao nhiêu một thùng ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_02','V301','导购员',2,'这款68一箱，我们这两天刚好有活动呢。','zhè kuǎn 68 yī xiāng， wǒ men zhè liǎng tiān gāng hǎo yǒu huó dòng ne。','Loại này 68 tệ một thùng, mấy hôm nay đang có chương trình khuyến mãi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_03','V301','阮明',3,'那是什么优惠呀，划算吗？','nà shì shén me yōu huì ya， huá suàn ma？','Vậy ưu đãi gì vậy chị, có lời không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_04','V301','导购员',4,'买一箱送一小盒酸奶，买两箱直接减20块，很划算的。','mǎi yī xiāng sòng yī xiǎo hé suān nǎi， mǎi liǎng xiāng zhí jiē jiǎn 20 kuài， hěn huá suàn de。','Mua một thùng tặng một hộp sữa chua nhỏ, mua hai thùng thì giảm thẳng 20 tệ, lời lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_05','V301','阮明',5,'这样啊，那我买两箱吧，平时喝得多。','zhè yàng a， nà wǒ mǎi liǎng xiāng ba， píng shí hē dé duō。','Vậy à, thế thì em mua hai thùng luôn, nhà em cũng hay uống.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_06','V301','导购员',6,'可以的，我帮你扫一下，结账自动抵扣。','kě yǐ de， wǒ bāng nǐ sǎo yī xià， jié zhàng zì dòng dǐ kòu。','Được rồi, để chị quét mã cho em, lúc tính tiền sẽ tự động trừ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L301_07','V301','阮明',7,'好嘞，谢谢你！','hǎo lei， xiè xiè nǐ！','Dạ vâng, cảm ơn chị!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT302','S101','Cân rau quả và tự thanh toán',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V302','SIT302','P1','twist','tuy_y',NULL,'国内超市生鲜蔬果必须自助称重贴价签，无标签商品无法通过自助结账，是通用规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_01','V302','阮明',1,'阿姨，请问蔬菜水果是在这里称重的吧？','ā yí， qǐng wèn shū cài shuǐ guǒ shì zài zhè lǐ chēng zhòng de ba？','Cô ơi, rau củ quả là cân ở đây đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_02','V302','阿姨',2,'对的呀，把东西放上去选对应的菜名就行。','duì de ya， bǎ dōng xī fàng shàng qù xuǎn duì yìng de cài míng jiù xíng。','Đúng rồi đó, con để đồ lên rồi chọn đúng tên rau là được.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_03','V302','阮明',3,'奇怪，我按了好几次，怎么都不出标签呢？','qí guài， wǒ àn le hǎo jǐ cì， zěn me dōu bù chū biāo qiān ne？','Lạ ghê, con bấm mấy lần rồi mà sao không ra tem vậy cô?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_04','V302','阿姨',4,'我看看，你选的是大白菜，你拿的是青菜，选错品类啦。','wǒ kàn kàn， nǐ xuǎn de shì dà bái cài， nǐ ná de shì qīng cài， xuǎn cuò pǐn lèi la。','Để cô xem, con chọn cải thảo mà con lại cầm rau cải xanh, chọn sai loại rồi đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_05','V302','阮明',5,'原来是这样，难怪一直不行，我重新弄一下。','yuán lái shì zhè yàng， nán guài yì zhí bù xíng， wǒ chóng xīn nòng yī xià。','Thì ra là vậy, thảo nào cứ không được, để con làm lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_06','V302','阿姨',6,'没事，慢慢来，打好标签就可以去自助机结账了。','méi shì， màn màn lái， dǎ hǎo biāo qiān jiù kě yǐ qù zì zhù jī jié zhàng le。','Không sao, cứ từ từ, in tem xong là ra máy tự thanh toán được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L302_07','V302','阮明',7,'太感谢您了，不然我得卡好久。','tài gǎn xiè nín le， bù rán wǒ dé kǎ hǎo jiǔ。','Cảm ơn cô nhiều lắm, không thì con phải loay hoay lâu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT303','S101','Đổi trả hàng bị lỗi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V303','SIT303','P1','suon_se','ban_chinh_thuc',NULL,'国内正规商超在售后期内，非人为损坏的商品，可凭购物凭证无条件退换货；生鲜食品变质优先全额退款，避免顾客再次购买同类问题产品。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_01','V303','阮明',1,'你好，我有一件商品存在质量问题，想来售后窗口处理退换。','nǐ hǎo， wǒ yǒu yī jiàn shāng pǐn cún zài zhì liàng wèn tí， xiǎng lái shòu hòu chuāng kǒu chǔ lǐ tuì huàn。','Chào chị, em có một món hàng bị lỗi chất lượng, muốn đến quầy hậu mãi để xử lý đổi trả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_02','V303','店员',2,'您好，麻烦先跟我说一下是什么商品，什么时候在店内购买的？','nín hǎo， má fán xiān gēn wǒ shuō yī xià shì shén me shāng pǐn， shén me shí hòu zài diàn nèi gòu mǎi de？','Chào em, phiền em nói qua giúp chị là hàng gì, mua ở cửa hàng lúc nào vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_03','V303','阮明',3,'是一款全麦吐司面包，昨天傍晚在生鲜烘焙区选购的，今天早上拆开就发霉了。','shì yī kuǎn quán mài tǔ sī miàn bāo， zuó tiān bàng wǎn zài shēng xiān hōng bèi qū xuǎn gòu de， jīn tiān zǎo shàng chāi kāi jiù fā méi le。','Là bánh mì nguyên cám ạ, em mua chiều tối hôm qua ở khu bánh tươi, sáng nay mở ra thì đã bị mốc rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_04','V303','店员',4,'麻烦出示一下对应的购物小票，我们需要核对购买时间和批次信息。','má fán chū shì yī xià duì yìng de gòu wù xiǎo piào， wǒ men xū yào hé duì gòu mǎi shí jiān hé pī cì xìn xī。','Phiền em cho chị xem hóa đơn mua hàng tương ứng, chị cần đối chiếu thời gian mua và thông tin lô hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_05','V303','阮明',5,'小票我一直妥善收在钱包里，现在拿给您，我全程常温存放，根本没放多久呀。','xiǎo piào wǒ yì zhí tuǒ shàn shōu zài qián bāo lǐ， xiàn zài ná gěi nín， wǒ quán chéng cháng wēn cún fàng， gēn běn méi fàng duō jiǔ ya。','Hóa đơn em vẫn cất cẩn thận trong ví, giờ em đưa chị đây, em bảo quản ở nhiệt độ thường suốt, cũng đâu để lâu gì đâu ạ.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_06','V303','店员',6,'我对照系统入库记录核对面包批次，确认是商品本身出厂保鲜出现问题，非常抱歉哈。','wǒ duì zhào xì tǒng rù kù jì lù hé duì miàn bāo pī cì， què rèn shì shāng pǐn běn shēn chū chǎng bǎo xiān chū xiàn wèn tí， fēi cháng bào qiàn hā。','Chị đối chiếu ghi chép nhập kho trong hệ thống với lô bánh này, xác nhận là do khâu bảo quản xuất xưởng của sản phẩm có vấn đề, chị xin lỗi em nhiều nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_07','V303','阮明',7,'没关系，我也不是故意为难店里，只是担心同类商品其他顾客买到。','méi guān xì， wǒ yě bú shì gù yì wéi nán diàn lǐ， zhǐ shì dān xīn tóng lèi shāng pǐn qí tā gù kè mǎi dào。','Không sao đâu chị, em cũng không cố ý làm khó cửa hàng, chỉ lo là khách khác cũng mua phải loại hàng này thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_08','V303','店员',8,'您愿意换新商品，还是直接申请全额退款，两种方案都可以执行。','nín yuàn yì huàn xīn shāng pǐn， hái shì zhí jiē shēn qǐng quán é tuì kuǎn， liǎng zhǒng fāng àn dōu kě yǐ zhí xíng。','Em muốn đổi hàng mới hay là làm thủ tục hoàn tiền toàn bộ luôn, cả hai cách đều được cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_09','V303','阮明',9,'这款面包我不敢再选购同款，直接办理全额退款会更合适。','zhè kuǎn miàn bāo wǒ bù gǎn zài xuǎn gòu tóng kuǎn， zhí jiē bàn lǐ quán é tuì kuǎn huì gèng hé shì。','Loại bánh này em không dám mua lại nữa, hoàn tiền toàn bộ sẽ hợp lý hơn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_10','V303','店员',10,'没问题，我现在操作后台退款，资金会原路返还到您付款的支付软件。','méi wèn tí， wǒ xiàn zài cāo zuò hòu tái tuì kuǎn， zī jīn huì yuán lù fǎn huán dào nín fù kuǎn de zhī fù ruǎn jiàn。','Không vấn đề gì, giờ chị thao tác hoàn tiền trên hệ thống, tiền sẽ hoàn về đúng ứng dụng thanh toán em đã dùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_11','V303','阮明',11,'退款到账大概需要多长时间，会不会有延迟？','tuì kuǎn dào zhàng dà gài xū yào duō zhǎng shí jiān， huì bú huì yǒu yán chí？','Tiền hoàn về khoảng bao lâu vậy chị, có bị chậm trễ gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_12','V303','店员',12,'线上支付退款实时到账，您现在打开手机就能查到余额变动。','xiàn shàng zhī fù tuì kuǎn shí shí dào zhàng， nín xiàn zài dǎ kāi shǒu jī jiù néng chá dào yú é biàn dòng。','Hoàn tiền thanh toán online là về ngay lập tức, em mở điện thoại lên là thấy số dư thay đổi liền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_13','V303','阮明',13,'清楚流程了，给您添麻烦实在不好意思。','qīng chǔ liú chéng le， gěi nín tiān má fán shí zài bù hǎo yì sī。','Em hiểu quy trình rồi ạ, làm phiền chị nhiều thật sự xin lỗi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_14','V303','店员',14,'是我们商品存在质量瑕疵，本该向您致歉，您慢走。','shì wǒ men shāng pǐn cún zài zhì liàng xiá cī， běn gāi xiàng nín zhì qiàn， nín màn zǒu。','Là do sản phẩm bên chị bị lỗi chất lượng, đáng lẽ phải xin lỗi em mới đúng, em đi cẩn thận nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L303_15','V303','阮明',15,'好的，麻烦你啦。','hǎo de， má fán nǐ la。','Dạ vâng, phiền chị nhiều rồi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT304','S102','Mua chăn, gối, nồi, ly cho phòng mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V304','SIT304','P1','twist','tuy_y',NULL,'国内高校宿舍严禁大功率电器，校园店铺售卖的煮锅均为合规小功率产品，不会违规跳闸。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_01','V304','阮明',1,'老板，我是新生，想买一套宿舍被褥、枕头还有小煮锅。','lǎo bǎn， wǒ shì xīn shēng， xiǎng mǎi yī tào sù shè bèi rù、 zhěn tou hái yǒu xiǎo zhǔ guō。','Anh ơi, em là sinh viên mới, muốn mua một bộ chăn ga gối ký túc với cả nồi nấu nhỏ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_02','V304','老板',2,'有的，这些都是学生专用的，厚度和功率都适配宿舍的。','yǒu de， zhè xiē dōu shì xué shēng zhuān yòng de， hòu dù hé gōng lǜ dōu shì pèi sù shè de。','Có chứ, mấy món này đều là loại chuyên dùng cho sinh viên, độ dày và công suất đều phù hợp với ký túc hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_03','V304','阮明',3,'这个被子冬天盖够厚吗？我怕冷的。','zhè ge bèi zi dōng tiān gài gòu hòu ma？ wǒ pà lěng de。','Cái chăn này mùa đông đắp có đủ ấm không anh? Em sợ lạnh lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_04','V304','老板',4,'足够过冬的，就是宿舍小煮锅今天刚卖断货了嘛。','zú gòu guò dōng de， jiù shì sù shè xiǎo zhǔ guō jīn tiān gāng mài duàn huò le ma。','Đủ để qua mùa đông luôn, chỉ có điều nồi nấu nhỏ cho ký túc hôm nay vừa bán hết hàng rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_05','V304','阮明',5,'啊？那什么时候能补货呀？我急用。','a？ nà shén me shí hòu néng bǔ huò ya？ wǒ jí yòng。','Hả? Vậy khi nào có hàng lại vậy anh? Em đang cần gấp.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_06','V304','老板',6,'明天中午就到货，你明天过来拿就行。','míng tiān zhōng wǔ jiù dào huò， nǐ míng tiān guò lái ná jiù xíng。','Trưa mai là có hàng về rồi, mai em qua lấy là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L304_07','V304','阮明',7,'行，那我今天先买被子、枕头和水杯。','xíng， nà wǒ jīn tiān xiān mǎi bèi zi、 zhěn tou hé shuǐ bēi。','Vâng, vậy hôm nay em mua trước chăn, gối với ly nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT305','S103','Mua nước giặt và dùng máy giặt tự động',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V305','SIT305','P1','suon_se','tuy_y',NULL,'国内高校宿舍洗衣房均为无人自助设备，按次计费，无需人工值守，操作简单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_01','V305','阮明',1,'学姐，请问哪种洗衣液好用啊？我第一次在宿舍洗衣服。','xué jiě， qǐng wèn nǎ zhǒng xǐ yī yè hǎo yòng a？ wǒ dì yī cì zài sù shè xǐ yī fú。','Chị ơi, cho em hỏi loại nước giặt nào dùng tốt vậy chị? Em lần đầu giặt đồ ở ký túc.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_02','V305','学姐',2,'你买这款瓶装的就行，味道清淡，去污力也不错呢。','nǐ mǎi zhè kuǎn píng zhuāng de jiù xíng， wèi dào qīng dàn， qù wū lì yě bù cuò ne。','Em mua loại chai này là được, mùi nhẹ nhàng, tẩy sạch cũng tốt lắm đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_03','V305','阮明',3,'好嘞，那楼下自助洗衣机难操作吗？','hǎo lei， nà lóu xià zì zhù xǐ yī jī nán cāo zuò ma？','Dạ được, vậy máy giặt tự động ở dưới lầu có khó dùng không chị?','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_04','V305','学姐',4,'一点不难，扫码付款、放衣服和洗衣液就可以啦。','yì diǎn bù nán， sǎo mǎ fù kuǎn、 fàng yī fú hé xǐ yī yè jiù kě yǐ la。','Không khó chút nào, quét mã thanh toán, bỏ quần áo với nước giặt vào là xong.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_05','V305','阮明',5,'需要自己调时间和模式吗？','xū yào zì jǐ diào shí jiān hé mó shì ma？','Có cần tự chỉnh thời gian với chế độ giặt không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_06','V305','学姐',6,'不用，默认标准模式，洗得很干净的。','bù yòng， mò rèn biāo zhǔn mó shì， xǐ dé hěn gān jìng de。','Không cần đâu, mặc định chế độ tiêu chuẩn, giặt sạch lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L305_07','V305','阮明',7,'明白了，太谢谢你啦！','míng bái le， tài xiè xiè nǐ la！','Em hiểu rồi ạ, cảm ơn chị nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT306','S103','Máy giặt hết tiền giữa chừng, xin hoàn tiền',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V306','SIT306','P1','suon_se','ban_chinh_thuc',NULL,'校园自助设备出现扣费异常、中途停机等问题，均可找宿管统一走后勤退款流程；退款不会即时处理，学校后勤固定日期批量结算。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_01','V306','阮明',1,'阿姨您好，我刚刚在宿舍楼自助洗衣房洗衣服，机器运行一半突然停机了。','ā yí nín hǎo， wǒ gāng gāng zài sù shè lóu zì zhù xǐ yī fáng xǐ yī fú， jī qì yùn xíng yí bàn tū rán tíng jī le。','Cô ơi, cháu vừa giặt đồ ở tiệm giặt tự động trong ký túc xá, máy đang chạy nửa chừng thì tự nhiên dừng lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_02','V306','宿管阿姨',2,'别着急，你先回忆一下，机器停机的时候屏幕有没有弹出提示文字？','bié zháo jí， nǐ xiān huí yì yī xià， jī qì tíng jī de shí hòu píng mù yǒu méi yǒu dàn chū tí shì wén zì？','Đừng lo, cháu thử nhớ lại xem lúc máy dừng thì màn hình có hiện thông báo gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_03','V306','阮明',3,'屏幕显示账户余额不足，自动中断洗涤程序，衣服只洗了一半。','píng mù xiǎn shì zhàng hù yú é bù zú， zì dòng zhōng duàn xǐ dí chéng xù， yī fú zhǐ xǐ le yí bàn。','Màn hình báo số dư tài khoản không đủ, chương trình giặt tự động bị ngắt, quần áo mới giặt được nửa chừng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_04','V306','宿管阿姨',4,'原来是扣费余额耗尽，这种情况在自助设备使用里十分常见。','yuán lái shì kòu fèi yú é hào jìn， zhè zhǒng qíng kuàng zài zì zhù shè bèi shǐ yòng lǐ shí fēn cháng jiàn。','Thì ra là hết tiền trong tài khoản, tình trạng này khá thường gặp khi dùng máy tự động lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_05','V306','阮明',5,'我之前查看余额还有几块钱，以为完全够完整洗完一整轮，没想到中途欠费了。','wǒ zhī qián chá kàn yú é hái yǒu jǐ kuài qián， yǐ wéi wán quán gòu wán zhěng xǐ wán yī zhěng lún， méi xiǎng dào zhōng tú qiàn fèi le。','Lúc trước cháu kiểm tra thấy vẫn còn vài đồng, tưởng là đủ để giặt xong hết một lượt, ai ngờ giữa chừng lại thiếu tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_06','V306','宿管阿姨',6,'洗衣程序分为洗涤、漂洗、脱水三段，分段扣取费用，余额不够就会中途停机。','xǐ yī chéng xù fēn wéi xǐ dí、 piǎo xǐ、 tuō shuǐ sān duàn， fēn duàn kòu qǔ fèi yòng， yú é bù gòu jiù huì zhōng tú tíng jī。','Chương trình giặt chia làm ba bước: giặt, xả, vắt, mỗi bước trừ tiền riêng, không đủ số dư là nó dừng giữa chừng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_07','V306','阮明',7,'那像我这种只洗一半就停机的情况，可以申请退还部分洗衣费用吗？','nà xiàng wǒ zhè zhǒng zhǐ xǐ yí bàn jiù tíng jī de qíng kuàng， kě yǐ shēn qǐng tuì huán bù fèn xǐ yī fèi yòng ma？','Vậy trường hợp như cháu, mới giặt được nửa chừng thì máy dừng, có xin hoàn lại một phần tiền giặt được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_08','V306','宿管阿姨',8,'完全可以，后勤处专门有异常扣费退款登记流程，我帮你上报。','wán quán kě yǐ， hòu qín chù zhuān mén yǒu yì cháng kòu fèi tuì kuǎn dēng jì liú chéng， wǒ bāng nǐ shàng bào。','Được chứ, bên hậu cần có quy trình đăng ký hoàn tiền cho trường hợp trừ phí bất thường, để cô báo lên giúp cháu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Để làm thủ tục hoàn tiền, cháu cần in hóa đơn thanh toán giấy, hay chỉ cần gửi ảnh chụp màn hình điện thoại thôi ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in giấy đâu, cháu cứ chụp lại màn hình thanh toán lúc đó rồi gửi qua WeChat cho cô là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Cháu lấy ảnh gửi ngay đây ạ, khoảng bao lâu thì tiền hoàn về ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ thứ Sáu hàng tuần là xử lý gộp các yêu cầu hoàn tiền, chậm nhất thứ Sáu tuần này tiền sẽ hoàn về đúng nguồn thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Cháu hiểu rồi, phải chờ xử lý gộp mà, cô giúp đăng ký báo lên là được rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ mà, lần sau giặt đồ nhớ nạp thêm chút tiền vào, tránh để máy dừng giữa chừng nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ vâng, cảm ơn cô vất vả giúp cháu nhé!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, cho em một cái bánh tráng ngũ cốc, gói mang đi nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được rồi, em có muốn thêm xúc xích nướng, xà lách không?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Thêm một cây xúc xích nướng thôi, ít ớt lại giúp em nha, em không ăn cay được lắm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không vấn đề gì, vị cay nhẹ nha, hai phút là xong liền.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Chị gói cho em chắc chắn chút nha, em mang về ký túc xá ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói kín mít cho em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nha!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn xong, có mấy điều kiêng kỵ quan trọng cần ghi chú lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào bạn, bạn cứ nói rõ yêu cầu cụ thể, chúng tôi sẽ chuyển ngay cho bếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng đậu phộng khá nặng, xin đừng cho bất kỳ chút đậu phộng nào vào món ăn nhé.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Vâng, chúng tôi đã ghi chú đặc biệt về việc kiêng đậu phộng cho đơn của bạn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây từng có quán bỏ sót phần ghi chú này, suýt nữa xảy ra chuyện đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng tôi rất xin lỗi vì đã khiến bạn lo lắng, sẽ dặn dò riêng bên bếp cẩn thận hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy nhờ các bạn để ý kỹ giúp mình nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, cho em hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Sữa chua để ở nhiệt độ thường này hạn dùng ba tháng, không cần bỏ tủ lạnh đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở nắp thì để được bao lâu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','Ra là vậy, để ở nhiệt độ thường là được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, chỉ cần tránh ánh nắng trực tiếp thôi, tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em hiểu rồi ạ, cảm ơn chị!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn chút nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, có chuyện gì bạn cứ nói thẳng luôn nha.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Buổi tối mình cần ôn bài thi, phòng các bạn hơi ồn một chút.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn, tụi mình không để ý âm lượng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau mười giờ tối thì yên tĩnh hơn một chút thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, tụi mình nhỏ tiếng lại ngay, sau này chắc chắn sẽ chú ý!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thầy ơi em xin lỗi, em đi học trễ, thật sự rất xin lỗi thầy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại trễ vậy? Nguyên nhân là gì thế?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Sáng nay em ra khỏi nhà hơi muộn, lại gặp kẹt xe nên bị trễ giờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải canh giờ cho tốt, đừng để trễ nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Em nhớ rồi ạ, sau này em sẽ ra khỏi nhà sớm hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, vào chỗ ngồi nghe giảng nhanh đi, đừng để ảnh hưởng việc học.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Em cảm ơn thầy đã thông cảm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Cô ơi, em muốn xin nghỉ phép chiều nay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được thôi, em nói qua lý do xin nghỉ nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Em có việc riêng quan trọng cần giải quyết, không thể hoãn lại được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Cô hiểu rồi, để cô ghi nhận vào điểm danh, cho em nghỉ phép.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn cô, bài học bị lỡ em sẽ bổ sung kịp thời ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhất định phải theo kịp tiến độ, đừng để nợ bài đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Em hiểu rồi ạ, cô vất vả rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Thầy ơi, xin phép chiếm chút thời gian của thầy, em muốn xin thầy cho gia hạn nộp bài tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói rõ lý do trước đã, quy định lớp mình là không được tự ý trì hoãn nộp bài vô cớ đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua cả ngày em bị đau bụng đột ngột, chóng mặt mệt mỏi phải nằm nghỉ, hoàn toàn không có sức để làm bài ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Ốm thì thầy hiểu, bệnh là trường hợp đặc biệt hợp lý, nhưng việc gia hạn vẫn có quy định thời hạn nghiêm ngặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Em vốn định chiều tối nay nộp bài đúng hạn, nhưng giờ vẫn còn thiếu một nửa nội dung chưa làm xong ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài chỉ được gia hạn tối đa một ngày thôi, không thể kéo dài mãi được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Chỉ cần gia hạn một ngày là đủ với em rồi ạ, tối nay em sẽ thức khuya làm cho xong, đảm bảo hoàn thành đầy đủ nội dung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em ốm nên thầy châm chước đặc biệt một lần, sau này dù lý do gì cũng phải cố gắng hoàn thành đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc của thầy rồi ạ, lần sau em sẽ sắp xếp thời gian trước, sẽ không để xảy ra trễ hạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp trễ thì chậm nhất sáu giờ chiều mai phải nộp tới văn phòng, nếu trễ hạn vẫn sẽ bị trừ điểm quá trình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ đặt báo thức để nộp đúng giờ, sẽ không bỏ lỡ thời hạn đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi bài được nộp thầy sẽ ưu tiên chấm trước, có lỗi gì thầy sẽ giải thích riêng cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em cảm ơn thầy rất nhiều vì đã thông cảm cho tình trạng sức khỏe của em, em nhất định sẽ làm bài thật nghiêm túc ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho tốt vào, đừng thức khuya quá mà hại sức khỏe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Dạ vâng, em cảm ơn thầy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Bài tập nhóm mình vẫn chưa phân công, hôm nay chốt luôn nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được đó, mình phân công theo sở trường của từng người, làm vậy hiệu quả hơn.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Mình mạnh về thu thập tài liệu với viết nội dung, cậu làm PPT được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không vấn đề gì, mình làm PPT khá ổn, để phần đó cho mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy phần thuyết trình cuối cùng trên lớp, hai đứa mình cùng phối hợp nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được, làm xong mình kiểm tra chéo cho nhau, tránh sai sót.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Tuyệt vời, vậy mỗi đứa bắt tay vào làm phần của mình thôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa thầy/cô và các bạn, em thật sự xin lỗi vì lần thuyết trình này em chuẩn bị chưa kỹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao, cứ trình bày bình thường thôi, nói xem vấn đề nằm ở đâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Em thu thập tài liệu ở giai đoạn đầu chưa được kỹ, nội dung còn thiếu nhiều chi tiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em chưa chuẩn bị và trau chuốt nội dung đầy đủ từ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn thẳng vào vấn đề như vậy là tốt rồi, lần sau chuẩn bị trước cho kỹ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, cảm ơn thầy/cô và các bạn đã thông cảm cho em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Thầy/cô ơi, phần kiến thức vừa giảng trên lớp em chưa hiểu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em chưa hiểu? Thầy/cô giảng lại cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là logic áp dụng công thức ấy ạ, em vẫn còn hơi mơ hồ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, để thầy/cô hệ thống lại ngắn gọn, em nghe kỹ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Dạ vâng, phiền thầy/cô giảng giải giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, không cần ngại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hết rồi ạ, cảm ơn thầy/cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Thầy/cô ơi, em muốn hỏi về quy định phòng thi cho kỳ thi cuối kỳ lần này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Có chỗ nào chưa rõ em cứ hỏi thẳng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Dạ cho em hỏi trong lúc thi có được mang theo giấy nháp và dụng cụ học tập riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát thống nhất mọi vật dụng cần thiết cho thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử thì có cần tháo ra cất riêng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải cất riêng theo quy định chung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Em nắm rõ hết các quy định rồi ạ, cảm ơn thầy/cô!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Thầy/cô ơi, em muốn xác nhận lại điểm cuối kỳ môn học của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể là vấn đề gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Em đã hoàn thành đầy đủ bài tập, điểm danh, thi cử bình thường, nhưng hệ thống lại hiện chưa có điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là hệ thống giáo vụ bị lỗi khi nhập liệu nên dữ liệu bị sai lệch đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo là do mình quên nộp bài tập nào đó, trong lòng thấy bất an quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em cứ yên tâm, thầy/cô sẽ đối chiếu hồ sơ thủ công và nhập lại điểm cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn thầy/cô nhiều lắm vì đã giúp em xử lý việc này!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道；复核结果统一公示，具备官方效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，今天来找您，是想正式提交本次期末试卷成绩复核申请。','lǎo shī nín hǎo， jīn tiān lái zhǎo nín， shì xiǎng zhèng shì tí jiāo běn cì qī mò shì juàn chéng jì fù hé shēn qǐng。','Thầy/cô ơi, hôm nay em đến gặp là muốn chính thức nộp đơn xin phúc khảo điểm bài thi cuối kỳ lần này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'先坐，我先跟你确认，你清楚学校成绩复核的具体范围和规则吗？','xiān zuò， wǒ xiān gēn nǐ què rèn， nǐ qīng chǔ xué xiào chéng jì fù hé de jù tǐ fàn wéi hé guī zé ma？','Em ngồi đi đã, thầy/cô hỏi trước, em có nắm rõ phạm vi và quy định phúc khảo điểm của trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'只听说可以核对卷面总分统计，不能重新评判答题内容，细节了解不多。','zhǐ tīng shuō kě yǐ hé duì juàn miàn zǒng fēn tǒng jì， bù néng chóng xīn píng pàn dá tí nèi róng， xì jié liǎo jiě bù duō。','Em chỉ nghe nói là được đối chiếu lại tổng điểm trên bài thi, chứ không được chấm lại nội dung bài làm, còn chi tiết thì em chưa rõ lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'没错，复核仅检查每道小题得分相加是否计算错误，不会更改主观题打分。','méi cuò， fù hé jǐn jiǎn chá měi dào xiǎo tí dé fēn xiāng jiā shì fǒu jì suàn cuò wù， bú huì gēng gǎi zhǔ guān tí dǎ fēn。','Đúng vậy, phúc khảo chỉ kiểm tra xem tổng điểm cộng từ các câu nhỏ có tính sai không, chứ không thay đổi điểm chấm các câu tự luận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'我自己对照参考答案预估的分数，和最终系统录入成绩差距很大，心里比较疑惑。','wǒ zì jǐ duì zhào cān kǎo dá àn yù gū de fēn shù， hé zuì zhōng xì tǒng lù rù chéng jì chā jù hěn dà， xīn lǐ bǐ jiào yí huò。','Em tự đối chiếu với đáp án tham khảo rồi ước tính điểm, thấy chênh lệch khá nhiều so với điểm hệ thống ghi cuối cùng, nên trong lòng em khá thắc mắc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'我理解你的顾虑，我可以协助你向学院教学办提交官方书面复核申请。','wǒ lǐ jiě nǐ de gù lǜ， wǒ kě yǐ xié zhù nǐ xiàng xué yuàn jiào xué bàn tí jiāo guān fāng shū miàn fù hé shēn qǐng。','Thầy/cô hiểu băn khoăn của em, thầy/cô có thể hỗ trợ em nộp đơn phúc khảo chính thức bằng văn bản lên phòng đào tạo của khoa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'提交申请的时候，需要附带什么证明材料，填写专用表格吗？','tí jiāo shēn qǐng de shí hòu， xū yào fù dài shén me zhèng míng cái liào， tián xiě zhuān yòng biǎo gé ma？','Vậy khi nộp đơn thì em cần đính kèm giấy tờ gì, hay điền vào mẫu đơn riêng ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_08','V319','老师',8,'我这边给你打印统一的复核申请表，填写姓名、学号、科目和申请理由即可。','wǒ zhè biān gěi nǐ dǎ yìn tǒng yī de fù hé shēn qǐng biǎo， tián xiě xìng míng、 xué hào、 kē mù hé shēn qǐng lǐ yóu jí kě。','Thầy/cô sẽ in cho em mẫu đơn phúc khảo chung, em chỉ cần điền họ tên, mã số sinh viên, môn học và lý do xin phúc khảo là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_09','V319','阮明',9,'请问提交申请表之后，大概多久可以出具最终复核结果呢？','qǐng wèn tí jiāo shēn qǐng biǎo zhī hòu， dà gài duō jiǔ kě yǐ chū jù zuì zhōng fù hé jié guǒ ne？','Cho em hỏi sau khi nộp đơn thì khoảng bao lâu sẽ có kết quả phúc khảo cuối cùng ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_10','V319','老师',10,'学院统一收集申请，三个工作日内完成卷面核对并公示修正后的成绩。','xué yuàn tǒng yī shōu jí shēn qǐng， sān gè gōng zuò rì nèi wán chéng juàn miàn hé duì bìng gōng shì xiū zhèng hòu de chéng jì。','Khoa sẽ thu thập đơn thống nhất, trong vòng ba ngày làm việc sẽ hoàn tất đối chiếu bài thi và công bố điểm đã điều chỉnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_11','V319','阮明',11,'如果复核后分数有调整，系统成绩会同步更新对吧？','rú guǒ fù hé hòu fēn shù yǒu tiáo zhěng， xì tǒng chéng jì huì tóng bù gēng xīn duì ba？','Nếu sau phúc khảo điểm có thay đổi thì hệ thống cũng sẽ tự động cập nhật đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_12','V319','老师',12,'是的，核对出计算失误会直接修改教务系统内你的期末分数。','shì de， hé duì chū jì suàn shī wù huì zhí jiē xiū gǎi jiào wù xì tǒng nèi nǐ de qī mò fēn shù。','Đúng vậy, nếu phát hiện tính sai thì sẽ chỉnh sửa trực tiếp điểm cuối kỳ của em trong hệ thống giáo vụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_13','V319','阮明',13,'我现在填写申请表，麻烦老师帮忙转交教学办。','wǒ xiàn zài tián xiě shēn qǐng biǎo， má fán lǎo shī bāng máng zhuǎn jiāo jiào xué bàn。','Vậy giờ em điền đơn luôn, phiền thầy/cô chuyển giúp em lên phòng đào tạo ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_14','V319','老师',14,'放心，流程我全程跟进，有结果第一时间通知你。','fàng xīn， liú chéng wǒ quán chéng gēn jìn， yǒu jié guǒ dì yī shí jiān tōng zhī nǐ。','Yên tâm đi, thầy/cô sẽ theo sát toàn bộ quy trình, có kết quả sẽ báo cho em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_15','V319','阮明',15,'辛苦老师费心办理，非常感谢！','xīn kǔ lǎo shī fèi xīn bàn lǐ， fēi cháng gǎn xiè！','Cảm ơn thầy/cô đã vất vả lo liệu việc này giúp em, em cảm kích lắm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ ơi, hôm qua tớ xin nghỉ nên lỡ mất buổi học, cho tớ mượn vở ghi chép của cậu được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Đương nhiên được, tớ ghi khá chi tiết đó, chỗ trọng tâm khó đều đánh dấu hết rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Tuyệt quá, tớ đúng lúc bị lỡ mất phần kiến thức quan trọng nhất luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ từ từ xem, xem xong trả lại tớ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều lắm, chỗ nào không hiểu tớ hỏi cậu tiếp nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không vấn đề gì, bạn bè với nhau vốn dĩ phải giúp đỡ nhau mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng thật đấy!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào bạn, mình muốn đặt lịch khám nội khoa hôm nay trên ứng dụng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Dạ chào anh/chị, anh/chị muốn đặt số khám thường hay số khám chuyên gia ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Số khám thường là được rồi, mình chỉ hơi chóng mặt và mệt mỏi thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Dạ em rất xin lỗi, số khám nội khoa thường hôm nay đã kín hết rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn số trống không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn nhiều số trống ạ, em có thể hướng dẫn anh/chị đặt lịch.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Được, phiền bạn hướng dẫn mình thao tác nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào chị, dạo này em hay bị chóng mặt, ngủ không ngon, vậy em nên khám khoa gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Triệu chứng của em thì khám khoa nội thần kinh là hợp lý nhất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy chị đăng ký giúp em suất khám thường chiều nay nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được rồi, em thanh toán bằng bảo hiểm y tế hay tự trả phí ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Em dùng bảo hiểm y tế sinh viên để thanh toán ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Em đã đăng ký thành công rồi, mời em lên phòng khám tầng hai chờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Dạ vâng, em cảm ơn chị nhiều!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Bác sĩ ơi, mấy ngày nay em cứ bị chóng mặt với người mệt rũ suốt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Là chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng thôi ạ, nhất là buổi tối, với lại em còn hay mất ngủ, không ngủ được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Em có bị sốt, buồn nôn hay khó chịu gì khác không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Không ạ, chỉ có mỗi hai triệu chứng chóng mặt với mệt mỏi thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Được rồi, bác sĩ hiểu sơ bộ rồi, để bác sĩ khám qua cho em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Dạ vâng, phiền bác sĩ rồi ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Thưa bác sĩ, tôi cần báo trước với bác sĩ về tiền sử dị ứng thuốc của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Được, vậy cụ thể anh dị ứng với loại thuốc nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Tôi dị ứng với nhóm thuốc penicillin, tuyệt đối không được dùng loại này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Tôi đã ghi lại rồi, khi kê đơn sẽ tránh hoàn toàn loại thuốc gây dị ứng đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây tôi từng bị phản ứng dị ứng rất nặng nên tôi đặc biệt thận trọng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Tôi hiểu, an toàn dùng thuốc là ưu tiên hàng đầu, anh cứ yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Cảm ơn bác sĩ đã cẩn thận và chu đáo!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào chị, đây là đơn thuốc của em, phiền chị lấy giúp em thuốc với ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Được rồi, em chờ chút, chị kiểm tra lại thông tin thuốc đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Dạ không sao ạ, mấy loại thuốc này uống cụ thể thế nào vậy chị?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều uống ngày ba lần, sau ăn với nước ấm, trên tờ hướng dẫn cũng có ghi rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Vậy có cần bảo quản lạnh không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần đâu, để nơi thoáng mát, tránh ánh sáng là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Dạ em hiểu rồi, em cảm ơn chị nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào chị, em muốn hỏi mấy loại thuốc bác sĩ kê cho em có được bảo hiểm y tế thanh toán không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để chị tra giúp em danh mục thuốc bảo hiểm y tế nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi này, trong đó có hai loại thuốc cơ bản được thanh toán, còn một loại thuốc nhập khẩu thì không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, tức là thuốc nhập khẩu em phải tự trả toàn bộ phải không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng vậy, thuốc đặc trị nhập khẩu không nằm trong phạm vi bảo hiểm y tế chi trả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_06','V326','阮明',6,'我了解了，那麻烦你分开结算吧。','wǒ liǎo jiě le， nà má fán nǐ fēn kāi jié suàn ba。','Dạ em hiểu rồi, vậy phiền chị tách riêng ra khi thanh toán giúp em nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_07','V326','工作人员',7,'没问题，我帮你区分清楚。','méi wèn tí， wǒ bāng nǐ qū fēn qīng chǔ。','Không vấn đề gì, chị sẽ tách rõ ràng cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT327','S109','Đặt lịch tái khám',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V327','SIT327','P1','suon_se','ban_chinh_thuc',NULL,'慢性病、短期病症恢复都需要复诊，携带既往病历是医院常规要求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_01','V327','阮明',1,'你好，我想预约下周的复诊门诊。','nǐ hǎo， wǒ xiǎng yù yuē xià zhōu de fù zhěn mén zhěn。','Chào chị, em muốn đặt lịch khám tái khám tuần sau ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_02','V327','工作人员',2,'可以的，你想预约周几的时间段？','kě yǐ de， nǐ xiǎng yù yuē zhōu jǐ de shí jiān duàn？','Được chứ, em muốn đặt vào khung giờ nào, thứ mấy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_03','V327','阮明',3,'下周二下午吧，我下午没有课程安排。','xià zhōu èr xià wǔ ba， wǒ xià wǔ méi yǒu kè chéng ān pái。','Chiều thứ ba tuần sau ạ, chiều đó em không có lịch học.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_04','V327','工作人员',4,'好的，已经为你预约成功。','hǎo de， yǐ jīng wèi nǐ yù yuē chéng gōng。','Được rồi, chị đã đặt lịch thành công cho em rồi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_05','V327','阮明',5,'复诊的时候需要带这次的病历本吗？','fù zhěn de shí hòu xū yào dài zhè cì de bìng lì běn ma？','Khi tái khám em có cần mang theo sổ bệnh án lần này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_06','V327','工作人员',6,'需要的，务必携带方便医生对比恢复情况。','xū yào de， wù bì xié dài fāng biàn yī shēng duì bǐ huī fù qíng kuàng。','Cần chứ, nhất định phải mang theo để bác sĩ tiện so sánh tình hình hồi phục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L327_07','V327','阮明',7,'好的，我会妥善保管，谢谢你！','hǎo de， wǒ huì tuǒ shàn bǎo guǎn， xiè xiè nǐ！','Dạ vâng, em sẽ giữ cẩn thận, cảm ơn chị nhé!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT328','S109','Xin giấy chứng nhận nghỉ bệnh cho trường',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V328','SIT328','P1','suon_se','chinh_thuc',NULL,'国内高校只认可医院机打正规病假证明，手写证明无效，是统一考勤制度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_01','V328','阮明',1,'医生您好，我身体不适需要请假，麻烦您开具一张病假证明。','yī shēng nín hǎo， wǒ shēn tǐ bù shì xū yào qǐng jià， má fán nín kāi jù yī zhāng bìng jià zhèng míng。','Thưa bác sĩ, tôi thấy trong người không khỏe cần xin nghỉ, phiền bác sĩ viết giúp tôi một giấy chứng nhận nghỉ bệnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_02','V328','医生',2,'没问题，你需要请假休养几天？','méi wèn tí， nǐ xū yào qǐng jià xiū yǎng jǐ tiān？','Không vấn đề gì, anh cần nghỉ dưỡng bao nhiêu ngày?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_03','V328','阮明',3,'我身体比较虚弱，想请假两天调整状态。','wǒ shēn tǐ bǐ jiào xū ruò， xiǎng qǐng jià liǎng tiān tiáo zhěng zhuàng tài。','Tôi thấy trong người khá yếu nên muốn xin nghỉ hai ngày để điều chỉnh lại sức khỏe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_04','V328','医生',4,'可以，我给你开具正规机打病假证明。','kě yǐ， wǒ gěi nǐ kāi jù zhèng guī jī dǎ bìng jià zhèng míng。','Được, tôi sẽ viết cho anh giấy chứng nhận nghỉ bệnh in chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_05','V328','阮明',5,'证明上会标注就诊时间和请假时长对吧？','zhèng míng shàng huì biāo zhù jiù zhěn shí jiān hé qǐng jià shí cháng duì ba？','Trên giấy có ghi rõ thời gian khám và số ngày nghỉ đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_06','V328','医生',6,'是的，信息齐全，学校可以直接认可。','shì de， xìn xī qí quán， xué xiào kě yǐ zhí jiē rèn kě。','Đúng vậy, thông tin đầy đủ, nhà trường có thể công nhận trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L328_07','V328','阮明',7,'太感谢医生了！','tài gǎn xiè yī shēng le！','Tôi cảm ơn bác sĩ nhiều lắm!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT329','S111','Tự giới thiệu trong buổi sinh hoạt đầu năm',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V329','SIT329','P1','suon_se','ban_chinh_thuc',NULL,'新生自我介绍简洁谦逊即可，"多多指教"是国内年轻人社交最常用的礼貌用语。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_01','V329','阮明',1,'大家好，我是阮明，一名来自越南的留学生，今年22岁。','dà jiā hǎo， wǒ shì ruǎn míng， yī míng lái zì yuè nán de liú xué shēng， jīn nián 22 suì。','Chào mọi người, mình là Nguyễn Minh, du học sinh đến từ Việt Nam, năm nay mình 22 tuổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_02','V329','阮明',2,'目前就读于汉语言文学专业，非常开心加入这个集体。','mù qián jiù dú yú hàn yǔ yán wén xué zhuān yè， fēi cháng kāi xīn jiā rù zhè ge jí tǐ。','Hiện tại mình đang học chuyên ngành Ngôn ngữ và Văn học Trung Quốc, rất vui khi được gia nhập tập thể mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_03','V329','阮明',3,'平时我喜欢读书和慢跑，性格比较随和开朗。','píng shí wǒ xǐ huān dú shū hé màn pǎo， xìng gé bǐ jiào suí hé kāi lǎng。','Bình thường mình thích đọc sách và chạy bộ, tính cách khá dễ gần và cởi mở.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_04','V329','阮明',4,'我刚来中国，对这边的学习和生活还在适应中。','wǒ gāng lái zhōng guó， duì zhè biān de xué xí hé shēng huó hái zài shì yìng zhōng。','Mình mới sang Trung Quốc nên vẫn đang dần thích nghi với việc học và cuộc sống ở đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_05','V329','阮明',5,'往后希望可以和各位同学友好相处，互相学习、多多指教。','wǎng hòu xī wàng kě yǐ hé gè wèi tóng xué yǒu hǎo xiāng chǔ， hù xiāng xué xí、 duō duō zhǐ jiào。','Sau này mong được hòa đồng với các bạn, cùng nhau học hỏi, mong mọi người chỉ bảo thêm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_06','V329','辅导员',6,'欢迎阮明加入我们的大家庭！','huān yíng ruǎn míng jiā rù wǒ men de dà jiā tíng！','Chào mừng Nguyễn Minh gia nhập đại gia đình của chúng ta!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L329_07','V329','阮明',7,'谢谢大家！','xiè xiè dà jiā！','Em cảm ơn mọi người!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT330','S111','Hỏi thông tin liên hệ để giữ kết nối',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V330','SIT330','P1','suon_se','tuy_y',NULL,'微信是国内学生唯一主流沟通工具，学习通知、日常交友、小组协作均依托微信完成。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_01','V330','阮明',1,'今天认识你真的太开心了！我们可以加个微信吗？','jīn tiān rèn shí nǐ zhēn de tài kāi xīn le！ wǒ men kě yǐ jiā gè wēi xìn ma？','Hôm nay quen được cậu vui thật đấy! Tụi mình kết bạn Wechat nhé?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_02','V330','林溪',2,'当然可以呀，以后我们就是同班同学了。','dāng rán kě yǐ ya， yǐ hòu wǒ men jiù shì tóng bān tóng xué le。','Đương nhiên là được rồi, sau này tụi mình là bạn cùng lớp mà.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_03','V330','阮明',3,'太好了，我刚来这边，以后还要多向你请教呢。','tài hǎo le， wǒ gāng lái zhè biān， yǐ hòu hái yào duō xiàng nǐ qǐng jiào ne。','Tuyệt quá, mình mới đến đây, sau này còn phải nhờ cậu chỉ bảo nhiều nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_04','V330','林溪',4,'不用客气，我们互相帮忙、共同进步。','bù yòng kè qì， wǒ men hù xiāng bāng máng、 gòng tóng jìn bù。','Khỏi khách sáo, tụi mình giúp đỡ nhau cùng tiến bộ mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_05','V330','阮明',5,'那我扫你的二维码加好友哈。','nà wǒ sǎo nǐ de èr wéi mǎ jiā hǎo yǒu hā。','Vậy để mình quét mã QR kết bạn với cậu nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_06','V330','林溪',6,'好嘞，以后常联系，有空一起学习！','hǎo lei， yǐ hòu cháng lián xì， yǒu kòng yì qǐ xué xí！','Ok đó, sau này liên lạc thường xuyên nhé, rảnh thì học chung!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L330_07','V330','阮明',7,'太好啦，谢谢你！','tài hǎo la， xiè xiè nǐ！','Tuyệt vời, cảm ơn cậu nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT331','S112','Mời bạn cùng lớp đi ăn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V331','SIT331','P1','suon_se','tuy_y',NULL,'中国大学生下课常结伴去食堂就餐，主动邀约同学吃饭是很常见的社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_01','V331','阮明',1,'下课啦，等下要不要一起去食堂吃饭啊？','xià kè la， děng xià yào bù yào yì qǐ qù shí táng chī fàn a？','Tan học rồi, lát nữa cùng đi ăn ở căng tin không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_02','V331','王浩',2,'可以呀，我正愁一个人吃饭没意思呢。','kě yǐ ya， wǒ zhèng chóu yí gè rén chī fàn méi yì si ne。','Được chứ, mình đang buồn vì ăn một mình chán muốn chết đây.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_03','V331','阮明',3,'食堂今天有米线，听说味道很不错的。','shí táng jīn tiān yǒu mǐ xiàn， tīng shuō wèi dào hěn bú cuò de。','Căng tin hôm nay có bún, nghe nói ngon lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_04','V331','王浩',4,'刚好我也想吃米线，咱们现在就走吧。','gāng hǎo wǒ yě xiǎng chī mǐ xiàn， zán men xiàn zài jiù zǒu ba。','Đúng lúc mình cũng thèm ăn bún, đi luôn bây giờ nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_05','V331','阮明',5,'行，那我收拾一下书本，马上就好。','xíng， nà wǒ shōu shí yī xià shū běn， mǎ shàng jiù hǎo。','Được, để mình thu dọn sách vở tí, xong ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_06','V331','王浩',6,'没事，我在教室门口等你就行啦。','méi shì， wǒ zài jiào shì mén kǒu děng nǐ jiù xíng la。','Không sao, mình đợi cậu ở cửa lớp là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L331_07','V331','阮明',7,'太感谢啦，有同学一起吃饭热闹多了。','tài gǎn xiè la， yǒu tóng xué yì qǐ chī fàn rè nào duō le。','Cảm ơn nhiều nha, có bạn cùng ăn vui hơn hẳn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT332','S112','Từ chối lời mời một cách lịch sự',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V332','SIT332','P1','suon_se','tuy_y',NULL,'拒绝他人邀约时，中国人习惯说明合理理由并主动提出下次赴约，显得有礼貌不扫兴。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_01','V332','林晓',1,'晚上我们宿舍一起去校外吃火锅，你也来吧？','wǎn shàng wǒ men sù shè yì qǐ qù xiào wài chī huǒ guō， nǐ yě lái ba？','Tối nay phòng ký túc mình rủ nhau ra ngoài ăn lẩu, cậu cũng đi luôn nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_02','V332','阮明',2,'真的很谢谢你邀请我，不过我今晚不行呢。','zhēn de hěn xiè xiè nǐ yāo qǐng wǒ， bù guò wǒ jīn wǎn bù xíng ne。','Thật sự cảm ơn cậu đã rủ, nhưng tối nay mình không đi được rồi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_03','V332','林晓',3,'怎么啦，是有别的安排吗？','zěn me la， shì yǒu bié de ān pái ma？','Sao vậy, có việc gì khác à?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_04','V332','阮明',4,'我要完成一篇汉语作文，明天就得提交的。','wǒ yào wán chéng yī piān hàn yǔ zuò wén， míng tiān jiù dé tí jiāo de。','Mình phải hoàn thành một bài văn tiếng Trung, mai phải nộp rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_05','V332','林晓',5,'原来是这样，学习要紧，那下次再约吧。','yuán lái shì zhè yàng， xué xí yào jǐn， nà xià cì zài yuē ba。','Ra là vậy, học hành quan trọng hơn, vậy lần sau hẹn lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_06','V332','阮明',6,'好，下次我一定主动找你们，实在抱歉啦。','hǎo， xià cì wǒ yí dìng zhǔ dòng zhǎo nǐ men， shí zài bào qiàn la。','Được, lần sau mình nhất định chủ động rủ mọi người, thật ngại quá.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L332_07','V332','林晓',7,'没关系，学习完早点休息。','méi guān xì， xué xí wán zǎo diǎn xiū xī。','Không sao đâu, học xong nhớ nghỉ ngơi sớm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT333','S112','Xin lỗi vì đến muộn buổi hẹn',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V333','SIT333','P1','twist','ban_chinh_thuc',NULL,'与人线下见面迟到，中国人会主动诚恳道歉，还会主动提出买单、请客作为补偿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_01','V333','阮明',1,'实在对不起，我路上堵车，迟到二十分钟了。','shí zài duì bù qǐ， wǒ lù shàng dǔ chē， chí dào èr shí fēn zhōng le。','Thật sự xin lỗi, mình bị kẹt xe nên trễ hai mươi phút rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_02','V333','陈悦',2,'没事，我也刚到一会儿，不用这么愧疚。','méi shì， wǒ yě gāng dào yī huì er， bù yòng zhè me kuì jiù。','Không sao, mình cũng vừa mới đến thôi, đừng áy náy quá vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_03','V333','阮明',3,'都怪我没提前出门，让你在这里干等啊。','dōu guài wǒ méi tí qián chū mén， ràng nǐ zài zhè lǐ gàn děng a。','Đều tại mình không ra khỏi nhà sớm hơn, để cậu phải đợi không vậy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_04','V333','陈悦',4,'还好，这家咖啡店座位挺多，我先点了两杯饮品。','hái hǎo， zhè jiā kā fēi diàn zuò wèi tǐng duō， wǒ xiān diǎn le liǎng bēi yǐn pǐn。','May mà quán cà phê này khá nhiều chỗ ngồi, mình gọi trước hai ly rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_05','V333','阮明',5,'太不好意思了，这杯饮品我来付钱吧。','tài bù hǎo yì sī le， zhè bēi yǐn pǐn wǒ lái fù qián ba。','Ngại quá, để mình trả tiền ly nước này nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_06','V333','陈悦',6,'不用啦，下次见面你请我就可以咯。','bù yòng la， xià cì jiàn miàn nǐ qǐng wǒ jiù kě yǐ gē。','Khỏi cần đâu, lần sau gặp lại cậu mời mình là được rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L333_07','V333','阮明',7,'好，下次我一定提前半小时出门，绝不迟到。','hǎo， xià cì wǒ yí dìng tí qián bàn xiǎo shí chū mén， jué bù chí dào。','Được, lần sau mình nhất định ra khỏi nhà sớm nửa tiếng, tuyệt đối không trễ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT334','S112','Cảm ơn khi được giúp đỡ đặc biệt',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V334','SIT334','P1','suon_se','ban_chinh_thuc',NULL,'得到他人较大帮助后，中国人常会赠送小零食、小礼物表达谢意，不会只口头道谢。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_01','V334','阮明',1,'班长，这次真的太谢谢你帮我补办签证材料了。','bān zhǎng， zhè cì zhēn de tài xiè xiè nǐ bāng wǒ bǔ bàn qiān zhèng cái liào le。','Lớp trưởng ơi, lần này thật sự cảm ơn cậu đã giúp mình làm lại giấy tờ visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_02','V334','周宇',2,'小事而已，留学生办理手续本来就麻烦嘛。','xiǎo shì ér yǐ， liú xué shēng bàn lǐ shǒu xù běn lái jiù má fán ma。','Chuyện nhỏ thôi mà, du học sinh làm thủ tục vốn dĩ đã phiền phức rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_03','V334','阮明',3,'要是没有你带路讲解，我肯定跑好多趟。','yào shì méi yǒu nǐ dài lù jiǎng jiě， wǒ kěn dìng pǎo hǎo duō tàng。','Nếu không có cậu dẫn đường giải thích, chắc mình phải chạy tới chạy lui bao nhiêu lần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_04','V334','周宇',4,'不用放在心上，班里同学互相帮忙是应该的。','bù yòng fàng zài xīn shàng， bān lǐ tóng xué hù xiāng bāng máng shì yīng gāi de。','Đừng để bụng làm gì, bạn cùng lớp giúp đỡ nhau là chuyện nên làm mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_05','V334','阮明',5,'下周我买了家乡小零食，带给你尝尝吧。','xià zhōu wǒ mǎi le jiā xiāng xiǎo líng shí， dài gěi nǐ cháng cháng ba。','Tuần sau mình mua ít đồ ăn vặt quê nhà, mang đến cho cậu thử nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_06','V334','周宇',6,'不用这么客气，能帮上忙我也很高兴。','bù yòng zhè me kè qì， néng bāng shàng máng wǒ yě hěn gāo xìng。','Không cần khách sáo vậy đâu, giúp được cậu mình cũng thấy vui rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L334_07','V334','阮明',7,'一定要收下，不然我心里过意不去呢。','yí dìng yào shōu xià， bù rán wǒ xīn lǐ guò yì bù qù ne。','Cậu phải nhận đấy, không thì mình áy náy trong lòng lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT335','S113','Hỏi sở thích để tìm điểm chung với bạn mới',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V335','SIT335','P1','suon_se','tuy_y',NULL,'初次认识的年轻人会通过爱好聊天，找到共同兴趣能快速拉近彼此距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_01','V335','阮明',1,'课余时间你平时都喜欢做什么呀？','kè yú shí jiān nǐ píng shí dōu xǐ huān zuò shén me ya？','Bình thường ngoài giờ học cậu hay thích làm gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_02','V335','苏雯',2,'我有空就会追剧、出门爬山，你呢？','wǒ yǒu kòng jiù huì zhuī jù、 chū mén pá shān， nǐ ne？','Mình rảnh thì hay xem phim, đi leo núi, còn cậu thì sao?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_03','V335','阮明',3,'我也很喜欢爬山，只是刚来还不熟悉周边路线。','wǒ yě hěn xǐ huān pá shān， zhǐ shì gāng lái hái bù shú xī zhōu biān lù xiàn。','Mình cũng rất thích leo núi, chỉ là mới đến đây nên chưa rành đường xá xung quanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_04','V335','苏雯',4,'学校附近有一座小山，周末可以一起去的。','xué xiào fù jìn yǒu yī zuò xiǎo shān， zhōu mò kě yǐ yì qǐ qù de。','Gần trường có một ngọn núi nhỏ, cuối tuần có thể đi chung đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_05','V335','阮明',5,'太棒了，我还担心找不到同好呢。','tài bàng le， wǒ hái dān xīn zhǎo bú dào tóng hào ne。','Tuyệt quá, mình còn đang lo không tìm được ai hợp gu nữa chứ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_06','V335','苏雯',6,'那我们加个微信，周末约着一起出发吧。','nà wǒ men jiā gè wēi xìn， zhōu mò yuē zhe yì qǐ chū fā ba。','Vậy tụi mình kết bạn Wechat, cuối tuần hẹn nhau cùng đi nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L335_07','V335','阮明',7,'好呀，终于找到一样爱好的朋友啦。','hǎo ya， zhōng yú zhǎo dào yī yàng ài hào de péng yǒu la。','Được đó, cuối cùng cũng tìm được người bạn cùng sở thích rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT336','S114','Đăng ký tham gia câu lạc bộ sinh viên',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V336','SIT336','P1','twist','ban_chinh_thuc',NULL,'国内高校社团统一在开学招新，多数社团有活动人数限制，需要提前登记报名。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_01','V336','阮明',1,'学姐你好，我想报名加入咱们汉服社团可以吗？','xué jiě nǐ hǎo， wǒ xiǎng bào míng jiā rù zán men hàn fú shè tuán kě yǐ ma？','Chào chị, em muốn đăng ký tham gia câu lạc bộ Hán phục của tụi mình có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_02','V336','学姐',2,'当然可以，先填一张信息登记表哦。','dāng rán kě yǐ， xiān tián yī zhāng xìn xī dēng jì biǎo ó。','Được chứ, em điền vào một tờ đăng ký thông tin trước đã nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_03','V336','阮明',3,'好的，我平时很喜欢中国传统服饰和文化。','hǎo de， wǒ píng shí hěn xǐ huān zhōng guó chuán tǒng fú shì hé wén huà。','Dạ được, em rất thích trang phục và văn hóa truyền thống Trung Quốc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_04','V336','学姐',4,'咱们每周有线下活动，不过本周活动名额满了。','zán men měi zhōu yǒu xiàn xià huó dòng， bù guò běn zhōu huó dòng míng é mǎn le。','Tụi chị mỗi tuần có hoạt động ngoại tuyến, nhưng tuần này hết chỗ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_05','V336','阮明',5,'啊？那我下周能正常参与活动吗？','a？ nà wǒ xià zhōu néng zhèng cháng cān yù huó dòng ma？','Ơ? Vậy tuần sau em có thể tham gia bình thường không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_06','V336','学姐',6,'没问题，下周名额会重新开放，记得准时来。','méi wèn tí， xià zhōu míng é huì chóng xīn kāi fàng， jì de zhǔn shí lái。','Không vấn đề gì, tuần sau sẽ mở lại chỗ trống, nhớ đến đúng giờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L336_07','V336','阮明',7,'好，我会记好时间，麻烦学姐啦。','hǎo， wǒ huì jì hǎo shí jiān， má fán xué jiě la。','Dạ, em sẽ ghi nhớ thời gian, phiền chị nhiều rồi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT337','S112','Giải thích khi hiểu nhầm ý của bạn',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V337','SIT337','P1','suon_se','ban_chinh_thuc',NULL,'朋友产生隔阂后，中国人会主动沟通解释，厘清误会后不会一直记在心里。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_01','V337','阮明',1,'昨天那件事你是不是误会我了，我跟你解释一下吧。','zuó tiān nà jiàn shì nǐ shì bú shì wù huì wǒ le， wǒ gēn nǐ jiě shì yī xià ba。','Chuyện hôm qua chắc cậu hiểu lầm mình rồi, để mình giải thích nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_02','V337','李然',2,'我昨天确实有点生气，你说说是什么情况。','wǒ zuó tiān què shí yǒu diǎn shēng qì， nǐ shuō shuō shì shén me qíng kuàng。','Hôm qua mình đúng là có hơi giận, cậu nói xem là chuyện gì vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_03','V337','阮明',3,'我不是故意放你鸽子，是老师临时留我补作业呢。','wǒ bú shì gù yì fàng nǐ gē zi， shì lǎo shī lín shí liú wǒ bǔ zuò yè ne。','Mình không cố ý cho cậu leo cây đâu, là thầy giữ mình lại làm bù bài tập đột xuất đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_04','V337','李然',4,'原来是这样，我还以为你不想跟我出门。','yuán lái shì zhè yàng， wǒ hái yǐ wéi nǐ bù xiǎng gēn wǒ chū mén。','Ra là vậy, mình còn tưởng cậu không muốn đi chơi với mình chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_05','V337','阮明',5,'怎么会，我一直很期待和你逛街的。','zěn me huì， wǒ yì zhí hěn qī dài hé nǐ guàng jiē de。','Sao lại thế được, mình luôn mong được đi dạo phố với cậu mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_06','V337','李然',6,'行，我明白啦，这件事就翻篇不提了。','xíng， wǒ míng bái la， zhè jiàn shì jiù fān piān bù tí le。','Được rồi, mình hiểu rồi, chuyện này coi như bỏ qua không nhắc lại nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L337_07','V337','阮明',7,'太好了，下次出门我提前跟你确认时间。','tài hǎo le， xià cì chū mén wǒ tí qián gēn nǐ què rèn shí jiān。','Tuyệt quá, lần sau đi đâu mình sẽ báo trước giờ giấc với cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT338','S112','Chúc mừng sinh nhật bạn cùng phòng',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V338','SIT338','P1','suon_se','tuy_y',NULL,'大学生宿舍室友常会合伙买蛋糕、礼物一起过生日，是宿舍常见暖心活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_01','V338','阮明',1,'张明，生日快乐！快拆开我们准备的蛋糕吧。','zhāng míng， shēng rì kuài lè！ kuài chāi kāi wǒ men zhǔn bèi de dàn gāo ba。','Trương Minh, chúc mừng sinh nhật nha! Mở cái bánh kem tụi mình chuẩn bị ra đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_02','V338','张明',2,'哇，你们居然还记得我的生日，太惊喜了。','wa， nǐ men jū rán hái jì de wǒ de shēng rì， tài jīng xǐ le。','Ồ, tụi cậu còn nhớ sinh nhật mình cơ à, bất ngờ quá đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_03','V338','阮明',3,'我们悄悄凑钱买的，还有小礼物送给你呢。','wǒ men qiāo qiāo còu qián mǎi de， hái yǒu xiǎo lǐ wù sòng gěi nǐ ne。','Tụi mình lén góp tiền mua đó, còn có quà nhỏ tặng cậu nữa nè.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_04','V338','张明',4,'真的不用这么破费，有你们陪伴就足够啦。','zhēn de bù yòng zhè me pò fèi， yǒu nǐ men péi bàn jiù zú gòu la。','Thật sự không cần tốn kém vậy đâu, có tụi cậu ở bên là đủ rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_05','V338','阮明',5,'室友之间不用客气，赶紧许愿吹蜡烛哦。','shì yǒu zhī jiān bù yòng kè qì， gǎn jǐn xǔ yuàn chuī là zhú ó。','Bạn cùng phòng với nhau khách sáo gì, mau ước nguyện rồi thổi nến đi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_06','V338','张明',6,'好，我许个愿，希望我们宿舍一直和睦。','hǎo， wǒ xǔ gè yuàn， xī wàng wǒ men sù shè yì zhí hé mù。','Được, mình ước nè, mong phòng mình lúc nào cũng hòa thuận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L338_07','V338','阮明',7,'一定会的，咱们切蛋糕一起分享！','yí dìng huì de， zán men qiè dàn gāo yì qǐ fēn xiǎng！','Chắc chắn rồi, giờ cắt bánh cùng ăn thôi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT339','S112','Hỏi mượn đồ dùng cá nhân từ bạn cùng lớp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V339','SIT339','P1','twist','tuy_y',NULL,'向他人借私人物品需要主动询问，用完及时归还，很多人会用小饮品、零食答谢对方。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_01','V339','阮明',1,'菲菲，能不能借你的笔记本电脑用半小时啊？','fēi fēi， néng bù néng jiè nǐ de bǐ jì běn diàn nǎo yòng bàn xiǎo shí a？','Phi Phi, cho mình mượn laptop dùng nửa tiếng được không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_02','V339','刘菲',2,'不好意思，我电脑拿去图书馆充电了嘛。','bù hǎo yì sī， wǒ diàn nǎo ná qù tú shū guǎn chōng diàn le ma。','Xin lỗi nha, máy tính mình đem ra thư viện sạc pin mất rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_03','V339','阮明',3,'这样啊，那你有多余的U盘借我拷贝文件吗？','zhè yàng a， nà nǐ yǒu duō yú de U pán jiè wǒ kǎo bèi wén jiàn ma？','Vậy à, thế cậu có USB dư cho mình mượn copy tài liệu không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_04','V339','刘菲',4,'这个可以，我包里刚好有一个全新的。','zhè ge kě yǐ， wǒ bāo lǐ gāng hǎo yǒu yí gè quán xīn de。','Cái này thì được, trong cặp mình vừa hay có một cái mới toanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_05','V339','阮明',5,'太感谢了，用完我马上还给你，绝不弄丢。','tài gǎn xiè le， yòng wán wǒ mǎ shàng huán gěi nǐ， jué bù nòng diū。','Cảm ơn nhiều lắm, dùng xong mình trả lại ngay, tuyệt đối không làm mất đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_06','V339','刘菲',6,'没关系，你慢慢用，不用着急归还。','méi guān xì， nǐ màn màn yòng， bù yòng zháo jí guī huán。','Không sao đâu, cậu cứ dùng thoải mái, không cần vội trả đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L339_07','V339','阮明',7,'好嘞，等下请你喝奶茶作为答谢。','hǎo lei， děng xià qǐng nǐ hē nǎi chá zuò wéi dá xiè。','Được rồi, lát nữa mời cậu uống trà sữa để cảm ơn nhé.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT340','S112','Đề nghị đổi lịch hẹn vì bận đột xuất',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V340','SIT340','P1','suon_se','ban_chinh_thuc',NULL,'临时无法赴约，中国人会第一时间告知对方，主动协商新时间，避免对方空等。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_01','V340','阮明',1,'实在抱歉，我们下午约好逛书店得改时间了。','shí zài bào qiàn， wǒ men xià wǔ yuē hǎo guàng shū diàn dé gǎi shí jiān le。','Thật sự xin lỗi, buổi chiều mình hẹn đi nhà sách với cậu phải đổi giờ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_02','V340','吴桐',2,'怎么了，是临时有突发事情吗？','zěn me le， shì lín shí yǒu tū fā shì qíng ma？','Sao vậy, có chuyện gì đột xuất à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_03','V340','阮明',3,'辅导员通知我去办公室提交留学材料呢。','fǔ dǎo yuán tōng zhī wǒ qù bàn gōng shì tí jiāo liú xué cái liào ne。','Cố vấn lớp báo mình lên văn phòng nộp hồ sơ du học đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_04','V340','吴桐',4,'没事，正事要紧，我们改到明天下午行吗？','méi shì， zhèng shì yào jǐn， wǒ men gǎi dào míng tiān xià wǔ xíng ma？','Không sao, việc chính quan trọng hơn, mình đổi sang chiều mai được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_05','V340','阮明',5,'明天下午我全天有空，完全没问题的。','míng tiān xià wǔ wǒ quán tiān yǒu kòng， wán quán méi wèn tí de。','Chiều mai cả buổi mình đều rảnh, hoàn toàn không vấn đề gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_06','V340','吴桐',6,'那就定明天三点，咱们校门口碰面吧。','nà jiù dìng míng tiān sān diǎn， zán men xiào mén kǒu pèng miàn ba。','Vậy hẹn ba giờ chiều mai nhé, tụi mình gặp nhau trước cổng trường.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L340_07','V340','阮明',7,'好，明天我提前十分钟在门口等你啦。','hǎo， míng tiān wǒ tí qián shí fēn zhōng zài mén kǒu děng nǐ la。','Được, mai mình sẽ đến sớm mười phút đợi cậu ở cổng nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT341','S114','Xin nghỉ một buổi sinh hoạt câu lạc bộ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V341','SIT341','P1','suon_se','ban_chinh_thuc',NULL,'学生社团有事无法参与活动，需要提前向负责人报备请假，不能无故缺席。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_01','V341','阮明',1,'学姐，我想跟你请假，本周的社团活动没法参加了。','xué jiě， wǒ xiǎng gēn nǐ qǐng jià， běn zhōu de shè tuán huó dòng méi fǎ cān jiā le。','Chị ơi, em muốn xin phép nghỉ, buổi sinh hoạt câu lạc bộ tuần này em không tham gia được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_02','V341','学姐',2,'可以，你是有什么重要的事情耽误了吗？','kě yǐ， nǐ shì yǒu shén me zhòng yào de shì qíng dān wù le ma？','Được, em có việc gì quan trọng nên bị vướng à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_03','V341','阮明',3,'下周有汉语考试，我需要全天在家复习嘛。','xià zhōu yǒu hàn yǔ kǎo shì， wǒ xū yào quán tiān zài jiā fù xí ma。','Tuần sau em có kỳ thi tiếng Trung, em cần ở nhà ôn tập cả ngày ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_04','V341','学姐',4,'原来是备考，学习优先，我帮你登记请假。','yuán lái shì bèi kǎo， xué xí yōu xiān， wǒ bāng nǐ dēng jì qǐng jià。','Thì ra là chuẩn bị thi, học hành ưu tiên trước, chị giúp em ghi phép nghỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_05','V341','阮明',5,'活动的任务我下周会主动补上，不会落下进度。','huó dòng de rèn wù wǒ xià zhōu huì zhǔ dòng bǔ shàng， bú huì là xià jìn dù。','Nhiệm vụ của hoạt động tuần sau em sẽ chủ động bù lại, không để tiến độ bị chậm đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_06','V341','学姐',6,'不用着急，等你考完试再来参与就行。','bù yòng zháo jí， děng nǐ kǎo wán shì zài lái cān yù jiù xíng。','Không cần gấp đâu, đợi em thi xong rồi tham gia lại cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L341_07','V341','阮明',7,'辛苦学姐体谅我啦，非常感谢。','xīn kǔ xué jiě tǐ liàng wǒ la， fēi cháng gǎn xiè。','Cảm ơn chị đã thông cảm cho em nhiều lắm ạ, em cảm ơn chị thật sự.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT342','S112','Khen món ăn bạn Trung Quốc nấu, đáp lại khi được khen',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V342','SIT342','P1','suon_se','tuy_y',NULL,'品尝他人亲手做的饭菜，中国人会真诚夸赞，还会互相邀约交换拿手菜。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_01','V342','阮明',1,'你做的番茄炒蛋也太好吃了吧，味道超正宗！','nǐ zuò de fān qié chǎo dàn yě tài hǎo chī le ba， wèi dào chāo zhèng zōng！','Món trứng xào cà chua cậu làm ngon quá trời, đúng vị chuẩn luôn!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_02','V342','小雅',2,'没有啦，就是简单家常菜，你喜欢就多吃点。','méi yǒu la， jiù shì jiǎn dān jiā cháng cài， nǐ xǐ huān jiù duō chī diǎn。','Có gì đâu, chỉ là món nhà làm đơn giản thôi, cậu thích thì ăn nhiều vào.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_03','V342','阮明',3,'比校外餐馆做得还香，你厨艺也太好了啊。','bǐ xiào wài cān guǎn zuò dé hái xiāng， nǐ chú yì yě tài hǎo le a。','Còn thơm hơn cả quán ăn ngoài trường ấy, tay nghề nấu ăn của cậu giỏi thật đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_04','V342','小雅',4,'谢谢你夸奖，下次我教你一起做呢。','xiè xiè nǐ kuā jiǎng， xià cì wǒ jiāo nǐ yì qǐ zuò ne。','Cảm ơn cậu khen, lần sau mình dạy cậu làm cùng nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_05','V342','阮明',5,'那太好了，我还怕自己学不会。','nà tài hǎo le， wǒ hái pà zì jǐ xué bú huì。','Vậy thì tốt quá, mình còn sợ mình không học được cơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_06','V342','小雅',6,'不难的，下次你做家乡菜给我尝尝吧。','bù nán de， xià cì nǐ zuò jiā xiāng cài gěi wǒ cháng cháng ba。','Không khó đâu, lần sau cậu nấu món quê hương cho mình nếm thử nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L342_07','V342','阮明',7,'没问题，下次我带食材过来，一定露一手！','méi wèn tí， xià cì wǒ dài shí cái guò lái， yí dìng lòu yī shǒu！','Được luôn, lần sau mình mang nguyên liệu qua, nhất định trổ tài cho xem!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT343','S115','Mua điện thoại mới, hỏi thông số',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V343','SIT343','P1','suon_se','tuy_y',NULL,'线下买电子产品，顾客可以自由询问全部参数，对比多款机型，店家不会催促下单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_01','V343','阮明',1,'你好，这款新款手机内存和电池容量是多少啊？','nǐ hǎo， zhè kuǎn xīn kuǎn shǒu jī nèi cún hé diàn chí róng liàng shì duō shǎo a？','Chào anh/chị, cái điện thoại mới này bộ nhớ với dung lượng pin bao nhiêu vậy ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_02','V343','销售员',2,'这款手机256G内存，电池续航一整天没问题。','zhè kuǎn shǒu jī 256G nèi cún， diàn chí xù háng yī zhěng tiān méi wèn tí。','Máy này bộ nhớ 256G, pin dùng cả ngày thoải mái không lo hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_03','V343','阮明',3,'拍照像素高吗？我平时很喜欢出门拍照呢。','pāi zhào xiàng sù gāo ma？ wǒ píng shí hěn xǐ huān chū mén pāi zhào ne。','Chụp ảnh độ phân giải cao không ạ? Em hay đi ra ngoài chụp ảnh lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_04','V343','销售员',4,'后置五千万像素，夜景拍摄效果特别清晰。','hòu zhì wǔ qiān wàn xiàng sù， yè jǐng pāi shè xiào guǒ tè bié qīng xī。','Camera sau 50 triệu điểm ảnh, chụp cảnh đêm rõ nét lắm luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_05','V343','阮明',5,'那处理器运行会不会卡顿，适合学习软件吗？','nà chǔ lǐ qì yùn xíng huì bú huì kǎ dùn， shì hé xué xí ruǎn jiàn ma？','Vậy chip xử lý chạy có bị giật lag không, có hợp để học phần mềm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_06','V343','销售员',6,'配置足够流畅运行各类软件，学生用很合适。','pèi zhì zú gòu liú chàng yùn xíng gè lèi ruǎn jiàn， xué shēng yòng hěn hé shì。','Cấu hình đủ sức chạy mượt mọi loại phần mềm, học sinh sinh viên dùng rất hợp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L343_07','V343','阮明',7,'行，那我再对比一下另一款，等下再来找你。','xíng， nà wǒ zài duì bǐ yī xià lìng yī kuǎn， děng xià zài lái zhǎo nǐ。','Vâng, để em so sánh thêm một mẫu nữa, lát em quay lại tìm anh/chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT344','S115','Mang điện thoại đi sửa màn hình vỡ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V344','SIT344','P1','twist','ban_chinh_thuc',NULL,'手机维修更换配件分原装和平价配件，店家会主动区分报价，配件缺货会告知顾客取机时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_01','V344','阮明',1,'师傅，我的手机屏幕摔碎了，能帮忙更换吗？','shī fù， wǒ de shǒu jī píng mù shuāi suì le， néng bāng máng gēng huàn ma？','Anh ơi, màn hình điện thoại em bị vỡ do rớt, anh đổi giúp em được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_02','V344','维修师傅',2,'可以，先看看型号，原装屏幕价格贵一点哈。','kě yǐ， xiān kàn kàn xíng hào， yuán zhuāng píng mù jià gé guì yì diǎn hā。','Được, để anh xem đời máy trước đã, màn zin giá hơi cao một chút nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_03','V344','阮明',3,'原装的大概多少钱，维修需要等多久呢？','yuán zhuāng de dà gài duō shǎo qián， wéi xiū xū yào děng duō jiǔ ne？','Màn zin khoảng bao nhiêu tiền vậy anh, sửa thì phải đợi lâu không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_04','V344','维修师傅',4,'三百五十元，可惜现在店里没有现货屏幕。','sān bǎi wǔ shí yuán， kě xī xiàn zài diàn lǐ méi yǒu xiàn huò píng mù。','Ba trăm năm mươi tệ, tiếc là bên tiệm hiện chưa có sẵn màn hình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_05','V344','阮明',5,'啊？那什么时候能到货，我手机每天都要用。','a？ nà shén me shí hòu néng dào huò， wǒ shǒu jī měi tiān dōu yào yòng。','Ơ? Vậy chừng nào có hàng vậy anh, điện thoại em ngày nào cũng phải dùng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_06','V344','维修师傅',6,'明天中午到货，你明天下午过来取就行。','míng tiān zhōng wǔ dào huò， nǐ míng tiān xià wǔ guò lái qǔ jiù xíng。','Trưa mai hàng về, em chiều mai qua lấy là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L344_07','V344','阮明',7,'好，我明天准时过来，麻烦师傅预留屏幕。','hǎo， wǒ míng tiān zhǔn shí guò lái， má fán shī fù yù liú píng mù。','Dạ, mai em qua đúng giờ, phiền anh giữ màn hình giúp em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT345','S116','Mua laptop, hỏi bảo hành',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V345','SIT345','P1','suon_se','ban_chinh_thuc',NULL,'国内数码产品均提供全国联保服务，门店会清晰告知保修时长、售后范围。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_01','V345','阮明',1,'这款笔记本适合留学生写论文、做PPT吗？','zhè kuǎn bǐ jì běn shì hé liú xué shēng xiě lùn wén、 zuò PPT ma？','Mẫu laptop này có hợp cho du học sinh viết luận văn, làm PPT không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_02','V345','导购',2,'完全适配，轻薄便携，性能足够日常学习的。','wán quán shì pèi， qīng bó biàn xié， xìng néng zú gòu rì cháng xué xí de。','Hoàn toàn hợp luôn, mỏng nhẹ dễ mang theo, hiệu năng đủ dùng cho việc học hằng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_03','V345','阮明',3,'那整机官方保修时长是多久呀？','nà zhěng jī guān fāng bǎo xiū shí cháng shì duō jiǔ ya？','Vậy thời hạn bảo hành chính hãng của cả máy là bao lâu vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_04','V345','导购',4,'基础全国联保一年，加钱可以升级到三年哦。','jī chǔ quán guó lián bǎo yī nián， jiā qián kě yǐ shēng jí dào sān nián ó。','Bảo hành toàn quốc cơ bản là một năm, trả thêm phí có thể nâng lên ba năm đó ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_05','V345','阮明',5,'保修期内系统故障能免费上门维修吗？','bǎo xiū qī nèi xì tǒng gù zhàng néng miǎn fèi shàng mén wéi xiū ma？','Trong thời gian bảo hành nếu hệ thống lỗi có được sửa tận nơi miễn phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_06','V345','导购',6,'市区范围内可以免费上门，超出范围需要送店。','shì qū fàn wéi nèi kě yǐ miǎn fèi shàng mén， chāo chū fàn wéi xū yào sòng diàn。','Trong nội thành thì được sửa tận nơi miễn phí, ngoài phạm vi thì phải mang ra tiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L345_07','V345','阮明',7,'了解了，我考虑一下，晚点过来付款吧。','liǎo jiě le， wǒ kǎo lǜ yī xià， wǎn diǎn guò lái fù kuǎn ba。','Em hiểu rồi, để em suy nghĩ thêm, lát em quay lại thanh toán ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT346','S117','Đăng ký lắp Internet cho phòng trọ',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V346','SIT346','P1','twist','ban_chinh_thuc',NULL,'租房办理宽带需要核验房屋地址，小区宽带端口有限，满员只能排队等待新端口。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_01','V346','阮明',1,'你好，我租的单间想办理宽带安装业务。','nǐ hǎo， wǒ zū de dān jiān xiǎng bàn lǐ kuān dài ān zhuāng yè wù。','Chào chị, em thuê phòng đơn, muốn đăng ký lắp mạng băng rộng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_02','V346','客服',2,'您好，请提供详细地址，我查询线路覆盖情况。','nín hǎo， qǐng tí gōng xiáng xì dì zhǐ， wǒ chá xún xiàn lù fù gài qíng kuàng。','Chào em, em cho chị xin địa chỉ chi tiết để chị kiểm tra tình trạng phủ sóng đường truyền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_03','V346','阮明',3,'地址是大学周边小区3栋502室，麻烦查一下。','dì zhǐ shì dà xué zhōu biān xiǎo qū 3 dòng 502 shì， má fán chá yī xià。','Địa chỉ là căn hộ số 502, tòa 3, khu gần trường đại học, phiền chị kiểm tra giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_04','V346','客服',4,'不好意思，您小区本周宽带端口已经全部用完了嘛。','bù hǎo yì sī， nín xiǎo qū běn zhōu kuān dài duān kǒu yǐ jīng quán bù yòng wán le ma。','Xin lỗi em, cổng mạng ở khu em tuần này đã dùng hết sạch rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_05','V346','阮明',5,'这样啊，那下一批端口什么时候开放呢？','zhè yàng a， nà xià yī pī duān kǒu shén me shí hòu kāi fàng ne？','Vậy à, thế đợt cổng tiếp theo mở khi nào ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_06','V346','客服',6,'三天后重新放号，到时候我可以提醒您预约。','sān tiān hòu chóng xīn fàng hào， dào shí hòu wǒ kě yǐ tí xǐng nín yù yuē。','Ba ngày nữa sẽ mở lại đợt số mới, lúc đó chị có thể nhắc em đặt trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L346_07','V346','阮明',7,'好，那麻烦三天后联系我，辛苦你啦。','hǎo， nà má fán sān tiān hòu lián xì wǒ， xīn kǔ nǐ la。','Vâng, vậy ba ngày nữa phiền chị liên hệ em nhé, cảm ơn chị nhiều ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT347','S115','Chuyển dữ liệu sang điện thoại mới',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V347','SIT347','P1','suon_se','tuy_y',NULL,'国产手机自带一键换机功能，年轻人大多会互相帮忙操作数据迁移。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_01','V347','阮明',1,'我刚换了新手机，不知道怎么转移旧手机数据啊。','wǒ gāng huàn le xīn shǒu jī， bù zhī dào zěn me zhuǎn yí jiù shǒu jī shù jù a。','Tao vừa đổi điện thoại mới, chẳng biết chuyển dữ liệu từ máy cũ sang thế nào cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_02','V347','小杨',2,'很简单，手机自带换机软件，跟着步骤操作就行啦。','hěn jiǎn dān， shǒu jī zì dài huàn jī ruǎn jiàn， gēn zhe bù zhòu cāo zuò jiù xíng la。','Đơn giản mà, điện thoại có sẵn phần mềm chuyển máy, cứ theo từng bước làm là được ấy.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_03','V347','阮明',3,'聊天记录、照片和文件都能完整复制过去吗？','liáo tiān jì lù、 zhào piān hé wén jiàn dōu néng wán zhěng fù zhì guò qù ma？','Tin nhắn, ảnh với file có sao chép nguyên vẹn qua được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_04','V347','小杨',4,'全部可以，就是两台手机都要连接同一个WiFi呢。','quán bù kě yǐ， jiù shì liǎng tái shǒu jī dōu yào lián jiē tóng yī gè WiFi ne。','Được hết luôn, chỉ cần hai máy cùng kết nối chung một WiFi thôi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_05','V347','阮明',5,'我还担心会丢失重要的学习资料。','wǒ hái dān xīn huì diū shī zhòng yào de xué xí zī liào。','Tao còn hơi lo bị mất mấy tài liệu học tập quan trọng nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_06','V347','小杨',6,'放心，我上次换机一点资料都没漏掉。','fàng xīn， wǒ shàng cì huàn jī yì diǎn zī liào dōu méi lòu diào。','Yên tâm đi, lần trước tao đổi máy chẳng thiếu tí tài liệu nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L347_07','V347','阮明',7,'太谢谢你了，等下我操作有问题再来问你吧。','tài xiè xiè nǐ le， děng xià wǒ cāo zuò yǒu wèn tí zài lái wèn nǐ ba。','Cảm ơn mày nhiều nha, lát tao làm mà có gì thắc mắc lại hỏi mày tiếp nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT348','S118','Cài đặt và đăng ký app dịch tiếng Trung',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V348','SIT348','P1','suon_se','tuy_y',NULL,'留学生常用翻译APP辅助学习中文，国内软件支持微信、QQ快捷登录，注册流程简单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_01','V348','阮明',1,'有没有好用的翻译软件推荐我下载一下啊？','yǒu méi yǒu hǎo yòng de fān yì ruǎn jiàn tuī jiàn wǒ xià zài yī xià a？','Có app dịch nào ngon giới thiệu tao tải về không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_02','V348','小林',2,'这款翻译APP特别适合留学生，离线也能用呢。','zhè kuǎn fān yì APP tè bié shì hé liú xué shēng， lí xiàn yě néng yòng ne。','Cái app dịch này hợp với du học sinh lắm, offline vẫn dùng được luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_03','V348','阮明',3,'下载之后注册需要绑定手机号吗？','xià zài zhī hòu zhù cè xū yào bǎng dìng shǒu jī hào ma？','Tải xong đăng ký có cần liên kết số điện thoại không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_04','V348','小林',4,'只用微信一键登录就可以，不用额外注册啦。','zhǐ yòng wēi xìn yī jiàn dēng lù jiù kě yǐ， bù yòng é wài zhù cè la。','Chỉ cần đăng nhập bằng WeChat một chạm là xong, không cần đăng ký thêm gì cả.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_05','V348','阮明',5,'还能拍照翻译课本上的汉字，对吗？','hái néng pāi zhào fān yì kè běn shàng de hàn zì， duì ma？','Còn chụp ảnh dịch chữ Hán trong sách giáo khoa được nữa đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_06','V348','小林',6,'没错，拍照翻译准确度很高，日常学习够用。','méi cuò， pāi zhào fān yì zhǔn què dù hěn gāo， rì cháng xué xí gòu yòng。','Đúng rồi, chụp ảnh dịch độ chính xác cao lắm, học hành hàng ngày dùng tẹt ga luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L348_07','V348','阮明',7,'太好了，我现在就下载安装试试吧。','tài hǎo le， wǒ xiàn zài jiù xià zài ān zhuāng shì shì ba。','Tuyệt quá, để tao tải về cài thử ngay đây.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT349','S115','Gia hạn gói cước SIM khi hết hạn',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V349','SIT349','P1','twist','ban_chinh_thuc',NULL,'国内手机运营商会推出专属学生优惠套餐，优惠到期或活动结束就无法办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_01','V349','阮明',1,'您好，我的手机流量套餐今天到期，想现场续费。','nín hǎo， wǒ de shǒu jī liú liàng tào cān jīn tiān dào qī， xiǎng xiàn chǎng xù fèi。','Chào anh, gói cước data điện thoại của em hôm nay hết hạn, em muốn gia hạn luôn tại đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_02','V349','工作人员',2,'可以，出示手机卡号，我帮你查询套餐选项。','kě yǐ， chū shì shǒu jī kǎ hào， wǒ bāng nǐ chá xún tào cān xuǎn xiàng。','Được, em cho xem số sim để anh kiểm tra các gói cước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_03','V349','阮明',3,'我平时流量用得多，有没有不限流量的学生套餐？','wǒ píng shí liú liàng yòng dé duō， yǒu méi yǒu bù xiàn liú liàng de xué shēng tào cān？','Em thường dùng data nhiều, có gói sinh viên không giới hạn dung lượng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_04','V349','工作人员',4,'学生专属套餐本月已经下架，只能选普通套餐嘛。','xué shēng zhuān shǔ tào cān běn yuè yǐ jīng xià jià， zhǐ néng xuǎn pǔ tōng tào cān ma。','Gói dành riêng cho sinh viên tháng này ngừng bán rồi, chỉ còn gói thường thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_05','V349','阮明',5,'啊，那普通套餐每月多少流量，多少钱月租？','a， nà pǔ tōng tào cān měi yuè duō shǎo liú liàng， duō shǎo qián yuè zū？','À, vậy gói thường mỗi tháng bao nhiêu dung lượng, cước tháng bao nhiêu ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_06','V349','工作人员',6,'每月40G流量，月租三十九元，性价比很高。','měi yuè 40G liú liàng， yuè zū sān shí jiǔ yuán， xìng jià bǐ hěn gāo。','Mỗi tháng 40G, cước tháng ba mươi chín tệ, khá đáng đồng tiền đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L349_07','V349','阮明',7,'行，那就办理这个普通套餐续费吧。','xíng， nà jiù bàn lǐ zhè ge pǔ tōng tào cān xù fèi ba。','Được ạ, vậy đăng ký gia hạn gói thường này cho em.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT350','S116','Nhờ sửa lỗi kết nối wifi trong phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V350','SIT350','P1','suon_se','ban_chinh_thuc',NULL,'宽带套餐保修期内，线路、WiFi故障可免费上门维修，无需支付人工费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_01','V350','阮明',1,'师傅，我房间WiFi突然连不上了，麻烦上门看看吧。','shī fù， wǒ fáng jiān WiFi tū rán lián bù shàng le， má fán shàng mén kàn kàn ba。','Anh ơi, WiFi phòng em tự dưng không kết nối được nữa, phiền anh qua xem giúp em với.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_02','V350','维修师傅',2,'好，我先检查光猫和路由器，大概率是线路松动。','hǎo， wǒ xiān jiǎn chá guāng māo hé lù yóu qì， dà gài lǜ shì xiàn lù sōng dòng。','Được, để anh kiểm tra modem quang với router trước đã, chắc là do đường dây bị lỏng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_03','V350','阮明',3,'昨天网络还很流畅，今天一早直接断网了呢。','zuó tiān wǎng luò hái hěn liú chàng， jīn tiān yī zǎo zhí jiē duàn wǎng le ne。','Hôm qua mạng vẫn chạy êm ru mà, sáng nay tự dưng mất mạng luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_04','V350','维修师傅',4,'我重新插紧线路，再重置路由器就能恢复。','wǒ chóng xīn chā jǐn xiàn lù， zài zhòng zhì lù yóu qì jiù néng huī fù。','Anh cắm chặt lại dây, rồi reset lại router là sẽ hoạt động lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_05','V350','阮明',5,'维修需要额外收取服务费吗？','wéi xiū xū yào é wài shōu qǔ fú wù fèi ma？','Sửa như vậy có tính thêm phí dịch vụ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_06','V350','维修师傅',6,'在宽带保修期内，上门检修完全免费。','zài kuān dài bǎo xiū qī nèi， shàng mén jiǎn xiū wán quán miǎn fèi。','Còn trong thời hạn bảo hành mạng thì đến kiểm tra hoàn toàn miễn phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L350_07','V350','阮明',7,'太好了，辛苦师傅帮忙处理啦。','tài hǎo le， xīn kǔ shī fù bāng máng chǔ lǐ la。','Tuyệt quá, cảm ơn anh đã giúp em xử lý nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT351','S119','Chuyển tiền cho bạn qua app ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V351','SIT351','P1','suon_se','ban_chinh_thuc',NULL,'国内手机银行转账实时到账，会自动发送短信通知，转账前务必核对姓名卡号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_01','V351','阮明',1,'你好，我想在手机银行APP给同学转账。','nǐ hǎo， wǒ xiǎng zài shǒu jī yín háng APP gěi tóng xué zhuǎn zhàng。','Chào chị, em muốn chuyển tiền cho bạn học qua app ngân hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_02','V351','客服',2,'您好，您需要输入对方银行卡号和姓名核对哦。','nín hǎo， nín xū yào shū rù duì fāng yín háng kǎ hào hé xìng míng hé duì ó。','Chào em, em cần nhập số thẻ ngân hàng và tên của người nhận để đối chiếu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_03','V351','阮明',3,'转账有限额吗，我一次转三千元可以吗？','zhuǎn zhàng yǒu xiàn é ma， wǒ yī cì zhuǎn sān qiān yuán kě yǐ ma？','Chuyển khoản có giới hạn không ạ, em chuyển một lần ba nghìn tệ được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_04','V351','客服',4,'学生一类银行卡单日转账限额五万元，完全没问题。','xué shēng yī lèi yín háng kǎ dān rì zhuǎn zhàng xiàn é wǔ wàn yuán， wán quán méi wèn tí。','Thẻ ngân hàng loại dành cho sinh viên hạn mức chuyển khoản một ngày là năm mươi nghìn tệ, hoàn toàn không vấn đề gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_05','V351','阮明',5,'转账成功之后会有短信通知双方吗？','zhuǎn zhàng chéng gōng zhī hòu huì yǒu duǎn xìn tōng zhī shuāng fāng ma？','Chuyển thành công rồi thì có tin nhắn báo cho cả hai bên không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_06','V351','客服',6,'双方都会收到提醒，方便核对交易记录呢。','shuāng fāng dōu huì shōu dào tí xǐng， fāng biàn hé duì jiāo yì jì lù ne。','Cả hai bên đều sẽ nhận được thông báo, tiện đối chiếu giao dịch luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L351_07','V351','阮明',7,'清楚操作流程了，谢谢你的讲解吧。','qīng chǔ cāo zuò liú chéng le， xiè xiè nǐ de jiǎng jiě ba。','Em hiểu rõ quy trình rồi ạ, cảm ơn chị đã hướng dẫn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT352','S119','Nhận tiền gia đình gửi từ nước ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V352','SIT352','P1','twist','chinh_thuc',NULL,'境外跨境汇款需要银行系统清算，无法实时兑换人民币取现，留学生需携带护照办理外汇业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_01','V352','阮明',1,'您好，我家人从境外给我汇了一笔生活费，我来办理结汇。','nín hǎo， wǒ jiā rén cóng jìng wài gěi wǒ huì le yī bǐ shēng huó fèi， wǒ lái bàn lǐ jié huì。','Chào chị, gia đình tôi từ nước ngoài chuyển cho tôi một khoản sinh hoạt phí, tôi đến làm thủ tục đổi ngoại tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_02','V352','柜员',2,'请出示你的护照和银行卡，我先查询外汇到账状态。','qǐng chū shì nǐ de hù zhào hé yín háng kǎ， wǒ xiān chá xún wài huì dào zhàng zhuàng tài。','Anh vui lòng cho xem hộ chiếu và thẻ ngân hàng, tôi kiểm tra tình trạng tiền về trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_03','V352','阮明',3,'好，证件都在这里，大概昨天傍晚汇出的。','hǎo， zhèng jiàn dōu zài zhè lǐ， dà gài zuó tiān bàng wǎn huì chū de。','Vâng, giấy tờ đây đủ cả, khoảng chiều tối hôm qua thì tiền được chuyển đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_04','V352','柜员',4,'抱歉，这笔汇款还未清算，今天暂时无法提取嘛。','bào qiàn， zhè bǐ huì kuǎn hái wèi qīng suàn， jīn tiān zàn shí wú fǎ tí qǔ ma。','Xin lỗi anh, khoản tiền này chưa được thanh toán bù trừ xong, hôm nay tạm thời chưa rút được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_05','V352','阮明',5,'啊？那要等到什么时候才能兑换人民币？','a？ nà yào děng dào shén me shí hòu cái néng duì huàn rén mín bì？','Ơ? Vậy phải đợi đến khi nào mới đổi được sang nhân dân tệ ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_06','V352','柜员',6,'明天上午系统完成清算，你再来柜台办理就行。','míng tiān shàng wǔ xì tǒng wán chéng qīng suàn， nǐ zài lái guì tái bàn lǐ jiù xíng。','Sáng mai hệ thống hoàn tất thanh toán bù trừ, anh quay lại quầy làm thủ tục là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L352_07','V352','阮明',7,'好，我明天一早过来，麻烦你登记一下。','hǎo， wǒ míng tiān yī zǎo guò lái， má fán nǐ dēng jì yī xià。','Vâng, mai tôi qua từ sáng sớm, phiền chị đăng ký giúp tôi trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT353','S119','Rút tiền tại ATM',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V353','SIT353','P1','suon_se','tuy_y',NULL,'国内ATM取款有现金上限，忘记取卡会被机器回收，需要带身份证去柜台取回。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_01','V353','阮明',1,'学长，这个ATM机怎么取款，我不太会操作啊。','xué zhǎng， zhè ge ATM jī zěn me qǔ kuǎn， wǒ bù tài huì cāo zuò a。','Anh ơi, cái máy ATM này rút tiền kiểu gì thế, em không rành thao tác lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_02','V353','学长',2,'先插银行卡，输入密码，再选择取款金额就行啦。','xiān chā yín háng kǎ， shū rù mì mǎ， zài xuǎn zé qǔ kuǎn jīn é jiù xíng la。','Cắm thẻ ngân hàng vào trước, nhập mật khẩu, rồi chọn số tiền cần rút là xong ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_03','V353','阮明',3,'单日最多能取多少现金，会不会有限制？','dān rì zuì duō néng qǔ duō shǎo xiàn jīn， huì bú huì yǒu xiàn zhì？','Một ngày rút tối đa được bao nhiêu tiền mặt, có bị giới hạn gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_04','V353','学长',4,'ATM单日限额两万，日常取生活费完全够用呢。','ATM dān rì xiàn é liǎng wàn， rì cháng qǔ shēng huó fèi wán quán gòu yòng ne。','ATM giới hạn hai vạn tệ một ngày, đủ xài thoải mái cho sinh hoạt phí hàng ngày luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_05','V353','阮明',5,'取完钱之后一定要记得拔卡对吧？','qǔ wán qián zhī hòu yí dìng yào jì de bá kǎ duì ba？','Rút tiền xong nhất định phải nhớ rút thẻ ra đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_06','V353','学长',6,'没错，超时不取卡机器会自动吞卡的。','méi cuò， chāo shí bù qǔ kǎ jī qì huì zì dòng tūn kǎ de。','Đúng rồi, để quá lâu không rút thẻ là máy tự động nuốt thẻ luôn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L353_07','V353','阮明',7,'太感谢你提醒我，不然我很容易忘啦。','tài gǎn xiè nǐ tí xǐng wǒ， bù rán wǒ hěn róng yì wàng la。','Cảm ơn anh nhắc em nhiều nha, không thì em kiểu gì cũng quên mất.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT354','S119','Báo mất thẻ và xin khóa thẻ khẩn cấp',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V354','SIT354','P1','suon_se','chinh_thuc',NULL,'银行卡丢失第一时间电话挂失锁卡，能保障账户资金安全，补办卡片必须线下网点办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_01','V354','阮明',1,'您好，我的银行卡遗失了，申请紧急挂失锁卡。','nín hǎo， wǒ de yín háng kǎ yí shī le， shēn qǐng jǐn jí guà shī suǒ kǎ。','Chào chị, tôi bị mất thẻ ngân hàng, tôi muốn xin khóa thẻ khẩn cấp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_02','V354','客服',2,'请告知您姓名、银行卡尾号以及身份证号吧。','qǐng gào zhī nín xìng míng、 yín háng kǎ wěi hào yǐ jí shēn fèn zhèng hào ba。','Anh vui lòng cho biết họ tên, 4 số cuối của thẻ và số CMND/CCCD ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_03','V354','阮明',3,'全部信息我都记好了，现在报给你核对。','quán bù xìn xī wǒ dōu jì hǎo le， xiàn zài bào gěi nǐ hé duì。','Tất cả thông tin tôi đã ghi sẵn rồi, để tôi đọc cho chị đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_04','V354','客服',4,'已经为您临时冻结卡片，资金不会被盗刷呢。','yǐ jīng wèi nín lín shí dòng jié kǎ piàn， zī jīn bú huì bèi dào shuā ne。','Chúng tôi đã tạm khóa thẻ cho anh rồi, tiền trong tài khoản sẽ không bị mất đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_05','V354','阮明',5,'那之后补办新卡需要去线下柜台办理吗？','nà zhī hòu bǔ bàn xīn kǎ xū yào qù xiàn xià guì tái bàn lǐ ma？','Vậy sau này muốn làm lại thẻ mới thì có phải ra quầy giao dịch không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_06','V354','客服',6,'是的，携带护照前往就近网点即可补办。','shì de， xié dài hù zhào qián wǎng jiù jìn wǎng diǎn jí kě bǔ bàn。','Vâng, anh mang theo hộ chiếu đến chi nhánh gần nhất là làm lại được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L354_07','V354','阮明',7,'太感谢了，还好及时打电话挂失啦。','tài gǎn xiè le， hái hǎo jí shí dǎ diàn huà guà shī la。','Cảm ơn chị nhiều, may mà tôi gọi điện báo mất kịp thời.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT355','S119','Yêu cầu in sao kê giao dịch',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V355','SIT355','P1','suon_se','ban_chinh_thuc',NULL,'留学生打印银行卡流水用于留学报备，多数银行免费办理，打印文件加盖公章才具备证明效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_01','V355','阮明',1,'你好，我需要打印近半年的银行卡交易流水。','nǐ hǎo， wǒ xū yào dǎ yìn jìn bàn nián de yín háng kǎ jiāo yì liú shuǐ。','Chào chị, tôi cần in sao kê giao dịch thẻ ngân hàng khoảng nửa năm gần đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_02','V355','柜员',2,'可以，出示你的银行卡和护照，我帮你调取记录哦。','kě yǐ， chū shì nǐ de yín háng kǎ hé hù zhào， wǒ bāng nǐ diào qǔ jì lù ó。','Được ạ, anh cho em xin thẻ ngân hàng và hộ chiếu, em tra giúp anh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_03','V355','阮明',3,'打印流水需要收取手续费吗？','dǎ yìn liú shuǐ xū yào shōu qǔ shǒu xù fèi ma？','In sao kê thì có tính phí không vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_04','V355','柜员',4,'留学生办理留学相关流水打印是免费的呢。','liú xué shēng bàn lǐ liú xué xiāng guān liú shuǐ dǎ yìn shì miǎn fèi de ne。','Du học sinh in sao kê phục vụ mục đích du học thì được miễn phí ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_05','V355','阮明',5,'太好了，我要交给学校作为资金证明材料。','tài hǎo le， wǒ yào jiāo gěi xué xiào zuò wéi zī jīn zhèng míng cái liào。','Tốt quá, tôi cần nộp cho trường làm giấy chứng minh tài chính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_06','V355','柜员',6,'我会帮你加盖银行公章，学校可以直接认可。','wǒ huì bāng nǐ jiā gài yín háng gōng zhāng， xué xiào kě yǐ zhí jiē rèn kě。','Em sẽ đóng dấu ngân hàng vào, trường sẽ công nhận trực tiếp luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L355_07','V355','阮明',7,'辛苦你了，等下我取完流水就离开。','xīn kǔ nǐ le， děng xià wǒ qǔ wán liú shuǐ jiù lí kāi。','Cảm ơn chị vất vả rồi, lát tôi lấy sao kê xong là về.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT356','S119','Đổi mã PIN thẻ ngân hàng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V356','SIT356','P1','twist','tuy_y',NULL,'银行取款密码固定六位数，修改时两次输入必须完全相同，不一致则操作失败。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_01','V356','阮明',1,'你好，我想在自助终端修改银行卡取款密码。','nǐ hǎo， wǒ xiǎng zài zì zhù zhōng duān xiū gǎi yín háng kǎ qǔ kuǎn mì mǎ。','Chào anh, tôi muốn đổi mã PIN rút tiền của thẻ ngân hàng ở cây ATM này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_02','V356','引导员',2,'先插卡输入旧密码，再设置新的六位数字密码。','xiān chā kǎ shū rù jiù mì mǎ， zài shè zhì xīn de liù wèi shù zì mì mǎ。','Anh cắm thẻ vào, nhập mật khẩu cũ trước, rồi đặt mật khẩu mới 6 số nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_03','V356','阮明',3,'我刚刚输入一遍，提示两次密码不一致嘛。','wǒ gāng gāng shū rù yī biàn， tí shì liǎng cì mì mǎ bù yī zhì ma。','Tôi vừa nhập rồi mà máy báo hai lần mật khẩu không khớp nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_04','V356','阮明',4,'我没看清屏幕，两次输的数字不一样。','wǒ méi kàn qīng píng mù， liǎng cì shū de shù zì bù yí yàng。','Tôi không nhìn rõ màn hình, hai lần gõ số không giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_05','V356','引导员',5,'没关系，重新操作一次，仔细核对数字就行。','méi guān xì， chóng xīn cāo zuò yī cì， zǐ xì hé duì shù zì jiù xíng。','Không sao, anh làm lại lần nữa, chú ý xem kỹ số trên màn hình là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_06','V356','阮明',6,'好，我慢慢来，这次一定留意屏幕提示。','hǎo， wǒ màn màn lái， zhè cì yí dìng liú yì píng mù tí shì。','Ừ, để tôi làm từ từ, lần này chắc chắn để ý màn hình cẩn thận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L356_07','V356','阮明',7,'终于修改成功了，谢谢你在旁边指导我啦。','zhōng yú xiū gǎi chéng gōng le， xiè xiè nǐ zài páng biān zhǐ dǎo wǒ la。','Cuối cùng cũng đổi thành công, cảm ơn anh đứng bên chỉ tôi nha.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT357','S119','Hỏi phí chuyển tiền quốc tế',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V357','SIT357','P1','suon_se','chinh_thuc',NULL,'国际跨境转账手续费固定收取，到账速度受国内外节假日、银行清算时间影响。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_01','V357','阮明',1,'您好，如果我往越南的账户转账，手续费怎么收取？','nín hǎo， rú guǒ wǒ wǎng yuè nán de zhàng hù zhuǎn zhàng， shǒu xù fèi zěn me shōu qǔ？','Chào chị, nếu tôi chuyển tiền về tài khoản ở Việt Nam thì phí chuyển tính thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_02','V357','柜员',2,'手续费分为固定工本费和跨境电讯费两部分哦。','shǒu xù fèi fēn wéi gù dìng gōng běn fèi hé kuà jìng diàn xùn fèi liǎng bù fèn ó。','Phí chuyển gồm phí công điện cố định và phí điện tín xuyên biên giới đó ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_03','V357','阮明',3,'转账金额不同，手续费价格会变化吗？','zhuǎn zhàng jīn é bù tóng， shǒu xù fèi jià gé huì biàn huà ma？','Số tiền chuyển khác nhau thì phí có thay đổi theo không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_04','V357','柜员',4,'手续费统一标准，不会随转账金额增减呢。','shǒu xù fèi tǒng yī biāo zhǔn， bú huì suí zhuǎn zhàng jīn é zēng jiǎn ne。','Phí là mức chung, không tăng giảm theo số tiền chuyển đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_05','V357','阮明',5,'那多久能到对方的海外银行卡账户？','nà duō jiǔ néng dào duì fāng de hǎi wài yín háng kǎ zhàng hù？','Vậy mất bao lâu thì tiền vào tài khoản ngân hàng nước ngoài của người nhận?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_06','V357','柜员',6,'最快两个工作日，节假日会顺延清算时间。','zuì kuài liǎng gè gōng zuò rì， jié jià rì huì shùn yán qīng suàn shí jiān。','Nhanh nhất là hai ngày làm việc, gặp ngày lễ thì thời gian thanh toán sẽ lùi lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L357_07','V357','阮明',7,'我全部了解清楚了，感谢你的细致讲解。','wǒ quán bù liǎo jiě qīng chǔ le， gǎn xiè nǐ de xì zhì jiǎng jiě。','Tôi hiểu rõ hết rồi, cảm ơn chị đã giải thích kỹ càng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT358','S119','Khiếu nại giao dịch bị trừ tiền nhưng không nhận được hàng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V358','SIT358','P1','twist','ban_chinh_thuc',NULL,'国内电商平台漏发、丢件，顾客可自主选择补发货物或全额退款，平台客服全程协调处理；商家责任退款自动审核，到账速度更快。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_01','V358','阮明',1,'你好，我要反馈一笔线上订单问题，支付扣款成功，至今没有收到包裹。','nǐ hǎo， wǒ yào fǎn kuì yī bǐ xiàn shàng dìng dān wèn tí， zhī fù kòu kuǎn chéng gōng， zhì jīn méi yǒu shōu dào bāo guǒ。','Chào chị, tôi muốn phản ánh một đơn hàng online, tôi đã thanh toán thành công mà đến giờ vẫn chưa nhận được hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_02','V358','客服',2,'您好，麻烦先提供一下完整订单编号，我调取后台物流配送记录哈。','nín hǎo， má fán xiān tí gōng yī xià wán zhěng dìng dān biān hào， wǒ diào qǔ hòu tái wù liú pèi sòng jì lù hā。','Chào anh, phiền anh cung cấp mã đơn hàng đầy đủ để em tra thông tin vận chuyển ở hệ thống nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_03','V358','阮明',3,'订单编号我复制在这里发给你，物流页面从下单当天一直显示待揽收状态呢。','dìng dān biān hào wǒ fù zhì zài zhè lǐ fā gěi nǐ， wù liú yè miàn cóng xià dān dàng tiān yì zhí xiǎn shì dài lǎn shōu zhuàng tài ne。','Mã đơn hàng tôi copy gửi chị đây, trang vận chuyển từ lúc đặt hàng đến giờ vẫn hiện trạng thái chờ lấy hàng.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_04','V358','客服',4,'我调取仓库发货台账核对，查到是仓库工作人员漏打包商品，实在非常抱歉。','wǒ diào qǔ cāng kù fā huò tái zhàng hé duì， chá dào shì cāng kù gōng zuò rén yuán lòu dǎ bāo shāng pǐn， shí zài fēi cháng bào qiàn。','Em kiểm tra sổ giao hàng của kho rồi, phát hiện nhân viên kho đóng gói thiếu sản phẩm, thật sự rất xin lỗi anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_05','V358','阮明',5,'我下单已经七天，一直等待收货，耽误了我的使用计划，心里挺着急的。','wǒ xià dān yǐ jīng qī tiān， yì zhí děng dài shōu huò， dān wù le wǒ de shǐ yòng jì huà， xīn lǐ tǐng zháo jí de。','Tôi đặt hàng đã bảy ngày rồi, cứ chờ mãi mà không thấy hàng, ảnh hưởng đến kế hoạch sử dụng của tôi, tôi cũng sốt ruột lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_06','V358','客服',6,'针对漏发问题平台提供两种解决方案，您可以自由选择，没有强制要求。','zhēn duì lòu fā wèn tí píng tái tí gōng liǎng zhǒng jiě jué fāng àn， nín kě yǐ zì yóu xuǎn zé， méi yǒu qiáng zhì yāo qiú。','Về vấn đề giao thiếu hàng, bên sàn có hai phương án giải quyết, anh có thể tự chọn, không bắt buộc đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_07','V358','阮明',7,'那现在第一种方案补发商品、第二种全额退款，两种分别需要等待多久？','nà xiàn zài dì yī zhǒng fāng àn bǔ fā shāng pǐn、 dì èr zhǒng quán é tuì kuǎn， liǎng zhǒng fēn bié xū yào děng dài duō jiǔ？','Vậy phương án một là gửi bù hàng, phương án hai là hoàn tiền toàn bộ, mỗi cái phải chờ bao lâu vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_08','V358','客服',8,'选择补发需要重新排单发货，仓库备货需要再等三天；退款申请提交当日原路返还资金。','xuǎn zé bǔ fā xū yào chóng xīn pái dān fā huò， cāng kù bèi huò xū yào zài děng sān tiān； tuì kuǎn shēn qǐng tí jiāo dāng rì yuán lù fǎn huán zī jīn。','Nếu chọn gửi bù thì phải xếp lại đơn giao hàng, kho chuẩn bị hàng phải chờ thêm ba ngày; còn hoàn tiền thì nộp yêu cầu trong ngày là tiền về lại ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_09','V358','阮明',9,'我急需这件商品使用，不想再额外等待三天补发货品。','wǒ jí xū zhè jiàn shāng pǐn shǐ yòng， bù xiǎng zài é wài děng dài sān tiān bǔ fā huò pǐn。','Tôi đang cần dùng gấp món đồ này, không muốn chờ thêm ba ngày để nhận hàng bù nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_10','V358','客服',10,'我明白您的需求，那我直接为您提交全额退款售后申请。','wǒ míng bái nín de xū qiú， nà wǒ zhí jiē wèi nín tí jiāo quán é tuì kuǎn shòu hòu shēn qǐng。','Em hiểu nhu cầu của anh rồi, vậy em nộp yêu cầu hoàn tiền toàn bộ cho anh luôn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_11','V358','阮明',11,'退款审核会不会需要人工排队，延迟好几天到账？','tuì kuǎn shěn hé huì bú huì xū yào rén gōng pái duì， yán chí hǎo jǐ tiān dào zhàng？','Việc duyệt hoàn tiền có phải xếp hàng xử lý thủ công không, có bị chậm mấy ngày mới vào tiền không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_12','V358','客服',12,'漏发属于商家全责，退款自动审核，几分钟内就能完成资金返还。','lòu fā shǔ yú shāng jiā quán zé， tuì kuǎn zì dòng shěn hé， jǐ fēn zhōng nèi jiù néng wán chéng zī jīn fǎn huán。','Lỗi giao thiếu hàng hoàn toàn do bên bán, nên hoàn tiền được duyệt tự động, chỉ vài phút là tiền về lại tài khoản thôi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_13','V358','阮明',13,'那就直接办理全额退款吧，我不想继续等待补发货物了。','nà jiù zhí jiē bàn lǐ quán é tuì kuǎn ba， wǒ bù xiǎng jì xù děng dài bǔ fā huò wù le。','Vậy thì làm hoàn tiền toàn bộ luôn đi, tôi không muốn chờ gửi bù hàng nữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_14','V358','客服',14,'申请已提交，您留意支付软件的到账通知即可。','shēn qǐng yǐ tí jiāo， nín liú yì zhī fù ruǎn jiàn de dào zhàng tōng zhī jí kě。','Yêu cầu đã được gửi rồi ạ, anh chú ý thông báo nhận tiền trên ứng dụng thanh toán là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L358_15','V358','阮明',15,'好，感谢快速处理我的售后投诉。','hǎo， gǎn xiè kuài sù chǔ lǐ wǒ de shòu hòu tóu sù。','Được, cảm ơn chị đã xử lý khiếu nại của tôi nhanh chóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT359','S120','Hỏi tuyến xe buýt đến trung tâm thành phố',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V359','SIT359','P1','suon_se','tuy_y',NULL,'国内城市公交支持手机二维码扫码乘车，无需单独购买公交卡，出行更方便。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_01','V359','阮明',1,'大叔您好，我想去市中心步行街，该坐哪一路公交啊？','dà shū nín hǎo， wǒ xiǎng qù shì zhōng xīn bù xíng jiē， gāi zuò nǎ yī lù gōng jiāo a？','Chú ơi, cháu muốn ra phố đi bộ trung tâm thành phố, vậy phải đi tuyến xe buýt nào ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_02','V359','保安大叔',2,'出门右转站台坐12路，终点站就是市中心啦。','chū mén yòu zhuǎn zhàn tái zuò 12 lù， zhōng diǎn zhàn jiù shì shì zhōng xīn la。','Ra cửa rẽ phải, ra trạm đón tuyến 12, điểm cuối chính là trung tâm thành phố đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_03','V359','阮明',3,'一趟车程大概要多久，会不会经常堵车呢？','yī tàng chē chéng dà gài yào duō jiǔ， huì bú huì jīng cháng dǔ chē ne？','Một chuyến đi mất khoảng bao lâu ạ, có hay bị kẹt xe không chú?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_04','V359','保安大叔',4,'不堵车四十分钟，下班高峰期会慢一点。','bù dǔ chē sì shí fēn zhōng， xià bān gāo fēng qī huì màn yì diǎn。','Không kẹt xe thì bốn mươi phút, giờ cao điểm tan tầm thì chậm hơn chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_05','V359','阮明',5,'公交支持手机扫码乘车，不用办实体卡对吧？','gōng jiāo zhī chí shǒu jī sǎo mǎ chéng chē， bù yòng bàn shí tǐ kǎ duì ba？','Xe buýt có hỗ trợ quét mã điện thoại để lên xe, không cần làm thẻ cứng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_06','V359','保安大叔',6,'没错，调出乘车码直接扫码就能上车。','méi cuò， diào chū chéng chē mǎ zhí jiē sǎo mǎ jiù néng shàng chē。','Đúng rồi, cháu mở mã lên xe ra rồi quét là lên xe được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L359_07','V359','阮明',7,'太感谢大叔指路，我现在就去站台等车吧。','tài gǎn xiè dà shū zhǐ lù， wǒ xiàn zài jiù qù zhàn tái děng chē ba。','Cảm ơn chú chỉ đường nhiều lắm, giờ cháu ra trạm chờ xe luôn đây ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT360','S121','Nạp tiền vào thẻ tàu điện',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V360','SIT360','P1','twist','tuy_y',NULL,'地铁自助充值机偶尔出现系统延迟扣款不到账，等待片刻或联系站内工作人员即可解决。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_01','V360','阮明',1,'同学，这个自助机怎么给地铁交通卡充值啊？','tóng xué， zhè ge zì zhù jī zěn me gěi dì tiě jiāo tōng kǎ chōng zhí a？','Bạn ơi, cái máy tự động này nạp tiền vào thẻ tàu điện ngầm kiểu gì vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_02','V360','志愿者',2,'先把卡片放在感应区，再选择充值金额扫码付款。','xiān bǎ kǎ piàn fàng zài gǎn yìng qū， zài xuǎn zé chōng zhí jīn é sǎo mǎ fù kuǎn。','Bạn để thẻ vào vùng cảm ứng trước, rồi chọn số tiền nạp và quét mã thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_03','V360','阮明',3,'我扫码支付之后，机器提示充值失败嘛。','wǒ sǎo mǎ zhī fù zhī hòu， jī qì tí shì chōng zhí shī bài ma。','Mình quét mã thanh toán xong rồi mà máy báo nạp tiền thất bại nè.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_04','V360','阮明',4,'手机扣款了，但是卡里余额没有增加。','shǒu jī kòu kuǎn le， dàn shì kǎ lǐ yú é méi yǒu zēng jiā。','Điện thoại bị trừ tiền rồi, nhưng số dư trong thẻ không tăng lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_05','V360','志愿者',5,'别着急，系统延迟，五分钟后再查询余额就行。','bié zháo jí， xì tǒng yán chí， wǔ fēn zhōng hòu zài chá xún yú é jiù xíng。','Đừng lo, hệ thống bị chậm thôi, đợi năm phút rồi kiểm tra lại số dư là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_06','V360','阮明',6,'原来是系统卡顿，我等一会儿再看余额。','yuán lái shì xì tǒng kǎ dùn， wǒ děng yī huì er zài kàn yú é。','Ra là do hệ thống bị lag, để mình đợi chút rồi xem lại số dư.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L360_07','V360','阮明',7,'还好有你帮忙讲解，不然我都不知道怎么办啦。','hái hǎo yǒu nǐ bāng máng jiǎng jiě， bù rán wǒ dōu bù zhī dào zěn me bàn la。','May mà có bạn giúp giải thích, chứ không mình chẳng biết làm sao luôn á.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT361','S122','Mở khóa và thuê xe đạp công cộng qua app',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V361','SIT361','P1','twist','tuy_y',NULL,'国内共享单车依靠手机App扫码、蓝牙联动解锁，故障车辆可免费更换，不会扣费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_01','V361','阮明',1,'同学，我扫码共享单车怎么一直开锁失败啊？','tóng xué， wǒ sǎo mǎ gòng xiǎng dān chē zěn me yì zhí kāi suǒ shī bài a？','Bạn ơi, mình quét mã xe đạp chung mà sao cứ mở khóa thất bại hoài vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_02','V361','小杨',2,'你看看手机蓝牙开了吗，骑车必须打开蓝牙呢。','nǐ kàn kàn shǒu jī lán yá kāi le ma， qí chē bì xū dǎ kāi lán yá ne。','Bạn xem điện thoại đã bật Bluetooth chưa, muốn đi xe là phải bật Bluetooth đó nha.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_03','V361','阮明',3,'蓝牙是打开的，页面一直显示车辆故障。','lán yá shì dǎ kāi de， yè miàn yì zhí xiǎn shì chē liàng gù zhàng。','Bluetooth mình bật rồi, mà màn hình cứ báo xe bị lỗi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_04','V361','小杨',4,'那这辆车出问题了，直接点换车按钮就行啦。','nà zhè liàng chē chū wèn tí le， zhí jiē diǎn huàn chē àn niǔ jiù xíng la。','Vậy là xe đó có vấn đề rồi, bạn bấm nút đổi xe khác là được luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_05','V361','阮明',5,'原来是这样，我还以为是我的账号有问题。','yuán lái shì zhè yàng， wǒ hái yǐ wéi shì wǒ de zhàng hào yǒu wèn tí。','Ra vậy à, mình cứ tưởng tài khoản của mình bị làm sao chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_06','V361','小杨',6,'路边很多备用单车，换一辆很快就能解锁。','lù biān hěn duō bèi yòng dān chē， huàn yī liàng hěn kuài jiù néng jiě suǒ。','Ở lề đường có nhiều xe dự phòng lắm, đổi xe khác là mở khóa được ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L361_07','V361','阮明',7,'太谢谢你提醒我，不然我要在这里耗好久。','tài xiè xiè nǐ tí xǐng wǒ， bù rán wǒ yào zài zhè lǐ hào hǎo jiǔ。','Cảm ơn bạn nhắc mình nhiều nha, không thì mình phải loay hoay ở đây lâu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT362','S123','Thuê xe máy điện ngắn ngày',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V362','SIT362','P1','suon_se','ban_chinh_thuc',NULL,'国内电动车租赁门店大多需要押证件，归还车辆无损坏后立即返还证件押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_01','V362','阮明',1,'老板你好，我想租一辆电动车，只用半天可以吗？','lǎo bǎn nǐ hǎo， wǒ xiǎng zū yī liàng diàn dòng chē， zhǐ yòng bàn tiān kě yǐ ma？','Chào chú, cháu muốn thuê một chiếc xe máy điện, chỉ dùng nửa ngày thôi được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_02','V362','老板',2,'没问题，半天三十块，需要押你的护照登记哦。','méi wèn tí， bàn tiān sān shí kuài， xū yào yā nǐ de hù zhào dēng jì ó。','Không vấn đề gì, nửa ngày ba mươi tệ, cần thế chấp hộ chiếu của cháu để đăng ký nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_03','V362','阮明',3,'骑车去城郊景点，电量来回足够吗？','qí chē qù chéng jiāo jǐng diǎn， diàn liàng lái huí zú gòu ma？','Cháu đi ra mấy điểm tham quan ngoại ô, pin đi về đủ dùng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_04','V362','老板',4,'满电续航五十公里，短途出行完全够用的。','mǎn diàn xù háng wǔ shí gōng lǐ， duǎn tú chū xíng wán quán gòu yòng de。','Sạc đầy chạy được năm mươi cây số, đi gần thì thoải mái luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_05','V362','阮明',5,'路上万一没电，店里有应急充电设备吧？','lù shàng wàn yī méi diàn， diàn lǐ yǒu yìng jí chōng diàn shè bèi ba？','Lỡ trên đường hết pin thì cửa hàng có thiết bị sạc dự phòng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_06','V362','老板',6,'店里有便携充电器，你可以随身带着备用。','diàn lǐ yǒu biàn xié chōng diàn qì， nǐ kě yǐ suí shēn dài zhe bèi yòng。','Cửa hàng có sạc di động, cháu mang theo bên người để phòng khi cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L362_07','V362','阮明',7,'好，那我现在登记租车，麻烦你啦。','hǎo， nà wǒ xiàn zài dēng jì zū chē， má fán nǐ la。','Dạ vậy giờ cháu đăng ký thuê xe luôn, làm phiền chú nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT363','S124','Mua vé tàu cao tốc về quê vào kỳ nghỉ',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V363','SIT363','P1','twist','ban_chinh_thuc',NULL,'外籍留学生使用护照购买高铁票，部分自助设备无法识别，必须前往人工窗口办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_01','V363','阮明',1,'你好，我想用自助机买一张周末去邻市的高铁票。','nǐ hǎo， wǒ xiǎng yòng zì zhù jī mǎi yī zhāng zhōu mò qù lín shì de gāo tiě piào。','Chào anh, tôi muốn dùng máy tự phục vụ mua vé tàu cao tốc cuối tuần đi thành phố bên cạnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_02','V363','引导员',2,'先把护照放在读卡区，再输入目的地站点就行。','xiān bǎ hù zhào fàng zài dú kǎ qū， zài shū rù mù dì dì zhàn diǎn jiù xíng。','Anh đặt hộ chiếu vào khu quét thẻ trước, rồi nhập ga đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_03','V363','阮明',3,'我选好车次，系统提示外籍证件无法线上核验嘛。','wǒ xuǎn hǎo chē cì， xì tǒng tí shì wài jí zhèng jiàn wú fǎ xiàn shàng hé yàn ma。','Tôi chọn xong chuyến tàu rồi mà hệ thống báo giấy tờ nước ngoài không xác thực online được à.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_04','V363','引导员',4,'这种情况要去人工窗口，工作人员手动录入信息。','zhè zhǒng qíng kuàng yào qù rén gōng chuāng kǒu， gōng zuò rén yuán shǒu dòng lù rù xìn xī。','Trường hợp này phải ra quầy vé thủ công, nhân viên sẽ nhập thông tin bằng tay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_05','V363','阮明',5,'人工窗口排队人多吗，大概要等多久呢？','rén gōng chuāng kǒu pái duì rén duō ma， dà gài yào děng duō jiǔ ne？','Quầy thủ công có đông người xếp hàng không, chắc phải đợi bao lâu vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_06','V363','引导员',6,'现在人不多，十分钟左右就能完成购票。','xiàn zài rén bù duō， shí fēn zhōng zuǒ yòu jiù néng wán chéng gòu piào。','Giờ này không đông đâu, khoảng mười phút là mua xong vé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L363_07','V363','阮明',7,'好，我马上过去人工窗口办理，感谢指引。','hǎo， wǒ mǎ shàng guò qù rén gōng chuāng kǒu bàn lǐ， gǎn xiè zhǐ yǐn。','Vâng, tôi qua quầy thủ công làm ngay đây, cảm ơn anh đã chỉ dẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT364','S124','Đổi vé tàu cao tốc vì thay đổi lịch trình',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V364','SIT364','P1','suon_se','ban_chinh_thuc',NULL,'高铁车票发车前可免费改签一次，仅变更乘车时间，目的地不变无需额外付费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_01','V364','阮明',1,'您好，我买了明天上午的高铁票，想改签成下午班次。','nín hǎo， wǒ mǎi le míng tiān shàng wǔ de gāo tiě piào， xiǎng gǎi qiān chéng xià wǔ bān cì。','Chào chị, tôi có mua vé tàu cao tốc sáng mai, giờ muốn đổi sang chuyến buổi chiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_02','V364','售票员',2,'出示购票用的护照，我帮你查询余票情况哈。','chū shì gòu piào yòng de hù zhào， wǒ bāng nǐ chá xún yú piào qíng kuàng hā。','Anh đưa hộ chiếu lúc mua vé ra, để tôi tra giúp anh tình trạng vé còn trống nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_03','V364','阮明',3,'改签需要额外收取手续费吗？','gǎi qiān xū yào é wài shōu qǔ shǒu xù fèi ma？','Đổi vé có phải trả thêm phí gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_04','V364','售票员',4,'发车前免费改签一次，第二次改签才会收费呢。','fā chē qián miǎn fèi gǎi qiān yī cì， dì èr cì gǎi qiān cái huì shōu fèi ne。','Trước giờ tàu chạy thì đổi vé lần đầu miễn phí, lần thứ hai mới tính phí đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_05','V364','阮明',5,'下午三点那趟还有空余座位对吧？','xià wǔ sān diǎn nà tàng hái yǒu kòng yú zuò wèi duì ba？','Chuyến ba giờ chiều vẫn còn chỗ trống đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_06','V364','售票员',6,'还有二等座，我直接帮你更改车次信息。','hái yǒu èr děng zuò， wǒ zhí jiē bāng nǐ gēng gǎi chē cì xìn xī。','Vẫn còn ghế hạng hai, để tôi đổi luôn thông tin chuyến tàu cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L364_07','V364','阮明',7,'辛苦你了，行程临时变动实在不好意思。','xīn kǔ nǐ le， xíng chéng lín shí biàn dòng shí zài bù hǎo yì sī。','Cảm ơn chị vất vả rồi, lịch trình thay đổi đột xuất thật ngại quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT365','S125','Đặt taxi đi khám bệnh gấp',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V365','SIT365','P1','suon_se','ban_chinh_thuc',NULL,'网约车支持目的地精准定位，紧急就医可备注需求，司机会优先规划快速路线。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_01','V365','阮明',1,'师傅麻烦快一点，我身体不舒服要赶去医院啊。','shī fù má fán kuài yì diǎn， wǒ shēn tǐ bù shū fú yào gǎn qù yī yuàn a。','Bác tài làm ơn đi nhanh giúp em một chút, em thấy khó chịu trong người cần đến bệnh viện gấp ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_02','V365','司机',2,'放心，我避开堵车路段，尽量缩短路上时间。','fàng xīn， wǒ bì kāi dǔ chē lù duàn， jǐn liàng suō duǎn lù shàng shí jiān。','Yên tâm đi, tôi sẽ tránh mấy đoạn kẹt xe, cố gắng rút ngắn thời gian trên đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_03','V365','阮明',3,'到医院正门下车，不用停地下车库可以吧？','dào yī yuàn zhèng mén xià chē， bù yòng tíng dì xià chē kù kě yǐ ba？','Bác cho em xuống ngay cổng chính bệnh viện, không cần vào bãi đỗ xe ngầm được không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_04','V365','司机',4,'没问题，正门临时上下客区域可以短暂停靠。','méi wèn tí， zhèng mén lín shí shàng xià kè qū yù kě yǐ duǎn zàn tíng kào。','Được chứ, khu vực đón trả khách tạm thời ở cổng chính có thể dừng một lát.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_05','V365','阮明',5,'我头晕得厉害，麻烦开车平稳一点呢。','wǒ tóu yūn dé lì hài， má fán kāi chē píng wěn yì diǎn ne。','Em thấy chóng mặt dữ lắm, bác lái xe êm êm một chút giúp em nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_06','V365','司机',6,'我放慢车速，有不舒服你随时跟我说。','wǒ fàng màn chē sù， yǒu bù shū fú nǐ suí shí gēn wǒ shuō。','Tôi sẽ chạy chậm lại, có khó chịu gì cứ nói với tôi ngay nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L365_07','V365','阮明',7,'太感谢师傅体谅我，到地方我立刻付款。','tài gǎn xiè shī fù tǐ liàng wǒ， dào dì fāng wǒ lì kè fù kuǎn。','Cảm ơn bác thông cảm cho em nhiều lắm, tới nơi em thanh toán ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT366','S120','Hỏi giờ chuyến xe buýt cuối cùng trong ngày',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V366','SIT366','P1','twist','tuy_y',NULL,'公交末班时间会根据工作日、节假日临时调整，站台工作人员可实时查询当日运营时刻。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_01','V366','阮明',1,'您好，请问18路公交今晚末班车几点发车呀？','nín hǎo， qǐng wèn 18 lù gōng jiāo jīn wǎn mò bān chē jǐ diǎn fā chē ya？','Chào anh, cho em hỏi chuyến xe buýt số 18 tối nay xe cuối chạy mấy giờ vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_02','V366','工作人员',2,'平常九点半，今天线路临时调整，九点就收班了嘛。','píng cháng jiǔ diǎn bàn， jīn tiān xiàn lù lín shí diào zhěng， jiǔ diǎn jiù shōu bān le ma。','Bình thường là chín rưỡi, hôm nay tuyến đổi lịch tạm thời, chín giờ là hết chuyến rồi đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_03','V366','阮明',3,'这么早？那错过这趟车还有别的换乘路线吗？','zhè me zǎo？ nà cuò guò zhè tàng chē hái yǒu bié de huàn chéng lù xiàn ma？','Sớm vậy sao? Vậy lỡ chuyến này thì còn tuyến nào chuyển xe khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_04','V366','工作人员',4,'可以转地铁，地铁末班车十一点才停运。','kě yǐ zhuǎn dì tiě， dì tiě mò bān chē shí yì diǎn cái tíng yùn。','Có thể đi tàu điện ngầm, chuyến cuối của tàu điện ngầm mười một giờ mới ngừng chạy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_05','V366','阮明',5,'步行到地铁站大概需要几分钟呢？','bù xíng dào dì tiě zhàn dà gài xū yào jǐ fēn zhōng ne？','Đi bộ ra ga tàu điện ngầm mất khoảng mấy phút vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_06','V366','工作人员',6,'七八分钟，顺着人行道直走就能看见入口。','qī bā fēn zhōng， shùn zhe rén xíng dào zhí zǒu jiù néng kàn jiàn rù kǒu。','Bảy tám phút thôi, cứ đi thẳng theo vỉa hè là thấy lối vào ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L366_07','V366','阮明',7,'好，那我提前出发去坐地铁，多谢告知。','hǎo， nà wǒ tí qián chū fā qù zuò dì tiě， duō xiè gào zhī。','Dạ, vậy em đi sớm để kịp bắt tàu điện ngầm, cảm ơn anh đã chỉ giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT367','S121','Hỏi lối ra gần nhất tới địa điểm cần đến',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V367','SIT367','P1','suon_se','tuy_y',NULL,'大型商场划分专门网约车上下客出口，普通主干道禁止车辆临时停靠，避免拥堵。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_01','V367','阮明',1,'师傅，我想打车，最近的商场出口往哪边走呢？','shī fù， wǒ xiǎng dǎ chē， zuì jìn de shāng chǎng chū kǒu wǎng nǎ biān zǒu ne？','Anh ơi, tôi muốn bắt taxi, lối ra gần nhất của trung tâm thương mại đi hướng nào vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_02','V367','安保人员',2,'直走到中庭右转，一号门就是打车专用出口哦。','zhí zǒu dào zhōng tíng yòu zhuǎn， yī hào mén jiù shì dǎ chē zhuān yòng chū kǒu ó。','Đi thẳng đến sảnh giữa rồi rẽ phải, cửa số 1 chính là lối ra dành riêng cho taxi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_03','V367','阮明',3,'一号门外面有专门的等候区域吧？','yī hào mén wài miàn yǒu zhuān mén de děng hòu qū yù ba？','Bên ngoài cửa số 1 có khu vực chờ riêng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_04','V367','安保人员',4,'有的，路边不能随便停车，只能在指定区域等车。','yǒu de， lù biān bù néng suí biàn tíng chē， zhǐ néng zài zhǐ dìng qū yù děng chē。','Có chứ, ven đường không được đỗ xe tùy tiện đâu, chỉ đợi xe ở khu vực chỉ định thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_05','V367','阮明',5,'我拎了不少东西，这条路线没有台阶对吗？','wǒ līn le bù shǎo dōng xī， zhè tiáo lù xiàn méi yǒu tái jiē duì ma？','Tôi xách khá nhiều đồ, đường này không có bậc thềm đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_06','V367','安保人员',6,'全程平坦通道，推行李箱、拎重物都方便。','quán chéng píng tǎn tōng dào， tuī xíng lǐ xiāng、 līn zhòng wù dōu fāng biàn。','Toàn bộ là lối đi bằng phẳng, kéo vali hay xách đồ nặng đều thuận tiện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L367_07','V367','阮明',7,'清楚了，麻烦你指路啦。','qīng chǔ le， má fán nǐ zhǐ lù la。','Rõ rồi ạ, làm phiền anh chỉ đường nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT368','S123','Trả xe thuê trễ giờ, hỏi phụ phí',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V368','SIT368','P1','twist','ban_chinh_thuc',NULL,'共享电单车设置固定免费时长，超时产生溢价费用，平台优惠券一般仅抵扣基础租赁费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_01','V368','阮明',1,'你好，我租的共享电车超时半小时，要补多少钱？','nǐ hǎo， wǒ zū de gòng xiǎng diàn chē chāo shí bàn xiǎo shí， yào bǔ duō shǎo qián？','Chào anh, xe điện chia sẻ tôi thuê trễ nửa tiếng, phải bù thêm bao nhiêu tiền ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_02','V368','运维员',2,'基础时长两小时，超出后每半小时加收五元哈。','jī chǔ shí cháng liǎng xiǎo shí， chāo chū hòu měi bàn xiǎo shí jiā shōu wǔ yuán hā。','Thời gian cơ bản hai tiếng, quá giờ mỗi nửa tiếng tính thêm năm tệ nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_03','V368','阮明',3,'页面提示有超时罚款，不能直接抵扣优惠券嘛？','yè miàn tí shì yǒu chāo shí fá kuǎn， bù néng zhí jiē dǐ kòu yōu huì quàn ma？','Trên màn hình báo phạt trễ giờ, không dùng mã giảm giá để trừ trực tiếp được à?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_04','V368','运维员',4,'超时产生的额外费用不支持优惠券抵扣的。','chāo shí chǎn shēng de é wài fèi yòng bù zhī chí yōu huì quàn dǐ kòu de。','Phí phát sinh do trễ giờ không áp dụng mã giảm giá được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_05','V368','阮明',5,'原来是这样，那我直接微信扫码支付就行？','yuán lái shì zhè yàng， nà wǒ zhí jiē wēi xìn sǎo mǎ zhī fù jiù xíng？','Ra là vậy, vậy tôi quét mã QR bằng WeChat thanh toán luôn là được chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_06','V368','运维员',6,'对，站点二维码扫码就能结清所有费用。','duì， zhàn diǎn èr wéi mǎ sǎo mǎ jiù néng jié qīng suǒ yǒu fèi yòng。','Đúng rồi, quét mã QR tại trạm là thanh toán hết mọi khoản phí luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L368_07','V368','阮明',7,'好，我马上付款，下次一定看好还车时限。','hǎo， wǒ mǎ shàng fù kuǎn， xià cì yí dìng kàn hǎo hái chē shí xiàn。','Được, tôi thanh toán ngay đây, lần sau nhất định để ý thời hạn trả xe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT369','S126','Báo mất hộ chiếu với cảnh sát',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V369','SIT369','P1','suon_se','chinh_thuc',NULL,'外籍人士丢失护照必须先到派出所开具遗失报案回执，再前往出入境大厅办理临时通行证明，后续可凭回执到本国驻华大使馆补办正式护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_01','V369','阮明',1,'警官您好，我想报案，我的护照不小心弄丢了，情况挺紧急的。','jǐng guān nín hǎo ， wǒ xiǎng bào àn ， wǒ de hù zhào bù xiǎo xīn nòng diū le ， qíng kuàng tǐng jǐn jí de 。','Chào anh công an, em muốn trình báo, hộ chiếu của em bị mất rồi ạ, tình hình khá gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_02','V369','民警',2,'你先冷静一下，不用着急。先告诉我你的基本信息，姓名、国籍、在校身份都说一下。','nǐ xiān lěng jìng yī xià ， bù yòng zháo jí 。 xiān gào sù wǒ nǐ de jī běn xìn xī ， xìng míng 、 guó jí 、 zài xiào shēn fèn dōu shuō yī xià 。','Em bình tĩnh lại đã, không cần vội. Trước tiên cho anh biết thông tin cơ bản của em, họ tên, quốc tịch, thông tin trường học đều nói qua nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_03','V369','阮明',3,'我叫阮明，是越南人，今年二十二岁，在这边的大学读汉语言专业。','wǒ jiào ruǎn míng ， shì yuè nán rén ， jīn nián èr shí èr suì ， zài zhè biān de dà xué dú hàn yǔ yán zhuān yè 。','Em tên Nguyễn Minh, là người Việt Nam, năm nay 22 tuổi, đang học ngành tiếng Trung ở trường đại học bên này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_04','V369','民警',4,'好，那你详细说一下今天的出行路线，从出门到发现护照丢失，完整讲一遍。','hǎo ， nà nǐ xiáng xì shuō yī xià jīn tiān de chū xíng lù xiàn ， cóng chū mén dào fā xiàn hù zhào diū shī ， wán zhěng jiǎng yī biàn 。','Được, vậy em kể chi tiết lộ trình đi lại hôm nay xem, từ lúc ra khỏi nhà đến khi phát hiện mất hộ chiếu, kể đầy đủ cho anh nghe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_05','V369','阮明',5,'我中午十二点从学校宿舍出门，先去路边小吃店吃了午饭，下午两点到了市中心商业街逛街。','wǒ zhōng wǔ shí èr diǎn cóng xué xiào sù shè chū mén ， xiān qù lù biān xiǎo chī diàn chī le wǔ fàn ， xià wǔ liǎng diǎn dào le shì zhōng xīn shāng yè jiē guàng jiē 。','Trưa mười hai giờ em ra khỏi ký túc xá trường, trước tiên đến quán ăn vặt ven đường ăn trưa, hai giờ chiều thì đến phố thương mại trung tâm thành phố dạo phố.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_06','V369','民警',6,'商业街范围太大了，这个时间段没法锁定线索。你仔细想想，具体是哪家店、大概几点丢的？','shāng yè jiē fàn wéi tài dà le ， zhè ge shí jiān duàn méi fǎ suǒ dìng xiàn suǒ 。 nǐ zǐ xì xiǎng xiǎng ， jù tǐ shì nǎ jiā diàn 、 dà gài jǐ diǎn diū de ？','Phố thương mại phạm vi rộng quá, khoảng thời gian này khó mà xác định manh mối được. Em nghĩ kỹ lại xem, cụ thể là cửa hàng nào, mất vào khoảng mấy giờ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_07','V369','阮明',7,'我记得是下午三点左右，在商业街二楼的文具店结完账，走出店没多久，摸口袋就发现护照没了。','wǒ jì de shì xià wǔ sān diǎn zuǒ yòu ， zài shāng yè jiē èr lóu de wén jù diàn jié wán zhàng ， zǒu chū diàn méi duō jiǔ ， mō kǒu dài jiù fā xiàn hù zhào méi le 。','Em nhớ là khoảng ba giờ chiều, sau khi thanh toán ở cửa hàng văn phòng phẩm tầng hai của phố thương mại, đi ra khỏi cửa hàng chưa lâu thì sờ túi phát hiện hộ chiếu không còn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_08','V369','民警',8,'丢了之后你有没有当场找过？或者找店里工作人员帮忙、调监控看过？','diū le zhī hòu nǐ yǒu méi yǒu dāng chǎng zhǎo guò ？ huò zhě zhǎo diàn lǐ gōng zuò rén yuán bāng máng 、 diào jiān kòng kàn guò ？','Sau khi mất em có tìm ngay tại chỗ không? Hoặc có nhờ nhân viên cửa hàng giúp, xem lại camera giám sát chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_09','V369','阮明',9,'我马上回去问店员了，他们没捡到。而且店里说监控不能随便给个人看，需要派出所开证明才行。','wǒ mǎ shàng huí qù wèn diàn yuán le ， tā men méi jiǎn dào 。 ér qiě diàn lǐ shuō jiān kòng bù néng suí biàn gěi gè rén kàn ， xū yào pài chū suǒ kāi zhèng míng cái xíng 。','Em quay lại hỏi nhân viên cửa hàng ngay, nhưng họ không nhặt được. Với lại cửa hàng nói camera không thể tùy tiện cho cá nhân xem, cần công an phường cấp giấy xác nhận mới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_10','V369','民警',10,'了解了。那我现在给你做遗失报案笔录，你需要填写国籍、护照编号、学校这些详细信息。','liǎo jiě le 。 nà wǒ xiàn zài gěi nǐ zuò yí shī bào àn bǐ lù ， nǐ xū yào tián xiě guó jí 、 hù zhào biān hào 、 xué xiào zhè xiē xiáng xì xìn xī 。','Anh hiểu rồi. Vậy bây giờ anh lập biên bản trình báo mất giấy tờ cho em, em cần điền quốc tịch, số hộ chiếu, tên trường và các thông tin chi tiết khác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_11','V369','阮明',11,'没问题，我手机里存了护照的复印件，我可以照着直接填，信息都齐全。','méi wèn tí ， wǒ shǒu jī lǐ cún le hù zhào de fù yìn jiàn ， wǒ kě yǐ zhào zhe zhí jiē tián ， xìn xī dōu qí quán 。','Không vấn đề gì ạ, trong điện thoại em có lưu bản sao hộ chiếu, em có thể nhìn vào đó điền trực tiếp, thông tin đầy đủ hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_12','V369','民警',12,'行，你慢慢填，填完核对无误签字就行，我之后给你打印报案回执。','xíng ， nǐ màn màn tián ， tián wán hé duì wú wù qiān zì jiù xíng ， wǒ zhī hòu gěi nǐ dǎ yìn bào àn huí zhí 。','Được, em cứ từ từ điền, điền xong kiểm tra không sai thì ký tên là được, sau đó anh in biên nhận trình báo cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_13','V369','阮明',13,'好的警官。对了，拿到这份回执，是不是就可以去出入境大厅办临时通行证件了？','hǎo de jǐng guān 。 duì le ， ná dào zhè fèn huí zhí ， shì bú shì jiù kě yǐ qù chū rù jìng dà tīng bàn lín shí tōng xíng zhèng jiàn le ？','Dạ vâng ạ. À đúng rồi, có được biên nhận này rồi thì em có thể đến phòng xuất nhập cảnh làm giấy tờ thông hành tạm thời được chưa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_14','V369','民警',14,'对的，外籍人员遗失护照，我们开具的报案回执是补办证件、办理临时通行证明的必备材料。','duì de ， wài jí rén yuán yí shī hù zhào ， wǒ men kāi jù de bào àn huí zhí shì bǔ bàn zhèng jiàn 、 bàn lǐ lín shí tōng xíng zhèng míng de bì bèi cái liào 。','Đúng vậy, người nước ngoài mất hộ chiếu thì biên nhận trình báo do chúng tôi cấp là giấy tờ bắt buộc để làm lại giấy tờ, xin cấp giấy thông hành tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_15','V369','阮明',15,'辛苦您了，给您添麻烦了。','xīn kǔ nín le ， gěi nín tiān má fán le 。','Cảm ơn anh vất vả rồi ạ, làm phiền anh quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L369_16','V369','民警',16,'没事，这是我们的本职工作。后续补办证件有任何问题，随时再来咨询。','méi shì ， zhè shì wǒ men de běn zhí gōng zuò 。 hòu xù bǔ bàn zhèng jiàn yǒu rèn hé wèn tí ， suí shí zài lái zī xún 。','Không sao, đây là công việc của chúng tôi mà. Sau này làm lại giấy tờ có vấn đề gì thì cứ đến hỏi bất cứ lúc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT370','S126','Báo mất ví tiền nơi công cộng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V370','SIT370','P1','twist','ban_chinh_thuc',NULL,'商场、餐厅等公共场所设有失物招领处，捡到私人物品大多会统一送至前台保管；领取失物需要核对专属标识确认归属。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_01','V370','Nguyễn Minh',1,'你好，我刚才在三楼餐饮区吃饭，钱包好像落在那儿了。','nǐ hǎo ， wǒ gāng cái zài sān lóu cān yǐn qū chī fàn ， qián bāo hǎo xiàng luò zài nà ér le 。','Chào chị, lúc nãy em ăn ở khu ẩm thực tầng ba, hình như em để quên ví ở đó rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_02','V370','Nhân viên',2,'黑色的还是什么颜色？大概什么时候的事？','hēi sè de hái shì shén me yán sè ？ dà gài shén me shí hòu de shì ？','Ví màu đen hay màu gì vậy em? Khoảng mấy giờ thì để quên?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_03','V370','Nguyễn Minh',3,'黑色，短款的，就……刚才，可能十分钟前吧。','hēi sè ， duǎn kuǎn de ， jiù …… gāng cái ， kě néng shí fēn zhōng qián ba 。','Màu đen, dáng ngắn, khoảng... lúc nãy thôi, chắc mười phút trước ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_04','V370','Nhân viên',4,'三楼餐饮区……现在还没有人上交类似的物品呢。','sān lóu cān yǐn qū …… xiàn zài hái méi yǒu rén shàng jiāo lèi sì de wù pǐn ne 。','Khu ẩm thực tầng ba à... hiện giờ chưa có ai nộp lại món đồ giống vậy cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_05','V370','Nguyễn Minh',5,'啊？那怎么办，里面还有银行卡和我的居留卡呢。','a ？ nà zěn me bàn ， lǐ miàn hái yǒu yín háng kǎ hé wǒ de jū liú kǎ ne 。','Ơ? Vậy phải làm sao đây, trong ví còn có thẻ ngân hàng với thẻ cư trú của em nữa.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_06','V370','Nhân viên',6,'先别急，我广播一下，你顺便说说钱包里还有什么，方便核对。','xiān bié jí ， wǒ guǎng bō yī xià ， nǐ shùn biàn shuō shuō qián bāo lǐ hái yǒu shén me ， fāng biàn hé duì 。','Em đừng vội, để chị thông báo qua loa xem, tiện thể em nói rõ trong ví còn có gì để dễ đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_07','V370','Nguyễn Minh',7,'现金大概两百多，还有一张学生卡，卡上有照片的。','xiàn jīn dà gài liǎng bǎi duō ， hái yǒu yī zhāng xué shēng kǎ ， kǎ shàng yǒu zhào piān de 。','Tiền mặt khoảng hơn hai trăm, còn có một thẻ sinh viên, trên thẻ có ảnh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_08','V370','Nhân viên',8,'好，广播先发出去了，你在服务台这边等一下吧。','hǎo ， guǎng bō xiān fā chū qù le ， nǐ zài fú wù tái zhè biān děng yí xià ba 。','Được, chị thông báo qua loa rồi đó, em đợi ở quầy dịch vụ này một lát nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_09','V370','Nguyễn Minh',9,'好……','hǎo ……','Vâng ạ...',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_10','V370','Nhân viên',10,'刚才保洁说捡到一个钱包，不过她说是深棕色的。','gāng cái bǎo jié shuō jiǎn dào yí gè qián bāo ， bù guò tā shuō shì shēn zōng sè de 。','Lúc nãy cô lao công nói nhặt được một cái ví, nhưng cô ấy bảo là màu nâu sẫm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_11','V370','Nguyễn Minh',11,'那不是我的……我的是纯黑色，会不会是别人的？','nà bú shì wǒ de …… wǒ de shì chún hēi sè ， huì bú huì shì bié rén de ？','Vậy không phải của em rồi... ví của em màu đen tuyền, hay là của người khác nhỉ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_12','V370','Nhân viên',12,'那可能不是同一个，我再问问三楼其他区域。','nà kě néng bú shì tóng yī gè ， wǒ zài wèn wèn sān lóu qí tā qū yù 。','Vậy chắc không phải cùng một cái rồi, để chị hỏi thêm các khu vực khác ở tầng ba xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_13','V370','Nguyễn Minh',13,'好吧，那我再等等。','hǎo ba ， nà wǒ zài děng děng 。','Vâng, vậy em đợi thêm chút nữa.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_14','V370','Nhân viên',14,'找到了，是黑色的，刚有顾客路过捡到直接交给保安了。','zhǎo dào le ， shì hēi sè de ， gāng yǒu gù kè lù guò jiǎn dào zhí jiē jiāo gěi bǎo ān le 。','Tìm thấy rồi, là ví màu đen, vừa có khách đi ngang qua nhặt được và giao ngay cho bảo vệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_15','V370','Nguyễn Minh',15,'太好了！我现在能上去拿吗？','tài hǎo le ！ wǒ xiàn zài néng shàng qù ná ma ？','Tuyệt quá ạ! Bây giờ em lên lấy được chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L370_16','V370','Nhân viên',16,'一楼保安室，你带上证件核对一下就行。','yī lóu bǎo ān shì ， nǐ dài shàng zhèng jiàn hé duì yī xià jiù xíng 。','Phòng bảo vệ ở tầng một, em mang theo giấy tờ tùy thân để đối chiếu là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT371','S126','Báo mất điện thoại, xin khóa SIM từ xa',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V371','SIT371','P1','suon_se','chinh_thuc',NULL,'手机丢失后可致电运营商紧急挂失SIM卡，补办卡片可保留原有手机号，不会更换号码；首次挂失补卡大多免除工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_01','V371','阮明',1,'您好，我手机弄丢了，情况紧急，想申请远程锁定我的SIM卡。','nín hǎo ， wǒ shǒu jī nòng diū le ， qíng kuàng jǐn jí ， xiǎng shēn qǐng yuǎn chéng suǒ dìng wǒ de SIM kǎ 。','Chào chị, điện thoại của em bị mất rồi, tình huống khá gấp, em muốn đăng ký khóa SIM từ xa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_02','V371','客服',2,'您好，理解您的紧急情况。挂失锁卡需要核验实名信息，请您配合提供相关资料。','nín hǎo ， lǐ jiě nín de jǐn jí qíng kuàng 。 guà shī suǒ kǎ xū yào hé yàn shí míng xìn xī ， qǐng nín pèi hé tí gōng xiāng guān zī liào 。','Chào anh, tôi hiểu tình huống khẩn cấp của anh. Để báo mất và khóa SIM cần xác minh thông tin chính chủ, mong anh phối hợp cung cấp thông tin liên quan.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_03','V371','阮明',3,'我知道的，您需要什么信息直接说，我全部如实提供。','wǒ zhī dào de ， nín xū yào shén me xìn xī zhí jiē shuō ， wǒ quán bù rú shí tí gōng 。','Em biết ạ, chị cần thông tin gì cứ nói thẳng, em sẽ cung cấp đầy đủ và trung thực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_04','V371','客服',4,'麻烦依次报一下您遗失的手机号、实名登记姓名，还有完整的护照编号。','má fán yī cì bào yī xià nín yí shī de shǒu jī hào 、 shí míng dēng jì xìng míng ， hái yǒu wán zhěng de hù zhào biān hào 。','Phiền anh đọc lần lượt số điện thoại bị mất, họ tên đăng ký chính chủ, và số hộ chiếu đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_05','V371','阮明',5,'好的，我这些信息都存在手机备忘录里，我现在逐一念给您核对。','hǎo de ， wǒ zhè xiē xìn xī dōu cún zài shǒu jī bèi wàng lù lǐ ， wǒ xiàn zài zhú yī niàn gěi nín hé duì 。','Vâng, những thông tin này em có lưu trong ghi chú điện thoại, để em đọc từng cái một cho chị đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_06','V371','客服',6,'收到，信息全部核验一致，系统已经成功为您办理SIM卡紧急挂失锁定，他人无法使用您的号码。','shōu dào ， xìn xī quán bù hé yàn yí zhì ， xì tǒng yǐ jīng chéng gōng wèi nín bàn lǐ SIM kǎ jǐn jí guà shī suǒ dìng ， tā rén wú fǎ shǐ yòng nín de hào mǎ 。','Đã nhận được, thông tin đối chiếu khớp hết, hệ thống đã khóa khẩn cấp SIM của anh thành công, người khác sẽ không thể sử dụng số của anh nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_07','V371','阮明',7,'那就好。我想问一下，锁卡之后，我手机里的支付软件、社交账号就安全了吧？不会被盗用吧？','nà jiù hǎo 。 wǒ xiǎng wèn yī xià ， suǒ kǎ zhī hòu ， wǒ shǒu jī lǐ de zhī fù ruǎn jiàn 、 shè jiāo zhàng hào jiù ān quán le ba ？ bú huì bèi dào yòng ba ？','Vậy thì tốt rồi. Em muốn hỏi thêm, sau khi khóa SIM thì các ứng dụng thanh toán, tài khoản mạng xã hội trong điện thoại của em có an toàn không ạ? Sẽ không bị lợi dụng chứ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_08','V371','客服',8,'是的，SIM卡锁定后无法接收验证码，能最大程度规避账户被盗、资金被盗刷的风险。','shì de ，SIM kǎ suǒ dìng hòu wú fǎ jiē shōu yàn zhèng mǎ ， néng zuì dà chéng dù guī bì zhàng hù bèi dào 、 zī jīn bèi dào shuā de fēng xiǎn 。','Đúng vậy, sau khi khóa SIM thì không thể nhận mã xác minh nữa, sẽ giảm thiểu tối đa nguy cơ tài khoản bị đánh cắp, tiền bị rút trộm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_09','V371','阮明',9,'我还有个疑问，这个挂失是临时的对吧？之后我补办新卡，还能保留原来的手机号吗？','wǒ hái yǒu gè yí wèn ， zhè ge guà shī shì lín shí de duì ba ？ zhī hòu wǒ bǔ bàn xīn kǎ ， hái néng bǎo liú yuán lái de shǒu jī hào ma ？','Em còn một thắc mắc nữa, việc báo mất này là tạm thời đúng không ạ? Sau này em làm lại SIM mới thì có giữ được số điện thoại cũ không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_10','V371','客服',10,'可以的，您本人携带护照去任意线下营业厅，都可以补办同号的SIM卡。','kě yǐ de ， nín běn rén xié dài hù zhào qù rèn yì xiàn xià yíng yè tīng ， dōu kě yǐ bǔ bàn tóng hào de SIM kǎ 。','Được ạ, anh chỉ cần mang hộ chiếu đến bất kỳ cửa hàng giao dịch nào là có thể làm lại SIM cùng số.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_11','V371','阮明',11,'那补办需要花钱吗？是免费的还是要交工本费？','nà bǔ bàn xū yào huā qián ma ？ shì miǎn fèi de hái shì yào jiāo gōng běn fèi ？','Vậy làm lại SIM có mất tiền không ạ? Miễn phí hay phải đóng phí làm thẻ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_12','V371','客服',12,'首次挂失补卡是免收工本费的，只有一年内多次补办，才会收取相关费用。','shǒu cì guà shī bǔ kǎ shì miǎn shōu gōng běn fèi de ， zhǐ yǒu yī nián nèi duō cì bǔ bàn ， cái huì shōu qǔ xiāng guān fèi yòng 。','Lần đầu báo mất và làm lại SIM thì miễn phí, chỉ khi trong vòng một năm làm lại nhiều lần mới bị tính phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_13','V371','阮明',13,'原来是这样，我都清楚了，太感谢您帮忙紧急冻结卡号了。','yuán lái shì zhè yàng ， wǒ dōu qīng chǔ le ， tài gǎn xiè nín bāng máng jǐn jí dòng jié kǎ hào le 。','Ra là vậy, em rõ hết rồi ạ, cảm ơn chị nhiều vì đã giúp khóa khẩn cấp số của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L371_14','V371','客服',14,'不用客气，后续补办有任何疑问，随时拨打我们的官方热线咨询即可。','bù yòng kè qì ， hòu xù bǔ bàn yǒu rèn hé yí wèn ， suí shí bō dǎ wǒ men de guān fāng rè xiàn zī xún jí kě 。','Không có gì, sau này làm lại có thắc mắc gì thì cứ gọi đường dây nóng chính thức của chúng tôi để được tư vấn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT372','S126','Gọi số cấp cứu khi có người bị thương',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V372','SIT372','P1','suon_se','chinh_thuc',NULL,'国内急救电话120免费拨打，接线员会同步指导简单急救措施，并快速调配就近医院车辆；伤者骨折、出血不可随意挪动，防止二次伤害。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_01','V372','阮明',1,'您好！麻烦快点，这边有人摔倒受伤了，需要救护车！','nín hǎo ！ má fán kuài diǎn ， zhè biān yǒu rén shuāi dǎo shòu shāng le ， xū yào jiù hù chē ！','Alo! Xin nhanh lên giúp, ở đây có người bị ngã bị thương, cần xe cứu thương gấp!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_02','V372','接线员',2,'请您先保持冷静，不要慌张。告诉我准确的事发地址，还有伤者的具体情况。','qǐng nín xiān bǎo chí lěng jìng ， bú yào huāng zhāng 。 gào sù wǒ zhǔn què de shì fā dì zhǐ ， hái yǒu shāng zhě de jù tǐ qíng kuàng 。','Anh/chị bình tĩnh lại đã, đừng hoảng. Cho tôi biết địa chỉ chính xác nơi xảy ra sự việc, và tình trạng cụ thể của người bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_03','V372','阮明',3,'地点在大学南门的沿街小吃街，有人下楼梯摔下去了，腿流了很多血，现在站不起来。','dì diǎn zài dà xué nán mén de yán jiē xiǎo chī jiē ， yǒu rén xià lóu tī shuāi xià qù le ， tuǐ liú le hěn duō xuè ， xiàn zài zhàn bù qǐ lái 。','Địa điểm ở phố ăn vặt ven đường phía cổng nam trường đại học, có người bị ngã cầu thang, chân chảy rất nhiều máu, giờ không đứng dậy được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_04','V372','接线员',4,'切记千万不要挪动、拖拽伤者，很容易造成二次骨折损伤。救护车十分钟内就能到现场。','qiè jì qiān wàn bú yào nuó dòng 、 tuō zhuāi shāng zhě ， hěn róng yì zào chéng èr cì gǔ zhé sǔn shāng 。 jiù hù chē shí fēn zhōng nèi jiù néng dào xiàn chǎng 。','Nhớ kỹ tuyệt đối không được di chuyển, kéo lê người bị thương, rất dễ gây gãy xương lần hai. Xe cứu thương sẽ đến trong vòng mười phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_05','V372','阮明',5,'好的好的，我不碰他！我马上站在路口显眼的地方等着，给救护车引路。','hǎo de hǎo de ， wǒ bù pèng tā ！ wǒ mǎ shàng zhàn zài lù kǒu xiǎn yǎn de dì fāng děng zhe ， gěi jiù hù chē yǐn lù 。','Vâng vâng, em sẽ không đụng vào người đó! Em sẽ đứng ngay ở chỗ dễ thấy đầu đường đợi để dẫn đường cho xe cứu thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_06','V372','接线员',6,'辛苦您了，全程保持电话畅通。如果伤者出血量变大、意识变差，一定要立刻告诉我。','xīn kǔ nín le ， quán chéng bǎo chí diàn huà chàng tōng 。 rú guǒ shāng zhě chū xiě liàng biàn dà 、 yì shí biàn chà ， yí dìng yào lì kè gào sù wǒ 。','Cảm ơn anh/chị đã vất vả, giữ điện thoại thông suốt trong suốt quá trình. Nếu người bị thương chảy máu nhiều hơn hoặc ý thức kém đi thì phải báo ngay cho tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_07','V372','阮明',7,'我明白，我现在用纸巾帮他按压伤口止血，目前人还是清醒的，没有迷糊。','wǒ míng bái ， wǒ xiàn zài yòng zhǐ jīn bāng tā àn yā shāng kǒu zhǐ xuè ， mù qián rén hái shì qīng xǐng de ， méi yǒu mí hū 。','Em hiểu rồi, em đang dùng khăn giấy ấn lên vết thương để cầm máu cho người đó, hiện tại người vẫn tỉnh táo, không lơ mơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_08','V372','接线员',8,'很好，就保持持续按压止血，尽量减少失血，等待医护人员到场。','hěn hǎo ， jiù bǎo chí chí xù àn yā zhǐ xuè ， jǐn liàng jiǎn shǎo shī xuè ， děng dài yī hù rén yuán dào chǎng 。','Tốt lắm, cứ giữ ấn liên tục để cầm máu, cố gắng giảm thiểu mất máu, chờ nhân viên y tế đến.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_09','V372','阮明',9,'我会注意的，绝对不随便移动伤者，按照您说的做。','wǒ huì zhù yì de ， jué duì bù suí biàn yí dòng shāng zhě ， àn zhào nín shuō de zuò 。','Em sẽ chú ý, tuyệt đối không tùy tiện di chuyển người bị thương, em sẽ làm theo lời chị dặn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_10','V372','接线员',10,'救护车已经从医院出发了，距离现场只剩三分钟路程。','jiù hù chē yǐ jīng cóng yī yuàn chū fā le ， jù lí xiàn chǎng zhǐ shèng sān fēn zhōng lù chéng 。','Xe cứu thương đã xuất phát từ bệnh viện rồi, chỉ còn cách hiện trường ba phút đường đi thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_11','V372','阮明',11,'太好了，我现在就在校门口马路边等着，一会挥手示意车辆。','tài hǎo le ， wǒ xiàn zài jiù zài xiào mén kǒu mǎ lù biān děng zhe ， yī huì huī shǒu shì yì chē liàng 。','Tốt quá ạ, em đang đứng ở ven đường cổng trường đợi, lát nữa em sẽ vẫy tay ra hiệu cho xe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_12','V372','接线员',12,'辛苦您现场帮忙看护，医护人员马上抵达。','xīn kǔ nín xiàn chǎng bāng máng kān hù ， yī hù rén yuán mǎ shàng dǐ dá 。','Cảm ơn anh/chị đã vất vả trông chừng tại chỗ, nhân viên y tế sắp đến nơi rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L372_13','V372','阮明',13,'好，我一直在这等着。','hǎo ， wǒ yì zhí zài zhè děng zhe 。','Vâng, em sẽ đứng đây đợi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT373','S126','Báo cháy nhỏ trong khu bếp chung ký túc',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V373','SIT373','P1','twist','ban_chinh_thuc',NULL,'油锅起火严禁浇水，正确方式为隔绝氧气盖锅盖；国内宿舍厨房明令禁止无人看管明火，无人值守属于违规行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_01','V373','阮明',1,'宿管老师，不好了！公共厨房刚刚着火了！不过我已经把燃气总阀关掉了。','sù guǎn lǎo shī ， bù hǎo le ！ gōng gòng chú fáng gāng gāng zháo huǒ le ！ bù guò wǒ yǐ jīng bǎ rán qì zǒng fá guān diào le 。','Cô ơi, không hay rồi! Bếp chung vừa mới bị cháy! Nhưng em đã tắt van tổng gas rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_02','V373','宿管老师',2,'着火了？你先别靠近灶台！我先问你，你有没有直接往火上浇水？','zháo huǒ le ？ nǐ xiān bié kào jìn zào tái ！ wǒ xiān wèn nǐ ， nǐ yǒu méi yǒu zhí jiē wǎng huǒ shàng jiāo shuǐ ？','Cháy à? Em đừng lại gần bếp nấu vội! Cô hỏi trước đã, em có đổ nước trực tiếp lên lửa không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_03','V373','阮明',3,'没有没有！我参加过宿舍安全培训，知道油锅起火不能泼水，我马上拿锅盖把锅盖住，隔绝氧气灭火了。','méi yǒu méi yǒu ！ wǒ cān jiā guò sù shè ān quán péi xùn ， zhī dào yóu guō qǐ huǒ bù néng pō shuǐ ， wǒ mǎ shàng ná guō gài bǎ guō gài zhù ， gé jué yǎng qì miè huǒ le 。','Không có ạ, không có! Em từng tham gia tập huấn an toàn ký túc xá, biết chảo dầu bốc cháy thì không được đổ nước, em lấy nắp đậy chảo lại ngay để cách ly oxy dập lửa rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_04','V373','宿管老师',4,'还好你懂常识，没乱操作，不然火势一下子就蔓延开了。我现在拿灭火器马上过去。','hái hǎo nǐ dǒng cháng shí ， méi luàn cāo zuò ， bù rán huǒ shì yī xià zi jiù màn yán kāi le 。 wǒ xiàn zài ná miè huǒ qì mǎ shàng guò qù 。','May mà em biết kiến thức cơ bản, không xử lý bừa, chứ không thì lửa đã lan nhanh rồi. Cô lấy bình cứu hỏa qua ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_05','V373','阮明',5,'明火已经灭了，就是墙面有点被熏黑。我刚刚看了一圈，橱柜、纸巾这些易燃物都没烧到，应该没事吧？','míng huǒ yǐ jīng miè le ， jiù shì qiáng miàn yǒu diǎn bèi xūn hēi 。 wǒ gāng gāng kàn le yī quān ， chú guì 、 zhǐ jīn zhè xiē yì rán wù dōu méi shāo dào ， yīng gāi méi shì ba ？','Ngọn lửa đã tắt rồi ạ, chỉ là tường bị ám khói đen một chút thôi. Em vừa nhìn quanh một vòng, tủ bếp, giấy vệ sinh mấy thứ dễ cháy đều không bị cháy tới, chắc không sao đâu ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_06','V373','宿管老师',6,'先别大意，厨房火情最怕复燃，不能光看表面。你确定锅里完全没有余火、火星了吗？','xiān bié dà yì ， chú fáng huǒ qíng zuì pà fù rán ， bù néng guāng kàn biǎo miàn 。 nǐ què dìng guō lǐ wán quán méi yǒu yú huǒ 、 huǒ xīng le ma ？','Đừng chủ quan vội, cháy bếp sợ nhất là bùng lại, không thể chỉ nhìn bề ngoài. Em chắc chắn trong nồi hoàn toàn không còn tàn lửa, tia lửa nào chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_07','V373','阮明',7,'我仔细看过了，锅里彻底凉了，没有一点火星。这次是我的问题，我熬汤的时候走开了几分钟，水烧干才着的火。','wǒ zǐ xì kàn guò le ， guō lǐ chè dǐ liáng le ， méi yǒu yì diǎn huǒ xīng 。 zhè cì shì wǒ de wèn tí ， wǒ áo tāng de shí hòu zǒu kāi le jǐ fēn zhōng ， shuǐ shāo gàn cái zhe de huǒ 。','Em xem kỹ rồi ạ, trong nồi nguội hẳn rồi, không còn chút tia lửa nào. Lần này là lỗi của em, lúc ninh canh em rời đi vài phút, nước cạn hết mới bị cháy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_08','V373','宿管老师',8,'我就说，宿舍公共厨房明文规定，用火必须有人看管，无人值守本来就是违规的，特别容易出事。','wǒ jiù shuō ， sù shè gōng gòng chú fáng míng wén guī dìng ， yòng huǒ bì xū yǒu rén kān guǎn ， wú rén zhí shǒu běn lái jiù shì wéi guī de ， tè bié róng yì chū shì 。','Cô đã nói rồi, bếp chung ký túc xá có quy định rõ ràng, dùng lửa bắt buộc phải có người trông, không có ai trông coi vốn dĩ đã là vi phạm rồi, rất dễ xảy ra chuyện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_09','V373','阮明',9,'我知道错了，以后做饭绝对不擅自离开灶台了，一定全程看着。','wǒ zhī dào cuò le ， yǐ hòu zuò fàn jué duì bù shàn zì lí kāi zào tái le ， yí dìng quán chéng kàn zhe 。','Em biết lỗi rồi ạ, sau này nấu ăn tuyệt đối sẽ không tự ý rời khỏi bếp nữa, nhất định sẽ trông coi suốt quá trình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_10','V373','宿管老师',10,'我马上到现场仔细检查一遍，确认没有复燃隐患，大家才能继续用厨房。','wǒ mǎ shàng dào xiàn chǎng zǐ xì jiǎn chá yī biàn ， què rèn méi yǒu fù rán yǐn huàn ， dà jiā cái néng jì xù yòng chú fáng 。','Cô sẽ đến hiện trường kiểm tra kỹ ngay, xác nhận không còn nguy cơ bùng cháy lại thì mọi người mới được tiếp tục dùng bếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_11','V373','阮明',11,'老师，需要我留在这边配合您检查、说明情况吗？','lǎo shī ， xū yào wǒ liú zài zhè biān pèi hé nín jiǎn chá 、 shuō míng qíng kuàng ma ？','Cô ơi, em có cần ở lại đây phối hợp cô kiểm tra, trình bày tình hình không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_12','V373','宿管老师',12,'不用，你直接来值班室等着就行，我检查完跟你说后续的注意事项。','bù yòng ， nǐ zhí jiē lái zhí bān shì děng zhe jiù xíng ， wǒ jiǎn chá wán gēn nǐ shuō hòu xù de zhù yì shì xiàng 。','Không cần, em cứ đến phòng trực đợi là được, cô kiểm tra xong sẽ nói với em những điều cần lưu ý sau đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_13','V373','阮明',13,'实在抱歉，给您添麻烦了，都是我的疏忽。','shí zài bào qiàn ， gěi nín tiān má fán le ， dōu shì wǒ de shū hū 。','Em thật sự xin lỗi, làm phiền cô rồi, đều là do em sơ suất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L373_14','V373','宿管老师',14,'吸取教训就好，宿舍安全永远是第一位的，不用太自责。','xī qǔ jiào xùn jiù hǎo ， sù shè ān quán yǒng yuǎn shì dì yī wèi de ， bù yòng tài zì zé 。','Rút kinh nghiệm là được rồi, an toàn ký túc xá luôn là ưu tiên hàng đầu, em không cần tự trách mình quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT374','S126','Trình báo tai nạn giao thông nhẹ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V374','SIT374','P1','suon_se','chinh_thuc',NULL,'无人员伤亡的轻微交通事故，可通过交管平台线上处理，无需等待交警到场；外籍当事人护照可作为辅助身份凭证上传备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_01','V374','阮明',1,'您好，我要报备一起交通事故，主干道十字路口两车轻微剐蹭，没有人受伤。','nín hǎo ， wǒ yào bào bèi yì qǐ jiāo tōng shì gù ， zhǔ gàn dào shí zì lù kǒu liǎng chē qīng wēi guǎ cèng ， méi yǒu rén shòu shāng 。','Chào anh, tôi muốn trình báo một vụ tai nạn giao thông, hai xe va quẹt nhẹ ở ngã tư đường chính, không có ai bị thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_02','V374','交警接线员',2,'您好，我跟你说两个关键步骤，你们先把车挪到路边非机动车道，不要堵路，然后多角度拍好现场照片留存证据。','nín hǎo ， wǒ gēn nǐ shuō liǎng gè guān jiàn bù zhòu ， nǐ men xiān bǎ chē nuó dào lù biān fēi jī dòng chē dào ， bú yào dǔ lù ， rán hòu duō jiǎo dù pāi hǎo xiàn chǎng zhào piān liú cún zhèng jù 。','Chào anh/chị, tôi hướng dẫn hai bước quan trọng nhé, trước tiên hai bên di chuyển xe vào làn đường không cơ giới ven đường, không để chắn đường, sau đó chụp ảnh hiện trường ở nhiều góc độ để lưu làm bằng chứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_03','V374','阮明',3,'好的，我们已经把车停到不影响交通的位置了，前后、侧面、碰撞点的照片都拍齐全了。','hǎo de ， wǒ men yǐ jīng bǎ chē tíng dào bù yǐng xiǎng jiāo tōng de wèi zhì le ， qián hòu 、 cè miàn 、 pèng zhuàng diǎn de zhào piān dōu pāi qí quán le 。','Vâng, chúng tôi đã đỗ xe vào vị trí không ảnh hưởng giao thông rồi, ảnh chụp mặt trước, sau, bên hông, điểm va chạm đều đã chụp đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_04','V374','交警接线员',4,'无人员伤亡的轻微剐蹭事故，不用我们线下出警，直接在交管线上平台就能快速定责处理。','wú rén yuán shāng wáng de qīng wēi guǎ cèng shì gù ， bù yòng wǒ men xiàn xià chū jǐng ， zhí jiē zài jiāo guǎn xiàn shàng píng tái jiù néng kuài sù dìng zé chǔ lǐ 。','Vụ va quẹt nhẹ không có thương vong thì không cần chúng tôi đến hiện trường, chỉ cần làm trực tiếp trên nền tảng trực tuyến của cơ quan giao thông là có thể xác định trách nhiệm nhanh chóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_05','V374','阮明',5,'了解了。那线上处理需要上传哪些证件？我是外国留学生，我的护照可以当作有效证件用吗？','liǎo jiě le 。 nà xiàn shàng chǔ lǐ xū yào shàng chuán nǎ xiē zhèng jiàn ？ wǒ shì wài guó liú xué shēng ， wǒ de hù zhào kě yǐ dàng zuò yǒu xiào zhèng jiàn yòng ma ？','Tôi hiểu rồi. Vậy xử lý trực tuyến cần tải lên những giấy tờ gì? Tôi là du học sinh nước ngoài, hộ chiếu của tôi có thể dùng làm giấy tờ hợp lệ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_06','V374','交警接线员',6,'可以的，完全没问题。需要上传机动车行驶证、驾驶员驾驶证，再加上你的护照照片即可。','kě yǐ de ， wán quán méi wèn tí 。 xū yào shàng chuán jī dòng chē xíng shǐ zhèng 、 jià shǐ yuán jià shǐ zhèng ， zài jiā shàng nǐ de hù zhào zhào piān jí kě 。','Được ạ, hoàn toàn không vấn đề gì. Anh/chị cần tải lên giấy đăng ký xe, bằng lái xe của người điều khiển, cộng thêm ảnh hộ chiếu của anh/chị là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_07','V374','阮明',7,'那定责之后，理赔也是线上操作吗？不用跑去交警大队线下办理吧？','nà dìng zé zhī hòu ， lǐ péi yě shì xiàn shàng cāo zuò ma ？ bù yòng pǎo qù jiāo jǐng dà duì xiàn xià bàn lǐ ba ？','Vậy sau khi xác định trách nhiệm rồi, việc bồi thường cũng làm trực tuyến à? Không cần chạy đến đội cảnh sát giao thông làm trực tiếp chứ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_08','V374','交警接线员',8,'对的，全责方的保险公司会线上对接理赔，全程线上办结，不用线下跑腿。','duì de ， quán zé fāng de bǎo xiǎn gōng sī huì xiàn shàng duì jiē lǐ péi ， quán chéng xiàn shàng bàn jié ， bù yòng xiàn xià pǎo tuǐ 。','Đúng vậy, công ty bảo hiểm của bên chịu trách nhiệm hoàn toàn sẽ kết nối bồi thường trực tuyến, xử lý xong toàn bộ qua mạng, không cần đi lại trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_09','V374','阮明',9,'太好了，那我现在就和对方车主整理证件照片，马上上传小程序。','tài hǎo le ， nà wǒ xiàn zài jiù hé duì fāng chē zhǔ zhěng lǐ zhèng jiàn zhào piān ， mǎ shàng shàng chuán xiǎo chéng xù 。','Tốt quá, vậy bây giờ tôi sẽ cùng chủ xe bên kia chuẩn bị ảnh giấy tờ, tải lên ứng dụng ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_10','V374','交警接线员',10,'上传之后等待系统线上审核就行，一般半小时内就会出具责任认定书。','shàng chuán zhī hòu děng dài xì tǒng xiàn shàng shěn hé jiù xíng ， yì bān bàn xiǎo shí nèi jiù huì chū jù zé rèn rèn dìng shū 。','Sau khi tải lên chỉ cần chờ hệ thống thẩm định trực tuyến là được, thường trong nửa tiếng sẽ có văn bản xác định trách nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_11','V374','阮明',11,'好的，流程我都清楚了。','hǎo de ， liú chéng wǒ dōu qīng chǔ le 。','Vâng, tôi đã rõ hết quy trình rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_12','V374','交警接线员',12,'后续如果理赔有纠纷，随时拨打热线咨询。','hòu xù rú guǒ lǐ péi yǒu jiū fēn ， suí shí bō dǎ rè xiàn zī xún 。','Sau này nếu có tranh chấp về bồi thường, cứ gọi đường dây nóng để được tư vấn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L374_13','V374','阮明',13,'明白，谢谢您。','míng bái ， xiè xiè nín 。','Tôi hiểu rồi, cảm ơn anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT375','S126','Trình báo bị lừa chuyển tiền qua mạng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V375','SIT375','P1','twist','chinh_thuc',NULL,'遭遇网络诈骗第一时间联系反诈中心冻结对方账户，再线下报案，是国内标准维权流程；完整聊天、转账截图是关键办案证据，不可删除。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_01','V375','阮明',1,'您好，我被网络诈骗了！被虚假客服诱导转了账，钱已经转出去了，能不能帮忙拦截一下？','nín hǎo ， wǒ bèi wǎng luò zhà piàn le ！ bèi xū jiǎ kè fú yòu dǎo zhuǎn liǎo zhàng ， qián yǐ jīng zhuǎn chū qù le ， néng bù néng bāng máng lán jié yī xià ？','Alo, tôi bị lừa đảo qua mạng rồi! Bị nhân viên chăm sóc khách hàng giả mạo dụ chuyển khoản, tiền đã chuyển đi rồi, có thể giúp tôi chặn lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_02','V375','反诈客服',2,'您先别慌，立刻告诉我三个关键信息：对方的收款账号、准确的转账时间、还有转账总金额。','nín xiān bié huāng ， lì kè gào sù wǒ sān gè guān jiàn xìn xī ： duì fāng de shōu kuǎn zhàng hào 、 zhǔn què de zhuǎn zhàng shí jiān 、 hái yǒu zhuǎn zhàng zǒng jīn é 。','Anh/chị bình tĩnh đã, cho tôi biết ngay ba thông tin quan trọng: số tài khoản nhận tiền của đối phương, thời gian chuyển khoản chính xác, và tổng số tiền đã chuyển.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_03','V375','阮明',3,'好的好的，我马上找记录！我转完账一秒就反应过来是骗子了，想撤回交易，但是系统提示撤回失败。','hǎo de hǎo de ， wǒ mǎ shàng zhǎo jì lù ！ wǒ zhuǎn wán zhàng yī miǎo jiù fǎn yìng guò lái shì piàn zi le ， xiǎng chè huí jiāo yì ， dàn shì xì tǒng tí shì chè huí shī bài 。','Vâng vâng, tôi tìm lịch sử giao dịch ngay! Vừa chuyển xong tôi nhận ra ngay là bị lừa, muốn hủy giao dịch nhưng hệ thống báo hủy không thành công.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_04','V375','反诈客服',4,'我先跟您说明一下，资金一旦成功转入私人账户，用户是无法自主撤回的，我现在立刻提交冻结指令，锁定对方账户。','wǒ xiān gēn nín shuō míng yī xià ， zī jīn yí dàn chéng gōng zhuǎn rù sī rén zhàng hù ， yòng hù shì wú fǎ zì zhǔ chè huí de ， wǒ xiàn zài lì kè tí jiāo dòng jié zhǐ lìng ， suǒ dìng duì fāng zhàng hù 。','Tôi giải thích trước với anh/chị, một khi tiền đã chuyển thành công vào tài khoản cá nhân thì người dùng không thể tự hủy được, bây giờ tôi sẽ gửi lệnh phong tỏa ngay để khóa tài khoản của đối phương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_05','V375','阮明',5,'啊？那还能追回吗？冻结之后，我转出去的钱还有机会找回来吗？','a ？ nà hái néng zhuī huí ma ？ dòng jié zhī hòu ， wǒ zhuǎn chū qù de qián hái yǒu jī huì zhǎo huí lái ma ？','Ơ? Vậy còn lấy lại được không? Sau khi phong tỏa, số tiền tôi đã chuyển đi có cơ hội tìm lại được không?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_06','V375','反诈客服',6,'只能冻结对方账户里还没被转走的剩余资金，已经流转的资金需要后续配合警方追查。现在最关键的是你要去派出所做报案笔录留存证据。','zhǐ néng dòng jié duì fāng zhàng hù lǐ hái méi bèi zhuǎn zǒu de shèng yú zī jīn ， yǐ jīng liú zhuǎn de zī jīn xū yào hòu xù pèi hé jǐng fāng zhuī chá 。 xiàn zài zuì guān jiàn de shì nǐ yào qù pài chū suǒ zuò bào àn bǐ lù liú cún zhèng jù 。','Chỉ có thể phong tỏa số tiền còn lại chưa bị chuyển đi trong tài khoản đối phương, số tiền đã lưu chuyển thì cần phối hợp với công an điều tra sau. Bây giờ quan trọng nhất là anh/chị phải đến đồn công an lập biên bản trình báo để lưu bằng chứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_07','V375','阮明',7,'那我要去哪个派出所？需要带什么证件过去办理？','nà wǒ yào qù nǎ ge pài chū suǒ ？ xū yào dài shén me zhèng jiàn guò qù bàn lǐ ？','Vậy tôi phải đến đồn công an nào? Cần mang giấy tờ gì đến làm thủ tục?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_08','V375','反诈客服',8,'带上你的本人护照，去你就近的辖区派出所就行，工作人员会对接我们反诈中心留存线索。','dài shàng nǐ de běn rén hù zhào ， qù nǐ jiù jìn de xiá qū pài chū suǒ jiù xíng ， gōng zuò rén yuán huì duì jiē wǒ men fǎn zhà zhōng xīn liú cún xiàn suǒ 。','Mang theo hộ chiếu của anh/chị, đến đồn công an khu vực gần nhất là được, nhân viên ở đó sẽ kết nối với trung tâm chống lừa đảo của chúng tôi để lưu manh mối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_09','V375','阮明',9,'做完笔录之后，警方会一直跟进追查这个诈骗账户吗？','zuò wán bǐ lù zhī hòu ， jǐng fāng huì yì zhí gēn jìn zhuī chá zhè ge zhà piàn zhàng hù ma ？','Sau khi lập biên bản xong, công an có tiếp tục theo dõi điều tra tài khoản lừa đảo này không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_10','V375','反诈客服',10,'会的，所有涉案线索都会登记备案，警方会持续追踪资金流向，尽力帮你挽回损失。','huì de ， suǒ yǒu shè àn xiàn suǒ dōu huì dēng jì bèi àn ， jǐng fāng huì chí xù zhuī zōng zī jīn liú xiàng ， jìn lì bāng nǐ wǎn huí sǔn shī 。','Có ạ, tất cả manh mối liên quan đến vụ việc đều sẽ được ghi nhận lưu hồ sơ, công an sẽ tiếp tục theo dõi dòng tiền, cố gắng hết sức giúp anh/chị giảm thiểu thiệt hại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_11','V375','阮明',11,'好，我马上查附近派出所地址，现在就过去报案。','hǎo ， wǒ mǎ shàng chá fù jìn pài chū suǒ dì zhǐ ， xiàn zài jiù guò qù bào àn 。','Vâng, tôi sẽ tra ngay địa chỉ đồn công an gần đây, đi trình báo luôn bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_12','V375','反诈客服',12,'一定要保存好所有证据，转账截图、聊天记录都不要删除，办案需要用到。','yí dìng yào bǎo cún hǎo suǒ yǒu zhèng jù ， zhuǎn zhàng jié tú 、 liáo tiān jì lù dōu bú yào shān chú ， bàn àn xū yào yòng dào 。','Nhất định phải lưu giữ toàn bộ bằng chứng, ảnh chụp màn hình chuyển khoản, lịch sử trò chuyện đều không được xóa, sẽ cần dùng đến khi xử lý vụ việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_13','V375','阮明',13,'我都存好了，一份没删。','wǒ dōu cún hǎo le ， yī fèn méi shān 。','Tôi lưu hết rồi, không xóa cái nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L375_14','V375','反诈客服',14,'后续案件的进展，派出所会第一时间通知你。','hòu xù àn jiàn de jìn zhǎn ， pài chū suǒ huì dì yī shí jiān tōng zhī nǐ 。','Về sau có tiến triển gì của vụ án, đồn công an sẽ thông báo cho anh/chị ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT376','S126','Báo khóa cửa phòng bị hỏng, không vào được phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V376','SIT376','P1','suon_se','ban_chinh_thuc',NULL,'出租公寓门锁自然老化损坏，物业免费上门维修；租客人为撬动、暴力损坏门锁，则需自行支付配件与工时费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_01','V376','阮明',1,'师傅您好，我公寓的门锁坏了，钥匙插进去转不动，我进不去房间了。','shī fù nín hǎo ， wǒ gōng yù de mén suǒ huài le ， yào shi chā jìn qù zhuǎn bù dòng ， wǒ jìn bù qù fáng jiān le 。','Chào chú, khóa cửa căn hộ của em bị hỏng rồi, tra chìa vào mà xoay không được, em không vào phòng được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_02','V376','维修专员',2,'我先问清楚情况，你之前有没有用力掰钥匙、大力敲门锁之类的操作？','wǒ xiān wèn qīng chǔ qíng kuàng ， nǐ zhī qián yǒu méi yǒu yòng lì bāi yào shi 、 dà lì qiāo mén suǒ zhī lèi de cāo zuò ？','Để chú hỏi rõ tình hình đã nhé, trước đó em có bẻ mạnh chìa khóa hay đập mạnh vào ổ khóa gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_03','V376','阮明',3,'没有的，我都是轻轻插钥匙、慢慢转，一点暴力操作都没有，完全不是我人为弄坏的。','méi yǒu de ， wǒ dōu shì qīng qīng chā yào shi 、 màn màn zhuǎn ， yì diǎn bào lì cāo zuò dōu méi yǒu ， wán quán bú shì wǒ rén wéi nòng huài de 。','Dạ không có ạ, em toàn tra chìa nhẹ nhàng rồi xoay từ từ thôi, không hề dùng lực mạnh, tuyệt đối không phải do em làm hỏng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_04','V376','维修专员',4,'行，那你先在楼下单元门等着，我带上工具，十分钟之内到你楼下。','xíng ， nà nǐ xiān zài lóu xià dān yuán mén děng zhe ， wǒ dài shàng gōng jù ， shí fēn zhōng zhī nèi dào nǐ lóu xià 。','Được rồi, vậy em cứ đứng chờ ở cửa tòa nhà tầng dưới nhé, chú mang đồ nghề qua, trong vòng mười phút là tới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_05','V376','阮明',5,'师傅，我补充一下，我家里三把备用钥匙我都试过了，全都转不动，锁芯应该是彻底卡死了。','shī fù ， wǒ bǔ chōng yī xià ， wǒ jiā lǐ sān bǎ bèi yòng yào shi wǒ dōu shì guò le ， quán dōu zhuǎn bù dòng ， suǒ xīn yīng gāi shì chè dǐ kǎ sǐ le 。','Chú ơi, em bổ sung thêm là ba chiếc chìa khóa dự phòng ở nhà em đều đã thử qua rồi, đều xoay không được, chắc ổ khóa bị kẹt cứng luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_06','V376','维修专员',6,'我大概清楚了，大概率是锁芯内部零件老化断裂，这种情况一般需要直接更换整套门锁。','wǒ dà gài qīng chǔ le ， dà gài lǜ shì suǒ xīn nèi bù líng jiàn lǎo huà duàn liè ， zhè zhǒng qíng kuàng yì bān xū yào zhí jiē gēng huàn zhěng tào mén suǒ 。','Chú hiểu sơ sơ rồi, khả năng cao là linh kiện bên trong ổ khóa bị lão hóa gãy rồi, trường hợp này thường phải thay nguyên bộ khóa cửa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_07','V376','阮明',7,'那我想问一下，换锁的配件费和人工费，是需要我自己出吗？','nà wǒ xiǎng wèn yī xià ， huàn suǒ de pèi jiàn fèi hé rén gōng fèi ， shì xū yào wǒ zì jǐ chū ma ？','Vậy cho em hỏi, tiền linh kiện với tiền công thay khóa thì em có phải tự chi trả không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_08','V376','维修专员',8,'这个要看损坏原因。房子设施自然老化故障，物业免费修；如果是租客暴力损坏，才需要自费。','zhè ge yào kàn sǔn huài yuán yīn 。 fáng zi shè shī zì rán lǎo huà gù zhàng ， wù yè miǎn fèi xiū ； rú guǒ shì zū kè bào lì sǔn huài ， cái xū yào zì fèi 。','Cái này còn tùy nguyên nhân hư hỏng. Nếu thiết bị nhà tự nhiên xuống cấp thì bên quản lý sửa miễn phí; còn nếu do người thuê làm hỏng do dùng lực mạnh thì mới phải tự bỏ tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_09','V376','阮明',9,'我真的全程轻轻操作，没有磕碰撬动，这肯定是自然老化吧？','wǒ zhēn de quán chéng qīng qīng cāo zuò ， méi yǒu kē pèng qiào dòng ， zhè kěn dìng shì zì rán lǎo huà ba ？','Em thao tác nhẹ nhàng suốt từ đầu đến cuối, không hề va đập hay cạy phá gì cả, chắc chắn là do tự nhiên xuống cấp rồi đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_10','V376','维修专员',10,'我到现场看过锁体磨损情况才能最终判定，只要是自然老化，你不用花一分钱。','wǒ dào xiàn chǎng kàn guò suǒ tǐ mó sǔn qíng kuàng cái néng zuì zhōng pàn dìng ， zhǐ yào shì zì rán lǎo huà ， nǐ bù yòng huā yī fēn qián 。','Chú phải đến tận nơi xem tình trạng mòn của ổ khóa mới kết luận chính xác được, nhưng nếu đúng là do lão hóa tự nhiên thì em không phải trả một đồng nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_11','V376','阮明',11,'好的，那我就在楼下等着您。','hǎo de ， nà wǒ jiù zài lóu xià děng zhe nín 。','Dạ vâng, vậy em đứng chờ chú ở dưới nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L376_12','V376','维修专员',12,'马上出发，到了我给你打电话。','mǎ shàng chū fā ， dào le wǒ gěi nǐ dǎ diàn huà 。','Chú xuất phát ngay đây, tới nơi chú gọi điện cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT377','S126','Xin cấp lại giấy tờ tạm thời khi mất hộ chiếu',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V377','SIT377','P1','twist','chinh_thuc',NULL,'外籍留学生护照丢失后，出入境大厅可开具临时通行证明，用于回国或补办护照；现场自助拍照符合涉外证件标准，无需提前线下照相馆拍摄。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_01','V377','阮明',1,'您好，我的越南护照不小心弄丢了，想来这边办理临时出入境通行证明。','nín hǎo ， wǒ de yuè nán hù zhào bù xiǎo xīn nòng diū le ， xiǎng lái zhè biān bàn lǐ lín shí chū rù jìng tōng xíng zhèng míng 。','Chào chị, hộ chiếu Việt Nam của em không may bị mất rồi, em muốn đến làm giấy chứng nhận xuất nhập cảnh tạm thời ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_02','V377','工作人员',2,'办理临时通行证明需要两样必备材料，派出所开的遗失回执，还有一寸白底证件照。','bàn lǐ lín shí tōng xíng zhèng míng xū yào liǎng yàng bì bèi cái liào ， pài chū suǒ kāi de yí shī huí zhí ， hái yǒu yī cùn bái dǐ zhèng jiàn zhào 。','Để làm giấy chứng nhận tạm thời cần hai loại giấy tờ bắt buộc, đó là biên nhận trình báo mất do công an phường cấp, và ảnh thẻ nền trắng cỡ một tấc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_03','V377','阮明',3,'派出所的回执我带了，一直揣在身上。但是太着急过来，我忘记准备证件照了。','pài chū suǒ de huí zhí wǒ dài le ， yì zhí chuāi zài shēn shàng 。 dàn shì tài zháo jí guò lái ， wǒ wàng jì zhǔn bèi zhèng jiàn zhào le 。','Biên nhận của công an phường em có mang theo, luôn giữ bên người. Nhưng vì vội quá nên em quên chuẩn bị ảnh thẻ mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_04','V377','工作人员',4,'没带也没关系，我们大厅入口有自助拍照机，专门拍涉外证件照片，规格都是达标，二十元一套。','méi dài yě méi guān xì ， wǒ men dà tīng rù kǒu yǒu zì zhù pāi zhào jī ， zhuān mén pāi shè wài zhèng jiàn zhào piān ， guī gé dōu shì dá biāo ， èr shí yuán yī tào 。','Không mang theo cũng không sao, ở lối vào sảnh có máy chụp ảnh tự động, chuyên chụp ảnh giấy tờ cho người nước ngoài, quy cách đều đạt chuẩn, hai mươi tệ một bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_05','V377','阮明',5,'那太好了。我拍完照片、提交所有材料，今天能直接拿到临时证明吗？','nà tài hǎo le 。 wǒ pāi wán zhào piān 、 tí jiāo suǒ yǒu cái liào ， jīn tiān néng zhí jiē ná dào lín shí zhèng míng ma ？','Vậy tốt quá ạ. Sau khi em chụp ảnh xong và nộp đầy đủ giấy tờ, hôm nay có thể lấy được giấy chứng nhận tạm thời luôn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_06','V377','工作人员',6,'材料齐全的话，窗口是当场办结出证的，不用排队等候。','cái liào qí quán de huà ， chuāng kǒu shì dāng chǎng bàn jié chū zhèng de ， bù yòng pái duì děng hòu 。','Nếu giấy tờ đầy đủ thì quầy sẽ xử lý và cấp ngay tại chỗ, không cần xếp hàng chờ đợi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_07','V377','阮明',7,'我再确认一下，这个临时证明有效期多久？可以用来回国、补办护照吗？','wǒ zài què rèn yī xià ， zhè ge lín shí zhèng míng yǒu xiào qī duō jiǔ ？ kě yǐ yòng lái huí guó 、 bǔ bàn hù zhào ma ？','Em xác nhận lại nhé, giấy chứng nhận tạm thời này có hiệu lực bao lâu ạ? Có thể dùng để về nước hay làm lại hộ chiếu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_08','V377','工作人员',8,'有效期三十天，既可以用来搭乘国际航班出境回国，也能用于去驻华大使馆补办正式护照。','yǒu xiào qī sān shí tiān ， jì kě yǐ yòng lái dā chéng guó jì háng bān chū jìng huí guó ， yě néng yòng yú qù zhù huá dà shǐ guǎn bǔ bàn zhèng shì hù zhào 。','Hiệu lực ba mươi ngày, vừa có thể dùng để lên chuyến bay quốc tế về nước, vừa có thể dùng để đến đại sứ quán làm lại hộ chiếu chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_09','V377','阮明',9,'没问题，那我现在去拍照，拍完马上回来交材料。','méi wèn tí ， nà wǒ xiàn zài qù pāi zhào ， pāi wán mǎ shàng huí lái jiāo cái liào 。','Không vấn đề gì, vậy giờ em đi chụp ảnh, chụp xong em quay lại nộp giấy tờ ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_10','V377','工作人员',10,'你拍照的时候注意核对一下人像清晰度和尺寸，不合格的话需要重拍，耽误时间。','nǐ pāi zhào de shí hòu zhù yì hé duì yī xià rén xiàng qīng xī dù hé chǐ cùn ， bù hé gé de huà xū yào chóng pāi ， dān wù shí jiān 。','Lúc chụp ảnh em chú ý kiểm tra kỹ độ nét của khuôn mặt và kích thước ảnh nhé, nếu không đạt sẽ phải chụp lại, mất thời gian lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_11','V377','阮明',11,'好，我一定仔细核对，保证照片合格。','hǎo ， wǒ yí dìng zǐ xì hé duì ， bǎo zhèng zhào piān hé gé 。','Dạ, em nhất định sẽ kiểm tra kỹ, đảm bảo ảnh đạt chuẩn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L377_12','V377','工作人员',12,'拍完直接去三号窗口递交材料就行。','pāi wán zhí jiē qù sān hào chuāng kǒu dì jiāo cái liào jiù xíng 。','Chụp xong thì đến thẳng quầy số ba nộp giấy tờ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT378','S126','Liên hệ đại sứ quán khi gặp sự cố nghiêm trọng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V378','SIT378','P1','suon_se','chinh_thuc',NULL,'外籍公民在中国发生重大人身意外，可联系本国驻华大使馆获取领事协助，包含对接家属、证件补办、事故手续协调等服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_01','V378','阮明',1,'您好，我是在中国读书的越南留学生，我遇到了严重的交通事故，想寻求大使馆的帮助。','nín hǎo ， wǒ shì zài zhōng guó dú shū de yuè nán liú xué shēng ， wǒ yù dào le yán zhòng de jiāo tōng shì gù ， xiǎng xún qiú dà shǐ guǎn de bāng zhù 。','Xin chào, tôi là du học sinh Việt Nam đang học tại Trung Quốc, tôi vừa gặp một vụ tai nạn giao thông nghiêm trọng, muốn nhờ đại sứ quán giúp đỡ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_02','V378','接线员',2,'您好，请您保持冷静，依次告诉我您的姓名、就读学校，还有事故发生的具体地点。','nín hǎo ， qǐng nín bǎo chí lěng jìng ， yī cì gào sù wǒ nín de xìng míng 、 jiù dú xué xiào ， hái yǒu shì gù fā shēng de jù tǐ dì diǎn 。','Chào bạn, mong bạn giữ bình tĩnh, hãy lần lượt cho tôi biết họ tên, trường đang theo học, và địa điểm cụ thể xảy ra tai nạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_03','V378','阮明',3,'我叫阮明，在本市高校读汉语言专业。事故发生在市中心主干道十字路口，现在交警和救护车都已经到现场处理了。','wǒ jiào ruǎn míng ， zài běn shì gāo xiào dú hàn yǔ yán zhuān yè 。 shì gù fā shēng zài shì zhōng xīn zhǔ gàn dào shí zì lù kǒu ， xiàn zài jiāo jǐng hé jiù hù chē dōu yǐ jīng dào xiàn chǎng chǔ lǐ le 。','Tôi tên Nguyễn Minh, đang học ngành tiếng Trung tại một trường đại học ở thành phố này. Tai nạn xảy ra ở ngã tư trục đường chính trung tâm thành phố, hiện cảnh sát giao thông và xe cứu thương đã có mặt xử lý rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_04','V378','接线员',4,'收到，我们会立刻对接当地辖区交警大队，跟进本次事故的全部处置流程，协助你处理后续手续。','shōu dào ， wǒ men huì lì kè duì jiē dāng dì xiá qū jiāo jǐng dà duì ， gēn jìn běn cì shì gù de quán bù chǔ zhì liú chéng ， xié zhù nǐ chǔ lǐ hòu xù shǒu xù 。','Đã nhận được thông tin, chúng tôi sẽ lập tức liên hệ với đội cảnh sát giao thông khu vực sở tại, theo sát toàn bộ quá trình xử lý vụ việc này, hỗ trợ bạn giải quyết các thủ tục tiếp theo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_05','V378','阮明',5,'我想咨询一下，后续的治疗、证件补办，还有联系我国内家属这些事，大使馆都能帮忙协助吗？','wǒ xiǎng zī xún yī xià ， hòu xù de zhì liáo 、 zhèng jiàn bǔ bàn ， hái yǒu lián xì wǒ guó nèi jiā shǔ zhè xiē shì ， dà shǐ guǎn dōu néng bāng máng xié zhù ma ？','Tôi muốn hỏi thêm, việc điều trị sau này, làm lại giấy tờ, rồi liên hệ với người thân trong nước của tôi, những việc đó đại sứ quán có thể hỗ trợ được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_06','V378','接线员',6,'可以的。本国公民在境外遭遇重大人身意外，驻华大使馆都会提供全套的领事协助服务，涵盖你说的这些事宜。','kě yǐ de 。 běn guó gōng mín zài jìng wài zāo yù zhòng dà rén shēn yì wài ， zhù huá dà shǐ guǎn dōu huì tí gōng quán tào de lǐng shì xié zhù fú wù ， hán gài nǐ shuō de zhè xiē shì yí 。','Được. Công dân nước mình gặp sự cố nghiêm trọng về thân thể ở nước ngoài thì đại sứ quán tại đây đều sẽ cung cấp đầy đủ dịch vụ hỗ trợ lãnh sự, bao gồm cả những việc bạn vừa nói.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_07','V378','阮明',7,'目前伤者还在做医护检查，伤情还没确定，后续有新情况我会再打电话汇报。','mù qián shāng zhě hái zài zuò yī hù jiǎn chá ， shāng qíng hái méi què dìng ， hòu xù yǒu xīn qíng kuàng wǒ huì zài dǎ diàn huà huì bào 。','Hiện tại người bị thương vẫn đang được kiểm tra y tế, tình trạng thương tích chưa xác định được, có tình hình mới tôi sẽ gọi điện báo lại ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_08','V378','接线员',8,'你记一下我们的官方热线，后续办理手续遇到任何难题，随时来电咨询。','nǐ jì yī xià wǒ men de guān fāng rè xiàn ， hòu xù bàn lǐ shǒu xù yù dào rèn hé nán tí ， suí shí lái diàn zī xún 。','Bạn ghi lại số đường dây nóng chính thức của chúng tôi nhé, sau này làm thủ tục gặp bất kỳ khó khăn gì cứ gọi điện hỏi bất cứ lúc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_09','V378','阮明',9,'好的，我马上保存号码。','hǎo de ， wǒ mǎ shàng bǎo cún hào mǎ 。','Vâng, tôi lưu số ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L378_10','V378','接线员',10,'祝你平安，有进展及时沟通。','zhù nǐ píng ān， yǒu jìn zhǎn jí shí gōu tōng。','Chúc bạn bình an, có tiến triển gì thì báo lại kịp thời nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT379','S127','Viết CV xin việc làm thêm bán thời gian',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V379','SIT379','P1','twist','tuy_y',NULL,'国内兼职简历注重简洁清晰，留学生求职必须标注在校合法务工资质，方便用人单位审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_01','V379','阮明',1,'溪溪，我想写简历申请中文助教兼职，不知道怎么排版啊。','xī xī， wǒ xiǎng xiě jiǎn lì shēn qǐng zhōng wén zhù jiào jiān zhí， bù zhī dào zěn me pái bǎn a。','Khê Khê, mình muốn viết CV xin làm trợ giảng tiếng Trung bán thời gian, không biết trình bày sao cho hợp lý nữa.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_02','V379','林溪',2,'简历分基础信息、语言能力、实践经历三大块就行啦。','jiǎn lì fēn jī chǔ xìn xī、 yǔ yán néng lì、 shí jiàn jīng lì sān dà kuài jiù xíng la。','CV chia thành ba phần chính là thông tin cơ bản, trình độ ngôn ngữ và kinh nghiệm thực tế là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_03','V379','阮明',3,'留学生需要额外标注签证和合法打工证明吗？','liú xué shēng xū yào é wài biāo zhù qiān zhèng hé hé fǎ dǎ gōng zhèng míng ma？','Du học sinh có cần ghi thêm visa và giấy phép làm thêm hợp pháp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_04','V379','林溪',4,'一定要写，很多商家不清楚留学生打工规定呢。','yí dìng yào xiě， hěn duō shāng jiā bù qīng chǔ liú xué shēng dǎ gōng guī dìng ne。','Nhất định phải ghi vào, nhiều nơi tuyển dụng không nắm rõ quy định làm thêm của du học sinh đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_05','V379','阮明',5,'我写完一份草稿，里面实践经历写得太简单。','wǒ xiě wán yī fèn cǎo gǎo， lǐ miàn shí jiàn jīng lì xiě dé tài jiǎn dān。','Mình viết xong một bản nháp rồi, nhưng phần kinh nghiệm thực tế viết sơ sài quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_06','V379','林溪',6,'没关系，发给我，我帮你修改补充细节。','méi guān xì， fā gěi wǒ， wǒ bāng nǐ xiū gǎi bǔ chōng xì jié。','Không sao, gửi cho mình, mình sẽ giúp sửa và bổ sung chi tiết cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L379_07','V379','阮明',7,'太谢谢你，改完我就能直接投递岗位。','tài xiè xiè nǐ， gǎi wán wǒ jiù néng zhí jiē tóu dì gǎng wèi。','Cảm ơn cậu nhiều lắm, sửa xong là mình nộp hồ sơ được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT380','S127','Trả lời phỏng vấn xin việc làm thêm',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V380','SIT380','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职面试注重实操能力与空闲时间匹配度，面试官一般会在三日内统一反馈录用结果。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_01','V380','阮明',1,'主管您好，我是阮明，今天来面试少儿汉语助教兼职。','zhǔ guǎn nín hǎo， wǒ shì ruǎn míng， jīn tiān lái miàn shì shào ér hàn yǔ zhù jiào jiān zhí。','Chào anh quản lý, tôi là Nguyễn Minh, hôm nay đến phỏng vấn vị trí trợ giảng tiếng Trung thiếu nhi bán thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_02','V380','主管',2,'请坐，先简单介绍一下你的语言水平和空闲时间吧。','qǐng zuò， xiān jiǎn dān jiè shào yī xià nǐ de yǔ yán shuǐ píng hé kòng xián shí jiān ba。','Mời ngồi, bạn giới thiệu qua trình độ ngôn ngữ và thời gian rảnh của mình nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_03','V380','阮明',3,'我汉语日常交流流利，工作日傍晚和周末全天有空呢。','wǒ hàn yǔ rì cháng jiāo liú liú lì， gōng zuò rì bàng wǎn hé zhōu mò quán tiān yǒu kòng ne。','Tôi giao tiếp tiếng Trung hàng ngày khá trôi chảy, các buổi tối trong tuần và cả ngày cuối tuần tôi đều rảnh.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_04','V380','主管',4,'你有和小朋友相处的相关经验，擅长课堂互动吗？','nǐ yǒu hé xiǎo péng yǒu xiāng chǔ de xiāng guān jīng yàn， shàn cháng kè táng hù dòng ma？','Bạn có kinh nghiệm tiếp xúc với trẻ nhỏ không, có giỏi tương tác trên lớp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_05','V380','阮明',5,'我之前在校园活动带过低龄学生，很喜欢和孩子沟通。','wǒ zhī qián zài xiào yuán huó dòng dài guò dī líng xué shēng， hěn xǐ huān hé hái zi gōu tōng。','Trước đây tôi từng phụ trách các em nhỏ trong các hoạt động ở trường, tôi rất thích giao tiếp với trẻ con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_06','V380','主管',6,'整体条件符合岗位需求，三天内通知你入职结果。','zhěng tǐ tiáo jiàn fú hé gǎng wèi xū qiú， sān tiān nèi tōng zhī nǐ rù zhí jié guǒ。','Nhìn chung điều kiện của bạn phù hợp với yêu cầu công việc, trong ba ngày sẽ báo kết quả tuyển dụng cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L380_07','V380','阮明',7,'感谢您给予面试机会，我耐心等候通知。','gǎn xiè nín jǐ yǔ miàn shì jī huì， wǒ nài xīn děng hòu tōng zhī。','Cảm ơn anh đã cho tôi cơ hội phỏng vấn, tôi sẽ kiên nhẫn chờ tin.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT381','S127','Ký hợp đồng lao động thời vụ',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V381','SIT381','P1','twist','chinh_thuc',NULL,'国内兼职临时用工必须签署劳务合同，薪资、加班、离职相关条款全部需要白纸黑字标注。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_01','V381','阮明',1,'您好，这份临时劳务合同我仔细看完，有一处想确认。','nín hǎo， zhè fèn lín shí láo wù hé tóng wǒ zǐ xì kàn wán， yǒu yī chù xiǎng què rèn。','Chào chị, tôi đã đọc kỹ bản hợp đồng lao động thời vụ này, có một chỗ muốn xác nhận lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_02','V381','人事专员',2,'你对哪一条条款有疑问，直接提出来就可以哈。','nǐ duì nǎ yī tiáo tiáo kuǎn yǒu yí wèn， zhí jiē tí chū lái jiù kě yǐ hā。','Bạn thắc mắc điều khoản nào, cứ nói thẳng ra nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_03','V381','阮明',3,'合同标注每月二十号发薪，但是没有写明加班补贴标准嘛。','hé tóng biāo zhù měi yuè èr shí hào fā xīn， dàn shì méi yǒu xiě míng jiā bān bǔ tiē biāo zhǔn ma。','Hợp đồng ghi ngày hai mươi hàng tháng trả lương, nhưng lại không nêu rõ tiêu chuẩn phụ cấp làm thêm giờ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_04','V381','人事专员',4,'加班薪资细则附在合同补充页，我拿给你核对。','jiā bān xīn zī xì zé fù zài hé tóng bǔ chōng yè， wǒ ná gěi nǐ hé duì。','Chi tiết lương làm thêm giờ được đính kèm ở trang phụ lục của hợp đồng, để tôi đưa cho bạn xem đối chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_05','V381','阮明',5,'补充条款签字之后，两份合同双方各留存一份对吧？','bǔ chōng tiáo kuǎn qiān zì zhī hòu， liǎng fèn hé tóng shuāng fāng gè liú cún yī fèn duì ba？','Sau khi ký điều khoản bổ sung, hai bên mỗi bên giữ một bản hợp đồng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_06','V381','人事专员',6,'没错，一份门店存档，一份由你本人保管。','méi cuò， yī fèn mén diàn cún dàng， yī fèn yóu nǐ běn rén bǎo guǎn。','Đúng vậy, một bản lưu tại cửa hàng, một bản do chính bạn giữ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L381_07','V381','阮明',7,'清楚全部条款，我现在签字确认。','qīng chǔ quán bù tiáo kuǎn， wǒ xiàn zài qiān zì què rèn。','Tôi đã hiểu rõ toàn bộ điều khoản rồi, giờ tôi ký xác nhận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT382','S127','Xin nghỉ làm vì trùng giờ thi',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V382','SIT382','P1','suon_se','ban_chinh_thuc',NULL,'国内兼职允许学生因学业请假，门店会灵活调整排班，不会随意克扣薪资；学生备考类请假大多可以协调同事顶替，无需自行补工时。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_01','V382','阮明',1,'店长您好，有一件事提前跟您沟通，下周三我无法到门店上班。','diàn zhǎng nín hǎo， yǒu yī jiàn shì tí qián gēn nín gōu tōng， xià zhōu sān wǒ wú fǎ dào mén diàn shàng bān。','Chào cửa hàng trưởng, có một việc tôi muốn báo trước, thứ Tư tuần sau tôi không thể đến cửa hàng làm việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_02','V382','店长',2,'你先说说是什么原因，门店排班需要提前协调人员顶替岗位吧。','nǐ xiān shuō shuō shì shén me yuán yīn， mén diàn pái bān xū yào tí qián xié tiáo rén yuán dǐng tì gǎng wèi ba。','Bạn nói rõ lý do xem sao, vì lịch trực cửa hàng cần sắp xếp người thay ca trước.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_03','V382','阮明',3,'下周三全天进行汉语专业期末考试，从上午八点考到下午五点，全天都无法到岗，实在抱歉呢。','xià zhōu sān quán tiān jìn xíng hàn yǔ zhuān yè qī mò kǎo shì， cóng shàng wǔ bā diǎn kǎo dào xià wǔ wǔ diǎn， quán tiān dōu wú fǎ dào gǎng， shí zài bào qiàn ne。','Thứ Tư tuần sau tôi phải thi hết môn chuyên ngành tiếng Trung cả ngày, từ tám giờ sáng đến năm giờ chiều, cả ngày không thể đến làm được, tôi thật sự xin lỗi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_04','V382','店长',4,'学生学业优先是理所应当的，你提前一周告知，我有充足时间调整整体排班。','xué shēng xué yè yōu xiān shì lǐ suǒ yīng dāng de， nǐ tí qián yī zhōu gào zhī， wǒ yǒu chōng zú shí jiān tiáo zhěng zhěng tǐ pái bān。','Việc học của sinh viên là ưu tiên hàng đầu, đương nhiên rồi, bạn báo trước cả tuần thế này thì tôi có đủ thời gian để sắp xếp lại lịch trực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_05','V382','阮明',5,'我担心缺一天班次，月度工时达不到门店规定标准，影响当月薪资发放。','wǒ dān xīn quē yī tiān bān cì， yuè dù gōng shí dá bú dào mén diàn guī dìng biāo zhǔn， yǐng xiǎng dàng yuè xīn zī fā fàng。','Tôi chỉ lo là nghỉ mất một ca thì tổng giờ làm trong tháng không đạt tiêu chuẩn cửa hàng quy định, ảnh hưởng đến lương tháng này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_06','V382','店长',6,'我会安排其他空闲同事顶替你的全天班次，不用有心理负担。','wǒ huì ān pái qí tā kòng xián tóng shì dǐng tì nǐ de quán tiān bān cì， bù yòng yǒu xīn lǐ fù dān。','Tôi sẽ sắp xếp đồng nghiệp khác rảnh để thay ca cả ngày cho bạn, đừng lo lắng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_07','V382','阮明',7,'考完试之后，我可以主动多上两天晚班，补上本次缺失的工时。','kǎo wán shì zhī hòu， wǒ kě yǐ zhǔ dòng duō shàng liǎng tiān wǎn bān， bǔ shàng běn cì quē shī de gōng shí。','Sau khi thi xong, tôi có thể chủ động làm thêm hai ca tối để bù lại giờ làm bị thiếu lần này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_08','V382','店长',8,'不用刻意额外加班补工时，你后续正常出勤就满足月度最低工时要求。','bù yòng kè yì é wài jiā bān bǔ gōng shí， nǐ hòu xù zhèng cháng chū qín jiù mǎn zú yuè dù zuì dī gōng shí yāo qiú。','Không cần cố tình làm thêm để bù giờ đâu, sau này bạn đi làm bình thường là đủ đạt mức giờ làm tối thiểu trong tháng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_09','V382','阮明',9,'太感谢店长体谅学生备考，我会提前一天完成手头所有工作交接。','tài gǎn xiè diàn zhǎng tǐ liàng xué shēng bèi kǎo， wǒ huì tí qián yī tiān wán chéng shǒu tóu suǒ yǒu gōng zuò jiāo jiē。','Cảm ơn cửa hàng trưởng đã thông cảm cho việc học của sinh viên, tôi sẽ bàn giao xong hết công việc trước một ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_10','V382','店长',10,'交接不用复杂，把当日需要整理的货品清单留在收银台就行。','jiāo jiē bù yòng fù zá， bǎ dāng rì xū yào zhěng lǐ de huò pǐn qīng dān liú zài shōu yín tái jiù xíng。','Bàn giao không cần phức tạp đâu, chỉ cần để lại danh sách hàng hóa cần sắp xếp trong ngày ở quầy thu ngân là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_11','V382','阮明',11,'考试结束后我会第一时间回门店正常上班，不耽误后续排班。','kǎo shì jié shù hòu wǒ huì dì yī shí jiān huí mén diàn zhèng cháng shàng bān， bù dān wù hòu xù pái bān。','Sau khi thi xong tôi sẽ quay lại cửa hàng làm việc bình thường ngay, không làm ảnh hưởng đến lịch trực sau đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_12','V382','店长',12,'专心备考，不用分心担心门店工作。','zhuān xīn bèi kǎo， bù yòng fēn xīn dān xīn mén diàn gōng zuò。','Cứ tập trung ôn thi đi, đừng phân tâm lo lắng chuyện cửa hàng làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_13','V382','阮明',13,'我一定好好复习，不辜负您的包容。','wǒ yí dìng hǎo hǎo fù xí， bù gū fù nín de bāo róng。','Tôi nhất định sẽ ôn tập thật tốt, không phụ lòng bao dung của cửa hàng trưởng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_14','V382','店长',14,'有任何考试变动提前跟我说，方便我重新调班。','yǒu rèn hé kǎo shì biàn dòng tí qián gēn wǒ shuō， fāng biàn wǒ chóng xīn diào bān。','Nếu có thay đổi gì về lịch thi thì báo trước cho tôi, để tôi tiện sắp xếp lại ca trực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L382_15','V382','阮明',15,'多谢店长体谅！','duō xiè diàn zhǎng tǐ liàng！','Cảm ơn cửa hàng trưởng nhiều lắm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT383','S127','Hỏi rõ mức lương và hình thức trả lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V383','SIT383','P1','suon_se','ban_chinh_thuc',NULL,'企业发放兼职薪资仅支持国内储蓄卡，境外银行卡无法完成对公转账。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_01','V383','阮明',1,'您好，我想确认这份兼职的时薪标准和发薪渠道。','nín hǎo， wǒ xiǎng què rèn zhè fèn jiān zhí de shí xīn biāo zhǔn hé fā xīn qú dào。','Chào chị, tôi muốn xác nhận lại mức lương theo giờ và hình thức trả lương của công việc bán thời gian này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_02','V383','人事专员',2,'每小时二十二元，每月二十号银行卡统一转账哦。','měi xiǎo shí èr shí èr yuán， měi yuè èr shí hào yín háng kǎ tǒng yī zhuǎn zhàng ó。','Hai mươi hai tệ một giờ, ngày hai mươi hàng tháng sẽ chuyển khoản qua thẻ ngân hàng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_03','V383','阮明',3,'薪资会扣除社保或者其他手续费之类的费用吗？','xīn zī huì kòu chú shè bǎo huò zhě qí tā shǒu xù fèi zhī lèi de fèi yòng ma？','Lương có bị trừ tiền bảo hiểm xã hội hay các loại phí thủ tục nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_04','V383','人事专员',4,'学生短期兼职不缴纳社保，到手工资无扣除呢。','xué shēng duǎn qī jiān zhí bù jiǎo nà shè bǎo， dào shǒu gōng zī wú kòu chú ne。','Sinh viên làm thêm ngắn hạn không phải đóng bảo hiểm xã hội, lương thực nhận không bị trừ khoản nào cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_05','V383','阮明',5,'只能绑定国内银行卡接收工资对吧？','zhǐ néng bǎng dìng guó nèi yín háng kǎ jiē shōu gōng zī duì ba？','Chỉ có thể nhận lương qua thẻ ngân hàng trong nước thôi đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_06','V383','人事专员',6,'是的，境外银行卡无法对接公司财务系统。','shì de， jìng wài yín háng kǎ wú fǎ duì jiē gōng sī cái wù xì tǒng。','Đúng vậy, thẻ ngân hàng nước ngoài không kết nối được với hệ thống tài chính của công ty.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L383_07','V383','阮明',7,'明白了，我尽快办理专用工资卡。','míng bái le， wǒ jǐn kuài bàn lǐ zhuān yòng gōng zī kǎ。','Tôi hiểu rồi, tôi sẽ làm thẻ lương riêng càng sớm càng tốt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT384','S127','Hỏi về việc đóng thuế thu nhập làm thêm',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V384','SIT384','P1','twist','chinh_thuc',NULL,'国内劳务报酬设有免税额度，用人单位统一代扣个税，完税证明可用于留学生签证续办。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_01','V384','阮明',1,'您好，留学生兼职获得的收入，需要申报个人所得税吗？','nín hǎo， liú xué shēng jiān zhí huò dé de shōu rù， xū yào shēn bào gè rén suǒ dé shuì ma？','Xin chào, thu nhập từ việc làm thêm của du học sinh có cần khai thuế thu nhập cá nhân không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_02','V384','财务',2,'月度收入超过八百元，超出部分需要缴纳劳务个税哈。','yuè dù shōu rù chāo guò bā bǎi yuán， chāo chū bù fèn xū yào jiǎo nà láo wù gè shuì hā。','Thu nhập hàng tháng vượt quá tám trăm tệ thì phần vượt phải nộp thuế thu nhập cá nhân đối với thù lao dịch vụ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_03','V384','阮明',3,'个税会直接从当月工资里扣除，还是我自行申报嘛？','gè shuì huì zhí jiē cóng dàng yuè gōng zī lǐ kòu chú， hái shì wǒ zì xíng shēn bào ma？','Vậy thuế thu nhập cá nhân sẽ bị trừ trực tiếp từ lương tháng đó, hay tôi phải tự kê khai vậy ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_04','V384','财务',4,'公司统一代扣代缴，工资条会标注扣税明细。','gōng sī tǒng yí dài kòu dài jiǎo， gōng zī tiáo huì biāo zhù kòu shuì míng xì。','Công ty sẽ khấu trừ và nộp thay thống nhất, trên phiếu lương sẽ ghi rõ chi tiết khoản thuế bị trừ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_05','V384','阮明',5,'年末可以打印全年纳税记录用作签证材料吗？','nián mò kě yǐ dǎ yìn quán nián nà shuì jì lù yòng zuò qiān zhèng cái liào ma？','Cuối năm tôi có thể in bảng ghi nhận nộp thuế cả năm để dùng làm hồ sơ visa được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_06','V384','财务',6,'可以，年末我统一打印完整纳税单据交给你。','kě yǐ， nián mò wǒ tǒng yī dǎ yìn wán zhěng nà shuì dān jù jiāo gěi nǐ。','Được chứ, cuối năm tôi sẽ in đầy đủ chứng từ nộp thuế cả năm đưa cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L384_07','V384','阮明',7,'好，相关规则我记下来，感谢细致讲解。','hǎo， xiāng guān guī zé wǒ jì xià lái， gǎn xiè xì zhì jiǎng jiě。','Vâng, tôi đã ghi nhớ các quy định này rồi, cảm ơn đã giải thích cặn kẽ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT385','S128','Mở tài khoản ngân hàng riêng để nhận lương',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V385','SIT385','P1','suon_se','chinh_thuc',NULL,'外籍留学生凭护照、在校证明可办理学生储蓄卡，多数银行学生账户免除年费与小额管理费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_01','V385','阮明',1,'您好，我是在校留学生，想开一张储蓄卡专门接收兼职工资。','nín hǎo， wǒ shì zài xiào liú xué shēng， xiǎng kāi yī zhāng chǔ xù kǎ zhuān mén jiē shōu jiān zhí gōng zī。','Chào chị, tôi là du học sinh đang học tại trường, muốn mở một thẻ tiết kiệm riêng để nhận lương làm thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_02','V385','柜员',2,'请出示你的护照、在校学生证，填写开户申请单吧。','qǐng chū shì nǐ de hù zhào、 zài xiào xué shēng zhèng， tián xiě kāi hù shēn qǐng dān ba。','Bạn cho tôi xem hộ chiếu và thẻ sinh viên, rồi điền vào đơn đăng ký mở tài khoản nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_03','V385','阮明',3,'这张卡只用来收工资，平时不存放大额资金可以吗？','zhè zhāng kǎ zhǐ yòng lái shōu gōng zī， píng shí bù cún fàng dà é zī jīn kě yǐ ma？','Thẻ này chỉ dùng để nhận lương thôi, bình thường không để số tiền lớn trong đó có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_04','V385','柜员',4,'完全没问题，普通一类储蓄卡支持企业对公转账呢。','wán quán méi wèn tí， pǔ tōng yī lèi chǔ xù kǎ zhī chí qǐ yè duì gōng zhuàn zhàng ne。','Hoàn toàn không vấn đề gì, thẻ tiết kiệm loại một thông thường vẫn hỗ trợ chuyển khoản từ doanh nghiệp mà.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_05','V385','阮明',5,'开户有没有年费、短信通知这类额外收费项目？','kāi hù yǒu méi yǒu nián fèi、 duǎn xìn tōng zhī zhè lèi é wài shōu fèi xiàng mù？','Mở tài khoản có phát sinh phí thường niên, phí tin nhắn thông báo hay khoản phí nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_06','V385','柜员',6,'学生账户免年费，免费开通资金变动短信提醒。','xué shēng zhàng hù miǎn nián fèi， miǎn fèi kāi tōng zī jīn biàn dòng duǎn xìn tí xǐng。','Tài khoản sinh viên được miễn phí thường niên, và được miễn phí đăng ký nhận tin nhắn thông báo biến động số dư.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L385_07','V385','阮明',7,'好，我现在填写单据办理开户手续。','hǎo， wǒ xiàn zài tián xiě dān jù bàn lǐ kāi hù shǒu xù。','Vâng, giờ tôi điền vào đơn để làm thủ tục mở tài khoản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT386','S127','Xin nghỉ việc trước thời hạn hợp đồng',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V386','SIT386','P1','twist','ban_chinh_thuc',NULL,'国内临时劳务用工规范要求员工提前三十天申请离职，企业可根据门店人手、员工实际情况适度放宽离职期限；离职必须填写书面申请存档，口头离职不生效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_01','V386','阮明',1,'店长，我今天过来跟您沟通离职事宜，下学期专业课数量大幅增加。','diàn zhǎng， wǒ jīn tiān guò lái gēn nín gōu tōng lí zhí shì yí， xià xué qī zhuān yè kè shù liàng dà fú zēng jiā。','Chào chị quản lý, hôm nay em đến để trao đổi về việc xin nghỉ việc, học kỳ tới số lượng môn chuyên ngành tăng lên nhiều quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_02','V386','店长',2,'我大致了解留学生课程安排，你计划什么时候正式结束兼职工作？','wǒ dà zhì liǎo jiě liú xué shēng kè chéng ān pái， nǐ jì huà shén me shí hòu zhèng shì jié shù jiān zhí gōng zuò？','Chị cũng nắm sơ qua lịch học của du học sinh rồi, vậy em định khi nào chính thức nghỉ làm thêm?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_03','V386','阮明',3,'原本合同约定做到学期末，我想申请提前半个月办理离职手续。','yuán běn hé tóng yuē dìng zuò dào xué qī mò， wǒ xiǎng shēn qǐng tí qián bàn gè yuè bàn lǐ lí zhí shǒu xù。','Ban đầu hợp đồng ghi làm đến cuối học kỳ, nhưng em muốn xin nghỉ sớm nửa tháng để làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_04','V386','店长',4,'门店劳务用工有统一规范，离职需要提前三十天书面提交申请，只提前半个月不符合规定嘛。','mén diàn láo wù yòng gōng yǒu tǒng yī guī fàn， lí zhí xū yào tí qián sān shí tiān shū miàn tí jiāo shēn qǐng， zhǐ tí qián bàn gè yuè bù fú hé guī dìng ma。','Quy định lao động của cửa hàng là nghỉ việc phải báo trước bằng văn bản ba mươi ngày, chỉ báo trước nửa tháng thì không đúng quy định đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_05','V386','阮明',5,'新学期课程表全部排满白天晚上，完全抽不出空余时间兼顾兼职工作。','xīn xué qī kè chéng biǎo quán bù pái mǎn bái tiān wǎn shàng， wán quán chōu bù chū kòng yú shí jiān jiān gù jiān zhí gōng zuò。','Thời khóa biểu học kỳ mới của em kín hết cả ngày lẫn tối, không thể nào sắp xếp thời gian làm thêm được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_06','V386','店长',6,'我能理解留学生课业压力大，直接按三十天标准离职时间执行对你压力太大。','wǒ néng lǐ jiě liú xué shēng kè yè yā lì dà， zhí jiē àn sān shí tiān biāo zhǔn lí zhí shí jiān zhí xíng duì nǐ yā lì tài dà。','Chị hiểu áp lực học hành của du học sinh rất lớn, nếu bắt em phải làm đủ ba mươi ngày theo tiêu chuẩn thì cũng quá sức với em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_07','V386','阮明',7,'我这段时间可以全力做好客户对接、货品盘点等全部工作交接。','wǒ zhè duàn shí jiān kě yǐ quán lì zuò hào kè hù duì jiē、 huò pǐn pán diǎn děng quán bù gōng zuò jiāo jiē。','Trong thời gian này em có thể dồn hết sức để bàn giao đầy đủ, từ kết nối khách hàng đến kiểm kê hàng hóa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_08','V386','店长',8,'结合门店近期人手充足的现状，我向上级人事申请，最多协调缩短到二十天离职周期。','jié hé mén diàn jìn qī rén shǒu chōng zú de xiàn zhuàng， wǒ xiàng shàng jí rén shì shēn qǐng， zuì duō xié tiáo suō duǎn dào èr shí tiān lí zhí zhōu qī。','Xét tình hình gần đây cửa hàng cũng đủ người, chị sẽ xin bên nhân sự, cố gắng thu xếp rút xuống còn hai mươi ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_09','V386','阮明',9,'二十天的周期我完全可以接受，这段时间我逐项梳理所有工作内容做好交接。','èr shí tiān de zhōu qī wǒ wán quán kě yǐ jiē shòu， zhè duàn shí jiān wǒ zhú xiàng shū lǐ suǒ yǒu gōng zuò nèi róng zuò hǎo jiāo jiē。','Hai mươi ngày thì em hoàn toàn chấp nhận được, thời gian đó em sẽ rà soát từng phần công việc để bàn giao cho chu đáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_10','V386','店长',10,'今天填写纸质离职申请表，我签字之后统一交给人事部门存档备案。','jīn tiān tián xiě zhǐ zhì lí zhí shēn qǐng biǎo， wǒ qiān zì zhī hòu tǒng yī jiāo gěi rén shì bù mén cún dàng bèi àn。','Hôm nay em điền vào đơn xin nghỉ việc bản giấy, chị ký xong sẽ nộp lên phòng nhân sự lưu hồ sơ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_11','V386','阮明',11,'交接清单我每天整理一部分，离职当天完整交给接替岗位的同事。','jiāo jiē qīng dān wǒ měi tiān zhěng lǐ yī bù fèn， lí zhí dàng tiān wán zhěng jiāo gěi jiē tì gǎng wèi de tóng shì。','Danh sách bàn giao em sẽ soạn dần mỗi ngày một phần, đến ngày nghỉ việc sẽ giao đầy đủ cho người kế nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_12','V386','店长',12,'交接过程中有不清楚的地方随时来办公室找我沟通。','jiāo jiē guò chéng zhōng yǒu bù qīng chǔ de dì fāng suí shí lái bàn gōng shì zhǎo wǒ gōu tōng。','Trong quá trình bàn giao có chỗ nào chưa rõ thì cứ lên văn phòng tìm chị trao đổi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_13','V386','阮明',13,'麻烦店长帮忙审批这份离职申请，这段时间也多谢门店所有人照顾我。','má fán diàn zhǎng bāng máng shěn pī zhè fèn lí zhí shēn qǐng， zhè duàn shí jiān yě duō xiè mén diàn suǒ yǒu rén zhào gù wǒ。','Phiền chị duyệt giúp em đơn xin nghỉ này, cũng cảm ơn mọi người ở cửa hàng đã quan tâm giúp đỡ em trong thời gian qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_14','V386','店长',14,'没事，学业为重，后续有空闲假期也欢迎再来短期兼职。','méi shì， xué yè wèi zhòng， hòu xù yǒu kòng xián jià qī yě huān yíng zài lái duǎn qī jiān zhí。','Không sao đâu, việc học là quan trọng nhất, sau này rảnh kỳ nghỉ nào thì cứ quay lại làm thêm thời vụ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L386_15','V386','阮明',15,'十分感谢您通融调整离职周期！','shí fēn gǎn xiè nín tōng róng tiáo zhěng lí zhí zhōu qī！','Em cảm ơn chị rất nhiều vì đã linh động điều chỉnh thời gian nghỉ việc cho em!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT387','S127','Hỏi quy định giờ làm tối đa cho sinh viên quốc tế',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V387','SIT387','P1','suon_se','chinh_thuc',NULL,'中国法律明确规定外籍留学生务工时长，超时务工将影响签证续签，学校会定期核查兼职情况。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_01','V387','阮明',1,'老师您好，我想咨询留学生校内、校外兼职时长限制。','lǎo shī nín hǎo， wǒ xiǎng zī xún liú xué shēng xiào nèi、 xiào wài jiān zhí shí cháng xiàn zhì。','Chào thầy/cô, em muốn hỏi về quy định giới hạn thời gian làm thêm trong và ngoài trường dành cho du học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_02','V387','国际处老师',2,'学期内每周打工总时长不能超过二十小时哦。','xué qī nèi měi zhōu dǎ gōng zǒng shí cháng bù néng chāo guò èr shí xiǎo shí ó。','Trong học kỳ, tổng thời gian làm thêm mỗi tuần không được vượt quá hai mươi giờ đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_03','V387','阮明',3,'寒暑假期间，时长限制会适当放宽一些吗？','hán shǔ jià qī jiān， shí cháng xiàn zhì huì shì dàng fàng kuān yī xiē ma？','Vậy vào kỳ nghỉ hè và nghỉ đông, giới hạn thời gian có được nới lỏng hơn một chút không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_04','V387','国际处老师',4,'假期每周最多四十小时，超出属于违规务工呢。','jià qī měi zhōu zuì duō sì shí xiǎo shí， chāo chū shǔ yú wéi guī wù gōng ne。','Vào kỳ nghỉ thì tối đa bốn mươi giờ mỗi tuần, vượt quá mức đó là lao động trái quy định đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_05','V387','阮明',5,'超时打工会不会影响我的签证续办审核？','chāo shí dǎ gōng huì bú huì yǐng xiǎng wǒ de qiān zhèng xù bàn shěn hé？','Nếu làm thêm quá giờ thì có ảnh hưởng đến việc xét gia hạn visa của em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_06','V387','国际处老师',6,'会有影响，出入境管理局会核查务工时长记录。','huì yǒu yǐng xiǎng， chū rù jìng guǎn lǐ jú huì hé chá wù gōng shí cháng jì lù。','Có ảnh hưởng đấy, cục quản lý xuất nhập cảnh sẽ kiểm tra hồ sơ ghi nhận thời gian làm thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L387_07','V387','阮明',7,'我清楚规定了，一定会严格控制上班时长。','wǒ qīng chǔ guī dìng le， yí dìng huì yán gé kòng zhì shàng bān shí cháng。','Em đã hiểu rõ quy định rồi, em nhất định sẽ kiểm soát chặt chẽ thời gian làm việc của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT388','S127','Trao đổi ca làm việc với đồng nghiệp',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V388','SIT388','P1','twist','tuy_y',NULL,'兼职员工私下换班必须告知主管登记，避免岗位无人值守，产生运营问题。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_01','V388','阮明',1,'小秦，我周四下午有汉语测验，能和你互换班次吗？','xiǎo qín， wǒ zhōu sì xià wǔ yǒu hàn yǔ cè yàn， néng hé nǐ hù huàn bān cì ma？','Tiểu Tần ơi, chiều thứ Năm này mình có bài kiểm tra tiếng Hán, cậu đổi ca với mình được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_02','V388','小秦',2,'我周四全天有社团活动，那天也没办法上班嘛。','wǒ zhōu sì quán tiān yǒu shè tuán huó dòng， nà tiān yě méi bàn fǎ shàng bān ma。','Thứ Năm cả ngày mình có hoạt động câu lạc bộ, hôm đó mình cũng không đi làm được đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_03','V388','阮明',3,'原来是这样，那周五的班次你方便和我调换不？','yuán lái shì zhè yàng， nà zhōu wǔ de bān cì nǐ fāng biàn hé wǒ diào huàn bù？','À ra vậy, thế ca thứ Sáu cậu có tiện đổi cho mình không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_04','V388','小秦',4,'周五我空闲，我们调换之后跟店长报备一下就行。','zhōu wǔ wǒ kòng xián， wǒ men diào huàn zhī hòu gēn diàn zhǎng bào bèi yī xià jiù xíng。','Thứ Sáu mình rảnh, đổi xong tụi mình báo cho quản lý một tiếng là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_05','V388','阮明',5,'太好了，调换班次需要填写纸质调换申请单吗？','tài hǎo le， diào huàn bān cì xū yào tián xiě zhǐ zhì diào huàn shēn qǐng dān ma？','Tuyệt quá, đổi ca thế này có cần điền đơn giấy xin đổi ca không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_06','V388','小秦',6,'不用，微信跟店长说一声登记备案就可以。','bù yòng， wēi xìn gēn diàn zhǎng shuō yī shēng dēng jì bèi àn jiù kě yǐ。','Không cần đâu, nhắn WeChat báo quản lý một câu để ghi nhận lại là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L388_07','V388','阮明',7,'太谢谢你，解决了我的难题。','tài xiè xiè nǐ， jiě jué le wǒ de nán tí。','Cảm ơn cậu nhiều lắm, cậu giải quyết giúp mình vấn đề nan giải luôn đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT389','S127','Báo cáo sự cố trong ca làm với quản lý',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V389','SIT389','P1','suon_se','ban_chinh_thuc',NULL,'服务行业工作中出现客户突发状况，员工第一时间上报主管并留存记录，是标准工作流程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_01','V389','阮明',1,'主管，刚刚上课出现突发情况，我来跟您汇报一下。','zhǔ guǎn， gāng gāng shàng kè chū xiàn tū fā qíng kuàng， wǒ lái gēn nín huì bào yī xià。','Thưa quản lý, vừa nãy trong giờ dạy xảy ra sự việc bất ngờ, em xin báo cáo lại với anh/chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_02','V389','主管',2,'别着急，慢慢说，课堂上发生什么意外了吧？','bié zháo jí， màn màn shuō， kè táng shàng fā shēng shén me yì wài le ba？','Đừng gấp, cứ từ từ kể, trong lớp xảy ra chuyện gì vậy?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_03','V389','阮明',3,'一名小朋友身体不舒服，家长临时赶来把孩子接走了呢。','yī míng xiǎo péng yǒu shēn tǐ bù shū fú， jiā zhǎng lín shí gǎn lái bǎ hái zi jiē zǒu le ne。','Có một bé bị khó chịu trong người, phụ huynh vội đến đón bé về rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_04','V389','主管',4,'孩子有没有出现发烧、呕吐这类严重不适症状？','hái zi yǒu méi yǒu chū xiàn fā shāo、 ǒu tù zhè lèi yán zhòng bù shì zhèng zhuàng？','Bé có bị sốt, nôn ói hay có triệu chứng nghiêm trọng nào khác không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_05','V389','阮明',5,'只是轻微头晕，休息片刻就好转，家长已经带离校区。','zhǐ shì qīng wēi tóu yūn， xiū xī piàn kè jiù hǎo zhuǎn， jiā zhǎng yǐ jīng dài lí xiào qū。','Chỉ hơi chóng mặt nhẹ thôi, nghỉ một lát là đỡ, phụ huynh đã đưa bé rời khỏi trường rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_06','V389','主管',6,'记录好学生信息，后续跟进询问孩子身体状况。','jì lù hào xué shēng xìn xī， hòu xù gēn jìn xún wèn hái zi shēn tǐ zhuàng kuàng。','Em ghi lại thông tin của học sinh, sau đó tiếp tục theo dõi hỏi thăm tình hình sức khỏe của bé nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L389_07','V389','阮明',7,'好，我马上整理情况记录，同步发给您查看。','hǎo， wǒ mǎ shàng zhěng lǐ qíng kuàng jì lù， tóng bù fā gěi nín chá kàn。','Vâng, em sẽ lập tức tổng hợp lại tình hình và gửi cho anh/chị xem ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT390','S127','Xin thư giới thiệu từ nơi thực tập',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V390','SIT390','P1','twist','chinh_thuc',NULL,'企业开具实习推荐信加盖公章需行政部门审核，私人手写无公章的推荐信不具备官方证明效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_01','V390','阮明',1,'领导您好，我的实习周期即将结束，想申请一份实习推荐信。','lǐng dǎo nín hǎo， wǒ de shí xí zhōu qī jí jiāng jié shù， xiǎng shēn qǐng yī fèn shí xí tuī jiàn xìn。','Chào anh, kỳ thực tập của em sắp kết thúc rồi, em muốn xin một thư giới thiệu thực tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_02','V390','负责人',2,'可以，推荐信用于升学还是后续求职使用呢？','kě yǐ， tuī jiàn xìn yòng yú shēng xué hái shì hòu xù qiú zhí shǐ yòng ne？','Được chứ, thư giới thiệu này em dùng để học tiếp lên hay để xin việc sau này?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_03','V390','阮明',3,'用于境外深造申请，需要加盖公司官方公章对吧？','yòng yú jìng wài shēn zào shēn qǐng， xū yào jiā gài gōng sī guān fāng gōng zhāng duì ba？','Em dùng để nộp hồ sơ du học nước ngoài, cần đóng dấu chính thức của công ty phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_04','V390','负责人',4,'推荐信内容我可以撰写，但公章需要行政部门统一审批嘛。','tuī jiàn xìn nèi róng wǒ kě yǐ zhuàn xiě， dàn gōng zhāng xū yào xíng zhèng bù mén tǒng yī shěn pī ma。','Nội dung thư giới thiệu anh có thể viết cho em, nhưng việc đóng dấu thì cần phòng hành chính duyệt thống nhất nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_05','V390','阮明',5,'审批流程大概需要几天，我下周就要提交申请材料。','shěn pī liú chéng dà gài xū yào jǐ tiān， wǒ xià zhōu jiù yào tí jiāo shēn qǐng cái liào。','Quy trình duyệt khoảng bao nhiêu ngày ạ, tuần sau em phải nộp hồ sơ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_06','V390','负责人',6,'三天内完成审批盖章，到时候我通知你来领取。','sān tiān nèi wán chéng shěn pī gài zhāng， dào shí hòu wǒ tōng zhī nǐ lái lǐng qǔ。','Trong ba ngày sẽ hoàn tất duyệt và đóng dấu, lúc đó anh sẽ báo em đến lấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L390_07','V390','阮明',7,'麻烦领导费心帮忙，非常感谢。','má fán lǐng dǎo fèi xīn bāng máng， fēi cháng gǎn xiè。','Phiền anh giúp đỡ em, em cảm ơn anh rất nhiều ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT391','S129','Xin cấp bảng điểm chính thức',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V391','SIT391','P1','twist','ban_chinh_thuc',NULL,'留学生用于出境、升学的成绩单必须由学校教务盖章，电子版文件不具备官方效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_01','V391','阮明',1,'老师您好，我毕业需要正式成绩单，想申请打印几份。','lǎo shī nín hǎo， wǒ bì yè xū yào zhèng shì chéng jì dān， xiǎng shēn qǐng dǎ yìn jǐ fèn。','Chào thầy/cô, em sắp tốt nghiệp nên cần bảng điểm chính thức, em muốn xin in vài bản ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_02','V391','教务老师',2,'没问题，填好这份申请表，带上你的护照原件哦。','méi wèn tí， tián hǎo zhè fèn shēn qǐng biǎo， dài shàng nǐ de hù zhào yuán jiàn ó。','Không vấn đề gì, em điền vào đơn này, nhớ mang theo hộ chiếu bản gốc nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_03','V391','阮明',3,'申请表我已经填完了，但是护照昨天拿去办签证了嘛。','shēn qǐng biǎo wǒ yǐ jīng tián wán le， dàn shì hù zhào zuó tiān ná qù bàn qiān zhèng le ma。','Đơn em điền xong rồi ạ, nhưng hộ chiếu hôm qua em mang đi làm visa mất rồi ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_04','V391','教务老师',4,'没有证件不能办理，你改天带护照再来登记吧。','méi yǒu zhèng jiàn bù néng bàn lǐ， nǐ gǎi tiān dài hù zhào zài lái dēng jì ba。','Không có giấy tờ thì không làm được, hôm khác em mang hộ chiếu đến đăng ký lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_05','V391','阮明',5,'那我明天一早把护照带过来，当天就能拿到成绩单吗？','nà wǒ míng tiān yī zǎo bǎ hù zhào dài guò lái， dàng tiān jiù néng ná dào chéng jì dān ma？','Vậy sáng mai em mang hộ chiếu đến sớm, có thể nhận bảng điểm ngay trong ngày không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_06','V391','教务老师',6,'纸质成绩单当场打印盖章，不用额外等候。','zhǐ zhì chéng jì dān dāng chǎng dǎ yìn gài zhāng， bù yòng é wài děng hòu。','Bảng điểm giấy sẽ in và đóng dấu ngay tại chỗ, không cần chờ đợi thêm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L391_07','V391','阮明',7,'好，辛苦老师，我明天准时过来办理。','hǎo， xīn kǔ lǎo shī， wǒ míng tiān zhǔn shí guò lái bàn lǐ。','Vâng, cảm ơn thầy/cô đã vất vả giúp đỡ, mai em sẽ đến đúng giờ để làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT392','S129','Xin cấp bằng tốt nghiệp và công chứng',NULL,'C1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V392','SIT392','P1','suon_se','chinh_thuc',NULL,'外国留学生回国使用国内学历证件，必须办理涉外公证，境外机构才认可学历效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_01','V392','阮明',1,'您好，我课程全部修完，来领取毕业证并申请校内公证。','nín hǎo， wǒ kè chéng quán bù xiū wán， lái lǐng qǔ bì yè zhèng bìng shēn qǐng xiào nèi gōng zhèng。','Chào anh/chị, em đã hoàn thành hết các môn học rồi, em đến nhận bằng tốt nghiệp và xin công chứng trong trường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_02','V392','工作人员',2,'先核对你的全部考勤和缴费记录，没有欠费才能办理呢。','xiān hé duì nǐ de quán bù kǎo qín hé jiǎo fèi jì lù， méi yǒu qiàn fèi cái néng bàn lǐ ne。','Để tôi kiểm tra lại toàn bộ hồ sơ điểm danh và học phí của em đã, không còn nợ gì thì mới làm được nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_03','V392','阮明',3,'学费、住宿费我都按时交清，没有任何欠费记录。','xué fèi、 zhù sù fèi wǒ dōu àn shí jiāo qīng， méi yǒu rèn hé qiàn fèi jì lù。','Học phí và tiền ký túc xá em đều đóng đúng hạn, không có khoản nào còn nợ cả ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_04','V392','工作人员',4,'毕业证当场发放，公证文件三个工作日后可取。','bì yè zhèng dāng chǎng fā fàng， gōng zhèng wén jiàn sān gè gōng zuò rì hòu kě qǔ。','Bằng tốt nghiệp sẽ cấp ngay tại chỗ, còn giấy công chứng thì sau ba ngày làm việc mới lấy được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_05','V392','阮明',5,'公证文件可以多打印两份，方便我带回越南使用吧？','gōng zhèng wén jiàn kě yǐ duō dǎ yìn liǎng fèn， fāng biàn wǒ dài huí yuè nán shǐ yòng ba？','Giấy công chứng em xin in thêm hai bản nữa được không ạ, để tiện mang về Việt Nam sử dụng?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_06','V392','工作人员',6,'没问题，每份公证只收取基础工本费。','méi wèn tí， měi fèn gōng zhèng zhǐ shōu qǔ jī chǔ gōng běn fèi。','Không vấn đề gì, mỗi bản công chứng chỉ thu phí làm hồ sơ cơ bản thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L392_07','V392','阮明',7,'麻烦您帮忙办理，这份材料对我后续深造很重要。','má fán nín bāng máng bàn lǐ， zhè fèn cái liào duì wǒ hòu xù shēn zào hěn zhòng yào。','Phiền anh/chị giúp em làm thủ tục, hồ sơ này rất quan trọng cho việc học lên sau này của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT393','S130','Làm thủ tục trả phòng ký túc xá',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V393','SIT393','P1','twist','ban_chinh_thuc',NULL,'高校宿舍退房会逐一清点室内设施，人为造成大面积破损，学校会从住宿押金中扣除维修费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_01','V393','阮明',1,'阿姨，我今天来办宿舍退房，麻烦检查一下房间。','ā yí， wǒ jīn tiān lái bàn sù shè tuì fáng， má fán jiǎn chá yī xià fáng jiān。','Cô ơi, hôm nay con đến trả phòng ký túc xá, phiền cô kiểm tra giúp phòng con nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_02','V393','宿管阿姨',2,'我看看桌椅、墙面和电器，破损会扣押金哈。','wǒ kàn kàn zhuō yǐ、 qiáng miàn hé diàn qì， pò sǔn huì kòu yā jīn hā。','Để cô xem bàn ghế, tường và đồ điện, hỏng gì là bị trừ tiền cọc đó nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_03','V393','阮明',3,'我平时很爱惜房间，只有书桌边角有一点小划痕嘛。','wǒ píng shí hěn ài xī fáng jiān， zhǐ yǒu shū zhuō biān jiǎo yǒu yì diǎn xiǎo huà hén ma。','Con giữ gìn phòng cẩn thận lắm, chỉ có góc bàn học bị trầy nhẹ một chút xíu thôi ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_04','V393','宿管阿姨',4,'轻微划痕不影响，不需要扣除押金。','qīng wēi huà hén bù yǐng xiǎng， bù xū yào kòu chú yā jīn。','Trầy nhẹ vậy thì không sao, không cần trừ tiền cọc đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_05','V393','阮明',5,'那我的行李可以暂时放在楼道等同学帮忙搬运吗？','nà wǒ de xíng lǐ kě yǐ zàn shí fàng zài lóu dào děng tóng xué bāng máng bān yùn ma？','Vậy hành lý của con có thể để tạm ở hành lang chờ bạn đến phụ khiêng được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_06','V393','宿管阿姨',6,'短时间放置没问题，不要堵塞消防通道就行。','duǎn shí jiān fàng zhì méi wèn tí， bú yào dǔ sè xiāo fáng tōng dào jiù xíng。','Để tạm một lát thì không sao, chỉ cần đừng chắn lối thoát hiểm là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L393_07','V393','阮明',7,'太感谢阿姨通融，我收拾完立刻离开宿舍楼。','tài gǎn xiè ā yí tōng róng， wǒ shōu shí wán lì kè lí kāi sù shè lóu。','Con cảm ơn cô đã thông cảm nhiều lắm, con dọn xong là rời khỏi ký túc xá ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT394','S130','Thanh lý hợp đồng thuê nhà ngoài',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V394','SIT394','P1','suon_se','ban_chinh_thuc',NULL,'提前退租需和房东当面清点房屋物品，确认无损坏、无欠费后，房东才会全额返还租房押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_01','V394','阮明',1,'房东您好，我马上毕业回国，想提前终止租房合同。','fáng dōng nín hǎo， wǒ mǎ shàng bì yè huí guó， xiǎng tí qián zhōng zhǐ zū fáng hé tóng。','Chào chủ nhà, em sắp tốt nghiệp về nước rồi, em muốn xin kết thúc hợp đồng thuê nhà sớm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_02','V394','房东',2,'可以，我们按合同约定清点家具，结清水电杂费吧。','kě yǐ， wǒ men àn hé tóng yuē dìng qīng diǎn jiā jù， jié qīng shuǐ diàn zá fèi ba。','Được thôi, mình kiểm kê đồ đạc theo hợp đồng rồi thanh toán nốt tiền điện nước nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_03','V394','阮明',3,'所有家具完好无损，水电费我已经全部缴清了呢。','suǒ yǒu jiā jù wán hǎo wú sǔn， shuǐ diàn fèi wǒ yǐ jīng quán bù jiǎo qīng le ne。','Đồ đạc còn nguyên vẹn hết, tiền điện nước em cũng đóng đủ rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_04','V394','房东',4,'墙面没有污渍、家电能正常使用，我全额退还押金。','qiáng miàn méi yǒu wū zì、 jiā diàn néng zhèng cháng shǐ yòng， wǒ quán é tuì huán yā jīn。','Tường không có vết bẩn, đồ điện dùng bình thường, tôi hoàn lại toàn bộ tiền cọc cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_05','V394','阮明',5,'押金可以直接转账到我的银行卡里对吗？','yā jīn kě yǐ zhí jiē zhuǎn zhàng dào wǒ de yín háng kǎ lǐ duì ma？','Tiền cọc chuyển thẳng vào thẻ ngân hàng của em được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_06','V394','房东',6,'没问题，验收完房屋当天就给你转账。','méi wèn tí， yàn shōu wán fáng wū dàng tiān jiù gěi nǐ zhuǎn zhàng。','Không vấn đề gì, kiểm tra nhà xong hôm nay là chuyển khoản cho em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L394_07','V394','阮明',7,'辛苦您抽空过来验房，麻烦您多费心。','xīn kǔ nín chōu kòng guò lái yàn fáng， má fán nín duō fèi xīn。','Cảm ơn chủ nhà đã bỏ thời gian qua kiểm tra nhà, phiền chú/cô nhiều rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT395','S119','Đóng tài khoản ngân hàng trước khi về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V395','SIT395','P1','twist','chinh_thuc',NULL,'外籍人员长期离境建议注销国内闲置银行卡，避免长期休眠账户产生管理风险。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_01','V395','阮明',1,'您好，我即将回国，想要注销这张留学生储蓄卡。','nín hǎo， wǒ jí jiāng huí guó， xiǎng yào zhù xiāo zhè zhāng liú xué shēng chǔ xù kǎ。','Xin chào, tôi sắp về nước nên muốn đóng thẻ tiết kiệm dành cho du học sinh này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_02','V395','柜员',2,'先把卡里余额全部取出，再填写销户申请单哦。','xiān bǎ kǎ lǐ yú é quán bù qǔ chū， zài tián xiě xiāo hù shēn qǐng dān ó。','Anh/chị rút hết số dư trong thẻ ra trước, sau đó điền vào đơn xin đóng tài khoản nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_03','V395','阮明',3,'我刚刚查询，账户还有十几块零钱没法线上转出嘛。','wǒ gāng gāng chá xún， zhàng hù hái yǒu shí jǐ kuài líng qián méi fǎ xiàn shàng zhuǎn chū ma。','Tôi vừa kiểm tra thì tài khoản vẫn còn hơn mười tệ lẻ, không rút online được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_04','V395','柜员',4,'小额现金柜台可以直接取出，不影响销户流程。','xiǎo é xiàn jīn guì tái kě yǐ zhí jiē qǔ chū， bù yǐng xiǎng xiāo hù liú chéng。','Số tiền mặt nhỏ đó có thể rút trực tiếp tại quầy, không ảnh hưởng đến việc đóng tài khoản đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_05','V395','阮明',5,'销户完成后，银行会开具销户证明给我吗？','xiāo hù wán chéng hòu， yín háng huì kāi jù xiāo hù zhèng míng gěi wǒ ma？','Sau khi đóng tài khoản xong, ngân hàng có cấp giấy xác nhận đóng tài khoản cho tôi không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_06','V395','柜员',6,'可以，纸质销户回执会加盖公章交给你留存。','kě yǐ， zhǐ zhì xiāo hù huí zhí huì jiā gài gōng zhāng jiāo gěi nǐ liú cún。','Có chứ, biên nhận đóng tài khoản bản giấy sẽ được đóng dấu và giao cho anh/chị giữ lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L395_07','V395','阮明',7,'好，我现在办理取现，再完成销户手续。','hǎo， wǒ xiàn zài bàn lǐ qǔ xiàn， zài wán chéng xiāo hù shǒu xù。','Vâng, giờ tôi làm thủ tục rút tiền mặt, rồi hoàn tất việc đóng tài khoản luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT396','S131','Hủy SIM điện thoại trước khi về nước',NULL,'A2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V396','SIT396','P1','suon_se','ban_chinh_thuc',NULL,'留学生离境前务必注销手机卡，若长期欠费停机，会影响本人后续再次办理国内通信业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_01','V396','阮明',1,'你好，我毕业要回国，打算注销名下这张手机电话卡。','nǐ hǎo， wǒ bì yè yào huí guó， dǎ suàn zhù xiāo míng xià zhè zhāng shǒu jī diàn huà kǎ。','Chào bạn, tôi tốt nghiệp sắp về nước rồi, tôi muốn hủy sim điện thoại đứng tên tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_02','V396','客服',2,'出示办卡时的护照，我先查询套餐是否有未结清费用呢。','chū shì bàn kǎ shí de hù zhào， wǒ xiān chá xún tào cān shì fǒu yǒu wèi jié qīng fèi yòng ne。','Anh/chị cho em xin hộ chiếu lúc đăng ký sim, em kiểm tra xem gói cước còn nợ phí gì không nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_03','V396','阮明',3,'上个月话费已经缴完，没有欠费、没有合约捆绑。','shàng gè yuè huà fèi yǐ jīng jiǎo wán， méi yǒu qiàn fèi、 méi yǒu hé yuē kǔn bǎng。','Cước tháng trước tôi đóng hết rồi, không nợ cước, cũng không có ràng buộc hợp đồng gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_04','V396','客服',4,'那现在就能当场注销，卡里剩余话费可以现金退还。','nà xiàn zài jiù néng dāng chǎng zhù xiāo， kǎ lǐ shèng yú huà fèi kě yǐ xiàn jīn tuì huán。','Vậy thì bây giờ hủy được ngay, tiền cước còn dư trong thẻ có thể hoàn lại bằng tiền mặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_05','V396','阮明',5,'注销之后，会不会收到后续短信或者扣费通知吧？','zhù xiāo zhī hòu， huì bú huì shōu dào hòu xù duǎn xìn huò zhě kòu fèi tōng zhī ba？','Sau khi hủy sim rồi, có còn nhận được tin nhắn hay thông báo trừ tiền gì nữa không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_06','V396','客服',6,'不会，销户后号码直接回收，和你不再有关联。','bú huì， xiāo hù hòu hào mǎ zhí jiē huí shōu， hé nǐ bù zài yǒu guān lián。','Không đâu, hủy xong là số điện thoại bị thu hồi luôn, không còn liên quan gì đến anh/chị nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L396_07','V396','阮明',7,'那就麻烦你帮我办理注销业务了。','nà jiù má fán nǐ bāng wǒ bàn lǐ zhù xiāo yè wù le。','Vậy thì phiền bạn giúp tôi làm thủ tục hủy sim nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT397','S119','Xin hoàn lại tiền đặt cọc phòng',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V397','SIT397','P1','twist','ban_chinh_thuc',NULL,'学校各类押金退款均留存电子档案，票据丢失可凭本人有效证件核对记录办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_01','V397','阮明',1,'老师您好，我毕业离校，申请退还宿舍住宿押金。','lǎo shī nín hǎo， wǒ bì yè lí xiào， shēn qǐng tuì huán sù shè zhù sù yā jīn。','Chào thầy/cô, em tốt nghiệp rời trường rồi, em xin nộp đơn hoàn lại tiền cọc ký túc xá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_02','V397','财务老师',2,'带好退房回执和缴费票据，我登记后走退款流程哈。','dài hǎo tuì fáng huí zhí hé jiǎo fèi piào jù， wǒ dēng jì hòu zǒu tuì kuǎn liú chéng hā。','Em mang theo biên nhận trả phòng và hóa đơn nộp tiền, cô ghi nhận xong sẽ làm thủ tục hoàn tiền nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_03','V397','阮明',3,'退房回执我带来了，但是押金票据不小心弄丢了嘛。','tuì fáng huí zhí wǒ dài lái le， dàn shì yā jīn piào jù bù xiǎo xīn nòng diū le ma。','Biên nhận trả phòng em mang rồi ạ, nhưng hóa đơn tiền cọc em lỡ làm mất mất rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_04','V397','财务老师',4,'没关系，系统有缴费记录，凭护照也能核对退款。','méi guān xì， xì tǒng yǒu jiǎo fèi jì lù， píng hù zhào yě néng hé duì tuì kuǎn。','Không sao, hệ thống có lưu lại thông tin nộp tiền, dùng hộ chiếu đối chiếu cũng hoàn tiền được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_05','V397','阮明',5,'押金是原路退回银行卡，还是现场领取现金？','yā jīn shì yuán lù tuì huí yín háng kǎ， hái shì xiàn chǎng lǐng qǔ xiàn jīn？','Tiền cọc sẽ hoàn lại vào thẻ ngân hàng như ban đầu, hay em nhận tiền mặt tại chỗ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_06','V397','财务老师',6,'统一银行卡转账，三个工作日内到账。','tǒng yī yín háng kǎ zhuǎn zhàng， sān gè gōng zuò rì nèi dào zhàng。','Đều chuyển khoản vào thẻ ngân hàng hết, trong vòng ba ngày làm việc sẽ vào tài khoản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L397_07','V397','阮明',7,'太感谢老师帮忙核对，省去我不少麻烦。','tài gǎn xiè lǎo shī bāng máng hé duì， shěng qù wǒ bù shǎo má fán。','Em cảm ơn thầy/cô nhiều lắm vì đã giúp em đối chiếu, đỡ cho em bao nhiêu là phiền phức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT398','S132','Làm thủ tục ra sân bay về nước',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V398','SIT398','P1','suon_se','ban_chinh_thuc',NULL,'国内国际航班充电宝只能随身携带，严禁放入托运行李，超规行李需要额外支付运费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_01','V398','阮明',1,'您好，我乘坐飞往越南的航班，办理行李托运和值机。','nín hǎo， wǒ chéng zuò fēi wǎng yuè nán de háng bān， bàn lǐ xíng lǐ tuō yùn hé zhí jī。','Chào anh/chị, tôi đi chuyến bay về Việt Nam, tôi muốn ký gửi hành lý và làm thủ tục check-in.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_02','V398','工作人员',2,'出示你的护照和电子机票，行李不要超重哦。','chū shì nǐ de hù zhào hé diàn zi jī piào， xíng lǐ bú yào chāo zhòng ó。','Anh/chị cho em xin hộ chiếu và vé điện tử, hành lý đừng để quá cân nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_03','V398','阮明',3,'两件行李箱总重量二十公斤，符合免费托运标准呢。','liǎng jiàn xíng lǐ xiāng zǒng zhòng liàng èr shí gōng jīn， fú hé miǎn fèi tuō yùn biāo zhǔn ne。','Hai vali tổng cộng nặng hai mươi ký, đúng tiêu chuẩn ký gửi miễn phí rồi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_04','V398','工作人员',4,'行李贴好标签，登机口在二楼，提前一小时等候登机。','xíng lǐ tiē hǎo biāo qiān， dēng jī kǒu zài èr lóu， tí qián yī xiǎo shí děng hòu dēng jī。','Hành lý đã dán nhãn xong, cổng lên máy bay ở tầng hai, anh/chị ra sớm một tiếng để chờ lên máy bay nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_05','V398','阮明',5,'随身包里有电子产品，过安检需要单独拿出来对吧？','suí shēn bāo lǐ yǒu diàn zi chǎn pǐn， guò ān jiǎn xū yào dān dú ná chū lái duì ba？','Trong túi xách tay có đồ điện tử, qua an ninh cần lấy riêng ra đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_06','V398','工作人员',6,'没错，电脑、充电宝都要单独过机检查。','méi cuò， diàn nǎo、 chōng diàn bǎo dōu yào dān dú guò jī jiǎn chá。','Đúng vậy, máy tính, sạc dự phòng đều phải để riêng ra để qua máy soi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L398_07','V398','阮明',7,'清楚流程了，辛苦你指引我办理。','qīng chǔ liú chéng le， xīn kǔ nǐ zhǐ yǐn wǒ bàn lǐ。','Em hiểu quy trình rồi ạ, cảm ơn anh/chị đã hướng dẫn em làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT399','S129','Xin giấy xác nhận đã hoàn thành khóa học',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V399','SIT399','P1','suon_se','ban_chinh_thuc',NULL,'海外院校会要求留学生提供课程完成证明，以此核实学生完整完成在校学习。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_01','V399','阮明',1,'老师，我回国升学需要课程完成证明，麻烦帮忙开具。','lǎo shī， wǒ huí guó shēng xué xū yào kè chéng wán chéng zhèng míng， má fán bāng máng kāi jù。','Thầy ơi, em về nước học tiếp cần giấy xác nhận hoàn thành khóa học, phiền thầy cấp giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_02','V399','教务老师',2,'所有课程、论文全部合格，才能出具这份官方证明吧。','suǒ yǒu kè chéng、 lùn wén quán bù hé gé， cái néng chū jù zhè fèn guān fāng zhèng míng ba。','Tất cả các môn học, luận văn đều phải đạt thì mới cấp được giấy xác nhận chính thức này nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_03','V399','阮明',3,'我的全部课程考核通过，论文也顺利答辩完成了呢。','wǒ de quán bù kè chéng kǎo hé tōng guò， lùn wén yě shùn lì dá biàn wán chéng le ne。','Tất cả các môn em đều đạt hết rồi, luận văn cũng bảo vệ thành công rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_04','V399','教务老师',4,'我现在打印两份，加盖学院公章交给你带走。','wǒ xiàn zài dǎ yìn liǎng fèn， jiā gài xué yuàn gōng zhāng jiāo gěi nǐ dài zǒu。','Giờ tôi in hai bản, đóng dấu của khoa rồi đưa em mang đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_05','V399','阮明',5,'证明上面会标注我的在校学习时长和专业信息吗？','zhèng míng shàng miàn huì biāo zhù wǒ de zài xiào xué xí shí cháng hé zhuān yè xìn xī ma？','Trong giấy xác nhận có ghi rõ thời gian học tại trường và thông tin chuyên ngành của em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_06','V399','教务老师',6,'全部信息完整标注，国外院校完全认可。','quán bù xìn xī wán zhěng biāo zhù， guó wài yuàn xiào wán quán rèn kě。','Ghi đầy đủ hết mọi thông tin, các trường nước ngoài công nhận hoàn toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L399_07','V399','阮明',7,'太感谢老师，这份证明对我的深造至关重要。','tài gǎn xiè lǎo shī， zhè fèn zhèng míng duì wǒ de shēn zào zhì guān zhòng yào。','Em cảm ơn thầy nhiều lắm, giấy xác nhận này quan trọng vô cùng với việc học tiếp của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT400','S133','Nói lời chia tay và cảm ơn thầy cô, bạn bè',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V400','SIT400','P1','suon_se','ban_chinh_thuc',NULL,'学生毕业离校前主动和老师当面道别是尊师礼仪，中国人习惯祝福对方前路顺遂、常保持联络。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_01','V400','阮明',1,'李老师，我下周就要回国了，今天特地来和您道别。','lǐ lǎo shī， wǒ xià zhōu jiù yào huí guó le， jīn tiān tè dì lái hé nín dào bié。','Cô Lý ơi, tuần sau em về nước rồi, hôm nay em đến để chào tạm biệt cô ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_02','V400','李老师',2,'时间过得真快，这两年你的汉语进步特别明显啊。','shí jiān guò dé zhēn kuài， zhè liǎng nián nǐ de hàn yǔ jìn bù tè bié míng xiǎn a。','Thời gian trôi nhanh thật đấy, hai năm qua tiếng Trung của em tiến bộ rõ rệt luôn.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_03','V400','阮明',3,'多亏您一直耐心辅导我，我心里特别感激呢。','duō kuī nín yì zhí nài xīn fǔ dǎo wǒ， wǒ xīn lǐ tè bié gǎn jī ne。','Nhờ cô kiên nhẫn dạy dỗ em suốt thời gian qua, em cảm kích lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_04','V400','李老师',4,'以后回国也要坚持练习汉语，有空常联系吧。','yǐ hòu huí guó yě yào jiān chí liàn xí hàn yǔ， yǒu kòng cháng lián xì ba。','Sau này về nước cũng phải duy trì luyện tiếng Trung nhé, rảnh thì thường xuyên liên lạc nha.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_05','V400','阮明',5,'我回国会经常给您发消息，也会记得和同学们保持联络。','wǒ huí guó huì jīng cháng gěi nín fā xiāo xī， yě huì jì de hé tóng xué men bǎo chí lián luò。','Em về nước sẽ hay nhắn tin cho cô, cũng sẽ nhớ giữ liên lạc với các bạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_06','V400','李老师',6,'一路平安，祝你回国之后一切顺利。','yí lù píng ān， zhù nǐ huí guó zhī hòu yī qiè shùn lì。','Chúc em thượng lộ bình an, mong mọi thứ suôn sẻ sau khi em về nước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L400_07','V400','阮明',7,'谢谢老师两年的照顾，我永远不会忘记这段时光。','xiè xiè lǎo shī liǎng nián de zhào gù， wǒ yǒng yuǎn bú huì wàng jì zhè duàn shí guāng。','Em cảm ơn cô đã chăm lo cho em suốt hai năm qua, em sẽ không bao giờ quên khoảng thời gian này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT501','SV1','入境30天内前往国际学院登记备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V501','SIT501','P1','twist','ban_chinh_thuc',NULL,'外籍留学生入境后必须30日内完成校内住宿登记，超期会影响后续居留许可办理，甚至产生罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_01','V501','阮明',1,'老师您好，我是新来的越南留学生，上周刚从国内入境，今天过来做入境登记备案。','lǎo shī nín hǎo ， wǒ shì xīn lái de yuè nán liú xué shēng ， shàng zhōu gāng cóng guó nèi rù jìng ， jīn tiān guò lái zuò rù jìng dēng jì bèi àn 。','Chào cô, em là du học sinh Việt Nam mới, tuần trước em vừa nhập cảnh từ trong nước, hôm nay em đến làm đăng ký nhập cảnh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_02','V501','老师',2,'好的，把你的护照拿出来，还有入境时海关盖章那一页的复印件，我核对一下信息。','hǎo de ， bǎ nǐ de hù zhào ná chū lái ， hái yǒu rù jìng shí hǎi guān gài zhāng nà yī yè de fù yìn jiàn ， wǒ hé duì yī xià xìn xī 。','Được rồi, em lấy hộ chiếu ra đây, với cả bản photo trang có đóng dấu hải quan lúc nhập cảnh, cô kiểm tra lại thông tin nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_03','V501','阮明',3,'护照我带了，盖章页……我忘记提前打印复印件了，现在没有纸质版。','hù zhào wǒ dài le ， gài zhāng yè …… wǒ wàng jì tí qián dǎ yìn fù yìn jiàn le ， xiàn zài méi yǒu zhǐ zhì bǎn 。','Hộ chiếu em có mang ạ, còn trang đóng dấu... em quên photo trước mất rồi, giờ không có bản giấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_04','V501','老师',4,'那不行，校内登记系统必须留存纸质备案材料，缺一不可。楼下就有打印店，你可以直接下去复印，很快的。','nà bù xíng ， xiào nèi dēng jì xì tǒng bì xū liú cún zhǐ zhì bèi àn cái liào ， quē yī bù kě 。 lóu xià jiù yǒu dǎ yìn diàn ， nǐ kě yǐ zhí jiē xià qù fù yìn ， hěn kuài de 。','Vậy không được đâu, hệ thống đăng ký của trường bắt buộc phải lưu hồ sơ giấy, thiếu là không được. Tầng dưới có tiệm photocopy đấy, em xuống photo luôn cũng nhanh thôi mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_05','V501','阮明',5,'好，那我现在马上下去复印。对了，回来之后还需要填别的表格吗？','hǎo ， nà wǒ xiàn zài mǎ shàng xià qù fù yìn 。 duì le ， huí lái zhī hòu hái xū yào tián bié de biǎo gé ma ？','Dạ vâng, vậy em xuống photo ngay bây giờ. À, sau khi quay lại còn phải điền thêm biểu mẫu nào khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_06','V501','老师',6,'需要填写入境信息登记表，要写清楚你的入境日期、就读专业和宿舍具体房间号，信息必须填准确。','xū yào tián xiě rù jìng xìn xī dēng jì biǎo ， yào xiě qīng chǔ nǐ de rù jìng rì qī 、 jiù dú zhuān yè hé sù shè jù tǐ fáng jiān hào ， xìn xī bì xū tián zhǔn què 。','Cần điền tờ đăng ký thông tin nhập cảnh, phải ghi rõ ngày nhập cảnh, chuyên ngành đang học và số phòng ký túc xá cụ thể của em, thông tin phải điền chính xác nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_07','V501','阮明',7,'了解了。是不是做完这个校内登记，才能去出入境大厅办理居留许可？','liǎo jiě le 。 shì bú shì zuò wán zhè ge xiào nèi dēng jì ， cái néng qù chū rù jìng dà tīng bàn lǐ jū liú xǔ kě ？','Em hiểu rồi ạ. Có phải làm xong đăng ký trong trường này thì mới có thể đến sảnh xuất nhập cảnh làm thủ tục giấy phép cư trú không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_08','V501','老师',8,'没错，这是前置流程。没完成校内住宿入境登记，出入境那边是直接不受理你的签证业务的。','méi cuò ， zhè shì qián zhì liú chéng 。 méi wán chéng xiào nèi zhù sù rù jìng dēng jì ， chū rù jìng nà biān shì zhí jiē bù shòu lǐ nǐ de qiān zhèng yè wù de 。','Đúng vậy, đây là bước bắt buộc trước đó. Nếu chưa hoàn thành đăng ký lưu trú nhập cảnh trong trường thì bên xuất nhập cảnh sẽ không tiếp nhận hồ sơ visa của em đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L501_09','V501','阮明',9,'原来是这样，还好我提前来办理了。我十分钟就能回来，马上办好登记。','yuán lái shì zhè yàng ， hái hǎo wǒ tí qián lái bàn lǐ le 。 wǒ shí fēn zhōng jiù néng huí lái ， mǎ shàng bàn hǎo dēng jì 。','Ra là vậy, may mà em đến làm sớm. Em mười phút nữa sẽ quay lại, làm xong đăng ký ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT502','SV1','提交护照、录取材料申请首次居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V502','SIT502','P1','suon_se','chinh_thuc',NULL,'首次学生居留许可全套材料缺一不可，缺少任意一项都会直接退回不予受理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_01','V502','阮明',1,'您好，我是今年的新生留学生，过来申请办理首次学生居留许可。','nín hǎo ， wǒ shì jīn nián de xīn shēng liú xué shēng ， guò lái shēn qǐng bàn lǐ shǒu cì xué shēng jū liú xǔ kě 。','Chào chị, em là tân sinh viên du học năm nay, em đến xin làm thủ tục cấp giấy phép cư trú lần đầu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_02','V502','工作人员',2,'可以的，把所需材料依次递过来，护照、录取通知书、体检报告、住宿登记单，全部都要。','kě yǐ de ， bǎ suǒ xū cái liào yī cì dì guò lái ， hù zhào 、 lù qǔ tōng zhī shū 、 tǐ jiǎn bào gào 、 zhù sù dēng jì dān ， quán bù dōu yào 。','Được, em đưa lần lượt các giấy tờ cần thiết ra đây, hộ chiếu, giấy báo nhập học, giấy khám sức khỏe, phiếu đăng ký lưu trú, tất cả đều cần cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_03','V502','阮明',3,'好的，我都提前整理好了，一式两份，您直接核对就行。','hǎo de ， wǒ dōu tí qián zhěng lǐ hǎo le ， yī shì liǎng fèn ， nín zhí jiē hé duì jiù xíng 。','Dạ, em đã chuẩn bị sẵn hết rồi ạ, mỗi loại hai bản, chị kiểm tra trực tiếp là được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_04','V502','工作人员',4,'我逐一核对一下……信息全部匹配，材料齐全没有问题，这是你的受理回执，你收好。','wǒ zhú yī hé duì yī xià …… xìn xī quán bù pǐ pèi ， cái liào qí quán méi yǒu wèn tí ， zhè shì nǐ de shòu lǐ huí zhí ， nǐ shōu hǎo 。','Để chị kiểm tra từng cái một nhé... thông tin khớp hết rồi, giấy tờ đầy đủ không có vấn đề gì, đây là biên nhận tiếp nhận hồ sơ của em, em giữ cẩn thận nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_05','V502','阮明',5,'好的，谢谢！我想问一下，大概多久能办好拿到居留贴纸？','hǎo de ， xiè xiè ！ wǒ xiǎng wèn yī xià ， dà gài duō jiǔ néng bàn hǎo ná dào jū liú tiē zhǐ ？','Dạ vâng, cảm ơn chị! Cho em hỏi, khoảng bao lâu thì em nhận được thẻ cư trú ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_06','V502','工作人员',6,'普通办理是七个工作日，要是着急的话，可以申请加急，三个工作日就能办结。','pǔ tōng bàn lǐ shì qī gè gōng zuò rì ， yào shì zháo jí de huà ， kě yǐ shēn qǐng jiā jí ， sān gè gōng zuò rì jiù néng bàn jié 。','Xử lý thông thường là bảy ngày làm việc, nếu gấp thì có thể đăng ký làm nhanh, ba ngày làm việc là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_07','V502','阮明',7,'了解了。那取件可以让人代领吗？还是必须我本人过来？','liǎo jiě le 。 nà qǔ jiàn kě yǐ ràng rén dài lǐng ma ？ hái shì bì xū wǒ běn rén guò lái ？','Em hiểu rồi ạ. Vậy lúc lấy thẻ có thể nhờ người khác lấy hộ được không hay bắt buộc em phải đến trực tiếp ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_08','V502','工作人员',8,'必须本人携带回执和护照原件到场领取，不支持代领。','bì xū běn rén xié dài huí zhí hé hù zhào yuán jiàn dào chǎng lǐng qǔ ， bù zhī chí dài lǐng 。','Bắt buộc phải chính chủ mang biên nhận và hộ chiếu gốc đến lấy trực tiếp, không hỗ trợ nhờ người khác lấy hộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L502_09','V502','阮明',9,'好，我清楚所有流程了，麻烦您帮忙受理啦！','hǎo ， wǒ qīng chǔ suǒ yǒu liú chéng le ， má fán nín bāng máng shòu lǐ la ！','Dạ, em nắm rõ hết quy trình rồi, phiền chị giúp em xử lý hồ sơ nhé ạ!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT503','SV1','体检不合格，需要重新预约出入境体检',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V503','SIT503','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生签证专用体检必须在出入境指定医院完成，体检不合格无法提交居留申请，复查需全额自费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_01','V503','阮明',1,'医生，我刚拿到出入境的体检报告，显示不合格，办不了签证。','yī shēng ， wǒ gāng ná dào chū rù jìng de tǐ jiǎn bào gào ， xiǎn shì bù hé gé ， bàn bù liǎo qiān zhèng 。','Bác sĩ ơi, em vừa nhận được báo cáo khám sức khỏe xuất nhập cảnh, kết quả không đạt, không làm visa được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_02','V503','校医',2,'我看一下报告。嗯，主要是肝功能指标偏高，属于临时异常，不符合签证体检的合格标准。','wǒ kàn yī xià bào gào 。 ń ， zhǔ yào shì gān gōng néng zhǐ biāo piān gāo ， shǔ yú lín shí yì cháng ， bù fú hé qiān zhèng tǐ jiǎn de hé gé biāo zhǔn 。','Để bác xem báo cáo nào. Ừm, chủ yếu là chỉ số chức năng gan hơi cao, thuộc dạng bất thường tạm thời, không đạt tiêu chuẩn khám sức khỏe cho visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_03','V503','阮明',3,'啊？那能不能只单独复查这一项？不用全套重新查吧？','a ？ nà néng bù néng zhǐ dān dú fù chá zhè yī xiàng ？ bù yòng quán tào chóng xīn chá ba ？','Hả? Vậy có thể chỉ khám lại riêng mục này thôi không ạ? Không cần khám lại toàn bộ chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_04','V503','校医',4,'不行的，出入境中心有规定，单项异常不支持单独复查。','bù xíng de ， chū rù jìng zhōng xīn yǒu guī dìng ， dān xiàng yì cháng bù zhī chí dān dú fù chá 。','Không được đâu, trung tâm xuất nhập cảnh có quy định, bất thường ở một mục thì không được khám lại riêng lẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_05','V503','阮明',5,'这样啊……那我现在该怎么办？','zhè yàng a …… nà wǒ xiàn zài gāi zěn me bàn ？','Vậy à... vậy giờ em phải làm sao ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_06','V503','校医',6,'你接下来一周清淡饮食、别熬夜、不喝酒，一周之后再来重新预约全套体检。','nǐ jiē xià lái yī zhōu qīng dàn yǐn shí 、 bié áo yè 、 bù hē jiǔ ， yī zhōu zhī hòu zài lái chóng xīn yù yuē quán tào tǐ jiǎn 。','Em về ăn uống thanh đạm trong một tuần tới, đừng thức khuya, đừng uống rượu bia, một tuần sau quay lại đặt lịch khám lại toàn bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_07','V503','阮明',7,'重新全套体检的话，是不是要重新交一整套费用？','chóng xīn quán tào tǐ jiǎn de huà ， shì bú shì yào chóng xīn jiāo yī zhěng tào fèi yòng ？','Nếu khám lại toàn bộ thì em có phải đóng lại toàn bộ chi phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_08','V503','校医',8,'对的，复查没有减免，必须全额缴费，和第一次体检流程一样。','duì de ， fù chá méi yǒu jiǎn miǎn ， bì xū quán é jiǎo fèi ， hé dì yī cì tǐ jiǎn liú chéng yī yàng 。','Đúng vậy, khám lại không được giảm trừ gì cả, phải đóng đủ phí, quy trình giống hệt lần khám đầu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_09','V503','阮明',9,'我明白了。那我一周后直接在网上预约就行？','wǒ míng bái le 。 nà wǒ yī zhōu hòu zhí jiē zài wǎng shàng yù yuē jiù xíng ？','Em hiểu rồi ạ. Vậy một tuần sau em đặt lịch trực tiếp trên mạng là được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_10','V503','校医',10,'可以线上预约，过来的时候把这次不合格的报告带上，方便医生对比数据，排除持续性异常。','kě yǐ xiàn shàng yù yuē ， guò lái de shí hòu bǎ zhè cì bù hé gé de bào gào dài shàng ， fāng biàn yī shēng duì bǐ shù jù ， pái chú chí xù xìng yì cháng 。','Có thể đặt lịch online, lúc đến thì mang theo báo cáo không đạt lần này, để bác sĩ tiện đối chiếu số liệu, loại trừ trường hợp bất thường kéo dài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L503_11','V503','阮明',11,'好，那我这几天好好调整作息，一周后再来重新体检。','hǎo ， nà wǒ zhè jǐ tiān hǎo hǎo tiáo zhěng zuò xī ， yī zhōu hòu zài lái chóng xīn tǐ jiǎn 。','Dạ vâng, vậy mấy ngày tới em sẽ điều chỉnh sinh hoạt cho tốt, một tuần sau em quay lại khám lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT504','SV1','忘记携带境外录取通知书原件，无法提交签证材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V504','SIT504','P1','that_bai_nhe','chinh_thuc',NULL,'出入境办理居留许可严格核验纸质原件，电子照片、复印件均不具备受理效力，必须线下现场核验。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_01','V504','阮明',1,'您好，我来提交居留许可的申请材料，麻烦您帮我审核一下。','nín hǎo ， wǒ lái tí jiāo jū liú xǔ kě de shēn qǐng cái liào ， má fán nín bāng wǒ shěn hé yī xià 。','Chào chị, em đến nộp hồ sơ xin giấy phép cư trú, phiền chị kiểm tra giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_02','V504','工作人员',2,'好的，请出示你的境外录取通知书原件。','hǎo de ， qǐng chū shì nǐ de jìng wài lù qǔ tōng zhī shū yuán jiàn 。','Được, em cho chị xem bản gốc giấy báo nhập học ở nước ngoài của em nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_03','V504','阮明',3,'糟了……我只带了复印件，原件落在宿舍了，忘记拿过来。','zāo le …… wǒ zhǐ dài le fù yìn jiàn ， yuán jiàn luò zài sù shè le ， wàng jì ná guò lái 。','Chết rồi... em chỉ mang bản photo thôi, bản gốc để quên ở ký túc xá, em quên mang theo mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_04','V504','工作人员',4,'抱歉，签证审核必须核验纸质原件，复印件是无效的，不能受理。','bào qiàn ， qiān zhèng shěn hé bì xū hé yàn zhǐ zhì yuán jiàn ， fù yìn jiàn shì wú xiào de ， bù néng shòu lǐ 。','Xin lỗi em, khâu xét duyệt visa bắt buộc phải kiểm tra bản gốc giấy tờ, bản photo không có giá trị, chị không thể tiếp nhận được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_05','V504','阮明',5,'那能不能通融一下？我手机里有原件的高清照片，先帮我建档，我明天马上补交原件可以吗？','nà néng bù néng tōng róng yī xià ？ wǒ shǒu jī lǐ yǒu yuán jiàn de gāo qīng zhào piān ， xiān bāng wǒ jiàn dàng ， wǒ míng tiān mǎ shàng bǔ jiāo yuán jiàn kě yǐ ma ？','Vậy có thể châm chước một chút được không ạ? Trong điện thoại em có ảnh chụp bản gốc độ phân giải cao, chị giúp em lập hồ sơ trước, mai em bổ sung bản gốc ngay được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_06','V504','工作人员',6,'不行的，这是系统硬性规定。材料不齐没办法录入系统建档，只能改天带齐原件再来办理。','bù xíng de ， zhè shì xì tǒng yìng xìng guī dìng 。 cái liào bù qí méi bàn fǎ lù rù xì tǒng jiàn dàng ， zhǐ néng gǎi tiān dài qí yuán jiàn zài lái bàn lǐ 。','Không được đâu em, đây là quy định cứng của hệ thống. Hồ sơ chưa đủ thì không thể nhập vào hệ thống để lập hồ sơ được, chỉ có thể hôm khác mang đủ bản gốc rồi đến làm lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_07','V504','阮明',7,'我明白了。那我明天一早过来可以吗？','wǒ míng bái le 。 nà wǒ míng tiān yī zǎo guò lái kě yǐ ma ？','Em hiểu rồi ạ. Vậy mai sáng sớm em qua được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_08','V504','工作人员',8,'可以，我们明天正常上班。建议你早点来，上午号源比较充足，不用久等。','kě yǐ ， wǒ men míng tiān zhèng cháng shàng bān 。 jiàn yì nǐ zǎo diǎn lái ， shàng wǔ hào yuán bǐ jiào chōng zú ， bù yòng jiǔ děng 。','Được chứ, mai chúng tôi làm việc bình thường. Chị khuyên em đến sớm một chút, buổi sáng số thứ tự còn nhiều, không phải chờ lâu đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L504_09','V504','阮明',9,'好的，实在不好意思，是我疏忽了，耽误您时间了。','hǎo de ， shí zài bù hǎo yì sī ， shì wǒ shū hū le ， dān wù nín shí jiān le 。','Dạ vâng, em thật sự xin lỗi, tại em sơ suất nên làm mất thời gian của chị ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT505','SV1','咨询留学生居留许可有效时长与入境截止规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V505','SIT505','P1','suon_se','ban_chinh_thuc',NULL,'学生居留许可最长与学制同步，到期断签属于非法滞留，会产生罚款并影响后续再次来华签证。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_01','V505','阮明',1,'警官您好，我想咨询一下留学生居留许可的有效期问题。','jǐng guān nín hǎo ， wǒ xiǎng zī xún yī xià liú xué shēng jū liú xǔ kě de yǒu xiào qī wèn tí 。','Chào anh công an, em muốn hỏi về vấn đề thời hạn hiệu lực của giấy phép cư trú dành cho du học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_02','V505','辅警',2,'没问题，学生居留许可的时长是跟你的学制对应的，本科留学生一般一次批一年有效期。','méi wèn tí ， xué shēng jū liú xǔ kě de shí cháng shì gēn nǐ de xué zhì duì yìng de ， běn kē liú xué shēng yì bān yī cì pī yī nián yǒu xiào qī 。','Không vấn đề gì, thời hạn giấy phép cư trú của du học sinh sẽ tương ứng với thời gian học của em, du học sinh đại học thông thường mỗi lần cấp có hiệu lực một năm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_03','V505','阮明',3,'那我寒暑假回国，只要居留证没过期，来回出入境都没问题是吗？','nà wǒ hán shǔ jià huí guó ， zhǐ yào jū liú zhèng mò guò qī ， lái huí chū rù jìng dōu méi wèn tí shì ma ？','Vậy nếu em về nước dịp nghỉ đông nghỉ hè, chỉ cần thẻ cư trú chưa hết hạn thì đi lại xuất nhập cảnh nhiều lần đều không sao đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_04','V505','辅警',4,'对，有效期内可以多次出入境，不用额外报备。但千万不能超期滞留，会有罚款和不良记录的。','duì ， yǒu xiào qī nèi kě yǐ duō cì chū rù jìng ， bù yòng é wài bào bèi 。 dàn qiān wàn bù néng chāo qī zhì liú ， huì yǒu fá kuǎn hé bù liáng jì lù de 。','Đúng vậy, trong thời hạn hiệu lực thì được xuất nhập cảnh nhiều lần, không cần báo cáo thêm gì cả. Nhưng tuyệt đối không được ở quá hạn, sẽ bị phạt tiền và có tiền sử xấu đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_05','V505','阮明',5,'了解了。那居留证快到期的话，最晚要提前多久申请续签？','liǎo jiě le 。 nà jū liú zhèng kuài dào qī de huà ， zuì wǎn yào tí qián duō jiǔ shēn qǐng xù qiān ？','Em hiểu rồi ạ. Vậy nếu thẻ cư trú sắp hết hạn thì chậm nhất phải xin gia hạn trước bao lâu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_06','V505','辅警',6,'最好提前三十天提交申请，预留出审核周期，避免出现断签的情况。','zuì hǎo tí qián sān shí tiān tí jiāo shēn qǐng ， yù liú chū shěn hé zhōu qī ， bì miǎn chū xiàn duàn qiān de qíng kuàng 。','Tốt nhất nên nộp hồ sơ trước ba mươi ngày, để dành thời gian cho quá trình xét duyệt, tránh bị gián đoạn thời hạn cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_07','V505','阮明',7,'还有一个问题，我入境签证上有个最晚入境日期，那个是必须遵守的吗？','hái yǒu yí gè wèn tí ， wǒ rù jìng qiān zhèng shàng yǒu gè zuì wǎn rù jìng rì qī ， nà ge shì bì xū zūn shǒu de ma ？','Còn một vấn đề nữa, trên visa nhập cảnh của em có ghi ngày nhập cảnh muộn nhất, cái đó có bắt buộc phải tuân thủ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_08','V505','辅警',8,'必须的，一定要在标注日期前入境，一旦逾期，这张签证就直接作废了。','bì xū de ， yí dìng yào zài biāo zhù rì qī qián rù jìng ， yí dàn yú qī ， zhè zhāng qiān zhèng jiù zhí jiē zuò fèi le 。','Bắt buộc chứ, nhất định phải nhập cảnh trước ngày ghi trên đó, một khi quá hạn thì visa này coi như bị hủy luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L505_09','V505','阮明',9,'嗯，所有规则我都记清楚了，谢谢您！','ń ， suǒ yǒu guī zé wǒ dōu jì qīng chǔ le ， xiè xiè nín ！','Dạ, tất cả các quy định em đã nhớ rõ rồi, em cảm ơn anh ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT506','SV1','学校统一代办居留签证，补交缺失的白底证件照',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V506','SIT506','P1','twist','tuy_y',NULL,'出入境签证证件照有统一尺寸、底色标准，照相馆会区分普通证件照与涉外签证专用照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_01','V506','老师',1,'阮明，等一下，你的签证材料还差一样东西。','ruǎn míng ， děng yí xià ， nǐ de qiān zhèng cái liào hái chà yī yàng dōng xī 。','Nguyễn Minh, khoan đã, hồ sơ xin visa của em còn thiếu một thứ nữa đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_02','V506','阮明',2,'啊？我上周不是已经把证件照交上去了吗？','a ？ wǒ shàng zhōu bú shì yǐ jīng bǎ zhèng jiàn zhào jiāo shàng qù le ma ？','Hả? Tuần trước em nộp ảnh thẻ rồi mà cô?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_03','V506','老师',3,'你上次交的是普通生活照，不符合出入境签证的照片标准，用不了。','nǐ shàng cì jiāo de shì pǔ tōng shēng huó zhào ， bù fú hé chū rù jìng qiān zhèng de zhào piān biāo zhǔn ， yòng bù liǎo 。','Lần trước em nộp là ảnh sinh hoạt bình thường, không đúng chuẩn ảnh dùng cho visa xuất nhập cảnh, không dùng được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_04','V506','阮明',4,'这样啊……那需要什么样的照片？','zhè yàng a …… nà xū yào shén me yàng de zhào piān ？','Vậy à... thế cần ảnh kiểu gì ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_05','V506','老师',5,'得是小二寸的白底免冠证件照，专门用来办签证的那种。','dé shì xiǎo èr cùn de bái dǐ miǎn guān zhèng jiàn zhào ， zhuān mén yòng lái bàn qiān zhèng de nà zhǒng 。','Phải là ảnh thẻ cỡ 2 nhỏ, nền trắng, không đội mũ, loại chuyên dùng để làm visa ấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_06','V506','阮明',6,'楼下的照相馆能拍吗？我怕拍出来还是不达标。','lóu xià de zhào xiàng guǎn néng pāi ma ？ wǒ pà pāi chū lái hái shì bù dá biāo 。','Tiệm ảnh dưới lầu chụp được không cô? Em sợ chụp xong lại không đạt chuẩn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_07','V506','老师',7,'可以的，你直接跟摄影师说，是留学生办居留许可用的，他们都知道统一规格。','kě yǐ de ， nǐ zhí jiē gēn shè yǐng shī shuō ， shì liú xué shēng bàn jū liú xǔ kě yòng de ， tā men dōu zhī dào tǒng yī guī gé 。','Được đấy, em cứ nói thẳng với thợ chụp là ảnh để du học sinh làm giấy phép cư trú, họ đều biết quy cách chung mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_08','V506','阮明',8,'行，那我现在立马下去拍。拍完直接拿给您，还需要补填别的表格吗？','xíng ， nà wǒ xiàn zài lì mǎ xià qù pāi 。 pāi wán zhí jiē ná gěi nín ， hái xū yào bǔ tián bié de biǎo gé ma ？','Dạ được, vậy em xuống chụp ngay bây giờ. Chụp xong em đem lên nộp cô luôn, có cần điền thêm giấy tờ gì nữa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_09','V506','老师',9,'不用填表，就只交纸质照片就行，你其他的信息系统里都存档了。','bù yòng tián biǎo ， jiù zhǐ jiāo zhǐ zhì zhào piān jiù xíng ， nǐ qí tā de xìn xī xì tǒng lǐ dōu cún dàng le 。','Không cần điền gì cả, chỉ nộp ảnh giấy thôi là được, các thông tin khác của em hệ thống đã lưu hết rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L506_10','V506','阮明',10,'好嘞，我很快就回来！','hǎo lei ， wǒ hěn kuài jiù huí lái ！','Dạ vâng, em đi nhanh rồi quay lại ngay!','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT507','SV1','入境停留超期，前往出入境大厅办理逾期说明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V507','SIT507','P1','twist','chinh_thuc',NULL,'外籍人员在华签证超期属于非法滞留，会根据超期天数罚款，多次逾期会被限制入境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_01','V507','阮明',1,'警官您好，我想来处理一下我的入境逾期问题。','jǐng guān nín hǎo ， wǒ xiǎng lái chǔ lǐ yī xià wǒ de rù jìng yú qī wèn tí 。','Chào anh công an, tôi muốn xử lý vấn đề nhập cảnh quá hạn của mình ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_02','V507','民警',2,'具体是什么情况？超期停留了多久，说一下原因。','jù tǐ shì shén me qíng kuàng ？ chāo qī tíng liú le duō jiǔ ， shuō yī xià yuán yīn 。','Cụ thể là tình huống thế nào? Quá hạn bao lâu rồi, anh nói rõ nguyên nhân xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_03','V507','阮明',3,'我之前出境旅游，本来按时返程，结果遇到航班大面积延误，最后在国内多停留了五天。','wǒ zhī qián chū jìng lǚ yóu ， běn lái àn shí fǎn chéng ， jié guǒ yù dào háng bān dà miàn jī yán wù ， zuì hòu zài guó nèi duō tíng liú le wǔ tiān 。','Trước đó tôi xuất cảnh du lịch, vốn định về đúng hạn, nhưng gặp phải chuyến bay bị hoãn trên diện rộng, nên cuối cùng ở lại trong nước thêm năm ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_04','V507','民警',4,'我看一下你的材料，机票行程单、学校在读证明都带了吗？','wǒ kàn yī xià nǐ de cái liào ， jī piào xíng chéng dān 、 xué xiào zài dú zhèng míng dōu dài le ma ？','Để tôi xem hồ sơ của anh, vé máy bay, lịch trình chuyến đi, giấy xác nhận đang học của trường, anh mang đủ chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_05','V507','阮明',5,'都带来了，这是我的行程单，确实是航班原因导致的延误。','dōu dài lái le ， zhè shì wǒ de xíng chéng dān ， què shí shì háng bān yuán yīn dǎo zhì de yán wù 。','Tôi mang đủ hết rồi, đây là lịch trình chuyến đi của tôi, đúng là do chuyến bay bị hoãn gây ra thật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_06','V507','民警',6,'五天属于短期超期，十五天以内的逾期，只要书面说明情况就可以，不会加重处罚。要是超过十五天，处理就严格多了。','wǔ tiān shǔ yú duǎn qī chāo qī ， shí wǔ tiān yǐ nèi de yú qī ， zhǐ yào shū miàn shuō míng qíng kuàng jiù kě yǐ ， bú huì jiā zhòng chǔ fá 。 yào shì chāo guò shí wǔ tiān ， chǔ lǐ jiù yán gé duō le 。','Năm ngày thuộc dạng quá hạn ngắn, trong vòng mười lăm ngày thì chỉ cần làm bản tường trình bằng văn bản là được, không bị xử phạt nặng. Nếu quá mười lăm ngày thì xử lý sẽ nghiêm ngặt hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_07','V507','阮明',7,'那我这次逾期，会留下不良记录吗？会不会影响我下次续签居留证？','nà wǒ zhè cì yú qī ， huì liú xià bù liáng jì lù ma ？ huì bú huì yǐng xiǎng wǒ xià cì xù qiān jū liú zhèng ？','Vậy lần quá hạn này có để lại hồ sơ xấu không anh? Có ảnh hưởng đến việc gia hạn thẻ cư trú lần sau của tôi không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_08','V507','民警',8,'你是首次违规，而且是客观航班延误原因，如实报备说明后，不会对你后续续签造成严重影响。','nǐ shì shǒu cì wéi guī ， ér qiě shì kè guān háng bān yán wù yuán yīn ， rú shí bào bèi shuō míng hòu ， bú huì duì nǐ hòu xù xù qiān zào chéng yán zhòng yǐng xiǎng 。','Anh là vi phạm lần đầu, với lại lý do là chuyến bay bị hoãn khách quan, sau khi khai báo trung thực thì sẽ không ảnh hưởng nghiêm trọng đến việc gia hạn sau này của anh đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_09','V507','阮明',9,'那就好。我需要手写一份逾期情况说明，然后签字上交是吗？','nà jiù hǎo 。 wǒ xū yào shǒu xiě yī fèn yú qī qíng kuàng shuō míng ， rán hòu qiān zì shàng jiāo shì ma ？','Vậy thì tốt quá. Tôi cần viết tay một bản tường trình tình hình quá hạn, rồi ký tên nộp lên phải không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_10','V507','民警',10,'对的，写完核对好个人信息签字，再缴纳对应的逾期罚款就办结了。','duì de ， xiě wán hé duì hǎo gè rén xìn xī qiān zì ， zài jiǎo nà duì yìng de yú qī fá kuǎn jiù bàn jié le 。','Đúng rồi, viết xong kiểm tra lại thông tin cá nhân cho khớp rồi ký tên, sau đó nộp phạt quá hạn tương ứng là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L507_11','V507','阮明',11,'好，我现在马上写，全力配合处理。','hǎo ， wǒ xiàn zài mǎ shàng xiě ， quán lì pèi hé chǔ lǐ 。','Vâng, tôi viết ngay bây giờ, sẽ phối hợp hết mình để xử lý ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT508','SV1','咨询单人宿舍住宿登记如何录入居留系统',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V508','SIT508','P1','suon_se','tuy_y',NULL,'所有外籍居住人员必须完成住宿登记，校内宿舍由宿管开具登记证明，校外租房由房东陪同社区备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_01','V508','阮明',1,'阿姨，想问个事，我住的是单人宿舍，住宿登记要怎么弄啊？办签证要用。','ā yí ， xiǎng wèn gè shì ， wǒ zhù de shì dān rén sù shè ， zhù sù dēng jì yào zěn me nòng a ？ bàn qiān zhèng yào yòng 。','Cô ơi, con hỏi cái này chút, con ở phòng ký túc xá một người, đăng ký lưu trú phải làm thế nào ạ? Con cần để làm visa.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_02','V508','宿管阿姨',2,'简单，我这边直接给你打印住宿登记单，盖宿舍楼的公章就可以用了。','jiǎn dān ， wǒ zhè biān zhí jiē gěi nǐ dǎ yìn zhù sù dēng jì dān ， gài sù shè lóu de gōng zhāng jiù kě yǐ yòng le 。','Đơn giản mà, cô in ngay cho con tờ đăng ký lưu trú, đóng dấu của khu ký túc xá là dùng được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_03','V508','阮明',3,'那单人宿舍和多人宿舍的单子是一样的吗？我怕格式不对用不了。','nà dān rén sù shè hé duō rén sù shè de dān zi shì yī yàng de ma ？ wǒ pà gé shì bú duì yòng bù liǎo 。','Vậy tờ đăng ký của phòng một người với phòng nhiều người có giống nhau không cô? Con sợ sai mẫu thì không dùng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_04','V508','宿管阿姨',4,'单据都是通用的，你是单人住，我就在人数那一栏填“单人”就行，不影响。','dān jù dōu shì tōng yòng de ， nǐ shì dān rén zhù ， wǒ jiù zài rén shù nà yī lán tián “ dān rén ” jiù xíng ， bù yǐng xiǎng 。','Mẫu đơn dùng chung hết, con ở một mình thì cô ghi vào ô số người là "một người" là được, không ảnh hưởng gì đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_05','V508','阮明',5,'明白啦，那我拿到单子直接去出入境大厅交材料就行？','míng bái la ， nà wǒ ná dào dān zi zhí jiē qù chū rù jìng dà tīng jiāo cái liào jiù xíng ？','Dạ con hiểu rồi, vậy con cầm tờ này đến thẳng phòng xuất nhập cảnh nộp hồ sơ là được ạ?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_06','V508','宿管阿姨',6,'对，这张单子就是证明你在校合法住宿的关键材料，办居留必须要的。','duì ， zhè zhāng dān zi jiù shì zhèng míng nǐ zài xiào hé fǎ zhù sù de guān jiàn cái liào ， bàn jū liú bì xū yào de 。','Đúng vậy, tờ giấy này chính là giấy tờ quan trọng chứng minh con ở trọ hợp pháp trong trường, làm cư trú bắt buộc phải có đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L508_07','V508','阮明',7,'那麻烦阿姨帮我打印一份呗，我下午就去办签证。','nà má fán ā yí bāng wǒ dǎ yìn yī fèn bei ， wǒ xià wǔ jiù qù bàn qiān zhèng 。','Vậy phiền cô in giúp con một bản nhé, chiều nay con đi làm visa luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT509','SV2','居留许可快到期，提前咨询续办流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V509','SIT509','P1','suon_se','ban_chinh_thuc',NULL,'居留续签不能使用过期住宿登记、旧流水，所有辅助材料要求近期开具，保证信息实时有效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_01','V509','阮明',1,'老师，我的居留许可还有四十天就到期了，我想提前问问续签的流程。','lǎo shī ， wǒ de jū liú xǔ kě hái yǒu sì shí tiān jiù dào qī le ， wǒ xiǎng tí qián wèn wèn xù qiān de liú chéng 。','Thưa cô, thẻ cư trú của em còn bốn mươi ngày nữa là hết hạn, em muốn hỏi trước về quy trình gia hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_02','V509','老师',2,'可以的，你提前准备刚好。首先要去学院开在读证明，然后备好银行存款流水。','kě yǐ de ， nǐ tí qián zhǔn bèi gāng hǎo 。 shǒu xiān yào qù xué yuàn kāi zài dú zhèng míng ， rán hòu bèi hǎo yín háng cún kuǎn liú shuǐ 。','Được chứ, em chuẩn bị trước như vậy là vừa đúng lúc. Trước tiên em cần lên khoa xin giấy xác nhận đang học, sau đó chuẩn bị sao kê số dư ngân hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_03','V509','阮明',3,'存款流水有要求吗？需要多少钱、存多久？','cún kuǎn liú shuǐ yǒu yāo qiú ma ？ xū yào duō shǎo qián 、 cún duō jiǔ ？','Sao kê số dư có yêu cầu gì không cô? Cần bao nhiêu tiền, gửi trong bao lâu ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_04','V509','老师',4,'留学生续签，建议准备不低于一万元的活期流水，最好是连续三个月以上的记录，更稳妥。','liú xué shēng xù qiān ， jiàn yì zhǔn bèi bù dī yú yī wàn yuán de huó qī liú shuǐ ， zuì hǎo shì lián xù sān gè yuè yǐ shàng de jì lù ， gèng wěn tuǒ 。','Du học sinh gia hạn thì nên chuẩn bị sao kê tài khoản thanh toán không dưới mười nghìn tệ, tốt nhất là có số dư liên tục từ ba tháng trở lên, sẽ chắc chắn hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_05','V509','阮明',5,'那我上次办签证的旧住宿登记单还能用吗？不想再重新开了。','nà wǒ shàng cì bàn qiān zhèng de jiù zhù sù dēng jì dān hái néng yòng ma ？ bù xiǎng zài chóng xīn kāi le 。','Vậy tờ đăng ký lưu trú cũ em dùng lần trước còn dùng được không ạ? Em không muốn xin lại nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_06','V509','老师',6,'不行哦，续签要求很严格，必须是近一个月新开具的登记单，旧的已经失效了。','bù xíng ó ， xù qiān yāo qiú hěn yán gé ， bì xū shì jìn yí gè yuè xīn kāi jù de dēng jì dān ， jiù de yǐ jīng shī xiào le 。','Không được đâu, yêu cầu gia hạn rất nghiêm ngặt, phải là tờ đăng ký mới cấp trong vòng một tháng gần đây, tờ cũ hết hiệu lực rồi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_07','V509','阮明',7,'懂了。那我材料全部备齐之后，线上预约号就能直接去办了吧？','dǒng le 。 nà wǒ cái liào quán bù bèi qí zhī hòu ， xiàn shàng yù yuē hào jiù néng zhí jiē qù bàn le ba ？','Em hiểu rồi. Vậy sau khi chuẩn bị đủ hồ sơ, em đặt lịch hẹn trực tuyến rồi đi làm luôn được phải không cô?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_08','V509','老师',8,'对，线上预约可以优先办理，不用排队。没预约的话，只能现场等空位，很耗时间。','duì ， xiàn shàng yù yuē kě yǐ yōu xiān bàn lǐ ， bù yòng pái duì 。 méi yù yuē de huà ， zhǐ néng xiàn chǎng děng kòng wèi ， hěn hào shí jiān 。','Đúng vậy, đặt lịch hẹn trực tuyến sẽ được ưu tiên xử lý, không cần xếp hàng. Nếu không đặt lịch thì chỉ có thể chờ chỗ trống tại chỗ thôi, rất mất thời gian.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L509_09','V509','阮明',9,'好，我尽快把所有材料整理齐全，避免到期来不及办理。','hǎo ， wǒ jǐn kuài bǎ suǒ yǒu cái liào zhěng lǐ qí quán ， bì miǎn dào qī lái bù jí bàn lǐ 。','Dạ, em sẽ nhanh chóng chuẩn bị đầy đủ hồ sơ, tránh để gần hết hạn mà không kịp làm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT510','SV2','续签证时银行存款证明余额不足，需重新开流水',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V510','SIT510','P1','that_bai_nhe','chinh_thuc',NULL,'留学生续签居留许可有活期存款最低额度要求，出入境只认可活期账户流水，定期、理财不计入审核余额。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_01','V510','阮明',1,'您好，我来递交居留续签的材料，麻烦您帮我核对一下。','nín hǎo ， wǒ lái dì jiāo jū liú xù qiān de cái liào ， má fán nín bāng wǒ hé duì yī xià 。','Chào anh, tôi đến nộp hồ sơ gia hạn thẻ cư trú, phiền anh kiểm tra giúp tôi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_02','V510','工作人员',2,'我看一下你的银行流水……不好意思，月末活期余额不够一万，达不到签证审核标准。','wǒ kàn yī xià nǐ de yín háng liú shuǐ …… bù hǎo yì sī ， yuè mò huó qī yú é bù gòu yī wàn ， dá bú dào qiān zhèng shěn hé biāo zhǔn 。','Để tôi xem sao kê ngân hàng của anh một chút... Xin lỗi, số dư tài khoản thanh toán cuối tháng không đủ mười nghìn, chưa đạt tiêu chuẩn xét duyệt visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_03','V510','阮明',3,'啊？可是我卡里有定期存款，能不能把定期单一起交上去，当作资产证明？','a ？ kě shì wǒ kǎ lǐ yǒu dìng qī cún kuǎn ， néng bù néng bǎ dìng qī dān yī qǐ jiāo shàng qù ， dàng zuò zī chǎn zhèng míng ？','Hả? Nhưng thẻ tôi có tiền gửi tiết kiệm kỳ hạn, có thể nộp kèm sổ tiết kiệm đó để làm chứng minh tài sản không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_04','V510','工作人员',4,'不可以的，系统只认可活期账户的实时余额，定期、理财这些都不算数。','bù kě yǐ de ， xì tǒng zhǐ rèn kě huó qī zhàng hù de shí shí yú é ， dìng qī 、 lǐ cái zhè xiē dōu bù suàn shù 。','Không được, hệ thống chỉ công nhận số dư thực tế của tài khoản thanh toán thôi, tiền gửi kỳ hạn hay đầu tư gì đó đều không tính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_05','V510','阮明',5,'这样啊。那我现在转钱进去，明天重新打流水再来办理可以吗？','zhè yàng a 。 nà wǒ xiàn zài zhuǎn qián jìn qù ， míng tiān chóng xīn dǎ liú shuǐ zài lái bàn lǐ kě yǐ ma ？','Vậy à. Vậy giờ tôi chuyển tiền vào, mai in lại sao kê rồi đến làm lại được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_06','V510','工作人员',6,'可以的，资金入账后建议隔天再打印流水，数据才会更新完整，之后重新取号递交就行。','kě yǐ de ， zī jīn rù zhàng hòu jiàn yì gé tiān zài dǎ yìn liú shuǐ ， shù jù cái huì gēng xīn wán zhěng ， zhī hòu chóng xīn qǔ hào dì jiāo jiù xíng 。','Được chứ, sau khi tiền vào tài khoản thì nên đợi qua ngày hôm sau in sao kê, dữ liệu mới cập nhật đầy đủ, sau đó lấy số nộp lại là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_07','V510','阮明',7,'好，那我今天先把其他材料带回去，明天补齐资金再来。','hǎo ， nà wǒ jīn tiān xiān bǎ qí tā cái liào dài huí qù ， míng tiān bǔ qí zī jīn zài lái 。','Vâng, vậy hôm nay tôi mang các giấy tờ khác về trước, mai bổ sung tiền xong rồi quay lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_08','V510','工作人员',8,'提醒你一下，流水打印当天，不要大额转出资金，不然余额又不达标了。','tí xǐng nǐ yī xià ， liú shuǐ dǎ yìn dàng tiān ， bú yào dà é zhuǎn chū zī jīn ， bù rán yú é yòu bù dá biāo le 。','Nhắc anh luôn, ngày in sao kê thì đừng chuyển tiền ra số lượng lớn, không lại không đủ số dư nữa đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L510_09','V510','阮明',9,'我记住了，谢谢您的提醒。','wǒ jì zhù le ， xiè xiè nín de tí xǐng 。','Tôi nhớ rồi, cảm ơn anh đã nhắc nhở.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT511','SV2','在校出勤率不够，学校不给开具签证在读证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V511','SIT511','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内高校对留学生出勤有硬性考核，出勤率不达标学校有权拒开在读证明，无法办理居留续签，严重者会要求限期离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_01','V511','阮明',1,'辅导员您好，我要办居留续签，需要开在读证明，麻烦您帮我办理一下。','fǔ dǎo yuán nín hǎo ， wǒ yào bàn jū liú xù qiān ， xū yào kāi zài dú zhèng míng ， má fán nín bāng wǒ bàn lǐ yī xià 。','Chào thầy, em cần làm gia hạn thẻ cư trú nên cần xin giấy xác nhận đang học, phiền thầy giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_02','V511','辅导员',2,'我查一下你的出勤记录……你这学期旷课次数超标，出勤率没达到学校的硬性标准，暂时开不了。','wǒ chá yī xià nǐ de chū qín jì lù …… nǐ zhè xué qī kuàng kè cì shù chāo biāo ， chū qín lǜ méi dá dào xué xiào de yìng xìng biāo zhǔn ， zàn shí kāi bù liǎo 。','Để thầy kiểm tra chuyên cần của em... học kỳ này em nghỉ học vượt quá số buổi cho phép, tỷ lệ chuyên cần không đạt chuẩn của trường, tạm thời chưa cấp được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_03','V511','阮明',3,'老师，我之前缺课都是因为身体不舒服，我有医院的病假单啊！','lǎo shī ， wǒ zhī qián quē kè dōu shì yīn wèi shēn tǐ bù shū fú ， wǒ yǒu yī yuàn de bìng jià dān a ！','Thầy ơi, trước đó em nghỉ học đều là vì bị ốm mệt trong người, em có giấy nghỉ ốm của bệnh viện mà!','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_04','V511','辅导员',4,'我知道你有单据，但学校规定病假必须提前报备，事后补交的单据，不算合规请假，没办法抵消缺勤记录。','wǒ zhī dào nǐ yǒu dān jù ， dàn xué xiào guī dìng bìng jià bì xū tí qián bào bèi ， shì hòu bǔ jiāo de dān jù ， bù suàn hé guī qǐng jià ， méi bàn fǎ dǐ xiāo quē qín jì lù 。','Thầy biết em có giấy tờ, nhưng quy định của trường là xin nghỉ ốm phải báo trước, giấy tờ bổ sung sau khi đã nghỉ thì không tính là xin phép hợp lệ, không thể trừ vào số buổi vắng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_05','V511','阮明',5,'那现在还有补救的办法吗？我真的急需这份证明办签证。','nà xiàn zài hái yǒu bǔ jiù de bàn fǎ ma ？ wǒ zhēn de jí xū zhè fèn zhèng míng bàn qiān zhèng 。','Vậy giờ có cách nào khắc phục không thầy? Em thực sự đang rất cần giấy này để làm visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_06','V511','辅导员',6,'你接下来一个月全程满勤、不缺一节课，月末核查出勤合格后，我才能给你开证明。','nǐ jiē xià lái yí gè yuè quán chéng mǎn qín 、 bù quē yī jié kè ， yuè mò hé chá chū qín hé gé hòu ， wǒ cái néng gěi nǐ kāi zhèng míng 。','Em phải đi học đầy đủ, không vắng buổi nào trong một tháng tới, đến cuối tháng kiểm tra chuyên cần đạt yêu cầu thì thầy mới cấp giấy cho em được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_07','V511','阮明',7,'可是我的签证马上就到期了，等一个月的话，肯定会断签的！','kě shì wǒ de qiān zhèng mǎ shàng jiù dào qī le ， děng yí gè yuè de huà ， kěn dìng huì duàn qiān de ！','Nhưng visa của em sắp hết hạn rồi, đợi một tháng nữa thì chắc chắn bị đứt visa mất!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_08','V511','辅导员',8,'别急，我帮你开一份特殊情况说明，你先拿着去出入境，申请短期缓冲受理，先稳住签证时效。','bié jí ， wǒ bāng nǐ kāi yī fèn tè shū qíng kuàng shuō míng ， nǐ xiān ná zhe qù chū rù jìng ， shēn qǐng duǎn qī huǎn chōng shòu lǐ ， xiān wěn zhù qiān zhèng shí xiào 。','Đừng lo, thầy sẽ viết cho em một bản giải trình tình huống đặc biệt, em cầm cái đó đến phòng xuất nhập cảnh xin gia hạn xử lý tạm thời, giữ ổn định hiệu lực visa trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L511_09','V511','阮明',9,'太感谢您了！我之后一定好好上课，再也不缺勤了。','tài gǎn xiè nín le ！ wǒ zhī hòu yí dìng hǎo hǎo shàng kè ， zài yě bù quē qín le 。','Em cảm ơn thầy nhiều lắm ạ! Sau này em nhất định sẽ đi học chăm chỉ, không nghỉ học nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT512','SV2','咨询寒暑假居留延期是否需要额外材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V512','SIT512','P1','suon_se','tuy_y',NULL,'留学生寒暑假留校，续签必须额外提交加盖学院公章的留校申请，证明假期在校学习安排。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_01','V512','阮明',1,'警官，问一下哈，我寒暑假不回国，留校的话续签材料和平时一样吗？','jǐng guān ， wèn yī xià hā ， wǒ hán shǔ jià bù huí guó ， liú xiào de huà xù qiān cái liào hé píng shí yī yàng ma ？','Anh công an ơi, em hỏi chút, dịp nghỉ hè nghỉ đông em không về nước, ở lại trường thì hồ sơ gia hạn có giống bình thường không ạ?','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_02','V512','辅警',2,'大体材料都一样，就多一份东西，需要学院的寒暑假留校申请书。','dà tǐ cái liào dōu yī yàng ， jiù duō yī fèn dōng xī ， xū yào xué yuàn de hán shǔ jià liú xiào shēn qǐng shū 。','Về cơ bản hồ sơ giống nhau, chỉ thêm một thứ thôi, cần đơn xin ở lại trường dịp nghỉ hè nghỉ đông do khoa cấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_03','V512','阮明',3,'申请书我手写一份可以吗？','shēn qǐng shū wǒ shǒu xiě yī fèn kě yǐ ma ？','Đơn đó em viết tay được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_04','V512','辅警',4,'不行，得打印填写完整，再去国际处盖章，手写的没有公章，审核不通过。','bù xíng ， dé dǎ yìn tián xiě wán zhěng ， zài qù guó jì chù gài zhāng ， shǒu xiě de méi yǒu gōng zhāng ， shěn hé bù tōng guò 。','Không được, phải in ra điền đầy đủ rồi đem lên phòng quốc tế đóng dấu, viết tay không có con dấu thì không qua được xét duyệt đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_05','V512','阮明',5,'哦，那有效期还是正常一年吗？不会只给到开学吧？','ó ， nà yǒu xiào qī hái shì zhèng cháng yī nián ma ？ bú huì zhǐ gěi dào kāi xué ba ？','À vậy hạn hiệu lực vẫn là một năm bình thường chứ ạ? Không phải chỉ đến ngày khai giảng thôi đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_06','V512','辅警',6,'放心，统一按学制批一年，不受寒暑假留校的影响。','fàng xīn ， tǒng yī àn xué zhì pī yī nián ， bù shòu hán shǔ jià liú xiào de yǐng xiǎng 。','Yên tâm đi, đều cấp một năm theo học chế, không bị ảnh hưởng gì bởi việc ở lại trường dịp nghỉ hè nghỉ đông cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L512_07','V512','阮明',7,'行，我清楚了，回去马上打印盖章。','xíng ， wǒ qīng chǔ le ， huí qù mǎ shàng dǎ yìn gài zhāng 。','Dạ, em rõ rồi, về là in với đóng dấu ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT513','SV2','校外租房居住，房东不配合办理住宿登记单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V513','SIT513','P1','twist','ban_chinh_thuc',NULL,'出租房屋房东有法定义务配合外籍租客完成社区住宿备案，拒不配合社区可依法约谈整改。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_01','V513','阮明',1,'网格员您好，我想咨询一下校外住宿备案的事，我的房东一直不肯配合我办理。','wǎng gé yuán nín hǎo ， wǒ xiǎng zī xún yī xià xiào wài zhù sù bèi àn de shì ， wǒ de fáng dōng yì zhí bù kěn pèi hé wǒ bàn lǐ 。','Chào anh cán bộ khu phố, tôi muốn hỏi về việc đăng ký lưu trú ngoài trường, chủ nhà tôi cứ không chịu phối hợp làm giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_02','V513','网格员',2,'他是为什么不愿意配合？是有什么顾虑吗？','tā shì wèi shén me bù yuàn yì pèi hé ？ shì yǒu shén me gù lǜ ma ？','Vì sao chủ nhà không chịu phối hợp? Có vướng mắc gì à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_03','V513','阮明',3,'房东说备案要上交房产证复印件，担心个人信息泄露，死活不同意。','fáng dōng shuō bèi àn yào shàng jiāo fáng chǎn zhèng fù yìn jiàn ， dān xīn gè rén xìn xī xiè lòu ， sǐ huó bù tóng yì 。','Chủ nhà bảo đăng ký phải nộp bản sao giấy chứng nhận quyền sở hữu nhà, sợ lộ thông tin cá nhân nên nhất quyết không đồng ý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_04','V513','网格员',4,'我懂了。你跟他说一下，外籍租客住宿备案是国家法定要求，房东有义务配合，不是可办可不办的。','wǒ dǒng le 。 nǐ gēn tā shuō yī xià ， wài jí zū kè zhù sù bèi àn shì guó jiā fǎ dìng yāo qiú ， fáng dōng yǒu yì wù pèi hé ， bú shì kě bàn kě bù bàn de 。','Tôi hiểu rồi. Anh nói với chủ nhà giúp tôi là đăng ký lưu trú cho người thuê nước ngoài là quy định pháp luật của nhà nước, chủ nhà có nghĩa vụ phối hợp, không phải muốn làm thì làm không muốn thì thôi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_05','V513','阮明',5,'我跟他说了好几次，他还是不愿意到场，那我还有别的办法可以办登记吗？','wǒ gēn tā shuō le hǎo jǐ cì ， tā hái shì bù yuàn yì dào chǎng ， nà wǒ hái yǒu bié de bàn fǎ kě yǐ bàn dēng jì ma ？','Tôi nói với anh ấy mấy lần rồi, anh ấy vẫn không chịu có mặt, vậy còn cách nào khác để đăng ký được không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_06','V513','网格员',6,'你不用自己沟通了，我上门去跟房东劝导沟通。要是还不配合，我们会下发书面整改告知单。','nǐ bù yòng zì jǐ gōu tōng le ， wǒ shàng mén qù gēn fáng dōng quàn dǎo gōu tōng 。 yào shì hái bù pèi hé ， wǒ men huì xià fā shū miàn zhěng gǎi gào zhī dān 。','Anh không cần tự trao đổi nữa, tôi sẽ đến tận nơi khuyên nhủ chủ nhà. Nếu vẫn không phối hợp, chúng tôi sẽ ban hành thông báo yêu cầu chỉnh sửa bằng văn bản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_07','V513','阮明',7,'那太好了！我现在就在出租屋这边等着，您今天方便过来吗？','nà tài hǎo le ！ wǒ xiàn zài jiù zài chū zū wū zhè biān děng zhe ， nín jīn tiān fāng biàn guò lái ma ？','Vậy thì tốt quá! Giờ tôi đang ở nhà thuê đây, hôm nay anh tiện đến được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_08','V513','网格员',8,'可以，我半小时内到现场，带备案表格过来，顺便核验房屋信息、拍照留存。','kě yǐ ， wǒ bàn xiǎo shí nèi dào xiàn chǎng ， dài bèi àn biǎo gé guò lái ， shùn biàn hé yàn fáng wū xìn xī 、 pāi zhào liú cún 。','Được, tôi sẽ đến nơi trong nửa tiếng nữa, mang theo mẫu đăng ký, tiện thể kiểm tra thông tin nhà và chụp ảnh lưu lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L513_09','V513','阮明',9,'真的麻烦您了，没有这个登记单，我根本没办法续办居留签证。','zhēn de má fán nín le ， méi yǒu zhè ge dēng jì dān ， wǒ gēn běn méi bàn fǎ xù bàn jū liú qiān zhèng 。','Thật sự phiền anh quá, không có tờ đăng ký này thì tôi hoàn toàn không thể gia hạn được visa cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT514','SV2','续居留预约号约满，咨询线下现场取号方案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V514','SIT514','P1','twist','tuy_y',NULL,'出入境线上预约号资源紧张，线下应急号数量有限，仅针对签证续签人群，新办居留不开放线下现场号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_01','V514','阮明',1,'你好，我想办居留续签，但是线上近七天的预约号全部约满了，根本抢不到。','nǐ hǎo ， wǒ xiǎng bàn jū liú xù qiān ， dàn shì xiàn shàng jìn qī tiān de yù yuē hào quán bù yuē mǎn le ， gēn běn qiǎng bú dào 。','Chào chị, em muốn gia hạn thẻ tạm trú, nhưng số hẹn online trong gần bảy ngày tới đã kín hết rồi, không tài nào giành được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_02','V514','引导员',2,'正常的，线上号源特别紧张。不过我们大厅每天会留少量的线下应急号。','zhèng cháng de ， xiàn shàng hào yuán tè bié jǐn zhāng 。 bù guò wǒ men dà tīng měi tiān huì liú shǎo liàng de xiàn xià yìng jí hào 。','Bình thường thôi, số online lúc nào cũng căng lắm. Nhưng sảnh mình mỗi ngày vẫn để lại một ít số khẩn cấp làm trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_03','V514','阮明',3,'线下号是直接来就能取吗？几点开始发放呀？','xiàn xià hào shì zhí jiē lái jiù néng qǔ ma ？ jǐ diǎn kāi shǐ fā fàng ya ？','Số làm trực tiếp là đến là lấy được luôn hả? Mấy giờ bắt đầu phát vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_04','V514','引导员',4,'早上八点开门准时放号，数量有限，发完就没了，不会额外追加。','zǎo shàng bā diǎn kāi mén zhǔn shí fàng hào ， shù liàng yǒu xiàn ， fā wán jiù méi le ， bú huì é wài zhuī jiā 。','Tám giờ sáng mở cửa là phát số đúng giờ luôn, số lượng có hạn, hết là hết, không bổ sung thêm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_05','V514','阮明',5,'那我问清楚，这个现场号只能办续签对吧？首次办居留不能用？','nà wǒ wèn qīng chǔ ， zhè ge xiàn chǎng hào zhǐ néng bàn xù qiān duì ba ？ shǒu cì bàn jū liú bù néng yòng ？','Vậy em hỏi rõ luôn nha, số trực tiếp này chỉ dùng để gia hạn thôi đúng không? Làm thẻ tạm trú lần đầu không dùng được à?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_06','V514','引导员',6,'没错，只针对续签业务，首次办理必须线上预约，没有现场通道。','méi cuò ， zhǐ zhēn duì xù qiān yè wù ， shǒu cì bàn lǐ bì xū xiàn shàng yù yuē ， méi yǒu xiàn chǎng tōng dào 。','Đúng rồi, chỉ áp dụng cho gia hạn thôi, làm lần đầu bắt buộc phải hẹn online, không có cửa làm trực tiếp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L514_07','V514','阮明',7,'明白了，那我明天早点来，七点半过来排队应该能抢到吧。','míng bái le ， nà wǒ míng tiān zǎo diǎn lái ， qī diǎn bàn guò lái pái duì yīng gāi néng qiǎng dào ba 。','Em hiểu rồi, vậy mai em đến sớm hơn, khoảng bảy rưỡi ra xếp hàng chắc giành được số.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT515','SV2','签证办理期间护照上交，申请临时出行证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V515','SIT515','P1','suon_se','chinh_thuc',NULL,'护照上交出入境办理签证期间，无法乘坐交通、入住酒店，必须申请临时出行证明作为替代身份证件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_01','V515','阮明',1,'您好，我的护照已经上交办理居留续签了，但是我周末要出门短途出行，想问问有没有替代证件能用？','nín hǎo ， wǒ de hù zhào yǐ jīng shàng jiāo bàn lǐ jū liú xù qiān le ， dàn shì wǒ zhōu mò yào chū mén duǎn tú chū xíng ， xiǎng wèn wèn yǒu méi yǒu tì dài zhèng jiàn néng yòng ？','Chào anh/chị, hộ chiếu của em đã nộp để làm thủ tục gia hạn tạm trú rồi, nhưng cuối tuần em có việc phải đi ra ngoài ngắn ngày, không biết có giấy tờ thay thế nào dùng được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_02','V515','工作人员',2,'有的，这种情况可以办理《外国人临时出行证明》。','yǒu de ， zhè zhǒng qíng kuàng kě yǐ bàn lǐ 《 wài guó rén lín shí chū xíng zhèng míng 》。','Có ạ, trường hợp này có thể làm "Giấy chứng nhận đi lại tạm thời cho người nước ngoài".',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_03','V515','阮明',3,'那这个证明有效期是多久啊？','nà zhè ge zhèng míng yǒu xiào qī shì duō jiǔ a ？','Vậy giấy chứng nhận này có hiệu lực bao lâu ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_04','V515','工作人员',4,'有效期统一七天，足够你短期出行使用了。','yǒu xiào qī tǒng yī qī tiān ， zú gòu nǐ duǎn qī chū xíng shǐ yòng le 。','Thời hạn thống nhất là bảy ngày, đủ để bạn đi lại ngắn ngày rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_05','V515','阮明',5,'办理的话需要准备什么材料？我提前备好。','bàn lǐ de huà xū yào zhǔn bèi shén me cái liào ？ wǒ tí qián bèi hǎo 。','Vậy làm giấy này cần chuẩn bị giấy tờ gì ạ? Để em chuẩn bị trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_06','V515','工作人员',6,'只需要交一张白底证件照，再填写清楚你的出行目的地就行。','zhǐ xū yào jiāo yī zhāng bái dǐ zhèng jiàn zhào ， zài tián xiě qīng chǔ nǐ de chū xíng mù dì dì jiù xíng 。','Chỉ cần nộp một ảnh thẻ nền trắng, rồi ghi rõ điểm đến của bạn là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_07','V515','阮明',7,'了解了。那我再确认一下，高铁乘车、酒店入住这些场景都能用吗？','liǎo jiě le 。 nà wǒ zài què rèn yī xià ， gāo tiě chéng chē 、 jiǔ diàn rù zhù zhè xiē chǎng jǐng dōu néng yòng ma ？','Em hiểu rồi ạ. Cho em xác nhận lại, đi tàu cao tốc, nhận phòng khách sạn có dùng được giấy này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_08','V515','工作人员',8,'可以的，国内交通出行、住宿登记全部通用，效力等同于临时身份证件。','kě yǐ de ， guó nèi jiāo tōng chū xíng 、 zhù sù dēng jì quán bù tōng yòng ， xiào lì děng tóng yú lín shí shēn fèn zhèng jiàn 。','Được chứ, đi lại trong nước, đăng ký lưu trú đều dùng chung được hết, giá trị tương đương giấy tờ tùy thân tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_09','V515','阮明',9,'那等我后续办好居留贴纸、拿回护照的时候，需要把这个临时证明交回来吗？','nà děng wǒ hòu xù bàn hǎo jū liú tiē zhǐ 、 ná huí hù zhào de shí hòu ， xū yào bǎ zhè ge lín shí zhèng míng jiāo huí lái ma ？','Vậy sau này khi em làm xong tem tạm trú, lấy lại hộ chiếu rồi, có cần nộp lại giấy chứng nhận tạm thời này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_10','V515','工作人员',10,'对，领取正式护照的当天，我们会回收这份纸质临时证明。','duì ， lǐng qǔ zhèng shì hù zhào dí dàng tiān ， wǒ men huì huí shōu zhè fèn zhǐ zhì lín shí zhèng míng 。','Đúng vậy, ngày nhận lại hộ chiếu chính thức, bên mình sẽ thu lại tờ giấy chứng nhận tạm thời này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L515_11','V515','阮明',11,'好的，那麻烦您帮我一并办理，这样周末就能正常出行了。','hǎo de ， nà má fán nín bāng wǒ yī bìng bàn lǐ ， zhè yàng zhōu mò jiù néng zhèng cháng chū xíng le 。','Vâng ạ, vậy phiền anh/chị giúp em làm luôn một thể, để cuối tuần em đi lại bình thường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT516','SV2','中途休学，咨询居留签证暂停与恢复手续',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V516','SIT516','P1','twist','chinh_thuc',NULL,'留学生休学、退学导致学籍失效，学生居留许可自动失效，需在规定缓冲期内离境，滞留会产生行政处罚。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_01','V516','阮明',1,'老师您好，因为身体原因，我打算申请休学半年，想问问我的居留签证要怎么处理？','lǎo shī nín hǎo ， yīn wèi shēn tǐ yuán yīn ， wǒ dǎ suàn shēn qǐng xiū xué bàn nián ， xiǎng wèn wèn wǒ de jū liú qiān zhèng yào zěn me chǔ lǐ ？','Thưa thầy/cô, vì lý do sức khỏe, em định xin bảo lưu nửa năm, cho em hỏi thẻ tạm trú của em phải xử lý thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_02','V516','老师',2,'是这样的，一旦办理休学，你的在校学籍会直接暂停。','shì zhè yàng de ， yí dàn bàn lǐ xiū xué ， nǐ de zài xiào xué jí huì zhí jiē zàn tíng 。','Là thế này, một khi làm thủ tục bảo lưu, tư cách học sinh tại trường của em sẽ bị tạm dừng ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_03','V516','阮明',3,'那学籍暂停的话，签证还能继续用吗？','nà xué jí zàn tíng de huà ， qiān zhèng hái néng jì xù yòng ma ？','Vậy tư cách học sinh bị tạm dừng thì visa còn dùng được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_04','V516','老师',4,'不能的，学生学籍失效，对应的居留许可也会同步失效，你需要在规定时间内离境。','bù néng de ， xué shēng xué jí shī xiào ， duì yìng de jū liú xǔ kě yě huì tóng bù shī xiào ， nǐ xū yào zài guī dìng shí jiān nèi lí jìng 。','Không được, tư cách học sinh mất hiệu lực thì giấy phép tạm trú tương ứng cũng mất hiệu lực theo, em cần xuất cảnh trong thời gian quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_05','V516','阮明',5,'啊？没办法通融吗？我是身体原因休学，想留在国内休养，不用回国。','a ？ méi bàn fǎ tōng róng ma ？ wǒ shì shēn tǐ yuán yīn xiū xué ， xiǎng liú zài guó nèi xiū yǎng ， bù yòng huí guó 。','Hả? Không có cách nào linh động được ạ? Em bảo lưu vì lý do sức khỏe, muốn ở lại đây dưỡng bệnh, không cần về nước ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_06','V516','老师',6,'我理解你的情况，但政策是统一的。没有有效在校学籍，就不符合学生居留的审批标准，没办法保留签证。','wǒ lǐ jiě nǐ de qíng kuàng ， dàn zhèng cè shì tǒng yī de 。 méi yǒu yǒu xiào zài xiào xué jí ， jiù bù fú hé xué shēng jū liú de shěn pī biāo zhǔn ， méi bàn fǎ bǎo liú qiān zhèng 。','Thầy/cô hiểu hoàn cảnh của em, nhưng chính sách là thống nhất. Không có tư cách học sinh hợp lệ tại trường thì không đủ điều kiện xét duyệt tạm trú diện học sinh, không thể giữ lại visa được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_07','V516','阮明',7,'我明白了。那半年后我复学回来，居留要怎么办理？','wǒ míng bái le 。 nà bàn nián hòu wǒ fù xué huí lái ， jū liú yào zěn me bàn lǐ ？','Em hiểu rồi ạ. Vậy nửa năm sau em quay lại học tiếp thì thủ tục tạm trú phải làm thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_08','V516','老师',8,'复学之后拿着学校的复学通知书，按照新生的流程，重新全套申请居留许可。','fù xué zhī hòu ná zhe xué xiào de fù xué tōng zhī shū ， àn zhào xīn shēng de liú chéng ， chóng xīn quán tào shēn qǐng jū liú xǔ kě 。','Sau khi quay lại học, em cầm giấy thông báo phục học của trường, làm theo quy trình như sinh viên mới, xin lại toàn bộ giấy phép tạm trú từ đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_09','V516','阮明',9,'那我办完休学手续，是不是马上就要离境？有没有缓冲时间？','nà wǒ bàn wán xiū xué shǒu xù ， shì bú shì mǎ shàng jiù yào lí jìng ？ yǒu méi yǒu huǎn chōng shí jiān ？','Vậy làm xong thủ tục bảo lưu là em phải xuất cảnh ngay luôn ạ? Có thời gian đệm nào không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_10','V516','老师',10,'有的，从休学备案当天开始算，有三十天的合法停留期，你可以利用这段时间收拾行李、安排行程。','yǒu de ， cóng xiū xué bèi àn dàng tiān kāi shǐ suàn ， yǒu sān shí tiān de hé fǎ tíng liú qī ， nǐ kě yǐ lì yòng zhè duàn shí jiān shōu shí xíng lǐ 、 ān pái xíng chéng 。','Có chứ, tính từ ngày đăng ký bảo lưu, em có ba mươi ngày lưu trú hợp pháp, có thể tận dụng khoảng thời gian này để thu xếp hành lý, sắp xếp lịch trình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L516_11','V516','阮明',11,'清楚了，我会在缓冲期内安排回国休养，不会逾期滞留的。','qīng chǔ le ， wǒ huì zài huǎn chōng qī nèi ān pái huí guó xiū yǎng ， bú huì yú qī zhì liú de 。','Em rõ rồi ạ, em sẽ sắp xếp về nước dưỡng bệnh trong thời gian đệm, không để quá hạn lưu trú đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT517','SV2','短期出境旅游，咨询居留证是否需要备案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V517','SIT517','P1','suon_se','tuy_y',NULL,'持有有效长期学生居留许可，短期出境旅游无需向出入境报备，仅毕业、休学、永久离境才需要注销备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_01','V517','阮明',1,'警官，问个事哈，我下周想出国旅游，手里的居留证还在有效期，需要提前报备吗？','jǐng guān ， wèn gè shì hā ， wǒ xià zhōu xiǎng chū guó lǚ yóu ， shǒu lǐ de jū liú zhèng hái zài yǒu xiào qī ， xū yào tí qián bào bèi ma ？','Anh cảnh sát ơi, hỏi tí nha, tuần sau em định đi du lịch nước ngoài, thẻ tạm trú trong tay em vẫn còn hạn, có cần báo trước không ạ?','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_02','V517','辅警',2,'不用不用，短期旅游不用线下备案。','bù yòng bù yòng ， duǎn qī lǚ yóu bù yòng xiàn xià bèi àn 。','Không cần đâu, không cần đâu, đi du lịch ngắn ngày thì không cần đăng ký trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_03','V517','阮明',3,'那我出入境的时候，直接带护照和居留贴纸就行吗？','nà wǒ chū rù jìng de shí hòu ， zhí jiē dài hù zhào hé jū liú tiē zhǐ jiù xíng ma ？','Vậy lúc xuất nhập cảnh, em cứ mang hộ chiếu với tem tạm trú theo là được hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_04','V517','辅警',4,'对，两个证件一起给海关查验就行，很方便的。','duì ， liǎng gè zhèng jiàn yì qǐ gěi hǎi guān chá yàn jiù xíng ， hěn fāng biàn de 。','Đúng rồi, đưa hai giấy đó cho hải quan kiểm tra là xong, tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_05','V517','阮明',5,'那要是我出去玩得久一点，超过一个月，回来签证会不会出问题？','nà yào shì wǒ chū qù wán dé jiǔ yì diǎn ， chāo guò yí gè yuè ， huí lái qiān zhèng huì bú huì chū wèn tí ？','Vậy nếu em đi chơi lâu hơn một chút, quá một tháng, lúc về visa có bị làm sao không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_06','V517','辅警',6,'没事的，只要你的居留许可没到期，不管出境多久，回来都能正常入境。','méi shì de ， zhǐ yào nǐ de jū liú xǔ kě méi dào qī ， bù guǎn chū jìng duō jiǔ ， huí lái dōu néng zhèng cháng rù jìng 。','Không sao đâu, miễn là giấy phép tạm trú của em chưa hết hạn, đi bao lâu cũng được, về là nhập cảnh bình thường thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L517_07','V517','阮明',7,'那就好，我还特意担心要跑一趟大厅报备呢。','nà jiù hǎo ， wǒ hái tè yì dān xīn yào pǎo yī tàng dà tīng bào bèi ne 。','Vậy thì tốt quá, em còn cứ lo phải chạy ra sảnh đăng ký cơ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT518','SV3','护照丢失，派出所开遗失证明用于补办签证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V518','SIT518','P1','suon_se','chinh_thuc',NULL,'外籍护照遗失必须先到派出所报案获取回执，无回执无法办理临时通行证明、新护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_01','V518','阮明',1,'警官您好，我的越南护照不小心弄丢了，想来办理遗失报案，开一份回执证明。','jǐng guān nín hǎo ， wǒ de yuè nán hù zhào bù xiǎo xīn nòng diū le ， xiǎng lái bàn lǐ yí shī bào àn ， kāi yī fèn huí zhí zhèng míng 。','Chào anh công an, hộ chiếu Việt Nam của em lỡ bị mất rồi, em muốn khai báo mất giấy tờ, xin một bản biên nhận ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_02','V518','民警',2,'好的，你仔细说一下具体情况，什么时候丢的、在哪里丢的，当时随身带了哪些东西。','hǎo de ， nǐ zǐ xì shuō yī xià jù tǐ qíng kuàng ， shén me shí hòu diū de 、 zài nǎ lǐ diū de ， dāng shí suí shēn dài le nǎ xiē dōng xī 。','Được, em kể chi tiết xem, mất lúc nào, mất ở đâu, lúc đó mang theo những gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_03','V518','阮明',3,'就在昨天下午，我在市区商圈逛街，结账之后发现口袋里的钱包和护照一起不见了。','jiù zài zuó tiān xià wǔ ， wǒ zài shì qū shāng quān guàng jiē ， jié zhàng zhī hòu fā xiàn kǒu dài lǐ de qián bāo hé hù zhào yì qǐ bú jiàn le 。','Là chiều hôm qua ạ, em đi dạo phố mua sắm ở khu trung tâm, thanh toán xong thì phát hiện ví với hộ chiếu trong túi mất luôn cùng lúc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_04','V518','民警',4,'清楚了，我现在给你录入遗失笔录，信息核对无误签字后，我给你打印两份报案回执。','qīng chǔ le ， wǒ xiàn zài gěi nǐ lù rù yí shī bǐ lù ， xìn xī hé duì wú wù qiān zì hòu ， wǒ gěi nǐ dǎ yìn liǎng fèn bào àn huí zhí 。','Rõ rồi, giờ anh nhập biên bản khai báo mất cho em, sau khi đối chiếu thông tin chính xác và em ký tên xong, anh sẽ in cho em hai bản biên nhận khai báo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_05','V518','阮明',5,'好的。这两份回执是不是一份用来办临时通行，另一份去大使馆补办新护照？','hǎo de 。 zhè liǎng fèn huí zhí shì bú shì yī fèn yòng lái bàn lín shí tōng xíng ， lìng yī fèn qù dà shǐ guǎn bǔ bàn xīn hù zhào ？','Vâng ạ. Cho em hỏi, hai bản biên nhận này có phải một bản dùng để làm giấy thông hành tạm thời, bản còn lại đem đến đại sứ quán làm lại hộ chiếu mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_06','V518','民警',6,'没错，两份用途不一样，你一定要分开保管，千万别再弄丢了。','méi cuò ， liǎng fèn yòng tú bù yí yàng ， nǐ yí dìng yào fēn kāi bǎo guǎn ， qiān wàn bié zài nòng diū le 。','Đúng rồi, hai bản dùng cho hai việc khác nhau, em nhất định phải cất riêng ra, đừng để mất nữa đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_07','V518','阮明',7,'我了解了。也就是说，没有这份派出所的回执，所有证件补办手续都办不了是吗？','wǒ liǎo jiě le 。 yě jiù shì shuō ， méi yǒu zhè fèn pài chū suǒ de huí zhí ， suǒ yǒu zhèng jiàn bǔ bàn shǒu xù dōu bàn bù liǎo shì ma ？','Em hiểu rồi ạ. Tức là nếu không có bản biên nhận của công an thì mọi thủ tục làm lại giấy tờ đều không làm được phải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_08','V518','民警',8,'是的，大使馆和出入境大厅都强制要求提供这份遗失证明，缺一不可。','shì de ， dà shǐ guǎn hé chū rù jìng dà tīng dōu qiáng zhì yāo qiú tí gōng zhè fèn yí shī zhèng míng ， quē yī bù kě 。','Đúng vậy, đại sứ quán và phòng xuất nhập cảnh đều bắt buộc phải có giấy chứng nhận mất này, thiếu là không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L518_09','V518','阮明',9,'辛苦您帮忙登记备案，给您添麻烦了。','xīn kǔ nín bāng máng dēng jì bèi àn ， gěi nín tiān má fán le 。','Cảm ơn anh đã giúp em đăng ký khai báo, làm phiền anh nhiều rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT519','SV3','居留许可贴纸损毁模糊，申请换发居留贴纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V519','SIT519','P1','twist','ban_chinh_thuc',NULL,'居留贴纸磨损、撕毁、信息模糊属于证件损毁，必须换发，旧照片超出半年有效期不能用于新证件办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_01','V519','阮明',1,'您好，我想咨询一下，我护照上的居留贴纸磨掉色了，上面的信息都看不清楚，该怎么处理？','nín hǎo ， wǒ xiǎng zī xún yī xià ， wǒ hù zhào shàng de jū liú tiē zhǐ mó diào sè le ， shàng miàn de xìn xī dōu kàn bù qīng chǔ ， gāi zěn me chǔ lǐ ？','Chào anh/chị, em muốn hỏi, tem tạm trú trên hộ chiếu của em bị mòn phai màu, thông tin nhìn không rõ nữa, phải xử lý thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_02','V519','工作人员',2,'这种属于证件损毁，需要申请换发新的居留许可，先准备一张白底证件照。','zhè zhǒng shǔ yú zhèng jiàn sǔn huǐ ， xū yào shēn qǐng huàn fā xīn de jū liú xǔ kě ， xiān zhǔn bèi yī zhāng bái dǐ zhèng jiàn zhào 。','Trường hợp này thuộc diện giấy tờ bị hư hỏng, cần làm thủ tục cấp lại giấy phép tạm trú mới, trước tiên bạn chuẩn bị một ảnh thẻ nền trắng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_03','V519','阮明',3,'啊，我上次办签证剩下的旧照片还在，用那个可以吗？','a ， wǒ shàng cì bàn qiān zhèng shèng xià de jiù zhào piān hái zài ， yòng nà ge kě yǐ ma ？','À, lần trước làm visa em còn dư ảnh cũ, dùng cái đó được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_04','V519','工作人员',4,'不可以的，换发新证件有规定，必须是近六个月新拍的照片，旧照片一律不受理。','bù kě yǐ de ， huàn fā xīn zhèng jiàn yǒu guī dìng ， bì xū shì jìn liù gè yuè xīn pāi de zhào piān ， jiù zhào piān yī lǜ bù shòu lǐ 。','Không được đâu, cấp lại giấy tờ mới có quy định, phải là ảnh chụp mới trong vòng sáu tháng gần đây, ảnh cũ đều không nhận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_05','V519','阮明',5,'这样啊……那大厅楼下的自助拍照机，能拍符合签证标准的照片吗？','zhè yàng a …… nà dà tīng lóu xià de zì zhù pāi zhào jī ， néng pāi fú hé qiān zhèng biāo zhǔn de zhào piān ma ？','Vậy à... thế máy chụp ảnh tự động ở dưới sảnh có chụp được ảnh đạt chuẩn visa không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_06','V519','工作人员',6,'可以的，机子拍的都是合规证件照，你拍完直接拿纸质照片回来取号办理就行。','kě yǐ de ， jī zi pāi de dōu shì hé guī zhèng jiàn zhào ， nǐ pāi wán zhí jiē ná zhǐ zhì zhào piān huí lái qǔ hào bàn lǐ jiù xíng 。','Được chứ, máy chụp ra đều là ảnh thẻ đạt chuẩn, bạn chụp xong cầm ảnh giấy quay lại lấy số làm thủ tục luôn là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_07','V519','阮明',7,'好，那我再问一下，办理换发的这段时间，护照要上交吗？','hǎo ， nà wǒ zài wèn yī xià ， bàn lǐ huàn fā de zhè duàn shí jiān ， hù zhào yào shàng jiāo ma ？','Dạ, cho em hỏi thêm, trong thời gian làm thủ tục cấp lại này, có phải nộp hộ chiếu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_08','V519','工作人员',8,'需要留存七个工作日。这期间如果你有出行需求，记得顺便办一张临时出行证明。','xū yào liú cún qī gè gōng zuò rì 。 zhè qī jiān rú guǒ nǐ yǒu chū xíng xū qiú ， jì de shùn biàn bàn yī zhāng lín shí chū xíng zhèng míng 。','Cần giữ lại bảy ngày làm việc. Trong thời gian này nếu bạn có nhu cầu đi lại, nhớ tiện thể làm luôn một giấy chứng nhận đi lại tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L519_09','V519','阮明',9,'明白了，我现在就去拍照，拍完马上回来递交材料办理换发。','míng bái le ， wǒ xiàn zài jiù qù pāi zhào ， pāi wán mǎ shàng huí lái dì jiāo cái liào bàn lǐ huàn fā 。','Em hiểu rồi ạ, giờ em đi chụp ảnh luôn, chụp xong quay lại nộp hồ sơ làm thủ tục cấp lại ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT520','SV3','护照补办完成后，重新补办在华居留许可',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V520','SIT520','P1','suon_se','chinh_thuc',NULL,'补办护照后不能直接沿用旧居留，必须同步补办居留贴纸，新旧护照搭配使用仅短期有效，长期必须换发居留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_01','V520','阮明',1,'您好，我已经从大使馆拿到新护照了，现在来补办之前丢失的居留许可。','nín hǎo ， wǒ yǐ jīng cóng dà shǐ guǎn ná dào xīn hù zhào le ， xiàn zài lái bǔ bàn zhī qián diū shī de jū liú xǔ kě 。','Chào anh/chị, em đã lấy được hộ chiếu mới từ đại sứ quán rồi, giờ em đến làm lại giấy phép tạm trú bị mất trước đó ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_02','V520','工作人员',2,'可以的，请递交你的新护照、派出所遗失回执、学校在读证明和住宿登记单。','kě yǐ de ， qǐng dì jiāo nǐ de xīn hù zhào 、 pài chū suǒ yí shī huí zhí 、 xué xiào zài dú zhèng míng hé zhù sù dēng jì dān 。','Được, mời bạn nộp hộ chiếu mới, biên nhận khai báo mất của công an, giấy xác nhận đang học của trường và phiếu đăng ký lưu trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_03','V520','阮明',3,'好的。对了，我旧护照过期签证页的复印件，需要一起上交核对吗？','hǎo de 。 duì le ， wǒ jiù hù zhào guò qī qiān zhèng yè de fù yìn jiàn ， xū yào yì qǐ shàng jiāo hé duì ma ？','Vâng ạ. À, bản photo trang visa đã hết hạn trong hộ chiếu cũ có cần nộp kèm để đối chiếu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_04','V520','工作人员',4,'需要的，复印件我们会留存归档，用来核对你原本的居留有效期限。','xū yào de ， fù yìn jiàn wǒ men huì liú cún guī dàng ， yòng lái hé duì nǐ yuán běn de jū liú yǒu xiào qī xiàn 。','Cần, bản photo bên mình sẽ lưu lại hồ sơ, dùng để đối chiếu thời hạn tạm trú ban đầu của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_05','V520','阮明',5,'了解。那补办的办理时间，和第一次办一样是七个工作日吗？','liǎo jiě 。 nà bǔ bàn de bàn lǐ shí jiān ， hé dì yī cì bàn yī yàng shì qī gè gōng zuò rì ma ？','Em hiểu rồi ạ. Vậy thời gian làm thủ tục cấp lại có giống lần đầu là bảy ngày làm việc không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_06','V520','工作人员',6,'常规流程是七个工作日，如果你着急，也可以走加急通道，三个工作日就能取证。','cháng guī liú chéng shì qī gè gōng zuò rì ， rú guǒ nǐ zháo jí ， yě kě yǐ zǒu jiā jí tōng dào ， sān gè gōng zuò rì jiù néng qǔ zhèng 。','Quy trình thông thường là bảy ngày làm việc, nếu bạn gấp thì cũng có thể làm nhanh, ba ngày làm việc là lấy được giấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_07','V520','阮明',7,'不用加急，我正常等就行。那补办后的居留有效期，是和我原来剩下的时长一样的吧？','bù yòng jiā jí ， wǒ zhèng cháng děng jiù xíng 。 nà bǔ bàn hòu de jū liú yǒu xiào qī ， shì hé wǒ yuán lái shèng xià de shí cháng yī yàng de ba ？','Không cần gấp đâu ạ, em chờ bình thường cũng được. Vậy giấy phép tạm trú làm lại có thời hạn giống với thời hạn còn lại ban đầu của em đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_08','V520','工作人员',8,'对的，完全同步原来的到期时间，不会重新计算一年有效期。','duì de ， wán quán tóng bù yuán lái de dào qī shí jiān ， bú huì chóng xīn jì suàn yī nián yǒu xiào qī 。','Đúng vậy, hoàn toàn giữ nguyên thời hạn hết hạn ban đầu, không tính lại một năm mới đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L520_09','V520','阮明',9,'没问题，我材料都齐了，麻烦您帮我受理一下。','méi wèn tí ， wǒ cái liào dōu qí le ， má fán nín bāng wǒ shòu lǐ yī xià 。','Không vấn đề gì ạ, hồ sơ em đã đủ cả rồi, phiền anh/chị giúp em tiếp nhận xử lý ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT521','SV3','出境紧急情况无证件，申请出入境临时通行纸',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V521','SIT521','P1','twist','chinh_thuc',NULL,'临时出入境通行证明仅限单次出境，不可用于再次入境中国，回国后需在本国驻华使馆补办正式护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_01','V521','阮明',1,'警官，麻烦您帮帮忙！我明天一早的航班要回国，但是护照丢了，急需办一个临时通行证件。','jǐng guān ， má fán nín bāng bāng máng ！ wǒ míng tiān yī zǎo de háng bān yào huí guó ， dàn shì hù zhào diū le ， jí xū bàn yí gè lín shí tōng xíng zhèng jiàn 。','Anh công an ơi, làm ơn giúp em với! Sáng sớm mai em có chuyến bay về nước, nhưng hộ chiếu bị mất rồi, em cần gấp một giấy thông hành tạm thời ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_02','V521','民警',2,'别着急，先把派出所的遗失回执给我，我核对一下你的备案信息。','bié zháo jí ， xiān bǎ pài chū suǒ de yí shī huí zhí gěi wǒ ， wǒ hé duì yī xià nǐ de bèi àn xìn xī 。','Đừng lo, trước tiên đưa anh biên nhận khai báo mất của công an, anh kiểm tra thông tin đăng ký của em đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_03','V521','阮明',3,'回执我带在身上了！但是我刚刚去拍照，自助机已经关门了，没有纸质照片怎么办？','huí zhí wǒ dài zài shēn shàng le ！ dàn shì wǒ gāng gāng qù pāi zhào ， zì zhù jī yǐ jīng guān mén le ， méi yǒu zhǐ zhì zhào piān zěn me bàn ？','Biên nhận em mang theo người rồi ạ! Nhưng em vừa mới đi chụp ảnh thì máy tự động đã đóng cửa, không có ảnh giấy thì phải làm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_04','V521','民警',4,'没关系，你是紧急出境情况，可以免交纸质照片，我们系统里有你之前留存的证件照，可以直接调取使用。','méi guān xì ， nǐ shì jǐn jí chū jìng qíng kuàng ， kě yǐ miǎn jiāo zhǐ zhì zhào piān ， wǒ men xì tǒng lǐ yǒu nǐ zhī qián liú cún de zhèng jiàn zhào ， kě yǐ zhí jiē diào qǔ shǐ yòng 。','Không sao, trường hợp em xuất cảnh khẩn cấp thì được miễn nộp ảnh giấy, hệ thống bên anh có lưu ảnh thẻ trước đây của em, có thể lấy trực tiếp để dùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_05','V521','阮明',5,'太好了，谢谢您！那我确认一下，这张临时通行纸只能这次出境用，不能再入境中国了对吧？','tài hǎo le ， xiè xiè nín ！ nà wǒ què rèn yī xià ， zhè zhāng lín shí tōng xíng zhǐ zhǐ néng zhè cì chū jìng yòng ， bù néng zài rù jìng zhōng guó le duì ba ？','Tuyệt quá, cảm ơn anh! Cho em xác nhận lại, tờ giấy thông hành tạm thời này chỉ dùng để xuất cảnh lần này thôi, không thể dùng để nhập cảnh lại Trung Quốc nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_06','V521','民警',6,'没错，仅限单次出境有效。你回到越南之后，要尽快去当地大使馆补办新护照。','méi cuò ， jǐn xiàn dān cì chū jìng yǒu xiào 。 nǐ huí dào yuè nán zhī hòu ， yào jǐn kuài qù dāng dì dà shǐ guǎn bǔ bàn xīn hù zhào 。','Đúng vậy, chỉ có giá trị cho một lần xuất cảnh duy nhất. Sau khi về đến Việt Nam, em phải nhanh chóng ra đại sứ quán ở đó làm lại hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_07','V521','阮明',7,'那办理需要等很久吗？我时间特别赶。','nà bàn lǐ xū yào děng hěn jiǔ ma ？ wǒ shí jiān tè bié gǎn 。','Vậy làm thủ tục có phải chờ lâu không ạ? Em đang gấp lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_08','V521','民警',8,'紧急出境业务可以当场办结，大概十分钟就能打印好给你。','jǐn jí chū jìng yè wù kě yǐ dāng chǎng bàn jié ， dà gài shí fēn zhōng jiù néng dǎ yìn hǎo gěi nǐ 。','Trường hợp xuất cảnh khẩn cấp có thể giải quyết ngay tại chỗ, khoảng mười phút là in xong đưa cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L521_09','V521','阮明',9,'太感谢了！要是没有这个紧急通道，我明天肯定赶不上航班了。','tài gǎn xiè le ！ yào shì méi yǒu zhè ge jǐn jí tōng dào ， wǒ míng tiān kěn dìng gǎn bù shàng háng bān le 。','Cảm ơn anh nhiều lắm! Nếu không có kênh khẩn cấp này chắc mai em lỡ chuyến bay mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT522','SV3','居留卡片丢失，线上挂失后线下补办',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V522','SIT522','P1','suon_se','tuy_y',NULL,'外国人居留卡丢失需线上立即挂失，挂失后原卡直接作废，无法恢复使用，只能线下重新制卡。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_01','V522','阮明',1,'你好，我的居留卡不小心弄丢了，想问下挂失和补办要怎么操作？','nǐ hǎo ， wǒ de jū liú kǎ bù xiǎo xīn nòng diū le ， xiǎng wèn xià guà shī hé bǔ bàn yào zěn me cāo zuò ？','Chào bạn, mình lỡ làm mất thẻ cư trú rồi, cho mình hỏi khai báo mất và làm lại thì phải làm thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_02','V522','引导员',2,'先线上操作就行，在出入境官方小程序把卡片挂失锁上，防止别人冒用。','xiān xiàn shàng cāo zuò jiù xíng ， zài chū rù jìng guān fāng xiǎo chéng xù bǎ kǎ piàn guà shī suǒ shàng ， fáng zhǐ bié rén mào yòng 。','Bạn cứ thao tác online trước đã, vào mini app chính thức của xuất nhập cảnh khai báo mất và khóa thẻ lại, để tránh người khác lợi dụng dùng trộm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_03','V522','阮明',3,'好，我现在就操作。挂失完之后，线下补办需要带什么材料呀？','hǎo ， wǒ xiàn zài jiù cāo zuò 。 guà shī wán zhī hòu ， xiàn xià bǔ bàn xū yào dài shén me cái liào ya ？','Được, mình làm luôn đây. Sau khi khai báo mất xong thì làm lại offline cần mang theo giấy tờ gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_04','V522','引导员',4,'准备四样东西：白底证件照、护照、在读证明和住宿登记单。','zhǔn bèi sì yàng dōng xī ： bái dǐ zhèng jiàn zhào 、 hù zhào 、 zài dú zhèng míng hé zhù sù dēng jì dān 。','Chuẩn bị bốn thứ: ảnh thẻ nền trắng, hộ chiếu, giấy xác nhận đang học và phiếu đăng ký lưu trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_05','V522','阮明',5,'对了，万一我挂失之后又找到卡片了，还能解锁继续用吗？','duì le ， wàn yī wǒ guà shī zhī hòu yòu zhǎo dào kǎ piàn le ， hái néng jiě suǒ jì xù yòng ma ？','À đúng rồi, lỡ sau khi khai báo mất mà mình lại tìm thấy thẻ thì còn mở khóa dùng lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_06','V522','引导员',6,'不行的，一旦线上挂失，原卡片就永久失效了，找回来也没用，只能重新补办新卡。','bù xíng de ， yí dàn xiàn shàng guà shī ， yuán kǎ piàn jiù yǒng jiǔ shī xiào le ， zhǎo huí lái yě méi yòng ， zhǐ néng chóng xīn bǔ bàn xīn kǎ 。','Không được đâu, một khi đã khai báo mất online là thẻ cũ mất hiệu lực vĩnh viễn luôn, có tìm lại được cũng vô ích, chỉ có thể làm lại thẻ mới thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L522_07','V522','阮明',7,'行，我懂了。我马上挂失，之后取号递交材料补办。','xíng ， wǒ dǒng le 。 wǒ mǎ shàng guà shī ， zhī hòu qǔ hào dì jiāo cái liào bǔ bàn 。','Được rồi, mình hiểu rồi. Mình khai báo mất ngay, sau đó lấy số và nộp hồ sơ làm lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT523','SV3','旧护照签证页剪角，咨询新旧护照联用规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V523','SIT523','P1','twist','ban_chinh_thuc',NULL,'旧护照到期剪角，居留贴纸短期可新旧护照联用，缓冲期三十天，超时无法正常出入境，必须转移居留许可至新护照。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_01','V523','阮明',1,'警官您好，我的旧护照到期被剪角作废了，但是有效的居留贴纸还贴在旧护照上，这个要怎么处理？','jǐng guān nín hǎo ， wǒ de jiù hù zhào dào qī bèi jiǎn jiǎo zuò fèi le ， dàn shì yǒu xiào de jū liú tiē zhǐ hái tiē zài jiù hù zhào shàng ， zhè ge yào zěn me chǔ lǐ ？','Chào anh công an, hộ chiếu cũ của em hết hạn nên bị cắt góc hủy rồi, nhưng tem cư trú còn hiệu lực lại đang dán trên hộ chiếu cũ, vậy phải xử lý thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_02','V523','辅警',2,'这种情况可以新旧两本护照一起带着，出示给海关查验，短期是可以正常出入境的。','zhè zhǒng qíng kuàng kě yǐ xīn jiù liǎng běn hù zhào yì qǐ dài zhe ， chū shì gěi hǎi guān chá yàn ， duǎn qī shì kě yǐ zhèng cháng chū rù jìng de 。','Trường hợp này thì mang cả hai hộ chiếu cũ và mới theo bên mình, xuất trình cho hải quan kiểm tra, trong thời gian ngắn thì vẫn xuất nhập cảnh bình thường được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_03','V523','阮明',3,'那能一直这样用吗？还是有时间限制？','nà néng yì zhí zhè yàng yòng ma ？ hái shì yǒu shí jiān xiàn zhì ？','Vậy dùng như thế mãi được không ạ, hay là có giới hạn thời gian?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_04','V523','辅警',4,'不能长期联用的，只有三十天的缓冲期，超期之后就无效了，必须把居留信息转移到新护照上。','bù néng cháng qī lián yòng de ， zhǐ yǒu sān shí tiān de huǎn chōng qī ， chāo qī zhī hòu jiù wú xiào le ， bì xū bǎ jū liú xìn xī zhuǎn yí dào xīn hù zhào shàng 。','Không dùng chung lâu dài được đâu, chỉ có thời gian đệm ba mươi ngày thôi, quá hạn là không còn hiệu lực nữa, bắt buộc phải chuyển thông tin cư trú sang hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_05','V523','阮明',5,'啊，只有三十天？那转移居留要怎么办理？是单独预约，还是等续签的时候一起弄？','a ， zhǐ yǒu sān shí tiān ？ nà zhuǎn yí jū liú yào zěn me bàn lǐ ？ shì dān dú yù yuē ， hái shì děng xù qiān de shí hòu yì qǐ nòng ？','Ơ, chỉ có ba mươi ngày thôi ạ? Vậy chuyển cư trú thì làm thủ tục thế nào? Phải đặt lịch hẹn riêng hay đợi lúc gia hạn visa làm luôn một thể ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_06','V523','辅警',6,'需要单独预约居留信息变更业务，不用等到签证到期，尽早办理更稳妥。','xū yào dān dú yù yuē jū liú xìn xī biàn gēng yè wù ， bù yòng děng dào qiān zhèng dào qī ， jǐn zǎo bàn lǐ gèng wěn tuǒ 。','Phải đặt lịch hẹn riêng cho việc thay đổi thông tin cư trú, không cần đợi đến khi visa hết hạn đâu, làm sớm cho chắc ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L523_07','V523','阮明',7,'好的，那我这三天内就预约窗口，把居留贴纸转移到新护照上。','hǎo de ， nà wǒ zhè sān tiān nèi jiù yù yuē chuāng kǒu ， bǎ jū liú tiē zhǐ zhuǎn yí dào xīn hù zhào shàng 。','Vâng ạ, vậy trong ba ngày tới em sẽ đặt lịch ra quầy, chuyển tem cư trú sang hộ chiếu mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT524','SV4','校内转专业，办理居留许可信息变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V524','SIT524','P1','suon_se','ban_chinh_thuc',NULL,'留学生校内转专业、更换学院，必须三十日内到出入境更新居留证件信息，信息不符会被判定证件失效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_01','V524','阮明',1,'您好，我这学期在校内转了专业，想来办理居留证件的信息变更。','nín hǎo ， wǒ zhè xué qī zài xiào nèi zhuǎn le zhuān yè ， xiǎng lái bàn lǐ jū liú zhèng jiàn de xìn xī biàn gēng 。','Chào chị, học kỳ này em chuyển ngành học trong trường, em muốn đến làm thủ tục thay đổi thông tin trên giấy tờ cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_02','V524','工作人员',2,'可以的，请提交你的专业调整证明、个人护照，还有一张白底证件照。','kě yǐ de ， qǐng tí jiāo nǐ de zhuān yè tiáo zhěng zhèng míng 、 gè rén hù zhào ， hái yǒu yī zhāng bái dǐ zhèng jiàn zhào 。','Được chứ, em nộp giấy xác nhận chuyển ngành, hộ chiếu cá nhân, và một tấm ảnh thẻ nền trắng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_03','V524','阮明',3,'好的。我想问一下，只是变更就读专业，签证的到期时间会跟着延后吗？','hǎo de 。 wǒ xiǎng wèn yī xià ， zhǐ shì biàn gēng jiù dú zhuān yè ， qiān zhèng de dào qī shí jiān huì gēn zhe yán hòu ma ？','Vâng ạ. Em muốn hỏi thêm, nếu chỉ thay đổi ngành học thôi thì thời hạn visa có bị dời theo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_04','V524','工作人员',4,'不会的，居留有效期保持不变，只会更新你证件上的就读专业信息。','bú huì de ， jū liú yǒu xiào qī bǎo chí bù biàn ， zhǐ huì gēng xīn nǐ zhèng jiàn shàng de jiù dú zhuān yè xìn xī 。','Không đâu, thời hạn cư trú vẫn giữ nguyên, chỉ cập nhật lại thông tin ngành học trên giấy tờ của em thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_05','V524','阮明',5,'了解了。那这个变更业务要办多久？当天能拿到新证件吗？','liǎo jiě le 。 nà zhè ge biàn gēng yè wù yào bàn duō jiǔ ？ dàng tiān néng ná dào xīn zhèng jiàn ma ？','Em hiểu rồi ạ. Vậy thủ tục thay đổi này mất bao lâu ạ? Trong ngày có lấy được giấy mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_06','V524','工作人员',6,'办理时长是三个工作日，没办法当场取证，需要后续来领取。','bàn lǐ shí cháng shì sān gè gōng zuò rì ， méi bàn fǎ dāng chǎng qǔ zhèng ， xū yào hòu xù lái lǐng qǔ 。','Thời gian xử lý là ba ngày làm việc, không lấy ngay được đâu, phải quay lại lấy sau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_07','V524','阮明',7,'那费用方面呢？信息变更需要交手续费或者工本费吗？','nà fèi yòng fāng miàn ne ？ xìn xī biàn gēng xū yào jiāo shǒu xù fèi huò zhě gōng běn fèi ma ？','Vậy còn về chi phí thì sao ạ? Thay đổi thông tin có phải đóng phí thủ tục hay lệ phí làm giấy tờ không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_08','V524','工作人员',8,'校内转专业的信息变更属于免费业务，没有任何额外费用。','xiào nèi zhuǎn zhuān yè de xìn xī biàn gēng shǔ yú miǎn fèi yè wù ， méi yǒu rèn hé é wài fèi yòng 。','Thay đổi thông tin do chuyển ngành trong trường thì miễn phí, không phát sinh thêm khoản nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L524_09','V524','阮明',9,'太好了，我材料都准备好了，麻烦您帮我受理一下。','tài hǎo le ， wǒ cái liào dōu zhǔn bèi hǎo le ， má fán nín bāng wǒ shòu lǐ yī xià 。','Tuyệt quá, hồ sơ của em chuẩn bị đầy đủ hết rồi, phiền chị tiếp nhận giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT525','SV4','从A校转学至另一城市高校，办理居留迁出迁入',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V525','SIT525','P1','twist','chinh_thuc',NULL,'跨城市转学居留无法异地转移，原城市居留注销失效，抵达新城市三十日内必须重新申请本地学生居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_01','V525','阮明',1,'老师您好，我近期要转学去外地的高校，想咨询一下居留迁出的办理流程。','lǎo shī nín hǎo ， wǒ jìn qī yào zhuǎn xué qù wài dì de gāo xiào ， xiǎng zī xún yī xià jū liú qiān chū de bàn lǐ liú chéng 。','Chào thầy, gần đây em sắp chuyển trường sang một trường ở tỉnh khác, em muốn hỏi quy trình làm thủ tục chuyển đi cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_02','V525','老师',2,'首先要在学校开好转学离校证明，然后带着证明去本地出入境大厅办理居留迁出备案。','shǒu xiān yào zài xué xiào kāi hǎo zhuǎn xué lí xiào zhèng míng ， rán hòu dài zhe zhèng míng qù běn dì chū rù jìng dà tīng bàn lǐ jū liú qiān chū bèi àn 。','Trước tiên em cần xin giấy xác nhận thôi học chuyển trường từ trường, sau đó mang giấy này ra sảnh xuất nhập cảnh địa phương để làm thủ tục đăng ký chuyển đi cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_03','V525','阮明',3,'那我办完迁出之后，原来的居留还能用吗？','nà wǒ bàn wán qiān chū zhī hòu ， yuán lái de jū liú hái néng yòng ma ？','Vậy làm thủ tục chuyển đi xong rồi, cư trú cũ của em còn dùng được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_04','V525','老师',4,'不行的，迁出手续办理完成的当天，你原本的居留许可就自动失效了。','bù xíng de ， qiān chū shǒu xù bàn lǐ wán chéng dí dàng tiān ， nǐ yuán běn de jū liú xǔ kě jiù zì dòng shī xiào le 。','Không được đâu, ngay trong ngày hoàn tất thủ tục chuyển đi, giấy phép cư trú cũ của em sẽ tự động hết hiệu lực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_05','V525','阮明',5,'这样啊……那我中间跨城市转学出行，没有有效居留会不会有问题？','zhè yàng a …… nà wǒ zhōng jiān kuà chéng shì zhuǎn xué chū xíng ， méi yǒu yǒu xiào jū liú huì bú huì yǒu wèn tí ？','Vậy à... thế trong lúc em di chuyển giữa các tỉnh để chuyển trường mà không có cư trú hợp lệ thì có vấn đề gì không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_06','V525','老师',6,'不用担心，出入境会给你开具三十天的临时停留证明，专门用来中转过渡。','bù yòng dān xīn ， chū rù jìng huì gěi nǐ kāi jù sān shí tiān de lín shí tíng liú zhèng míng ， zhuān mén yòng lái zhōng zhuǎn guò dù 。','Không cần lo, bên xuất nhập cảnh sẽ cấp cho em giấy tạm trú ba mươi ngày, dùng riêng cho giai đoạn chuyển tiếp này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_07','V525','阮明',7,'那我到了新学校之后，是不是要重新提交所有居留材料？','nà wǒ dào le xīn xué xiào zhī hòu ， shì bú shì yào chóng xīn tí jiāo suǒ yǒu jū liú cái liào ？','Vậy khi đến trường mới rồi, em có phải nộp lại toàn bộ hồ sơ cư trú từ đầu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_08','V525','老师',8,'对的，需要按照新生标准，全套重新递交材料，办理新城市的居留许可。','duì de ， xū yào àn zhào xīn shēng biāo zhǔn ， quán tào chóng xīn dì jiāo cái liào ， bàn lǐ xīn chéng shì de jū liú xǔ kě 。','Đúng vậy, em phải làm theo tiêu chuẩn của sinh viên mới, nộp lại toàn bộ hồ sơ để làm giấy phép cư trú ở thành phố mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L525_09','V525','阮明',9,'我明白了，那我先办好离校转学证明，再去大厅办理迁出备案。','wǒ míng bái le ， nà wǒ xiān bàn hǎo lí xiào zhuǎn xué zhèng míng ， zài qù dà tīng bàn lǐ qiān chū bèi àn 。','Em hiểu rồi ạ, vậy em sẽ xin giấy xác nhận thôi học chuyển trường trước, rồi ra sảnh làm thủ tục đăng ký chuyển đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT526','SV4','更换校外租房地址，10日内办理居留地址变更',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V526','SIT526','P1','that_bai_nhe','tuy_y',NULL,'外籍人员更换居住地址法定十日内向社区更新住宿信息，多次逾期备案会影响后续居留续签审核。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_01','V526','阮明',1,'网格员你好，我最近换了校外的出租房，但是搬家之后太忙了，超过十天没办地址变更登记。','wǎng gé yuán nǐ hǎo ， wǒ zuì jìn huàn le xiào wài de chū zū fáng ， dàn shì bān jiā zhī hòu tài máng le ， chāo guò shí tiān méi bàn dì zhǐ biàn gēng dēng jì 。','Chào anh, gần đây em chuyển ra ngoài thuê trọ, nhưng chuyển nhà xong bận quá nên để quá mười ngày mà chưa đăng ký thay đổi địa chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_02','V526','网格员',2,'哎呀，这个要注意的，外籍人员更换居住地址，法定要十天内更新备案的，逾期会有警告记录。','āi yā ， zhè ge yào zhù yì de ， wài jí rén yuán gēng huàn jū zhù dì zhǐ ， fǎ dìng yào shí tiān nèi gēng xīn bèi àn de ， yú qī huì yǒu jǐng gào jì lù 。','Ôi, cái này phải chú ý đấy nhé, người nước ngoài thay đổi chỗ ở là theo luật phải cập nhật đăng ký trong vòng mười ngày, để quá hạn là sẽ bị ghi nhận cảnh cáo đó.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_03','V526','阮明',3,'我知道错了，最近上课太忙完全忘了。我现在来补办，会被罚款吗？','wǒ zhī dào cuò le ， zuì jìn shàng kè tài máng wán quán wàng le 。 wǒ xiàn zài lái bǔ bàn ， huì bèi fá kuǎn ma ？','Em biết sai rồi ạ, dạo này đi học bận quá nên quên mất luôn. Giờ em ra làm bù thì có bị phạt tiền không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_04','V526','网格员',4,'你是第一次轻微超期，只做书面警告，不会罚款。但要是下次再逾期，就会有行政处罚了。','nǐ shì dì yī cì qīng wēi chāo qī ， zhǐ zuò shū miàn jǐng gào ， bú huì fá kuǎn 。 dàn yào shì xià cì zài yú qī ， jiù huì yǒu xíng zhèng chǔ fá le 。','Em quá hạn nhẹ lần đầu thì chỉ bị cảnh cáo bằng văn bản thôi, không phạt tiền đâu. Nhưng lần sau mà còn quá hạn nữa là sẽ bị xử phạt hành chính đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_05','V526','阮明',5,'还好只是警告！那补办的话，需要房东过来配合吗？','hái hǎo zhǐ shì jǐng gào ！ nà bǔ bàn de huà ， xū yào fáng dōng guò lái pèi hé ma ？','May quá chỉ bị cảnh cáo thôi! Vậy làm bù thì có cần chủ nhà đến phối hợp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_06','V526','网格员',6,'需要的，得让房东本人到场签字，我们这边才能同步打印新的住宿登记单。','xū yào de ， dé ràng fáng dōng běn rén dào chǎng qiān zì ， wǒ men zhè biān cái néng tóng bù dǎ yìn xīn de zhù sù dēng jì dān 。','Cần chứ, phải để chủ nhà đích thân đến ký tên, bên anh mới in được phiếu đăng ký lưu trú mới đồng bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L526_07','V526','阮明',7,'好，我现在马上联系房东过来，立刻补办变更登记。','hǎo ， wǒ xiàn zài mǎ shàng lián xì fáng dōng guò lái ， lì kè bǔ bàn biàn gēng dēng jì 。','Vâng, em liên hệ chủ nhà đến ngay bây giờ, làm bù đăng ký thay đổi luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT527','SV4','护照个人信息更新，同步更新居留证件信息',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V527','SIT527','P1','suon_se','chinh_thuc',NULL,'护照姓名、国籍、证件编号等核心信息变动后，必须同步更新居留许可，证件信息不一致会被判定无效证件。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_01','V527','阮明',1,'您好，我刚更换了新护照，上面的姓名拼写更新了，想来同步改一下居留卡的对应信息。','nín hǎo ， wǒ gāng gēng huàn le xīn hù zhào ， shàng miàn de xìng míng pīn xiě gēng xīn le ， xiǎng lái tóng bù gǎi yī xià jū liú kǎ de duì yìng xìn xī 。','Chào chị, em vừa đổi hộ chiếu mới, cách viết tên trên đó có cập nhật, em muốn đến đồng bộ lại thông tin tương ứng trên thẻ cư trú ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_02','V527','工作人员',2,'可以办理。请提供你的新护照、使馆开具的信息变更证明，还有一张证件照。','kě yǐ bàn lǐ 。 qǐng tí gōng nǐ de xīn hù zhào 、 shǐ guǎn kāi jù de xìn xī biàn gēng zhèng míng ， hái yǒu yī zhāng zhèng jiàn zhào 。','Được, em cung cấp hộ chiếu mới, giấy xác nhận thay đổi thông tin do đại sứ quán cấp, và một tấm ảnh thẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_03','V527','阮明',3,'好的。我想确认一下，信息改完之后，居留的到期时间会不会变？','hǎo de 。 wǒ xiǎng què rèn yī xià ， xìn xī gǎi wán zhī hòu ， jū liú de dào qī shí jiān huì bú huì biàn ？','Vâng ạ. Em muốn xác nhận lại, sau khi sửa thông tin xong thì thời hạn cư trú có thay đổi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_04','V527','工作人员',4,'有效期完全不变，系统只同步更新你的姓名、护照编号这些核心信息。','yǒu xiào qī wán quán bù biàn ， xì tǒng zhǐ tóng bù gēng xīn nǐ de xìng míng 、 hù zhào biān hào zhè xiē hé xīn xìn xī 。','Thời hạn hoàn toàn không đổi, hệ thống chỉ đồng bộ cập nhật những thông tin cốt lõi như tên và số hộ chiếu của em thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_05','V527','阮明',5,'那就没问题。那更新之后，我出入境、坐高铁、住酒店，就不会显示信息不符了吧？','nà jiù méi wèn tí 。 nà gēng xīn zhī hòu ， wǒ chū rù jìng 、 zuò gāo tiě 、 zhù jiǔ diàn ， jiù bú huì xiǎn shì xìn xī bù fú le ba ？','Vậy thì không vấn đề gì rồi. Sau khi cập nhật xong, khi em xuất nhập cảnh, đi tàu cao tốc, hay ở khách sạn thì sẽ không bị báo sai lệch thông tin nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_06','V527','工作人员',6,'对的，信息是实时同步的，全国所有查验终端都会刷新最新数据，不会有异常。','duì de ， xìn xī shì shí shí tóng bù de ， quán guó suǒ yǒu chá yàn zhōng duān dōu huì shuā xīn zuì xīn shù jù ， bú huì yǒu yì cháng 。','Đúng vậy, thông tin được đồng bộ theo thời gian thực, tất cả các điểm kiểm tra trên toàn quốc đều sẽ cập nhật dữ liệu mới nhất, không có gì bất thường đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L527_07','V527','阮明',7,'嗯，我材料都带齐了，麻烦您帮我受理一下这个变更业务。','ń ， wǒ cái liào dōu dài qí le ， má fán nín bāng wǒ shòu lǐ yī xià zhè ge biàn gēng yè wù 。','Vâng, hồ sơ em mang đủ hết rồi, phiền chị tiếp nhận giúp em thủ tục thay đổi này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT528','SV5','咨询留学生合法校外实习签证备案流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V528','SIT528','P1','twist','ban_chinh_thuc',NULL,'外籍留学生无备案校外实习属于非法务工，一旦查实会行政处罚，严重者不予续签居留许可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_01','V528','阮明',1,'老师，我最近找了一家校外企业的实习，想问问留学生实习要怎么备案？','lǎo shī ， wǒ zuì jìn zhǎo le yī jiā xiào wài qǐ yè de shí xí ， xiǎng wèn wèn liú xué shēng shí xí yào zěn me bèi àn ？','Thầy ơi, gần đây em xin được thực tập ở một công ty ngoài trường, cho em hỏi du học sinh đi thực tập thì phải đăng ký như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_02','V528','老师',2,'校外实习管控很严格，必须学校、你本人、实习企业三方签协议，完成备案才算合法。','xiào wài shí xí guǎn kòng hěn yán gé ， bì xū xué xiào 、 nǐ běn rén 、 shí xí qǐ yè sān fāng qiān xié yì ， wán chéng bèi àn cái suàn hé fǎ 。','Thực tập ngoài trường quản lý rất chặt, bắt buộc phải có ba bên là trường, bản thân em, và công ty thực tập cùng ký thỏa thuận, hoàn tất đăng ký thì mới hợp pháp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_03','V528','阮明',3,'啊？如果我先去实习，后面再补备案可以吗？会不会影响之后的签证续签？','a ？ rú guǒ wǒ xiān qù shí xí ， hòu miàn zài bǔ bèi àn kě yǐ ma ？ huì bú huì yǐng xiǎng zhī hòu de qiān zhèng xù qiān ？','Ơ? Nếu em đi thực tập trước rồi đăng ký bù sau có được không ạ? Có ảnh hưởng đến việc gia hạn visa sau này không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_04','V528','老师',4,'绝对不行。没有备案的校外务工属于非法就业，一旦查到，不仅会罚款，还会直接缩短你的居留期限。','jué duì bù xíng 。 méi yǒu bèi àn de xiào wài wù gōng shǔ yú fēi fǎ jiù yè ， yí dàn chá dào ， bù jǐn huì fá kuǎn ， hái huì zhí jiē suō duǎn nǐ de jū liú qī xiàn 。','Tuyệt đối không được. Đi làm ngoài trường mà chưa đăng ký là thuộc diện làm việc trái phép, một khi bị phát hiện thì không chỉ bị phạt tiền mà còn bị cắt ngắn thời hạn cư trú của em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_05','V528','阮明',5,'我明白了。那我还有个问题，要是我备案了一家公司，中途想换实习单位，还能重新备案吗？','wǒ míng bái le 。 nà wǒ hái yǒu gè wèn tí ， yào shì wǒ bèi àn le yī jiā gōng sī ， zhōng tú xiǎng huàn shí xí dān wèi ， hái néng chóng xīn bèi àn ma ？','Em hiểu rồi ạ. Em còn một câu hỏi nữa, nếu em đã đăng ký một công ty rồi, giữa chừng muốn đổi nơi thực tập thì có đăng ký lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_06','V528','老师',6,'不能直接新增，得先把原来的实习备案注销掉，再重新提交新的三方协议才行。','bù néng zhí jiē xīn zēng ， dé xiān bǎ yuán lái de shí xí bèi àn zhù xiāo diào ， zài chóng xīn tí jiāo xīn de sān fāng xié yì cái xíng 。','Không thể thêm trực tiếp được đâu, phải hủy đăng ký thực tập cũ trước, rồi nộp lại thỏa thuận ba bên mới thì mới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_07','V528','阮明',7,'原来是这样，我还以为可以直接叠加备案。那办理备案需要企业的营业执照复印件吗？','yuán lái shì zhè yàng ， wǒ hái yǐ wéi kě yǐ zhí jiē dié jiā bèi àn 。 nà bàn lǐ bèi àn xū yào qǐ yè de yíng yè zhí zhào fù yìn jiàn ma ？','Ra là vậy, em cứ tưởng có thể đăng ký chồng lên trực tiếp. Vậy làm đăng ký có cần bản sao giấy phép kinh doanh của công ty không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_08','V528','老师',8,'需要的，而且必须是加盖企业公章的复印件，这是备案的核心材料，缺一不可。','xū yào de ， ér qiě bì xū shì jiā gài qǐ yè gōng zhāng de fù yìn jiàn ， zhè shì bèi àn de hé xīn cái liào ， quē yī bù kě 。','Cần chứ, mà phải là bản sao có đóng dấu công ty đàng hoàng, đây là giấy tờ cốt lõi của việc đăng ký, thiếu là không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L528_09','V528','阮明',9,'好，那我先跟企业对接好，把资质材料准备齐全，再来学校办理备案。','hǎo ， nà wǒ xiān gēn qǐ yè duì jiē hǎo ， bǎ zī zhì cái liào zhǔn bèi qí quán ， zài lái xué xiào bàn lǐ bèi àn 。','Vâng, vậy em sẽ trao đổi với công ty trước, chuẩn bị đầy đủ giấy tờ pháp lý rồi mới đến trường làm đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT529','SV5','办理留学生校内勤工助学务工备案证明',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V529','SIT529','P1','suon_se','tuy_y',NULL,'留学生校内勤工助学同样有严格时长限制，校内备案仅学院留存，校外实习必须同步向出入境备案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_01','V529','阮明',1,'老师，我申请了图书馆的校内助教兼职，这个需要办务工备案吗？','lǎo shī ， wǒ shēn qǐng le tú shū guǎn de xiào nèi zhù jiào jiān zhí ， zhè ge xū yào bàn wù gōng bèi àn ma ？','Thầy ơi, em xin được làm trợ giảng bán thời gian ở thư viện trong trường, cái này có cần đăng ký làm thêm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_02','V529','老师',2,'要的哦，校内勤工助学也得备案，系统里要有记录留存。','yào de ó ， xiào nèi qín gōng zhù xué yě dé bèi àn ， xì tǒng lǐ yào yǒu jì lù liú cún 。','Cần đó, làm thêm trong trường cũng phải đăng ký, hệ thống phải có lưu hồ sơ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_03','V529','阮明',3,'那打工时长还是和以前一样，一周最多二十小时对吧？','nà dǎ gōng shí cháng hái shì hé yǐ qián yī yàng ， yī zhōu zuì duō èr shí xiǎo shí duì ba ？','Vậy thời gian làm thêm vẫn như trước, một tuần tối đa hai mươi tiếng đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_04','V529','老师',4,'平时上课周是二十小时上限，寒暑假可以放宽到四十小时。','píng shí shàng kè zhōu shì èr shí xiǎo shí shàng xiàn ， hán shǔ jià kě yǐ fàng kuān dào sì shí xiǎo shí 。','Bình thường trong tuần học thì giới hạn hai mươi tiếng, còn kỳ nghỉ đông hè thì được nới lên bốn mươi tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_05','V529','阮明',5,'了解了。那这个备案办好之后，要不要拿去出入境更新签证信息呀？','liǎo jiě le 。 nà zhè ge bèi àn bàn hǎo zhī hòu ， yào bù yào ná qù chū rù jìng gēng xīn qiān zhèng xìn xī ya ？','Em hiểu rồi ạ. Vậy đăng ký xong rồi có cần mang ra xuất nhập cảnh cập nhật thông tin visa không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_06','V529','老师',6,'不用这么麻烦，校内兼职只需要学院内部存档，不用跑出入境。','bù yòng zhè me má fán ， xiào nèi jiān zhí zhǐ xū yào xué yuàn nèi bù cún dàng ， bù yòng pǎo chū rù jìng 。','Không cần rắc rối vậy đâu, làm thêm trong trường chỉ cần lưu hồ sơ nội bộ ở khoa thôi, không cần chạy ra xuất nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L529_07','V529','阮明',7,'行，那我把申请表填好，找您盖章备案就行。','xíng ， nà wǒ bǎ shēn qǐng biǎo tián hǎo ， zhǎo nín gài zhāng bèi àn jiù xíng 。','Dạ, vậy em điền đơn đăng ký xong sẽ tìm thầy để đóng dấu đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT530','SV5','咨询逾期打工、超时务工对签证续签的影响',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V530','SIT530','P1','twist','chinh_thuc',NULL,'中国法律严格限制外籍留学生务工时长与务工范围，非法就业会直接影响居留续签，甚至限期离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_01','V530','阮明',1,'警官您好，我想咨询一下，如果留学生没有备案打工，或者打工超时，对签证续签有什么影响？','jǐng guān nín hǎo ， wǒ xiǎng zī xún yī xià ， rú guǒ liú xué shēng méi yǒu bèi àn dǎ gōng ， huò zhě dǎ gōng chāo shí ， duì qiān zhèng xù qiān yǒu shén me yǐng xiǎng ？','Chào anh công an, tôi muốn hỏi thăm một chút, nếu du học sinh làm thêm mà không đăng ký, hoặc làm thêm quá giờ quy định, thì sẽ ảnh hưởng thế nào đến việc gia hạn visa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_02','V530','辅警',2,'首次查到这类非法务工行为，会处以罚款，同时缩短半年的居留许可有效期。','shǒu cì chá dào zhè lèi fēi fǎ wù gōng háng wèi ， huì chǔ yǐ fá kuǎn ， tóng shí suō duǎn bàn nián de jū liú xǔ kě yǒu xiào qī 。','Nếu lần đầu bị phát hiện làm việc bất hợp pháp kiểu này, sẽ bị phạt tiền, đồng thời rút ngắn nửa năm thời hạn hiệu lực của giấy phép cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_03','V530','阮明',3,'只是缩短有效期吗？那如果是多次违规，会不会直接不给续签了？','zhǐ shì suō duǎn yǒu xiào qī ma ？ nà rú guǒ shì duō cì wéi guī ， huì bú huì zhí jiē bù gěi xù qiān le ？','Chỉ bị rút ngắn thời hạn thôi ạ? Vậy nếu vi phạm nhiều lần thì có bị từ chối gia hạn luôn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_04','V530','辅警',4,'对的，两次及以上违规记录，出入境会直接驳回你的居留续签申请。','duì de ， liǎng cì jí yǐ shàng wéi guī jì lù ， chū rù jìng huì zhí jiē bó huí nǐ de jū liú xù qiān shēn qǐng 。','Đúng vậy, nếu có từ hai lần vi phạm trở lên, phòng xuất nhập cảnh sẽ trực tiếp từ chối đơn xin gia hạn cư trú của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_05','V530','阮明',5,'那寒暑假的四十小时上限，超出一点点也算违规吗？','nà hán shǔ jià de sì shí xiǎo shí shàng xiàn ， chāo chū yì diǎn diǎn yě suàn wéi guī ma ？','Vậy giới hạn 40 giờ trong kỳ nghỉ đông hè, chỉ vượt quá một chút thôi cũng tính là vi phạm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_06','V530','辅警',6,'算的，不管是学期还是假期，只要超出规定时长，一律判定为非法就业，没有例外。','suàn de ， bù guǎn shì xué qī hái shì jià qī ， zhǐ yào chāo chū guī dìng shí cháng ， yī lǜ pàn dìng wèi fēi fǎ jiù yè ， méi yǒu lì wài 。','Tính chứ, dù là trong học kỳ hay kỳ nghỉ, chỉ cần vượt quá thời gian quy định là đều bị coi là làm việc bất hợp pháp, không có ngoại lệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_07','V530','阮明',7,'啊这……那我要是换了实习单位，忘了注销之前的旧备案，会不会也有问题？','a zhè …… nà wǒ yào shì huàn le shí xí dān wèi ， wàng le zhù xiāo zhī qián de jiù bèi àn ， huì bú huì yě yǒu wèn tí ？','Ơ vậy à... Vậy nếu em đổi đơn vị thực tập mà quên hủy đăng ký cũ trước đó, thì có bị coi là có vấn đề không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_08','V530','辅警',8,'会的，系统会判定你同时在多家单位务工，同样属于违规行为。','huì de ， xì tǒng huì pàn dìng nǐ tóng shí zài duō jiā dān wèi wù gōng ， tóng yàng shǔ yú wéi guī xíng wéi 。','Có chứ, hệ thống sẽ xác định là bạn đang làm việc cùng lúc ở nhiều đơn vị, đó cũng là hành vi vi phạm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L530_09','V530','阮明',9,'明白了，我之后一定严格遵守时长规定，及时更新、注销实习备案，绝不违规。','míng bái le ， wǒ zhī hòu yí dìng yán gé zūn shǒu shí cháng guī dìng ， jí shí gēng xīn 、 zhù xiāo shí xí bèi àn ， jué bù wéi guī 。','Em hiểu rồi ạ, sau này em nhất định sẽ tuân thủ nghiêm ngặt quy định về thời gian, cập nhật và hủy đăng ký thực tập kịp thời, tuyệt đối không vi phạm nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT531','SV6','毕业申请短期停留签证（毕业生留华缓冲期）',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V531','SIT531','P1','suon_se','ban_chinh_thuc',NULL,'留学生毕业后可申请最长180天短期停留缓冲签证，该签证禁止任何形式务工、实习，到期必须离境。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_01','V531','阮明',1,'您好，我已经顺利毕业了，想申请毕业生的短期停留签证。','nín hǎo ， wǒ yǐ jīng shùn lì bì yè le ， xiǎng shēn qǐng bì yè shēng de duǎn qī tíng liú qiān zhèng 。','Chào anh chị, em đã tốt nghiệp thuận lợi rồi, giờ em muốn xin visa lưu trú ngắn hạn dành cho sinh viên mới tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_02','V531','工作人员',2,'可以的，请准备好毕业证、离校证明、住宿登记单，还有一张证件照。','kě yǐ de ， qǐng zhǔn bèi hǎo bì yè zhèng 、 lí xiào zhèng míng 、 zhù sù dēng jì dān ， hái yǒu yī zhāng zhèng jiàn zhào 。','Được, bạn chuẩn bị bằng tốt nghiệp, giấy chứng nhận rời trường, phiếu đăng ký lưu trú, và một tấm ảnh thẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_03','V531','阮明',3,'好的。我想问下这个短期签证最长能办多久？是三十天还是更久？','hǎo de 。 wǒ xiǎng wèn xià zhè ge duǎn qī qiān zhèng zuì zhǎng néng bàn duō jiǔ ？ shì sān shí tiān hái shì gèng jiǔ ？','Dạ vâng. Em muốn hỏi visa ngắn hạn này có thể xin tối đa bao lâu ạ? Là 30 ngày hay lâu hơn?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_04','V531','工作人员',4,'毕业生缓冲居留最长可以申请一百八十天，你可以根据自己的需求选择时长。','bì yè shēng huǎn chōng jū liú zuì zhǎng kě yǐ shēn qǐng yì bǎi bā shí tiān ， nǐ kě yǐ gēn jù zì jǐ de xū qiú xuǎn zé shí cháng 。','Thời gian lưu trú đệm cho sinh viên mới tốt nghiệp tối đa có thể xin đến 180 ngày, bạn có thể chọn thời hạn theo nhu cầu của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_05','V531','阮明',5,'一百八十天这么久！那这段时间我能不能找实习、打工呢？','yì bǎi bā shí tiān zhè me jiǔ ！ nà zhè duàn shí jiān wǒ néng bù néng zhǎo shí xí 、 dǎ gōng ne ？','180 ngày lâu vậy sao! Vậy trong thời gian này em có thể tìm việc thực tập hoặc làm thêm được không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_06','V531','工作人员',6,'不可以的，毕业短期停留签证仅限旅游、整理行李、采购物品，禁止一切务工和实习行为。','bù kě yǐ de ， bì yè duǎn qī tíng liú qiān zhèng jǐn xiàn lǚ yóu 、 zhěng lǐ xíng lǐ 、 cǎi gòu wù pǐn ， jìn zhǐ yī qiè wù gōng hé shí xí xíng wéi 。','Không được đâu, visa lưu trú ngắn hạn sau tốt nghiệp chỉ dùng để du lịch, thu xếp hành lý, mua sắm đồ đạc, còn mọi hình thức làm thêm hay thực tập đều bị cấm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_07','V531','阮明',7,'懂了。那缓冲期到期之后，是不是完全不能延期，必须离境？','dǒng le 。 nà huǎn chōng qī dào qī zhī hòu ， shì bú shì wán quán bù néng yán qī ， bì xū lí jìng ？','Em hiểu rồi. Vậy sau khi hết thời gian đệm thì hoàn toàn không thể gia hạn, bắt buộc phải xuất cảnh đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_08','V531','工作人员',8,'是的，没有重大特殊事由，一律不予二次延期。','shì de ， méi yǒu zhòng dà tè shū shì yóu ， yī lǜ bù yǔ èr cì yán qī 。','Đúng vậy, nếu không có lý do đặc biệt quan trọng thì đều không được gia hạn lần hai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L531_09','V531','阮明',9,'好，我所有材料都备齐了，麻烦您帮我受理申请。','hǎo ， wǒ suǒ yǒu cái liào dōu bèi qí le ， má fán nín bāng wǒ shòu lǐ shēn qǐng 。','Dạ vâng, em đã chuẩn bị đầy đủ giấy tờ rồi, phiền anh chị giúp em tiếp nhận hồ sơ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT532','SV6','办理留学回国人员证明，用于境外学历认证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V532','SIT532','P1','twist','ban_chinh_thuc',NULL,'留学回国人员证明是境外学历认证必备材料，需要完整留存全部在华居留、出入境记录，证件丢失需打印官方流水补充。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_01','V532','阮明',1,'老师，我马上毕业了，需要办留学回国人员证明，回国之后要做学历认证。','lǎo shī ， wǒ mǎ shàng bì yè le ， xū yào bàn liú xué huí guó rén yuán zhèng míng ， huí guó zhī hòu yào zuò xué lì rèn zhèng 。','Thầy ơi, em sắp tốt nghiệp rồi, em cần làm giấy chứng nhận du học sinh về nước, để về nước làm thủ tục công nhận văn bằng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_02','V532','老师',2,'没问题，你准备好护照签证页复印件、毕业证和毕业离校回执交给我。','méi wèn tí ， nǐ zhǔn bèi hǎo hù zhào qiān zhèng yè fù yìn jiàn 、 bì yè zhèng hé bì yè lí xiào huí zhí jiāo gěi wǒ 。','Không vấn đề gì, em chuẩn bị bản photo trang visa hộ chiếu, bằng tốt nghiệp và biên nhận rời trường sau khi tốt nghiệp rồi đưa cho thầy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_03','V532','阮明',3,'那个……我的旧护照之前剪角弄丢了，现在只有新护照的复印件，这样可以吗？','nà ge …… wǒ de jiù hù zhào zhī qián jiǎn jiǎo nòng diū le ， xiàn zài zhǐ yǒu xīn hù zhào de fù yìn jiàn ， zhè yàng kě yǐ ma ？','À... hộ chiếu cũ của em bị cắt góc với lại làm mất rồi ạ, giờ em chỉ có bản photo hộ chiếu mới thôi, như vậy có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_04','V532','老师',4,'这不行的，缺少完整的在华居留出入境记录，材料不齐全，我这边暂时没法给你开具证明。','zhè bù xíng de ， quē shǎo wán zhěng de zài huá jū liú chū rù jìng jì lù ， cái liào bù qí quán ， wǒ zhè biān zàn shí méi fǎ gěi nǐ kāi jù zhèng míng 。','Vậy thì không được đâu, thiếu đầy đủ hồ sơ xuất nhập cảnh và cư trú tại Trung Quốc, giấy tờ không đủ thì thầy tạm thời chưa thể cấp giấy chứng nhận cho em được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_05','V532','阮明',5,'啊？那怎么办？我实在找不回旧护照了。能不能去派出所或者大厅打印出入境记录代替？','a ？ nà zěn me bàn ？ wǒ shí zài zhǎo bù huí jiù hù zhào le 。 néng bù néng qù pài chū suǒ huò zhě dà tīng dǎ yìn chū rù jìng jì lù dài tì ？','Ơ? Vậy phải làm sao ạ? Em thật sự không tìm lại được hộ chiếu cũ nữa. Em có thể ra đồn công an hoặc trung tâm hành chính in lại hồ sơ xuất nhập cảnh để thay thế được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_06','V532','老师',6,'可以的，你去出入境大厅打印一份完整的出入境流水单，就能补上缺失的记录。','kě yǐ de ， nǐ qù chū rù jìng dà tīng dǎ yìn yī fèn wán zhěng de chū rù jìng liú shuǐ dān ， jiù néng bǔ shàng quē shī de jì lù 。','Được đó, em ra phòng xuất nhập cảnh in một bản sao kê xuất nhập cảnh đầy đủ, là có thể bổ sung được phần hồ sơ còn thiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L532_07','V532','阮明',7,'太好了，那我现在就去打印流水，补齐材料再来找您办理。','tài hǎo le ， nà wǒ xiàn zài jiù qù dǎ yìn liú shuǐ ， bǔ qí cái liào zài lái zhǎo nín bàn lǐ 。','Tuyệt quá, vậy em đi in sao kê ngay bây giờ, bổ sung đủ giấy tờ rồi quay lại tìm thầy làm thủ tục ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT533','SV6','退学终止学业，注销有效居留许可限期离境',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V533','SIT533','P1','that_bai_nhe','chinh_thuc',NULL,'退学学籍终止，学生居留许可注销，缓冲期仅用于收拾行李离境，缓冲到期无合法续签渠道，超期属于非法滞留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_01','V533','阮明',1,'警官您好，我办理了退学手续，今天过来注销我的学生居留许可。','jǐng guān nín hǎo ， wǒ bàn lǐ le tuì xué shǒu xù ， jīn tiān guò lái zhù xiāo wǒ de xué shēng jū liú xǔ kě 。','Chào anh công an, tôi đã làm xong thủ tục thôi học, hôm nay đến để hủy giấy phép cư trú diện sinh viên của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_02','V533','民警',2,'出示一下你的退学离校证明。居留注销后，系统会自动给你三十天的合法停留缓冲期。','chū shì yī xià nǐ de tuì xué lí xiào zhèng míng 。 jū liú zhù xiāo hòu ， xì tǒng huì zì dòng gěi nǐ sān shí tiān de hé fǎ tíng liú huǎn chōng qī 。','Cho tôi xem giấy chứng nhận thôi học rời trường của anh chị. Sau khi hủy cư trú, hệ thống sẽ tự động cho anh chị 30 ngày lưu trú hợp pháp đệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_03','V533','阮明',3,'好的，证明在这里。那这三十天里，我正常出门旅游、出行都没问题吧？','hǎo de ， zhèng míng zài zhè lǐ 。 nà zhè sān shí tiān lǐ ， wǒ zhèng cháng chū mén lǚ yóu 、 chū xíng dōu méi wèn tí ba ？','Vâng, giấy chứng nhận đây ạ. Vậy trong 30 ngày này, tôi đi lại, du lịch bình thường thì không sao chứ ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_04','V533','民警',4,'出行不受限制，但是你要清楚，缓冲期一到必须离境，没办法续签、延期。','chū xíng bù shòu xiàn zhì ， dàn shì nǐ yào qīng chǔ ， huǎn chōng qī yī dào bì xū lí jìng ， méi bàn fǎ xù qiān 、 yán qī 。','Việc đi lại không bị hạn chế, nhưng anh chị phải nhớ rõ, hết thời gian đệm là bắt buộc phải xuất cảnh, không thể gia hạn hay xin thêm thời gian được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_05','V533','阮明',5,'我明白。但我担心万一三十天内没买到机票，不小心超期停留了，会有什么处罚？','wǒ míng bái 。 dàn wǒ dān xīn wàn yī sān shí tiān nèi méi mǎi dào jī piào ， bù xiǎo xīn chāo qī tíng liú le ， huì yǒu shén me chǔ fá ？','Tôi hiểu rồi. Nhưng tôi lo là nếu trong 30 ngày không mua được vé máy bay, lỡ ở quá hạn thì sẽ bị xử phạt như thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_06','V533','民警',6,'退学后你已经没有有效学籍了，一旦超期停留，每天都会产生罚款，还会留下不良入境记录，影响以后来华。','tuì xué hòu nǐ yǐ jīng méi yǒu yǒu xiào xué jí le ， yí dàn chāo qī tíng liú ， měi tiān dōu huì chǎn shēng fá kuǎn ， hái huì liú xià bù liáng rù jìng jì lù ， yǐng xiǎng yǐ hòu lái huá 。','Sau khi thôi học thì anh chị không còn tư cách học sinh hợp lệ nữa, nếu ở quá hạn thì mỗi ngày đều sẽ bị tính phạt, còn để lại tiền sử xuất nhập cảnh xấu, ảnh hưởng đến việc quay lại Trung Quốc sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_07','V533','阮明',7,'这么严重……那我再确认下，缓冲期内如果我临时回国一趟，还能再进来吗？','zhè me yán zhòng …… nà wǒ zài què rèn xià ， huǎn chōng qī nèi rú guǒ wǒ lín shí huí guó yī tàng ， hái néng zài jìn lái ma ？','Nghiêm trọng vậy sao... Vậy tôi xác nhận lại, trong thời gian đệm nếu tôi về nước tạm thời một chuyến, thì có thể quay lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_08','V533','民警',8,'不能，居留注销后签证直接失效，一旦离境，就无法再次入境中国了。','bù néng ， jū liú zhù xiāo hòu qiān zhèng zhí jiē shī xiào ， yí dàn lí jìng ， jiù wú fǎ zài cì rù jìng zhōng guó le 。','Không được, sau khi hủy cư trú thì visa mất hiệu lực ngay, một khi đã xuất cảnh là không thể nhập cảnh lại Trung Quốc được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L533_09','V533','阮明',9,'我清楚规定了，我会在三十天内订好机票，按时回国，绝不逾期。','wǒ qīng chǔ guī dìng le ， wǒ huì zài sān shí tiān nèi dìng hǎo jī piào ， àn shí huí guó ， jué bù yú qī 。','Tôi đã hiểu rõ quy định rồi, tôi sẽ đặt vé máy bay trong vòng 30 ngày, về nước đúng hạn, tuyệt đối không để quá hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT534','SV6','签证到期前彻底回国，咨询居留注销流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V534','SIT534','P1','suon_se','tuy_y',NULL,'留学生永久离境建议主动注销居留许可，证件到期自动失效虽无罚款，但会提升下次来华签证的审核严格程度。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_01','V534','阮明',1,'警官，我毕业之后就直接回国了，以后暂时不来中国了，需要注销居留吗？','jǐng guān ， wǒ bì yè zhī hòu jiù zhí jiē huí guó le ， yǐ hòu zàn shí bù lái zhōng guó le ， xū yào zhù xiāo jū liú ma ？','Anh công an ơi, em tốt nghiệp xong là về nước luôn, sau này tạm thời không sang Trung Quốc nữa, vậy em có cần hủy cư trú không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_02','V534','辅警',2,'建议主动注销哈，长期离境不注销，休眠证件容易产生异常记录。','jiàn yì zhǔ dòng zhù xiāo hā ， cháng qī lí jìng bù zhù xiāo ， xiū mián zhèng jiàn róng yì chǎn shēng yì cháng jì lù 。','Nên chủ động hủy đi nha, để lâu mà không hủy, giấy tờ ở trạng thái treo dễ phát sinh ghi nhận bất thường lắm.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_03','V534','阮明',3,'哦，那如果我不主动注销，让它到期自动失效，会不会有负面影响？','ó ， nà rú guǒ wǒ bù zhǔ dòng zhù xiāo ， ràng tā dào qī zì dòng shī xiào ， huì bú huì yǒu fù miàn yǐng xiǎng ？','À, vậy nếu em không chủ động hủy, cứ để nó tự hết hạn thì có ảnh hưởng gì xấu không ạ?','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_04','V534','辅警',4,'到期自动失效是没有罚款的，但是下次你想申请来华签证，审核会更严格、更麻烦。','dào qī zì dòng shī xiào shì méi yǒu fá kuǎn de ， dàn shì xià cì nǐ xiǎng shēn qǐng lái huá qiān zhèng ， shěn hé huì gèng yán gé 、 gèng má fán 。','Tự hết hạn thì không bị phạt tiền đâu, nhưng lần sau em muốn xin visa sang Trung Quốc lại thì việc xét duyệt sẽ gắt gao và phiền phức hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_05','V534','阮明',5,'原来是这样。那注销的话，只带护照就够了吗？','yuán lái shì zhè yàng 。 nà zhù xiāo de huà ， zhǐ dài hù zhào jiù gòu le ma ？','Ra là vậy. Vậy nếu hủy thì chỉ cần mang hộ chiếu thôi là đủ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_06','V534','辅警',6,'还要带上你的毕业证，现场办理注销，当场就能给你打印注销回执。','hái yào dài shàng nǐ de bì yè zhèng ， xiàn chǎng bàn lǐ zhù xiāo ， dāng chǎng jiù néng gěi nǐ dǎ yìn zhù xiāo huí zhí 。','Còn phải mang theo bằng tốt nghiệp nữa, làm thủ tục hủy tại chỗ luôn, xong là in biên nhận hủy cho em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_07','V534','阮明',7,'那我保留好这个回执，以后再来留学办签证会顺利一点？','nà wǒ bǎo liú hǎo zhè ge huí zhí ， yǐ hòu zài lái liú xué bàn qiān zhèng huì shùn lì yì diǎn ？','Vậy em giữ kỹ cái biên nhận này, sau này quay lại du học xin visa sẽ thuận lợi hơn đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_08','V534','辅警',8,'对的，有完整的注销记录，签证审核通过率会高很多。','duì de ， yǒu wán zhěng de zhù xiāo jì lù ， qiān zhèng shěn hé tōng guò lǜ huì gāo hěn duō 。','Đúng rồi, có hồ sơ hủy đầy đủ thì tỷ lệ xét duyệt visa đậu sẽ cao hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L534_09','V534','阮明',9,'行，那我离校前抽空过来把居留注销了。','xíng ， nà wǒ lí xiào qián chōu kòng guò lái bǎ jū liú zhù xiāo le 。','Được ạ, vậy trước khi rời trường em sẽ tranh thủ qua đây hủy cư trú luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT535','SV6','毕业短期签证到期无法按时离境，申请延期缓冲',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V535','SIT535','P1','twist','chinh_thuc',NULL,'毕业生短期缓冲签证一般不可延期，仅航班取消、重病住院等不可抗力可短期延长停留期限，且需缴纳签证工本费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_01','V535','阮明',1,'您好，我的毕业短期停留签证马上到期了，但是我的回国航班延误取消了，实在没办法按时离境，想申请延期。','nín hǎo ， wǒ de bì yè duǎn qī tíng liú qiān zhèng mǎ shàng dào qī le ， dàn shì wǒ de huí guó háng bān yán wù qǔ xiāo le ， shí zài méi bàn fǎ àn shí lí jìng ， xiǎng shēn qǐng yán qī 。','Chào anh chị, visa lưu trú ngắn hạn sau tốt nghiệp của tôi sắp hết hạn rồi, nhưng chuyến bay về nước của tôi bị hoãn rồi hủy, thực sự không thể xuất cảnh đúng hạn được, tôi muốn xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_02','V535','工作人员',2,'我先说明一下政策，毕业短期签证原则上是不允许延期的，只有突发客观情况才能特殊审批。','wǒ xiān shuō míng yī xià zhèng cè ， bì yè duǎn qī qiān zhèng yuán zé shàng shì bù yǔn xǔ yán qī de ， zhǐ yǒu tū fā kè guān qíng kuàng cái néng tè shū shěn pī 。','Tôi giải thích trước về quy định, visa ngắn hạn sau tốt nghiệp về nguyên tắc là không được gia hạn, chỉ có trường hợp phát sinh khách quan đột xuất mới được xét duyệt đặc biệt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_03','V535','阮明',3,'我理解！这次是大规模国际航班取消，航空公司已经给我开了延误证明，您看一下。','wǒ lǐ jiě ！ zhè cì shì dà guī mó guó jì háng bān qǔ xiāo ， háng kōng gōng sī yǐ jīng gěi wǒ kāi le yán wù zhèng míng ， nín kàn yī xià 。','Tôi hiểu ạ! Lần này là do hủy hàng loạt chuyến bay quốc tế, hãng hàng không đã cấp cho tôi giấy chứng nhận hoãn chuyến rồi, anh chị xem qua giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_04','V535','工作人员',4,'嗯，航班延误属于不可抗力，符合特殊审批条件，最多可以给你延期十五天。','ń ， háng bān yán wù shǔ yú bù kě kàng lì ， fú hé tè shū shěn pī tiáo jiàn ， zuì duō kě yǐ gěi nǐ yán qī shí wǔ tiān 。','Ừm, việc hoãn chuyến bay thuộc trường hợp bất khả kháng, đủ điều kiện xét duyệt đặc biệt, tối đa có thể gia hạn cho anh chị 15 ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_05','V535','阮明',5,'太好了，太感谢了！那这十五天的延期需要交手续费吗？','tài hǎo le ， tài gǎn xiè le ！ nà zhè shí wǔ tiān de yán qī xū yào jiāo shǒu xù fèi ma ？','Tuyệt quá, cảm ơn anh chị nhiều lắm! Vậy gia hạn 15 ngày này có cần đóng phí thủ tục không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_06','V535','工作人员',6,'需要收取标准的签证工本费，没有免费办理的政策。','xū yào shōu qǔ biāo zhǔn de qiān zhèng gōng běn fèi ， méi yǒu miǎn fèi bàn lǐ de zhèng cè 。','Cần đóng phí làm visa theo mức quy định, không có chính sách miễn phí đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_07','V535','阮明',7,'明白。那我是不是递交延误证明、护照和证件照就可以办理？','míng bái 。 nà wǒ shì bú shì dì jiāo yán wù zhèng míng 、 hù zhào hé zhèng jiàn zhào jiù kě yǐ bàn lǐ ？','Tôi hiểu rồi. Vậy tôi chỉ cần nộp giấy chứng nhận hoãn chuyến, hộ chiếu và ảnh thẻ là có thể làm thủ tục được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_08','V535','工作人员',8,'材料齐全的话，三个工作日就能完成审批和制证。','cái liào qí quán de huà ， sān gè gōng zuò rì jiù néng wán chéng shěn pī hé zhì zhèng 。','Nếu giấy tờ đầy đủ thì trong ba ngày làm việc là có thể hoàn tất xét duyệt và làm giấy tờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L535_09','V535','阮明',9,'好，材料我都带齐了，现在递交我的延期申请。','hǎo ， cái liào wǒ dōu dài qí le ， xiàn zài dì jiāo wǒ de yán qī shēn qǐng 。','Vâng, giấy tờ tôi đã mang đầy đủ rồi, giờ tôi xin nộp đơn xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT601','SF1','下载注册国际通用视频软件，和父母跨国视频通话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V601','SIT601','P1','suon_se','tuy_y',NULL,'国内本土社交软件海外受限，留学生普遍使用国际通用通讯软件和境外家人联络。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_01','V601','阮明',1,'小林，我想装一款国外能用的视频软件跟爸妈通话，你知道哪款好用吗？','xiǎo lín， wǒ xiǎng zhuāng yī kuǎn guó wài néng yòng de shì pín ruǎn jiàn gēn bà mā tōng huà， nǐ zhī dào nǎ kuǎn hǎo yòng ma？','Tiểu Lâm, tớ muốn cài một app video dùng được ở nước ngoài để gọi cho bố mẹ, cậu biết app nào dùng ổn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_02','V601','小林',2,'这款APP国内外都能互通，下载之后用邮箱注册就行啦。','zhè kuǎn APP guó nèi wài dōu néng hù tōng， xià zài zhī hòu yòng yóu xiāng zhù cè jiù xíng la。','App này trong nước ngoài nước gì cũng liên lạc được hết, tải về rồi đăng ký bằng email là xong ngay ấy mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_03','V601','阮明',3,'国内手机号注册的话，越南那边收得到验证码吗？','guó nèi shǒu jī hào zhù cè de huà， yuè nán nà biān shōu dé dào yàn zhèng mǎ ma？','Nếu đăng ký bằng số điện thoại trong nước thì bên Việt Nam có nhận được mã xác nhận không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_04','V601','小林',4,'手机号跨国有延迟，直接绑定邮箱登录最稳妥呢。','shǒu jī hào kuà guó yǒu yán chí， zhí jiē bǎng dìng yóu xiāng dēng lù zuì wěn tuǒ ne。','Số điện thoại xuyên quốc gia hay bị trễ lắm, cứ gắn email để đăng nhập là chắc ăn nhất đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_05','V601','阮明',5,'注册完成后，直接搜索爸妈的账号就能发起视频吗？','zhù cè wán chéng hòu， zhí jiē sōu suǒ bà mā de zhàng hào jiù néng fā qǐ shì pín ma？','Đăng ký xong là tớ tìm tài khoản của bố mẹ rồi gọi video luôn được hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_06','V601','小林',6,'没错，还能发照片、短视频，日常报平安很方便。','méi cuò， hái néng fā zhào piān、 duǎn shì pín， rì cháng bào píng ān hěn fāng biàn。','Đúng rồi, còn gửi ảnh, gửi video ngắn được nữa, báo bình an hằng ngày tiện lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L601_07','V601','阮明',7,'太好了，你教我一步步注册，今晚就能跟家里视频。','tài hǎo le， nǐ jiāo wǒ yí bù bù zhù cè， jīn wǎn jiù néng gēn jiā lǐ shì pín。','Tuyệt quá, cậu chỉ tớ đăng ký từng bước đi, tối nay là gọi video về nhà được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT602','SF1','宿舍WiFi卡顿，求助室友调试网络方便和家人打电话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V602','SIT602','P1','twist','tuy_y',NULL,'高校宿舍晚八点至十点是网络使用高峰，多人同时联网会造成网速变慢、跨国视频卡顿。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_01','V602','阮明',1,'我一打开视频软件网络就卡顿，根本没法跟爸妈正常通话啊。','wǒ yī dǎ kāi shì pín ruǎn jiàn wǎng luò jiù kǎ dùn， gēn běn méi fǎ gēn bà mā zhèng cháng tōng huà a。','Tớ vừa mở app video lên là mạng bị giật lag ngay, chẳng nói chuyện được với bố mẹ gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_02','V602','小林',2,'是不是宿舍同时好几个人连WiFi，带宽被占满了？','shì bú shì sù shè tóng shí hǎo jǐ gè rén lián WiFi， dài kuān bèi zhàn mǎn le？','Có phải cùng lúc mấy người trong phòng đều nối WiFi nên băng thông bị chiếm hết không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_03','V602','阮明',3,'刚才隔壁宿舍也在刷视频，我切换手机流量试试还是卡嘛。','gāng cái gé bì sù shè yě zài shuā shì pín， wǒ qiè huàn shǒu jī liú liàng shì shì hái shì kǎ ma。','Lúc nãy phòng bên cạnh cũng đang xem video, tớ thử chuyển sang 4G rồi vẫn giật lag chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_04','V602','小林',4,'我教你断开自动连接的多余设备，路由器重启一下会流畅很多。','wǒ jiāo nǐ duàn kāi zì dòng lián jiē de duō yú shè bèi， lù yóu qì zhòng qǐ yī xià huì liú chàng hěn duō。','Để tớ chỉ cậu ngắt bớt mấy thiết bị tự động kết nối thừa, khởi động lại router là mượt hơn nhiều đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_05','V602','阮明',5,'重启路由器之后，跨国视频延迟能降低多少？','chóng qǐ lù yóu qì zhī hòu， kuà guó shì pín yán chí néng jiàng dī duō shǎo？','Khởi động lại router xong thì độ trễ gọi video xuyên quốc gia giảm được bao nhiêu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_06','V602','小林',6,'至少少一半卡顿，避开晚间八点上网高峰效果更好。','zhì shǎo shǎo yí bàn kǎ dùn， bì kāi wǎn jiān bā diǎn shàng wǎng gāo fēng xiào guǒ gèng hǎo。','Giảm ít nhất một nửa độ giật, tránh giờ cao điểm tầm tám giờ tối thì càng mượt hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L602_07','V602','阮明',7,'我现在跟着你的步骤操作，等下再打视频电话。','wǒ xiàn zài gēn zhe nǐ de bù zhòu cāo zuò， děng xià zài dǎ shì pín diàn huà。','Giờ tớ làm theo các bước cậu chỉ đây, lát nữa gọi video lại thử xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT603','SF1','时差冲突，错过和父母固定视频时间，重新约定时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V603','SIT603','P1','suon_se','tuy_y',NULL,'跨国跨时区留学生和家人一般会约定固定通话时间，临时无法上线必须提前留言报平安，避免家人过度担忧。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_01','V603','阮明',1,'昨天上课拖堂，错过了和爸妈约定的视频时间，他们一直等我。','zuó tiān shàng kè tuō táng， cuò guò le hé bà mā yuē dìng de shì pín shí jiān， tā men yì zhí děng wǒ。','Hôm qua lớp học kéo dài hơn dự kiến, tớ lỡ mất giờ video hẹn với bố mẹ, ông bà cứ chờ mãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_02','V603','苏雯',2,'越南和国内有一小时时差，你可以提前调整固定联络时段哦。','yuè nán hé guó nèi yǒu yī xiǎo shí shí chà， nǐ kě yǐ tí qián tiáo zhěng gù dìng lián luò shí duàn ó。','Việt Nam với trong nước lệch nhau một tiếng, cậu nên chủ động điều chỉnh trước khung giờ liên lạc cố định đó nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_03','V603','阮明',3,'我这边晚上七点，越南就是傍晚六点，这个时间他们刚好下班。','wǒ zhè biān wǎn shàng qī diǎn， yuè nán jiù shì bàng wǎn liù diǎn， zhè ge shí jiān tā men gāng hǎo xià bān。','Bên tớ bảy giờ tối thì bên Việt Nam là sáu giờ chiều, đúng lúc bố mẹ vừa tan làm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_04','V603','苏雯',4,'那你跟家里重新敲定这个时间，提前发消息提醒他们上线吧。','nà nǐ gēn jiā lǐ chóng xīn qiāo dìng zhè ge shí jiān， tí qián fā xiāo xī tí xǐng tā men shàng xiàn ba。','Vậy cậu chốt lại khung giờ này với nhà mình đi, rồi nhắn tin nhắc trước để họ lên mạng đúng giờ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_05','V603','阮明',5,'我昨天临时缺场，爸妈还以为我出了什么事，特别担心。','wǒ zuó tiān lín shí quē chǎng， bà mā hái yǐ wéi wǒ chū le shén me shì， tè bié dān xīn。','Hôm qua tớ tự dưng vắng mặt, bố mẹ cứ tưởng tớ gặp chuyện gì, lo lắng lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_06','V603','苏雯',6,'下次如果有课，提前发文字留言告知家人，免得他们焦虑。','xià cì rú guǒ yǒu kè， tí qián fā wén zì liú yán gào zhī jiā rén， miǎn de tā men jiāo lǜ。','Lần sau nếu có tiết học thì nhắn tin báo trước cho gia đình, kẻo họ lo lắng không cần thiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L603_07','V603','阮明',7,'我记下了，今晚提前跟家里敲定新的视频时段。','wǒ jì xià le， jīn wǎn tí qián gēn jiā lǐ qiāo dìng xīn de shì pín shí duàn。','Tớ ghi nhớ rồi, tối nay sẽ chốt lại giờ video mới với gia đình sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT604','SF1','软件登录失败、账号被锁，找同学帮忙找回账号',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V604','SIT604','P1','that_bai_nhe','tuy_y',NULL,'公共网络存在安全风险，跨国通讯软件检测到异地登录会自动锁号，保护用户隐私与账号安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_01','V604','阮明',1,'糟糕，我的视频软件账号提示异常登录，直接被系统锁住了。','zāo gāo， wǒ de shì pín ruǎn jiàn zhàng hào tí shì yì cháng dēng lù， zhí jiē bèi xì tǒng suǒ zhù le。','Chết rồi, tài khoản app video của tớ báo đăng nhập bất thường, bị hệ thống khóa luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_02','V604','小林',2,'你是不是切换手机、频繁换WiFi登录，系统判定有风险？','nǐ shì bú shì qiè huàn shǒu jī、 pín fán huàn WiFi dēng lù， xì tǒng pàn dìng yǒu fēng xiǎn？','Có phải cậu đổi điện thoại, đổi WiFi liên tục nên hệ thống nghi ngờ rủi ro không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_03','V604','阮明',3,'昨天去图书馆连公共网络登录过，之后回家就登不上去嘛。','zuó tiān qù tú shū guǎn lián gōng gòng wǎng luò dēng lù guò， zhī hòu huí jiā jiù dēng bù shàng qù ma。','Hôm qua tớ ra thư viện đăng nhập bằng mạng công cộng, xong về nhà là không vào được nữa chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_04','V604','小林',4,'解锁需要邮箱收验证链接，你注册时绑定的邮箱还能正常使用吗？','jiě suǒ xū yào yóu xiāng shōu yàn zhèng liàn jiē， nǐ zhù cè shí bǎng dìng de yóu xiāng hái néng zhèng cháng shǐ yòng ma？','Mở khóa cần nhận link xác nhận qua email, cái email cậu gắn lúc đăng ký còn dùng được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_05','V604','阮明',5,'邮箱密码我记混了，现在双重验证全部卡住没法操作。','yóu xiāng mì mǎ wǒ jì hùn le， xiàn zài shuāng chóng yàn zhèng quán bù kǎ zhù méi fǎ cāo zuò。','Tớ nhớ nhầm mật khẩu email rồi, giờ xác thực hai lớp bị kẹt luôn không thao tác được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_06','V604','小林',6,'只能先找回邮箱密码，才能解锁通讯软件账号，一步一步来。','zhǐ néng xiān zhǎo huí yóu xiāng mì mǎ， cái néng jiě suǒ tōng xùn ruǎn jiàn zhàng hào， yí bù yí bù lái。','Vậy chỉ còn cách lấy lại mật khẩu email trước, mới mở khóa được tài khoản app gọi video, từ từ làm từng bước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L604_07','V604','阮明',7,'麻烦你陪我操作，不然我今天完全联系不上家里人。','má fán nǐ péi wǒ cāo zuò， bù rán wǒ jīn tiān wán quán lián xì bù shàng jiā lǐ rén。','Phiền cậu ngồi làm cùng tớ với, không thì hôm nay tớ chịu, không liên lạc được với gia đình luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT605','SF1','不会操作美颜、屏幕共享，请教室友教自己给家人展示校园',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V605','SIT605','P1','suon_se','tuy_y',NULL,'国际视频软件自带基础美颜、屏幕共享功能，留学生常用来实时展示校园、宿舍生活给海外亲人。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_01','V605','阮明',1,'我想给爸妈看看校园风景，不知道怎么打开屏幕共享功能啊。','wǒ xiǎng gěi bà mā kàn kàn xiào yuán fēng jǐng， bù zhī dào zěn me dǎ kāi píng mù gòng xiǎng gōng néng a。','Tớ muốn cho bố mẹ xem cảnh trường, mà không biết mở tính năng chia sẻ màn hình kiểu gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_02','V605','小林',2,'视频通话界面下方有分享按钮，点一下就能同步实景画面呢。','shì pín tōng huà jiè miàn xià fāng yǒu fēn xiǎng àn niǔ， diǎn yī xià jiù néng tóng bù shí jǐng huà miàn ne。','Giao diện gọi video có nút chia sẻ ở phía dưới ấy, bấm vào là hình ảnh thực tế đồng bộ ngay.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_03','V605','阮明',3,'另外画面光线不好，有没有简单的美颜提亮功能？','lìng wài huà miàn guāng xiàn bù hǎo， yǒu méi yǒu jiǎn dān de měi yán tí liàng gōng néng？','Với lại ánh sáng trong hình không đẹp lắm, có tính năng làm đẹp làm sáng đơn giản nào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_04','V605','小林',4,'侧边工具栏有基础提亮滤镜，不用复杂调整，一键开启就行。','cè biān gōng jù lán yǒu jī chǔ tí liàng lǜ jìng， bù yòng fù zá tiáo zhěng， yī jiàn kāi qǐ jiù xíng。','Ở thanh công cụ bên cạnh có bộ lọc làm sáng cơ bản, không cần chỉnh phức tạp, bật một cái là xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_05','V605','阮明',5,'共享画面的时候，手机里的照片相册也能同步展示给家人吗？','gòng xiǎng huà miàn de shí hòu， shǒu jī lǐ de zhào piān xiàng cè yě néng tóng bù zhǎn shì gěi jiā rén ma？','Lúc chia sẻ màn hình vậy thì album ảnh trong điện thoại có đồng bộ hiện cho gia đình xem được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_06','V605','小林',6,'可以，共享时切换相册，宿舍、教学楼照片都能直接看。','kě yǐ， gòng xiǎng shí qiè huàn xiàng cè， sù shè、 jiào xué lóu zhào piān dōu néng zhí jiē kàn。','Được chứ, lúc chia sẻ chuyển sang album là ảnh ký túc xá, giảng đường gì cũng xem trực tiếp được hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L605_07','V605','阮明',7,'太实用了，今晚视频带爸妈逛一遍我们整个校园。','tài shí yòng le， jīn wǎn shì pín dài bà mā guàng yī biàn wǒ men zhěng gè xiào yuán。','Hay quá, tối nay tớ sẽ gọi video dẫn bố mẹ đi một vòng khắp trường luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT606','SF1','境外手机号收不到软件验证码，改用邮箱登录联系家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V606','SIT606','P1','twist','ban_chinh_thuc',NULL,'境内外运营商短信互通存在延迟、丢失问题，跨国软件优先推荐邮箱作为备用验证渠道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_01','V606','阮明',1,'我更换新手机，软件登录要验证码，越南手机号一直收不到短信。','wǒ gēng huàn xīn shǒu jī， ruǎn jiàn dēng lù yào yàn zhèng mǎ， yuè nán shǒu jī hào yì zhí shōu bú dào duǎn xìn。','Tôi đổi điện thoại mới, app yêu cầu nhập mã xác nhận để đăng nhập, mà số điện thoại Việt Nam mãi không nhận được tin nhắn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_02','V606','苏雯',2,'跨国短信运营商通道不稳定，境外号码接收验证码延迟很常见。','kuà guó duǎn xìn yùn yíng shāng tōng dào bù wěn dìng， jìng wài hào mǎ jiē shōu yàn zhèng mǎ yán chí hěn cháng jiàn。','Đường truyền tin nhắn xuyên quốc gia của nhà mạng không ổn định lắm, số nước ngoài nhận mã xác nhận bị trễ là chuyện thường thấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_03','V606','阮明',3,'那除了手机号验证，还有别的登录方式可以选择吗？','nà chú le shǒu jī hào yàn zhèng， hái yǒu bié de dēng lù fāng shì kě yǐ xuǎn zé ma？','Vậy ngoài xác thực bằng số điện thoại ra, còn cách đăng nhập nào khác để chọn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_04','V606','苏雯',4,'注册时绑定的电子邮箱是备用渠道，用邮件验证码就能登录哈。','zhù cè shí bǎng dìng de diàn zi yóu xiāng shì bèi yòng qú dào， yòng yóu jiàn yàn zhèng mǎ jiù néng dēng lù hā。','Email đã gắn lúc đăng ký là kênh dự phòng đấy, dùng mã xác nhận qua email là đăng nhập được luôn.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_05','V606','阮明',5,'我之前没留意邮箱验证功能，差点一整天没法联系父母。','wǒ zhī qián méi liú yì yóu xiāng yàn zhèng gōng néng， chà diǎn yī zhěng tiān méi fǎ lián xì fù mǔ。','Trước giờ tôi không để ý tính năng xác thực bằng email, suýt nữa cả ngày không liên lạc được với bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_06','V606','苏雯',6,'之后记得把邮箱设为主要验证方式，避免跨国短信失效。','zhī hòu jì de bǎ yóu xiāng shè wéi zhǔ yào yàn zhèng fāng shì， bì miǎn kuà guó duǎn xìn shī xiào。','Sau này nhớ đặt email làm phương thức xác thực chính, tránh trường hợp tin nhắn xuyên quốc gia bị lỗi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L606_07','V606','阮明',7,'我现在操作邮箱验证，登录之后第一时间给家里报平安。','wǒ xiàn zài cāo zuò yóu xiāng yàn zhèng， dēng lù zhī hòu dì yī shí jiān gěi jiā lǐ bào píng ān。','Giờ tôi thao tác xác thực email đây, đăng nhập xong là báo bình an cho gia đình ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT607','SF1','软件内存过大卡顿，清理缓存保证和家人稳定通话',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V607','SIT607','P1','suon_se','tuy_y',NULL,'长期使用通讯软件会产生大量缓存图片、视频碎片，占用手机内存，定期清理是国内年轻人通用的手机维护习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_01','V607','阮明',1,'这款视频软件存了很多聊天照片，手机越用越卡顿。','zhè kuǎn shì pín ruǎn jiàn cún le hěn duō liáo tiān zhào piān， shǒu jī yuè yòng yuè kǎ dùn。','App gọi video này lưu nhiều ảnh chat quá, điện thoại dùng càng lâu càng lag.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_02','V607','小林',2,'长期堆积缓存文件会拖慢运行速度，定期清理就流畅啦。','cháng qī duī jī huǎn cún wén jiàn huì tuō màn yùn xíng sù dù， dìng qī qīng lǐ jiù liú chàng la。','File cache tích lâu ngày sẽ làm máy chạy chậm đó, dọn dẹp định kỳ là mượt lại ngay.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_03','V607','阮明',3,'清理缓存会不会删掉我和家人之前保存的聊天照片？','qīng lǐ huǎn cún huì bú huì shān diào wǒ hé jiā rén zhī qián bǎo cún de liáo tiān zhào piān？','Dọn cache thì có xóa mất mấy tấm ảnh chat mình lưu với gia đình trước đó không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_04','V607','小林',4,'清理临时缓存不会删除相册原图，只会清除冗余临时数据呢。','qīng lǐ lín shí huǎn cún bú huì shān chú xiàng cè yuán tú， zhǐ huì qīng chú rǒng yú lín shí shù jù ne。','Dọn cache tạm thì không xóa ảnh gốc trong album đâu, chỉ xóa mấy dữ liệu tạm dư thừa thôi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_05','V607','阮明',5,'清理完缓存，跨国视频的延迟、卡顿问题会明显好转吗？','qīng lǐ wán huǎn cún， kuà guó shì pín de yán chí、 kǎ dùn wèn tí huì míng xiǎn hǎo zhuǎn ma？','Dọn cache xong thì gọi video xuyên quốc gia đỡ giật, đỡ trễ rõ rệt không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_06','V607','小林',6,'是的，手机存储空间充足，网络传输才不会被占用。','shì de， shǒu jī cún chǔ kōng jiān chōng zú， wǎng luò chuán shū cái bú huì bèi zhàn yòng。','Đúng vậy, bộ nhớ máy đủ trống thì đường truyền mạng mới không bị chiếm dụng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L607_07','V607','阮明',7,'我现在清理缓存，晚上跟家里长时间视频聊天。','wǒ xiàn zài qīng lǐ huǎn cún， wǎn shàng gēn jiā lǐ zhǎng shí jiān shì pín liáo tiān。','Để mình dọn cache ngay, tối nay gọi video lâu với gia đình cho thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT608','SF2','跟中国同学解释越南与国内时差，调整联系父母的时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V608','SIT608','P1','suon_se','tuy_y',NULL,'中国全境统一使用北京时间，无分时区；东南亚多国时区与中国存在1-2小时时差，留学生需要协调双方作息沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_01','V608','阮明',1,'很多同学不清楚，越南时间比北京时间慢一小时呢。','hěn duō tóng xué bù qīng chǔ， yuè nán shí jiān bǐ běi jīng shí jiān màn yī xiǎo shí ne。','Nhiều bạn cùng lớp không biết đâu, giờ Việt Nam chậm hơn giờ Bắc Kinh một tiếng đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_02','V608','苏雯',2,'难怪你总是傍晚才跟家里打电话，原来是时差错开了作息。','nán guài nǐ zǒng shì bàng wǎn cái gēn jiā lǐ dǎ diàn huà， yuán lái shì shí chà cuò kāi le zuò xī。','Thảo nào cậu toàn gọi điện về nhà lúc chiều tối, hóa ra là do lệch múi giờ với lịch sinh hoạt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_03','V608','阮明',3,'国内晚上八点，越南才七点，爸妈刚下班有空跟我聊天。','guó nèi wǎn shàng bā diǎn， yuè nán cái qī diǎn， bà mā gāng xià bān yǒu kòng gēn wǒ liáo tiān。','Ở Trung Quốc 8 giờ tối thì bên Việt Nam mới 7 giờ, bố mẹ mình vừa tan làm nên có thời gian nói chuyện với mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_04','V608','苏雯',4,'要是你晚上有晚自习，只能白天课间发文字消息联系家里？','yào shì nǐ wǎn shàng yǒu wǎn zì xí， zhǐ néng bái tiān kè jiān fā wén zì xiāo xī lián xì jiā lǐ？','Vậy tối nào cậu có tự học thì chỉ nhắn tin lúc giờ ra chơi ban ngày để liên lạc với nhà thôi à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_05','V608','阮明',5,'对，白天我这边下午，越南中午，他们午休能看消息。','duì， bái tiān wǒ zhè biān xià wǔ， yuè nán zhōng wǔ， tā men wǔ xiū néng kàn xiāo xī。','Ừ, ban ngày bên mình là buổi chiều, bên Việt Nam là buổi trưa, lúc đó bố mẹ nghỉ trưa nên xem tin nhắn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_06','V608','苏雯',6,'时差错开确实不方便，固定时段联系家人会省心很多。','shí chà cuò kāi què shí bù fāng biàn， gù dìng shí duàn lián xì jiā rén huì shěng xīn hěn duō。','Lệch múi giờ đúng là bất tiện thật, cố định khung giờ liên lạc với gia đình sẽ nhàn hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L608_07','V608','阮明',7,'我已经把通话时间标注在备忘录，不会再错过。','wǒ yǐ jīng bǎ tōng huà shí jiān biāo zhù zài bèi wàng lù， bú huì zài cuò guò。','Mình ghi giờ gọi điện vào ghi chú rồi, sẽ không bị quên nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT609','SF2','生病不舒服，视频隐瞒病情，怕远方家人担心',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V609','SIT609','P1','twist','ban_chinh_thuc',NULL,'在外留学生生病时大多会下意识向家人隐瞒严重不适，不想让远方亲人担忧，是十分普遍的心理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_01','V609','阮明',1,'我发烧头晕，等下跟爸妈视频，不想让他们看出我不舒服。','wǒ fā shāo tóu yūn， děng xià gēn bà mā shì pín， bù xiǎng ràng tā men kàn chū wǒ bù shū fú。','Mình đang sốt và hơi choáng đầu, lát nữa gọi video cho bố mẹ, mình không muốn để họ nhận ra mình đang khó chịu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_02','V609','小林',2,'你脸色很苍白，视频一开家人一眼就能察觉到不对劲嘛。','nǐ liǎn sè hěn cāng bái， shì pín yī kāi jiā rén yī yǎn jiù néng chá jué dào bú duì jìn ma。','Mặt cậu tái nhợt thế này, vừa mở video là gia đình nhận ra ngay có gì không ổn đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_03','V609','阮明',3,'他们离这么远，没办法过来照顾我，知道我生病只会干着急。','tā men lí zhè me yuǎn， méi bàn fǎ guò lái zhào gù wǒ， zhī dào wǒ shēng bìng zhǐ huì gān zháo jí。','Bố mẹ ở xa vậy, không thể qua chăm sóc mình được, biết mình bệnh thì chỉ càng thêm lo lắng vô ích thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_04','V609','小林',4,'那你可以只发文字简单提一句轻微感冒，不用隐瞒全部情况。','nà nǐ kě yǐ zhǐ fā wén zì jiǎn dān tí yī jù qīng wēi gǎn mào， bù yòng yǐn mán quán bù qíng kuàng。','Vậy cậu có thể chỉ nhắn vài chữ nói là bị cảm nhẹ thôi, không cần giấu hết mọi chuyện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_05','V609','阮明',5,'我想等完全康复再细说，现在只说一切正常就好。','wǒ xiǎng děng wán quán kāng fù zài xì shuō， xiàn zài zhǐ shuō yī qiè zhèng cháng jiù hǎo。','Mình muốn đợi khỏi hẳn rồi mới kể chi tiết, giờ chỉ cần nói mọi thứ vẫn ổn là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_06','V609','小林',6,'但如果病情加重没人陪同，家人不知情反而更危险。','dàn rú guǒ bìng qíng jiā zhòng méi rén péi tóng， jiā rén bù zhī qíng fǎn ér gèng wēi xiǎn。','Nhưng nếu bệnh trở nặng mà không có ai bên cạnh, gia đình không biết thì lại càng nguy hiểm hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L609_07','V609','阮明',7,'我会控制视频时长，尽量不提身体难受的地方。','wǒ huì kòng zhì shì pín shí cháng， jǐn liàng bù tí shēn tǐ nán shòu de dì fāng。','Mình sẽ hạn chế thời gian gọi video, cố gắng không nhắc đến chỗ nào khó chịu trong người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT610','SF2','期末备考压力大，和家人倾诉焦虑，家人远程安抚',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V610','SIT610','P1','suon_se','ban_chinh_thuc',NULL,'国内家庭普遍重视学业，但父母更在意子女身心健康，子女倾诉学习压力时，家人优先安抚情绪而非一味要求成绩。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_01','V610','阮明',1,'妈，期末要考四门专业课，每天复习到凌晨，压力好大啊。','mā， qī mò yào kǎo sì mén zhuān yè kè， měi tiān fù xí dào líng chén， yā lì hǎo dà a。','Mẹ ơi, cuối kỳ con phải thi bốn môn chuyên ngành, ngày nào cũng ôn tới tận khuya, áp lực lớn quá.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_02','V610','母亲',2,'不用逼自己太紧，劳逸结合，身体比成绩重要呢。','bù yòng bī zì jǐ tài jǐn， láo yì jié hé， shēn tǐ bǐ chéng jì zhòng yào ne。','Con đừng ép mình quá sức, học kết hợp nghỉ ngơi cho hợp lý, sức khỏe quan trọng hơn điểm số nhiều.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_03','V610','阮明',3,'汉语写作难度很高，我怕期末分数太低影响签证续签。','hàn yǔ xiě zuò nán dù hěn gāo， wǒ pà qī mò fēn shù tài dī yǐng xiǎng qiān zhèng xù qiān。','Môn viết tiếng Trung khó lắm, con sợ điểm cuối kỳ thấp quá sẽ ảnh hưởng đến việc gia hạn visa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_04','V610','母亲',4,'尽力就好，我们不会要求你必须考高分，放平心态吧。','jìn lì jiù hǎo， wǒ men bú huì yāo qiú nǐ bì xū kǎo gāo fēn， fàng píng xīn tài ba。','Con cố gắng hết sức là được rồi, bố mẹ không bắt con phải đạt điểm cao đâu, cứ giữ tâm lý thoải mái nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_05','V610','阮明',5,'身边同学进度都很快，我总担心自己跟不上大家。','shēn biān tóng xué jìn dù dōu hěn kuài， wǒ zǒng dān xīn zì jǐ gēn bù shàng dà jiā。','Các bạn xung quanh học tiến độ nhanh lắm, con cứ lo mình theo không kịp mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_06','V610','母亲',6,'每天抽空休息半小时，有空多跟我们聊聊，释放压力。','měi tiān chōu kòng xiū xī bàn xiǎo shí， yǒu kòng duō gēn wǒ men liáo liáo， shì fàng yā lì。','Mỗi ngày con dành ra nửa tiếng để nghỉ ngơi, rảnh thì gọi nói chuyện nhiều với bố mẹ cho bớt căng thẳng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L610_07','V610','阮明',7,'听完您说的话，心里轻松不少，谢谢妈妈安慰我。','tīng wán nín shuō de huà， xīn lǐ qīng sōng bù shǎo， xiè xiè mā mā ān wèi wǒ。','Nghe mẹ nói xong con thấy nhẹ lòng hẳn, cảm ơn mẹ đã an ủi con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT611','SF2','忘记每日给父母报平安，家人连续多天联系不上十分着急',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V611','SIT611','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生在外，国内家人习惯每日收到平安消息，多日失联极易引发家人恐慌，甚至直接联系学校老师求助。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_01','V611','阮明',1,'辅导员，我连续三天忙于备考，忘了给爸妈发消息报平安。','fǔ dǎo yuán， wǒ lián xù sān tiān máng yú bèi kǎo， wàng le gěi bà mā fā xiāo xī bào píng ān。','Thầy/cô cố vấn ơi, em bận ôn thi liên tục ba ngày nên quên nhắn tin báo bình an cho bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_02','V611','辅导员',2,'你母亲昨天打电话到学院，一直联系不上你，特别慌乱。','nǐ mǔ qīn zuó tiān dǎ diàn huà dào xué yuàn， yì zhí lián xì bù shàng nǐ， tè bié huāng luàn。','Hôm qua mẹ em gọi điện đến trường, liên lạc mãi không được với em, bà lo lắng dữ lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_03','V611','阮明',3,'我以为不回复一两天没关系，没想到家人会这么担心。','wǒ yǐ wéi bù huí fù yī liǎng tiān méi guān xì， méi xiǎng dào jiā rén huì zhè me dān xīn。','Em tưởng không trả lời một hai ngày cũng không sao, không ngờ gia đình lại lo lắng đến vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_04','V611','辅导员',4,'境外子女长期失联，父母很容易往危险的方向联想嘛。','jìng wài zǐ nǚ cháng qī shī lián， fù mǔ hěn róng yì wǎng wēi xiǎn de fāng xiàng lián xiǎng ma。','Con cái ở nước ngoài mà mất liên lạc lâu ngày thì bố mẹ rất dễ nghĩ theo hướng xấu đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_05','V611','阮明',5,'我现在立刻打视频电话，好好跟家里解释这几天的情况。','wǒ xiàn zài lì kè dǎ shì pín diàn huà， hǎo hǎo gēn jiā lǐ jiě shì zhè jǐ tiān de qíng kuàng。','Em sẽ gọi video ngay bây giờ, giải thích rõ ràng với gia đình về tình hình mấy ngày qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_06','V611','辅导员',6,'之后再忙也要抽一分钟发一句简短文字，让家人放心。','zhī hòu zài máng yě yào chōu yì fēn zhōng fā yī jù jiǎn duǎn wén zì， ràng jiā rén fàng xīn。','Sau này dù bận đến đâu cũng phải dành ra một phút nhắn vài chữ ngắn gọn, để gia đình yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L611_07','V611','阮明',7,'我记住教训，以后每天固定简单留言报平安。','wǒ jì zhù jiào xùn， yǐ hòu měi tiān gù dìng jiǎn dān liú yán bào píng ān。','Em sẽ ghi nhớ bài học này, từ nay ngày nào cũng nhắn vài dòng báo bình an cố định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT612','SF2','学校放长假规划出行，提前和父母商量行程并实时分享定位',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V612','SIT612','P1','suon_se','tuy_y',NULL,'子女独自外出旅行，中国父母普遍要求实时分享定位、每日报备行程，优先关注出行安全。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_01','V612','阮明',1,'妈，寒假我打算和同学去周边城市短途旅行，跟您商量一下。','mā， hán jià wǒ dǎ suàn hé tóng xué qù zhōu biān chéng shì duǎn tú lǚ xíng， gēn nín shāng liáng yī xià。','Mẹ ơi, kỳ nghỉ đông con định cùng bạn bè đi du lịch ngắn ngày mấy thành phố gần đây, con muốn bàn với mẹ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_02','V612','母亲',2,'路途远不远，住宿安全吗，出门一定要实时共享定位给我们哦。','lù tú yuǎn bù yuǎn， zhù sù ān quán ma， chū mén yí dìng yào shí shí gòng xiǎng dìng wèi gěi wǒ men ó。','Đường đi có xa không, chỗ ở có an toàn không, ra ngoài nhớ chia sẻ định vị thời gian thực cho bố mẹ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_03','V612','阮明',3,'全程高铁出行，住正规连锁酒店，每天晚上同步行程定位。','quán chéng gāo tiě chū xíng， zhù zhèng guī lián suǒ jiǔ diàn， měi tiān wǎn shàng tóng bù xíng chéng dìng wèi。','Cả chuyến đi con toàn đi tàu cao tốc, ở khách sạn chuỗi uy tín, tối nào con cũng cập nhật lịch trình và định vị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_04','V612','母亲',4,'每天晚上十点前发消息，告诉我们当天去了哪些地方吧。','měi tiān wǎn shàng shí diǎn qián fā xiāo xī， gào sù wǒ men dàng tiān qù le nǎ xiē dì fāng ba。','Mỗi tối trước 10 giờ con nhắn tin kể cho bố mẹ biết hôm đó đi những đâu nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_05','V612','阮明',5,'我每到一个景点都拍照片发给家里，不让你们担心。','wǒ měi dào yí gè jǐng diǎn dōu pāi zhào piān fā gěi jiā lǐ， bù ràng nǐ men dān xīn。','Mỗi khi đến điểm nào con cũng chụp ảnh gửi về nhà, để bố mẹ không phải lo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_06','V612','母亲',6,'在外结伴出行，不要单独去偏僻人少的地方。','zài wài jié bàn chū xíng， bú yào dān dú qù piān pì rén shǎo de dì fāng。','Ra ngoài phải đi cùng bạn bè, đừng một mình đến những chỗ vắng vẻ, ít người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L612_07','V612','阮明',7,'我会牢记您的叮嘱，出行全程和同学结伴行动。','wǒ huì láo jì nín de dīng zhǔ， chū xíng quán chéng hé tóng xué jié bàn xíng dòng。','Con sẽ ghi nhớ lời mẹ dặn, suốt chuyến đi con sẽ đi cùng bạn bè, không tách nhóm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT613','SF2','深夜在图书馆自习，怕打扰家人休息只发文字消息不打视频',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V613','SIT613','P1','suon_se','tuy_y',NULL,'国人普遍重视夜间休息，深夜语音、视频通话会被视作打扰他人，非紧急情况只用文字留言沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_01','V613','阮明',1,'现在国内已经深夜十一点，我不敢发起视频打扰爸妈休息。','xiàn zài guó nèi yǐ jīng shēn yè shí yì diǎn， wǒ bù gǎn fā qǐ shì pín dǎ rǎo bà mā xiū xī。','Giờ ở nhà đã 11 giờ đêm rồi, mình không dám gọi video sợ làm phiền giấc ngủ của bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_02','V613','苏雯',2,'时差叠加熬夜，一通视频会直接打断他们睡眠呢。','shí chà dié jiā áo yè， yí tòng shì pín huì zhí jiē dǎ duàn tā men shuì mián ne。','Lệch múi giờ với việc thức khuya cộng lại, một cuộc gọi video là cắt ngang giấc ngủ của họ luôn đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_03','V613','阮明',3,'我简单发一段文字，说明我在图书馆自习，一切平安。','wǒ jiǎn dān fā yī duàn wén zì， shuō míng wǒ zài tú shū guǎn zì xí， yī qiè píng ān。','Mình nhắn vài dòng đơn giản, báo là mình đang tự học ở thư viện, mọi thứ vẫn bình an.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_04','V613','苏雯',4,'文字留言他们明天一早醒来就能看到，不会被深夜来电惊扰。','wén zì liú yán tā men míng tiān yī zǎo xǐng lái jiù néng kàn dào， bú huì bèi shēn yè lái diàn jīng rǎo。','Tin nhắn thì sáng mai họ thức dậy là thấy ngay, khỏi bị cuộc gọi lúc nửa đêm làm giật mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_05','V613','阮明',5,'要是遇到急事，才会选择打电话联系家里。','yào shì yù dào jí shì， cái huì xuǎn zé dǎ diàn huà lián xì jiā lǐ。','Chỉ khi nào có việc gấp mình mới gọi điện về nhà thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_06','V613','苏雯',6,'这样体贴家人作息，长辈心里也会觉得你懂事贴心。','zhè yàng tǐ tiē jiā rén zuò xī， zhǎng bèi xīn lǐ yě huì jué de nǐ dǒng shì tiē xīn。','Cậu biết nghĩ cho lịch sinh hoạt của gia đình như vậy, bố mẹ chắc cũng thấy cậu hiểu chuyện, chu đáo lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L613_07','V613','阮明',7,'嗯，我简单编辑平安消息发送给父母。','ń， wǒ jiǎn dān biān jí píng ān xiāo xī fā sòng gěi fù mǔ。','Ừ, để mình soạn vài dòng tin nhắn báo bình an gửi cho bố mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT614','SF3','生活费不足，委婉跟父母说明开销，协商每月转账额度',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V614','SIT614','P1','suon_se','ban_chinh_thuc',NULL,'子女向家长说明生活费不足时，多委婉说明开销用途，家长一般会适度上调生活费，同时叮嘱合理消费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_01','V614','阮明',1,'爸，最近物价小幅上涨，食堂、生活用品开销比之前多一些。','bà， zuì jìn wù jià xiǎo fú shàng zhǎng， shí táng、 shēng huó yòng pǐn kāi xiāo bǐ zhī qián duō yī xiē。','Bố ơi, dạo này giá cả tăng nhẹ, tiền ăn ở căng tin với đồ dùng sinh hoạt tốn hơn trước một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_02','V614','父亲',2,'每月给你的生活费不够支撑日常开销了是吗？','měi yuè gěi nǐ de shēng huó fèi bù gòu zhī chēng rì cháng kāi xiāo le shì ma？','Ý con là tiền sinh hoạt bố mẹ gửi mỗi tháng không đủ trang trải chi tiêu hàng ngày nữa phải không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_03','V614','阮明',3,'除去吃饭、水电，还要买汉语教材，手头经常月底紧张呢。','chú qù chī fàn、 shuǐ diàn， hái yào mǎi hàn yǔ jiào cái， shǒu tóu jīng cháng yuè dǐ jǐn zhāng ne。','Trừ tiền ăn, tiền điện nước ra, con còn phải mua giáo trình tiếng Trung nữa, nên cuối tháng con hay bị hụt tiền.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_04','V614','父亲',4,'那我们每个月上调一部分汇款额度，保证你不用拮据生活。','nà wǒ men měi gè yuè shàng diào yī bù fèn huì kuǎn é dù， bǎo zhèng nǐ bù yòng jié jū shēng huó。','Vậy bố mẹ sẽ tăng thêm một phần tiền chuyển khoản hàng tháng, để con không phải sống chật vật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_05','V614','阮明',5,'我也会减少不必要的网购，合理控制日常消费。','wǒ yě huì jiǎn shǎo bù bì yào de wǎng gòu， hé lǐ kòng zhì rì cháng xiāo fèi。','Con cũng sẽ giảm bớt mua sắm online không cần thiết, chi tiêu hàng ngày sẽ hợp lý hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_06','V614','父亲',6,'不用太节俭，该花的学习、生活开支不用省。','bù yòng tài jié jiǎn， gāi huā de xué xí、 shēng huó kāi zhī bù yòng shěng。','Con không cần tiết kiệm quá đâu, khoản nào cần cho việc học và sinh hoạt thì cứ chi, không phải dè sẻn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L614_07','V614','阮明',7,'谢谢您体谅，我会做好消费规划，不乱花钱。','xiè xiè nín tǐ liàng， wǒ huì zuò hǎo xiāo fèi guī huà， bù luàn huā qián。','Cảm ơn bố đã thông cảm, con sẽ lên kế hoạch chi tiêu cẩn thận, không tiêu xài linh tinh đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT615','SF3','家人不会操作跨境汇款软件，一步步远程指导父母操作',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V615','SIT615','P1','twist','tuy_y',NULL,'中老年境外亲属不熟悉国内银行跨境汇款线上系统，留学生常通过屏幕共享远程手把手指导操作，避免操作失误转错账户。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_01','V615','阮明',1,'妈，跨境汇款手机软件操作不难，我开屏幕共享一步步教您。','mā， kuà jìng huì kuǎn shǒu jī ruǎn jiàn cāo zuò bù nán， wǒ kāi píng mù gòng xiǎng yí bù bù jiào nín。','Mẹ ơi, thao tác chuyển tiền xuyên biên giới trên điện thoại không khó đâu, con mở chia sẻ màn hình chỉ từng bước cho mẹ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_02','V615','母亲',2,'页面全是外文，我看不懂按钮，怕点错造成资金损失啊。','yè miàn quán shì wài wén， wǒ kàn bù dǒng àn niǔ， pà diǎn cuò zào chéng zī jīn sǔn shī a。','Giao diện toàn chữ nước ngoài, mẹ chẳng hiểu nút nào ra nút nào, sợ bấm nhầm mất tiền lắm.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_03','V615','阮明',3,'我指给您看汇款、收款人信息输入的固定位置，不用点其他按钮嘛。','wǒ zhǐ gěi nín kàn huì kuǎn、 shōu kuǎn rén xìn xī shū rù de gù dìng wèi zhì， bù yòng diǎn qí tā àn niǔ ma。','Con chỉ mẹ đúng chỗ nhập thông tin chuyển khoản với người nhận thôi, không cần đụng vào nút khác đâu mẹ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_04','V615','母亲',4,'输入我的护照号码的时候，字母大小写需要严格区分吗？','shū rù wǒ de hù zhào hào mǎ de shí hòu， zì mǔ dà xiǎo xiě xū yào yán gé qū fēn ma？','Lúc nhập số hộ chiếu của mẹ, chữ hoa chữ thường có cần phân biệt nghiêm ngặt không con?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_05','V615','阮明',5,'系统不区分大小写，但是姓名拼音必须和护照完全一致。','xì tǒng bù qū fēn dà xiǎo xiě， dàn shì xìng míng pīn yīn bì xū hé hù zhào wán quán yí zhì。','Hệ thống không phân biệt hoa thường đâu mẹ, nhưng tên phiên âm phải khớp y hệt với hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_06','V615','母亲',6,'我操作到一半跳转验证页面，不知道怎么填写信息。','wǒ cāo zuò dào yí bàn tiào zhuǎn yàn zhèng yè miàn， bù zhī dào zěn me tián xiě xìn xī。','Mẹ đang làm nửa chừng thì nó nhảy sang trang xác minh, không biết điền thông tin sao nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L615_07','V615','阮明',7,'您别退出页面，我放慢语速，逐项告诉你怎么填写。','nín bié tuì chū yè miàn， wǒ fàng màn yǔ sù， zhú xiàng gào sù nǐ zěn me tián xiě。','Mẹ đừng thoát trang nhé, con nói chậm lại, chỉ từng mục một cho mẹ điền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT616','SF3','转账手续费过高，和家人商量换更划算的汇款渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V616','SIT616','P1','suon_se','ban_chinh_thuc',NULL,'不同跨境汇款渠道手续费标准差异大，大额资金线下银行电汇性价比更高，小额线上便捷但手续费占比更高。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_01','V616','阮明',1,'之前用的汇款渠道手续费比例很高，一笔钱扣不少手续费呢。','zhī qián yòng de huì kuǎn qú dào shǒu xù fèi bǐ lì hěn gāo， yī bǐ qián kòu bù shǎo shǒu xù fèi ne。','Kênh chuyển tiền trước giờ mình dùng phí cao quá, mỗi lần chuyển bị trừ khá nhiều phí.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_02','V616','父亲',2,'那有没有手续费更低、到账速度稳定的跨境汇款方式？','nà yǒu méi yǒu shǒu xù fèi gèng dī、 dào zhàng sù dù wěn dìng de kuà jìng huì kuǎn fāng shì？','Vậy có cách chuyển tiền xuyên biên giới nào phí thấp hơn mà tiền vào ổn định không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_03','V616','阮明',3,'银行线下柜台跨境电汇手续费固定，大额汇款会划算很多。','yín háng xiàn xià guì tái kuà jìng diàn huì shǒu xù fèi gù dìng， dà é huì kuǎn huì huá suàn hěn duō。','Chuyển khoản quốc tế trực tiếp tại quầy ngân hàng thì phí cố định, chuyển số tiền lớn sẽ lợi hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_04','V616','父亲',4,'下次大额生活费，我直接去线下银行柜台办理汇款吧。','xià cì dà é shēng huó fèi， wǒ zhí jiē qù xiàn xià yín háng guì tái bàn lǐ huì kuǎn ba。','Vậy lần tới chuyển sinh hoạt phí số tiền lớn, bố sẽ ra thẳng quầy ngân hàng để làm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_05','V616','阮明',5,'小额日常零花钱可以线上软件，大额走线下银行渠道。','xiǎo é rì cháng líng huā qián kě yǐ xiàn shàng ruǎn jiàn， dà é zǒu xiàn xià yín háng qú dào。','Tiền tiêu vặt hằng ngày ít thì dùng app online được, còn số tiền lớn thì đi qua kênh ngân hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_06','V616','父亲',6,'两种渠道分开使用，能省下不少手续费长期积累。','liǎng zhǒng qú dào fēn kāi shǐ yòng， néng shěng xià bù shǎo shǒu xù fèi cháng qī jī lěi。','Tách riêng hai kênh như vậy dùng, về lâu dài cũng tiết kiệm được kha khá phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L616_07','V616','阮明',7,'好，我们分开渠道汇款，减少不必要的手续费损耗。','hǎo， wǒ men fēn kāi qú dào huì kuǎn， jiǎn shǎo bù bì yào de shǒu xù fèi sǔn hào。','Vâng, mình tách riêng kênh chuyển tiền, giảm bớt phần phí không cần thiết đi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT617','SF3','银行卡接收境外汇款被银行拦截，第一时间电话告知父母',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V617','SIT617','P1','twist','chinh_thuc',NULL,'国内银行对大额境外汇款有资金来源核查机制，留学生生活费汇款需携带护照线下申报，防止跨境资金违规流动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_01','V617','阮明',1,'爸，您刚刚汇过来的生活费，被银行系统临时拦截了。','bà， nín gāng gāng huì guò lái de shēng huó fèi， bèi yín háng xì tǒng lín shí lán jié le。','Bố ơi, khoản sinh hoạt phí bố vừa chuyển bị hệ thống ngân hàng tạm giữ lại rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_02','V617','父亲',2,'怎么会拦截正常留学生生活费，是不是信息填写出错？','zěn me huì lán jié zhèng cháng liú xué shēng shēng huó fèi， shì bú shì xìn xī tián xiě chū cuò？','Sao lại giữ tiền sinh hoạt bình thường của du học sinh được, hay là điền sai thông tin gì rồi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_03','V617','阮明',3,'银行需要我携带护照去柜台申报资金来源，才能入账嘛。','yín háng xū yào wǒ xié dài hù zhào qù guì tái shēn bào zī jīn lái yuán， cái néng rù zhàng ma。','Ngân hàng yêu cầu con mang hộ chiếu ra quầy khai báo nguồn tiền thì mới vào tài khoản được ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_04','V617','父亲',4,'那这笔资金会原路退回我的账户，还是暂时冻结等待申报？','nà zhè bǐ zī jīn huì yuán lù tuì huí wǒ de zhàng hù， hái shì zàn shí dòng jié děng dài shēn bào？','Vậy số tiền đó sẽ hoàn về tài khoản của bố, hay là tạm đóng băng chờ khai báo?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_05','V617','阮明',5,'资金暂时冻结，今天办完申报手续，明天就能正常入账。','zī jīn zàn shí dòng jié， jīn tiān bàn wán shēn bào shǒu xù， míng tiān jiù néng zhèng cháng rù zhàng。','Tiền đang bị tạm đóng băng ạ, hôm nay con làm xong thủ tục khai báo thì ngày mai sẽ vào tài khoản bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_06','V617','父亲',6,'我这边暂时不再追加汇款，等你确认资金到账再说。','wǒ zhè biān zàn shí bù zài zhuī jiā huì kuǎn， děng nǐ què rèn zī jīn dào zhàng zài shuō。','Bên này bố tạm thời chưa chuyển thêm nữa, đợi con xác nhận tiền vào rồi tính tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L617_07','V617','阮明',7,'我办完银行手续第一时间给您回电话告知结果。','wǒ bàn wán yín háng shǒu xù dì yī shí jiān gěi nín huí diàn huà gào zhī jié guǒ。','Con làm xong thủ tục ngân hàng sẽ gọi điện báo kết quả cho bố ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT618','SF3','想买电子产品，和家人沟通预算，协商分期添置',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V618','SIT618','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内家庭购置大额电子产品会综合考量子女备用资金，优先留存应急生活费，再规划数码产品采购预算。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_01','V618','阮明',1,'我旧手机卡顿严重，想更换一台新手机用于上课录课件。','wǒ jiù shǒu jī kǎ dùn yán zhòng， xiǎng gēng huàn yī tái xīn shǒu jī yòng yú shàng kè lù kè jiàn。','Điện thoại cũ của con giật lag nặng quá rồi, con muốn đổi cái mới để lên lớp quay bài giảng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_02','V618','母亲',2,'新款机型总价偏高，一次性拿出全部资金压力比较大。','xīn kuǎn jī xíng zǒng jià piān gāo， yí cì xìng ná chū quán bù zī jīn yā lì bǐ jiào dà。','Mẫu máy mới giá hơi cao, bỏ ra hết một lần thì áp lực tài chính khá lớn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_03','V618','阮明',3,'我平时兼职有少量收入，可以自己承担一半购机费用。','wǒ píng shí jiān zhí yǒu shǎo liàng shōu rù， kě yǐ zì jǐ chéng dān yí bàn gòu jī fèi yòng。','Con đi làm thêm cũng có chút thu nhập, con có thể tự lo một nửa tiền mua máy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_04','V618','父亲',4,'兼职收入要留存作应急备用金，不能全部拿来买电子产品嘛。','jiān zhí shōu rù yào liú cún zuò yìng jí bèi yòng jīn， bù néng quán bù ná lái mǎi diàn zi chǎn pǐn ma。','Tiền làm thêm nên giữ lại làm quỹ dự phòng khẩn cấp, không thể dồn hết vào mua đồ điện tử đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_05','V618','阮明',5,'那我们分两个月，分两次凑齐预算购置手机可以吗？','nà wǒ men fēn liǎng gè yuè， fēn liǎng cì còu qí yù suàn gòu zhì shǒu jī kě yǐ ma？','Vậy mình chia làm hai tháng, góp hai lần đủ tiền rồi mua máy được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_06','V618','母亲',6,'可以，先预留应急生活费，剩余资金再安排购置设备。','kě yǐ， xiān yù liú yìng jí shēng huó fèi， shèng yú zī jīn zài ān pái gòu zhì shè bèi。','Được, cứ để dành sinh hoạt phí khẩn cấp trước, tiền còn lại thì tính chuyện mua thiết bị sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L618_07','V618','阮明',7,'我理解家里的顾虑，不急于一次性换新手机。','wǒ lǐ jiě jiā lǐ de gù lǜ， bù jí yú yí cì xìng huàn xīn shǒu jī。','Con hiểu những băn khoăn của nhà mình, con không vội đổi máy mới ngay đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT619','SF4','中国传统节日，拍校园节日活动视频发给父母讲解习俗',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V619','SIT619','P1','suon_se','tuy_y',NULL,'中秋、春节是中国人核心团圆节日，留学生常会拍摄校园节日活动分享给海外家人，对比两国民俗差异。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_01','V619','阮明',1,'妈，今天校园举办中秋晚会，我拍一段视频发给您看看。','mā， jīn tiān xiào yuán jǔ bàn zhōng qiū wǎn huì， wǒ pāi yī duàn shì pín fā gěi nín kàn kàn。','Mẹ ơi, hôm nay trường tổ chức lễ hội Trung thu, con quay một đoạn video gửi mẹ xem nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_02','V619','母亲',2,'画面里大家都在吃月饼、赏月，这就是中国中秋习俗对吧？','huà miàn lǐ dà jiā dōu zài chī yuè bǐng、 shǎng yuè， zhè jiù shì zhōng guó zhōng qiū xí sú duì ba？','Trong hình ai cũng đang ăn bánh trung thu, ngắm trăng, đây là phong tục Trung thu của Trung Quốc đúng không con?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_03','V619','阮明',3,'没错，中秋代表团圆，家家户户都会吃月饼、家人相聚呢。','méi cuò， zhōng qiū dài biǎo tuán yuán， jiā jiā hù hù dōu huì chī yuè bǐng、 jiā rén xiāng jù ne。','Đúng rồi mẹ, Trung thu tượng trưng cho đoàn viên, nhà nào cũng ăn bánh trung thu, người thân quây quần bên nhau đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_04','V619','母亲',4,'越南也有类似团圆节日，只是美食和庆祝方式不一样。','yuè nán yě yǒu lèi sì tuán yuán jié rì， zhǐ shì měi shí hé qìng zhù fāng shì bù yí yàng。','Việt Nam mình cũng có ngày lễ đoàn viên tương tự, chỉ khác món ăn với cách tổ chức thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_05','V619','阮明',5,'我今晚分到一块月饼，等下拍照发给您看看样式。','wǒ jīn wǎn fēn dào yī kuài yuè bǐng， děng xià pāi zhào fā gěi nín kàn kàn yàng shì。','Tối nay con được chia một miếng bánh trung thu, lát nữa con chụp ảnh gửi mẹ xem hình dáng thế nào nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_06','V619','母亲',6,'身在异国也能体验他国节日，多感受不同文化挺好。','shēn zài yì guó yě néng tǐ yàn tā guó jié rì， duō gǎn shòu bù tóng wén huà tǐng hǎo。','Ở nước ngoài mà cũng được trải nghiệm lễ hội của người ta, cảm nhận thêm văn hóa khác vậy cũng hay đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L619_07','V619','阮明',7,'之后过春节、端午，我都拍校园活动分享给家里。','zhī hòu guò chūn jié、 duān wǔ， wǒ dōu pāi xiào yuán huó dòng fēn xiǎng gěi jiā lǐ。','Sau này đến Tết, Tết Đoan Ngọ, con cũng sẽ quay hoạt động ở trường gửi về cho nhà xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT620','SF4','越南传统节日无法回国，视频和家里亲友线上过节',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V620','SIT620','P1','suon_se','tuy_y',NULL,'跨国留学生无法回国过节时，全家会集体视频连线线上团圆，弥补不能线下相聚的遗憾。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_01','V620','阮明',1,'各位长辈，今年节日我没法回国，只能线上和大家一起过节啦。','gè wèi zhǎng bèi， jīn nián jié rì wǒ méi fǎ huí guó， zhǐ néng xiàn shàng hé dà jiā yì qǐ guò jié la。','Mọi người ơi, năm nay con không về nước ăn Tết được, chỉ có thể ăn Tết online cùng cả nhà thôi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_02','V620','亲戚长辈',2,'我们准备了节日特色饭菜，屏幕这边分一份给你看看。','wǒ men zhǔn bèi le jié rì tè sè fàn cài， píng mù zhè biān fēn yī fèn gěi nǐ kàn kàn。','Chúng ta chuẩn bị mấy món đặc trưng ngày Tết rồi, để bên này chia cho con xem qua màn hình nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_03','V620','阮明',3,'我在食堂也点了相似风味菜品，也算同步过节了呢。','wǒ zài shí táng yě diǎn le xiāng sì fēng wèi cài pǐn， yě suàn tóng bù guò jié le ne。','Con ở căng tin cũng gọi món có hương vị tương tự, coi như cũng ăn Tết đồng thời rồi đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_04','V620','亲戚长辈',4,'在外好好照顾自己，不用挂念家里的节日聚餐。','zài wài hǎo hǎo zhào gù zì jǐ， bù yòng guà niàn jiā lǐ de jié rì jù cān。','Ở bên đó tự chăm sóc bản thân cho tốt, không cần lo lắng chuyện tiệc tùng ngày Tết ở nhà đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_05','V620','阮明',5,'虽然相隔很远，视频连线也像坐在一张桌子吃饭。','suī rán xiāng gé hěn yuǎn， shì pín lián xiàn yě xiàng zuò zài yī zhāng zhuō zi chī fàn。','Tuy cách xa nhau vậy, nhưng gọi video cũng giống như đang ngồi chung một bàn ăn thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_06','V620','亲戚长辈',6,'假期有空多视频，常跟家里说说日常校园生活。','jià qī yǒu kòng duō shì pín， cháng gēn jiā lǐ shuō shuō rì cháng xiào yuán shēng huó。','Rảnh dịp lễ thì gọi video nhiều nhé, hay kể chuyện đời sống ở trường cho cả nhà nghe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L620_07','V620','阮明',7,'好，每年传统节日我都会准时上线和大家团聚。','hǎo， měi nián chuán tǒng jié rì wǒ dōu huì zhǔn shí shàng xiàn hé dà jiā tuán jù。','Vâng, mỗi năm đến dịp lễ truyền thống con đều sẽ lên mạng đúng giờ đoàn tụ với mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT621','SF4','拍食堂饭菜、宿舍环境视频，实时展示在华日常给家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V621','SIT621','P1','suon_se','tuy_y',NULL,'远在境外的父母十分关心子女居住、饮食环境，实时实景视频是最直观让家人安心的方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_01','V621','阮明',1,'爸，我现在共享画面，带您看看我的宿舍和学校食堂。','bà， wǒ xiàn zài gòng xiǎng huà miàn， dài nín kàn kàn wǒ de sù shè hé xué xiào shí táng。','Bố ơi, con đang chia sẻ màn hình đây, để con dẫn bố xem ký túc xá với căng tin trường con luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_02','V621','父亲',2,'宿舍整洁宽敞，食堂菜品种类看着很丰富，放心多了。','sù shè zhěng jié kuān chǎng， shí táng cài pǐn zhǒng lèi kàn zhe hěn fēng fù， fàng xīn duō le。','Ký túc xá gọn gàng rộng rãi, món ăn ở căng tin nhìn cũng phong phú, bố yên tâm hơn nhiều rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_03','V621','阮明',3,'每天三餐都在食堂解决，价格实惠，口味也能适应。','měi tiān sān cān dōu zài shí táng jiě jué， jià gé shí huì， kǒu wèi yě néng shì yìng。','Ba bữa mỗi ngày con đều ăn ở căng tin, giá cả phải chăng, khẩu vị cũng hợp được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_04','V621','父亲',4,'日常居住环境安全整洁，我们在家不用一直担心你的生活。','rì cháng jū zhù huán jìng ān quán zhěng jié， wǒ men zài jiā bù yòng yì zhí dān xīn nǐ de shēng huó。','Môi trường sống hằng ngày an toàn sạch sẽ vậy, ở nhà chúng tôi cũng đỡ phải lo lắng suốt về cuộc sống của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_05','V621','阮明',5,'楼下还有超市、药店，日常生活用品采购很方便。','lóu xià hái yǒu chāo shì、 yào diàn， rì cháng shēng huó yòng pǐn cǎi gòu hěn fāng biàn。','Dưới tầng còn có siêu thị, nhà thuốc nữa, mua đồ dùng sinh hoạt hằng ngày rất tiện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_06','V621','父亲',6,'多拍日常视频发给我们，直观知道你在校的生活状态。','duō pāi rì cháng shì pín fā gěi wǒ men， zhí guān zhī dào nǐ zài xiào de shēng huó zhuàng tài。','Con quay thêm video sinh hoạt hằng ngày gửi cho bố mẹ nhé, để trực quan biết được tình hình sống của con ở trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L621_07','V621','阮明',7,'之后每周固定拍一段校园日常视频发给家里。','zhī hòu měi zhōu gù dìng pāi yī duàn xiào yuán rì cháng shì pín fā gěi jiā lǐ。','Sau này mỗi tuần con sẽ cố định quay một đoạn video sinh hoạt ở trường gửi về cho nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT622','SF4','教父母简单中文短句，方便以后来华出行沟通',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V622','SIT622','P1','twist','tuy_y',NULL,'不少外籍留学生父母计划来华探亲，子女会远程教授基础中文短句，方便线下出行、购物沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_01','V622','阮明',1,'妈，我教您几句简单中文，以后来中国旅游能用得上。','mā， wǒ jiào nín jǐ jù jiǎn dān zhōng wén， yǐ hòu lái zhōng guó lǚ yóu néng yòng dé shàng。','Mẹ ơi, con dạy mẹ vài câu tiếng Trung đơn giản, sau này qua Trung Quốc du lịch dùng được đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_02','V622','母亲',2,'中文发音太难了，我记不住声调，读出来很奇怪啊。','zhōng wén fā yīn tài nán le， wǒ jì bú zhù shēng diào， dú chū lái hěn qí guài a。','Phát âm tiếng Trung khó quá, mẹ nhớ không nổi thanh điệu, đọc lên nghe kỳ kỳ sao ấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_03','V622','阮明',3,'不用纠结标准声调，简单短句能让店员听懂意思就行嘛。','bù yòng jiū jié biāo zhǔn shēng diào， jiǎn dān duǎn jù néng ràng diàn yuán tīng dǒng yì si jiù xíng ma。','Mẹ không cần cố đúng thanh điệu chuẩn đâu, câu ngắn đơn giản để nhân viên hiểu ý là được rồi mẹ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_04','V622','母亲',4,'比如点餐、问路这类基础句子，您一句一句慢速教我。','bǐ rú diǎn cān、 wèn lù zhè lèi jī chǔ jù zi， nín yī jù yī jù màn sù jiāo wǒ。','Ví dụ như mấy câu cơ bản gọi món, hỏi đường ấy, con dạy mẹ từng câu một, chậm thôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_05','V622','阮明',5,'先学"多少钱""请问卫生间在哪里"两句最常用的。','xiān xué " duō shǎo qián "" qǐng wèn wèi shēng jiān zài nǎ lǐ " liǎng jù zuì cháng yòng de。','Trước tiên học hai câu hay dùng nhất là "bao nhiêu tiền" với "xin hỏi nhà vệ sinh ở đâu" đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_06','V622','母亲',6,'我反复跟读几遍，下次来华就能简单沟通不慌张。','wǒ fǎn fù gēn dú jǐ biàn， xià cì lái huá jiù néng jiǎn dān gōu tōng bù huāng zhāng。','Mẹ đọc theo vài lần cho quen, lần sau qua Trung Quốc là có thể giao tiếp đơn giản mà không cuống nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L622_07','V622','阮明',7,'我每天视频花十分钟教您短句，慢慢积累就熟练了。','wǒ měi tiān shì pín huā shí fēn zhōng jiào nín duǎn jù， màn màn jī lěi jiù shú liàn le。','Mỗi ngày con gọi video dạy mẹ câu ngắn khoảng mười phút, từ từ tích lũy là sẽ quen tay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT623','SF4','父母好奇中国课堂，申请老师允许录制简短上课片段发给家人',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V623','SIT623','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂课件拥有教学版权，随意完整录制传播属于违规；仅无课件、不暴露他人肖像的短实景片段可适度拍摄。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_01','V623','阮明',1,'老师您好，我的父母十分好奇中国课堂，想申请录制一小段授课视频。','lǎo shī nín hǎo， wǒ de fù mǔ shí fēn hào qí zhōng guó kè táng， xiǎng shēn qǐng lù zhì yī xiǎo duàn shòu kè shì pín。','Chào cô ạ, bố mẹ em rất tò mò về lớp học ở Trung Quốc nên muốn xin phép quay một đoạn video ngắn buổi học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_02','V623','老师',2,'课堂内容涉及课件版权，完整整节课录制是不允许的。','kè táng nèi róng shè jí kè jiàn bǎn quán， wán zhěng zhěng jié kè lù zhì shì bù yǔn xǔ de。','Nội dung bài giảng liên quan đến bản quyền giáo án nên không được phép quay trọn vẹn cả tiết học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_03','V623','阮明',3,'那只录制教室环境、课堂互动，不拍摄课件文字可以吗？','nà zhǐ lù zhì jiào shì huán jìng、 kè táng hù dòng， bù pāi shè kè jiàn wén zì kě yǐ ma？','Vậy em chỉ quay không gian lớp học và các hoạt động tương tác, không quay chữ trên giáo án thì được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_04','V623','老师',4,'无课件文字的实景互动片段可以短时间录制，时长控制在一分钟内嘛。','wú kè jiàn wén zì de shí jǐng hù dòng piàn duàn kě yǐ duǎn shí jiān lù zhì， shí cháng kòng zhì zài yì fēn zhōng nèi ma。','Đoạn ghi hình thực tế không có chữ giáo án thì có thể quay trong thời gian ngắn, khống chế trong khoảng một phút nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_05','V623','阮明',5,'一分钟短视频足够发给家人了解课堂氛围，不会泄露教学内容。','yì fēn zhōng duǎn shì pín zú gòu fā gěi jiā rén liǎo jiě kè táng fēn wéi， bú huì xiè lòu jiào xué nèi róng。','Một đoạn video ngắn một phút cũng đủ để gửi cho gia đình xem không khí lớp học rồi, sẽ không lộ nội dung giảng dạy đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_06','V623','老师',6,'录制时不要拍到其他同学清晰面部，保护同班同学隐私。','lù zhì shí bú yào pāi dào qí tā tóng xué qīng xī miàn bù， bǎo hù tóng bān tóng xué yǐn sī。','Lúc quay đừng để lộ rõ mặt các bạn học khác, phải bảo vệ quyền riêng tư cho các bạn cùng lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L623_07','V623','阮明',7,'我会避开其他同学镜头，只拍摄讲台与教室环境，感谢老师通融。','wǒ huì bì kāi qí tā tóng xué jìng tóu， zhǐ pāi shè jiǎng tái yǔ jiào shì huán jìng， gǎn xiè lǎo shī tōng róng。','Em sẽ tránh ống kính khỏi các bạn khác, chỉ quay bục giảng với khung cảnh lớp học thôi, cảm ơn cô đã thông cảm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT624','SF5','护照丢失，第一时间视频联系家人说明情况寻求建议',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V624','SIT624','P1','suon_se','chinh_thuc',NULL,'留学生丢失护照属于重大紧急事件，第一时间同步家人，家人会协助梳理资金、证件补办相关方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_01','V624','阮明',1,'爸妈，我今天出门逛街不慎丢失护照，现在在派出所报案。','bà mā， wǒ jīn tiān chū mén guàng jiē bù shèn diū shī hù zhào， xiàn zài zài pài chū suǒ bào àn。','Bố mẹ ơi, hôm nay con đi dạo phố sơ ý làm mất hộ chiếu, giờ con đang ở đồn công an để trình báo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_02','V624','母亲',2,'怎么这么不小心，补办证件流程复杂，资金、证件都有麻烦。','zěn me zhè me bù xiǎo xīn， bǔ bàn zhèng jiàn liú chéng fù zá， zī jīn、 zhèng jiàn dōu yǒu má fán。','Sao con lại bất cẩn như vậy, thủ tục làm lại giấy tờ phức tạp lắm, cả tiền bạc lẫn giấy tờ đều rắc rối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_03','V624','阮明',3,'民警告知我先开遗失回执，再分别去出入境、大使馆补办呢。','mín jǐng gào zhī wǒ xiān kāi yí shī huí zhí， zài fēn bié qù chū rù jìng、 dà shǐ guǎn bǔ bàn ne。','Công an bảo con trước tiên xin biên nhận báo mất, sau đó lần lượt đến cục xuất nhập cảnh và đại sứ quán để làm lại ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_04','V624','父亲',4,'需要加急汇款给你吗，补办护照、临时通行证明会产生费用？','xū yào jiā jí huì kuǎn gěi nǐ ma， bǔ bàn hù zhào、 lín shí tōng xíng zhèng míng huì chǎn shēng fèi yòng？','Có cần bố mẹ chuyển gấp tiền cho con không, làm lại hộ chiếu và giấy thông hành tạm thời chắc sẽ phát sinh chi phí?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_05','V624','阮明',5,'暂时不用，校内还有备用生活费，足够支付全部手续工本费。','zàn shí bù yòng， xiào nèi hái yǒu bèi yòng shēng huó fèi， zú gòu zhī fù quán bù shǒu xù gōng běn fèi。','Tạm thời chưa cần đâu ạ, trong trường con vẫn còn tiền sinh hoạt dự phòng, đủ để trả hết các khoản lệ phí thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_06','V624','母亲',6,'全程保留所有报案单据，每一步办理完及时跟我们同步进度。','quán chéng bǎo liú suǒ yǒu bào àn dān jù， měi yī bù bàn lǐ wán jí shí gēn wǒ men tóng bù jìn dù。','Con nhớ giữ lại toàn bộ giấy tờ trình báo, mỗi bước làm xong phải báo tiến độ cho bố mẹ ngay nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L624_07','V624','阮明',7,'我每办完一项手续立刻视频同步情况，不让你们一直焦虑。','wǒ měi bàn wán yī xiàng shǒu xù lì kè shì pín tóng bù qíng kuàng， bù ràng nǐ men yì zhí jiāo lǜ。','Mỗi lần con làm xong một thủ tục là con sẽ gọi video báo tình hình ngay, không để bố mẹ cứ phải lo lắng mãi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT625','SF5','轻微摔伤生病，先简单文字报平安，再视频细说伤情',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V625','SIT625','P1','twist','ban_chinh_thuc',NULL,'遇到轻微意外，留学生习惯先发简短文字稳住家人情绪，再短时间视频说明具体情况，防止家人瞬间恐慌。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_01','V625','阮明',1,'（文字）妈，下楼不小心轻微摔伤，无大碍，先跟您报平安。','（wén zì） mā， xià lóu bù xiǎo xīn qīng wēi shuāi shāng， wú dà ài， xiān gēn nín bào píng ān。','(Nhắn tin) Mẹ ơi, con xuống cầu thang sơ ý bị ngã trầy nhẹ thôi, không sao đâu, con báo tin để mẹ yên tâm trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_02','V625','母亲',2,'看到消息立刻很担心，方便开视频让我看看伤口情况吗？','kàn dào xiāo xī lì kè hěn dān xīn， fāng biàn kāi shì pín ràng wǒ kàn kàn shāng kǒu qíng kuàng ma？','Thấy tin nhắn là mẹ lo ngay lập tức, con mở video cho mẹ xem vết thương được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_03','V625','阮明',3,'刚处理完伤口，纱布包裹住，视频画面看着会让人揪心嘛。','gāng chǔ lǐ wán shāng kǒu， shā bù bāo guǒ zhù， shì pín huà miàn kàn zhe huì ràng rén jiū xīn ma。','Con vừa xử lý vết thương xong, đã băng gạc rồi, mở video lên nhìn chắc mẹ lại xót ruột thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_04','V625','母亲',4,'就算轻微擦伤也要让我直观看看，判断需不需要去医院复查。','jiù suàn qīng wēi cā shāng yě yào ràng wǒ zhí guān kàn kàn， pàn duàn xū bù xū yào qù yī yuàn fù chá。','Dù chỉ là trầy xước nhẹ mẹ cũng muốn nhìn trực tiếp một chút, để xem có cần đi bệnh viện kiểm tra lại không.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_05','V625','阮明',5,'那我简短开五分钟视频，只展示腿部擦伤，不细说难受感受。','nà wǒ jiǎn duǎn kāi wǔ fēn zhōng shì pín， zhǐ zhǎn shì tuǐ bù cā shāng， bù xì shuō nán shòu gǎn shòu。','Vậy con mở video ngắn năm phút, chỉ cho mẹ xem chỗ trầy ở chân thôi, con sẽ không kể chi tiết cảm giác đau đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_06','V625','母亲',6,'之后出门走路小心，上下楼梯放慢速度，避免再次受伤。','zhī hòu chū mén zǒu lù xiǎo xīn， shàng xià lóu tī fàng màn sù dù， bì miǎn zài cì shòu shāng。','Sau này ra ngoài đi đứng cẩn thận, lên xuống cầu thang thì đi chậm lại, tránh bị thương lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L625_07','V625','阮明',7,'我会多加注意，之后受伤第一时间同步文字平安消息。','wǒ huì duō jiā zhù yì， zhī hòu shòu shāng dì yī shí jiān tóng bù wén zì píng ān xiāo xī。','Con sẽ chú ý hơn, sau này bị thương là con nhắn tin báo bình an ngay lập tức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT626','SF5','签证续签材料资金不足，远程和父母沟通加急汇款',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V626','SIT626','P1','suon_se','chinh_thuc',NULL,'签证材料资金不达标会直接驳回续签申请，遇到资金缺口家人会优先选择加急汇款渠道，不计较高额手续费保障证件办理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_01','V626','阮明',1,'爸，下周就要递交居留续签材料，活期存款余额还差一部分标准。','bà， xià zhōu jiù yào dì jiāo jū liú xù qiān cái liào， huó qī cún kuǎn yú é hái chà yī bù fèn biāo zhǔn。','Bố ơi, tuần sau con phải nộp hồ sơ gia hạn cư trú rồi, mà số dư tài khoản vẫn còn thiếu một phần so với mức yêu cầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_02','V626','父亲',2,'还差多少，我今天立刻走加急跨境电汇给你补足流水。','hái chà duō shǎo， wǒ jīn tiān lì kè zǒu jiā jí kuà jìng diàn huì gěi nǐ bǔ zú liú shuǐ。','Còn thiếu bao nhiêu, để bố chuyển khoản quốc tế hỏa tốc bù đủ số dư cho con ngay hôm nay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_03','V626','阮明',3,'还差四千元，加急汇款隔天就能到账，刚好赶上办理日期。','hái chà sì qiān yuán， jiā jí huì kuǎn gé tiān jiù néng dào zhàng， gāng hǎo gǎn shàng bàn lǐ rì qī。','Còn thiếu bốn nghìn tệ ạ, chuyển gấp thì hôm sau là vào tài khoản rồi, vừa kịp ngày làm thủ tục luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_04','V626','父亲',4,'加急渠道手续费更高，但是能保证不耽误你的签证办理。','jiā jí qú dào shǒu xù fèi gèng gāo， dàn shì néng bǎo zhèng bù dān wù nǐ de qiān zhèng bàn lǐ。','Chuyển qua kênh hỏa tốc thì phí cao hơn, nhưng đảm bảo không làm trễ việc xin visa của con.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_05','V626','阮明',5,'我计算好金额，等资金到账次日立刻打印银行流水。','wǒ jì suàn hǎo jīn é， děng zī jīn dào zhàng cì rì lì kè dǎ yìn yín háng liú shuǐ。','Con tính toán số tiền rồi ạ, đợi tiền vào tài khoản là hôm sau con in sao kê ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_06','V626','父亲',6,'收到汇款短信第一时间告知我，确认入账再去大厅办手续。','shōu dào huì kuǎn duǎn xìn dì yī shí jiān gào zhī wǒ， què rèn rù zhàng zài qù dà tīng bàn shǒu xù。','Nhận được tin nhắn báo có tiền chuyển vào thì báo bố biết ngay, xác nhận tiền vào rồi mới đến quầy làm thủ tục nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L626_07','V626','阮明',7,'感谢您加急处理汇款，避免签证断签影响在校学习。','gǎn xiè nín jiā jí chǔ lǐ huì kuǎn， bì miǎn qiān zhèng duàn qiān yǐng xiǎng zài xiào xué xí。','Cảm ơn bố đã chuyển tiền gấp giúp con, để visa không bị gián đoạn ảnh hưởng đến việc học ở trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT627','SF5','航班延误、行程变动，立刻发消息同步家人避免担忧',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V627','SIT627','P1','suon_se','tuy_y',NULL,'出行航班延误、取消属于高频突发变动，国内家长十分在意行程实时动态，子女必须第一时间同步变动消息。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_01','V627','阮明',1,'妈，我原定今天返程航班大面积延误，起飞推迟六个小时。','mā， wǒ yuán dìng jīn tiān fǎn chéng háng bān dà miàn jī yán wù， qǐ fēi tuī chí liù gè xiǎo shí。','Mẹ ơi, chuyến bay về nước hôm nay của con bị delay diện rộng, giờ cất cánh lùi lại sáu tiếng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_02','V627','母亲',2,'还好你及时发消息，我一直在盯着航班时刻表担心你落地太晚。','hái hǎo nǐ jí shí fā xiāo xī， wǒ yì zhí zài dīng zhe háng bān shí kè biǎo dān xīn nǐ luò dì tài wǎn。','May mà con báo tin kịp thời, mẹ cứ dán mắt vào lịch bay lo con hạ cánh muộn quá đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_03','V627','阮明',3,'机场安排临时休息区域，提供简餐，不会让我长时间干等。','jī chǎng ān pái lín shí xiū xī qū yù， tí gōng jiǎn cān， bú huì ràng wǒ zhǎng shí jiān gàn děng。','Sân bay bố trí khu nghỉ tạm, có phục vụ đồ ăn nhẹ nên con không phải chờ suông cả đống thời gian đâu mẹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_04','V627','母亲',4,'落地到达目的地之后，第一时间给我发一条平安消息吧。','luò dì dào dá mù dì dì zhī hòu， dì yī shí jiān gěi wǒ fā yī tiáo píng ān xiāo xī ba。','Hạ cánh tới nơi rồi thì nhắn ngay một tin báo bình an cho mẹ nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_05','V627','阮明',5,'落地取完行李、坐上交通车辆，立刻同步文字报平安。','luò dì qǔ wán xíng lǐ、 zuò shàng jiāo tōng chē liàng， lì kè tóng bù wén zì bào píng ān。','Con hạ cánh lấy hành lý xong, lên xe rồi là con nhắn tin báo bình an ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_06','V627','母亲',6,'路途奔波注意休息，不用硬撑着长时间跟我们视频。','lù tú bēn bō zhù yì xiū xī， bù yòng yìng chēng zhe zhǎng shí jiān gēn wǒ men shì pín。','Đường xa vất vả thì nhớ nghỉ ngơi, đừng cố gọi video dài với bố mẹ làm gì cho mệt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L627_07','V627','阮明',7,'我会随时同步航班动态，不让您一直悬着心。','wǒ huì suí shí tóng bù háng bān dòng tài， bù ràng nín yì zhí xuán zhe xīn。','Con sẽ cập nhật tình hình chuyến bay liên tục, không để mẹ cứ thấp thỏm mãi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT628','SF6','和父母商量寒暑假回国机票时间，对比价格选择合适航班',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V628','SIT628','P1','twist','tuy_y',NULL,'家长选购国际机票会同时考量票价、落地时段、夜间出行安全，不会单纯选择最低价航班。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_01','V628','阮明',1,'寒暑假有两档回国机票，早一点的班次价格贵三成，晚班性价比更高。','hán shǔ jià yǒu liǎng dàng huí guó jī piào， zǎo yì diǎn de bān cì jià gé guì sān chéng， wǎn bān xìng jià bǐ gèng gāo。','Kỳ nghỉ hè đông có hai khung giờ vé máy bay về nước, chuyến sớm giá đắt hơn ba phần, chuyến muộn thì hời hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_02','V628','母亲',2,'晚班抵达越南是深夜，独自打车回家安全方面我们不放心嘛。','wǎn bān dǐ dá yuè nán shì shēn yè， dú zì dǎ chē huí jiā ān quán fāng miàn wǒ men bù fàng xīn ma。','Chuyến muộn thì tới Việt Nam là nửa đêm rồi, một mình bắt taxi về nhà bố mẹ không yên tâm về khoản an toàn đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_03','V628','阮明',3,'深夜机场有正规接驳大巴直达市区，比单独打车安全很多。','shēn yè jī chǎng yǒu zhèng guī jiē bó dà bā zhí dá shì qū， bǐ dān dú dǎ chē ān quán hěn duō。','Nửa đêm sân bay vẫn có xe buýt trung chuyển chính quy chạy thẳng vào trung tâm, an toàn hơn tự bắt taxi nhiều mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_04','V628','父亲',4,'差价不小，如果接驳交通稳妥，可以选择平价晚班航班。','chā jià bù xiǎo， rú guǒ jiē bó jiāo tōng wěn tuǒ， kě yǐ xuǎn zé píng jià wǎn bān háng bān。','Chênh lệch giá cũng không nhỏ, nếu xe trung chuyển đáng tin cậy thì chọn chuyến muộn giá rẻ hơn cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_05','V628','阮明',5,'我查询了机场大巴运营时间，深夜落地仍有专线班车运行。','wǒ chá xún le jī chǎng dà bā yùn yíng shí jiān， shēn yè luò dì réng yǒu zhuān xiàn bān chē yùn xíng。','Con tra giờ hoạt động của xe buýt sân bay rồi, nửa đêm hạ cánh vẫn có tuyến xe chuyên chạy bình thường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_06','V628','母亲',6,'那我们折中选择午间航班，价格适中、落地时间也安全。','nà wǒ men zhé zhōng xuǎn zé wǔ jiān háng bān， jià gé shì zhōng、 luò dì shí jiān yě ān quán。','Vậy thôi mình chọn dung hòa chuyến bay giữa trưa, giá vừa phải mà giờ hạ cánh cũng an toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L628_07','V628','阮明',7,'我对比三个航班价格与落地时段，把最优方案发给你们确认。','wǒ duì bǐ sān gè háng bān jià gé yǔ luò dì shí duàn， bǎ zuì yōu fāng àn fā gěi nǐ men què rèn。','Con so sánh giá cả và giờ hạ cánh của ba chuyến bay rồi, để con gửi phương án tốt nhất cho bố mẹ duyệt nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT629','SF6','讨论毕业后规划（留华深造/回国工作），和家人交换想法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V629','SIT629','P1','suon_se','ban_chinh_thuc',NULL,'中国家庭在子女升学、就业选择上，大多会先倾听子女自身意愿，共同商量长远规划，不强行安排人生道路。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_01','V629','阮明',1,'毕业有两条路线，留在中国读硕士，或者直接回国找相关工作。','bì yè yǒu liǎng tiáo lù xiàn， liú zài zhōng guó dú shuò shì， huò zhě zhí jiē huí guó zhǎo xiāng guān gōng zuò。','Sau khi tốt nghiệp có hai hướng, hoặc là ở lại Trung Quốc học thạc sĩ, hoặc là về nước tìm việc luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_02','V629','父亲',2,'留在国内深造汉语专业，未来就业选择会更广阔一些。','liú zài guó nèi shēn zào hàn yǔ zhuān yè， wèi lái jiù yè xuǎn zé huì gèng guǎng kuò yī xiē。','Ở lại trong nước học sâu thêm chuyên ngành tiếng Trung thì sau này cơ hội việc làm sẽ rộng mở hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_03','V629','阮明',3,'回国本地外贸行业也有对口岗位，离家近方便照顾你们。','huí guó běn dì wài mào háng yè yě yǒu duì kǒu gǎng wèi， lí jiā jìn fāng biàn zhào gù nǐ men。','Về nước thì ngành ngoại thương ở địa phương cũng có vị trí phù hợp, lại gần nhà tiện chăm sóc bố mẹ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_04','V629','母亲',4,'我们尊重你的个人发展意愿，不会强迫你固定选择一条路。','wǒ men zūn zhòng nǐ de gè rén fā zhǎn yì yuàn， bú huì qiǎng pò nǐ gù dìng xuǎn zé yī tiáo lù。','Bố mẹ tôn trọng nguyện vọng phát triển của con, sẽ không ép con phải chọn cố định một hướng đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_05','V629','阮明',5,'我先实习半年，感受两边行业环境，再确定最终发展方向。','wǒ xiān shí xí bàn nián， gǎn shòu liǎng biān háng yè huán jìng， zài què dìng zuì zhōng fā zhǎn fāng xiàng。','Con định thực tập nửa năm trước, để cảm nhận môi trường ngành nghề cả hai bên rồi mới quyết định hướng đi cuối cùng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_06','V629','父亲',6,'实习期间每月同步你的感受，我们一起分析利弊再做决定。','shí xí qī jiān měi yuè tóng bù nǐ de gǎn shòu， wǒ men yì qǐ fēn xī lì bì zài zuò jué dìng。','Trong thời gian thực tập con cập nhật cảm nhận cho bố mẹ hàng tháng nhé, cả nhà cùng phân tích lợi hại rồi quyết định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L629_07','V629','阮明',7,'谢谢爸妈尊重我的规划，有想法第一时间和你们沟通。','xiè xiè bà mā zūn zhòng wǒ de guī huà， yǒu xiǎng fǎ dì yī shí jiān hé nǐ men gōu tōng。','Cảm ơn bố mẹ đã tôn trọng kế hoạch của con, có ý tưởng gì con sẽ trao đổi với bố mẹ ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT630','SF6','签证有效期快到期，视频和父母说明续办流程、所需资金',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V630','SIT630','P1','twist','chinh_thuc',NULL,'居留续签存在固定办理周期，证件上交期间无法出行，留学生需要提前和家人沟通资金、时间安排，预留充足缓冲时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_01','V630','阮明',1,'我的学生居留许可还有三十天到期，现在开始准备续签全套材料。','wǒ de xué shēng jū liú xǔ kě hái yǒu sān shí tiān dào qī， xiàn zài kāi shǐ zhǔn bèi xù qiān quán tào cái liào。','Giấy phép cư trú diện học sinh của con còn ba mươi ngày nữa là hết hạn, giờ con bắt đầu chuẩn bị đầy đủ hồ sơ gia hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_02','V630','父亲',2,'续签需要额外支付手续费，存款流水也有最低余额要求对吧？','xù qiān xū yào é wài zhī fù shǒu xù fèi， cún kuǎn liú shuǐ yě yǒu zuì dī yú é yāo qiú duì ba？','Gia hạn cần đóng thêm lệ phí thủ tục, và số dư tài khoản cũng có yêu cầu tối thiểu đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_03','V630','阮明',3,'工本费金额不高，但是活期流水需要稳定一万元以上留存三个月嘛。','gōng běn fèi jīn é bù gāo， dàn shì huó qī liú shuǐ xū yào wěn dìng yī wàn yuán yǐ shàng liú cún sān gè yuè ma。','Lệ phí thủ tục thì không cao đâu ạ, nhưng số dư tài khoản cần duy trì ổn định trên một vạn tệ trong ba tháng ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_04','V630','父亲',4,'卡里流动资金不足的话，提前一周告诉我，我提前汇款补足。','kǎ lǐ liú dòng zī jīn bù zú de huà， tí qián yī zhōu gào sù wǒ， wǒ tí qián huì kuǎn bǔ zú。','Nếu trong tài khoản không đủ tiền lưu động thì báo bố trước một tuần, bố sẽ chuyển tiền bù đủ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_05','V630','阮明',5,'材料齐全七个工作日办结，办理期间护照要上交出入境大厅。','cái liào qí quán qī gè gōng zuò rì bàn jié， bàn lǐ qī jiān hù zhào yào shàng jiāo chū rù jìng dà tīng。','Hồ sơ đầy đủ thì bảy ngày làm việc là xong, trong thời gian xử lý phải nộp hộ chiếu cho phòng xuất nhập cảnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_06','V630','父亲',6,'上交护照期间出行不方便，记得提前办好临时出行证明。','shàng jiāo hù zhào qī jiān chū xíng bù fāng biàn， jì de tí qián bàn hǎo lín shí chū xíng zhèng míng。','Trong lúc nộp hộ chiếu thì đi lại sẽ bất tiện, nhớ làm sẵn giấy thông hành tạm thời trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L630_07','V630','阮明',7,'我会把控办理时间，预留缓冲期，不会出现签证断签的情况。','wǒ huì bǎ kòng bàn lǐ shí jiān， yù liú huǎn chōng qī， bú huì chū xiàn qiān zhèng duàn qiān de qíng kuàng。','Con sẽ kiểm soát thời gian làm thủ tục, để dành thời gian dự phòng, sẽ không để xảy ra chuyện visa bị gián đoạn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT701','SSH1','入住新生宿舍，向宿管领取钥匙、核对宿舍物品清单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V701','SIT701','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍入住必须现场核验室内设施并签字登记，人为损坏物品退房会从住宿押金扣除维修费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_01','V701','阮明',1,'阿姨您好，今天办理入住，麻烦给我宿舍钥匙和门禁卡吧。','ā yí nín hǎo， jīn tiān bàn lǐ rù zhù， má fán gěi wǒ sù shè yào shi hé mén jìn kǎ ba。','Cô ơi, hôm nay em làm thủ tục nhập ở, phiền cô đưa cho em chìa khóa phòng và thẻ ra vào ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_02','V701','宿管阿姨',2,'先出示你的录取证件，我们一起进屋核对屋内家具清单哦。','xiān chū shì nǐ de lù qǔ zhèng jiàn， wǒ men yì qǐ jìn wū hé duì wū nèi jiā jù qīng dān ó。','Em xuất trình giấy báo trúng tuyển trước đã, rồi mình cùng vào phòng kiểm tra danh sách đồ đạc trong phòng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_03','V701','阮明',3,'清单上写书桌、衣柜、椅子、空调，我需要逐一检查完好度吗？','qīng dān shàng xiě shū zhuō、 yī guì、 yǐ zi、 kōng tiáo， wǒ xū yào zhú yī jiǎn chá wán hǎo dù ma？','Trong danh sách ghi bàn học, tủ quần áo, ghế, điều hòa, em có cần kiểm tra từng món xem còn nguyên vẹn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_04','V701','宿管阿姨',4,'对，有划痕、损坏当场标注，退房时就不会扣押金了。','duì， yǒu huà hén、 sǔn huài dāng chǎng biāo zhù， tuì fáng shí jiù bú huì kòu yā jīn le。','Đúng rồi, nếu có vết xước hay hư hỏng thì ghi chú ngay tại chỗ, để lúc trả phòng không bị trừ tiền cọc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_05','V701','阮明',5,'墙面很干净，家电都能正常使用，没有破损地方。','qiáng miàn hěn gān jìng， jiā diàn dōu néng zhèng cháng shǐ yòng， méi yǒu pò sǔn dì fāng。','Tường rất sạch, các thiết bị điện đều dùng bình thường, không có chỗ nào hỏng cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_06','V701','宿管阿姨',6,'确认无误就在物品清单签字，钥匙一共两把收好。','què rèn wú wù jiù zài wù pǐn qīng dān qiān zì， yào shi yī gòng liǎng bǎ shōu hǎo。','Xác nhận không có vấn đề gì thì ký vào danh sách đồ đạc, chìa khóa có hai chiếc nhớ giữ cẩn thận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L701_07','V701','阮明',7,'好的，清单我签字，后续宿舍有问题再来找您报修。','hǎo de， qīng dān wǒ qiān zì， hòu xù sù shè yǒu wèn tí zài lái zhǎo nín bào xiū。','Vâng ạ, em ký vào danh sách, sau này phòng có vấn đề gì em sẽ lại tìm cô báo sửa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT702','SSH1','宿舍空调故障不制冷，报修物业上门检修',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V702','SIT702','P1','twist','tuy_y',NULL,'校内宿舍家电基础检修、滤网清洗免费，制冷剂、配件更换属于耗材，会统一登记收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_01','V702','阮明',1,'师傅，我宿舍空调吹出来全是热风，完全没法制冷啊。','shī fù， wǒ sù shè kōng tiáo chuī chū lái quán shì rè fēng， wán quán méi fǎ zhì lěng a。','Chú ơi, máy lạnh phòng em thổi ra toàn hơi nóng, chẳng làm mát được tí nào luôn.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_02','V702','维修师傅',2,'我先开机检测，大概率滤网积灰堵塞，也可能缺制冷剂。','wǒ xiān kāi jī jiǎn cè， dà gài lǜ lǜ wǎng jī huī dǔ sè， yě kě néng quē zhì lěng jì。','Để chú bật máy kiểm tra trước, khả năng cao là lưới lọc bám bụi bị nghẹt, cũng có thể thiếu gas làm lạnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_03','V702','阮明',3,'上周还正常使用，昨晚突然出故障，没有人为磕碰损坏嘛。','shàng zhōu hái zhèng cháng shǐ yòng， zuó wǎn tū rán chū gù zhàng， méi yǒu rén wéi kē pèng sǔn huài ma。','Tuần trước còn dùng bình thường mà, tối qua tự dưng hỏng, đâu có ai va đập làm hỏng đâu nhỉ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_04','V702','维修师傅',4,'滤网我拆下来清洗，如果缺氟就要登记预约次日加制冷剂。','lǜ wǎng wǒ chāi xià lái qīng xǐ， rú guǒ quē fú jiù yào dēng jì yù yuē cì rì jiā zhì lěng jì。','Lưới lọc chú tháo ra rửa cho, nếu thiếu gas thì phải đăng ký hẹn hôm sau bơm gas thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_05','V702','阮明',5,'清洗滤网免费吗，加制冷剂需要我额外支付费用？','qīng xǐ lǜ wǎng miǎn fèi ma， jiā zhì lěng jì xū yào wǒ é wài zhī fù fèi yòng？','Rửa lưới lọc có miễn phí không chú, bơm gas thì em có phải trả thêm tiền không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_06','V702','维修师傅',6,'日常清洗免费，制冷剂损耗需要统一走后勤耗材计费。','rì cháng qīng xǐ miǎn fèi， zhì lěng jì sǔn hào xū yào tǒng yī zǒu hòu qín hào cái jì fèi。','Vệ sinh định kỳ thì miễn phí, còn hao gas thì phải tính chung vào chi phí vật tư hậu cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L702_07','V702','阮明',7,'先清洗滤网看看效果，不够制冷再预约加氟。','xiān qīng xǐ lǜ wǎng kàn kàn xiào guǒ， bù gòu zhì lěng zài yù yuē jiā fú。','Vậy chú rửa lưới lọc trước xem sao đã, không đủ mát thì em hẹn bơm gas sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT703','SSH1','宿舍断电跳闸，找宿管排查电路、恢复供电',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V703','SIT703','P1','that_bai_nhe','tuy_y',NULL,'高校宿舍限制大功率电器，多设备同时使用极易触发过载保护跳闸，违规电器引发故障需学生承担维修费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_01','V703','阮明',1,'阿姨，我宿舍突然全屋断电，插座和顶灯全都没电了。','ā yí， wǒ sù shè tū rán quán wū duàn diàn， chā zuò hé dǐng dēng quán dōu méi diàn le。','Cô ơi, phòng em tự nhiên mất điện cả phòng, ổ cắm với đèn trần đều không có điện luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_02','V703','宿管阿姨',2,'是不是同时使用吹风机、电煮锅大功率电器跳闸？','shì bú shì tóng shí shǐ yòng chuī fēng jī、 diàn zhǔ guō dà gōng lǜ diàn qì tiào zhá？','Có phải cùng lúc dùng máy sấy tóc, nồi điện công suất lớn nên bị nhảy aptomat không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_03','V703','阮明',3,'我只用电脑和台灯，没有违规大功率电器，不清楚原因。','wǒ zhǐ yòng diàn nǎo hé tái dēng， méi yǒu wéi guī dà gōng lǜ diàn qì， bù qīng chǔ yuán yīn。','Em chỉ dùng máy tính với đèn bàn thôi, không có thiết bị công suất lớn gì vi phạm cả, không rõ vì sao luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_04','V703','宿管阿姨',4,'宿舍总闸在楼道配电箱，我去合闸，如果再次跳闸就要断电检修线路。','sù shè zǒng zhá zài lóu dào pèi diàn xiāng， wǒ qù hé zhá， rú guǒ zài cì tiào zhá jiù yào duàn diàn jiǎn xiū xiàn lù。','Cầu dao tổng của phòng ở tủ điện hành lang, để cô đi đóng lại, nếu nhảy tiếp thì phải cắt điện kiểm tra đường dây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_05','V703','阮明',5,'合闸之后要是反复断电，今晚没法开灯学习怎么办？','hé zhá zhī hòu yào shì fǎn fù duàn diàn， jīn wǎn méi fǎ kāi dēng xué xí zěn me bàn？','Đóng cầu dao xong mà cứ bị mất điện liên tục thì tối nay em không bật đèn học bài được, biết làm sao đây?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_06','V703','宿管阿姨',6,'反复跳闸说明线路隐患，今晚临时安排隔壁空宿舍让你自习。','fǎn fù tiào zhá shuō míng xiàn lù yǐn huàn， jīn wǎn lín shí ān pái gé bì kōng sù shè ràng nǐ zì xí。','Nhảy liên tục thì chứng tỏ đường dây có vấn đề tiềm ẩn, tối nay cô sắp xếp tạm cho em sang phòng trống bên cạnh tự học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L703_07','V703','阮明',7,'麻烦您先合闸恢复供电，我之后不用多余电器避免跳闸。','má fán nín xiān hé zhá huī fù gōng diàn， wǒ zhī hòu bù yòng duō yú diàn qì bì miǎn tiào zhá。','Phiền cô đóng cầu dao cho có điện lại trước đã, sau này em không dùng thêm thiết bị điện gì để khỏi bị nhảy nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT704','SSH1','宿舍楼道公共热水机不出热水，咨询宿管使用规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V704','SIT704','P1','suon_se','tuy_y',NULL,'校园公共热水设备统一定时启停，夜间停止加热节约水电，是国内高校通用管理方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_01','V704','阮明',1,'阿姨，楼道热水机按了出水键，一直没有热水流出呢。','ā yí， lóu dào rè shuǐ jī àn le chū shuǐ jiàn， yì zhí méi yǒu rè shuǐ liú chū ne。','Cô ơi, máy nước nóng ở hành lang em bấm nút xả nước rồi mà mãi không thấy nước nóng chảy ra gì cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_02','V704','宿管阿姨',2,'机器有定时加热时段，早上六点到晚上十一点才有热水哦。','jī qì yǒu dìng shí jiā rè shí duàn， zǎo shàng liù diǎn dào wǎn shàng shí yì diǎn cái yǒu rè shuǐ ó。','Máy có giờ hẹn đun nước, chỉ từ sáu giờ sáng đến mười một giờ tối mới có nước nóng thôi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_03','V704','阮明',3,'现在十一点半，刚好过了加热时段，难怪不出热水。','xiàn zài shí yì diǎn bàn， gāng hǎo guò le jiā rè shí duàn， nán guài bù chū rè shuǐ。','Giờ là mười một rưỡi, vừa đúng qua giờ đun nước, thảo nào không có nước nóng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_04','V704','宿管阿姨',4,'如果中途停水，机器缺水也会暂停出水，明天一早恢复。','rú guǒ zhōng tú tíng shuǐ， jī qì quē shuǐ yě huì zàn tíng chū shuǐ， míng tiān yī zǎo huī fù。','Nếu giữa chừng bị cúp nước, máy thiếu nước cũng sẽ tạm ngừng xả, sáng mai là có lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_05','V704','阮明',5,'那我只能明天早上再来接热水洗漱、泡热水杯。','nà wǒ zhǐ néng míng tiān zǎo shàng zài lái jiē rè shuǐ xǐ shù、 pào rè shuǐ bēi。','Vậy chắc mai em phải sáng sớm ra lấy nước nóng để rửa mặt với pha cốc nước nóng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_06','V704','宿管阿姨',6,'尽量避开晚间高峰，八点左右热水出水最稳定。','jǐn liàng bì kāi wǎn jiān gāo fēng， bā diǎn zuǒ yòu rè shuǐ chū shuǐ zuì wěn dìng。','Em cố tránh giờ cao điểm buổi tối nhé, khoảng tám giờ là nước nóng chảy ổn định nhất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L704_07','V704','阮明',7,'我记好热水供应时间，不再错过取水时段。','wǒ jì hǎo rè shuǐ gōng yìng shí jiān， bù zài cuò guò qǔ shuǐ shí duàn。','Em ghi nhớ giờ có nước nóng rồi, sẽ không bỏ lỡ giờ lấy nước nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT705','SSH1','想加装简易收纳架，询问宿管宿舍墙面能否打孔粘贴',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V705','SIT705','P1','twist','ban_chinh_thuc',NULL,'学生宿舍墙面严禁打孔、钉钉子，保护墙体完整，避免退房产生墙面修补扣款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_01','V705','阮明',1,'阿姨，我想买墙上收纳架，能不能在墙面打孔固定？','ā yí， wǒ xiǎng mǎi qiáng shàng shōu nà jià， néng bù néng zài qiáng miàn dǎ kǒng gù dìng？','Cô ơi, em muốn mua giá kệ treo tường, có được khoan lỗ để cố định vào tường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_02','V705','宿管阿姨',2,'宿舍墙体不能打孔，打孔留下孔洞退房要扣修补押金。','sù shè qiáng tǐ bù néng dǎ kǒng， dǎ kǒng liú xià kǒng dòng tuì fáng yào kòu xiū bǔ yā jīn。','Tường phòng không được khoan lỗ, khoan để lại lỗ thì lúc trả phòng sẽ bị trừ tiền cọc sửa chữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_03','V705','阮明',3,'那无痕粘钩、免钉粘贴式置物架可以使用吗？','nà wú hén zhān gōu、 miǎn dīng zhān tiē shì zhì wù jià kě yǐ shǐ yòng ma？','Vậy loại móc dán không để lại vết, kệ dán không cần đóng đinh thì dùng được chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_04','V705','宿管阿姨',4,'无痕粘胶可以，但退房必须完整撕掉，不能残留胶印嘛。','wú hén zhān jiāo kě yǐ， dàn tuì fáng bì xū wán zhěng sī diào， bù néng cán liú jiāo yìn ma。','Keo dán không để lại vết thì được, nhưng lúc trả phòng phải bóc sạch hoàn toàn, không được để lại vết keo nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_05','V705','阮明',5,'如果粘胶撕掉留有痕迹，会收取墙面清洁费对吗？','rú guǒ zhān jiāo sī diào liú yǒu hén jì， huì shōu qǔ qiáng miàn qīng jié fèi duì ma？','Nếu bóc keo mà vẫn còn để lại vết, thì có bị tính phí vệ sinh tường không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_06','V705','宿管阿姨',6,'少量胶印擦拭干净即可，大面积顽固污渍才收费。','shǎo liàng jiāo yìn cā shì gān jìng jí kě， dà miàn jī wán gù wū zì cái shōu fèi。','Vết keo ít thì lau sạch là được, chỉ khi nào vết bẩn cứng đầu diện tích lớn mới bị tính phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L705_07','V705','阮明',7,'我只买免钉粘贴款收纳架，不破坏墙面墙体。','wǒ zhǐ mǎi miǎn dīng zhān tiē kuǎn shōu nà jià， bù pò huài qiáng miàn qiáng tǐ。','Vậy em chỉ mua loại kệ dán không cần đóng đinh thôi, không làm hỏng tường đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT706','SSH1','室友作息差异，协商关灯、安静学习的作息时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V706','SIT706','P1','suon_se','tuy_y',NULL,'多人宿舍室友作息不同是普遍情况，国内学生一般会互相协商灯光、噪音、休息时间，彼此迁就包容。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_01','V706','阮明',1,'小林，我习惯十一点关灯休息，你晚上复习灯光会影响我睡觉。','xiǎo lín， wǒ xí guàn shí yì diǎn guān dēng xiū xī， nǐ wǎn shàng fù xí dēng guāng huì yǐng xiǎng wǒ shuì jiào。','Tiểu Lâm ơi, mình quen tắt đèn nghỉ lúc mười một giờ, tối cậu ôn bài để đèn sáng sẽ ảnh hưởng đến giấc ngủ của mình đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_02','V706','小林',2,'我专业课作业多，经常要学到十二点，咱们折中调整一下吧。','wǒ zhuān yè kè zuò yè duō， jīng cháng yào xué dào shí èr diǎn， zán men zhé zhōng tiáo zhěng yī xià ba。','Môn chuyên ngành của mình bài tập nhiều lắm, thường phải học đến mười hai giờ, thôi mình điều chỉnh dung hòa một chút đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_03','V706','阮明',3,'那你用桌面小台灯，十一点后关掉头顶大灯可以吗？','nà nǐ yòng zhuō miàn xiǎo tái dēng， shí yì diǎn hòu guān diào tóu dǐng dà dēng kě yǐ ma？','Vậy cậu dùng đèn bàn nhỏ, sau mười một giờ tắt đèn trần lớn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_04','V706','小林',4,'没问题，我搭配静音鼠标，不发出敲击键盘噪音打扰你。','méi wèn tí， wǒ dā pèi jìng yīn shǔ biāo， bù fā chū qiāo jī jiàn pán zào yīn dǎ rǎo nǐ。','Không vấn đề gì, mình sẽ dùng chuột im lặng, không gõ bàn phím gây tiếng ồn làm phiền cậu nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_05','V706','阮明',5,'早上七点我会早起洗漱，我动作轻一点不吵醒你休息。','zǎo shàng qī diǎn wǒ huì zǎo qǐ xǐ shù， wǒ dòng zuò qīng yì diǎn bù chǎo xǐng nǐ xiū xī。','Sáng bảy giờ mình dậy sớm rửa mặt, mình sẽ nhẹ nhàng để không đánh thức cậu dậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_06','V706','小林',6,'互相体谅作息，宿舍居住才能舒服不产生矛盾。','hù xiāng tǐ liàng zuò xī， sù shè jū zhù cái néng shū fú bù chǎn shēng máo dùn。','Thông cảm cho nhau về giờ giấc sinh hoạt thì ở phòng mới thoải mái, không nảy sinh mâu thuẫn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L706_07','V706','阮明',7,'太好了，咱们就按这个作息约定长期配合。','tài hǎo le， zán men jiù àn zhè ge zuò xī yuē dìng cháng qī pèi hé。','Tuyệt quá, vậy mình cứ theo thỏa thuận giờ giấc này mà phối hợp lâu dài nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT707','SSH1','宿舍晾晒衣物空间不足，咨询楼顶晾晒区开放时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V707','SIT707','P1','twist','tuy_y',NULL,'楼顶露天晾晒区夜间关闭，防止衣物夜间受潮、丢失，同时避免高空坠物安全隐患。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_01','V707','阮明',1,'阿姨，阳台晾衣杆挂满衣服，没有位置晾晒刚洗的床单。','ā yí， yáng tái liàng yī gān guà mǎn yī fú， méi yǒu wèi zhì liàng shài gāng xǐ de chuáng dān。','Cô ơi, dây phơi ở ban công treo kín quần áo rồi, không còn chỗ nào phơi ga giường mới giặt cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_02','V707','宿管阿姨',2,'宿舍楼顶有公共晾晒区，但是只白天七点到十八点开放。','sù shè lóu dǐng yǒu gōng gòng liàng shài qū， dàn shì zhǐ bái tiān qī diǎn dào shí bā diǎn kāi fàng。','Sân thượng ký túc xá có khu phơi chung, nhưng chỉ mở cửa ban ngày từ bảy giờ sáng đến sáu giờ chiều thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_03','V707','阮明',3,'现在傍晚六点半，马上到关闭时间，今天还能上楼顶晾衣服吗？','xiàn zài bàng wǎn liù diǎn bàn， mǎ shàng dào guān bì shí jiān， jīn tiān hái néng shàng lóu dǐng liàng yī fú ma？','Bây giờ là sáu rưỡi chiều, sắp đến giờ đóng cửa rồi, hôm nay em còn lên sân thượng phơi đồ được không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_04','V707','宿管阿姨',4,'十八点保洁会收回露天衣物，晚一点容易夜间受潮发霉嘛。','shí bā diǎn bǎo jié huì shōu huí lù tiān yī wù， wǎn yì diǎn róng yì yè jiān shòu cháo fā méi ma。','Sáu giờ chiều là nhân viên vệ sinh sẽ thu đồ phơi ngoài trời rồi, để muộn dễ bị ẩm ướt mốc meo qua đêm lắm.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_05','V707','阮明',5,'那我明天一早七点上楼顶，抢占晾晒位置晒大件被褥。','nà wǒ míng tiān yī zǎo qī diǎn shàng lóu dǐng， qiǎng zhàn liàng shài wèi zhì shài dà jiàn bèi rù。','Vậy mai em lên sân thượng từ sớm bảy giờ, tranh chỗ phơi để phơi mấy món chăn đệm to.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_06','V707','宿管阿姨',6,'楼顶风大，记得带夹子固定衣物，防止被风吹落丢失。','lóu dǐng fēng dà， jì de dài jiā zi gù dìng yī wù， fáng zhǐ bèi fēng chuī luò diū shī。','Trên sân thượng gió lớn lắm, nhớ mang kẹp để cố định quần áo, tránh bị gió thổi bay mất đồ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L707_07','V707','阮明',7,'好，我明天提前上楼晾晒大件床上用品。','hǎo， wǒ míng tiān tí qián shàng lóu liàng shài dà jiàn chuáng shàng yòng pǐn。','Vâng, mai em lên sớm phơi mấy món đồ dùng giường chiếu to đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT708','SSH1','宿舍公共垃圾桶满溢，询问保洁阿姨清运时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V708','SIT708','P1','suon_se','tuy_y',NULL,'国内校园推行垃圾分类，楼道垃圾桶定时清运，满溢时可使用楼下备用分类垃圾桶。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_01','V708','阮明',1,'阿姨，楼道垃圾桶全部装满垃圾，没法再投放废弃物了。','ā yí， lóu dào lā jī tǒng quán bù zhuāng mǎn lā jī， méi fǎ zài tóu fàng fèi qì wù le。','Cô ơi, thùng rác chung ở hành lang đầy ắp rác rồi, không thể bỏ thêm rác vào được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_02','V708','保洁李阿姨',2,'我每天上午九点、下午四点各清运一次垃圾哈。','wǒ měi tiān shàng wǔ jiǔ diǎn、 xià wǔ sì diǎn gè qīng yùn yī cì lā jī hā。','Mỗi ngày cô thu gom rác một lần vào chín giờ sáng và bốn giờ chiều đó.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_03','V708','阮明',3,'现在下午两点，还要等两小时才能清空垃圾桶吗？','xiàn zài xià wǔ liǎng diǎn， hái yào děng liǎng xiǎo shí cái néng qīng kōng lā jī tǒng ma？','Bây giờ hai giờ chiều, vậy phải chờ thêm hai tiếng nữa mới dọn sạch thùng rác được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_04','V708','保洁李阿姨',4,'楼下门口有备用分类垃圾桶，可以暂时投放垃圾。','lóu xià mén kǒu yǒu bèi yòng fēn lèi lā jī tǒng， kě yǐ zàn shí tóu fàng lā jī。','Dưới cổng có thùng rác phân loại dự phòng, em có thể tạm bỏ rác vào đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_05','V708','阮明',5,'我先把垃圾带到楼下备用桶，等您四点再来清运。','wǒ xiān bǎ lā jī dài dào lóu xià bèi yòng tǒng， děng nín sì diǎn zài lái qīng yùn。','Vậy em đem rác xuống thùng dự phòng dưới đó trước, đợi bốn giờ cô lên thu gom nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_06','V708','保洁李阿姨',6,'垃圾分类记得分开投放，纸类、塑料不要混在一起。','lā jī fēn lèi jì de fēn kāi tóu fàng， zhǐ lèi、 sù liào bú yào hùn zài yì qǐ。','Nhớ phân loại rác rồi bỏ riêng nhé, giấy với nhựa đừng để lẫn lộn với nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L708_07','V708','阮明',7,'我会做好垃圾分类投放，不给您增加分拣工作量。','wǒ huì zuò hǎo lā jī fēn lèi tóu fàng， bù gěi nín zēng jiā fēn jiǎn gōng zuò liàng。','Em sẽ phân loại rác cẩn thận rồi mới bỏ, không để cô phải mất công phân loại thêm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT709','SSH1','宿舍门禁卡丢失，到宿管处挂失补办门禁卡',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V709','SIT709','P1','that_bai_nhe','ban_chinh_thuc',NULL,'宿舍门禁卡丢失必须第一时间挂失锁卡，保障宿舍财物安全；补办卡片统一收取工本费，制卡设备故障会发放临时通行凭证。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_01','V709','阮明',1,'阿姨，我的宿舍门禁卡昨天外出弄丢了，前来挂失补办。','ā yí， wǒ de sù shè mén jìn kǎ zuó tiān wài chū nòng diū le， qián lái guà shī bǔ bàn。','Cô ơi, thẻ ra vào ký túc xá của em hôm qua đi ra ngoài bị làm mất rồi, em đến báo mất để làm lại thẻ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_02','V709','宿管阿姨',2,'先登记挂失，旧卡立刻锁死，防止别人开门进入宿舍。','xiān dēng jì guà shī， jiù kǎ lì kè suǒ sǐ， fáng zhǐ bié rén kāi mén jìn rù sù shè。','Đăng ký báo mất trước đã, thẻ cũ sẽ bị khóa ngay lập tức, để tránh người khác dùng thẻ mở cửa vào ký túc xá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_03','V709','阮明',3,'补办新门禁卡需要支付工本费吗，当场就能拿到卡片？','bǔ bàn xīn mén jìn kǎ xū yào zhī fù gōng běn fèi ma， dāng chǎng jiù néng ná dào kǎ piàn？','Làm lại thẻ mới có phải đóng phí làm thẻ không cô, và có lấy được thẻ ngay không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_04','V709','宿管阿姨',4,'补办一张门禁卡二十元工本费，制卡机器今天故障维修嘛。','bǔ bàn yī zhāng mén jìn kǎ èr shí yuán gōng běn fèi， zhì kǎ jī qì jīn tiān gù zhàng wéi xiū ma。','Làm lại một thẻ mới là hai mươi tệ phí làm thẻ, nhưng máy làm thẻ hôm nay đang hỏng phải sửa chữa đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_05','V709','阮明',5,'那今天拿不到新卡，晚上怎么刷卡回宿舍休息？','nà jīn tiān ná bú dào xīn kǎ， wǎn shàng zěn me shuā kǎ huí sù shè xiū xī？','Vậy hôm nay không lấy được thẻ mới, tối nay em quẹt thẻ kiểu gì để về ký túc xá nghỉ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_06','V709','宿管阿姨',6,'我给你开具临时纸质通行条，今晚凭纸条进出楼栋。','wǒ gěi nǐ kāi jù lín shí zhǐ zhì tōng xíng tiáo， jīn wǎn píng zhǐ tiáo jìn chū lóu dòng。','Cô sẽ viết cho em một tờ giấy thông hành tạm thời, tối nay cứ cầm tờ giấy đó ra vào tòa nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L709_07','V709','阮明',7,'明天机器修好我再来缴费领新门禁卡。','míng tiān jī qì xiū hǎo wǒ zài lái jiǎo fèi lǐng xīn mén jìn kǎ。','Mai máy sửa xong em sẽ quay lại đóng tiền lấy thẻ mới ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT710','SSH1','校外租房看房，和房东核对家具家电完好情况',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V710','SIT710','P1','suon_se','ban_chinh_thuc',NULL,'校外租房入住前必须逐项核对房屋设施并书面记录原有损坏，避免退租时房东以破损为由克扣押金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_01','V710','阮明',1,'刘哥，我们一起核对屋内家电、家具，记录破损地方吧。','liú gē， wǒ men yì qǐ hé duì wū nèi jiā diàn、 jiā jù， jì lù pò sǔn dì fāng ba。','Anh Lưu ơi, mình cùng kiểm tra lại đồ điện, đồ nội thất trong phòng rồi ghi lại chỗ nào hư hỏng nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_02','V710','房东',2,'冰箱、洗衣机、空调全部试机，有问题当场写进租房合同。','bīng xiāng、 xǐ yī jī、 kōng tiáo quán bù shì jī， yǒu wèn tí dāng chǎng xiě jìn zū fáng hé tóng。','Tủ lạnh, máy giặt, điều hòa đều chạy thử hết, có vấn đề gì thì ghi ngay vào hợp đồng thuê nhà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_03','V710','阮明',3,'衣柜门板有一道小划痕，墙面墙角轻微掉皮，我标注下来。','yī guì mén bǎn yǒu yī dào xiǎo huà hén， qiáng miàn qiáng jiǎo qīng wēi diào pí， wǒ biāo zhù xià lái。','Cánh tủ quần áo có một vết xước nhỏ, góc tường bị bong sơn nhẹ, để em ghi chú lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_04','V710','房东',4,'这些原有轻微损伤全部备注，退房不会扣你的押金。','zhè xiē yuán yǒu qīng wēi sǔn shāng quán bù bèi zhù， tuì fáng bú huì kòu nǐ de yā jīn。','Những chỗ hư hỏng nhẹ có sẵn này đều được ghi chú hết, khi trả nhà sẽ không bị trừ tiền cọc của em đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_05','V710','阮明',5,'水电表初始读数也一起记录，避免结算时产生争议。','shuǐ diàn biǎo chū shǐ dú shù yě yì qǐ jì lù， bì miǎn jié suàn shí chǎn shēng zhēng yì。','Chỉ số điện nước ban đầu cũng ghi lại luôn, để tránh sau này thanh toán bị tranh cãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_06','V710','房东',6,'没问题，所有物品、读数核对完，我们签署纸质租房合同。','méi wèn tí， suǒ yǒu wù pǐn、 dú shù hé duì wán， wǒ men qiān shǔ zhǐ zhì zū fáng hé tóng。','Không vấn đề gì, kiểm tra hết đồ đạc, chỉ số xong thì mình ký hợp đồng thuê nhà bằng giấy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L710_07','V710','阮明',7,'全部设备正常使用，破损全部登记，可以签约入住。','quán bù shè bèi zhèng cháng shǐ yòng， pò sǔn quán bù dēng jì， kě yǐ qiān yuē rù zhù。','Tất cả thiết bị đều dùng bình thường, chỗ hư hỏng cũng ghi lại hết rồi, có thể ký hợp đồng dọn vào ở được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT711','SSH2','食堂充值机无法读卡，找食堂工作人员处理饭卡故障',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V711','SIT711','P1','twist','tuy_y',NULL,'校园饭卡内置磁条，手机、钥匙长期放在一起容易消磁失效，消磁卡片无法修复只能补办。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_01','V711','阮明',1,'你好，校园饭卡放到充值机，机器完全识别不出卡片啊。','nǐ hǎo， xiào yuán fàn kǎ fàng dào chōng zhí jī， jī qì wán quán shí bié bù chū kǎ piàn a。','Chào chị, em để thẻ ăn của trường vào máy nạp tiền mà máy không nhận ra thẻ gì cả.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_02','V711','工作人员',2,'是不是卡片弯折、消磁了，放到读卡窗口多试两次。','shì bú shì kǎ piàn wān zhé、 xiāo cí le， fàng dào dú kǎ chuāng kǒu duō shì liǎng cì。','Có phải thẻ bị cong hay mất từ không, thử đặt vào khe đọc thẻ vài lần xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_03','V711','阮明',3,'反复摆放五次都无反应，昨天还正常充值用餐嘛。','fǎn fù bǎi fàng wǔ cì dōu wú fǎn yìng， zuó tiān hái zhèng cháng chōng zhí yòng cān ma。','Em thử đi thử lại năm lần rồi vẫn không có phản ứng gì, hôm qua vẫn nạp tiền ăn bình thường mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_04','V711','工作人员',4,'卡片消磁只能补办新卡，旧卡余额可以转移到新卡里。','kǎ piàn xiāo cí zhǐ néng bǔ bàn xīn kǎ， jiù kǎ yú é kě yǐ zhuǎn yí dào xīn kǎ lǐ。','Thẻ mất từ rồi thì chỉ có cách làm lại thẻ mới thôi, số dư trong thẻ cũ có thể chuyển sang thẻ mới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_05','V711','阮明',5,'补办饭卡需要携带什么证件，多久能拿到新卡片？','bǔ bàn fàn kǎ xū yào xié dài shén me zhèng jiàn， duō jiǔ néng ná dào xīn kǎ piàn？','Làm lại thẻ ăn cần mang theo giấy tờ gì, bao lâu thì lấy được thẻ mới ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_06','V711','工作人员',6,'带护照、学生证，十分钟制卡完成，当场转移余额。','dài hù zhào、 xué shēng zhèng， shí fēn zhōng zhì kǎ wán chéng， dāng chǎng zhuǎn yí yú é。','Mang hộ chiếu, thẻ sinh viên, mười phút là làm xong thẻ, chuyển số dư ngay tại chỗ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L711_07','V711','阮明',7,'我现在回宿舍拿证件，过来补办饭卡转移余额。','wǒ xiàn zài huí sù shè ná zhèng jiàn， guò lái bǔ bàn fàn kǎ zhuǎn yí yú é。','Vậy giờ em về ký túc xá lấy giấy tờ, rồi quay lại làm lại thẻ ăn chuyển số dư nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT712','SSH2','丢失校园饭卡，挂失冻结余额、补办新饭卡',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V712','SIT712','P1','suon_se','ban_chinh_thuc',NULL,'饭卡丢失第一时间挂失可保护卡内余额，挂失后旧卡永久失效，余额完整迁移至新卡片。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_01','V712','阮明',1,'您好，我的校园饭卡丢失，麻烦先帮我挂失冻结余额。','nín hǎo， wǒ de xiào yuán fàn kǎ diū shī， má fán xiān bāng wǒ guà shī dòng jié yú é。','Chào chị, thẻ ăn của trường em bị mất rồi, phiền chị giúp em báo mất khóa số dư trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_02','V712','工作人员',2,'报你的姓名、学号，系统马上锁定旧卡，无法刷卡消费。','bào nǐ de xìng míng、 xué hào， xì tǒng mǎ shàng suǒ dìng jiù kǎ， wú fǎ shuā kǎ xiāo fèi。','Em cho biết tên, mã số sinh viên, hệ thống sẽ khóa thẻ cũ ngay, không quẹt thẻ tiêu được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_03','V712','阮明',3,'卡里还有一百二十元余额，挂失后能完整转移到新卡吗？','kǎ lǐ hái yǒu yì bǎi èr shí yuán yú é， guà shī hòu néng wán zhěng zhuǎn yí dào xīn kǎ ma？','Trong thẻ còn một trăm hai mươi tệ, báo mất xong có chuyển hết được sang thẻ mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_04','V712','工作人员',4,'全部余额无损转移，仅收取十元新卡工本费。','quán bù yú é wú sǔn zhuǎn yí， jǐn shōu qǔ shí yuán xīn kǎ gōng běn fèi。','Toàn bộ số dư sẽ được chuyển nguyên vẹn, chỉ thu mười tệ phí làm thẻ mới thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_05','V712','阮明',5,'挂失之后如果有人捡到旧卡，也不能刷卡消费了对吧？','guà shī zhī hòu rú guǒ yǒu rén jiǎn dào jiù kǎ， yě bù néng shuā kǎ xiāo fèi le duì ba？','Sau khi báo mất, nếu có ai nhặt được thẻ cũ thì cũng không quẹt tiêu được nữa đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_06','V712','工作人员',6,'没错，挂失永久锁死旧卡，捡到也无法使用。','méi cuò， guà shī yǒng jiǔ suǒ sǐ jiù kǎ， jiǎn dào yě wú fǎ shǐ yòng。','Đúng vậy, báo mất là khóa vĩnh viễn thẻ cũ, có nhặt được cũng không dùng được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L712_07','V712','阮明',7,'我现在补办新卡，今晚就能正常去食堂吃饭。','wǒ xiàn zài bǔ bàn xīn kǎ， jīn wǎn jiù néng zhèng cháng qù shí táng chī fàn。','Vậy giờ em làm lại thẻ mới, tối nay là có thể đi ăn ở căng tin bình thường rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT713','SSH2','食堂错打不喜欢的菜品，询问能否免费更换菜品',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V713','SIT713','P1','twist','tuy_y',NULL,'食堂菜品盛出后无法回收更换，防止交叉污染、食品安全问题，点餐提前告知忌口是更稳妥的方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_01','V713','阮明',1,'阿姨，我不爱吃青椒，刚刚窗口误打了青椒炒肉，能换一份别的菜吗？','ā yí， wǒ bù ài chī qīng jiāo， gāng gāng chuāng kǒu wù dǎ le qīng jiāo chǎo ròu， néng huàn yī fèn bié de cài ma？','Cô ơi, con không ăn được ớt xanh, lúc nãy quầy múc nhầm cho con món thịt xào ớt xanh, đổi cho con món khác được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_02','V713','打菜阿姨',2,'已经盛到餐盘里的菜品，没法回收更换，会影响食品安全嘛。','yǐ jīng shèng dào cān pán lǐ de cài pǐn， méi fǎ huí shōu gēng huàn， huì yǐng xiǎng shí pǐn ān quán ma。','Món đã múc vào khay rồi thì không thu hồi đổi lại được đâu, sẽ ảnh hưởng đến an toàn thực phẩm đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_03','V713','阮明',3,'我一口都没动，只是拿到手才发现里面全是青椒。','wǒ yī kǒu dōu méi dòng， zhǐ shì ná dào shǒu cái fā xiàn lǐ miàn quán shì qīng jiāo。','Con chưa động đũa miếng nào cả, chỉ là cầm lên tay mới phát hiện toàn là ớt xanh thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_04','V713','打菜阿姨',4,'未食用也不能退回，下次排队提前跟我说避开青椒菜品。','wèi shí yòng yě bù néng tuì huí， xià cì pái duì tí qián gēn wǒ shuō bì kāi qīng jiāo cài pǐn。','Chưa ăn cũng không trả lại được, lần sau xếp hàng thì nói trước với cô để tránh món có ớt xanh nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_05','V713','阮明',5,'那只能下次点餐提前说明忌口，这份我打包送给同学。','nà zhǐ néng xià cì diǎn cān tí qián shuō míng jì kǒu， zhè fèn wǒ dǎ bāo sòng gěi tóng xué。','Vậy chỉ đành lần sau gọi món nói trước là kiêng gì thôi, phần này con gói mang cho bạn ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_06','V713','打菜阿姨',6,'下次点餐提前告知忌口食材，我给你单独打别的菜品。','xià cì diǎn cān tí qián gào zhī jì kǒu shí cái， wǒ gěi nǐ dān dú dǎ bié de cài pǐn。','Lần sau gọi món cứ nói trước là kiêng nguyên liệu gì, cô sẽ múc riêng cho con món khác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L713_07','V713','阮明',7,'我记住了，下次打菜提前说明不吃的食材。','wǒ jì zhù le， xià cì dǎ cài tí qián shuō míng bù chī de shí cái。','Con nhớ rồi ạ, lần sau múc đồ ăn con sẽ nói trước là không ăn được gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT714','SSH2','校园奶茶店点单，询问甜度、冰度可选标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V714','SIT714','P1','suon_se','tuy_y',NULL,'国内奶茶饮品可自由调整甜度、冰量，基础小料大多免费添加，是茶饮店通用服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_01','V714','阮明',1,'你好，一杯原味奶茶，甜度和冰度有几种选择呢？','nǐ hǎo， yī bēi yuán wèi nǎi chá， tián dù hé bīng dù yǒu jǐ zhǒng xuǎn zé ne？','Chào anh, cho em một ly trà sữa nguyên vị, độ ngọt với độ đá có mấy mức để chọn vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_02','V714','店员',2,'甜度分无糖、三分糖、五分糖、七分糖、全糖五档哦。','tián dù fēn wú táng、 sān fēn táng、 wǔ fēn táng、 qī fēn táng、 quán táng wǔ dàng ó。','Độ ngọt có năm mức: không đường, ba phần đường, năm phần đường, bảy phần đường, đường đầy đủ nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_03','V714','阮明',3,'冰度常温、少冰、正常冰、去冰，全部都能选吗？','bīng dù cháng wēn、 shǎo bīng、 zhèng cháng bīng、 qù bīng， quán bù dōu néng xuǎn ma？','Độ đá thường, ít đá, đá bình thường, không đá, đều chọn được hết đúng không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_04','V714','店员',4,'是的，任意搭配，另外可以免费加珍珠、椰果两种小料。','shì de， rèn yì dā pèi， lìng wài kě yǐ miǎn fèi jiā zhēn zhū、 yē guǒ liǎng zhǒng xiǎo liào。','Đúng vậy, kết hợp tùy ý, ngoài ra còn được thêm miễn phí trân châu hoặc thạch dừa hai loại topping.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_05','V714','阮明',5,'那五分糖、少冰，再加一份珍珠，麻烦帮我制作。','nà wǔ fēn táng、 shǎo bīng， zài jiā yī fèn zhēn zhū， má fán bāng wǒ zhì zuò。','Vậy cho em năm phần đường, ít đá, thêm một phần trân châu nhé, làm giúp em với.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_06','V714','店员',6,'好的，一共八元，扫码付款后在取餐口等候就行。','hǎo de， yī gòng bā yuán， sǎo mǎ fù kuǎn hòu zài qǔ cān kǒu děng hòu jiù xíng。','Được rồi, tổng cộng tám tệ, quét mã thanh toán xong thì đợi ở quầy lấy đồ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L714_07','V714','阮明',7,'好，我扫码支付，在这里等奶茶做好。','hǎo， wǒ sǎo mǎ zhī fù， zài zhè lǐ děng nǎi chá zuò hǎo。','Vâng, em quét mã thanh toán rồi, em đợi ở đây chờ trà sữa làm xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT715','SSH2','自带饭盒去食堂打包饭菜，咨询打包收费规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V715','SIT715','P1','suon_se','tuy_y',NULL,'国内倡导减少一次性塑料用品，自带饭盒打包可免收餐盒打包费，是校园食堂环保规定。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_01','V715','阮明',1,'您好，我自带饭盒打包饭菜，还要额外收取打包费吗？','nín hǎo， wǒ zì dài fàn hé dǎ bāo fàn cài， hái yào é wài shōu qǔ dǎ bāo fèi ma？','Chào chị, em tự mang hộp cơm đến gói đồ ăn, vậy có phải trả thêm phí đóng gói không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_02','V715','工作人员',2,'自带容器不使用食堂一次性餐盒，免收打包费哈。','zì dài róng qì bù shǐ yòng shí táng yí cì xìng cān hé， miǎn shōu dǎ bāo fèi hā。','Tự mang hộp không dùng hộp dùng một lần của căng tin thì miễn phí đóng gói luôn.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_03','V715','阮明',3,'要是忘记带饭盒，用食堂塑料盒打包多少钱一份？','yào shì wàng jì dài fàn hé， yòng shí táng sù liào hé dǎ bāo duō shǎo qián yī fèn？','Nếu quên mang hộp cơm, dùng hộp nhựa của căng tin để gói thì bao nhiêu tiền một phần vậy chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_04','V715','工作人员',4,'一次性餐盒一元一个，筷子、塑料袋免费提供。','yí cì xìng cān hé yī yuán yí gè， kuài zi、 sù liào dài miǎn fèi tí gōng。','Hộp dùng một lần là một tệ một cái, đũa với túi ni lông thì cung cấp miễn phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_05','V715','阮明',5,'我以后每天带饭盒，既省钱也更环保。','wǒ yǐ hòu měi tiān dài fàn hé， jì shěng qián yě gèng huán bǎo。','Vậy từ giờ ngày nào em cũng mang hộp cơm theo, vừa tiết kiệm vừa bảo vệ môi trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_06','V715','工作人员',6,'自带餐具打包我们十分鼓励，减少塑料垃圾。','zì dài cān jù dǎ bāo wǒ men shí fēn gǔ lì， jiǎn shǎo sù liào lā jī。','Tự mang dụng cụ đến gói đồ thì bên chị rất khuyến khích, giảm bớt rác thải nhựa mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L715_07','V715','阮明',7,'好，我每天自备饭盒来食堂打包饭菜。','hǎo， wǒ měi tiān zì bèi fàn hé lái shí táng dǎ bāo fàn cài。','Vâng, từ nay ngày nào em cũng tự chuẩn bị hộp cơm đến căng tin gói đồ ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT716','SSH2','食堂高峰期排队久，和同学交流错峰就餐时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V716','SIT716','P1','suon_se','tuy_y',NULL,'国内高校十二点是下课就餐最高峰，提前或延后半小时就餐可大幅缩短排队时长。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_01','V716','阮明',1,'中午十二点食堂人挤人，排队二十分钟才能打到饭啊。','zhōng wǔ shí èr diǎn shí táng rén jǐ rén， pái duì èr shí fēn zhōng cái néng dǎ dào fàn a。','Mười hai giờ trưa căng tin đông nghẹt người, xếp hàng hai mươi phút mới lấy được cơm đó.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_02','V716','苏雯',2,'可以十一点四十提前下课去食堂，几乎不用排队呢。','kě yǐ shí yì diǎn sì shí tí qián xià kè qù shí táng， jī hū bù yòng pái duì ne。','Cậu có thể tan học sớm lúc mười một giờ bốn mươi rồi ra căng tin, gần như không phải xếp hàng luôn đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_03','V716','阮明',3,'要是上午有课走不开，下午一点再去是不是人很少？','yào shì shàng wǔ yǒu kè zǒu bù kāi， xià wǔ yì diǎn zài qù shì bú shì rén hěn shǎo？','Nhưng nếu buổi sáng có tiết không đi được, thì một giờ chiều đi có phải vắng người hơn không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_04','V716','苏雯',4,'一点大部分学生吃完回宿舍，窗口菜品选择也还算多。','yì diǎn dà bù fèn xué shēng chī wán huí sù shè， chuāng kǒu cài pǐn xuǎn zé yě hái suàn duō。','Một giờ chiều phần lớn sinh viên ăn xong về ký túc xá rồi, món ở quầy vẫn còn khá nhiều lựa chọn đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_05','V716','阮明',5,'那我分两种时段，早下课就提前去，晚下课一点再就餐。','nà wǒ fēn liǎng zhǒng shí duàn， zǎo xià kè jiù tí qián qù， wǎn xià kè yì diǎn zài jiù cān。','Vậy mình chia hai khung giờ, hôm nào tan sớm thì đi trước, hôm nào tan muộn thì một giờ đi ăn sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_06','V716','苏雯',6,'避开十二点整的高峰，能节省很多排队等待时间。','bì kāi shí èr diǎn zhěng de gāo fēng， néng jié shěng hěn duō pái duì děng dài shí jiān。','Tránh đúng lúc cao điểm mười hai giờ, sẽ tiết kiệm được rất nhiều thời gian xếp hàng chờ đợi đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L716_07','V716','阮明',7,'我之后错开高峰，不用长时间排队等餐。','wǒ zhī hòu cuò kāi gāo fēng， bù yòng zhǎng shí jiān pái duì děng cān。','Từ giờ tớ sẽ tránh giờ cao điểm, khỏi phải xếp hàng chờ ăn lâu như vậy nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT717','SSH2','咨询食堂清真窗口开放时间、菜品范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V717','SIT717','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有独立清真餐窗口，厨具、食材完全隔离，满足有饮食禁忌的学生就餐需求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_01','V717','阮明',1,'您好，想咨询食堂清真窗口每日开放时段有哪些？','nín hǎo， xiǎng zī xún shí táng qīng zhēn chuāng kǒu měi rì kāi fàng shí duàn yǒu nǎ xiē？','Chào chị, cho em hỏi khung giờ mở cửa hàng ngày của quầy Halal ở căng tin là những khung nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_02','V717','工作人员',2,'早七点至八点半早餐，十一点到十三点午餐，十七点半至十九点晚餐哦。','zǎo qī diǎn zhì bā diǎn bàn zǎo cān， shí yì diǎn dào shí sān diǎn wǔ cān， shí qī diǎn bàn zhì shí jiǔ diǎn wǎn cān ó。','Bữa sáng từ bảy giờ đến tám rưỡi, bữa trưa từ mười một giờ đến mười ba giờ, bữa tối từ mười bảy rưỡi đến mười chín giờ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_03','V717','阮明',3,'清真窗口只供应牛羊肉、素食，完全不出现猪肉菜品对吧？','qīng zhēn chuāng kǒu zhǐ gōng yìng niú yáng ròu、 sù shí， wán quán bù chū xiàn zhū ròu cài pǐn duì ba？','Quầy Halal chỉ phục vụ thịt bò, thịt cừu và đồ chay, hoàn toàn không có món nào có thịt heo đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_04','V717','工作人员',4,'没错，厨具、操作台独立分开，杜绝混炒普通菜品。','méi cuò， chú jù、 cāo zuò tái dú lì fēn kāi， dù jué hùn chǎo pǔ tōng cài pǐn。','Đúng vậy, dụng cụ nấu và bàn chế biến đều tách riêng hoàn toàn, không xào chung với món ăn thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_05','V717','阮明',5,'明天早上我早点过来，去清真窗口吃早餐。','míng tiān zǎo shàng wǒ zǎo diǎn guò lái， qù qīng zhēn chuāng kǒu chī zǎo cān。','Sáng mai em sẽ đến sớm hơn, ra quầy Halal ăn sáng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_06','V717','工作人员',6,'窗口每日定时供应，太晚抵达会菜品售罄。','chuāng kǒu měi rì dìng shí gōng yìng， tài wǎn dǐ dá huì cài pǐn shòu qìng。','Quầy phục vụ theo giờ cố định mỗi ngày, đến muộn quá là hết món đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L717_07','V717','阮明',7,'我把控好时间，在窗口开放时段内就餐。','wǒ bǎ kòng hǎo shí jiān， zài chuāng kǒu kāi fàng shí duàn nèi jiù cān。','Em sẽ canh giờ cho chuẩn, ăn trong đúng khung giờ quầy mở cửa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT718','SSH2','餐后忘记归还食堂餐盘，被工作人员提醒规范就餐',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V718','SIT718','P1','that_bai_nhe','tuy_y',NULL,'校园食堂餐盘、汤碗属于公共耗材，禁止带出就餐区域，餐后统一送至店内回收处是通用就餐规范。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_01','V718','阮明',1,'阿姨不好意思，吃完饭后我把餐盘直接带出食堂了，现在送回来。','ā yí bù hǎo yì sī， chī wán fàn hòu wǒ bǎ cān pán zhí jiē dài chū shí táng le， xiàn zài sòng huí lái。','Cô ơi, cháu xin lỗi, ăn xong cháu lỡ mang khay ra khỏi căng tin luôn, giờ cháu mang trả lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_02','V718','保洁李阿姨',2,'食堂规定餐盘必须在店内回收台归还，不能带出就餐区嘛。','shí táng guī dìng cān pán bì xū zài diàn nèi huí shōu tái guī huán， bù néng dài chū jiù cān qū ma。','Căng tin quy định khay phải trả ở quầy thu hồi trong nhà ăn, không được mang ra khỏi khu vực ăn uống mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_03','V718','阮明',3,'刚才着急赶课，一时忘记食堂就餐规定，下次一定注意。','gāng cái zháo jí gǎn kè， yī shí wàng jì shí táng jiù cān guī dìng， xià cì yí dìng zhù yì。','Lúc nãy cháu vội đi học nên quên mất quy định của căng tin, lần sau cháu để ý ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_04','V718','保洁李阿姨',4,'餐盘餐具外流容易丢失、破损，增加食堂耗材成本。','cān pán cān jù wài liú róng yì diū shī、 pò sǔn， zēng jiā shí táng hào cái chéng běn。','Khay với dụng cụ mang ra ngoài dễ bị mất hoặc hỏng, làm tăng chi phí vật tư của căng tin đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_05','V718','阮明',5,'我之后吃完立刻送到回收台，绝不带出食堂大门。','wǒ zhī hòu chī wán lì kè sòng dào huí shōu tái， jué bù dài chū shí táng dà mén。','Sau này cháu ăn xong là mang trả ngay ở quầy thu hồi, không mang ra khỏi cổng căng tin nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_06','V718','保洁李阿姨',6,'记住规则就好，下次不用再特意送回来。','jì zhù guī zé jiù hǎo， xià cì bù yòng zài tè yì sòng huí lái。','Nhớ quy định là được rồi, lần sau không cần cố tình chạy lại trả đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L718_07','V718','阮明',7,'十分抱歉给您增加额外工作，我严格遵守食堂规定。','shí fēn bào qiàn gěi nín zēng jiā é wài gōng zuò， wǒ yán gé zūn shǒu shí táng guī dìng。','Cháu thật sự xin lỗi vì làm cô phải bận thêm, cháu sẽ tuân thủ nghiêm quy định của căng tin.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT719','SSH3','图书馆办理借阅证，学习图书借还、逾期罚款规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V719','SIT719','P1','suon_se','ban_chinh_thuc',NULL,'国内高校图书馆图书超期会收取每日罚金，逾期过久会暂停借阅权限，直至缴清罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_01','V719','阮明',1,'老师您好，我是新生留学生，前来办理图书馆借阅证件。','lǎo shī nín hǎo， wǒ shì xīn shēng liú xué shēng， qián lái bàn lǐ tú shū guǎn jiè yuè zhèng jiàn。','Chào thầy/cô, em là sinh viên quốc tế mới nhập học, em đến làm thẻ thư viện ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_02','V719','馆员王老师',2,'出示学生证、护照，登记信息后绑定校园卡就能借书哦。','chū shì xué shēng zhèng、 hù zhào， dēng jì xìn xī hòu bǎng dìng xiào yuán kǎ jiù néng jiè shū ó。','Em xuất trình thẻ sinh viên với hộ chiếu, đăng ký thông tin rồi liên kết với thẻ sinh viên là mượn sách được nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_03','V719','阮明',3,'单次最多能借几本书，最长借阅期限是多少天？','dān cì zuì duō néng jiè jǐ běn shū， zuì zhǎng jiè yuè qī xiàn shì duō shǎo tiān？','Mỗi lần được mượn tối đa bao nhiêu cuốn, thời hạn mượn lâu nhất là bao nhiêu ngày ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_04','V719','馆员王老师',4,'一次六本，三十天借阅期，可线上续借一次延长十五天。','yī cì liù běn， sān shí tiān jiè yuè qī， kě xiàn shàng xù jiè yī cì yán cháng shí wǔ tiān。','Mỗi lần sáu cuốn, thời hạn ba mươi ngày, có thể gia hạn online một lần thêm mười lăm ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_05','V719','阮明',5,'超过三十天未续借，每天会产生多少逾期罚款呢？','chāo guò sān shí tiān wèi xù jiè， měi tiān huì chǎn shēng duō shǎo yú qī fá kuǎn ne？','Nếu quá ba mươi ngày mà không gia hạn thì mỗi ngày sẽ bị phạt trễ hạn bao nhiêu ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_06','V719','馆员王老师',6,'每本书每日零点一元罚款，超期越久费用累加越高。','měi běn shū měi rì líng diǎn yī yuán fá kuǎn， chāo qī yuè jiǔ fèi yòng lěi jiā yuè gāo。','Mỗi cuốn sách phạt không phẩy một tệ mỗi ngày, càng trễ lâu thì tiền phạt càng cộng dồn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_07','V719','阮明',7,'我会按时续借或者归还，避免产生逾期罚金。','wǒ huì àn shí xù jiè huò zhě guī huán， bì miǎn chǎn shēng yú qī fá jīn。','Em sẽ gia hạn hoặc trả sách đúng hạn, để tránh bị phạt trễ hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT720','SSH3','图书馆自习座位被占，咨询管理员占座管理规定',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V720','SIT720','P1','twist','ban_chinh_thuc',NULL,'图书馆严禁用书、水杯长期霸占自习座位，临时离开超过一小时管理员会清理占位物品，保障座位公平使用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_01','V720','阮明',1,'您好，这个自习座位放着书本一整天没人，我可以坐这里吗？','nín hǎo， zhè ge zì xí zuò wèi fàng zhe shū běn yī zhěng tiān méi rén， wǒ kě yǐ zuò zhè lǐ ma？','Chào anh/chị, chỗ tự học này để sách cả ngày không có ai ngồi, em ngồi đây được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_02','V720','管理员',2,'图书馆禁止长期占座，离开超过一小时物品会统一清收。','tú shū guǎn jìn zhǐ cháng qī zhàn zuò， lí kāi chāo guò yī xiǎo shí wù pǐn huì tǒng yī qīng shōu。','Thư viện cấm giữ chỗ lâu dài, rời chỗ quá một tiếng là đồ đạc sẽ bị thu gom hết đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_03','V720','阮明',3,'书本、水杯全都留在桌面，座位空了整整一下午嘛。','shū běn、 shuǐ bēi quán dōu liú zài zhuō miàn， zuò wèi kōng le zhěng zhěng yī xià wǔ ma。','Sách vở với cốc nước để nguyên trên bàn, chỗ trống suốt cả buổi chiều luôn mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_04','V720','管理员',4,'我先把占位物品收到失物存放区，你可以正常使用这个座位。','wǒ xiān bǎ zhàn wèi wù pǐn shōu dào shī wù cún fàng qū， nǐ kě yǐ zhèng cháng shǐ yòng zhè ge zuò wèi。','Để tôi mang đồ giữ chỗ đó cất vào khu đồ thất lạc trước, em cứ sử dụng chỗ ngồi này bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_05','V720','阮明',5,'那物品主人回来，去哪里领取自己的书本、水杯？','nà wù pǐn zhǔ rén huí lái， qù nǎ lǐ lǐng qǔ zì jǐ de shū běn、 shuǐ bēi？','Vậy chủ nhân của đồ đó quay lại thì đến đâu để lấy lại sách vở, cốc nước ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_06','V720','管理员',6,'一楼服务台报姓名、物品特征就能取回存放物品。','yī lóu fú wù tái bào xìng míng、 wù pǐn tè zhēng jiù néng qǔ huí cún fàng wù pǐn。','Ra quầy phục vụ ở tầng một, báo tên và đặc điểm đồ vật là lấy lại được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_07','V720','阮明',7,'我以后临时离开自习室，随身带走全部私人物品。','wǒ yǐ hòu lín shí lí kāi zì xí shì， suí shēn dài zǒu quán bù sī rén wù pǐn。','Sau này em sẽ mang hết đồ cá nhân theo người mỗi khi rời phòng tự học tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT721','SSH3','图书馆电脑无法登录校园内网，求助值班管理员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V721','SIT721','P1','suon_se','tuy_y',NULL,'校园内网会定期服务器维护，维护期间图书馆电脑无法访问校内论文数据库，属于常规网络维护安排。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_01','V721','阮明',1,'你好，图书馆台式机输入学号，一直登录不上校园内网啊。','nǐ hǎo， tú shū guǎn tái shì jī shū rù xué hào， yì zhí dēng lù bù shàng xiào yuán nèi wǎng a。','Chào anh, máy tính bàn ở thư viện em nhập mã số sinh viên vào mà cứ không đăng nhập được mạng nội bộ trường ấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_02','V721','管理员',2,'是不是校园网账号欠费停机，或者密码输入错误呢？','shì bú shì xiào yuán wǎng zhàng hào qiàn fèi tíng jī， huò zhě mì mǎ shū rù cuò wù ne？','Không biết có phải tài khoản mạng trường bị khóa do quá hạn, hay là gõ nhầm mật khẩu không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_03','V721','阮明',3,'昨天还正常登录查阅文献，没有修改过账号密码。','zuó tiān hái zhèng cháng dēng lù chá yuè wén xiàn， méi yǒu xiū gǎi guò zhàng hào mì mǎ。','Hôm qua em còn đăng nhập bình thường để tra tài liệu mà, em có sửa tài khoản mật khẩu gì đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_04','V721','管理员',4,'今天校内服务器临时维护，部分电脑网络不稳定。','jīn tiān xiào nèi fú wù qì lín shí wéi hù， bù fèn diàn nǎo wǎng luò bù wěn dìng。','Hôm nay máy chủ nội bộ trường đang bảo trì tạm thời, một số máy mạng không ổn định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_05','V721','阮明',5,'那大概多久恢复内网访问，我需要查阅专业论文。','nà dà gài duō jiǔ huī fù nèi wǎng fǎng wèn， wǒ xū yào chá yuè zhuān yè lùn wén。','Vậy khoảng bao lâu nữa thì truy cập mạng nội bộ lại được, em cần tra luận văn chuyên ngành gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_06','V721','管理员',6,'预计四十分钟维护结束，你可以先用手机流量临时查资料。','yù jì sì shí fēn zhōng wéi hù jié shù， nǐ kě yǐ xiān yòng shǒu jī liú liàng lín shí chá zī liào。','Dự kiến bốn mươi phút nữa bảo trì xong, em cứ tạm dùng 4G điện thoại để tra tài liệu trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_07','V721','阮明',7,'我先等服务器维护完成，再使用电脑下载文献。','wǒ xiān děng fú wù qì wéi hù wán chéng， zài shǐ yòng diàn nǎo xià zài wén xiàn。','Em đợi máy chủ bảo trì xong rồi mới dùng máy tính để tải tài liệu vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT722','SSH3','借阅书籍超期，咨询罚款标准、补缴流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V722','SIT722','P1','that_bai_nhe','ban_chinh_thuc',NULL,'图书逾期罚金必须线下结清，未缴清罚款会永久限制图书借阅、数据库使用权限。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_01','V722','阮明',1,'老师，我借阅的两本专业书忘记续借，已经超期八天了。','lǎo shī， wǒ jiè yuè de liǎng běn zhuān yè shū wàng jì xù jiè， yǐ jīng chāo qī bā tiān le。','Thầy/cô ơi, hai cuốn sách chuyên ngành em mượn quên gia hạn mất rồi, đã trễ tám ngày rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_02','V722','馆员王老师',2,'先把图书归还，系统自动核算每日逾期罚款金额。','xiān bǎ tú shū guī huán， xì tǒng zì dòng hé suàn měi rì yú qī fá kuǎn jīn é。','Em trả sách trước đã, hệ thống sẽ tự động tính tiền phạt trễ hạn theo từng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_03','V722','阮明',3,'两本书分开计算罚金，还是合并统一收取费用？','liǎng běn shū fēn kāi jì suàn fá jīn， hái shì hé bìng tǒng yī shōu qǔ fèi yòng？','Hai cuốn tính tiền phạt riêng, hay là gộp chung lại thu một lần ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_04','V722','馆员王老师',4,'每本单独计费，两本书八天一共十六元逾期罚金嘛。','měi běn dān dú jì fèi， liǎng běn shū bā tiān yī gòng shí liù yuán yú qī fá jīn ma。','Mỗi cuốn tính riêng, hai cuốn tám ngày tổng cộng là mười sáu tệ tiền phạt đó nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_05','V722','阮明',5,'罚金只能线下在图书馆服务台扫码缴纳，不能线上支付吗？','fá jīn zhǐ néng xiàn xià zài tú shū guǎn fú wù tái sǎo mǎ jiǎo nà， bù néng xiàn shàng zhī fù ma？','Tiền phạt chỉ có thể quét mã nộp trực tiếp ở quầy phục vụ thư viện thôi, không thanh toán online được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_06','V722','馆员王老师',6,'仅支持线下现场缴费，缴清罚金才能恢复借阅权限。','jǐn zhī chí xiàn xià xiàn chǎng jiǎo fèi， jiǎo qīng fá jīn cái néng huī fù jiè yuè quán xiàn。','Chỉ nộp trực tiếp tại chỗ thôi, nộp phạt xong mới được khôi phục quyền mượn sách.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_07','V722','阮明',7,'我现在扫码缴纳罚金，之后一定记好续借日期。','wǒ xiàn zài sǎo mǎ jiǎo nà fá jīn， zhī hòu yí dìng jì hǎo xù jiè rì qī。','Vậy giờ em quét mã nộp phạt luôn, sau này em nhớ kỹ ngày gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT723','SSH3','图书馆打印复印设备卡纸，找工作人员维修',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V723','SIT723','P1','suon_se','tuy_y',NULL,'自助打印设备卡纸禁止用户自行拆机拉扯纸张，容易造成硬件损坏，需工作人员专业处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_01','V723','阮明',1,'你好，自助复印机打印到一半卡纸，纸张卡在机器里面了。','nǐ hǎo， zì zhù fù yìn jī dǎ yìn dào yí bàn kǎ zhǐ， zhǐ zhāng kǎ zài jī qì lǐ miàn le。','Chào anh, máy photocopy tự động in được nửa chừng thì kẹt giấy, giấy kẹt cứng trong máy luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_02','V723','运维工作人员',2,'别手动拉扯纸张，容易损坏打印机内部齿轮。','bié shǒu dòng lā chě zhǐ zhāng， róng yì sǔn huài dǎ yìn jī nèi bù chǐ lún。','Đừng dùng tay kéo giấy ra, dễ làm hỏng bánh răng bên trong máy in lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_03','V723','阮明',3,'我只是按了停止键，没有强行拽取卡住的打印纸。','wǒ zhǐ shì àn le tíng zhǐ jiàn， méi yǒu qiáng xíng zhuāi qǔ kǎ zhù de dǎ yìn zhǐ。','Em chỉ bấm nút dừng thôi, không có cố kéo tờ giấy bị kẹt ra đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_04','V723','运维工作人员',4,'我打开机盖取出卡纸，清理之后就能恢复打印啦。','wǒ dǎ kāi jī gài qǔ chū kǎ zhǐ， qīng lǐ zhī hòu jiù néng huī fù dǎ yìn la。','Để tôi mở nắp máy lấy giấy kẹt ra, dọn xong là in lại bình thường thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_05','V723','阮明',5,'刚才已经扣取打印费用，卡纸没有完整出纸会返还余额吗？','gāng cái yǐ jīng kòu qǔ dǎ yìn fèi yòng， kǎ zhǐ méi yǒu wán zhěng chū zhǐ huì fǎn huán yú é ma？','Lúc nãy tiền in đã bị trừ rồi, kẹt giấy mà không ra giấy hoàn chỉnh thì có được hoàn lại tiền không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_06','V723','运维工作人员',6,'单次卡纸未出纸，系统自动退还本次打印扣费。','dān cì kǎ zhǐ wèi chū zhǐ， xì tǒng zì dòng tuì huán běn cì dǎ yìn kòu fèi。','Kẹt giấy mà không in ra được thì hệ thống tự động hoàn lại tiền lần in đó thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_07','V723','阮明',7,'麻烦您检修机器，我等下继续打印复习资料。','má fán nín jiǎn xiū jī qì， wǒ děng xià jì xù dǎ yìn fù xí zī liào。','Phiền anh kiểm tra sửa máy giúp em, lát nữa em in tiếp tài liệu ôn tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT724','SSH3','自习到闭馆时间，咨询夜间留校自习申请渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V724','SIT724','P1','twist','ban_chinh_thuc',NULL,'图书馆夜间统一闭馆安保巡查，国内高校单独设置通宵自习教室满足期末备考学生需求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_01','V724','阮明',1,'距离期末考还有两周，图书馆九点闭馆太早，想夜间留校自习。','jù lí qī mò kǎo hái yǒu liǎng zhōu， tú shū guǎn jiǔ diǎn bì guǎn tài zǎo， xiǎng yè jiān liú xiào zì xí。','Còn hai tuần nữa là thi cuối kỳ rồi, thư viện đóng cửa lúc chín giờ sớm quá, em muốn ở lại trường tự học ban đêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_02','V724','管理员',2,'图书馆晚间九点统一闭馆，不允许学生留在馆内过夜自习。','tú shū guǎn wǎn jiān jiǔ diǎn tǒng yī bì guǎn， bù yǔn xǔ xué shēng liú zài guǎn nèi guò yè zì xí。','Thư viện đóng cửa cố định lúc chín giờ tối, không cho phép sinh viên ở lại trong thư viện qua đêm để tự học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_03','V724','阮明',3,'有没有专门通宵自习教室，或者申请延长图书馆开放时间？','yǒu méi yǒu zhuān mén tōng xiāo zì xí jiào shì， huò zhě shēn qǐng yán cháng tú shū guǎn kāi fàng shí jiān？','Vậy có phòng tự học thâu đêm riêng nào không, hay là có thể xin gia hạn giờ mở cửa thư viện không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_04','V724','管理员',4,'教学楼有两间通宵自习室，图书馆无延时开放审批通道嘛。','jiào xué lóu yǒu liǎng jiān tōng xiāo zì xí shì， tú shū guǎn wú yán shí kāi fàng shěn pī tōng dào ma。','Tòa nhà giảng đường có hai phòng tự học thâu đêm, còn thư viện thì không có kênh xin gia hạn giờ mở cửa đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_05','V724','阮明',5,'教学楼通宵教室晚上十一点之后还能正常开灯自习吗？','jiào xué lóu tōng xiāo jiào shì wǎn shàng shí yì diǎn zhī hòu hái néng zhèng cháng kāi dēng zì xí ma？','Phòng tự học thâu đêm ở tòa giảng đường sau mười một giờ đêm vẫn bật đèn học bình thường được chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_06','V724','管理员',6,'全天供电，门禁可刷校园卡二十四小时自由进出。','quán tiān gōng diàn， mén jìn kě shuā xiào yuán kǎ èr shí sì xiǎo shí zì yóu jìn chū。','Có điện cả ngày, cửa ra vào quẹt thẻ sinh viên là ra vào tự do hai mươi bốn tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_07','V724','阮明',7,'今晚开始转移到教学楼通宵教室复习备考。','jīn wǎn kāi shǐ zhuǎn yí dào jiào xué lóu tōng xiāo jiào shì fù xí bèi kǎo。','Vậy tối nay em chuyển sang phòng tự học thâu đêm ở tòa giảng đường để ôn thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT725','SSH3','借阅外文专业参考书，咨询馆员查找馆藏方法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V725','SIT725','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆外文藏书单独分区管理，为保护原版书籍，不开放学生自行入内取阅，由馆员统一调取。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_01','V725','阮明',1,'老师，我需要越南语原版专业参考书，不知道怎么检索馆藏。','lǎo shī， wǒ xū yào yuè nán yǔ yuán bǎn zhuān yè cān kǎo shū， bù zhī dào zěn me jiǎn suǒ guǎn cáng。','Thầy ơi, em cần tìm sách tham khảo chuyên ngành bản gốc tiếng Việt, mà không biết tra cứu sách trong thư viện kiểu gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_02','V725','馆员王老师',2,'图书馆检索系统左上角切换外文分类，输入语种关键词即可。','tú shū guǎn jiǎn suǒ xì tǒng zuǒ shàng jiǎo qiè huàn wài wén fēn lèi， shū rù yǔ zhǒng guān jiàn cí jí kě。','Ở góc trên bên trái hệ thống tra cứu của thư viện có mục chuyển sang phân loại sách ngoại văn, em chỉ cần nhập từ khóa ngôn ngữ vào là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_03','V725','阮明',3,'检索出来显示在三楼外文馆藏区，需要凭借阅证入内取书对吧？','jiǎn suǒ chū lái xiǎn shì zài sān lóu wài wén guǎn cáng qū， xū yào píng jiè yuè zhèng rù nèi qǔ shū duì ba？','Tra ra thì thấy sách nằm ở khu sách ngoại văn tầng ba, vậy em phải có thẻ mượn sách mới vào lấy được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_04','V725','馆员王老师',4,'外文图书区域不对外开放自由取书，报书名由我调取。','wài wén tú shū qū yù bú duì wài kāi fàng zì yóu qǔ shū， bào shū míng yóu wǒ diào qǔ。','Khu sách ngoại văn không mở cửa cho tự do vào lấy đâu, em báo tên sách để cô lấy giúp cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_05','V725','阮明',5,'那我把书籍编号发给您，麻烦帮忙调取这本参考书。','nà wǒ bǎ shū jí biān hào fā gěi nín， má fán bāng máng diào qǔ zhè běn cān kǎo shū。','Vậy em gửi mã số sách cho cô nhé, phiền cô lấy giúp em cuốn sách tham khảo này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_06','V725','馆员王老师',6,'十分钟内找到书籍，你在服务台等候领取。','shí fēn zhōng nèi zhǎo dào shū jí， nǐ zài fú wù tái děng hòu lǐng qǔ。','Trong vòng mười phút cô sẽ tìm được sách, em ra quầy phục vụ đợi lấy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_07','V725','阮明',7,'好，我在这里等候，感谢协助查找外文藏书。','hǎo， wǒ zài zhè lǐ děng hòu， gǎn xiè xié zhù chá zhǎo wài wén cáng shū。','Dạ vâng, em đợi ở đây, cảm ơn cô đã giúp em tìm sách ngoại văn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT726','SSH4','办理校园统一公交优惠学生卡，提交证件材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V726','SIT726','P1','suon_se','ban_chinh_thuc',NULL,'国内在校学生可办理公交学生卡，市内通勤公交享受半价优惠，长途客运不参与学生折扣政策。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_01','V726','阮明',1,'老师您好，想办理公交学生优惠卡，出门乘坐公交半价乘车。','lǎo shī nín hǎo， xiǎng bàn lǐ gōng jiāo xué shēng yōu huì kǎ， chū mén chéng zuò gōng jiāo bàn jià chéng chē。','Chào thầy, em muốn làm thẻ ưu đãi xe buýt học sinh, để đi xe buýt được giảm nửa giá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_02','V726','办事老师',2,'准备好护照、学生证、一寸证件照，填写办卡申请表哦。','zhǔn bèi hǎo hù zhào、 xué shēng zhèng、 yī cùn zhèng jiàn zhào， tián xiě bàn kǎ shēn qǐng biǎo ó。','Em chuẩn bị hộ chiếu, thẻ sinh viên, ảnh thẻ cỡ 3x4, rồi điền tờ đăng ký làm thẻ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_03','V726','阮明',3,'办好公交卡，全市所有公交线路都能享受学生折扣吗？','bàn hǎo gōng jiāo kǎ， quán shì suǒ yǒu gōng jiāo xiàn lù dōu néng xiǎng shòu xué shēng zhé kòu ma？','Làm thẻ xe buýt xong thì tất cả các tuyến xe buýt trong thành phố đều được hưởng ưu đãi học sinh phải không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_04','V726','办事老师',4,'市内常规公交全部半价，长途城际公交不适用优惠。','shì nèi cháng guī gōng jiāo quán bù bàn jià， cháng tú chéng jì gōng jiāo bù shì yòng yōu huì。','Xe buýt thường trong nội thành thì được giảm nửa giá hết, còn xe buýt liên tỉnh đường dài thì không áp dụng ưu đãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_05','V726','阮明',5,'公交卡丢失可以挂失转移余额，和校园饭卡规则一样？','gōng jiāo kǎ diū shī kě yǐ guà shī zhuǎn yí yú é， hé xiào yuán fàn kǎ guī zé yī yàng？','Nếu mất thẻ xe buýt thì báo mất và chuyển số dư được, giống quy định thẻ ăn của trường đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_06','V726','办事老师',6,'没错，携带证件到服务中心挂失补办，余额完整保留。','méi cuò， xié dài zhèng jiàn dào fú wù zhōng xīn guà shī bǔ bàn， yú é wán zhěng bǎo liú。','Đúng vậy, em mang giấy tờ đến trung tâm dịch vụ báo mất và làm lại thẻ, số dư vẫn giữ nguyên đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_07','V726','阮明',7,'我备齐材料，今天办理学生公交优惠卡。','wǒ bèi qí cái liào， jīn tiān bàn lǐ xué shēng gōng jiāo yōu huì kǎ。','Em chuẩn bị đủ giấy tờ rồi, hôm nay em làm thẻ ưu đãi xe buýt học sinh luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT727','SSH4','共享单车扫码失败、车辆故障，咨询换车流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V727','SIT727','P1','twist','tuy_y',NULL,'共享单车故障车辆免费换车，短时间内切换新车不重复收取起步费用，是平台通用售后规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_01','V727','阮明',1,'师傅，这辆单车扫码开锁一直失败，页面提示车辆故障啊。','shī fù， zhè liàng dān chē sǎo mǎ kāi suǒ yì zhí shī bài， yè miàn tí shì chē liàng gù zhàng a。','Anh ơi, chiếc xe đạp này em quét mã mở khóa mãi không được, màn hình báo xe bị hỏng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_02','V727','运维员',2,'故障车辆后台锁定无法解锁，直接在APP点更换车辆按钮。','gù zhàng chē liàng hòu tái suǒ dìng wú fǎ jiě suǒ， zhí jiē zài APP diǎn gēng huàn chē liàng àn niǔ。','Xe hỏng thì hệ thống đã khóa lại rồi, không mở khóa được đâu, em bấm nút đổi xe trên app là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_03','V727','阮明',3,'换车会不会重复收取骑行起步费，两辆车分开计费吗？','huàn chē huì bú huì chóng fù shōu qǔ qí xíng qǐ bù fèi， liǎng liàng chē fēn kāi jì fèi ma？','Đổi xe như vậy có bị tính lại phí mở chuyến không, hai xe có tính tiền riêng không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_04','V727','运维员',4,'故障换车十分钟内切换新车，不会二次扣费，自动取消订单嘛。','gù zhàng huàn chē shí fēn zhōng nèi qiè huàn xīn chē， bú huì èr cì kòu fèi， zì dòng qǔ xiāo dìng dān ma。','Đổi xe do lỗi trong vòng mười phút thì không bị tính phí lần hai đâu, đơn cũ tự động hủy mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_05','V727','阮明',5,'那我直接换旁边完好单车，不用手动结束当前订单？','nà wǒ zhí jiē huàn páng biān wán hǎo dān chē， bù yòng shǒu dòng jié shù dāng qián dìng dān？','Vậy em cứ đổi luôn sang chiếc xe bên cạnh còn tốt, không cần tự tay kết thúc chuyến đang mở à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_06','V727','运维员',6,'APP一键换车系统自动处理，不用额外操作订单。','APP yī jiàn huàn chē xì tǒng zì dòng chǔ lǐ， bù yòng é wài cāo zuò dìng dān。','App đổi xe một chạm là hệ thống tự xử lý hết, em không cần thao tác thêm gì với đơn cũ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_07','V727','阮明',7,'我现在操作更换车辆，正常骑行前往教学楼。','wǒ xiàn zài cāo zuò gēng huàn chē liàng， zhèng cháng qí xíng qián wǎng jiào xué lóu。','Giờ em thao tác đổi xe đây, rồi đi bình thường lên nhà giảng đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT728','SSH4','校内电动车限速规定，被安保提醒减速慢行',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V728','SIT728','P1','that_bai_nhe','tuy_y',NULL,'国内大学校园非机动车统一低速限速，保护步行学生安全，多次超速会暂扣车辆进行安全教育。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_01','V728','阮明',1,'保安大叔，怎么拦下我，是电动车行驶有违规地方吗？','bǎo ān dà shū， zěn me lán xià wǒ， shì diàn dòng chē háng shǐ yǒu wéi guī dì fāng ma？','Chú bảo vệ ơi, sao chú chặn cháu lại vậy, xe điện cháu chạy có gì sai quy định à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_02','V728','安保大叔',2,'校内道路限速十五公里每小时，你车速过快存在安全隐患。','xiào nèi dào lù xiàn sù shí wǔ gōng lǐ měi xiǎo shí， nǐ chē sù guò kuài cún zài ān quán yǐn huàn。','Đường trong trường quy định tốc độ tối đa mười lăm cây số một giờ, cháu chạy nhanh quá là có nguy cơ mất an toàn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_03','V728','阮明',3,'我赶去上课没留意限速标识，没有注意控制骑行速度嘛。','wǒ gǎn qù shàng kè méi liú yì xiàn sù biāo shí， méi yǒu zhù yì kòng zhì qí xíng sù dù ma。','Cháu vội đi học nên không để ý biển báo giới hạn tốc độ, không chú ý giữ tốc độ chậm lại ấy mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_04','V728','安保大叔',4,'校园行人多，电动车超速容易撞到散步、赶路的学生。','xiào yuán xíng rén duō， diàn dòng chē chāo sù róng yì zhuàng dào sàn bù、 gǎn lù de xué shēng。','Trong trường người đi bộ đông, xe điện chạy quá tốc độ dễ tông phải học sinh đang dạo bộ hay đang vội đi đâu đó lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_05','V728','阮明',5,'第一次超速提醒，会不会扣除校园通行积分或者罚款？','dì yī cì chāo sù tí xǐng， huì bú huì kòu chú xiào yuán tōng xíng jī fēn huò zhě fá kuǎn？','Lần đầu bị nhắc chạy quá tốc độ thế này có bị trừ điểm ra vào trường hay bị phạt tiền không chú?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_06','V728','安保大叔',6,'首次口头警告，多次超速会暂扣电动车半天教育。','shǒu cì kǒu tóu jǐng gào， duō cì chāo sù huì zàn kòu diàn dòng chē bàn tiān jiào yù。','Lần đầu thì chỉ nhắc nhở bằng lời thôi, chạy quá tốc độ nhiều lần thì sẽ bị giữ xe điện nửa ngày để giáo dục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_07','V728','阮明',7,'之后在校内骑行放慢车速，严格遵守限速规定。','zhī hòu zài xiào nèi qí xíng fàng màn chē sù， yán gé zūn shǒu xiàn sù guī dìng。','Từ giờ cháu sẽ đi xe chậm lại trong trường, tuân thủ nghiêm quy định giới hạn tốc độ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT729','SSH4','快递驿站取件忘记取件码，凭护照核对身份取件',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V729','SIT729','P1','suon_se','tuy_y',NULL,'快递驿站可凭实名有效证件核对身份取件，不止局限于短信取件码，方便遗失短信的顾客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_01','V729','阮明',1,'你好，我网购的快递到驿站，但是手机弄丢取件短信码了。','nǐ hǎo， wǒ wǎng gòu de kuài dì dào yì zhàn， dàn shì shǒu jī nòng diū qǔ jiàn duǎn xìn mǎ le。','Chào chị, em có đơn hàng online gửi về bưu cục, nhưng em làm mất tin nhắn mã lấy hàng trong điện thoại rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_02','V729','驿站店员',2,'报你的收件姓名、手机号，出示有效证件就能核对包裹。','bào nǐ de shōu jiàn xìng míng、 shǒu jī hào， chū shì yǒu xiào zhèng jiàn jiù néng hé duì bāo guǒ。','Em đọc tên người nhận, số điện thoại, rồi xuất trình giấy tờ tùy thân hợp lệ là chị đối chiếu được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_03','V729','阮明',3,'我出示留学生护照，上面有我的姓名拼音可以核对身份吗？','wǒ chū shì liú xué shēng hù zhào， shàng miàn yǒu wǒ de xìng míng pīn yīn kě yǐ hé duì shēn fèn ma？','Em xuất trình hộ chiếu du học sinh, trên đó có tên phiên âm của em, vậy có đối chiếu được không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_04','V729','驿站店员',4,'可以，姓名、手机号匹配无误就能直接找出快递包裹。','kě yǐ， xìng míng、 shǒu jī hào pǐ pèi wú wù jiù néng zhí jiē zhǎo chū kuài dì bāo guǒ。','Được chứ, tên với số điện thoại khớp là chị tìm ra được kiện hàng của em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_05','V729','阮明',5,'麻烦帮我查找今天送达的小件包裹，是学习文具。','má fán bāng wǒ chá zhǎo jīn tiān sòng dá de xiǎo jiàn bāo guǒ， shì xué xí wén jù。','Phiền chị tìm giúp em kiện hàng nhỏ gửi đến hôm nay, đồ dùng học tập ấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_06','V729','驿站店员',6,'查到了，这个快递，你核对包裹面单信息再拿走。','chá dào le， zhè ge kuài dì， nǐ hé duì bāo guǒ miàn dān xìn xī zài ná zǒu。','Tìm ra rồi đây, kiện hàng này, em kiểm tra lại thông tin trên phiếu gửi rồi lấy về nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_07','V729','阮明',7,'信息全部匹配，感谢不用取件码也能取件。','xìn xī quán bù pǐ pèi， gǎn xiè bù yòng qǔ jiàn mǎ yě néng qǔ jiàn。','Thông tin khớp hết rồi, cảm ơn chị đã cho em lấy hàng dù không nhớ mã ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT730','SSH4','大件快递无法上楼，和驿站协商送货上门服务',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V730','SIT730','P1','twist','ban_chinh_thuc',NULL,'校园快递驿站以自取为主，大件重物单独上门配送会收取少量配送服务费，用于补贴人工运力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_01','V730','阮明',1,'我这个纸箱是被褥大件，楼梯没有电梯，自己搬不动上楼。','wǒ zhè ge zhǐ xiāng shì bèi rù dà jiàn， lóu tī méi yǒu diàn tī， zì jǐ bān bù dòng shàng lóu。','Thùng các tông này của em là chăn đệm cồng kềnh, cầu thang lại không có thang máy, tự em không khiêng lên được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_02','V730','驿站店员',2,'校园驿站规定小件自取，大件上门需要额外支付配送服务费。','xiào yuán yì zhàn guī dìng xiǎo jiàn zì qǔ， dà jiàn shàng mén xū yào é wài zhī fù pèi sòng fú wù fèi。','Theo quy định của bưu cục trong trường, hàng nhỏ thì tự lấy, còn hàng cồng kềnh muốn giao tận nơi thì phải trả thêm phí giao hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_03','V730','阮明',3,'宿舍就在校内宿舍楼，距离驿站步行三分钟也要额外收费嘛？','sù shè jiù zài xiào nèi sù shè lóu， jù lí yì zhàn bù xíng sān fēn zhōng yě yào é wài shōu fèi ma？','Ký túc xá em ở ngay trong khuôn viên trường, đi bộ từ bưu cục có ba phút mà cũng phải trả thêm phí sao?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_04','V730','驿站店员',4,'配送人员批量派送楼栋，单独上门单件加收三元配送费嘛。','pèi sòng rén yuán pī liàng pài sòng lóu dòng， dān dú shàng mén dān jiàn jiā shōu sān yuán pèi sòng fèi ma。','Nhân viên giao hàng giao theo lô cho cả tòa nhà, còn giao riêng lẻ từng đơn thì tính thêm ba tệ phí giao hàng.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_05','V730','阮明',5,'那我今天下午有空，能不能傍晚统一顺路送货上门？','nà wǒ jīn tiān xià wǔ yǒu kòng， néng bù néng bàng wǎn tǒng yī shùn lù sòng huò shàng mén？','Vậy chiều nay em rảnh, có thể chiều tối gộp giao luôn tiện đường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_06','V730','驿站店员',6,'傍晚六点批量配送，你留好宿舍房间号等候送货。','bàng wǎn liù diǎn pī liàng pèi sòng， nǐ liú hǎo sù shè fáng jiān hào děng hòu sòng huò。','Sáu giờ chiều bên em giao hàng theo lô, em nhớ để lại số phòng ký túc xá rồi đợi giao hàng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_07','V730','阮明',7,'我同意支付配送费，傍晚等工作人员送被褥上楼。','wǒ tóng yì zhī fù pèi sòng fèi， bàng wǎn děng gōng zuò rén yuán sòng bèi rù shàng lóu。','Em đồng ý trả phí giao hàng, chiều tối em đợi nhân viên mang chăn đệm lên phòng giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT731','SSH4','咨询校园医务室就诊流程、医保报销范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V731','SIT731','P1','suon_se','ban_chinh_thuc',NULL,'国内高校统一购买大学生医保，校内医务室基础诊疗、常用药品可按比例报销，大幅降低就医开支。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_01','V731','阮明',1,'护士您好，轻微咳嗽不舒服，想咨询医务室就诊流程。','hù shì nín hǎo， qīng wēi ké sòu bù shū fú， xiǎng zī xún yī wù shì jiù zhěn liú chéng。','Chào cô y tá, em bị ho nhẹ khó chịu trong người, muốn hỏi quy trình khám ở phòng y tế trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_02','V731','护士',2,'携带校园医保凭证、学生证，一楼分诊台登记排队就诊哦。','xié dài xiào yuán yī bǎo píng zhèng、 xué shēng zhèng， yī lóu fēn zhěn tái dēng jì pái duì jiù zhěn ó。','Em mang theo thẻ bảo hiểm y tế của trường, thẻ sinh viên, rồi đăng ký xếp hàng ở bàn phân loại tầng một để khám nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_03','V731','阮明',3,'校内医务室拿药可以直接医保报销，不用全额自费吗？','xiào nèi yī wù shì ná yào kě yǐ zhí jiē yī bǎo bào xiāo， bù yòng quán é zì fèi ma？','Lấy thuốc ở phòng y tế trong trường có được bảo hiểm y tế thanh toán luôn không, hay em phải trả toàn bộ tiền túi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_04','V731','护士',4,'基础感冒、消炎药品报销七成，美容、滋补类药品不参与报销。','jī chǔ gǎn mào、 xiāo yán yào pǐn bào xiāo qī chéng， měi róng、 zī bǔ lèi yào pǐn bù cān yù bào xiāo。','Thuốc cảm cúm cơ bản, thuốc kháng viêm thì bảo hiểm chi trả bảy mươi phần trăm, còn thuốc làm đẹp, thuốc bổ thì không nằm trong diện thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_05','V731','阮明',5,'就诊之后如果需要输液，也是同样报销比例对吗？','jiù zhěn zhī hòu rú guǒ xū yào shū yè， yě shì tóng yàng bào xiāo bǐ lì duì ma？','Sau khi khám nếu cần truyền dịch thì cũng được thanh toán theo tỷ lệ như vậy đúng không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_06','V731','护士',6,'普通诊疗、输液均纳入医保报销，仅自费耗材除外。','pǔ tōng zhěn liáo、 shū yè jūn nà rù yī bǎo bào xiāo， jǐn zì fèi hào cái chú wài。','Khám bệnh thông thường và truyền dịch đều được đưa vào diện bảo hiểm chi trả, chỉ có vật tư tự chi trả là ngoại lệ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_07','V731','阮明',7,'我带好证件，现在登记排队问诊拿药。','wǒ dài hǎo zhèng jiàn， xiàn zài dēng jì pái duì wèn zhěn ná yào。','Em mang đủ giấy tờ rồi, giờ em đi đăng ký xếp hàng khám và lấy thuốc đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT732','SSH5','宿舍线上缴纳水电费，系统缴费失败咨询后勤',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V732','SIT732','P1','twist','ban_chinh_thuc',NULL,'校园线上缴费系统夜间服务器负载高容易卡顿，水电欠费设有三天缓冲期，不会立刻断供。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_01','V732','阮明',1,'您好，线上小程序缴纳宿舍电费，提交支付一直提示缴费失败。','nín hǎo， xiàn shàng xiǎo chéng xù jiǎo nà sù shè diàn fèi， tí jiāo zhī fù yì zhí tí shì jiǎo fèi shī bài。','Chào chị, em đóng tiền điện ký túc xá qua mini app trên mạng, mà bấm thanh toán cứ báo lỗi đóng tiền không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_02','V732','后勤客服',2,'核对宿舍房间编号，近期是否输入错误楼栋号导致匹配失败？','hé duì sù shè fáng jiān biān hào， jìn qī shì fǒu shū rù cuò wù lóu dòng hào dǎo zhì pǐ pèi shī bài？','Em kiểm tra lại số phòng ký túc xá xem, gần đây có nhập nhầm số tòa nhà nên không khớp được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_03','V732','阮明',3,'楼栋、房间号全部核对无误，银行卡扣款短信也没有收到嘛。','lóu dòng、 fáng jiān hào quán bù hé duì wú wù， yín háng kǎ kòu kuǎn duǎn xìn yě méi yǒu shōu dào ma。','Tòa nhà, số phòng em đối chiếu lại hết rồi, không sai đâu, mà tin nhắn trừ tiền từ thẻ ngân hàng cũng không nhận được luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_04','V732','后勤客服',4,'小程序晚间服务器拥堵，夜间零点至早八点系统不稳定。','xiǎo chéng xù wǎn jiān fú wù qì yōng dǔ， yè jiān líng diǎn zhì zǎo bā diǎn xì tǒng bù wěn dìng。','Buổi tối máy chủ mini app hay bị nghẽn, từ nửa đêm đến tám giờ sáng hệ thống không ổn định lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_05','V732','阮明',5,'那我明天上午再重新提交缴费，不会产生停水断电吧？','nà wǒ míng tiān shàng wǔ zài chóng xīn tí jiāo jiǎo fèi， bú huì chǎn shēng tíng shuǐ duàn diàn ba？','Vậy sáng mai em nộp lại tiền, chắc không bị cắt nước cắt điện chứ chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_06','V732','后勤客服',6,'宿舍水电欠费缓冲三天，三天内缴费不会切断供应。','sù shè shuǐ diàn qiàn fèi huǎn chōng sān tiān， sān tiān nèi jiǎo fèi bú huì qiē duàn gōng yìng。','Tiền điện nước ký túc xá có thời gian gia hạn ba ngày, trong ba ngày đóng tiền thì không bị cắt cung cấp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_07','V732','阮明',7,'明天一早完成缴费，避免宿舍水电临时关停。','míng tiān yī zǎo wán chéng jiǎo fèi， bì miǎn sù shè shuǐ diàn lín shí guān tíng。','Sáng mai em đóng tiền xong sớm luôn, để tránh bị cắt điện nước ký túc xá tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT733','SSH5','校园校园网账号欠费断网，线上续费恢复网络',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V733','SIT733','P1','suon_se','tuy_y',NULL,'校园内网按月计费，欠费立刻断网，校内图书馆、论文数据库均依托校园网访问。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_01','V733','阮明',1,'电脑显示校园网欠费停机，网页视频、学习软件全都打不开。','diàn nǎo xiǎn shì xiào yuán wǎng qiàn fèi tíng jī， wǎng yè shì pín、 xué xí ruǎn jiàn quán dōu dǎ bù kāi。','Máy tính báo mạng trường bị nợ phí nên bị cắt kết nối, web, video, phần mềm học tập gì cũng không mở được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_02','V733','小林',2,'打开校园网小程序，输入学号就能线上充值续费啦。','dǎ kāi xiào yuán wǎng xiǎo chéng xù， shū rù xué hào jiù néng xiàn shàng chōng zhí xù fèi la。','Cậu mở app mạng trường lên, nhập mã số sinh viên vào là nạp tiền gia hạn online được ngay.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_03','V733','阮明',3,'包月套餐三十元，充值之后是立刻恢复网络吗？','bāo yuè tào cān sān shí yuán， chōng zhí zhī hòu shì lì kè huī fù wǎng luò ma？','Gói cước tháng ba mươi tệ, nạp xong là mạng có lại liền hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_04','V733','小林',4,'充值成功十秒内自动联网，不用重启电脑路由器。','chōng zhí chéng gōng shí miǎo nèi zì dòng lián wǎng， bù yòng chóng qǐ diàn nǎo lù yóu qì。','Nạp thành công là trong vòng mười giây tự động có mạng lại, không cần khởi động lại máy tính hay router đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_05','V733','阮明',5,'要是忘记续费，断网之后校内论文数据库也没法访问？','yào shì wàng jì xù fèi， duàn wǎng zhī hòu xiào nèi lùn wén shù jù kù yě méi fǎ fǎng wèn？','Nếu lỡ quên gia hạn, mất mạng rồi thì thư viện luận văn nội bộ trong trường cũng không vào được luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_06','V733','小林',6,'没错，内网文献库依赖校园网，断网完全无法登录查阅。','méi cuò， nèi wǎng wén xiàn kù yī lài xiào yuán wǎng， duàn wǎng wán quán wú fǎ dēng lù chá yuè。','Đúng vậy đó, kho tài liệu nội bộ phụ thuộc vào mạng trường, mất mạng là chịu, không đăng nhập tra cứu được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_07','V733','阮明',7,'我现在线上充值续费，恢复网络继续写作业。','wǒ xiàn zài xiàn shàng chōng zhí xù fèi， huī fù wǎng luò jì xù xiě zuò yè。','Giờ tớ nạp tiền gia hạn online luôn đây, có mạng lại rồi làm bài tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT734','SSH5','手机话费余额不足停机，便利店线下充值缴费',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V734','SIT734','P1','suon_se','tuy_y',NULL,'国内线下便利店可办理手机话费充值，适合线上支付故障、手机停机无法收验证码的情况。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_01','V734','阮明',1,'你好，手机停机没法收短信，能不能线下充值话费？','nǐ hǎo， shǒu jī tíng jī méi fǎ shōu duǎn xìn， néng bù néng xiàn xià chōng zhí huà fèi？','Chào chị, điện thoại em bị khóa máy không nhận được tin nhắn, chị cho em nạp tiền trực tiếp ở đây được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_02','V734','便利店店员',2,'支持五十、一百面额线下充值，输入手机号就能充值哈。','zhī chí wǔ shí、 yì bǎi miàn é xiàn xià chōng zhí， shū rù shǒu jī hào jiù néng chōng zhí hā。','Chỗ chị nhận nạp mệnh giá năm mươi, một trăm trực tiếp, cứ đọc số điện thoại là nạp được liền nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_03','V734','阮明',3,'充值成功之后，多久手机能恢复通话、短信功能？','chōng zhí chéng gōng zhī hòu， duō jiǔ shǒu jī néng huī fù tōng huà、 duǎn xìn gōng néng？','Nạp xong thì bao lâu máy mới gọi được, nhắn tin lại được vậy chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_04','V734','便利店店员',4,'充值到账两分钟内自动复机，不用重启手机。','chōng zhí dào zhàng liǎng fēn zhōng nèi zì dòng fù jī， bù yòng chóng qǐ shǒu jī。','Tiền vào tài khoản là trong hai phút tự động mở máy lại, không cần khởi động lại điện thoại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_05','V734','阮明',5,'那充值一百元，报我的手机号码给你。','nà chōng zhí yì bǎi yuán， bào wǒ de shǒu jī hào mǎ gěi nǐ。','Vậy chị nạp cho em một trăm, em đọc số điện thoại cho chị nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_06','V734','便利店店员',6,'充值完成，手机很快就能恢复正常通讯。','chōng zhí wán chéng， shǒu jī hěn kuài jiù néng huī fù zhèng cháng tōng xùn。','Nạp xong rồi đó, máy sẽ nhanh chóng liên lạc bình thường trở lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_07','V734','阮明',7,'太好了，终于可以联系家人和同学。','tài hǎo le， zhōng yú kě yǐ lián xì jiā rén hé tóng xué。','Tuyệt quá, cuối cùng cũng liên lạc được với gia đình với bạn học rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT735','SSH5','干洗店送洗衣物，询问污渍清洗、取件时效',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V735','SIT735','P1','twist','tuy_y',NULL,'重度油污、陈年污渍无法保证完全洗净，干洗店会根据清洗效果调整收费，提前告知顾客预期。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_01','V735','阮明',1,'你好，这件外套沾了油污，送过来干洗能完全洗掉污渍吗？','nǐ hǎo， zhè jiàn wài tào zhān le yóu wū， sòng guò lái gān xǐ néng wán quán xǐ diào wū zì ma？','Chào anh, cái áo khoác này dính dầu mỡ, đem giặt khô ở đây có sạch hết được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_02','V735','干洗店员',2,'大面积油污需要特殊去渍剂，不一定能彻底清除干净。','dà miàn jī yóu wū xū yào tè shū qù zì jì， bù yí dìng néng chè dǐ qīng chú gān jìng。','Vết dầu loang diện rộng như này cần dùng chất tẩy chuyên dụng, chưa chắc đã sạch hoàn toàn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_03','V735','阮明',3,'要是洗完还有残留油污，会收取全套干洗费用嘛？','yào shì xǐ wán hái yǒu cán liú yóu wū， huì shōu qǔ quán tào gān xǐ fèi yòng ma？','Vậy nếu giặt xong mà vẫn còn dính dầu, tiệm có tính đủ tiền giặt khô không ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_04','V735','干洗店员',4,'尽力清洗，无法去除重度污渍仅收取基础洗护半价嘛。','jìn lì qīng xǐ， wú fǎ qù chú zhòng dù wū zì jǐn shōu qǔ jī chǔ xǐ hù bàn jià ma。','Bên anh sẽ cố hết sức để giặt, nếu vết bẩn nặng quá không tẩy được thì chỉ tính nửa giá giặt cơ bản thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_05','V735','阮明',5,'正常洗护多久可以取件，三天后过来取来得及吗？','zhèng cháng xǐ hù duō jiǔ kě yǐ qǔ jiàn， sān tiān hòu guò lái qǔ lái de jí ma？','Giặt bình thường thì mất mấy ngày lấy được, ba ngày sau em quay lại lấy có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_06','V735','干洗店员',6,'标准洗护两天完工，三天来取完全没有问题。','biāo zhǔn xǐ hù liǎng tiān wán gōng， sān tiān lái qǔ wán quán méi yǒu wèn tí。','Giặt tiêu chuẩn hai ngày là xong rồi, ba ngày sau lấy hoàn toàn thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_07','V735','阮明',7,'那我把外套留在店里，后天下午前来取衣服。','nà wǒ bǎ wài tào liú zài diàn lǐ， hòu tiān xià wǔ qián lái qǔ yī fú。','Vậy em để áo lại tiệm nha, chiều mốt em quay lại lấy áo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT736','SSH5','上门保洁预约，和保洁阿姨确认清洁范围与时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V736','SIT736','P1','suon_se','ban_chinh_thuc',NULL,'上门保洁分基础清扫、深度清洁两类服务，厨房重度油污清理属于额外增值服务，需要增加时长与费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_01','V736','阮明',1,'阿姨，我预约两小时全屋保洁，跟您确认清洁区域吧。','ā yí， wǒ yù yuē liǎng xiǎo shí quán wū bǎo jié， gēn nín què rèn qīng jié qū yù ba。','Chị ơi, em đặt hai tiếng dọn dẹp toàn bộ nhà, để em xác nhận lại khu vực dọn với chị nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_02','V736','保洁阿姨',2,'客厅、卧室、卫生间常规清扫，厨房油污深度清洗需要额外加时。','kè tīng、 wò shì、 wèi shēng jiān cháng guī qīng sǎo， chú fáng yóu wū shēn dù qīng xǐ xū yào é wài jiā shí。','Phòng khách, phòng ngủ, nhà vệ sinh thì lau dọn bình thường, còn bếp mà muốn tẩy sạch dầu mỡ thì cần tính thêm giờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_03','V736','阮明',3,'厨房简单擦拭台面即可，不用深度清理厚重油污。','chú fáng jiǎn dān cā shì tái miàn jí kě， bù yòng shēn dù qīng lǐ hòu zhòng yóu wū。','Bếp thì chỉ cần lau sơ mặt bàn thôi, không cần dọn kỹ hết lớp dầu mỡ dày đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_04','V736','保洁阿姨',4,'两小时只做基础除尘拖地，不含重度厨房油污清理。','liǎng xiǎo shí zhǐ zuò jī chǔ chú chén tuō dì， bù hán zhòng dù chú fáng yóu wū qīng lǐ。','Hai tiếng thì chỉ làm phần lau bụi, lau nhà cơ bản thôi, không bao gồm dọn dầu mỡ nặng trong bếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_05','V736','阮明',5,'本周六上午九点上门，我提前把桌面杂物收纳好。','běn zhōu liù shàng wǔ jiǔ diǎn shàng mén， wǒ tí qián bǎ zhuō miàn zá wù shōu nà hǎo。','Thứ Bảy này chín giờ sáng chị đến nhé, em sẽ dọn đồ đạc trên bàn gọn gàng trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_06','V736','保洁阿姨',6,'到点准时上门，杂物收纳干净清洁效率更高。','dào diǎn zhǔn shí shàng mén， zá wù shōu nà gān jìng qīng jié xiào lǜ gèng gāo。','Vậy đúng giờ chị sẽ đến, đồ đạc gọn gàng thì dọn dẹp cũng nhanh và hiệu quả hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_07','V736','阮明',7,'我提前整理房间，方便阿姨快速完成全屋保洁。','wǒ tí qián zhěng lǐ fáng jiān， fāng biàn ā yí kuài sù wán chéng quán wū bǎo jié。','Em sẽ dọn phòng trước, để chị tiện làm sạch cả nhà cho nhanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT737','SSH6','报名校园羽毛球社团，咨询会费、活动固定时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V737','SIT737','P1','suon_se','tuy_y',NULL,'国内高校学生社团会费低廉，仅用于活动耗材、场地租赁，定期开展免费校内文体活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_01','V737','阮明',1,'学长，我想加入羽毛球社团，请问入社需要缴纳会费吗？','xué zhǎng， wǒ xiǎng jiā rù yǔ máo qiú shè tuán， qǐng wèn rù shè xū yào jiǎo nà huì fèi ma？','Anh ơi, em muốn tham gia câu lạc bộ cầu lông, vào câu lạc bộ có phải đóng hội phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_02','V737','学长',2,'一年二十元会费，全部用于采购羽毛球、场地租赁哦。','yī nián èr shí yuán huì fèi， quán bù yòng yú cǎi gòu yǔ máo qiú、 chǎng dì zū lìn ó。','Một năm hội phí hai mươi tệ, dùng hết để mua cầu lông với thuê sân đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_03','V737','阮明',3,'社团固定活动周几开展，是校内体育馆场地吗？','shè tuán gù dìng huó dòng zhōu jǐ kāi zhǎn， shì xiào nèi tǐ yù guǎn chǎng dì ma？','Câu lạc bộ sinh hoạt cố định vào thứ mấy vậy anh, có phải ở nhà thi đấu trong trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_04','V737','学长',4,'每周四傍晚六点到八点，校内羽毛球馆专属场地。','měi zhōu sì bàng wǎn liù diǎn dào bā diǎn， xiào nèi yǔ máo qiú guǎn zhuān shǔ chǎng dì。','Mỗi tối thứ Năm từ sáu đến tám giờ, ở nhà thi đấu cầu lông riêng trong trường luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_05','V737','阮明',5,'没有自带球拍，社团可以临时借用训练球拍吗？','méi yǒu zì dài qiú pāi， shè tuán kě yǐ lín shí jiè yòng xùn liàn qiú pāi ma？','Em không có vợt riêng, câu lạc bộ có cho mượn vợt tập tạm thời không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_06','V737','学长',6,'新人可免费借用公用球拍，长期参与建议自备球拍。','xīn rén kě miǎn fèi jiè yòng gōng yòng qiú pāi， cháng qī cān yù jiàn yì zì bèi qiú pāi。','Thành viên mới thì được mượn vợt chung miễn phí, còn tham gia lâu dài thì nên tự sắm vợt riêng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_07','V737','阮明',7,'我今天缴纳会费入社，周四准时参加社团活动。','wǒ jīn tiān jiǎo nà huì fèi rù shè， zhōu sì zhǔn shí cān jiā shè tuán huó dòng。','Vậy hôm nay em đóng hội phí vào câu lạc bộ luôn, thứ Năm em sẽ đến sinh hoạt đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT738','SSH6','校园操场运动扭伤，前往医务室简单处理伤口',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V738','SIT738','P1','twist','ban_chinh_thuc',NULL,'校内医务室跌打损伤、消炎外敷药品均可医保报销，运动受伤可免费冷敷理疗处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_01','V738','阮明',1,'护士，操场跑步崴到脚踝，现在肿胀疼痛没法正常走路。','hù shì， cāo chǎng pǎo bù wǎi dào jiǎo huái， xiàn zài zhǒng zhàng téng tòng méi fǎ zhèng cháng zǒu lù。','Cô ơi, em chạy ở sân vận động bị trẹo mắt cá chân, giờ sưng đau không đi lại bình thường được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_02','V738','护士',2,'先坐下抬高腿部冷敷消肿，我给你开外用消炎药膏。','xiān zuò xià tái gāo tuǐ bù lěng fū xiāo zhǒng， wǒ gěi nǐ kāi wài yòng xiāo yán yào gāo。','Em ngồi xuống, kê cao chân lên chườm lạnh cho giảm sưng, cô sẽ kê cho em thuốc mỡ kháng viêm bôi ngoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_03','V738','阮明',3,'冷敷需要持续多久，今晚还能正常下床行走吗？','lěng fū xū yào chí xù duō jiǔ， jīn wǎn hái néng zhèng cháng xià chuáng xíng zǒu ma？','Chườm lạnh cần bao lâu vậy cô, tối nay em có xuống giường đi lại bình thường được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_04','V738','护士',4,'连续冷敷二十分钟，三天之内尽量减少走路、剧烈运动嘛。','lián xù lěng fū èr shí fēn zhōng， sān tiān zhī nèi jǐn liàng jiǎn shǎo zǒu lù、 jù liè yùn dòng ma。','Chườm lạnh liên tục hai mươi phút, trong ba ngày cố gắng hạn chế đi lại, vận động mạnh nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_05','V738','阮明',5,'药膏医保可以报销吗，还是需要全额自费购买？','yào gāo yī bǎo kě yǐ bào xiāo ma， hái shì xū yào quán é zì fèi gòu mǎi？','Thuốc mỡ có được bảo hiểm y tế thanh toán không ạ, hay em phải tự trả toàn bộ tiền thuốc?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_06','V738','护士',6,'外用跌打药膏纳入学生医保，只需要自费三成费用。','wài yòng diē dǎ yào gāo nà rù xué shēng yī bǎo， zhǐ xū yào zì fèi sān chéng fèi yòng。','Thuốc mỡ trị bong gân được đưa vào bảo hiểm y tế sinh viên, em chỉ cần tự trả ba mươi phần trăm thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_07','V738','阮明',7,'我拿药之后回宿舍静养，不再剧烈运动加重扭伤。','wǒ ná yào zhī hòu huí sù shè jìng yǎng， bù zài jù liè yùn dòng jiā zhòng niǔ shāng。','Em lấy thuốc xong sẽ về ký túc xá nghỉ ngơi, không vận động mạnh nữa kẻo trẹo nặng thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT739','SSH6','咨询校园奖学金申请条件、提交材料截止日期',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V739','SIT739','P1','suon_se','chinh_thuc',NULL,'留学生奖学金对出勤率、期末分数有硬性门槛，逾期不接受补报，错过只能等待下一学年申报。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_01','V739','阮明',1,'老师您好，想咨询留学生校级奖学金的申请基础条件。','lǎo shī nín hǎo， xiǎng zī xún liú xué shēng xiào jí jiǎng xué jīn de shēn qǐng jī chǔ tiáo jiàn。','Chào thầy/cô, em muốn hỏi về điều kiện cơ bản để nộp đơn xin học bổng cấp trường dành cho lưu học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_02','V739','教务老师',2,'全年出勤率达标、期末平均分七十五分以上方可申报。','quán nián chū qín lǜ dá biāo、 qī mò píng jūn fēn qī shí wǔ fēn yǐ shàng fāng kě shēn bào。','Tỷ lệ chuyên cần cả năm phải đạt chuẩn, điểm trung bình học kỳ từ bảy mươi lăm điểm trở lên mới đủ điều kiện đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_03','V739','阮明',3,'申请需要提交成绩单、在校证明，截止提交日期是哪天？','shēn qǐng xū yào tí jiāo chéng jì dān、 zài xiào zhèng míng， jié zhǐ tí jiāo rì qī shì nǎ tiān？','Hồ sơ cần nộp bảng điểm, giấy xác nhận đang học, vậy hạn chót nộp hồ sơ là ngày nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_04','V739','教务老师',4,'本月二十五号下午五点关闭申报通道，逾期不予受理。','běn yuè èr shí wǔ hào xià wǔ wǔ diǎn guān bì shēn bào tōng dào， yú qī bù yǔ shòu lǐ。','Cổng đăng ký sẽ đóng lúc năm giờ chiều ngày hai mươi lăm tháng này, nộp trễ sẽ không được xét ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_05','V739','阮明',5,'材料线上系统提交，还是纸质复印件线下上交学院？','cái liào xiàn shàng xì tǒng tí jiāo， hái shì zhǐ zhì fù yìn jiàn xiàn xià shàng jiāo xué yuàn？','Hồ sơ nộp qua hệ thống online, hay là nộp bản giấy photo trực tiếp cho khoa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_06','V739','教务老师',6,'线上填报信息，纸质材料线下送至国际学院办公室。','xiàn shàng tián bào xìn xī， zhǐ zhì cái liào xiàn xià sòng zhì guó jì xué yuàn bàn gōng shì。','Điền thông tin online, còn bản giấy thì nộp trực tiếp tại văn phòng học viện quốc tế nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_07','V739','阮明',7,'我这周整理好全部材料，提前完成奖学金申报。','wǒ zhè zhōu zhěng lǐ hǎo quán bù cái liào， tí qián wán chéng jiǎng xué jīn shēn bào。','Vậy tuần này em sẽ chuẩn bị đầy đủ hồ sơ, hoàn thành đăng ký học bổng sớm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT740','SSH6','校内丢失水杯、雨伞，去失物招领处登记寻物',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V740','SIT740','P1','that_bai_nhe','tuy_y',NULL,'校园失物招领处仅短期保管遗失物品，超过一周无人认领会统一收纳，长期无人认领定期清理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_01','V740','阮明',1,'你好，我昨天操场丢失黑色水杯、折叠雨伞，前来登记寻物。','nǐ hǎo， wǒ zuó tiān cāo chǎng diū shī hēi sè shuǐ bēi、 zhé dié yǔ sǎn， qián lái dēng jì xún wù。','Chào anh/chị, hôm qua em làm mất bình nước màu đen và cây dù gấp ở sân vận động, em đến đăng ký tìm đồ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_02','V740','工作人员',2,'登记物品外观、丢失地点、你的联系方式，有人上交会通知你。','dēng jì wù pǐn wài guān、 diū shī dì diǎn、 nǐ de lián xì fāng shì， yǒu rén shàng jiāo huì tōng zhī nǐ。','Em đăng ký hình dạng đồ vật, chỗ mất, số điện thoại liên hệ của em, có ai nộp lên thì bên anh/chị sẽ báo cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_03','V740','阮明',3,'水杯侧面印有越南文字标识，雨伞是深蓝色，特征很明显。','shuǐ bēi cè miàn yìn yǒu yuè nán wén zì biāo shí， yǔ sǎn shì shēn lán sè， tè zhēng hěn míng xiǎn。','Bình nước có in chữ tiếng Việt ở mặt bên, còn dù thì màu xanh navy, đặc điểm khá rõ ràng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_04','V740','工作人员',4,'今日上交失物清单没有匹配物品，大概率还未被捡拾上交嘛。','jīn rì shàng jiāo shī wù qīng dān méi yǒu pǐ pèi wù pǐn， dà gài lǜ hái wèi bèi jiǎn shí shàng jiāo ma。','Danh sách đồ thất lạc nộp lên hôm nay không khớp món nào cả, chắc là chưa ai nhặt được nộp lên đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_05','V740','阮明',5,'要是之后有人送到招领处，麻烦打电话通知我过来领取。','yào shì zhī hòu yǒu rén sòng dào zhāo lǐng chù， má fán dǎ diàn huà tōng zhī wǒ guò lái lǐng qǔ。','Nếu sau này có ai đem nộp lên, phiền anh/chị gọi điện báo em đến nhận nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_06','V740','工作人员',6,'登记信息留存一周，一周无人认领物品统一清理存放。','dēng jì xìn xī liú cún yī zhōu， yī zhōu wú rén rèn lǐng wù pǐn tǒng yī qīng lǐ cún fàng。','Thông tin đăng ký sẽ lưu lại một tuần, sau một tuần không ai nhận thì đồ sẽ được gom lại lưu kho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_07','V740','阮明',7,'我三天后再来招领处询问，看看有没有捡到我的物品。','wǒ sān tiān hòu zài lái zhāo lǐng chù xún wèn， kàn kàn yǒu méi yǒu jiǎn dào wǒ de wù pǐn。','Ba ngày nữa em sẽ quay lại phòng tìm đồ hỏi thăm, xem có nhặt được đồ của em chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT801','SHT1','向同班同学借课件PPT，拷贝到自己电脑复习',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V801','SIT801','P1','suon_se','tuy_y',NULL,'国内课堂老师大多会课后分享电子课件，同学之间互相转发课件、笔记是很普遍的互助学习习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_01','V801','阮明',1,'苏雯，昨天专业课老师的课件我忘记拷贝，能发我一份PPT吗？','sū wén， zuó tiān zhuān yè kè lǎo shī de kè jiàn wǒ wàng jì kǎo bèi， néng fā wǒ yī fèn PPT ma？','Tô Văn ơi, hôm qua mình quên copy slide bài giảng chuyên ngành của thầy, cậu gửi cho mình bản PPT được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_02','V801','苏雯',2,'没问题，我把完整课件打包，微信文件传输发给你就行啦。','méi wèn tí， wǒ bǎ wán zhěng kè jiàn dǎ bāo， wēi xìn wén jiàn chuán shū fā gěi nǐ jiù xíng la。','Không vấn đề gì, mình đóng gói cả bộ slide lại rồi gửi qua truyền file WeChat cho cậu là được nè.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_03','V801','阮明',3,'文件内存很大，微信会不会压缩模糊里面的表格内容？','wén jiàn nèi cún hěn dà， wēi xìn huì bú huì yā suō mó hú lǐ miàn de biǎo gé nèi róng？','File nặng vậy WeChat có nén làm mờ mấy cái bảng biểu trong đó không ta?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_04','V801','苏雯',4,'我发原文件不压缩，要是打不开我再分享网盘链接给你呢。','wǒ fā yuán wén jiàn bù yā suō， yào shì dǎ bù kāi wǒ zài fēn xiǎng wǎng pán liàn jiē gěi nǐ ne。','Mình gửi file gốc không nén đâu, nếu mở không được thì mình chia sẻ link ổ đĩa mạng cho cậu nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_05','V801','阮明',5,'太好了，我今晚对照课件梳理今天课堂没听懂的知识点。','tài hǎo le， wǒ jīn wǎn duì zhào kè jiàn shū lǐ jīn tiān kè táng méi tīng dǒng de zhī shí diǎn。','Tuyệt quá, tối nay mình đối chiếu slide để rà lại mấy chỗ chưa hiểu trên lớp hôm nay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_06','V801','苏雯',6,'课件里标注了期末重点，复习的时候可以优先看标红部分。','kè jiàn lǐ biāo zhù le qī mò zhòng diǎn， fù xí de shí hòu kě yǐ yōu xiān kàn biāo hóng bù fèn。','Trong slide có đánh dấu trọng tâm cuối kỳ đó, lúc ôn thì ưu tiên xem phần bôi đỏ trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_07','V801','阮明',7,'太感谢你，有完整课件复习会轻松很多。','tài gǎn xiè nǐ， yǒu wán zhěng kè jiàn fù xí huì qīng sōng hěn duō。','Cảm ơn cậu nhiều lắm, có slide đầy đủ thì ôn bài nhẹ nhàng hơn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT802','SHT1','询问老师课堂录音是否允许，方便课后复盘知识点',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V802','SIT802','P1','twist','ban_chinh_thuc',NULL,'课堂自用录音一般老师都会许可，但传播授课录音、课件属于侵犯教学版权，会被制止。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_01','V802','阮明',1,'李老师，我汉语听力反应慢一点，请问上课可以手机录音吗？','lǐ lǎo shī， wǒ hàn yǔ tīng lì fǎn yìng màn yì diǎn， qǐng wèn shàng kè kě yǐ shǒu jī lù yīn ma？','Thầy Lý ơi, em nghe tiếng Trung phản xạ hơi chậm, thầy cho em ghi âm bài giảng được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_02','V802','李老师',2,'单纯自己课后复习录音是可以的，但禁止转发、上传网络平台。','dān chún zì jǐ kè hòu fù xí lù yīn shì kě yǐ de， dàn jìn zhǐ zhuǎn fā、 shàng chuán wǎng luò píng tái。','Chỉ tự ghi âm để ôn lại cho bản thân thì được, nhưng cấm chuyển phát cho người khác hay đăng lên mạng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_03','V802','阮明',3,'我只自己私下复盘，绝对不会分享录音给其他同学或者发到网上。','wǒ zhǐ zì jǐ sī xià fù pán， jué duì bú huì fēn xiǎng lù yīn gěi qí tā tóng xué huò zhě fā dào wǎng shàng。','Em chỉ tự nghe lại riêng thôi ạ, tuyệt đối không chia sẻ bản ghi âm cho bạn khác hay đăng lên mạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_04','V802','李老师',4,'还有一点，录音不能遮挡其他同学，手机音量一定要完全静音嘛。','hái yǒu yì diǎn， lù yīn bù néng zhē dǎng qí tā tóng xué， shǒu jī yīn liàng yí dìng yào wán quán jìng yīn ma。','Còn một điều nữa, ghi âm không được che khuất các bạn khác, và điện thoại phải để im lặng hoàn toàn nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_05','V802','阮明',5,'我把手机调成飞行模式，只开启本地录音，不会弹出消息打扰课堂。','wǒ bǎ shǒu jī diào chéng fēi xíng mó shì， zhǐ kāi qǐ běn dì lù yīn， bú huì dàn chū xiāo xī dǎ rǎo kè táng。','Em sẽ để điện thoại ở chế độ máy bay, chỉ bật ghi âm nội bộ thôi, sẽ không có thông báo hiện lên làm phiền lớp học đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_06','V802','李老师',6,'如果后期有听不懂的地方，结合录音再来办公室问我也可以。','rú guǒ hòu qī yǒu tīng bù dǒng de dì fāng， jié hé lù yīn zài lái bàn gōng shì wèn wǒ yě kě yǐ。','Nếu sau này có chỗ nào không hiểu, em cứ kết hợp bản ghi âm rồi lên văn phòng hỏi thầy cũng được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L802_07','V802','阮明',7,'谢谢您允许录音，课后我能反复梳理课堂难点。','xiè xiè nín yǔn xǔ lù yīn， kè hòu wǒ néng fǎn fù shū lǐ kè táng nán diǎn。','Em cảm ơn thầy đã cho phép ghi âm, sau giờ học em có thể xem lại nhiều lần những chỗ khó ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT803','SHT1','课堂听不懂专业词汇，课后找同学一对一讲解',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V803','SIT803','P1','suon_se','tuy_y',NULL,'课后同学之间一对一拆解难点、互相讲题是高校主流互助学习方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_01','V803','阮明',1,'今天课上老师讲的几个贸易专业术语，我完全没理解含义啊。','jīn tiān kè shàng lǎo shī jiǎng de jǐ gè mào yì zhuān yè shù yǔ， wǒ wán quán méi lǐ jiě hán yì a。','Hôm nay trên lớp thầy giảng mấy thuật ngữ chuyên ngành thương mại, mình chả hiểu gì cả luôn á.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_02','V803','苏雯',2,'这几个词是国内外贸常用词汇，我举简单例子给你拆解意思。','zhè jǐ gè cí shì guó nèi wài mào cháng yòng cí huì， wǒ jǔ jiǎn dān lì zi gěi nǐ chāi jiě yì si。','Mấy từ này là từ vựng ngoại thương thông dụng trong nước á, để mình lấy ví dụ đơn giản phân tích cho cậu nghe.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_03','V803','阮明',3,'每个词汇搭配例句讲一遍，我才能分清使用场景对吧？','měi gè cí huì dā pèi lì jù jiǎng yī biàn， wǒ cái néng fēn qīng shǐ yòng chǎng jǐng duì ba？','Mỗi từ đi kèm câu ví dụ giảng qua một lượt, vậy mình mới phân biệt được ngữ cảnh sử dụng đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_04','V803','苏雯',4,'没错，我结合课本习题举例，方便你区分易混淆词汇。','méi cuò， wǒ jié hé kè běn xí tí jǔ lì， fāng biàn nǐ qū fēn yì hùn xiáo cí huì。','Đúng rồi đó, mình sẽ lấy ví dụ theo bài tập trong sách, để cậu dễ phân biệt mấy từ hay bị nhầm lẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_05','V803','阮明',5,'耽误你半小时休息时间，实在不好意思麻烦你。','dān wù nǐ bàn xiǎo shí xiū xī shí jiān， shí zài bù hǎo yì sī má fán nǐ。','Làm mất nửa tiếng nghỉ ngơi của cậu, thật ngại quá đi mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_06','V803','苏雯',6,'互相讲题很正常，之后我有语言难题也会找你帮忙。','hù xiāng jiǎng tí hěn zhèng cháng， zhī hòu wǒ yǒu yǔ yán nán tí yě huì zhǎo nǐ bāng máng。','Giảng bài qua lại cho nhau là chuyện bình thường mà, sau này mình có vướng mắc gì về ngôn ngữ cũng nhờ cậu giúp nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L803_07','V803','阮明',7,'太感谢，听完讲解一下子清晰多了。','tài gǎn xiè， tīng wán jiǎng jiě yī xià zi qīng xī duō le。','Cảm ơn cậu nhiều, nghe cậu giảng xong là thấy rõ ràng hẳn lên luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT804','SHT1','咨询老师课程平时分构成：出勤、课堂发言、小测占比',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V804','SIT804','P1','suon_se','ban_chinh_thuc',NULL,'国内大学课程普遍实行平时分+期末试卷综合打分，不会仅凭一次期末成绩定总分，鼓励日常课堂参与。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_01','V804','阮明',1,'老师，想向您咨询这门课期末总评分数的分配标准。','lǎo shī， xiǎng xiàng nín zī xún zhè mén kè qī mò zǒng píng fēn shù de fēn pèi biāo zhǔn。','Thầy ơi, em muốn hỏi thầy về cách tính điểm tổng kết cuối kỳ của môn này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_02','V804','李老师',2,'总评由三部分组成：出勤20%、课堂发言与随堂小测30%、期末试卷50%哦。','zǒng píng yóu sān bù fèn zǔ chéng： chū qín 20%、 kè táng fā yán yǔ suí táng xiǎo cè 30%、 qī mò shì juàn 50% ó。','Điểm tổng kết gồm ba phần: điểm danh 20%, phát biểu trên lớp cùng kiểm tra nhỏ 30%, bài thi cuối kỳ 50% nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_03','V804','阮明',3,'随堂小测每节课都会有吗，缺课一次会直接扣掉出勤分？','suí táng xiǎo cè měi jié kè dōu huì yǒu ma， quē kè yī cì huì zhí jiē kòu diào chū qín fēn？','Kiểm tra nhỏ buổi nào cũng có ạ, nghỉ học một buổi là bị trừ thẳng điểm chuyên cần luôn hả thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_04','V804','李老师',4,'无故缺课单次扣5分，请假备案不扣分；小测每月一次，错过可补。','wú gù quē kè dān cì kòu 5 fēn， qǐng jià bèi àn bù kòu fēn； xiǎo cè měi yuè yī cì， cuò guò kě bǔ。','Nghỉ không phép một lần trừ 5 điểm, có xin phép ghi nhận thì không bị trừ; kiểm tra nhỏ mỗi tháng một lần, lỡ có bỏ lỡ thì được thi bù.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_05','V804','阮明',5,'课堂发言只要主动回答问题，就能拿到对应的平时分吗？','kè táng fā yán zhǐ yào zhǔ dòng huí dá wèn tí， jiù néng ná dào duì yìng de píng shí fēn ma？','Phát biểu trên lớp chỉ cần chủ động trả lời câu hỏi là được tính điểm quá trình đúng không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_06','V804','李老师',6,'主动思考作答、有完整观点，都会记录课堂表现分。','zhǔ dòng sī kǎo zuò dá、 yǒu wán zhěng guān diǎn， dōu huì jì lù kè táng biǎo xiàn fēn。','Chỉ cần chủ động suy nghĩ trả lời, có quan điểm rõ ràng, đều được ghi nhận vào điểm thể hiện trên lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L804_07','V804','阮明',7,'我清楚分值规则了，之后多主动参与课堂互动。','wǒ qīng chǔ fēn zhí guī zé le， zhī hòu duō zhǔ dòng cān yù kè táng hù dòng。','Em đã hiểu rõ quy tắc tính điểm rồi ạ, sau này em sẽ tích cực tham gia phát biểu hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT805','SHT1','忘记带课本，和同桌共用一本书听课',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V805','SIT805','P1','twist','tuy_y',NULL,'课堂忘记带教材和同桌共用书本很常见，但不建议长期如此，会影响双方记笔记效率。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_01','V805','阮明',1,'糟糕，早上出门匆忙，把专业课课本落在宿舍了，能和你共用一本吗？','zāo gāo， zǎo shàng chū mén cōng máng， bǎ zhuān yè kè kè běn luò zài sù shè le， néng hé nǐ gòng yòng yī běn ma？','Chết rồi, sáng nay ra khỏi nhà vội quá, mình để quên sách chuyên ngành ở ký túc xá, cho mình xem chung sách với cậu được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_02','V805','小林',2,'可以一起看，不过书本放在中间，记笔记会有点挤不方便。','kě yǐ yì qǐ kàn， bù guò shū běn fàng zài zhōng jiān， jì bǐ jì huì yǒu diǎn jǐ bù fāng biàn。','Xem chung thì được, nhưng để sách ở giữa vậy ghi chép sẽ hơi chật, bất tiện đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_03','V805','阮明',3,'我只对照书页听讲解，笔记先记在草稿纸上，下课再整理。','wǒ zhǐ duì zhào shū yè tīng jiǎng jiě， bǐ jì xiān jì zài cǎo gǎo zhǐ shàng， xià kè zài zhěng lǐ。','Mình chỉ nhìn theo trang sách nghe giảng thôi, ghi chú thì tạm ghi ra giấy nháp, xuống lớp rồi sắp xếp lại sau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_04','V805','小林',4,'老师等下要勾画重点段落，我们分开两边各自标注会不会混乱嘛。','lǎo shī děng xià yào gōu huà zhòng diǎn duàn luò， wǒ men fēn kāi liǎng biān gè zì biāo zhù huì bú huì hùn luàn ma。','Lát nữa thầy sẽ khoanh vùng đoạn trọng tâm, hai đứa mỗi bên tự đánh dấu riêng vậy có bị loạn không ta.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_05','V805','阮明',5,'我手机拍课本页面，重点自己在照片上标记，不影响你看书。','wǒ shǒu jī pāi kè běn yè miàn， zhòng diǎn zì jǐ zài zhào piān shàng biāo jì， bù yǐng xiǎng nǐ kàn shū。','Mình chụp ảnh trang sách bằng điện thoại, phần trọng tâm tự đánh dấu trên ảnh, không ảnh hưởng cậu xem sách đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_06','V805','小林',6,'这样也行，有看不懂的段落随时指给我一起讨论。','zhè yàng yě xíng， yǒu kàn bù dǒng de duàn luò suí shí zhǐ gěi wǒ yì qǐ tǎo lùn。','Vậy cũng được, có đoạn nào cậu không hiểu thì cứ chỉ cho mình để cùng bàn luôn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L805_07','V805','阮明',7,'今天多亏你，不然整节课没法跟上老师进度。','jīn tiān duō kuī nǐ， bù rán zhěng jié kè méi fǎ gēn shàng lǎo shī jìn dù。','Hôm nay may có cậu giúp, không thì cả tiết học mình chẳng theo kịp tiến độ của thầy luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT806','SHT1','上课手机静音没做到，被老师提醒课堂纪律',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V806','SIT806','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂严格管控手机声响，震动、响铃都会被老师提醒，多次违规会扣除课堂表现分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_01','V806','阮明',1,'老师对不起，刚刚手机消息突然响铃，打断您讲课了。','lǎo shī duì bù qǐ， gāng gāng shǒu jī xiāo xī tū rán xiǎng líng， dǎ duàn nín jiǎng kè le。','Thầy ơi em xin lỗi, vừa nãy điện thoại em bỗng dưng đổ chuông, làm gián đoạn bài giảng của thầy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_02','V806','李老师',2,'课堂要求所有手机必须完全静音或关机，你忘记调整设置了？','kè táng yāo qiú suǒ yǒu shǒu jī bì xū wán quán jìng yīn huò guān jī， nǐ wàng jì tiáo zhěng shè zhì le？','Trên lớp yêu cầu tất cả điện thoại phải để im lặng hoàn toàn hoặc tắt máy, em quên chỉnh lại rồi à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_03','V806','阮明',3,'早上调了震动，没想到震动声响也很明显，干扰全班听课嘛。','zǎo shàng diào le zhèn dòng， méi xiǎng dào zhèn dòng shēng xiǎng yě hěn míng xiǎn， gān rǎo quán bān tīng kè ma。','Sáng nay em để chế độ rung, không ngờ tiếng rung cũng lớn vậy, làm ồn cả lớp nghe giảng luôn ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_04','V806','李老师',4,'一次警告不计入扣分，之后如果再出现声响会扣除课堂平时分。','yī cì jǐng gào bù jì rù kòu fēn， zhī hòu rú guǒ zài chū xiàn shēng xiǎng huì kòu chú kè táng píng shí fēn。','Lần này cảnh cáo thôi không tính vào điểm trừ, nhưng sau này nếu còn phát ra tiếng động sẽ bị trừ điểm quá trình trên lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_05','V806','阮明',5,'我现在直接关机，整节课不再开启手机接收消息。','wǒ xiàn zài zhí jiē guān jī， zhěng jié kè bù zài kāi qǐ shǒu jī jiē shōu xiāo xī。','Em tắt máy luôn bây giờ ạ, cả tiết học em sẽ không mở điện thoại nhận tin nhắn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_06','V806','李老师',6,'课堂需要安静的听讲环境，还请遵守班级课堂规定。','kè táng xū yào ān jìng de tīng jiǎng huán jìng， hái qǐng zūn shǒu bān jí kè táng guī dìng。','Lớp học cần một môi trường yên tĩnh để nghe giảng, mong em tuân thủ đúng quy định của lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L806_07','V806','阮明',7,'我记住教训，之后课前一定检查手机静音状态。','wǒ jì zhù jiào xùn， zhī hòu kè qián yí dìng jiǎn chá shǒu jī jìng yīn zhuàng tài。','Em xin ghi nhớ bài học này, sau này trước giờ học nhất định sẽ kiểm tra chế độ im lặng của điện thoại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT807','SHT1','咨询课程课外拓展阅读书目、图书馆馆藏位置',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V807','SIT807','P1','suon_se','ban_chinh_thuc',NULL,'大学专业课会配套拓展阅读书目，图书馆专业馆藏区集中存放对应书籍，支持学生课外自主拓展学习。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_01','V807','阮明',1,'老师，想提升专业水平，请问这门课配套拓展阅读书籍有哪些？','lǎo shī， xiǎng tí shēng zhuān yè shuǐ píng， qǐng wèn zhè mén kè pèi tào tuò zhǎn yuè dú shū jí yǒu nǎ xiē？','Thầy ơi, em muốn nâng cao trình độ chuyên ngành, thầy cho em hỏi môn này có những sách đọc thêm nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_02','V807','李老师',2,'我列三本核心参考书，全部存放在图书馆三楼外文专业区哦。','wǒ liè sān běn hé xīn cān kǎo shū， quán bù cún fàng zài tú shū guǎn sān lóu wài wén zhuān yè qū ó。','Thầy liệt kê ba cuốn sách tham khảo cốt lõi, tất cả đều để ở khu chuyên ngành ngoại văn tầng ba thư viện nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_03','V807','阮明',3,'这几本书可以外借带回家长期阅读，还是只能馆内阅览？','zhè jǐ běn shū kě yǐ wài jiè dài huí jiā zhǎng qī yuè dú， hái shì zhǐ néng guǎn nèi yuè lǎn？','Mấy cuốn này có được mượn về nhà đọc lâu dài không ạ, hay chỉ đọc tại thư viện thôi thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_04','V807','李老师',4,'均可借阅三十天，线上系统还能办理续借延长阅读时间。','jūn kě jiè yuè sān shí tiān， xiàn shàng xì tǒng hái néng bàn lǐ xù jiè yán cháng yuè dú shí jiān。','Đều được mượn trong ba mươi ngày, hệ thống online còn cho gia hạn thêm thời gian đọc nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_05','V807','阮明',5,'我记下书名，下课直接去图书馆检索借阅。','wǒ jì xià shū míng， xià kè zhí jiē qù tú shū guǎn jiǎn suǒ jiè yuè。','Em ghi lại tên sách rồi, xuống lớp em ra thư viện tra cứu mượn luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_06','V807','李老师',6,'阅读完有疑问，随时来办公室和我交流书中观点。','yuè dú wán yǒu yí wèn， suí shí lái bàn gōng shì hé wǒ jiāo liú shū zhōng guān diǎn。','Đọc xong có gì thắc mắc thì cứ lên văn phòng trao đổi quan điểm trong sách với thầy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L807_07','V807','阮明',7,'感谢老师推荐书目，对我的专业学习帮助很大。','gǎn xiè lǎo shī tuī jiàn shū mù， duì wǒ de zhuān yè xué xí bāng zhù hěn dà。','Em cảm ơn thầy đã gợi ý sách, giúp ích rất nhiều cho việc học chuyên ngành của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT808','SHT1','小组讨论时观点分歧，和组员温和协商统一思路',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V808','SIT808','P1','suon_se','tuy_y',NULL,'国内小组作业鼓励充分发表不同观点，通过讨论、分工、投票协商统一方案，不强行听从单一人员想法。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_01','V808','阮明',1,'我对小组报告案例选取有不同想法，和大家现在选定的方向不一样。','wǒ duì xiǎo zǔ bào gào àn lì xuǎn qǔ yǒu bù tóng xiǎng fǎ， hé dà jiā xiàn zài xuǎn dìng de fāng xiàng bù yí yàng。','Mình có ý tưởng khác về việc chọn case cho báo cáo nhóm, khác với hướng mà mọi người đang chọn hiện tại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_02','V808','苏雯',2,'你说说你的思路，我们一起对比两个方案的优劣再做决定。','nǐ shuō shuō nǐ de sī lù， wǒ men yì qǐ duì bǐ liǎng gè fāng àn de yōu liè zài zuò jué dìng。','Cậu nói thử ý tưởng của cậu xem, tụi mình so sánh ưu nhược điểm của hai phương án rồi quyết định luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_03','V808','阮明',3,'我选的案例数据更贴近留学生视角，更容易结合我们课堂所学。','wǒ xuǎn de àn lì shù jù gèng tiē jìn liú xué shēng shì jiǎo， gèng róng yì jié hé wǒ men kè táng suǒ xué。','Case mình chọn có dữ liệu sát với góc nhìn của du học sinh hơn, dễ liên hệ với những gì tụi mình học trên lớp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_04','V808','苏雯',4,'原有案例优势是资料充足，你的案例需要额外查找外文资料嘛。','yuán yǒu àn lì yōu shì shì zī liào chōng zú， nǐ de àn lì xū yào é wài chá zhǎo wài wén zī liào ma。','Case ban đầu ưu điểm là tài liệu đầy đủ sẵn, còn case của cậu thì phải tìm thêm tài liệu nước ngoài đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_05','V808','阮明',5,'我可以负责全部外文资料检索，分担小组搜集素材的工作量。','wǒ kě yǐ fù zé quán bù wài wén zī liào jiǎn suǒ， fēn dān xiǎo zǔ sōu jí sù cái de gōng zuò liàng。','Mình có thể phụ trách toàn bộ phần tra cứu tài liệu nước ngoài, chia sẻ bớt khối lượng công việc thu thập tư liệu cho nhóm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_06','V808','苏雯',6,'那我们投票，多数人认可你的方案就调整报告选题。','nà wǒ men tóu piào， duō shù rén rèn kě nǐ de fāng àn jiù tiáo zhěng bào gào xuǎn tí。','Vậy tụi mình biểu quyết nhé, nếu đa số đồng ý phương án của cậu thì tụi mình đổi đề tài báo cáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L808_07','V808','阮明',7,'谢谢大家愿意一起讨论，综合所有人想法完善作业。','xiè xiè dà jiā yuàn yì yì qǐ tǎo lùn， zōng hé suǒ yǒu rén xiǎng fǎ wán shàn zuò yè。','Cảm ơn mọi người đã sẵn lòng cùng bàn bạc, tổng hợp ý kiến của mọi người để bài làm hoàn thiện hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT809','SHT1','询问老师课堂发言加分规则，主动争取平时分',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V809','SIT809','P1','suon_se','ban_chinh_thuc',NULL,'大学课堂鼓励学生主动发言提问，以此折算平时分，平衡期末试卷单一考核的局限性。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_01','V809','阮明',1,'老师，想咨询课堂发言加分的详细规则，我想多争取平时表现分。','lǎo shī， xiǎng zī xún kè táng fā yán jiā fēn de xiáng xì guī zé， wǒ xiǎng duō zhēng qǔ píng shí biǎo xiàn fēn。','Thầy ơi, em muốn hỏi rõ quy định cộng điểm phát biểu trên lớp, em muốn cố gắng kiếm thêm điểm chuyên cần ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_02','V809','李老师',2,'主动举手回答、提出有价值疑问、上台简短分享，都能累加课堂分。','zhǔ dòng jǔ shǒu huí dá、 tí chū yǒu jià zhí yí wèn、 shàng tái jiǎn duǎn fēn xiǎng， dōu néng lěi jiā kè táng fēn。','Chủ động giơ tay trả lời, đặt câu hỏi có giá trị, hay lên bảng chia sẻ ngắn gọn, đều được cộng dồn điểm trên lớp cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_03','V809','阮明',3,'每次发言加分分值相同，还是完整长篇回答分值更高？','měi cì fā yán jiā fēn fēn zhí xiāng tóng， hái shì wán zhěng cháng piān huí dá fēn zhí gèng gāo？','Mỗi lần phát biểu điểm cộng có bằng nhau không thầy, hay trả lời đầy đủ, dài thì điểm cao hơn ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_04','V809','李老师',4,'不看长短，只要独立思考、贴合课堂主题，每次统一加2分。','bù kàn cháng duǎn， zhǐ yào dú lì sī kǎo、 tiē hé kè táng zhǔ tí， měi cì tǒng yī jiā 2 fēn。','Không tính dài ngắn đâu, chỉ cần tự suy nghĩ độc lập, bám sát chủ đề bài học là mỗi lần cộng đều 2 điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_05','V809','阮明',5,'每节课最多能几次发言，有没有单次课堂加分上限？','měi jié kè zuì duō néng jǐ cì fā yán， yǒu méi yǒu dān cì kè táng jiā fēn shàng xiàn？','Mỗi tiết học tối đa được phát biểu mấy lần vậy thầy, có giới hạn điểm cộng cho một buổi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_06','V809','李老师',6,'无次数上限，只要不占用过多课堂时间均可主动发言。','wú cì shù shàng xiàn， zhǐ yào bù zhàn yòng guò duō kè táng shí jiān jūn kě zhǔ dòng fā yán。','Không giới hạn số lần, miễn là đừng chiếm quá nhiều thời gian lớp học thì cứ chủ động phát biểu thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L809_07','V809','阮明',7,'之后每节课我主动思考提问、回答，积极参与课堂互动。','zhī hòu měi jié kè wǒ zhǔ dòng sī kǎo tí wèn、 huí dá， jī jí cān yù kè táng hù dòng。','Từ giờ mỗi tiết học em sẽ chủ động suy nghĩ, đặt câu hỏi, trả lời, tích cực tham gia tương tác trên lớp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT810','SHT2','论文引用格式不懂，请教专业课老师规范要求',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V810','SIT810','P1','twist','chinh_thuc',NULL,'国内高校毕业论文统一执行国家标准参考文献格式，自媒体网络内容认可度低，学术写作优先纸质期刊、专著。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_01','V810','阮明',1,'老师，毕业论文参考文献引用格式我始终把握不准，想向您请教标准。','lǎo shī， bì yè lùn wén cān kǎo wén xiàn yǐn yòng gé shì wǒ shǐ zhōng bǎ wò bù zhǔn， xiǎng xiàng nín qǐng jiào biāo zhǔn。','Thưa thầy, em vẫn chưa nắm chắc được cách trích dẫn tài liệu tham khảo trong luận văn tốt nghiệp, mong thầy chỉ dạy cho em chuẩn mực cụ thể ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_02','V810','李老师',2,'校内统一使用GB/T7714国家标准格式，课件最后附完整范例。','xiào nèi tǒng yī shǐ yòng GB/T7714 guó jiā biāo zhǔn gé shì， kè jiàn zuì hòu fù wán zhěng fàn lì。','Trong trường thống nhất dùng định dạng theo tiêu chuẩn quốc gia GB/T7714, cuối slide bài giảng có kèm ví dụ đầy đủ rồi đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_03','V810','阮明',3,'外文书籍、期刊、网页资料三种文献格式区分很大对吗？','wài wén shū jí、 qī kān、 wǎng yè zī liào sān zhǒng wén xiàn gé shì qū fēn hěn dà duì ma？','Ba loại tài liệu là sách nước ngoài, tạp chí và tài liệu trên mạng có cách trình bày khác nhau nhiều đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_04','V810','李老师',4,'网页自媒体资源不建议大量引用，书籍、正规期刊优先使用嘛。','wǎng yè zì méi tǐ zī yuán bù jiàn yì dà liàng yǐn yòng， shū jí、 zhèng guī qī kān yōu xiān shǐ yòng ma。','Tài liệu từ các trang mạng tự phát thì không nên trích dẫn nhiều, nên ưu tiên dùng sách và tạp chí chính thống hơn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_05','V810','阮明',5,'我按照课件范例调整格式，修改完成后能麻烦您帮忙检查一遍吗？','wǒ àn zhào kè jiàn fàn lì tiáo zhěng gé shì， xiū gǎi wán chéng hòu néng má fán nín bāng máng jiǎn chá yī biàn ma？','Em sẽ chỉnh sửa theo đúng mẫu trong slide bài giảng, sau khi sửa xong phiền thầy giúp em kiểm tra lại một lượt được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_06','V810','李老师',6,'初稿定稿前可以发我线上预览，指出格式错误再修改。','chū gǎo dìng gǎo qián kě yǐ fā wǒ xiàn shàng yù lǎn， zhǐ chū gé shì cuò wù zài xiū gǎi。','Trước khi hoàn thiện bản cuối em có thể gửi bản xem trước cho thầy qua mạng, thầy sẽ chỉ ra chỗ sai định dạng để em sửa lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L810_07','V810','阮明',7,'谢谢您耐心指导引用规范，避免论文大量格式扣分。','xiè xiè nín nài xīn zhǐ dǎo yǐn yòng guī fàn， bì miǎn lùn wén dà liàng gé shì kòu fēn。','Em xin cảm ơn thầy đã kiên nhẫn hướng dẫn quy chuẩn trích dẫn, giúp em tránh bị trừ điểm định dạng nhiều trong luận văn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT811','SHT2','查重重复率超标，咨询老师降重修改方法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V811','SIT811','P1','that_bai_nhe','ban_chinh_thuc',NULL,'高校毕业论文查重有硬性重复率阈值，复制粘贴原文会判定学术不端，必须自行转述降重。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_01','V811','阮明',1,'老师，我的初稿论文查重重复率超过30%，达不到学校合格标准。','lǎo shī， wǒ de chū gǎo lùn wén chá chóng chóng fù lǜ chāo guò 30%， dá bú dào xué xiào hé gé biāo zhǔn。','Thầy ơi, bản nháp luận văn của em bị trùng lặp hơn 30%, chưa đạt tiêu chuẩn của trường ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_02','V811','李老师',2,'合格重复率要求控制在20%以内，超标需要大面积改写降重。','hé gé chóng fù lǜ yāo qiú kòng zhì zài 20% yǐ nèi， chāo biāo xū yào dà miàn jī gǎi xiě jiàng zhòng。','Tỷ lệ trùng lặp đạt yêu cầu phải kiểm soát dưới 20%, vượt mức thì phải viết lại phần lớn để giảm trùng lặp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_03','V811','阮明',3,'我只是直接摘抄文献句子，不清楚转述改写的技巧啊。','wǒ zhǐ shì zhí jiē zhāi chāo wén xiàn jù zi， bù qīng chǔ zhuǎn shù gǎi xiě de jì qiǎo a。','Em chỉ sao chép trực tiếp câu chữ trong tài liệu thôi, chưa rõ kỹ thuật diễn đạt lại theo ý mình ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_04','V811','李老师',4,'不能简单替换同义词，要调整句子语序、拆分长句、补充自己的分析嘛。','bù néng jiǎn dān tì huàn tóng yì cí， yào tiáo zhěng jù zi yǔ xù、 chāi fēn cháng jù、 bǔ chōng zì jǐ de fēn xī ma。','Không thể chỉ đơn giản thay từ đồng nghĩa đâu, phải điều chỉnh trật tự câu, tách câu dài ra, rồi bổ sung thêm phân tích của riêng mình vào nữa chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_05','V811','阮明',5,'图表数据、公式部分会不会计入重复率，需要重新绘制吗？','tú biǎo shù jù、 gōng shì bù fèn huì bú huì jì rù chóng fù lǜ， xū yào chóng xīn huì zhì ma？','Phần biểu đồ, số liệu, công thức có bị tính vào tỷ lệ trùng lặp không ạ, có cần vẽ lại không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_06','V811','李老师',6,'通用公式不计入，文字分析段落必须全部重新转述改写。','tōng yòng gōng shì bù jì rù， wén zì fēn xī duàn luò bì xū quán bù chóng xīn zhuǎn shù gǎi xiě。','Công thức chung thì không tính vào, còn các đoạn phân tích văn bản thì bắt buộc phải viết lại toàn bộ theo cách diễn đạt riêng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L811_07','V811','阮明',7,'我按照您的方法逐段改写，修改完成后再次提交查重。','wǒ àn zhào nín de fāng fǎ zhú duàn gǎi xiě， xiū gǎi wán chéng hòu zài cì tí jiāo chá zhòng。','Em sẽ viết lại từng đoạn theo cách thầy hướng dẫn, sửa xong sẽ nộp kiểm tra trùng lặp lại lần nữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT812','SHT2','找不到外文参考文献，求助图书馆馆员检索外文数据库',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V812','SIT812','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆购买多语种外文数据库，仅校园内网、校园VPN可免费下载全文外文文献。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_01','V812','阮明',1,'老师，我写论文需要越南、东南亚相关外文文献，自己检索不到。','lǎo shī， wǒ xiě lùn wén xū yào yuè nán、 dōng nán yà xiāng guān wài wén wén xiàn， zì jǐ jiǎn suǒ bú dào。','Chị ơi, em cần tài liệu nước ngoài liên quan đến Việt Nam và Đông Nam Á để viết luận văn nhưng tự tìm không ra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_02','V812','王馆员',2,'校内开通多国外文数据库，我带你进入外文检索专属页面。','xiào nèi kāi tōng duō guó wài wén shù jù kù， wǒ dài nǐ jìn rù wài wén jiǎn suǒ zhuān shǔ yè miàn。','Trường mình có mở nhiều cơ sở dữ liệu ngoại văn, chị dẫn em vào trang tìm kiếm ngoại văn chuyên dụng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_03','V812','阮明',3,'输入关键词只能检索中文文献，需要切换语种检索入口对吧？','shū rù guān jiàn cí zhǐ néng jiǎn suǒ zhōng wén wén xiàn， xū yào qiè huàn yǔ zhǒng jiǎn suǒ rù kǒu duì ba？','Em nhập từ khóa chỉ tìm ra tài liệu tiếng Trung thôi, phải chuyển sang cổng tìm kiếm ngôn ngữ khác đúng không chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_04','V812','王馆员',4,'没错，切换外文语种后，限定地区、出版年份缩小检索范围。','méi cuò， qiè huàn wài wén yǔ zhǒng hòu， xiàn dìng dì qū、 chū bǎn nián fèn suō xiǎo jiǎn suǒ fàn wéi。','Đúng rồi đó, sau khi chuyển sang ngôn ngữ nước ngoài thì em có thể giới hạn khu vực, năm xuất bản để thu hẹp phạm vi tìm kiếm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_05','V812','阮明',5,'检索到的外文文献可以直接下载全文PDF吗？','jiǎn suǒ dào de wài wén wén xiàn kě yǐ zhí jiē xià zài quán wén PDF ma？','Tài liệu tìm được có thể tải trực tiếp bản PDF đầy đủ luôn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_06','V812','王馆员',6,'校内IP可免费下载，校外需要登录校园网VPN访问数据库。','xiào nèi IP kě miǎn fèi xià zài， xiào wài xū yào dēng lù xiào yuán wǎng VPN fǎng wèn shù jù kù。','Dùng IP trong trường thì tải miễn phí, còn ở ngoài trường thì phải đăng nhập VPN mạng trường mới truy cập được cơ sở dữ liệu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L812_07','V812','阮明',7,'麻烦您带我操作一遍检索流程，之后我自己查找文献。','má fán nín dài wǒ cāo zuò yī biàn jiǎn suǒ liú chéng， zhī hòu wǒ zì jǐ chá zhǎo wén xiàn。','Phiền chị dẫn em thao tác thử một lượt quy trình tìm kiếm, sau đó em sẽ tự tìm tài liệu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT813','SHT2','打印论文装订格式错误，打印店重新调整排版',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V813','SIT813','P1','twist','tuy_y',NULL,'各学院毕业论文有统一打印排版模板，页眉、行距、页边距、装订线均有硬性规范，打印店常备模板供学生使用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_01','V813','阮明',1,'你好，刚打印的毕业论文装订不对，页码、页眉格式不符合学院要求。','nǐ hǎo， gāng dǎ yìn de bì yè lùn wén zhuāng dìng bú duì， yè mǎ、 yè méi gé shì bù fú hé xué yuàn yāo qiú。','Chào anh, luận văn tốt nghiệp em vừa in đóng gáy bị sai rồi, số trang với tiêu đề đầu trang không đúng yêu cầu của khoa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_02','V813','店员',2,'学院有统一排版模板，你刚才直接上传文档没有套用标准模板嘛。','xué yuàn yǒu tǒng yī pái bǎn mú bǎn， nǐ gāng cái zhí jiē shàng chuán wén dàng méi yǒu tào yòng biāo zhǔn mú bǎn ma。','Khoa có mẫu trình bày thống nhất mà, lúc nãy em upload file trực tiếp không dùng mẫu chuẩn nên mới vậy đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_03','V813','阮明',3,'我不知道学校专用模板，直接用自己电脑里的格式导出打印了。','wǒ bù zhī dào xué xiào zhuān yòng mú bǎn， zhí jiē yòng zì jǐ diàn nǎo lǐ de gé shì dǎo chū dǎ yìn le。','Em không biết trường có mẫu riêng, cứ dùng luôn định dạng trong máy tính của mình để xuất ra in thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_04','V813','店员',4,'我现在套用学院官方模板重新调整，页眉、页码、行距全部统一修改。','wǒ xiàn zài tào yòng xué yuàn guān fāng mú bǎn chóng xīn tiáo zhěng， yè méi、 yè mǎ、 háng jù quán bù tǒng yī xiū gǎi。','Giờ anh áp mẫu chính thức của khoa vào chỉnh lại nhé, tiêu đề, số trang, giãn dòng gì cũng sửa lại đồng bộ hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_05','V813','阮明',5,'重新排版打印会额外收取一次打印费用吗？','chóng xīn pái bǎn dǎ yìn huì é wài shōu qǔ yī cì dǎ yìn fèi yòng ma？','In lại theo bố cục mới thì có tính thêm phí in lần nữa không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_06','V813','店员',6,'格式调整失误首次免费重打，多次修改才会叠加收费。','gé shì tiáo zhěng shī wù shǒu cì miǎn fèi zhòng dǎ， duō cì xiū gǎi cái huì dié jiā shōu fèi。','Lỗi định dạng thì lần đầu in lại miễn phí, sửa nhiều lần mới tính thêm phí thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L813_07','V813','阮明',7,'辛苦重新排版，调整完我检查无误再装订成册。','xīn kǔ chóng xīn pái bǎn， tiáo zhěng wán wǒ jiǎn chá wú wù zài zhuāng dìng chéng cè。','Phiền anh trình bày lại giúp em, chỉnh xong em kiểm tra không sai sót gì rồi mới đem đóng thành quyển.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT814','SHT2','小组论文有人拖延进度，和组员沟通制定截止时间表',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V814','SIT814','P1','suon_se','tuy_y',NULL,'国内小组作业普遍设置分段截止日期，避免临近交稿集体赶工、质量粗糙。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_01','V814','阮明',1,'距离小组论文提交只剩五天，有部分板块素材还没有收集完成。','jù lí xiǎo zǔ lùn wén tí jiāo zhǐ shèng wǔ tiān， yǒu bù fèn bǎn kuài sù cái hái méi yǒu shōu jí wán chéng。','Chỉ còn năm ngày nữa là nộp bài luận văn nhóm rồi mà vài phần tài liệu vẫn chưa thu thập xong.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_02','V814','苏雯',2,'有两位组员进度滞后，我们统一拆分每日任务，设置分段小截止期。','yǒu liǎng wèi zǔ yuán jìn dù zhì hòu， wǒ men tǒng yī chāi fēn měi rì rèn wù， shè zhì fēn duàn xiǎo jié zhǐ qī。','Có hai bạn trong nhóm bị chậm tiến độ, mình chia nhỏ công việc hàng ngày ra, đặt mốc thời hạn nhỏ theo từng giai đoạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_03','V814','小林',3,'每天晚上八点群内同步当日完成内容，避免最后一天集中赶工。','měi tiān wǎn shàng bā diǎn qún nèi tóng bù dāng rì wán chéng nèi róng， bì miǎn zuì hòu yī tiān jí zhōng gǎn gōng。','Mỗi tối tám giờ báo cáo tiến độ hoàn thành trong ngày trên nhóm, để tránh dồn hết vào ngày cuối làm gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_04','V814','阮明',4,'我负责外文文献翻译，最晚后天完成全部翻译素材交付。','wǒ fù zé wài wén wén xiàn fān yì， zuì wǎn hòu tiān wán chéng quán bù fān yì sù cái jiāo fù。','Mình phụ trách dịch tài liệu nước ngoài, chậm nhất là ngày kia sẽ hoàn thành nộp toàn bộ tài liệu dịch.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_05','V814','苏雯',5,'每人明确标注自己的分工与完成时间，逾期提前在群内说明困难。','měi rén míng què biāo zhù zì jǐ de fēn gōng yǔ wán chéng shí jiān， yú qī tí qián zài qún nèi shuō míng kùn nán。','Mỗi người ghi rõ phần việc và thời gian hoàn thành của mình, nếu trễ thì nói trước trong nhóm để mọi người biết khó khăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_06','V814','阮明',6,'如果有人遇到检索、写作难题，群内大家一起协助解决。','rú guǒ yǒu rén yù dào jiǎn suǒ、 xiě zuò nán tí， qún nèi dà jiā yì qǐ xié zhù jiě jué。','Nếu có bạn nào gặp khó khi tìm tài liệu hay viết bài thì cả nhóm cùng hỗ trợ giải quyết nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L814_07','V814','小林',7,'按时间表分段推进，保证论文完整、高质量按时上交。','àn shí jiān biǎo fēn duàn tuī jìn， bǎo zhèng lùn wén wán zhěng、 gāo zhì liàng àn shí shàng jiāo。','Cứ theo bảng thời gian mà làm từng bước, đảm bảo luận văn hoàn chỉnh, chất lượng và nộp đúng hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT815','SHT2','咨询论文致谢、摘要、关键词标准写作规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V815','SIT815','P1','suon_se','chinh_thuc',NULL,'国内本科毕业论文强制要求中文摘要+英文摘要、规范关键词、简短致谢，三部分有固定字数与格式标准。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_01','V815','阮明',1,'老师，想请教毕业论文摘要、关键词、致谢三段写作规范。','lǎo shī， xiǎng qǐng jiào bì yè lùn wén zhāi yào、 guān jiàn cí、 zhì xiè sān duàn xiě zuò guī fàn。','Thưa thầy, em muốn hỏi quy chuẩn viết ba phần tóm tắt, từ khóa và lời cảm ơn trong luận văn tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_02','V815','李老师',2,'摘要三百字以内，完整概括研究目的、方法、结论；关键词3-5个。','zhāi yào sān bǎi zì yǐ nèi， wán zhěng gài kuò yán jiū mù dì、 fāng fǎ、 jié lùn； guān jiàn cí 3-5 gè。','Tóm tắt viết trong khoảng ba trăm chữ, phải nêu đầy đủ mục đích nghiên cứu, phương pháp, kết luận; từ khóa từ 3 đến 5 từ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_03','V815','阮明',3,'致谢部分可以感谢家人、同学、授课老师，篇幅有限制吗？','zhì xiè bù fèn kě yǐ gǎn xiè jiā rén、 tóng xué、 shòu kè lǎo shī， piān fú yǒu xiàn zhì ma？','Phần cảm ơn có thể cảm ơn gia đình, bạn học, thầy cô giảng dạy, có giới hạn độ dài không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_04','V815','李老师',4,'致谢篇幅一页以内，简洁真诚即可，不用过度冗长抒情嘛。','zhì xiè piān fú yī yè yǐ nèi， jiǎn jié zhēn chéng jí kě， bù yòng guò dù rǒng cháng shū qíng ma。','Phần cảm ơn viết trong một trang thôi, ngắn gọn chân thành là được, không cần dài dòng bày tỏ cảm xúc quá đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_05','V815','阮明',5,'摘要需要中英文双语版本，翻译关键词也要对应准确？','zhāi yào xū yào zhōng yīng wén shuāng yǔ bǎn běn， fān yì guān jiàn cí yě yào duì yìng zhǔn què？','Tóm tắt có cần viết cả hai thứ tiếng Việt và tiếng Trung không ạ, từ khóa dịch cũng phải chính xác tương ứng phải không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_06','V815','李老师',6,'本科毕业论文摘要中英文对照，关键词逐词精准翻译。','běn kē bì yè lùn wén zhāi yào zhōng yīng wén duì zhào， guān jiàn cí zhú cí jīng zhǔn fān yì。','Luận văn tốt nghiệp đại học thì tóm tắt phải song ngữ đối chiếu, từ khóa dịch từng từ cho chính xác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L815_07','V815','阮明',7,'我按照规范撰写三段内容，初稿写完发给您检查。','wǒ àn zhào guī fàn zhuàn xiě sān duàn nèi róng， chū gǎo xiě wán fā gěi nín jiǎn chá。','Em sẽ viết ba phần theo đúng quy chuẩn, viết xong bản nháp sẽ gửi thầy kiểm tra ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT816','SHT2','电脑崩溃丢失作业初稿，向老师说明情况申请延后上交',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V816','SIT816','P1','twist','ban_chinh_thuc',NULL,'学生设备故障丢失作业属于合理客观事由，多数老师会适度放宽提交期限，但会提醒养成云端备份文件的习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_01','V816','阮明',1,'老师不好意思，昨晚电脑系统崩溃，存储的课程论文初稿全部丢失。','lǎo shī bù hǎo yì sī， zuó wǎn diàn nǎo xì tǒng bēng kuì， cún chǔ de kè chéng lùn wén chū gǎo quán bù diū shī。','Thầy ơi cho em xin lỗi, tối qua máy tính em bị sập hệ thống, toàn bộ bản nháp luận văn môn học lưu trên máy mất sạch rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_02','V816','李老师',2,'有没有云端备份、U盘备份，能找回一部分写作内容吗？','yǒu méi yǒu yún duān bèi fèn、U pán bèi fèn， néng zhǎo huí yī bù fèn xiě zuò nèi róng ma？','Em có sao lưu trên mây hay trong USB không, có tìm lại được phần nào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_03','V816','阮明',3,'没有及时云端同步，只保留少量手写草稿，完整电子版全部丢失嘛。','méi yǒu jí shí yún duān tóng bù， zhǐ bǎo liú shǎo liàng shǒu xiě cǎo gǎo， wán zhěng diàn zi bǎn quán bù diū shī ma。','Em không kịp đồng bộ lên mây, chỉ còn lại ít bản viết tay thôi, còn bản điện tử đầy đủ thì mất hết rồi thầy ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_04','V816','李老师',4,'正常截止时间今天下午，突发设备故障可以延后一天提交。','zhèng cháng jié zhǐ shí jiān jīn tiān xià wǔ， tū fā shè bèi gù zhàng kě yǐ yán hòu yī tiān tí jiāo。','Hạn nộp bình thường là chiều nay, nhưng thiết bị hỏng đột xuất thì có thể lùi lại một ngày để nộp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_05','V816','阮明',5,'我今天通宵重新撰写，明天上午一定完整上交定稿。','wǒ jīn tiān tōng xiāo chóng xīn zhuàn xiě， míng tiān shàng wǔ yí dìng wán zhěng shàng jiāo dìng gǎo。','Em sẽ thức đêm nay viết lại từ đầu, sáng mai chắc chắn sẽ nộp bản hoàn chỉnh cuối cùng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_06','V816','李老师',6,'下次重要作业记得云端备份，避免设备故障丢失全部文稿。','xià cì zhòng yào zuò yè jì de yún duān bèi fèn， bì miǎn shè bèi gù zhàng diū shī quán bù wén gǎo。','Lần sau làm bài quan trọng nhớ sao lưu lên mây, để tránh mất hết bài vở khi thiết bị hỏng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L816_07','V816','阮明',7,'感谢老师通融延后提交，之后一定养成备份文件的习惯。','gǎn xiè lǎo shī tōng róng yán hòu tí jiāo， zhī hòu yí dìng yǎng chéng bèi fèn wén jiàn de xí guàn。','Em cảm ơn thầy đã thông cảm cho lùi hạn nộp, từ nay em nhất định sẽ tập thói quen sao lưu file ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT817','SHT2','分不清直接引用、间接转述，找助教讲解论文写作规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V817','SIT817','P1','suon_se','tuy_y',NULL,'学术写作严格区分直接引用与间接转述，大段无标注摘抄会判定抄袭，大幅拉高查重重复率。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_01','V817','阮明',1,'学长，写论文分不清直接引用和间接转述，很容易查重超标。','xué zhǎng， xiě lùn wén fēn bù qīng zhí jiē yǐn yòng hé jiàn jiē zhuǎn shù， hěn róng yì chá zhòng chāo biāo。','Anh ơi, em viết luận văn cứ lẫn lộn giữa trích dẫn trực tiếp với thuật lại gián tiếp, dễ bị trùng lặp vượt ngưỡng lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_02','V817','张学长',2,'直接引用加引号标注页码，篇幅不能过长；转述改写句式无需引号。','zhí jiē yǐn yòng jiā yǐn hào biāo zhù yè mǎ， piān fú bù néng guò cháng； zhuǎn shù gǎi xiě jù shì wú xū yǐn hào。','Trích dẫn trực tiếp thì cho vào ngoặc kép kèm số trang, không được dài quá; còn thuật lại thì phải đổi cách diễn đạt, không cần ngoặc kép.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_03','V817','阮明',3,'大段文献观点只能全部改写转述，不能连续直接摘抄原文对吧？','dà duàn wén xiàn guān diǎn zhǐ néng quán bù gǎi xiě zhuǎn shù， bù néng lián xù zhí jiē zhāi chāo yuán wén duì ba？','Vậy những đoạn quan điểm dài trong tài liệu chỉ được viết lại toàn bộ theo cách của mình, không được chép nguyên văn liên tục đúng không anh?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_04','V817','张学长',4,'单次直接引用不能超过三行，长观点必须拆分转述融合自己分析。','dān cì zhí jiē yǐn yòng bù néng chāo guò sān xíng， zhǎng guān diǎn bì xū chāi fēn zhuǎn shù róng hé zì jǐ fēn xī。','Trích dẫn trực tiếp một lần không được quá ba dòng, quan điểm dài thì phải tách ra rồi lồng phân tích của mình vào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_05','V817','阮明',5,'我拿一段自己写的文字，麻烦你标出哪里引用格式出错。','wǒ ná yī duàn zì jǐ xiě de wén zì， má fán nǐ biāo chū nǎ lǐ yǐn yòng gé shì chū cuò。','Em có một đoạn tự viết, phiền anh chỉ giúp chỗ nào trích dẫn sai định dạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_06','V817','张学长',6,'没问题，逐句给你修改示范，方便你之后独立写作。','méi wèn tí， zhú jù gěi nǐ xiū gǎi shì fàn， fāng biàn nǐ zhī hòu dú lì xiě zuò。','Được thôi, anh sửa mẫu cho em từng câu một, để sau này em tự viết được luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L817_07','V817','阮明',7,'听完示范清晰很多，不会再出现引用违规问题。','tīng wán shì fàn qīng xī hěn duō， bú huì zài chū xiàn yǐn yòng wéi guī wèn tí。','Nghe anh làm mẫu xong em hiểu rõ hơn nhiều rồi, chắc không còn bị lỗi trích dẫn nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT818','SHT2','询问期末课程论文字数下限、允许浮动范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V818','SIT818','P1','suon_se','ban_chinh_thuc',NULL,'课程论文、毕业论文有硬性最低正文字数要求，篇幅不足会被判定内容单薄，大幅扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_01','V818','阮明',1,'老师，期末课程论文要求最低字数五千字，上下浮动多少算合格？','lǎo shī， qī mò kè chéng lùn wén yāo qiú zuì dī zì shù wǔ qiān zì， shàng xià fú dòng duō shǎo suàn hé gé？','Thưa cô, luận văn cuối kỳ yêu cầu tối thiểu năm nghìn chữ, dao động trên dưới bao nhiêu thì vẫn đạt ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_02','V818','李老师',2,'正文五千字不含摘要参考文献，上下浮动五百字以内都可接受哦。','zhèng wén wǔ qiān zì bù hán zhāi yào cān kǎo wén xiàn， shàng xià fú dòng wǔ bǎi zì yǐ nèi dōu kě jiē shòu ó。','Phần thân bài năm nghìn chữ không tính tóm tắt với tài liệu tham khảo, dao động trong khoảng năm trăm chữ đều chấp nhận được nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_03','V818','阮明',3,'字数不足四千五，会直接扣除论文基础分数吗？','zì shù bù zú sì qiān wǔ， huì zhí jiē kòu chú lùn wén jī chǔ fēn shù ma？','Nếu thiếu chưa đủ bốn nghìn năm trăm chữ thì có bị trừ thẳng điểm cơ bản của bài không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_04','V818','李老师',4,'低于四千五会判定内容单薄，基础分直接减半。','dī yú sì qiān wǔ huì pàn dìng nèi róng dān bó， jī chǔ fēn zhí jiē jiǎn bàn。','Dưới bốn nghìn năm trăm chữ sẽ bị coi là nội dung sơ sài, điểm cơ bản bị trừ một nửa luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_05','V818','阮明',5,'图表、注释文字算不算入正文字数统计？','tú biǎo、 zhù shì wén zì suàn bù suàn rù zhèng wén zì shù tǒng jì？','Vậy chữ trong biểu đồ, chú thích có tính vào tổng số chữ của thân bài không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_06','V818','李老师',6,'图表说明、页下注释不计入，仅主体论述段落统计字数。','tú biǎo shuō míng、 yè xià zhù shì bù jì rù， jǐn zhǔ tǐ lùn shù duàn luò tǒng jì zì shù。','Phần chú thích biểu đồ, chú thích chân trang không tính vào, chỉ tính số chữ ở các đoạn lập luận chính thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L818_07','V818','阮明',7,'我控制正文五千字左右，保证内容完整不缺篇幅。','wǒ kòng zhì zhèng wén wǔ qiān zì zuǒ yòu， bǎo zhèng nèi róng wán zhěng bù quē piān fú。','Em sẽ canh phần thân bài khoảng năm nghìn chữ, đảm bảo nội dung đầy đủ không thiếu dung lượng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT819','SHT2','论文提交系统上传失败，咨询学院教务线上补交渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V819','SIT819','P1','twist','ban_chinh_thuc',NULL,'课程、毕业论文线上提交系统有固定截止时间与文件格式、大小限制，超时通道自动关闭不再受理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_01','V819','阮明',1,'老师，论文线上提交系统上传文档一直提示失败，无法完成提交。','lǎo shī， lùn wén xiàn shàng tí jiāo xì tǒng shàng chuán wén dàng yì zhí tí shì shī bài， wú fǎ wán chéng tí jiāo。','Thưa cô, em tải luận văn lên hệ thống nộp bài trực tuyến mãi mà cứ báo lỗi, không nộp được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_02','V819','教务老师',2,'大概率文档内存过大、格式不是PDF，系统仅支持PDF格式上传嘛。','dà gài lǜ wén dàng nèi cún guò dà、 gé shì bú shì PDF， xì tǒng jǐn zhī chí PDF gé shì shàng chuán ma。','Nhiều khả năng là do file quá nặng hoặc không phải định dạng PDF, hệ thống chỉ nhận file PDF thôi đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_03','V819','阮明',3,'我原本是Word文档，直接转换PDF之后文件大小超系统限制。','wǒ yuán běn shì Word wén dàng， zhí jiē zhuǎn huàn PDF zhī hòu wén jiàn dà xiǎo chāo xì tǒng xiàn zhì。','Ban đầu em làm file Word, chuyển sang PDF xong thì dung lượng lại vượt quá giới hạn của hệ thống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_04','V819','教务老师',4,'压缩PDF文件降低分辨率，缩小内存后重新进入系统提交。','yā suō PDF wén jiàn jiàng dī fēn biàn lǜ， suō xiǎo nèi cún hòu chóng xīn jìn rù xì tǒng tí jiāo。','Em nén file PDF lại, giảm độ phân giải xuống cho nhẹ rồi vào hệ thống nộp lại nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_05','V819','阮明',5,'今天是提交截止日，压缩完成后错过零点还能补交吗？','jīn tiān shì tí jiāo jié zhǐ rì， yā suō wán chéng hòu cuò guò líng diǎn hái néng bǔ jiāo ma？','Hôm nay là hạn chót nộp bài rồi, nếu nén xong mà lỡ qua giờ giao thừa thì còn nộp bù được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_06','V819','教务老师',6,'系统零点关闭通道，今晚二十三点五十九分前必须上传成功。','xì tǒng líng diǎn guān bì tōng dào， jīn wǎn èr shí sān diǎn wǔ shí jiǔ fēn qián bì xū shàng chuán chéng gōng。','Đúng nửa đêm hệ thống sẽ đóng cổng nộp bài, tối nay phải tải lên thành công trước hai mươi ba giờ năm mươi chín phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L819_07','V819','阮明',7,'我立刻压缩文档，赶在通道关闭前完成论文提交。','wǒ lì kè yā suō wén dàng， gǎn zài tōng dào guān bì qián wán chéng lùn wén tí jiāo。','Em nén file ngay bây giờ, cố gắng nộp xong luận văn trước khi hệ thống đóng cổng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT820','SHT3','想引用网络自媒体资料，咨询老师是否符合学术规范',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V820','SIT820','P1','that_bai_nhe','ban_chinh_thuc',NULL,'自媒体、短视频平台内容不具备学术权威性，高校论文不允许单独以此作为核心论证依据。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_01','V820','阮明',1,'老师，论文里想引用自媒体公众号文章的数据作为论据可以吗？','lǎo shī， lùn wén lǐ xiǎng yǐn yòng zì méi tǐ gōng zhòng hào wén zhāng de shù jù zuò wéi lùn jù kě yǐ ma？','Thưa cô, em muốn dùng số liệu từ một bài viết trên trang tự truyền thông làm luận cứ trong luận văn, có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_02','V820','李老师',2,'自媒体无正规学术审核，仅能作为辅助参考，不能当作核心论据。','zì méi tǐ wú zhèng guī xué shù shěn hé， jǐn néng zuò wéi fǔ zhù cān kǎo， bù néng dàng zuò hé xīn lùn jù。','Nội dung tự truyền thông không qua thẩm định học thuật chính thống, chỉ dùng làm tham khảo phụ thôi, không thể coi là luận cứ chính được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_03','V820','阮明',3,'如果数据来源只有自媒体，有没有办法合规写入论文内容？','rú guǒ shù jù lái yuán zhǐ yǒu zì méi tǐ， yǒu méi yǒu bàn fǎ hé guī xiě rù lùn wén nèi róng？','Nếu nguồn số liệu chỉ có từ tự truyền thông, có cách nào đưa vào luận văn cho đúng quy chuẩn không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_04','V820','李老师',4,'必须搭配官方期刊、统计年鉴佐证，单独自媒体内容不予认可嘛。','bì xū dā pèi guān fāng qī kān、 tǒng jì nián jiàn zuǒ zhèng， dān dú zì méi tǐ nèi róng bù yǔ rèn kě ma。','Bắt buộc phải có tạp chí chính thống, niên giám thống kê kèm theo để chứng minh, chỉ dùng riêng nội dung tự truyền thông thì không được công nhận đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_05','V820','阮明',5,'那我放弃自媒体素材，重新检索官方行业报告替换论据。','nà wǒ fàng qì zì méi tǐ sù cái， chóng xīn jiǎn suǒ guān fāng háng yè bào gào tì huàn lùn jù。','Vậy em bỏ tư liệu tự truyền thông, tìm lại báo cáo ngành chính thức để thay thế luận cứ vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_06','V820','李老师',6,'学术论文优先采用官方、期刊、专著类权威文献资料。','xué shù lùn wén yōu xiān cǎi yòng guān fāng、 qī kān、 zhuān zhù lèi quán wēi wén xiàn zī liào。','Luận văn học thuật nên ưu tiên dùng tài liệu chính thống, tạp chí, chuyên khảo có uy tín.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L820_07','V820','阮明',7,'我重新查找正规数据源，保证论文引用符合学术标准。','wǒ chóng xīn chá zhǎo zhèng guī shù jù yuán， bǎo zhèng lùn wén yǐn yòng fú hé xué shù biāo zhǔn。','Em sẽ tìm lại nguồn số liệu chuẩn, đảm bảo phần trích dẫn trong luận văn đúng chuẩn học thuật.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT821','SHT3','咨询老师期末复习重点、必考章节范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V821','SIT821','P1','suon_se','ban_chinh_thuc',NULL,'期末考前老师会划定大致复习范围，缩小复习体量，但不会直接透露原题，依靠学生自主背诵理解。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_01','V821','阮明',1,'老师，距离期末考还有两周，想咨询课程核心复习重点章节。','lǎo shī， jù lí qī mò kǎo hái yǒu liǎng zhōu， xiǎng zī xún kè chéng hé xīn fù xí zhòng diǎn zhāng jié。','Thưa cô, còn hai tuần nữa là thi cuối kỳ, em muốn hỏi những chương trọng tâm cần ôn của môn học ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_02','V821','李老师',2,'课本中间四个单元是试卷主要考点，首尾单元仅少量选择题哦。','kè běn zhōng jiān sì gè dān yuán shì shì juàn zhǔ yào kǎo diǎn， shǒu wěi dān yuán jǐn shǎo liàng xuǎn zé tí ó。','Bốn đơn vị bài ở giữa sách là trọng tâm chính của đề thi, hai đơn vị đầu cuối chỉ có ít câu trắc nghiệm thôi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_03','V821','阮明',3,'课后拓展阅读书目、课外补充案例会不会出大题？','kè hòu tuò zhǎn yuè dú shū mù、 kè wài bǔ chōng àn lì huì bú huì chū dà tí？','Sách đọc thêm sau bài học với các tình huống bổ sung ngoài giờ có ra vào câu lớn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_04','V821','李老师',4,'大题全部来自课内课本与课堂例题，课外内容仅少量选择填空。','dà tí quán bù lái zì kè nèi kè běn yǔ kè táng lì tí， kè wài nèi róng jǐn shǎo liàng xuǎn zé tián kòng。','Câu lớn đều lấy từ sách giáo trình và ví dụ trên lớp, phần ngoài chương trình chỉ có ít câu trắc nghiệm hay điền khuyết thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_05','V821','阮明',5,'名词解释、论述题分别对应课本哪一部分内容？','míng cí jiě shì、 lùn shù tí fēn bié duì yìng kè běn nǎ yī bù fèn nèi róng？','Vậy phần giải thích thuật ngữ với câu luận thuật ứng với phần nào trong sách ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_06','V821','李老师',6,'名词解释每单元课后词汇，论述题是课堂反复讲解的核心观点。','míng cí jiě shì měi dān yuán kè hòu cí huì， lùn shù tí shì kè táng fǎn fù jiǎng jiě de hé xīn guān diǎn。','Giải thích thuật ngữ là từ vựng sau mỗi đơn vị bài, còn câu luận thuật là những quan điểm cốt lõi được giảng đi giảng lại trên lớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L821_07','V821','阮明',7,'我优先重点复习核心单元，针对性背诵大题考点。','wǒ yōu xiān zhòng diǎn fù xí hé xīn dān yuán， zhēn duì xìng bèi sòng dà tí kǎo diǎn。','Em sẽ ưu tiên ôn kỹ các đơn vị trọng tâm, học thuộc có mục tiêu những điểm hay ra câu lớn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT822','SHT3','错过随堂小测，询问老师能否安排补测',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V822','SIT822','P1','twist','ban_chinh_thuc',NULL,'因病、公事请假缺测可凭证明补测，无故缺考无补测机会，直接扣除对应平时分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_01','V822','阮明',1,'老师，上周随堂小测我生病请假，没能到场完成测试。','lǎo shī， shàng zhōu suí táng xiǎo cè wǒ shēng bìng qǐng jià， méi néng dào chǎng wán chéng cè shì。','Thưa cô, tuần trước bài kiểm tra nhỏ trên lớp em bị ốm phải nghỉ, không đến làm bài được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_02','V822','李老师',2,'有医院病假证明备案的学生，可以统一参加期末前集中补测。','yǒu yī yuàn bìng jià zhèng míng bèi àn de xué shēng， kě yǐ tǒng yī cān jiā qī mò qián jí zhōng bǔ cè。','Học sinh có giấy chứng nhận nghỉ ốm của bệnh viện nộp lưu hồ sơ thì được xếp thi bù tập trung trước kỳ thi cuối kỳ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_03','V822','阮明',3,'我保留完整医院病历单据，今天带来给您登记备案可以吗？','wǒ bǎo liú wán zhěng yī yuàn bìng lì dān jù， jīn tiān dài lái gěi nín dēng jì bèi àn kě yǐ ma？','Em còn giữ đầy đủ hồ sơ bệnh án của bệnh viện, hôm nay mang đến để cô đăng ký lưu lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_04','V822','李老师',4,'病历登记截止本周四，周四之后不再受理补测报名嘛。','bìng lì dēng jì jié zhǐ běn zhōu sì， zhōu sì zhī hòu bù zài shòu lǐ bǔ cè bào míng ma。','Hạn đăng ký hồ sơ bệnh án là đến hết thứ Năm tuần này, sau thứ Năm sẽ không nhận đăng ký thi bù nữa đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_05','V822','阮明',5,'补测试卷难度、分值和正常随堂小测完全一致吗？','bǔ cè shì juàn nán dù、 fēn zhí hé zhèng cháng suí táng xiǎo cè wán quán yí zhì ma？','Đề thi bù về độ khó và thang điểm có hoàn toàn giống bài kiểm tra bình thường trên lớp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_06','V822','李老师',6,'题型、分值标准相同，只是作答时间缩短十分钟。','tí xíng、 fēn zhí biāo zhǔn xiāng tóng， zhǐ shì zuò dá shí jiān suō duǎn shí fēn zhōng。','Dạng đề và thang điểm giống nhau, chỉ có thời gian làm bài rút ngắn mười phút thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L822_07','V822','阮明',7,'我今天上交病假单登记，按时参加统一补测。','wǒ jīn tiān shàng jiāo bìng jià dān dēng jì， àn shí cān jiā tǒng yī bǔ cè。','Hôm nay em sẽ nộp giấy nghỉ ốm để đăng ký, đúng giờ tham gia thi bù tập trung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT823','SHT3','期末挂科，咨询补考报名时间、复习范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V823','SIT823','P1','suon_se','chinh_thuc',NULL,'国内大学补考最高绩点60分，仅标记及格，无法参与奖学金评选，重修才能刷新分数。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_01','V823','阮明',1,'老师，这门专业课期末挂科，想咨询补考报名与复习范围。','lǎo shī， zhè mén zhuān yè kè qī mò guà kē， xiǎng zī xún bǔ kǎo bào míng yǔ fù xí fàn wéi。','Thưa thầy/cô, môn chuyên ngành này em bị rớt ở kỳ cuối, em muốn hỏi thời gian đăng ký thi lại và phạm vi ôn tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_02','V823','教务老师',2,'开学第一周线上系统开放补考报名，逾期视为自动放弃补考。','kāi xué dì yī zhōu xiàn shàng xì tǒng kāi fàng bǔ kǎo bào míng， yú qī shì wèi zì dòng fàng qì bǔ kǎo。','Tuần đầu tiên của học kỳ mới, hệ thống trực tuyến sẽ mở đăng ký thi lại, quá hạn coi như tự động từ bỏ quyền thi lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_03','V823','阮明',3,'补考试卷考点和期末试卷范围一样，还是会更换全新章节？','bǔ kǎo shì juàn kǎo diǎn hé qī mò shì juàn fàn wéi yī yàng， hái shì huì gēng huàn quán xīn zhāng jié？','Phạm vi kiến thức đề thi lại có giống đề thi cuối kỳ không, hay sẽ đổi sang chương hoàn toàn mới ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_04','V823','教务老师',4,'考点范围完全相同，试卷题目全部重新出题，不会使用原卷。','kǎo diǎn fàn wéi wán quán xiāng tóng， shì juàn tí mù quán bù chóng xīn chū tí， bú huì shǐ yòng yuán juǎn。','Phạm vi kiến thức hoàn toàn giống nhau, nhưng đề thi sẽ ra hoàn toàn mới, không dùng lại đề cũ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_05','V823','阮明',5,'补考及格即可拿到学分，补考分数会直接替代期末成绩吗？','bǔ kǎo jí gé jí kě ná dào xué fēn， bǔ kǎo fēn shù huì zhí jiē tì dài qī mò chéng jì ma？','Thi lại đạt điểm đậu là được cấp tín chỉ, điểm thi lại có được thay thế trực tiếp cho điểm cuối kỳ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_06','V823','教务老师',6,'补考最高记60分及格，无论考多高都不会计入高分。','bǔ kǎo zuì gāo jì 60 fēn jí gé， wú lùn kǎo duō gāo dōu bú huì jì rù gāo fēn。','Điểm thi lại tối đa chỉ ghi nhận 60 điểm đậu, dù thi cao đến đâu cũng không tính là điểm cao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L823_07','V823','阮明',7,'我暑假完整复习课本核心内容，开学顺利通过补考。','wǒ shǔ jià wán zhěng fù xí kè běn hé xīn nèi róng， kāi xué shùn lì tōng guò bǔ kǎo。','Em sẽ ôn kỹ toàn bộ nội dung trọng tâm trong sách suốt hè, đầu học kỳ mới sẽ thi lại đậu suôn sẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT824','SHT3','补考仍未通过，咨询重修选课流程与缴费标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V824','SIT824','P1','that_bai_nhe','chinh_thuc',NULL,'补考不及格必须重修该门课程，按学分收取重修费用，全部考核达标才能拿到对应学分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_01','V824','阮明',1,'老师，补考依旧没有及格，想咨询课程重修办理流程。','lǎo shī， bǔ kǎo yī jiù méi yǒu jí gé， xiǎng zī xún kè chéng chóng xiū bàn lǐ liú chéng。','Thưa thầy/cô, em thi lại vẫn chưa đạt, em muốn hỏi quy trình đăng ký học lại môn này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_02','V824','教务老师',2,'下一学期选课周期，线上系统勾选重修课程，缴纳重修学分费。','xià yī xué qī xuǎn kè zhōu qī， xiàn shàng xì tǒng gōu xuǎn chóng xiū kè chéng， jiǎo nà chóng xiū xué fēn fèi。','Vào kỳ đăng ký học phần của học kỳ tới, em chọn tick môn học lại trên hệ thống trực tuyến rồi đóng học phí học lại theo tín chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_03','V824','阮明',3,'重修需要全程跟班上课、完成全部平时作业与课堂小测吗？','chóng xiū xū yào quán chéng gēn bān shàng kè、 wán chéng quán bù píng shí zuò yè yǔ kè táng xiǎo cè ma？','Học lại có phải theo học đầy đủ cùng lớp, hoàn thành hết bài tập thường xuyên và các bài kiểm tra trên lớp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_04','V824','教务老师',4,'是的，重修完整复刻正常课程考核规则，出勤、作业、考试全部计分嘛。','shì de， chóng xiū wán zhěng fù kè zhèng cháng kè chéng kǎo hé guī zé， chū qín、 zuò yè、 kǎo shì quán bù jì fēn ma。','Đúng vậy, học lại áp dụng đầy đủ quy chế đánh giá như học bình thường, điểm danh, bài tập, thi cử đều được tính điểm hết đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_05','V824','阮明',5,'一学分重修收费标准多少，一门完整课程一共几学分？','yī xué fēn chóng xiū shōu fèi biāo zhǔn duō shǎo， yī mén wán zhěng kè chéng yī gòng jǐ xué fēn？','Mức thu phí học lại mỗi tín chỉ là bao nhiêu, và một môn học đầy đủ có tổng cộng bao nhiêu tín chỉ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_06','V824','教务老师',6,'每学分一百元，本课程四学分，一次性缴纳四百元重修费。','měi xué fēn yì bǎi yuán， běn kè chéng sì xué fēn， yí cì xìng jiǎo nà sì bǎi yuán chóng xiū fèi。','Mỗi tín chỉ một trăm nghìn đồng, môn này có bốn tín chỉ, đóng một lần bốn trăm nghìn đồng phí học lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L824_07','V824','阮明',7,'我记下选课时间，下一学期按时报名重修认真学习。','wǒ jì xià xuǎn kè shí jiān， xià yī xué qī àn shí bào míng chóng xiū rèn zhēn xué xí。','Em ghi lại thời gian đăng ký học phần, học kỳ tới sẽ đăng ký học lại đúng hạn và học nghiêm túc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT825','SHT3','询问考场允许携带的文具，禁止带入物品清单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V825','SIT825','P1','suon_se','ban_chinh_thuc',NULL,'国内标准化考场严格管控随身物品，电子设备、纸质资料一律禁止带入，草稿纸统一发放回收。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_01','V825','阮明',1,'老师，期末考场允许携带哪些文具，有物品禁止带入考场吗？','lǎo shī， qī mò kǎo chǎng yǔn xǔ xié dài nǎ xiē wén jù， yǒu wù pǐn jìn zhǐ dài rù kǎo chǎng ma？','Thầy ơi, phòng thi cuối kỳ được mang những dụng cụ học tập nào ạ, có vật dụng nào bị cấm mang vào phòng thi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_02','V825','李老师',2,'黑色签字笔、2B铅笔、橡皮、直尺可带入；手机、课本、草稿纸全部禁止哦。','hēi sè qiān zì bǐ、2B qiān bǐ、 xiàng pí、 zhí chǐ kě dài rù； shǒu jī、 kè běn、 cǎo gǎo zhǐ quán bù jìn zhǐ ó。','Bút bi mực đen, bút chì 2B, tẩy, thước kẻ thì được mang; điện thoại, sách giáo khoa, giấy nháp thì tuyệt đối cấm nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_03','V825','阮明',3,'透明文件袋装文具可以，彩色帆布文具袋会不会不让带进考场？','tòu míng wén jiàn dài zhuāng wén jù kě yǐ， cǎi sè fān bù wén jù dài huì bú huì bù ràng dài jìn kǎo chǎng？','Em đựng dụng cụ học tập trong túi hồ sơ trong suốt thì được, còn túi vải bố nhiều màu thì có bị cấm mang vào phòng thi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_04','V825','李老师',4,'建议透明无图案文具袋，方便监考老师快速检查袋内物品。','jiàn yì tòu míng wú tú àn wén jù dài， fāng biàn jiān kǎo lǎo shī kuài sù jiǎn chá dài nèi wù pǐn。','Nên dùng túi đựng dụng cụ trong suốt, không hoa văn, để giám thị kiểm tra đồ trong túi cho nhanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_05','V825','阮明',5,'考场会统一发放草稿纸，不需要自己携带白纸对吧？','kǎo chǎng huì tǒng yī fā fàng cǎo gǎo zhǐ， bù xū yào zì jǐ xié dài bái zhǐ duì ba？','Phòng thi sẽ phát giấy nháp đồng loạt, nên em không cần tự mang giấy trắng theo đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_06','V825','李老师',6,'每场考试统一分发草稿纸，离场全部回收不允许带出考场。','měi chǎng kǎo shì tǒng yī fēn fā cǎo gǎo zhǐ， lí chǎng quán bù huí shōu bù yǔn xǔ dài chū kǎo chǎng。','Mỗi buổi thi đều phát giấy nháp thống nhất, hết giờ thu lại hết, không được mang ra khỏi phòng thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L825_07','V825','阮明',7,'我只准备规定文具，不带任何禁止物品进入考场。','wǒ zhǐ zhǔn bèi guī dìng wén jù， bù dài rèn hé jìn zhǐ wù pǐn jìn rù kǎo chǎng。','Vậy em chỉ chuẩn bị đúng dụng cụ quy định thôi, không mang bất kỳ vật gì bị cấm vào phòng thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT826','SHT3','复习资料丢失，找同学拷贝完整复习提纲',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V826','SIT826','P1','twist','tuy_y',NULL,'老师内部复习提纲属于班级专属学习材料，一般不允许跨班级大范围转发。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_01','V826','阮明',1,'我存复习提纲的U盘弄丢了，能不能把你的全套复习资料发我一份？','wǒ cún fù xí tí gāng de U pán nòng diū le， néng bù néng bǎ nǐ de quán tào fù xí zī liào fā wǒ yī fèn？','Cái USB lưu đề cương ôn tập của tớ bị mất rồi, cậu gửi cho tớ trọn bộ tài liệu ôn tập của cậu được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_02','V826','苏雯',2,'可以全部打包发给你，但是提纲内老师标注的内部例题不能转发给其他班级。','kě yǐ quán bù dǎ bāo fā gěi nǐ， dàn shì tí gāng nèi lǎo shī biāo zhù de nèi bù lì tí bù néng zhuǎn fā gěi qí tā bān jí。','Gửi hết cho cậu cũng được, nhưng mấy bài tập mẫu nội bộ mà thầy đánh dấu trong đề cương thì không được chuyển cho lớp khác đâu nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_03','V826','阮明',3,'我只自己复习，绝不外传资料，这点你放心。','wǒ zhǐ zì jǐ fù xí， jué bù wài chuán zī liào， zhè diǎn nǐ fàng xīn。','Tớ chỉ tự ôn thôi, tuyệt đối không phát tán tài liệu ra ngoài, điểm này cậu cứ yên tâm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_04','V826','苏雯',4,'文件很大，微信传输容易卡顿，我分享网盘链接给你下载嘛。','wén jiàn hěn dà， wēi xìn chuán shū róng yì kǎ dùn， wǒ fēn xiǎng wǎng pán liàn jiē gěi nǐ xià zài ma。','File nặng lắm, gửi qua WeChat dễ bị đơ, để tớ chia sẻ link ổ đĩa mạng cho cậu tải về nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_05','V826','阮明',5,'网盘下载完我立刻核对章节，补齐丢失的背诵提纲。','wǎng pán xià zài wán wǒ lì kè hé duì zhāng jié， bǔ qí diū shī de bèi sòng tí gāng。','Tải xong ở ổ đĩa mạng là tớ đối chiếu chương mục ngay, bổ sung lại phần đề cương học thuộc bị mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_06','V826','苏雯',6,'提纲划了必考背诵点，优先背诵标红大题内容。','tí gāng huà le bì kǎo bèi sòng diǎn， yōu xiān bèi sòng biāo hóng dà tí nèi róng。','Đề cương đã gạch sẵn mấy điểm chắc chắn thi rồi, ưu tiên học thuộc trước phần câu lớn được bôi đỏ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L826_07','V826','阮明',7,'太感谢，丢失资料差点耽误期末复习进度。','tài gǎn xiè， diū shī zī liào chà diǎn dān wù qī mò fù xí jìn dù。','Cảm ơn cậu nhiều lắm, mất tài liệu suýt nữa làm chậm tiến độ ôn thi cuối kỳ của tớ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT827','SHT4','咨询平时分过低，期末卷面需要多少分才能及格',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V827','SIT827','P1','suon_se','ban_chinh_thuc',NULL,'总评分数按固定比例加权计算，平时分偏低时需要更高期末卷面分数才能及格。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_01','V827','阮明',1,'老师，我出勤分、课堂小测得分不高，想问问期末卷面最低多少能总评及格。','lǎo shī， wǒ chū qín fēn、 kè táng xiǎo cè dé fēn bù gāo， xiǎng wèn wèn qī mò juàn miàn zuì dī duō shǎo néng zǒng píng jí gé。','Thầy ơi, điểm chuyên cần và điểm kiểm tra nhỏ trên lớp của em không cao lắm, em muốn hỏi bài thi cuối kỳ cần tối thiểu bao nhiêu điểm thì tổng kết mới đạt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_02','V827','李老师',2,'平时分目前只有12分，期末试卷至少考76分，总评才能达到60分及格线。','píng shí fēn mù qián zhǐ yǒu 12 fēn， qī mò shì juàn zhì shǎo kǎo 76 fēn， zǒng píng cái néng dá dào 60 fēn jí gé xiàn。','Điểm quá trình hiện tại của em chỉ được 12 điểm, bài thi cuối kỳ phải đạt ít nhất 76 điểm thì tổng kết mới chạm ngưỡng 60 điểm đạt yêu cầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_03','V827','阮明',3,'试卷满分一百分，76分难度偏高，我需要重点背诵全部大题吗？','shì juàn mǎn fēn yì bǎi fēn，76 fēn nán dù piān gāo， wǒ xū yào zhòng diǎn bèi sòng quán bù dà tí ma？','Bài thi thang điểm một trăm, mà 76 điểm thì khá khó, vậy em có cần học thuộc trọng tâm hết các câu lớn không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_04','V827','李老师',4,'论述、简答分值占比高，抓住大题就能拉高卷面总分。','lùn shù、 jiǎn dá fēn zhí zhàn bǐ gāo， zhuā zhù dà tí jiù néng lā gāo juàn miàn zǒng fēn。','Câu luận và câu hỏi ngắn chiếm tỷ trọng điểm cao, nắm chắc mấy câu lớn là kéo được tổng điểm bài thi lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_05','V827','阮明',5,'选择题分值低，复习时可以适当减少选择背诵时间？','xuǎn zé tí fēn zhí dī， fù xí shí kě yǐ shì dàng jiǎn shǎo xuǎn zé bèi sòng shí jiān？','Câu trắc nghiệm điểm thấp, vậy khi ôn tập em có thể giảm bớt thời gian học thuộc phần trắc nghiệm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_06','V827','李老师',6,'选择保证基础分，大题尽量拿满，平衡分配复习精力。','xuǎn zé bǎo zhèng jī chǔ fēn， dà tí jǐn liàng ná mǎn， píng héng fēn pèi fù xí jīng lì。','Trắc nghiệm thì cứ giữ chắc điểm cơ bản, còn câu lớn thì cố lấy trọn điểm, phân bổ đều công sức ôn tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L827_07','V827','阮明',7,'我重点攻克主观大题，争取期末卷面达标顺利及格。','wǒ zhòng diǎn gōng kè zhǔ guān dà tí， zhēng qǔ qī mò juàn miàn dá biāo shùn lì jí gé。','Vậy em sẽ tập trung chinh phục các câu lớn tự luận, cố gắng để bài thi cuối kỳ đạt chuẩn và qua môn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT828','SHT4','选课系统卡顿抢不到心仪选修课，咨询教务调剂方案',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V828','SIT828','P1','twist','ban_chinh_thuc',NULL,'高校选修课名额有限，首轮选满只能等待学生退课产生空位，无人工扩容插队渠道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_01','V828','阮明',1,'老师，线上选课系统卡顿，我心仪的汉语文化选修课已经选满关闭。','lǎo shī， xiàn shàng xuǎn kè xì tǒng kǎ dùn， wǒ xīn yí de hàn yǔ wén huà xuǎn xiū kè yǐ jīng xuǎn mǎn guān bì。','Thầy ơi, hệ thống đăng ký học online bị đơ, môn tự chọn văn hóa Hán ngữ mà em thích đã đầy chỗ và đóng đăng ký rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_02','V828','教务老师',2,'首轮选课结束后有一轮补选调剂通道，三天后系统重新开放空位。','shǒu lún xuǎn kè jié shù hòu yǒu yī lún bǔ xuǎn diào jì tōng dào， sān tiān hòu xì tǒng chóng xīn kāi fàng kōng wèi。','Sau vòng đăng ký đầu tiên sẽ có một đợt đăng ký bổ sung và điều chỉnh, ba ngày nữa hệ thống sẽ mở lại các suất trống.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_03','V828','阮明',3,'补选通道是随机释放退课空位，还是可以人工登记插队？','bǔ xuǎn tōng dào shì suí jī shì fàng tuì kè kòng wèi， hái shì kě yǐ rén gōng dēng jì chā duì？','Đợt đăng ký bổ sung là ngẫu nhiên phát chỗ trống do người khác hủy đăng ký, hay là có thể đăng ký thủ công để xếp trước ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_04','V828','教务老师',4,'无人工插队登记，只能等待其他学生退课后系统自动释放名额嘛。','wú rén gōng chā duì dēng jì， zhǐ néng děng dài qí tā xué shēng tuì kè hòu xì tǒng zì dòng shì fàng míng é ma。','Không có chuyện đăng ký thủ công để xếp trước đâu, chỉ có thể chờ sinh viên khác hủy môn rồi hệ thống tự động cấp suất thôi nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_05','V828','阮明',5,'如果补选依旧抢不到，有没有同类型替代选修课推荐？','rú guǒ bǔ xuǎn yī jiù qiǎng bú dào， yǒu méi yǒu tóng lèi xíng tì dài xuǎn xiū kè tuī jiàn？','Nếu đợt bổ sung vẫn không đăng ký được thì có môn tự chọn nào cùng loại để thay thế không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_06','V828','教务老师',6,'有两门民俗类选修课内容相近，难度、学分完全一致。','yǒu liǎng mén mín sú lèi xuǎn xiū kè nèi róng xiāng jìn， nán dù、 xué fēn wán quán yí zhì。','Có hai môn tự chọn về văn hóa dân gian nội dung khá tương tự, độ khó và số tín chỉ hoàn toàn giống nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L828_07','V828','阮明',7,'三天后准时登录系统补选，备选同步勾选民俗课程。','sān tiān hòu zhǔn shí dēng lù xì tǒng bǔ xuǎn， bèi xuǎn tóng bù gōu xuǎn mín sú kè chéng。','Vậy ba ngày nữa em sẽ đăng nhập đúng giờ để đăng ký bổ sung, đồng thời tick chọn thêm môn văn hóa dân gian làm phương án dự phòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT829','SHT4','选错课程，咨询退课截止时间、退课学分规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V829','SIT829','P1','suon_se','ban_chinh_thuc',NULL,'开学初期设有免费退课窗口期，窗口期外放弃课程会判定弃考挂科，影响学籍学分记录。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_01','V829','阮明',1,'老师，我选课误选高阶汉语课程，自身基础跟不上，想办理退课。','lǎo shī， wǒ xuǎn kè wù xuǎn gāo jiē hàn yǔ kè chéng， zì shēn jī chǔ gēn bù shàng， xiǎng bàn lǐ tuì kè。','Thầy ơi, em đăng ký nhầm phải môn Hán ngữ nâng cao, nền tảng bản thân không theo kịp, em muốn xin rút môn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_02','V829','教务老师',2,'开学第二周周五是免费退课截止日，退课后学分不计入本学期修读记录。','kāi xué dì èr zhōu zhōu wǔ shì miǎn fèi tuì kè jié zhǐ rì， tuì kè hòu xué fēn bù jì rù běn xué qī xiū dú jì lù。','Thứ Sáu tuần thứ hai của học kỳ là hạn chót rút môn miễn phí, rút sau đó thì tín chỉ sẽ không tính vào hồ sơ học tập kỳ này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_03','V829','阮明',3,'超过截止日期再退课，会标记课程挂科记录在学籍系统吗？','chāo guò jié zhǐ rì qī zài tuì kè， huì biāo jì kè chéng guà kē jì lù zài xué jí xì tǒng ma？','Nếu quá hạn mới rút môn thì có bị ghi vào hệ thống hồ sơ học tập là môn trượt không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_04','V829','教务老师',4,'逾期退课按弃考处理，直接记挂科，需要后续重修缴费。','yú qī tuì kè àn qì kǎo chǔ lǐ， zhí jiē jì guà kē， xū yào hòu xù chóng xiū jiǎo fèi。','Rút môn trễ hạn thì tính như bỏ thi, ghi thẳng là trượt môn, sau này phải học lại và đóng học phí lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_05','V829','阮明',5,'今天周二，我现在线上提交退课申请，来得及免费撤销课程。','jīn tiān zhōu èr， wǒ xiàn zài xiàn shàng tí jiāo tuì kè shēn qǐng， lái de jí miǎn fèi chè xiāo kè chéng。','Hôm nay là thứ Ba, em nộp đơn rút môn online ngay bây giờ thì vẫn kịp hủy môn miễn phí đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_06','V829','教务老师',6,'线上申请提交后一小时内系统自动审核完成退课。','xiàn shàng shēn qǐng tí jiāo hòu yī xiǎo shí nèi xì tǒng zì dòng shěn hé wán chéng tuì kè。','Sau khi nộp đơn online, trong vòng một tiếng hệ thống sẽ tự động duyệt xong việc rút môn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L829_07','V829','阮明',7,'我立刻操作退课，重新选择适配我水平的基础选修课。','wǒ lì kè cāo zuò tuì kè， chóng xīn xuǎn zé shì pèi wǒ shuǐ píng de jī chǔ xuǎn xiū kè。','Vậy em thao tác rút môn ngay, rồi chọn lại môn tự chọn cơ bản phù hợp với trình độ của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT830','SHT4','申请开具在校在读证明用于签证、实习',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V830','SIT830','P1','suon_se','chinh_thuc',NULL,'学院加盖公章的在读证明属于官方学籍凭证，出入境、企业实习均认可其法律效力，复印件无公章无效。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_01','V830','阮明',1,'老师，我需要官方在校在读证明，用于续签居留许可和校外实习备案。','lǎo shī， wǒ xū yào guān fāng zài xiào zài dú zhèng míng， yòng yú xù qiān jū liú xǔ kě hé xiào wài shí xí bèi àn。','Thưa thầy, em cần giấy xác nhận đang học chính thức, để dùng gia hạn giấy phép cư trú và đăng ký thực tập bên ngoài trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_02','V830','教务老师',2,'填写纸质申请表，携带护照、学生证，当场打印加盖学院公章哦。','tián xiě zhǐ zhì shēn qǐng biǎo， xié dài hù zhào、 xué shēng zhèng， dāng chǎng dǎ yìn jiā gài xué yuàn gōng zhāng ó。','Em điền vào mẫu đơn giấy, mang theo hộ chiếu và thẻ sinh viên, chúng tôi sẽ in tại chỗ và đóng dấu chính thức của khoa ngay ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_03','V830','阮明',3,'证明可以一次性打印两份，签证、实习分开使用吗？','zhèng míng kě yǐ yí cì xìng dǎ yìn liǎng fèn， qiān zhèng、 shí xí fēn kāi shǐ yòng ma？','Giấy xác nhận có thể in một lần được hai bản để dùng riêng cho visa và thực tập không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_04','V830','教务老师',4,'无份数限制，需要几份直接说明，全部同步盖章生效。','wú fèn shù xiàn zhì， xū yào jǐ fèn zhí jiē shuō míng， quán bù tóng bù gài zhāng shēng xiào。','Không giới hạn số bản, cần bao nhiêu bản cứ nói rõ, tất cả sẽ được đóng dấu có hiệu lực cùng lúc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_05','V830','阮明',5,'在读证明开具完成，当天就能直接拿去出入境大厅办理签证？','zài dú zhèng míng kāi jù wán chéng， dàng tiān jiù néng zhí jiē ná qù chū rù jìng dà tīng bàn lǐ qiān zhèng？','Giấy xác nhận đang học làm xong là ngay hôm đó em có thể mang thẳng đến phòng xuất nhập cảnh để làm visa được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_06','V830','教务老师',6,'盖红色公章的原件具备官方效力，可直接用于签证、实习备案。','gài hóng sè gōng zhāng de yuán jiàn jù bèi guān fāng xiào lì， kě zhí jiē yòng yú qiān zhèng、 shí xí bèi àn。','Bản gốc có đóng dấu đỏ chính thức là có giá trị pháp lý, có thể dùng trực tiếp cho visa và đăng ký thực tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L830_07','V830','阮明',7,'我填好申请表，现在提交办理两份在读证明。','wǒ tián hǎo shēn qǐng biǎo， xiàn zài tí jiāo bàn lǐ liǎng fèn zài dú zhèng míng。','Vậy em điền xong mẫu đơn rồi, giờ nộp luôn để xin làm hai bản giấy xác nhận đang học ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT831','SHT4','咨询学分修读进度，还差多少学分满足毕业要求',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V831','SIT831','P1','twist','chinh_thuc',NULL,'本科有硬性毕业总学分底线，综测竞赛加分仅用于评优，不能抵扣必修、选修毕业学分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_01','V831','阮明',1,'老师，想核对我已修学分总数，还差多少学分才能达标毕业。','lǎo shī， xiǎng hé duì wǒ yǐ xiū xué fēn zǒng shù， hái chà duō shǎo xué fēn cái néng dá biāo bì yè。','Thưa thầy, em muốn kiểm tra lại tổng số tín chỉ đã học của mình, còn thiếu bao nhiêu tín chỉ nữa mới đủ điều kiện tốt nghiệp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_02','V831','教务老师',2,'毕业总学分要求140分，你目前只修满112分，还差28学分。','bì yè zǒng xué fēn yāo qiú 140 fēn， nǐ mù qián zhǐ xiū mǎn 112 fēn， hái chà 28 xué fēn。','Yêu cầu tổng tín chỉ tốt nghiệp là 140 tín chỉ, hiện tại em mới học được 112 tín chỉ, còn thiếu 28 tín chỉ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_03','V831','阮明',3,'剩余学分只能靠专业课、选修课补齐，没有其他加分渠道吗？','shèng yú xué fēn zhǐ néng kào zhuān yè kè、 xuǎn xiū kè bǔ qí， méi yǒu qí tā jiā fēn qú dào ma？','Số tín chỉ còn thiếu chỉ có thể bù bằng môn chuyên ngành và môn tự chọn thôi ạ, không còn kênh cộng điểm nào khác sao thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_04','V831','教务老师',4,'竞赛、论文综测加分不抵扣毕业学分，仅用于奖学金评选嘛。','jìng sài、 lùn wén zōng cè jiā fēn bù dǐ kòu bì yè xué fēn， jǐn yòng yú jiǎng xué jīn píng xuǎn ma。','Điểm cộng từ thi đấu hay bài luận đánh giá tổng hợp không được khấu trừ vào tín chỉ tốt nghiệp đâu, chỉ dùng để xét học bổng thôi nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_05','V831','阮明',5,'剩余两个学期，平均每学期需要修十四分才能按时毕业？','shèng yú liǎng gè xué qī， píng jūn měi xué qī xū yào xiū shí sì fēn cái néng àn shí bì yè？','Còn hai học kỳ nữa, trung bình mỗi kỳ em cần học đủ mười bốn tín chỉ mới tốt nghiệp đúng hạn được đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_06','V831','教务老师',6,'没错，每学期至少七门课程，不能大量少选学分课。','méi cuò， měi xué qī zhì shǎo qī mén kè chéng， bù néng dà liàng shǎo xuǎn xué fēn kè。','Đúng vậy, mỗi kỳ ít nhất phải học bảy môn, không được chọn quá ít môn dẫn đến thiếu tín chỉ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L831_07','V831','阮明',7,'我之后每学期足额选课，保证按期修满毕业学分。','wǒ zhī hòu měi xué qī zú é xuǎn kè， bǎo zhèng àn qī xiū mǎn bì yè xué fēn。','Vậy từ giờ mỗi kỳ em sẽ đăng ký đủ số môn, đảm bảo học đủ tín chỉ tốt nghiệp đúng thời hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT832','SHT4','咨询辅修专业报名条件、额外课时安排',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V832','SIT832','P1','suon_se','ban_chinh_thuc',NULL,'国内高校辅修专业面向成绩合格无挂科学生开设，授课集中周末，完成后发放独立辅修证明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_01','V832','阮明',1,'老师，想报名外贸辅修专业，请问报名基础条件有哪些？','lǎo shī， xiǎng bào míng wài mào fǔ xiū zhuān yè， qǐng wèn bào míng jī chǔ tiáo jiàn yǒu nǎ xiē？','Thưa thầy, em muốn đăng ký ngành học phụ về ngoại thương, xin hỏi điều kiện cơ bản để đăng ký là gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_02','V832','教务老师',2,'本专业平均分70分以上，无挂科记录，大二可提交辅修申请。','běn zhuān yè píng jūn fēn 70 fēn yǐ shàng， wú guà kē jì lù， dà èr kě tí jiāo fǔ xiū shēn qǐng。','Điểm trung bình chuyên ngành chính từ 70 điểm trở lên, không có môn trượt, sinh viên năm hai có thể nộp đơn đăng ký học phụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_03','V832','阮明',3,'辅修课程全部安排在周末，会不会和本专业课程冲突？','fǔ xiū kè chéng quán bù ān pái zài zhōu mò， huì bú huì hé běn zhuān yè kè chéng chōng tū？','Các môn học phụ đều xếp vào cuối tuần, vậy có bị trùng với các môn chuyên ngành chính không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_04','V832','教务老师',4,'辅修统一周六全天授课，工作日无额外课时，不会冲突主修课。','fǔ xiū tǒng yī zhōu liù quán tiān shòu kè， gōng zuò rì wú é wài kè shí， bú huì chōng tū zhǔ xiū kè。','Học phụ được xếp học trọn ngày thứ Bảy, không có tiết học thêm vào ngày thường, nên sẽ không trùng với môn chính đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_05','V832','阮明',5,'辅修完成后发放辅修证书，证书和主修毕业证一同发放吗？','fǔ xiū wán chéng hòu fā fàng fǔ xiū zhèng shū， zhèng shū hé zhǔ xiū bì yè zhèng yī tóng fā fàng ma？','Sau khi hoàn thành học phụ sẽ được cấp chứng chỉ, chứng chỉ này có được phát cùng lúc với bằng tốt nghiệp chuyên ngành chính không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_06','V832','教务老师',6,'毕业时同步发放辅修结业证明，求职可作为专业补充凭证。','bì yè shí tóng bù fā fàng fǔ xiū jié yè zhèng míng， qiú zhí kě zuò wéi zhuān yè bǔ chōng píng zhèng。','Khi tốt nghiệp sẽ cấp đồng thời giấy chứng nhận hoàn thành học phụ, có thể dùng làm minh chứng chuyên môn bổ sung khi xin việc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L832_07','V832','阮明',7,'我本学期稳住平均分，下学期申请报名外贸辅修。','wǒ běn xué qī wěn zhù píng jūn fēn， xià xué qī shēn qǐng bào míng wài mào fǔ xiū。','Vậy học kỳ này em sẽ giữ vững điểm trung bình, học kỳ sau sẽ nộp đơn đăng ký học phụ ngoại thương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT833','SHT4','教务系统个人信息拼音拼写错误，申请更正学籍信息',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V833','SIT833','P1','twist','chinh_thuc',NULL,'学籍姓名、国籍、证件号属于锁定核心信息，学生无法线上自行修改，必须线下提交证件佐证人工更正。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_01','V833','阮明',1,'老师，教务系统里我的姓名拼音拼写错误，和护照不一致影响办签证。','lǎo shī， jiào wù xì tǒng lǐ wǒ de xìng míng pīn yīn pīn xiě cuò wù， hé hù zhào bù yī zhì yǐng xiǎng bàn qiān zhèng。','Thưa thầy/cô, tên em ghi trong hệ thống giáo vụ bị sai phần phiên âm, không khớp với hộ chiếu nên ảnh hưởng đến việc xin visa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_02','V833','教务老师',2,'填写学籍信息变更申请表，附上护照原件复印件佐证正确拼写。','tián xiě xué jí xìn xī biàn gēng shēn qǐng biǎo， fù shàng hù zhào yuán jiàn fù yìn jiàn zuǒ zhèng zhèng què pīn xiě。','Em điền vào mẫu đơn đề nghị thay đổi thông tin học tịch, kèm theo bản photo hộ chiếu gốc để làm căn cứ đối chiếu cách viết đúng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_03','V833','阮明',3,'线上系统不能自行修改，必须线下纸质申请人工后台更正嘛。','xiàn shàng xì tǒng bù néng zì xíng xiū gǎi， bì xū xiàn xià zhǐ zhì shēn qǐng rén gōng hòu tái gēng zhèng ma。','Vậy là hệ thống online không tự sửa được, phải nộp đơn giấy trực tiếp để bộ phận hậu đài chỉnh sửa thủ công đúng không ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_04','V833','教务老师',4,'学籍核心姓名属于锁定信息，仅教务管理员有权限后台修改。','xué jí hé xīn xìng míng shǔ yú suǒ dìng xìn xī， jǐn jiào wù guǎn lǐ yuán yǒu quán xiàn hòu tái xiū gǎi。','Tên trong học tịch là thông tin cốt lõi bị khóa, chỉ quản trị viên giáo vụ mới có quyền sửa ở hậu đài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_05','V833','阮明',5,'提交申请表之后，多久能同步更新全校教务系统信息？','tí jiāo shēn qǐng biǎo zhī hòu， duō jiǔ néng tóng bù gēng xīn quán xiào jiào wù xì tǒng xìn xī？','Sau khi nộp đơn thì bao lâu thông tin sẽ được đồng bộ cập nhật trên toàn hệ thống giáo vụ của trường ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_06','V833','教务老师',6,'三个工作日内完成修改，更新后打印成绩单姓名同步更正。','sān gè gōng zuò rì nèi wán chéng xiū gǎi， gēng xīn hòu dǎ yìn chéng jì dān xìng míng tóng bù gēng zhèng。','Trong vòng ba ngày làm việc sẽ sửa xong, sau khi cập nhật thì tên trên bảng điểm in ra cũng sẽ được sửa đồng bộ theo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L833_07','V833','阮明',7,'我带好护照复印件，今天提交信息变更申请表。','wǒ dài hǎo hù zhào fù yìn jiàn， jīn tiān tí jiāo xìn xī biàn gēng shēn qǐng biǎo。','Vậy em mang theo bản photo hộ chiếu, hôm nay nộp đơn đề nghị thay đổi thông tin luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT834','SHT5','打印官方成绩单用于升学，咨询打印盖章流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V834','SIT834','P1','suon_se','ban_chinh_thuc',NULL,'境外升学、签证使用的成绩单必须校内官方纸质打印+鲜红公章，自行截图打印无法律效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_01','V834','阮明',1,'老师，我准备升学深造，需要多份加盖公章的官方成绩单。','lǎo shī， wǒ zhǔn bèi shēng xué shēn zào， xū yào duō fèn jiā gài gōng zhāng de guān fāng chéng jì dān。','Thưa thầy/cô, em chuẩn bị học lên cao hơn nên cần vài bản bảng điểm chính thức có đóng dấu đỏ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_02','V834','教务老师',2,'线上系统预约打印，预约完成携带学生证线下领取盖章成绩单哦。','xiàn shàng xì tǒng yù yuē dǎ yìn， yù yuē wán chéng xié dài xué shēng zhèng xiàn xià lǐng qǔ gài zhāng chéng jì dān ó。','Em đặt lịch in trên hệ thống online, đặt xong thì mang thẻ sinh viên đến lấy bảng điểm đã đóng dấu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_03','V834','阮明',3,'电子版成绩单截图自行打印，能不能加盖学院公章？','diàn zi bǎn chéng jì dān jié tú zì xíng dǎ yìn， néng bù néng jiā gài xué yuàn gōng zhāng？','Nếu em tự chụp màn hình bảng điểm điện tử rồi tự in ra thì có được đóng dấu của khoa không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_04','V834','教务老师',4,'仅校内打印机输出的官方纸质成绩单可盖章，自行打印截图无效。','jǐn xiào nèi dǎ yìn jī shū chū de guān fāng zhǐ zhì chéng jì dān kě gài zhāng， zì xíng dǎ yìn jié tú wú xiào。','Chỉ bảng điểm chính thức in từ máy in trong trường mới được đóng dấu, tự chụp màn hình rồi in ra thì không có giá trị đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_05','V834','阮明',5,'一次最多能打印五份，每份都单独加盖红色公章吗？','yī cì zuì duō néng dǎ yìn wǔ fèn， měi fèn dōu dān dú jiā gài hóng sè gōng zhāng ma？','Một lần em có thể in tối đa bao nhiêu bản, mỗi bản đều được đóng dấu đỏ riêng ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_06','V834','教务老师',6,'每份独立盖章，全部具备同等官方效力用于境外升学。','měi fèn dú lì gài zhāng， quán bù jù bèi tóng děng guān fāng xiào lì yòng yú jìng wài shēng xué。','Mỗi bản đều được đóng dấu riêng, tất cả đều có giá trị chính thức như nhau, dùng để học lên ở nước ngoài được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L834_07','V834','阮明',7,'我线上预约打印五份成绩单，下午来办公室领取。','wǒ xiàn shàng yù yuē dǎ yìn wǔ fèn chéng jì dān， xià wǔ lái bàn gōng shì lǐng qǔ。','Vậy em đặt lịch in năm bản bảng điểm trên hệ thống online, chiều nay em qua văn phòng lấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT835','SHT5','报名校内汉语辅导小班，咨询上课时段、收费标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V835','SIT835','P1','suon_se','ban_chinh_thuc',NULL,'校内留学生汉语辅导小班收费低廉，仅收取教材耗材费，用于针对性提升口语、听力薄弱学生。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_01','V835','阮明',1,'老师，我的汉语口语薄弱，想报名校内留学生汉语辅导小班。','lǎo shī， wǒ de hàn yǔ kǒu yǔ bó ruò， xiǎng bào míng xiào nèi liú xué shēng hàn yǔ fǔ dǎo xiǎo bān。','Thưa thầy/cô, khả năng nói tiếng Trung của em còn yếu, em muốn đăng ký lớp phụ đạo tiếng Trung nhỏ dành cho lưu học sinh trong trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_02','V835','辅导老师',2,'小班每周二、四傍晚两节课，一学期统一收取两百元辅导耗材费。','xiǎo bān měi zhōu èr、 sì bàng wǎn liǎng jié kè， yī xué qī tǒng yī shōu qǔ liǎng bǎi yuán fǔ dǎo hào cái fèi。','Lớp nhỏ học vào chiều tối thứ Ba, thứ Năm hàng tuần, mỗi học kỳ thu chung hai trăm tệ phí tài liệu học tập.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_03','V835','阮明',3,'班级人数多少，能保证每个人都有开口练习的机会吗？','bān jí rén shù duō shǎo， néng bǎo zhèng měi gè rén dōu yǒu kāi kǒu liàn xí de jī huì ma？','Sĩ số lớp bao nhiêu người, có đảm bảo ai cũng có cơ hội mở miệng luyện tập không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_04','V835','辅导老师',4,'每班不超过十人，每节课轮流上台对话练习纠正发音。','měi bān bù chāo guò shí rén， měi jié kè lún liú shàng tái duì huà liàn xí jiū zhèng fā yīn。','Mỗi lớp không quá mười người, mỗi buổi học lần lượt lên bảng luyện hội thoại và chỉnh sửa phát âm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_05','V835','阮明',5,'零基础、中级、高级分班，我需要先参加分班测试吗？','líng jī chǔ、 zhōng jí、 gāo jí fēn bān， wǒ xū yào xiān cān jiā fēn bān cè shì ma？','Lớp được chia theo trình độ mất gốc, trung cấp, cao cấp, vậy em có cần tham gia bài kiểm tra xếp lớp trước không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_06','V835','辅导老师',6,'入学简单口语测试，匹配对应难度班级再缴费报名。','rù xué jiǎn dān kǒu yǔ cè shì， pǐ pèi duì yìng nán dù bān jí zài jiǎo fèi bào míng。','Có bài kiểm tra nói đơn giản khi nhập học, xếp vào lớp phù hợp trình độ rồi mới đóng tiền đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L835_07','V835','阮明',7,'我今天完成分班测试，合适就报名本学期汉语辅导小班。','wǒ jīn tiān wán chéng fèn bān cè shì， hé shì jiù bào míng běn xué qī hàn yǔ fǔ dǎo xiǎo bān。','Vậy hôm nay em làm bài kiểm tra xếp lớp trước, nếu phù hợp thì đăng ký lớp phụ đạo tiếng Trung học kỳ này luôn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT836','SHT5','图书馆自习被隔壁同学交谈打扰，找管理员协调安静区域',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V836','SIT836','P1','twist','ban_chinh_thuc',NULL,'图书馆分静音自习区、小组研讨室，交谈讨论必须在专用研讨室，阅览区全程保持安静。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_01','V836','阮明',1,'您好，隔壁座位两位同学持续交谈，严重干扰周边自习同学复习。','nín hǎo， gé bì zuò wèi liǎng wèi tóng xué chí xù jiāo tán， yán zhòng gān rǎo zhōu biān zì xí tóng xué fù xí。','Chào anh/chị, hai bạn ngồi cạnh bàn em cứ nói chuyện liên tục, ảnh hưởng nghiêm trọng đến các bạn xung quanh đang ôn bài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_02','V836','管理员',2,'图书馆阅览区禁止大声交谈，我过去提醒两位同学保持安静。','tú shū guǎn yuè lǎn qū jìn zhǐ dà shēng jiāo tán， wǒ guò qù tí xǐng liǎng wèi tóng xué bǎo chí ān jìng。','Khu đọc sách của thư viện cấm nói chuyện lớn tiếng, để tôi qua nhắc hai bạn đó giữ trật tự.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_03','V836','阮明',3,'如果他们需要小组讨论，有没有专门的讨论室可以转移过去？','rú guǒ tā men xū yào xiǎo zǔ tǎo lùn， yǒu méi yǒu zhuān mén de tǎo lùn shì kě yǐ zhuǎn yí guò qù？','Nếu hai bạn đó cần thảo luận nhóm thì có phòng thảo luận riêng để chuyển sang không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_04','V836','管理员',4,'一楼设有独立小组研讨室，交谈类学习活动统一安排在研讨室嘛。','yī lóu shè yǒu dú lì xiǎo zǔ yán tǎo shì， jiāo tán lèi xué xí huó dòng tǒng yī ān pái zài yán tǎo shì ma。','Tầng một có phòng thảo luận nhóm riêng, các hoạt động học tập cần trao đổi đều được sắp xếp vào phòng thảo luận đó cả mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_05','V836','阮明',5,'我想要全程安静无交谈的区域，能不能调整我的自习座位？','wǒ xiǎng yào quán chéng ān jìng wú jiāo tán de qū yù， néng bù néng tiáo zhěng wǒ de zì xí zuò wèi？','Em muốn ngồi ở khu vực hoàn toàn yên tĩnh, không ai nói chuyện, vậy có thể đổi chỗ ngồi cho em không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_06','V836','管理员',6,'二楼深度自习区全程静音，我带你去空位落座不受打扰。','èr lóu shēn dù zì xí qū quán chéng jìng yīn， wǒ dài nǐ qù kòng wèi luò zuò bù shòu dǎ rǎo。','Khu tự học chuyên sâu ở tầng hai im lặng hoàn toàn, để tôi dẫn em đến chỗ trống ngồi, không bị làm phiền đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L836_07','V836','阮明',7,'感谢协调安静自习区域，方便我专心复习期末内容。','gǎn xiè xié tiáo ān jìng zì xí qū yù， fāng biàn wǒ zhuān xīn fù xí qī mò nèi róng。','Cảm ơn anh/chị đã sắp xếp khu vực yên tĩnh, giờ em có thể yên tâm tập trung ôn thi cuối kỳ rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT837','SHT5','报名校内学术讲座，咨询签到、综测加分规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V837','SIT837','P1','suon_se','tuy_y',NULL,'国内高校综测体系包含学术讲座、竞赛加分，需全程到场完成签到流程才能录入加分记录。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_01','V837','阮明',1,'你好，我想报名本周外贸学术讲座，请问参与能综测加分吗？','nǐ hǎo， wǒ xiǎng bào míng běn zhōu wài mào xué shù jiǎng zuò， qǐng wèn cān yù néng zōng cè jiā fēn ma？','Chào anh, em muốn đăng ký buổi hội thảo học thuật về ngoại thương tuần này, tham gia có được cộng điểm tổng hợp không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_02','V837','干事',2,'现场签到、听完讲座提交简短心得，一次讲座加0.2综测分哦。','xiàn chǎng qiān dào、 tīng wán jiǎng zuò tí jiāo jiǎn duǎn xīn dé， yī cì jiǎng zuò jiā 0.2 zōng cè fēn ó。','Điểm danh trực tiếp, nghe xong hội thảo nộp bài thu hoạch ngắn, mỗi buổi được cộng 0.2 điểm tổng hợp nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_03','V837','阮明',3,'讲座时长两小时，中途提前离场还能正常计入加分吗？','jiǎng zuò shí cháng liǎng xiǎo shí， zhōng tú tí qián lí chǎng hái néng zhèng cháng jì rù jiā fēn ma？','Hội thảo kéo dài hai tiếng, nếu giữa chừng ra về sớm thì có được tính cộng điểm bình thường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_04','V837','干事',4,'全程听完签到两次（入场、散场），中途离场不予记录加分。','quán chéng tīng wán qiān dào liǎng cì （rù chǎng、 sàn chǎng）， zhōng tú lí chǎng bù yǔ jì lù jiā fēn。','Phải nghe hết toàn bộ và điểm danh hai lần (lúc vào, lúc tan), ra về giữa chừng thì không được ghi nhận cộng điểm đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_05','V837','阮明',5,'讲座名额有限，需要提前线上报名锁定席位吗？','jiǎng zuò míng é yǒu xiàn， xū yào tí qián xiàn shàng bào míng suǒ dìng xí wèi ma？','Số suất tham gia hội thảo có hạn, vậy có cần đăng ký trước trên mạng để giữ chỗ không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_06','V837','干事',6,'线上小程序提前预约，无预约现场有空位也可临时入场。','xiàn shàng xiǎo chéng xù tí qián yù yuē， wú yù yuē xiàn chǎng yǒu kòng wèi yě kě lín shí rù chǎng。','Đặt chỗ trước qua app mini trên mạng, nếu không đặt trước mà tại chỗ còn suất trống thì vẫn có thể vào tạm được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L837_07','V837','阮明',7,'我线上预约席位，全程参与讲座完成签到拿综测加分。','wǒ xiàn shàng yù yuē xí wèi， quán chéng cān yù jiǎng zuò wán chéng qiān dào ná zōng cè jiā fēn。','Vậy em đặt chỗ trước trên mạng, tham gia đầy đủ hội thảo, điểm danh xong để lấy điểm cộng tổng hợp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT838','SHT5','和中国同学结成语言交换搭档，约定每周练习时段',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V838','SIT838','P1','suon_se','tuy_y',NULL,'高校留学生与本国学生结成语言交换搭档是普遍互助学习方式，双方互相教授母语，零成本提升口语能力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_01','V838','阮明',1,'我们结成语言交换搭档吧，我教你越南语，你帮我练习汉语。','wǒ men jié chéng yǔ yán jiāo huàn dā dàng ba， wǒ jiāo nǐ yuè nán yǔ， nǐ bāng wǒ liàn xí hàn yǔ。','Hay là mình kết đôi trao đổi ngôn ngữ đi, tớ dạy cậu tiếng Việt, cậu giúp tớ luyện tiếng Trung nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_02','V838','苏雯',2,'太好了，每周三傍晚两小时，一半时间汉语、一半越南语互换练习。','tài hǎo le， měi zhōu sān bàng wǎn liǎng xiǎo shí， yí bàn shí jiān hàn yǔ、 yí bàn yuè nán yǔ hù huàn liàn xí。','Tuyệt quá, mỗi tuần chiều tối thứ Tư hai tiếng, một nửa thời gian nói tiếng Trung, một nửa nói tiếng Việt để luyện đổi qua lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_03','V838','阮明',3,'练习地点图书馆一楼研讨室，有白板方便写单词、句子讲解对吧？','liàn xí dì diǎn tú shū guǎn yī lóu yán tǎo shì， yǒu bái bǎn fāng biàn xiě dān cí、 jù zi jiǎng jiě duì ba？','Địa điểm luyện tập là phòng thảo luận tầng một thư viện, có bảng trắng để viết từ vựng, giải thích câu cho dễ đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_04','V838','苏雯',4,'研讨室安静，不会打扰其他人，还能书写词汇互相讲解。','yán tǎo shì ān jìng， bú huì dǎ rǎo qí tā rén， hái néng shū xiě cí huì hù xiāng jiǎng jiě。','Phòng thảo luận yên tĩnh, không làm phiền ai cả, lại có thể viết từ vựng ra để giải thích cho nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_05','V838','阮明',5,'每次结束布置少量口语练习任务，下周见面复盘巩固。','měi cì jié shù bù zhì shǎo liàng kǒu yǔ liàn xí rèn wù， xià zhōu jiàn miàn fù pán gǒng gù。','Mỗi lần học xong thì giao một ít bài tập luyện nói, tuần sau gặp lại thì ôn lại và củng cố nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_06','V838','苏雯',6,'分工互补互相提升语言，长期坚持进步会很明显。','fēn gōng hù bǔ hù xiāng tí shēng yǔ yán， cháng qī jiān chí jìn bù huì hěn míng xiǎn。','Bổ trợ qua lại như vậy, cùng nâng cao ngôn ngữ của nhau, kiên trì lâu dài thì tiến bộ sẽ thấy rõ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L838_07','V838','阮明',7,'每周三固定时段见面语言交换，稳步提升双方外语水平。','měi zhōu sān gù dìng shí duàn jiàn miàn yǔ yán jiāo huàn， wěn bù tí shēng shuāng fāng wài yǔ shuǐ píng。','Vậy cố định mỗi thứ Tư hàng tuần gặp nhau trao đổi ngôn ngữ, từng bước nâng cao trình độ ngoại ngữ của cả hai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT839','SHT5','咨询综测加分项目：讲座、竞赛、论文申报规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V839','SIT839','P1','suon_se','ban_chinh_thuc',NULL,'综测分数用于奖学金、评优评先，各类学术活动加分可叠加，但设置单学年加分上限。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_01','V839','阮明',1,'老师，想咨询留学生综合测评加分全部可申报项目细则。','lǎo shī， xiǎng zī xún liú xué shēng zōng hé cè píng jiā fēn quán bù kě shēn bào xiàng mù xì zé。','Thưa thầy/cô, em muốn hỏi chi tiết quy định về tất cả các hạng mục có thể đăng ký để cộng điểm tổng hợp cho lưu học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_02','V839','教务老师',2,'分为学术讲座、学科竞赛、期刊论文、社会实践四大类加分。','fēn wéi xué shù jiǎng zuò、 xué kē jìng sài、 qī kān lùn wén、 shè huì shí jiàn sì dà lèi jiā fēn。','Chia thành bốn nhóm lớn để cộng điểm là hội thảo học thuật, thi đấu học thuật, bài báo đăng tạp chí, và thực tế xã hội.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_03','V839','阮明',3,'校级汉语竞赛拿奖，一次能加多少综测分数？','xiào jí hàn yǔ jìng sài ná jiǎng， yī cì néng jiā duō shǎo zōng cè fēn shù？','Nếu đạt giải trong cuộc thi tiếng Trung cấp trường thì một lần được cộng bao nhiêu điểm tổng hợp ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_04','V839','教务老师',4,'校级竞赛三等奖0.3分、二等奖0.5分、一等奖0.8分，逐级递增。','xiào jí jìng sài sān děng jiǎng 0.3 fēn、 èr děng jiǎng 0.5 fēn、 yì děng jiǎng 0.8 fēn， zhú jí dì zēng。','Giải ba cấp trường được 0.3 điểm, giải nhì 0.5 điểm, giải nhất 0.8 điểm, tăng dần theo thứ hạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_05','V839','阮明',5,'发表普通校园期刊短文，论文加分和竞赛加分可以叠加吗？','fā biǎo pǔ tōng xiào yuán qī kān duǎn wén， lùn wén jiā fēn hé jìng sài jiā fēn kě yǐ dié jiā ma？','Nếu đăng bài viết ngắn trên tạp chí thông thường của trường, thì điểm cộng cho bài báo và điểm cộng thi đấu có được cộng dồn với nhau không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_06','V839','教务老师',6,'全部项目加分可叠加，单学年综测加分上限两分。','quán bù xiàng mù jiā fēn kě dié jiā， dān xué nián zōng cè jiā fēn shàng xiàn liǎng fēn。','Tất cả các hạng mục đều được cộng dồn, nhưng mức trần cộng điểm tổng hợp trong một năm học là hai điểm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L839_07','V839','阮明',7,'我多参与讲座、汉语竞赛，争取提升学年综测分数。','wǒ duō cān yù jiǎng zuò、 hàn yǔ jìng sài， zhēng qǔ tí shēng xué nián zōng cè fēn shù。','Vậy em sẽ tham gia thêm hội thảo và thi tiếng Trung, cố gắng nâng điểm tổng hợp của năm học lên ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT840','SHT5','报名校级汉语竞赛，咨询参赛材料、评比标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V840','SIT840','P1','twist','tuy_y',NULL,'留学生汉语竞赛综合考察发音、逻辑表达，禁止剪辑配音视频，保证真实口语水平比拼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_01','V840','阮明',1,'你好，我想报名校级留学生汉语竞赛，需要准备什么参赛材料？','nǐ hǎo， wǒ xiǎng bào míng xiào jí liú xué shēng hàn yǔ jìng sài， xū yào zhǔn bèi shén me cān sài cái liào？','Chào anh, em muốn đăng ký cuộc thi tiếng Trung cấp trường dành cho lưu học sinh, cần chuẩn bị những tài liệu dự thi gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_02','V840','干事',2,'线上提交一分钟汉语自我介绍视频，线下现场参与演讲答题环节。','xiàn shàng tí jiāo yì fēn zhōng hàn yǔ zì wǒ jiè shào shì pín， xiàn xià xiàn chǎng cān yù yǎn jiǎng dá tí huán jié。','Nộp online một video tự giới thiệu bằng tiếng Trung dài một phút, rồi tham gia phần thuyết trình và trả lời câu hỏi trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_03','V840','阮明',3,'竞赛评分侧重发音标准，还是内容立意、流畅度综合评判？','jìng sài píng fēn cè zhòng fā yīn biāo zhǔn， hái shì nèi róng lì yì、 liú chàng dù zōng hé píng pàn？','Cuộc thi chấm điểm thiên về phát âm chuẩn, hay là đánh giá tổng hợp cả nội dung ý tưởng và độ trôi chảy vậy anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_04','V840','干事',4,'发音40%、内容立意30%、表达流畅度30%，三项综合打分嘛。','fā yīn 40%、 nèi róng lì yì 30%、 biǎo dá liú chàng dù 30%， sān xiàng zōng hé dǎ fēn ma。','Phát âm 40%, nội dung ý tưởng 30%, độ trôi chảy khi diễn đạt 30%, chấm điểm tổng hợp cả ba tiêu chí đó mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_05','V840','阮明',5,'报名截止后天傍晚，我今天录制自我介绍视频线上提交。','bào míng jié zhǐ hòu tiān bàng wǎn， wǒ jīn tiān lù zhì zì wǒ jiè shào shì pín xiàn shàng tí jiāo。','Hạn đăng ký là chiều tối ngày kia, vậy hôm nay em quay video tự giới thiệu rồi nộp online luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_06','V840','干事',6,'视频不能后期剪辑配音，必须完整现场原声录制。','shì pín bù néng hòu qī jiǎn jí pèi yīn， bì xū wán zhěng xiàn chǎng yuán shēng lù zhì。','Video không được dựng hậu kỳ hay lồng tiếng, bắt buộc phải quay trọn vẹn bằng âm thanh gốc tại chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L840_07','V840','阮明',7,'我无剪辑完整录制视频，按时提交参赛报名素材。','wǒ wú jiǎn jí wán zhěng lù zhì shì pín， àn shí tí jiāo cān sài bào míng sù cái。','Em không chỉnh sửa gì, quay trọn vẹn video và nộp tài liệu đăng ký dự thi đúng hạn ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT901','SXH1','主动询问球场陌生人，加入临时羽毛球组队玩耍',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V901','SIT901','P1','suon_se','tuy_y',NULL,'国内校园运动场临时组队十分普遍，场地、球具费用当场AA分摊，陌生人共同运动很容易快速熟悉。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_01','V901','阮明',1,'你好，看你们还差一位队友，我可以加入一起打羽毛球吗？','nǐ hǎo， kàn nǐ men hái chà yī wèi duì yǒu， wǒ kě yǐ jiā rù yì qǐ dǎ yǔ máo qiú ma？','Chào bạn, mình thấy các bạn thiếu một người, cho mình chơi cầu lông cùng luôn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_02','V901','小杨',2,'没问题，正好缺人，你有自带球拍还是用球场公用拍？','méi wèn tí， zhèng hǎo quē rén， nǐ yǒu zì dài qiú pāi hái shì yòng qiú chǎng gōng yòng pāi？','Không vấn đề gì, đang thiếu người đây, bạn có mang vợt riêng không hay dùng vợt của sân?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_03','V901','阮明',3,'我带了球拍，咱们打两小时，场地费四个人平分对吧？','wǒ dài le qiú pāi， zán men dǎ liǎng xiǎo shí， chǎng dì fèi sì gè rén píng fēn duì ba？','Mình có mang vợt rồi, chơi hai tiếng thôi nhé, tiền sân chia đều bốn người đúng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_04','V901','小杨',4,'对，打完现场AA转账，每个人摊下来很便宜的。','duì， dǎ wán xiàn chǎng AA zhuǎn zhàng， měi gè rén tān xià lái hěn pián yi de。','Đúng rồi, chơi xong chuyển khoản AA luôn, chia ra mỗi người có mấy đồng à.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_05','V901','阮明',5,'太好了，平时很少找到人一起打球，今天刚好赶上。','tài hǎo le， píng shí hěn shǎo zhǎo dào rén yì qǐ dǎ qiú， jīn tiān gāng hǎo gǎn shàng。','Tuyệt quá, bình thường ít khi kiếm được người chơi cùng, hôm nay đúng lúc gặp được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_06','V901','小杨',6,'每周四下午我们都会来球场，你有空可以常过来组队。','měi zhōu sì xià wǔ wǒ men dōu huì lái qiú chǎng， nǐ yǒu kòng kě yǐ cháng guò lái zǔ duì。','Tụi mình cứ chiều thứ Năm hàng tuần là ra sân, bạn rảnh thì cứ qua chơi chung nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L901_07','V901','阮明',7,'记下时间，下周同一时间我再来球场找你们。','jì xià shí jiān， xià zhōu tóng yī shí jiān wǒ zài lái qiú chǎng zhǎo nǐ men。','Ghi lại giờ rồi, tuần sau cùng giờ này mình lại ra sân tìm mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT902','SXH1','观看校园文艺晚会，和身边陌生同学简单搭话交流观感',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V902','SIT902','P1','twist','tuy_y',NULL,'看演出时和邻座陌生人聊节目内容是自然破冰方式，国内学生不会觉得唐突。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_01','V902','阮明',1,'刚刚那个民族舞蹈节目编排真好看，你觉得怎么样？','gāng gāng nà ge mín zú wǔ dǎo jié mù biān pái zhēn hǎo kàn， nǐ jué de zěn me yàng？','Tiết mục múa dân tộc lúc nãy dàn dựng đẹp thật đấy, bạn thấy sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_02','V902','陈雨',2,'我也很喜欢，就是灯光有点暗，演员面部细节看不清呢。','wǒ yě hěn xǐ huān， jiù shì dēng guāng yǒu diǎn àn， yǎn yuán miàn bù xì jié kàn bù qīng ne。','Mình cũng thích lắm, chỉ tội ánh sáng hơi tối, nhìn không rõ mặt diễn viên.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_03','V902','阮明',3,'后面还有留学生合唱节目，听说有东南亚语种的歌曲。','hòu miàn hái yǒu liú xué shēng hé chàng jié mù， tīng shuō yǒu dōng nán yà yǔ zhǒng de gē qǔ。','Lát nữa còn có tiết mục hợp xướng của du học sinh nữa, nghe nói có bài hát tiếng Đông Nam Á đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_04','V902','陈雨',4,'我特意留到最后看，可惜中场手机没电，没法拍照记录。','wǒ tè yì liú dào zuì hòu kàn， kě xī zhōng chǎng shǒu jī méi diàn， méi fǎ pāi zhào jì lù。','Mình cố tình ở lại xem đến cuối, tiếc là giữa chừng điện thoại hết pin, không chụp ảnh lưu lại được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_05','V902','阮明',5,'我的手机电量充足，等下节目结束可以分几张照片给你。','wǒ de shǒu jī diàn liàng chōng zú， děng xià jié mù jié shù kě yǐ fēn jǐ zhāng zhào piān gěi nǐ。','Điện thoại mình còn đầy pin, lát nữa hết chương trình mình gửi vài tấm cho bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_06','V902','陈雨',6,'太感谢啦，晚会结束加个联系方式，方便你发图给我。','tài gǎn xiè la， wǎn huì jié shù jiā gè lián xì fāng shì， fāng biàn nǐ fā tú gěi wǒ。','Cảm ơn nhiều nha, xong buổi kết bạn Zalo đi để bạn gửi ảnh cho mình tiện hơn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L902_07','V902','阮明',7,'好，散场之后我们互相加好友，分享晚会现场照片。','hǎo， sàn chǎng zhī hòu wǒ men hù xiāng jiā hǎo yǒu， fēn xiǎng wǎn huì xiàn chǎng zhào piān。','Ừ, tan buổi rồi mình kết bạn với nhau, chia sẻ ảnh chụp tối nay cho vui.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT903','SXH1','报名校内志愿公益活动，活动中结识不同专业同学',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V903','SIT903','P1','suon_se','ban_chinh_thuc',NULL,'校内志愿活动是跨专业社交主流渠道，国内学生普遍愿意通过公益活动拓展朋友圈。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_01','V903','阮明',1,'学姐你好，我想报名周末社区敬老志愿活动，需要什么流程？','xué jiě nǐ hǎo， wǒ xiǎng bào míng zhōu mò shè qū jìng lǎo zhì yuàn huó dòng， xū yào shén me liú chéng？','Chào chị, em muốn đăng ký hoạt động tình nguyện chăm sóc người già cuối tuần, cần làm những thủ tục gì ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_02','V903','学姐',2,'线上填报名表单，周六早上八点在校门口集合统一出发哦。','xiàn shàng tián bào míng biǎo dān， zhōu liù zǎo shàng bā diǎn zài xiào mén kǒu jí hé tǒng yī chū fā ó。','Điền form đăng ký online, sáng thứ Bảy tám giờ tập trung ở cổng trường rồi cùng xuất phát nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_03','V903','阮明',3,'活动都是不同学院的学生参加吗，会不会只有我们专业？','huó dòng dōu shì bù tóng xué yuàn de xué shēng cān jiā ma， huì bú huì zhǐ yǒu wǒ men zhuān yè？','Hoạt động có sinh viên nhiều khoa khác nhau tham gia không, hay chỉ có mỗi ngành mình vậy chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_04','V903','学姐',4,'全校各专业都有人报名，正好能认识很多新朋友。','quán xiào gè zhuān yè dōu yǒu rén bào míng， zhèng hǎo néng rèn shí hěn duō xīn péng yǒu。','Cả trường ngành nào cũng có người đăng ký hết, đúng dịp để quen thêm nhiều bạn mới đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_05','V903','阮明',5,'活动主要做哪些工作，我提前准备简单的小节目给老人。','huó dòng zhǔ yào zuò nǎ xiē gōng zuò， wǒ tí qián zhǔn bèi jiǎn dān de xiǎo jié mù gěi lǎo rén。','Hoạt động chủ yếu làm những việc gì ạ, em chuẩn bị trước một tiết mục nhỏ cho các cụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_06','V903','学姐',6,'陪老人聊天、打扫房间，会才艺的话表演小段节目很受欢迎。','péi lǎo rén liáo tiān、 dǎ sǎo fáng jiān， huì cái yì de huà biǎo yǎn xiǎo duàn jié mù hěn shòu huān yíng。','Chủ yếu là trò chuyện với các cụ, dọn phòng, ai có tài lẻ thì biểu diễn một đoạn nhỏ được hưởng ứng lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L903_07','V903','阮明',7,'我准备一段越南简单民谣，周末准时来参与志愿活动。','wǒ zhǔn bèi yī duàn yuè nán jiǎn dān mín yáo， zhōu mò zhǔn shí lái cān yù zhì yuàn huó dòng。','Em chuẩn bị một bài dân ca Việt Nam đơn giản, cuối tuần sẽ đến tham gia tình nguyện đúng giờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT904','SXH1','约朋友周末去城市公园徒步、逛景区，协商出行路线预算',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V904','SIT904','P1','twist','tuy_y',NULL,'多人外出游玩会兼顾体力、预算、返程时间集体协商，所有公共开销统一AA是通用社交规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_01','V904','阮明',1,'这周末天气很好，我们约上几个朋友去郊外公园徒步好不好？','zhè zhōu mò tiān qì hěn hǎo， wǒ men yuē shàng jǐ gè péng yǒu qù jiāo wài gōng yuán tú bù hǎo bù hǎo？','Cuối tuần này thời tiết đẹp lắm, tụi mình rủ thêm mấy đứa bạn ra công viên ngoại ô đi bộ nhé?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_02','V904','苏雯',2,'可以，有两条路线，短途两小时、长途五小时，大家体力不一样。','kě yǐ， yǒu liǎng tiáo lù xiàn， duǎn tú liǎng xiǎo shí、 cháng tú wǔ xiǎo shí， dà jiā tǐ lì bù yí yàng。','Được đó, có hai lộ trình, ngắn thì hai tiếng, dài thì năm tiếng, mỗi người sức khỏe khác nhau mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_03','V904','阮明',3,'长途路程远，来回公交票价会高出不少，预算需要提前算清嘛。','cháng tú lù chéng yuǎn， lái huí gōng jiāo piào jià huì gāo chū bù shǎo， yù suàn xū yào tí qián suàn qīng ma。','Đi tuyến dài xa hơn, tiền vé xe buýt khứ hồi cũng đắt hơn kha khá, phải tính trước ngân sách chứ nhỉ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_04','V904','苏雯',4,'那我们先问所有人意愿，多数人选短途就走轻松路线。','nà wǒ men xiān wèn suǒ yǒu rén yì yuàn， duō shù rén xuǎn duǎn tú jiù zǒu qīng sōng lù xiàn。','Vậy mình hỏi ý kiến mọi người trước đã, đa số chọn tuyến ngắn thì đi cho nhẹ nhàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_05','V904','阮明',5,'零食、矿泉水我来采购，所有人AA分摊食材花费。','líng shí、 kuàng quán shuǐ wǒ lái cǎi gòu， suǒ yǒu rén AA fēn tān shí cái huā fèi。','Đồ ăn vặt với nước suối để mình lo mua, mọi người chia đều tiền đồ ăn theo kiểu AA nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_06','V904','苏雯',6,'傍晚返程避开晚高峰，不会耽误晚上自习休息。','bàng wǎn fǎn chéng bì kāi wǎn gāo fēng， bú huì dān wù wǎn shàng zì xí xiū xī。','Chiều về tránh giờ cao điểm, khỏi ảnh hưởng đến giờ tự học tối nay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L904_07','V904','阮明',7,'我现在在群里征集大家意见，敲定最终出行方案。','wǒ xiàn zài zài qún lǐ zhēng jí dà jiā yì jiàn， qiāo dìng zuì zhōng chū xíng fāng àn。','Giờ mình đang hỏi ý kiến mọi người trong nhóm, chốt phương án đi chơi cuối cùng luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT905','SXH1','宿舍公共观影夜，和室友商量影片选择、零食分摊',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V905','SIT905','P1','suon_se','tuy_y',NULL,'宿舍集体活动零食、饮品费用均分，同时会考虑周边宿舍作息，控制活动结束时间避免噪音扰民。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_01','V905','阮明',1,'今晚没课，我们宿舍办观影夜，大家投票选一部电影看吧？','jīn wǎn méi kè， wǒ men sù shè bàn guān yǐng yè， dà jiā tóu piào xuǎn yī bù diàn yǐng kàn ba？','Tối nay không có tiết, tụi mình tổ chức xem phim trong phòng ký túc xá, biểu quyết chọn một bộ đi?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_02','V905','小林',2,'有人想看喜剧，有人想看纪实纪录片，很难统一口味。','yǒu rén xiǎng kàn xǐ jù， yǒu rén xiǎng kàn jì shí jì lù piàn， hěn nán tǒng yī kǒu wèi。','Có người muốn xem hài, có người lại muốn xem phim tài liệu, khó mà hợp khẩu vị hết được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_03','V905','阮明',3,'那分上下半场，先放喜剧，后半段看纪实短片兼顾所有人。','nà fēn shàng xià bàn chǎng， xiān fàng xǐ jù， hòu bàn duàn kàn jì shí duǎn piàn jiān gù suǒ yǒu rén。','Vậy chia đôi buổi, nửa đầu chiếu hài, nửa sau xem phim tài liệu ngắn cho hợp ý mọi người luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_04','V905','小林',4,'零食饮料统一网购，下单之后四个人平均分摊费用。','líng shí yǐn liào tǒng yī wǎng gòu， xià dān zhī hòu sì gè rén píng jūn fēn tān fèi yòng。','Đồ ăn vặt với nước ngọt đặt online chung, đặt xong rồi bốn người chia đều tiền nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_05','V905','阮明',5,'我负责挑选影片，你统计大家想吃的零食清单。','wǒ fù zé tiāo xuǎn yǐng piàn， nǐ tǒng jì dà jiā xiǎng chī de líng shí qīng dān。','Mình lo chọn phim, bạn tổng hợp danh sách đồ ăn vặt mọi người muốn ăn nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_06','V905','小林',6,'熄灯前结束观影，不熬夜打扰隔壁宿舍休息。','xī dēng qián jié shù guān yǐng， bù áo yè dǎ rǎo gé bì sù shè xiū xī。','Xem xong trước giờ tắt đèn, khỏi thức khuya làm phiền phòng bên cạnh nghỉ ngơi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L905_07','V905','阮明',7,'安排妥当，今晚宿舍一起轻松放松一下。','ān pái tuǒ dàng， jīn wǎn sù shè yì qǐ qīng sōng fàng sōng yī xià。','Sắp xếp ổn thỏa rồi, tối nay cả phòng cùng thư giãn một chút cho vui.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT906','SXH1','校内桌游局，询问新人参与规则、是否收取分摊费用',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V906','SIT906','P1','that_bai_nhe','tuy_y',NULL,'线下桌游聚会大多会点饮品，多数人默认统一分摊，若有饮食禁忌可单独结算，无需勉强跟随大众消费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_01','V906','阮明',1,'我第一次来桌游局，想问游戏规则和场地费用怎么算？','wǒ dì yī cì lái zhuō yóu jú， xiǎng wèn yóu xì guī zé hé chǎng dì fèi yòng zěn me suàn？','Mình lần đầu đến chơi board game, cho mình hỏi luật chơi với tiền sân tính thế nào vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_02','V906','小周',2,'桌游社提供全部卡牌，活动室免费使用，只需要AA奶茶钱。','zhuō yóu shè tí gōng quán bù kǎ pái， huó dòng shì miǎn fèi shǐ yòng， zhǐ xū yào AA nǎi chá qián。','Câu lạc bộ board game cung cấp hết bài rồi, phòng sinh hoạt dùng miễn phí, chỉ cần chia tiền trà sữa AA thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_03','V906','阮明',3,'奶茶可以不点，只参与游戏不用分摊饮品费用吗？','nǎi chá kě yǐ bù diǎn， zhǐ cān yù yóu xì bù yòng fēn tān yǐn pǐn fèi yòng ma？','Vậy không gọi trà sữa, chỉ tham gia chơi game thôi thì không cần chia tiền đồ uống đúng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_04','V906','小周',4,'大家默认每人点一杯饮品，不点的话有点不合群嘛。','dà jiā mò rèn měi rén diǎn yī bēi yǐn pǐn， bù diǎn de huà yǒu diǎn bù hé qún ma。','Mọi người mặc định mỗi người gọi một ly, không gọi thì hơi lạc lõng với nhóm đó nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_05','V906','阮明',5,'我肠胃不适合喝甜饮，单独买矿泉水，只分摊矿泉水费用行吗？','wǒ cháng wèi bú shì hé hē tián yǐn， dān dú mǎi kuàng quán shuǐ， zhǐ fēn tān kuàng quán shuǐ fèi yòng xíng ma？','Bụng mình không hợp uống đồ ngọt, mình mua riêng nước suối, chỉ chia tiền nước suối thôi được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_06','V906','小周',6,'没问题，跟老板说清楚，只算自己饮用水的钱。','méi wèn tí， gēn lǎo bǎn shuō qīng chǔ， zhǐ suàn zì jǐ yǐn yòng shuǐ de qián。','Không sao đâu, nói rõ với chủ quán là được, chỉ tính tiền nước bạn uống thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L906_07','V906','阮明',7,'好，我先学习基础桌游规则，不勉强自己点奶茶。','hǎo， wǒ xiān xué xí jī chǔ zhuō yóu guī zé， bù miǎn qiǎng zì jǐ diǎn nǎi chá。','Được rồi, để mình học luật chơi cơ bản trước, không ép mình gọi trà sữa nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT907','SXH1','参加校园国际文化节，展示本国特色小吃与传统手工',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V907','SIT907','P1','suon_se','ban_chinh_thuc',NULL,'校园国际文化节鼓励各国留学生展示本土美食、手工艺，是跨文化交流、结交各国朋友的重要活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_01','V907','阮明',1,'老师，我报名文化节摊位，准备越南春卷和手工竹编展示可以吗？','lǎo shī， wǒ bào míng wén huà jié tān wèi， zhǔn bèi yuè nán chūn juǎn hé shǒu gōng zhú biān zhǎn shì kě yǐ ma？','Thưa cô, em đăng ký gian hàng lễ hội văn hóa, chuẩn bị chả giò Việt Nam với trưng bày đan tre thủ công có được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_02','V907','老师',2,'完全合适，每个国家摊位提供少量试吃，吸引其他同学参观哦。','wán quán hé shì， měi gè guó jiā tān wèi tí gōng shǎo liàng shì chī， xī yǐn qí tā tóng xué cān guān ó。','Hoàn toàn phù hợp, mỗi gian hàng của mỗi nước sẽ cho nếm thử một chút, thu hút các bạn khác đến tham quan nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_03','V907','阮明',3,'食材采购费用学院有补贴，还是需要留学生自行承担？','shí cái cǎi gòu fèi yòng xué yuàn yǒu bǔ tiē， hái shì xū yào liú xué shēng zì xíng chéng dān？','Chi phí nguyên liệu khoa có hỗ trợ không ạ, hay là du học sinh phải tự lo hết?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_04','V907','老师',4,'基础食材学院报销，额外精致配料由个人自愿准备。','jī chǔ shí cái xué yuàn bào xiāo， é wài jīng zhì pèi liào yóu gè rén zì yuàn zhǔn bèi。','Nguyên liệu cơ bản khoa thanh toán lại, còn nguyên liệu tinh xảo thêm thì tự nguyện chuẩn bị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_05','V907','阮明',5,'我现场简单演示竹编手法，方便来往同学体验手工。','wǒ xiàn chǎng jiǎn dān yǎn shì zhú biān shǒu fǎ， fāng biàn lái wǎng tóng xué tǐ yàn shǒu gōng。','Em sẽ trình diễn trực tiếp cách đan tre luôn, để các bạn qua lại tiện trải nghiệm thủ công.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_06','V907','老师',6,'活动当天人流量很大，提前半小时到场布置摊位。','huó dòng dàng tiān rén liú liàng hěn dà， tí qián bàn xiǎo shí dào chǎng bù zhì tān wèi。','Hôm diễn ra hoạt động lượng người rất đông, đến sớm nửa tiếng để dọn dẹp gian hàng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L907_07','V907','阮明',7,'我提前备好食材与手工材料，文化节准时布置摊位。','wǒ tí qián bèi hǎo shí cái yǔ shǒu gōng cái liào， wén huà jié zhǔn shí bù zhì tān wèi。','Em sẽ chuẩn bị sẵn nguyên liệu và đồ thủ công trước, đến giờ lễ hội là dọn gian hàng ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT908','SXH2','多人聚餐AA结算，核对账单、分摊转账，有人忘记付款提醒对方',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V908','SIT908','P1','twist','tuy_y',NULL,'多人AA聚餐统一由一人代收款项，提醒未付款人时语气委婉，避免让对方产生被催促的尴尬。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_01','V908','阮明',1,'我把餐厅完整账单发到群里，所有人人均三十五元，核对一下。','wǒ bǎ cān tīng wán zhěng zhàng dān fā dào qún lǐ， suǒ yǒu rén rén jūn sān shí wǔ yuán， hé duì yī xià。','Mình gửi hóa đơn đầy đủ của nhà hàng lên nhóm rồi, mỗi người ba mươi lăm đồng, mọi người kiểm tra lại giúp mình nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_02','V908','苏雯',2,'大部分人已经转账给我，只有两位同学还没有付款。','dà bù fèn rén yǐ jīng zhuǎn zhàng gěi wǒ， zhǐ yǒu liǎng wèi tóng xué hái méi yǒu fù kuǎn。','Phần lớn mọi người chuyển khoản cho mình rồi, chỉ còn hai bạn chưa thanh toán thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_03','V908','阮明',3,'可能他们忘记看群消息，我温和提醒一句，别让对方尴尬。','kě néng tā men wàng jì kàn qún xiāo xī， wǒ wēn hé tí xǐng yī jù， bié ràng duì fāng gān gà。','Chắc họ quên xem tin nhắn nhóm, để mình nhắc nhẹ một câu, đừng để người ta ngại nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_04','V908','苏雯',4,'说得委婉一点，就说我统一收款后要给店家结账。','shuō dé wěi wǎn yì diǎn， jiù shuō wǒ tǒng yī shōu kuǎn hòu yào gěi diàn jiā jié zhàng。','Nói khéo một chút thôi, cứ bảo là mình gom đủ tiền rồi mới thanh toán cho quán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_05','V908','阮明',5,'各位，麻烦有空转一下聚餐分摊费，我今晚统一结清账单哈。','gè wèi， má fán yǒu kòng zhuǎn yī xià jù cān fēn tān fèi， wǒ jīn wǎn tǒng yī jié qīng zhàng dān hā。','Mọi người ơi, ai rảnh thì chuyển khoản tiền chia phần bữa ăn giúp mình nhé, tối nay mình thanh toán hết luôn ạ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_06','V908','小林',6,'收到，我现在立刻转账，刚才自习完全没看手机。','shōu dào， wǒ xiàn zài lì kè zhuǎn zhàng， gāng cái zì xí wán quán méi kàn shǒu jī。','Nhận được rồi, mình chuyển khoản ngay đây, lúc nãy tự học xong có xem điện thoại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L908_07','V908','阮明',7,'全部款项收齐，这次聚餐开销结算完毕。','quán bù kuǎn xiàng shōu qí， zhè cì jù cān kāi xiāo jié suàn wán bì。','Thu đủ hết tiền rồi, bữa ăn lần này coi như thanh toán xong xuôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT909','SXH2','朋友过节送小礼物，推辞几番后礼貌收下并回赠伴手礼',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V909','SIT909','P1','suon_se','tuy_y',NULL,'国内人情讲究礼尚往来，收到礼物会先礼貌推辞一次再收下，后续准备等价小伴手礼回赠对方。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_01','V909','阮明',1,'不用特意给我准备中秋月饼，太破费啦，我不好意思收下。','bù yòng tè yì gěi wǒ zhǔn bèi zhōng qiū yuè bǐng， tài pò fèi la， wǒ bù hǎo yì sī shōu xià。','Cậu không cần đặc biệt chuẩn bị bánh Trung thu cho tớ đâu, tốn kém quá, tớ ngại nhận lắm.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_02','V909','苏雯',2,'只是一盒普通月饼，一点心意，你不用跟我客气。','zhǐ shì yī hé pǔ tōng yuè bǐng， yì diǎn xīn yì， nǐ bù yòng gēn wǒ kè qì。','Chỉ là một hộp bánh bình thường thôi mà, chút tấm lòng thôi, cậu đừng khách sáo với tớ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_03','V909','阮明',3,'那我收下这份心意，下周我把家里寄来的越南咖啡回送给你。','nà wǒ shōu xià zhè fèn xīn yì， xià zhōu wǒ bǎ jiā lǐ jì lái de yuè nán kā fēi huí sòng gěi nǐ。','Vậy tớ xin nhận tấm lòng này, tuần sau tớ gửi lại cậu cà phê Việt Nam nhà tớ gửi sang nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_04','V909','苏雯',4,'不用专门回礼，大家朋友之间不用计较这么多。','bù yòng zhuān mén huí lǐ， dà jiā péng yǒu zhī jiān bù yòng jì jiào zhè me duō。','Không cần đáp lễ đâu, bạn bè với nhau tính toán chi li làm gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_05','V909','阮明',5,'礼尚往来是我们两国都有的习惯，一定要收下我的伴手礼。','lǐ shàng wǎng lái shì wǒ men liǎng guó dōu yǒu de xí guàn， yí dìng yào shōu xià wǒ de bàn shǒu lǐ。','Có đi có lại là phong tục cả hai nước mình đều có, cậu nhất định phải nhận quà của tớ đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_06','V909','苏雯',6,'行，那我收下咖啡，下次过节我们简单小礼物互相分享。','xíng， nà wǒ shōu xià kā fēi， xià cì guò jié wǒ men jiǎn dān xiǎo lǐ wù hù xiāng fēn xiǎng。','Được rồi, vậy tớ nhận cà phê, lần sau đến dịp lễ mình đơn giản tặng nhau món quà nhỏ thôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L909_07','V909','阮明',7,'好，之后节日互相送平价小特产，不用贵重礼品。','hǎo， zhī hòu jié rì hù xiāng sòng píng jià xiǎo tè chǎn， bù yòng guì zhòng lǐ pǐn。','Ừ, sau này lễ tết mình tặng nhau đặc sản giá bình dân thôi, không cần quà đắt tiền.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT910','SXH2','主动请客吃饭，拒绝朋友抢单，解释自己提前规划买单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V910','SIT910','P1','twist','tuy_y',NULL,'朋友之间答谢请客十分常见，对方抢单时会说明请客缘由，约定下次轮流做东，平衡人情往来。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_01','V910','阮明',1,'今天是我请你吃饭，别跟我抢买单，我早就计划好了。','jīn tiān shì wǒ qǐng nǐ chī fàn， bié gēn wǒ qiǎng mǎi dān， wǒ zǎo jiù jì huà hǎo le。','Hôm nay tớ mời cậu ăn cơm, đừng giành trả tiền với tớ, tớ tính trước rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_02','V910','苏雯',2,'不行，每次都是你请客，这次必须我来付钱。','bù xíng， měi cì dōu shì nǐ qǐng kè， zhè cì bì xū wǒ lái fù qián。','Không được, lần nào cũng là cậu mời, lần này nhất định để tớ trả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_03','V910','阮明',3,'上次你帮我整理一整本汉语笔记，这次就当答谢你的帮忙嘛。','shàng cì nǐ bāng wǒ zhěng lǐ yī zhěng běn hàn yǔ bǐ jì， zhè cì jiù dāng dá xiè nǐ de bāng máng ma。','Lần trước cậu giúp tớ chép cả một cuốn vở tiếng Trung, lần này coi như tớ cảm ơn cậu vậy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_04','V910','苏雯',4,'只是小事而已，不用专门请客花这么多钱。','zhǐ shì xiǎo shì ér yǐ， bù yòng zhuān mén qǐng kè huā zhè me duō qián。','Chuyện nhỏ xíu thôi mà, không cần mời hẳn tốn kém vậy đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_05','V910','阮明',5,'心意一定要收下，下次换你请客，我们轮流做东。','xīn yì yí dìng yào shōu xià， xià cì huàn nǐ qǐng kè， wǒ men lún liú zuò dōng。','Tấm lòng này cậu phải nhận, lần sau đến lượt cậu mời, mình thay phiên nhau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_06','V910','苏雯',6,'那好吧，下次吃饭不许再跟我抢账单。','nà hǎo ba， xià cì chī fàn bù xǔ zài gēn wǒ qiǎng zhàng dān。','Thôi được rồi, lần sau ăn cơm không được giành trả tiền với tớ nữa đâu đấy.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L910_07','V910','阮明',7,'没问题，下次聚餐全部由你买单。','méi wèn tí， xià cì jù cān quán bù yóu nǐ mǎi dān。','Không thành vấn đề, lần sau ăn uống để cậu bao trọn hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT911','SXH2','多人外出喝奶茶，提前说好各自付款，避免互相垫付混淆',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V911','SIT911','P1','suon_se','tuy_y',NULL,'小额饮品、小吃分开自行付款，是年轻人简化人情、避免垫付纠纷的通用社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_01','V911','阮明',1,'我们去奶茶店，大家各自扫码点单自己付款，免得之后算不清垫付。','wǒ men qù nǎi chá diàn， dà jiā gè zì sǎo mǎ diǎn dān zì jǐ fù kuǎn， miǎn de zhī hòu suàn bù qīng diàn fù。','Mình vào quán trà sữa, ai nấy tự quét mã gọi món và tự trả tiền, khỏi sau này tính không ra ai ứng tiền cho ai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_02','V911','小林',2,'有时候有人手机没电，临时垫付之后很容易忘记转账。','yǒu shí hòu yǒu rén shǒu jī méi diàn， lín shí diàn fù zhī hòu hěn róng yì wàng jì zhuǎn zhàng。','Có lúc điện thoại hết pin, ứng tiền trước rồi lại dễ quên chuyển khoản lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_03','V911','阮明',3,'分开付款最省事，不用事后挨个核对转账记录。','fēn kāi fù kuǎn zuì shěng shì， bù yòng shì hòu āi gè hé duì zhuǎn zhàng jì lù。','Trả riêng là tiện nhất, khỏi phải đối chiếu từng cái lịch sử chuyển khoản sau này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_04','V911','苏雯',4,'行，到店每个人自己下单，不用统一一个人买单。','xíng， dào diàn měi gè rén zì jǐ xià dān， bù yòng tǒng yī yí gè rén mǎi dān。','Được, đến quán ai nấy tự gọi món, không cần dồn cho một người trả hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_05','V911','阮明',5,'想喝什么直接点，不用顾虑饮品价格互相迁就。','xiǎng hē shén me zhí jiē diǎn， bù yòng gù lǜ yǐn pǐn jià gé hù xiāng qiān jiù。','Thích uống gì thì cứ gọi thoải mái, khỏi phải e ngại giá đồ uống rồi nhường nhịn nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_06','V911','小林',6,'这个办法省心，避免一堆转账记录分不清谁欠谁。','zhè ge bàn fǎ shěng xīn， bì miǎn yī duī zhuǎn zhàng jì lù fēn bù qīng shuí qiàn shuí。','Cách này nhàn thật, khỏi phải rối tung lên với đống chuyển khoản không biết ai nợ ai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L911_07','V911','阮明',7,'那我们现在去奶茶店各自下单。','nà wǒ men xiàn zài qù nǎi chá diàn gè zì xià dān。','Vậy giờ mình đi quán trà sữa, ai nấy tự gọi món nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT912','SXH2','朋友生病住院，邀约同学一起买水果前去探望慰问',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V912','SIT912','P1','suon_se','ban_chinh_thuc',NULL,'国内探望病人有送礼禁忌，梨谐音"离"不宜赠送；多人结伴探望、控制时长，不打扰病人休养。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_01','V912','阮明',1,'听说小杨发烧住院，我们约几个朋友买水果去医院看望他吧？','tīng shuō xiǎo yáng fā shāo zhù yuàn， wǒ men yuē jǐ gè péng yǒu mǎi shuǐ guǒ qù yī yuàn kàn wàng tā ba？','Nghe nói Tiểu Dương bị sốt phải nhập viện, hay là mình rủ vài bạn mua ít trái cây vào thăm cậu ấy nhé?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_02','V912','小林',2,'可以，医院适合送苹果、橙子这类温和水果，不要送梨。','kě yǐ， yī yuàn shì hé sòng píng guǒ、 chéng zi zhè lèi wēn hé shuǐ guǒ， bú yào sòng lí。','Được đó, vào viện thì hợp mang táo, cam kiểu trái cây lành tính, đừng mang lê nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_03','V912','阮明',3,'梨在中文谐音不吉利，探望病人确实不适合携带对吧？','lí zài zhōng wén xié yīn bù jí lì， tàn wàng bìng rén què shí bú shì hé xié dài duì ba？','Lê phát âm tiếng Trung nghe không may mắn, đi thăm bệnh đúng là không hợp mang phải không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_04','V912','小林',4,'没错，我们四个人凑钱买一箱鲜果，统一分摊费用。','méi cuò， wǒ men sì gè rén còu qián mǎi yī xiāng xiān guǒ， tǒng yī fēn tān fèi yòng。','Đúng vậy, bốn đứa mình góp tiền mua một thùng trái cây tươi, chia đều chi phí ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_05','V912','阮明',5,'下午没课，三点左右在医院楼下集合一起上楼探望。','xià wǔ méi kè， sān diǎn zuǒ yòu zài yī yuàn lóu xià jí hé yī qǐ shàng lóu tàn wàng。','Chiều nay không có tiết, khoảng ba giờ mình tập trung dưới sảnh bệnh viện rồi cùng lên thăm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_06','V912','小林',6,'探望时间控制半小时，不耽误病人休息恢复。','tàn wàng shí jiān kòng zhì bàn xiǎo shí， bù dān wù bìng rén xiū xī huī fù。','Thời gian thăm nên gói gọn trong nửa tiếng thôi, để bệnh nhân còn nghỉ ngơi hồi phục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L912_07','V912','阮明',7,'我现在联系其他同学，敲定下午探望时间。','wǒ xiàn zài lián xì qí tā tóng xué， qiāo dìng xià wǔ tàn wàng shí jiān。','Giờ tớ liên hệ mấy bạn khác luôn, chốt giờ thăm buổi chiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT913','SXH2','节日邀请中国朋友来宿舍，亲手做越南特色饭菜招待',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V913','SIT913','P1','twist','tuy_y',NULL,'邀请好友到宿舍亲手做饭招待，代表十分重视这段友谊，是很真诚的社交待客方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_01','V913','阮明',1,'中秋宿舍不熄灯，你来我宿舍，我亲手做越南米粉招待你。','zhōng qiū sù shè bù xī dēng， nǐ lái wǒ sù shè， wǒ qīn shǒu zuò yuè nán mǐ fěn zhāo dài nǐ。','Trung thu ký túc xá không tắt đèn, cậu qua phòng tớ đi, tớ tự tay nấu bún gạo Việt Nam đãi cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_02','V913','苏雯',2,'太麻烦你了，买菜、做饭收拾要花很长时间。','tài má fán nǐ le， mǎi cài、 zuò fàn shōu shí yào huā hěn zhǎng shí jiān。','Phiền cậu quá đi, đi chợ, nấu ăn rồi dọn dẹp chắc mất nhiều thời gian lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_03','V913','阮明',3,'食材我已经提前网购备好，只需要简单蒸煮，不会很费力嘛。','shí cái wǒ yǐ jīng tí qián wǎng gòu bèi hǎo， zhǐ xū yào jiǎn dān zhēng zhǔ， bú huì hěn fèi lì ma。','Nguyên liệu tớ đặt online chuẩn bị sẵn hết rồi, chỉ cần hấp nấu qua loa thôi, không mất công lắm đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_04','V913','苏雯',4,'我带一盒月饼过去搭配晚餐，咱们两国小吃一起品尝。','wǒ dài yī hé yuè bǐng guò qù dā pèi wǎn cān， zán men liǎng guó xiǎo chī yì qǐ pǐn cháng。','Vậy tớ mang một hộp bánh Trung thu qua ăn kèm bữa tối, hai đứa mình cùng thưởng thức món ăn của hai nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_05','V913','阮明',5,'宿舍小电锅功率有限，菜品种类不多，你别嫌弃简单。','sù shè xiǎo diàn guō gōng lǜ yǒu xiàn， cài pǐn zhǒng lèi bù duō， nǐ bié xián qì jiǎn dān。','Nồi điện mini ở ký túc xá công suất có hạn, món ăn không nhiều đâu, cậu đừng chê đơn giản nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_06','V913','苏雯',6,'亲手做的饭菜比外面餐厅更有心意，我很期待。','qīn shǒu zuò de fàn cài bǐ wài miàn cān tīng gèng yǒu xīn yì， wǒ hěn qī dài。','Đồ ăn tự tay làm còn có tâm hơn nhà hàng bên ngoài nhiều, tớ mong lắm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L913_07','V913','阮明',7,'那晚上七点来宿舍，我们一起过节聊天。','nà wǎn shàng qī diǎn lái sù shè， wǒ men yì qǐ guò jié liáo tiān。','Vậy bảy giờ tối cậu qua phòng tớ nhé, mình cùng đón lễ trò chuyện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT914','SXH2','收到朋友贵重礼物，担心人情过重，和对方沟通下次减少花销',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V914','SIT914','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友交往更推崇平价走心小礼物，贵重礼品容易让对方产生人情压力，双方会提前约定简化送礼开销。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_01','V914','阮明',1,'这条围巾价格太高，贵重礼物我收下心里很过意不去。','zhè tiáo wéi jīn jià gé tài gāo， guì zhòng lǐ wù wǒ shōu xià xīn lǐ hěn guò yì bù qù。','Chiếc khăn quàng này giá cao quá, món quà quý giá thế này tớ nhận mà trong lòng thấy áy náy quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_02','V914','苏雯',2,'只是一份生日礼物，不用放在心上。','zhǐ shì yī fèn shēng rì lǐ wù， bù yòng fàng zài xīn shàng。','Chỉ là quà sinh nhật thôi mà, cậu đừng để bụng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_03','V914','阮明',3,'普通平价小特产就足够，这么贵重的礼物让我不知道怎么回礼。','pǔ tōng píng jià xiǎo tè chǎn jiù zú gòu， zhè me guì zhòng de lǐ wù ràng wǒ bù zhī dào zěn me huí lǐ。','Đặc sản bình dân là đủ rồi, quà quý giá thế này khiến tớ không biết đáp lễ thế nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_04','V914','苏雯',4,'朋友不用刻意计较礼物价值，不用非要等价回赠。','péng yǒu bù yòng kè yì jì jiào lǐ wù jià zhí， bù yòng fēi yào děng jià huí zèng。','Bạn bè không cần tính toán giá trị món quà làm gì, không cần phải đáp lại tương xứng đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_05','V914','阮明',5,'下次过节千万不要买高价礼品，不然我不敢再收你的礼物了。','xià cì guò jié qiān wàn bú yào mǎi gāo jià lǐ pǐn， bù rán wǒ bù gǎn zài shōu nǐ de lǐ wù le。','Lần sau đến dịp lễ tuyệt đối đừng mua quà đắt tiền nữa, không thì tớ không dám nhận quà của cậu nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_06','V914','苏雯',6,'好，之后只送零食、书签这类平价小物件。','hǎo， zhī hòu zhǐ sòng líng shí、 shū qiān zhè lèi píng jià xiǎo wù jiàn。','Được rồi, sau này tớ chỉ tặng đồ ăn vặt, bookmark kiểu vật nhỏ giá bình dân thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L914_07','V914','阮明',7,'这样轻松相处，不用因为人情礼物有心理负担。','zhè yàng qīng sōng xiāng chǔ， bù yòng yīn wèi rén qíng lǐ wù yǒu xīn lǐ fù dān。','Như vậy mới thoải mái, không phải vì quà cáp mà mang gánh nặng tâm lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT915','SXH3','因中外饮食礼仪差异产生小尴尬，主动和朋友解释本国习惯',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V915','SIT915','P1','suon_se','tuy_y',NULL,'中外餐桌礼仪存在大量差异，出现小尴尬主动说明本国习惯，多数中国年轻人会包容理解，不会苛责。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_01','V915','阮明',1,'刚刚吃饭我直接端碗喝汤，是不是和国内餐桌礼仪不一样？','gāng gāng chī fàn wǒ zhí jiē duān wǎn hē tāng， shì bú shì hé guó nèi cān zhuō lǐ yí bù yí yàng？','Vừa nãy ăn cơm tớ bưng bát húp canh trực tiếp, có phải khác với phép tắc bàn ăn ở đây không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_02','V915','苏雯',2,'这边习惯碗放在桌上喝汤，我还以为你不太适应菜品。','zhè biān xí guàn wǎn fàng zài zhuō shàng hē tāng， wǒ hái yǐ wéi nǐ bù tài shì yìng cài pǐn。','Ở đây quen để bát trên bàn húp canh, tớ còn tưởng cậu không hợp món ăn chứ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_03','V915','阮明',3,'越南日常吃饭都会端起碗，是从小养成的饮食习惯，没有失礼的意思。','yuè nán rì cháng chī fàn dōu huì duān qǐ wǎn， shì cóng xiǎo yǎng chéng de yǐn shí xí guàn， méi yǒu shī lǐ de yì si。','Ở Việt Nam ăn cơm hằng ngày đều bưng bát lên, đó là thói quen từ nhỏ, không có ý gì thất lễ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_04','V915','苏雯',4,'原来是两国礼仪差别，完全没关系，我能理解。','yuán lái shì liǎng guó lǐ yí chā bié， wán quán méi guān xì， wǒ néng lǐ jiě。','Hóa ra là khác biệt phép tắc giữa hai nước thôi, không sao cả, tớ hiểu mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_05','V915','阮明',5,'下次聚餐我会注意入乡随俗，兼顾这边餐桌习惯。','xià cì jù cān wǒ huì zhù yì rù xiāng suí sú， jiān gù zhè biān cān zhuō xí guàn。','Lần sau ăn uống chung tớ sẽ chú ý nhập gia tùy tục, để hợp với thói quen bàn ăn ở đây hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_06','V915','苏雯',6,'不用刻意改变自己，两国习俗不同很正常，不用拘谨。','bù yòng kè yì gǎi biàn zì jǐ， liǎng guó xí sú bù tóng hěn zhèng cháng， bù yòng jū jǐn。','Không cần cố ý thay đổi bản thân đâu, phong tục hai nước khác nhau là chuyện bình thường, cậu đừng gò bó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L915_07','V915','阮明',7,'谢谢你包容不同的饮食礼仪，不会让我觉得尴尬。','xiè xiè nǐ bāo róng bù tóng de yǐn shí lǐ yí， bú huì ràng wǒ jué de gān gà。','Cảm ơn cậu đã bao dung với phép tắc ăn uống khác biệt, không làm tớ thấy ngại chút nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT916','SXH3','说话直爽无意间冒犯中国同学，事后主动道歉、说明文化差异',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V916','SIT916','P1','twist','ban_chinh_thuc',NULL,'东南亚部分国家交流风格直白，和国内委婉含蓄的沟通方式有冲突，产生矛盾后主动解释文化差异并道歉，容易化解隔阂。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_01','V916','阮明',1,'昨天聊天我说话太直接，伤到你的感受，我郑重跟你道歉。','zuó tiān liáo tiān wǒ shuō huà tài zhí jiē， shāng dào nǐ de gǎn shòu， wǒ zhèng zhòng gēn nǐ dào qiàn。','Hôm qua nói chuyện tớ ăn nói thẳng quá, làm cậu buồn lòng, tớ xin lỗi cậu một cách nghiêm túc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_02','V916','小林',2,'当时听完心里有点不舒服，知道你不是恶意就没关系。','dāng shí tīng wán xīn lǐ yǒu diǎn bù shū fú， zhī dào nǐ bú shì è yì jiù méi guān xì。','Lúc đó nghe xong tớ cũng hơi khó chịu, nhưng biết cậu không cố ý nên không sao đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_03','V916','阮明',3,'越南日常交流说话更直白，我还没完全适应委婉的中文表达。','yuè nán rì cháng jiāo liú shuō huà gèng zhí bái， wǒ hái méi wán quán shì yìng wěi wǎn de zhōng wén biǎo dá。','Người Việt hằng ngày nói chuyện thẳng thắn hơn, tớ vẫn chưa quen hẳn với cách nói chuyện tế nhị của tiếng Trung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_04','V916','小林',4,'我明白文化差异，之后有不舒服我会直接跟你说。','wǒ míng bái wén huà chā yì， zhī hòu yǒu bù shū fú wǒ huì zhí jiē gēn nǐ shuō。','Tớ hiểu đó là khác biệt văn hóa mà, sau này có gì không thoải mái tớ sẽ nói thẳng với cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_05','V916','阮明',5,'之后我说话多斟酌用词，学着更委婉温和地表达想法。','zhī hòu wǒ shuō huà duō zhēn zhuó yòng cí， xué zhe gèng wěi wǎn wēn hé dì biǎo dá xiǎng fǎ。','Sau này tớ sẽ cân nhắc lời nói kỹ hơn, học cách diễn đạt tế nhị và ôn hòa hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_06','V916','小林',6,'我们互相包容两国说话习惯，不用因为小事隔阂。','wǒ men hù xiāng bāo róng liǎng guó shuō huà xí guàn， bù yòng yīn wèi xiǎo shì gé hé。','Mình bao dung với thói quen nói chuyện của hai nước nhé, đừng vì chuyện nhỏ mà xa cách nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L916_07','V916','阮明',7,'非常感谢你愿意原谅我无心的冒犯。','fēi cháng gǎn xiè nǐ yuàn yì yuán liàng wǒ wú xīn de mào fàn。','Cảm ơn cậu rất nhiều vì đã sẵn lòng tha thứ cho sự vô ý của tớ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT917','SXH3','和中国朋友聊两国节日风俗，互相讲解本土传统习俗',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V917','SIT917','P1','suon_se','tuy_y',NULL,'聊节日、民俗是安全无冲突的跨文化社交话题，很容易拉近留学生与中国同学的距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_01','V917','阮明',1,'越南新年会摆很多鲜花祭祖，你们春节主要有哪些习俗？','yuè nán xīn nián huì bǎi hěn duō xiān huā jì zǔ， nǐ men chūn jié zhǔ yào yǒu nǎ xiē xí sú？','Tết Việt Nam thường bày rất nhiều hoa tươi để cúng tổ tiên, Tết của các cậu chủ yếu có những phong tục gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_02','V917','苏雯',2,'贴春联、包饺子、全家守岁，长辈还给晚辈发红包呢。','tiē chūn lián、 bāo jiǎo zi、 quán jiā shǒu suì， zhǎng bèi huán gěi wǎn bèi fā hóng bāo ne。','Dán câu đối, gói sủi cảo, cả nhà thức đón giao thừa, người lớn còn lì xì cho con cháu nữa đó.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_03','V917','阮明',3,'我们也有压岁钱，只是发放的时间、包装和中国不一样。','wǒ men yě yǒu yā suì qián， zhǐ shì fā fàng de shí jiān、 bāo zhuāng hé zhōng guó bù yí yàng。','Bên tớ cũng có tiền lì xì, chỉ là thời điểm phát, cách gói với bên Trung Quốc không giống nhau thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_04','V917','苏雯',4,'中秋你们也会赏月吃月饼吗，还是有特色本土点心？','zhōng qiū nǐ men yě huì shǎng yuè chī yuè bǐng ma， hái shì yǒu tè sè běn tǔ diǎn xīn？','Trung thu bên cậu có ngắm trăng ăn bánh trung thu không, hay có bánh đặc trưng riêng?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_05','V917','阮明',5,'我们有同类团圆节日，点心是糯米团子，风味完全不同。','wǒ men yǒu tóng lèi tuán yuán jié rì， diǎn xīn shì nuò mǐ tuán zi， fēng wèi wán quán bù tóng。','Bên tớ cũng có ngày đoàn viên tương tự, nhưng bánh là bánh trôi nếp, hương vị hoàn toàn khác luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_06','V917','苏雯',6,'有空交换各自节日照片，直观看看两国节日场景。','yǒu kòng jiāo huàn gè zì jié rì zhào piān， zhí guān kàn kàn liǎng guó jié rì chǎng jǐng。','Lúc nào rảnh trao đổi ảnh chụp ngày Tết của hai bên nhé, để xem trực quan không khí lễ Tết mỗi nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L917_07','V917','阮明',7,'好，多交流民俗，能更了解彼此国家文化。','hǎo， duō jiāo liú mín sú， néng gèng liǎo jiě bǐ cǐ guó jiā wén huà。','Ừ, trao đổi phong tục nhiều thì mới hiểu văn hóa của nhau hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT918','SXH3','不清楚国内送礼禁忌，请教同学哪些礼物不适合送给长辈朋友',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V918','SIT918','P1','suon_se','ban_chinh_thuc',NULL,'中文大量谐音送礼禁忌，钟表（送终）、梨（离）、伞（散）均为送礼避讳物品，留学生提前询问可避免失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_01','V918','阮明',1,'我想给中国长辈准备礼物，想问问有什么物品不能赠送？','wǒ xiǎng gěi zhōng guó zhǎng bèi zhǔn bèi lǐ wù， xiǎng wèn wèn yǒu shén me wù pǐn bù néng zèng sòng？','Em muốn chuẩn bị quà cho người lớn tuổi bên Trung Quốc, không biết có món gì không nên tặng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_02','V918','苏雯',2,'钟表、梨、雨伞这几类谐音不吉利，尽量避开哦。','zhōng biǎo、 lí、 yǔ sǎn zhè jǐ lèi xié yīn bù jí lì， jǐn liàng bì kāi ó。','Đồng hồ, lê, ô dù mấy thứ này đọc âm gần giống từ xui xẻo, nên tránh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_03','V918','阮明',3,'送鲜花有没有讲究，白色、黄色花束适合探望长辈吗？','sòng xiān huā yǒu méi yǒu jiǎng jiū， bái sè、 huáng sè huā shù shì hé tàn wàng zhǎng bèi ma？','Tặng hoa tươi thì có kiêng kỵ gì không, bó hoa trắng, vàng có hợp để thăm người lớn tuổi không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_04','V918','苏雯',4,'白黄鲜花多用于丧葬，看望长辈选红色、粉色鲜花更合适。','bái huáng xiān huā duō yòng yú sāng zàng， kàn wàng zhǎng bèi xuǎn hóng sè、 fěn sè xiān huā gèng hé shì。','Hoa trắng, hoa vàng thường dùng trong tang lễ, thăm người lớn tuổi thì chọn hoa đỏ, hoa hồng sẽ hợp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_05','V918','阮明',5,'刀具也不能作为礼品赠送，代表分割分离的寓意对吧？','dāo jù yě bù néng zuò wéi lǐ pǐn zèng sòng， dài biǎo fēn gē fēn lí de yù yì duì ba？','Dao kéo cũng không nên dùng làm quà tặng đúng không, vì mang ý nghĩa cắt đứt, chia lìa phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_06','V918','苏雯',6,'没错，刀具寓意不好，食品、茶叶、丝巾是稳妥选择。','méi cuò， dāo jù yù yì bù hǎo， shí pǐn、 chá yè、 sī jīn shì wěn tuǒ xuǎn zé。','Đúng vậy, dao kéo mang ý nghĩa không hay, thực phẩm, trà, khăn lụa là lựa chọn an toàn hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L918_07','V918','阮明',7,'我记下所有禁忌，挑选稳妥礼品送给长辈。','wǒ jì xià suǒ yǒu jìn jì， tiāo xuǎn wěn tuǒ lǐ pǐn sòng gěi zhǎng bèi。','Em ghi nhớ hết những điều kiêng kỵ rồi, sẽ chọn quà an toàn để tặng người lớn tuổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT919','SXH3','朋友调侃本国文化，温和表达自己的看法，避免争执',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V919','SIT919','P1','that_bai_nhe','tuy_y',NULL,'国内年轻人偶尔会随口开玩笑，但涉及他国文化、风俗时需把握分寸，温和表达不适能有效避免社交矛盾升级。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_01','V919','阮明',1,'你刚刚调侃越南饮食的话，听着我心里有点不舒服。','nǐ gāng gāng tiáo kǎn yuè nán yǐn shí de huà， tīng zhe wǒ xīn lǐ yǒu diǎn bù shū fú。','Câu cậu vừa trêu về ẩm thực Việt Nam ấy, nghe xong tớ thấy hơi khó chịu trong lòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_02','V919','小林',2,'我只是随口开玩笑，没有贬低你国家的意思。','wǒ zhǐ shì suí kǒu kāi wán xiào， méi yǒu biǎn dī nǐ guó jiā de yì si。','Tớ chỉ tiện miệng đùa thôi, không có ý coi thường nước cậu đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_03','V919','阮明',3,'每个国家饮食文化都值得尊重，玩笑最好不要拿本国特色调侃嘛。','měi gè guó jiā yǐn shí wén huà dōu zhí de zūn zhòng， wán xiào zuì hǎo bù yào ná běn guó tè sè diào kǎn ma。','Văn hóa ẩm thực nước nào cũng đáng được tôn trọng, đùa thì tốt nhất đừng đem đặc trưng của nước người ta ra chọc ghẹo chứ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_04','V919','小林',4,'我不清楚你会在意这个，之后我会注意说话分寸。','wǒ bù qīng chǔ nǐ huì zài yì zhè ge， zhī hòu wǒ huì zhù yì shuō huà fēn cùn。','Tớ không biết là cậu để bụng chuyện này, sau này tớ sẽ chú ý lời ăn tiếng nói hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_05','V919','阮明',5,'我们可以客观对比两国美食，但不要用调侃、取笑的语气。','wǒ men kě yǐ kè guān duì bǐ liǎng guó měi shí， dàn bú yào yòng tiáo kǎn、 qǔ xiào de yǔ qì。','Tụi mình có thể khách quan so sánh ẩm thực hai nước, nhưng đừng dùng giọng điệu châm chọc, giễu cợt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_06','V919','小林',6,'我记住了，以后聊各国文化都会注意措辞。','wǒ jì zhù le， yǐ hòu liáo gè guó wén huà dōu huì zhù yì cuò cí。','Tớ nhớ rồi, sau này nói chuyện văn hóa các nước tớ sẽ chú ý cách dùng từ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L919_07','V919','阮明',7,'谢谢你理解我的感受，我们继续友好聊天。','xiè xiè nǐ lǐ jiě wǒ de gǎn shòu， wǒ men jì xù yǒu hǎo liáo tiān。','Cảm ơn cậu đã hiểu cho cảm giác của tớ, mình tiếp tục nói chuyện vui vẻ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT920','SXH3','线上聊天用词误会，线下见面澄清、化解线上尴尬',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V920','SIT920','P1','twist','ban_chinh_thuc',NULL,'纯文字线上聊天缺少语气表情，极易产生误会，国内朋友遇到分歧倾向线下当面澄清，高效化解尴尬。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_01','V920','阮明',1,'昨天线上聊天那句话我用词有误，让你误会我的意思了。','zuó tiān xiàn shàng liáo tiān nà jù huà wǒ yòng cí yǒu wù， ràng nǐ wù huì wǒ de yì si le。','Hôm qua nhắn tin online câu đó em dùng từ chưa đúng, khiến chị hiểu lầm ý em rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_02','V920','苏雯',2,'文字看不到语气，我当时还以为你有点生气。','wén zì kàn bú dào yǔ qì， wǒ dāng shí hái yǐ wéi nǐ yǒu diǎn shēng qì。','Nhắn chữ không thấy được giọng điệu, lúc đó chị còn tưởng em hơi giận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_03','V920','阮明',3,'线上打字缺少表情，很容易曲解情绪，我今天当面跟你解释清楚。','xiàn shàng dǎ zì quē shǎo biǎo qíng， hěn róng yì qū jiě qíng xù， wǒ jīn tiān dāng miàn gēn nǐ jiě shì qīng chǔ。','Nhắn tin online thiếu biểu cảm nên rất dễ hiểu sai cảm xúc, hôm nay em gặp trực tiếp giải thích rõ với chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_04','V920','苏雯',4,'线下聊开就没事了，之后重要事情尽量语音沟通。','xiàn xià liáo kāi jiù méi shì le， zhī hòu zhòng yào shì qíng jǐn liàng yǔ yīn gōu tōng。','Nói chuyện trực tiếp thế này là ổn rồi, sau này việc quan trọng nên cố gắng gọi điện trao đổi bằng giọng nói.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_05','V920','阮明',5,'文字容易产生误会，之后复杂想法直接语音或者见面聊。','wén zì róng yì chǎn shēng wù huì， zhī hòu fù zá xiǎng fǎ zhí jiē yǔ yīn huò zhě jiàn miàn liáo。','Nhắn chữ dễ gây hiểu lầm, sau này ý nào phức tạp thì em sẽ gọi điện hoặc gặp trực tiếp nói luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_06','V920','苏雯',6,'没问题，线上简单小事文字，重要话题线下沟通。','méi wèn tí， xiàn shàng jiǎn dān xiǎo shì wén zì， zhòng yào huà tí xiàn xià gōu tōng。','Không sao, việc nhỏ đơn giản thì nhắn tin, chuyện quan trọng thì gặp trực tiếp trao đổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L920_07','V920','阮明',7,'太好了，误会说开我们不会有隔阂。','tài hǎo le， wù huì shuō kāi wǒ men bú huì yǒu gé hé。','Tốt quá, hiểu lầm nói rõ ra rồi thì mình sẽ không có khoảng cách nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT921','SXH4','留学生微信群发起线下小型茶话会，统计参与人数、地点',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V921','SIT921','P1','suon_se','tuy_y',NULL,'留学生线上社群自发组织线下小型聚会十分普遍，饮品、零食自带或AA分摊，场地提前预留。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_01','V921','阮明',1,'本周六下午两点校内咖啡馆举办留学生茶话会，有意向的群里回复1。','běn zhōu liù xià wǔ liǎng diǎn xiào nèi kā fēi guǎn jǔ bàn liú xué shēng chá huà huì， yǒu yì xiàng de qún lǐ huí fù 1。','Chiều thứ Bảy tuần này lúc 2 giờ ở quán cà phê trong trường có buổi trà đàm cho lưu học sinh, ai muốn tham gia thì trả lời 1 trong nhóm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_02','V921','群友A',2,'咖啡馆座位有限，最多容纳十五个人，人数满了就截止报名吗？','kā fēi guǎn zuò wèi yǒu xiàn， zuì duō róng nà shí wǔ gè rén， rén shù mǎn le jiù jié zhǐ bào míng ma？','Quán cà phê chỗ ngồi có hạn, tối đa chứa được mười lăm người, đủ số là chốt sổ đăng ký luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_03','V921','阮明',3,'没错，先回复先预留位置，到场饮品全部AA自行点单。','méi cuò， xiān huí fù xiān yù liú wèi zhì， dào chǎng yǐn pǐn quán bù AA zì xíng diǎn dān。','Đúng rồi, ai trả lời trước thì giữ chỗ trước, đến nơi đồ uống thì mọi người tự gọi tự trả nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_04','V921','群友B',4,'会分享各国零食吗，我可以带越南特色糖果过去。','huì fēn xiǎng gè guó líng shí ma， wǒ kě yǐ dài yuè nán tè sè táng guǒ guò qù。','Có chia sẻ đồ ăn vặt các nước không, tớ có thể mang kẹo đặc sản Việt Nam qua.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_05','V921','阮明',5,'欢迎大家自带本国小零食交换品尝，丰富茶话会内容。','huān yíng dà jiā zì dài běn guó xiǎo líng shí jiāo huàn pǐn cháng， fēng fù chá huà huì nèi róng。','Chào đón mọi người mang đồ ăn vặt nước mình đến trao đổi nếm thử, cho buổi trà đàm thêm phong phú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_06','V921','阮明',6,'我傍晚统计最终人数，提前跟咖啡馆预留区域。','wǒ bàng wǎn tǒng jì zuì zhōng rén shù， tí qián gēn kā fēi guǎn yù liú qū yù。','Chiều tối tớ sẽ tổng hợp số người cuối cùng, rồi báo trước với quán cà phê để giữ chỗ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L921_07','V921','群友C',7,'我报名参加，周六准时到场。','wǒ bào míng cān jiā， zhōu liù zhǔn shí dào chǎng。','Tớ đăng ký tham gia nè, thứ Bảy tớ đến đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT922','SXH4','和新朋友初次线下见面，挑选公共场所、确认往返交通',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V922','SIT922','P1','twist','ban_chinh_thuc',NULL,'初次线下见面优先校园周边公共场所，不单独前往偏僻地点，分别后互相报平安是国内年轻人通用社交安全习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_01','V922','阮明',1,'我们第一次线下见面，选学校正门连锁奶茶店可以吗？','wǒ men dì yī cì xiàn xià jiàn miàn， xuǎn xué xiào zhèng mén lián suǒ nǎi chá diàn kě yǐ ma？','Lần đầu tụi mình gặp mặt trực tiếp, chọn quán trà sữa chuỗi ngay cổng chính trường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_02','V922','陈雨',2,'公共场所很安全，就是我下午有课，只能停留一小时。','gōng gòng chǎng suǒ hěn ān quán， jiù shì wǒ xià wǔ yǒu kè， zhǐ néng tíng liú yī xiǎo shí。','Chỗ công cộng thì rất an toàn, chỉ là chiều em có tiết học, chỉ ở lại được một tiếng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_03','V922','阮明',3,'一小时足够简单聊天，结束我可以送你回教学楼。','yī xiǎo shí zú gòu jiǎn dān liáo tiān， jié shù wǒ kě yǐ sòng nǐ huí jiào xué lóu。','Một tiếng cũng đủ để nói chuyện đơn giản rồi, xong anh có thể đưa em về tòa nhà học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_04','V922','陈雨',4,'不用特意送我，校门口公交直达教学楼，交通很方便。','bù yòng tè yì sòng wǒ， xiào mén kǒu gōng jiāo zhí dá jiào xué lóu， jiāo tōng hěn fāng biàn。','Không cần anh đưa đâu ạ, xe buýt ở cổng trường đi thẳng đến tòa nhà học, rất tiện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_05','V922','阮明',5,'见面结束记得发消息告诉我平安抵达教室哈。','jiàn miàn jié shù jì de fā xiāo xī gào sù wǒ píng ān dǐ dá jiào shì hā。','Gặp xong nhớ nhắn tin báo anh biết là em về đến lớp an toàn nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_06','V922','陈雨',6,'好，周六下午三点奶茶店门口碰面。','hǎo， zhōu liù xià wǔ sān diǎn nǎi chá diàn mén kǒu pèng miàn。','Vâng, ba giờ chiều thứ Bảy gặp nhau trước cửa quán trà sữa ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L922_07','V922','阮明',7,'准时赴约，初次见面简单聊一聊各自专业。','zhǔn shí fù yuē， chū cì jiàn miàn jiǎn dān liáo yī liáo gè zì zhuān yè。','Đến đúng giờ nhé, lần đầu gặp mặt thì nói chuyện đơn giản về chuyên ngành của mỗi người thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT923','SXH4','朋友频繁发消息打扰自习，委婉告知自己的作息学习时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V923','SIT923','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内学生重视自习、上课时间，会主动和朋友说明固定专注时段，委婉划定社交边界，对方一般都会体谅。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_01','V923','阮明',1,'不好意思，每天下午两点到五点我要专心自习，没法及时回复消息。','bù hǎo yì sī， měi tiān xià wǔ liǎng diǎn dào wǔ diǎn wǒ yào zhuān xīn zì xí， méi fǎ jí shí huí fù xiāo xī。','Xin lỗi cậu, mỗi ngày từ 2 giờ đến 5 giờ chiều tớ cần tập trung tự học, không kịp trả lời tin nhắn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_02','V923','小杨',2,'我以为你随时有空，一有琐事就发消息打扰你了。','wǒ yǐ wéi nǐ suí shí yǒu kòng， yī yǒu suǒ shì jiù fā xiāo xī dǎ rǎo nǐ le。','Tớ cứ tưởng cậu lúc nào cũng rảnh, có việc lặt vặt là nhắn cậu, làm phiền cậu rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_03','V923','阮明',3,'自习时段需要安静专注，其余晚上七点之后我可以随时聊天嘛。','zì xí shí duàn xū yào ān jìng zhuān zhù， qí yú wǎn shàng qī diǎn zhī hòu wǒ kě yǐ suí shí liáo tiān ma。','Khung giờ tự học cần yên tĩnh tập trung, còn lại sau 7 giờ tối là tớ rảnh nói chuyện thoải mái mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_04','V923','小杨',4,'我记住你的作息，非休息时间不会频繁发消息打断你学习。','wǒ jì zhù nǐ de zuò xī， fēi xiū xī shí jiān bú huì pín fán fā xiāo xī dǎ duàn nǐ xué xí。','Tớ nhớ giờ giấc của cậu rồi, ngoài giờ nghỉ tớ sẽ không nhắn tin liên tục làm gián đoạn việc học của cậu nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_05','V923','阮明',5,'急事可以直接打电话，普通闲聊集中晚上再回复你。','jí shì kě yǐ zhí jiē dǎ diàn huà， pǔ tōng xián liáo jí zhōng wǎn shàng zài huí fù nǐ。','Việc gấp thì cứ gọi điện thẳng luôn, còn tán gẫu bình thường thì để tối tớ trả lời tập trung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_06','V923','小杨',6,'没问题，我调整发消息的时间，不耽误你复习功课。','méi wèn tí， wǒ tiáo zhěng fā xiāo xī de shí jiān， bù dān wù nǐ fù xí gōng kè。','Không sao, tớ sẽ điều chỉnh giờ nhắn tin, không làm ảnh hưởng đến việc ôn bài của cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L923_07','V923','阮明',7,'十分感谢理解，我们错开自习时段聊天互不影响。','shí fēn gǎn xiè lǐ jiě， wǒ men cuò kāi zì xí shí duàn liáo tiān hù bù yǐng xiǎng。','Cảm ơn cậu nhiều vì đã thông cảm, mình tránh giờ tự học ra để nói chuyện, không ảnh hưởng lẫn nhau nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT924','SXH4','社交软件添加好友，简单自我介绍、说明结识契机',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V924','SIT924','P1','suon_se','tuy_y',NULL,'社交软件添加新朋友后，第一句主动自我介绍、说明相遇场景，是礼貌破冰的基础社交礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_01','V924','阮明',1,'你好，我是阮明，越南留学生，刚才羽毛球球场跟你搭话的人。','nǐ hǎo， wǒ shì ruǎn míng， yuè nán liú xué shēng， gāng cái yǔ máo qiú qiú chǎng gēn nǐ dā huà de rén。','Chào cậu, tớ là Nguyễn Minh, lưu học sinh Việt Nam, người vừa nãy bắt chuyện với cậu ở sân cầu lông đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_02','V924','小周',2,'你好，刚才打球聊了两句，特意添加好友方便之后约球场。','nǐ hǎo， gāng cái dǎ qiú liáo le liǎng jù， tè yì tiān jiā hǎo yǒu fāng biàn zhī hòu yuē qiú chǎng。','Chào cậu, vừa nãy đánh cầu nói chuyện được vài câu, nên kết bạn luôn cho tiện sau này hẹn sân.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_03','V924','阮明',3,'平时周四下午有空打球，有空可以在微信提前约场地。','píng shí zhōu sì xià wǔ yǒu kòng dǎ qiú， yǒu kòng kě yǐ zài wēi xìn tí qián yuē chǎng dì。','Bình thường chiều thứ Năm tớ rảnh đánh cầu, lúc nào rảnh thì nhắn WeChat hẹn sân trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_04','V924','小周',4,'没问题，我大部分周四没课，随时可以组队。','méi wèn tí， wǒ dà bù fèn zhōu sì méi kè， suí shí kě yǐ zǔ duì。','Không thành vấn đề, phần lớn thứ Năm tớ không có tiết, lúc nào cũng rủ đội được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_05','V924','阮明',5,'我汉语还在练习，有表达不通顺的地方麻烦多包涵。','wǒ hàn yǔ hái zài liàn xí， yǒu biǎo dá bù tōng shùn de dì fāng má fán duō bāo hán。','Tiếng Trung của tớ vẫn còn đang luyện, chỗ nào diễn đạt chưa trôi chảy thì mong cậu thông cảm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_06','V924','小周',6,'互相学习，你也可以教我几句越南日常用语。','hù xiāng xué xí， nǐ yě kě yǐ jiāo wǒ jǐ jù yuè nán rì cháng yòng yǔ。','Học hỏi lẫn nhau mà, cậu cũng có thể dạy tớ vài câu tiếng Việt thông dụng đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L924_07','V924','阮明',7,'之后球场碰面再详细聊天。','zhī hòu qiú chǎng pèng miàn zài xiáng xì liáo tiān。','Vậy hẹn gặp lại ở sân cầu lông rồi nói chuyện chi tiết hơn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT925','SXH4','多人出行计划出现分歧，投票协商统一游玩行程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V925','SIT925','P1','suon_se','tuy_y',NULL,'多人集体出行意见不统一时，普遍采用投票少数服从多数，落选一方配合集体安排，不单独搞分歧行程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_01','V925','阮明',1,'现在有两个游玩方案，爬山或者城市老街逛小店，大家投票选择。','xiàn zài yǒu liǎng gè yóu wán fāng àn， pá shān huò zhě chéng shì lǎo jiē guàng xiǎo diàn， dà jiā tóu piào xuǎn zé。','Giờ có hai phương án đi chơi, leo núi hoặc dạo phố cổ ngắm mấy cửa hàng nhỏ trong thành phố, mọi người bình chọn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_02','V925','苏雯',2,'我倾向老街，爬山体力消耗太大，晚上还有作业要写。','wǒ qīng xiàng lǎo jiē， pá shān tǐ lì xiāo hào tài dà， wǎn shàng hái yǒu zuò yè yào xiě。','Mình nghiêng về phố cổ hơn, leo núi tốn sức quá, tối còn phải làm bài tập nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_03','V925','小林',3,'我想爬山，老街商铺人太多拍照拥挤。','wǒ xiǎng pá shān， lǎo jiē shāng pù rén tài duō pāi zhào yōng jǐ。','Mình muốn leo núi, phố cổ đông người quá chụp ảnh chen chúc lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_04','V925','阮明',4,'我们五个人举手表决，票数多的方案作为本周出行计划。','wǒ men wǔ gè rén jǔ shǒu biǎo jué， piào shù duō de fāng àn zuò wéi běn zhōu chū xíng jì huà。','Năm đứa mình giơ tay biểu quyết nhé, phương án nào nhiều phiếu hơn thì chọn làm lịch đi chơi tuần này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_05','V925','小林',5,'行，少数服从多数，选老街我也配合大家行程。','xíng， shǎo shù fú cóng duō shù， xuǎn lǎo jiē wǒ yě pèi hé dà jiā xíng chéng。','Được, thiểu số phục tùng đa số, chọn phố cổ thì mình cũng theo lịch trình của mọi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_06','V925','阮明',6,'敲定老街路线，提前查公交、小吃店攻略。','qiāo dìng lǎo jiē lù xiàn， tí qián chá gōng jiāo、 xiǎo chī diàn gōng lüè。','Vậy chốt lộ trình phố cổ, tranh thủ tra trước tuyến xe buýt với mấy quán ăn vặt ngon.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L925_07','V925','苏雯',7,'统一行程之后，所有人周末同步出发。','tǒng yī xíng chéng zhī hòu， suǒ yǒu rén zhōu mò tóng bù chū fā。','Chốt lịch trình xong thì cuối tuần tất cả cùng xuất phát nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT926','SXH4','线下聚会结束后，主动发消息平安到家，告知同行朋友',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V926','SIT926','P1','suon_se','tuy_y',NULL,'多人线下活动解散后，互相在群内报平安是通用习惯，确认所有人安全抵达住处，避免同伴失联让人担心。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_01','V926','阮明',1,'我已经平安回到宿舍，大家到家都报一声平安哈。','wǒ yǐ jīng píng ān huí dào sù shè， dà jiā dào jiā dōu bào yī shēng píng ān hā。','Mình về tới ký túc xá an toàn rồi nè, mọi người về tới nơi thì báo một tiếng cho yên tâm nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_02','V926','苏雯',2,'我刚到楼下，马上进宿舍，路上公交很顺畅。','wǒ gāng dào lóu xià， mǎ shàng jìn sù shè， lù shàng gōng jiāo hěn shùn chàng。','Mình vừa tới dưới tòa nhà, sắp vào ký túc xá rồi, đường đi xe buýt suôn sẻ lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_03','V926','小林',3,'我还在步行回宿舍，十分钟左右到，一切顺利。','wǒ hái zài bù xíng huí sù shè， shí fēn zhōng zuǒ yòu dào， yī qiè shùn lì。','Mình vẫn đang đi bộ về ký túc xá, tầm mười phút nữa là tới, mọi thứ ổn cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_04','V926','阮明',4,'今晚聚会很开心，下次有空再约线下活动。','jīn wǎn jù huì hěn kāi xīn， xià cì yǒu kòng zài yuē xiàn xià huó dòng。','Tối nay tụ tập vui thật đấy, lần sau rảnh lại hẹn đi chơi tiếp nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_05','V926','苏雯',5,'好，下周看课表再商量下次聚会时间。','hǎo， xià zhōu kàn kè biǎo zài shāng liáng xià cì jù huì shí jiān。','Ừ, để tuần sau xem lịch học rồi bàn tiếp thời gian tụ tập lần tới.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L926_06','V926','阮明',6,'大家早点休息，晚安。','dà jiā zǎo diǎn xiū xī， wǎn ān。','Mọi người nghỉ sớm đi, chúc ngủ ngon nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT927','SXH5','社团换届竞选，为参选朋友加油，赛后安慰落选社员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V927','SIT927','P1','twist','ban_chinh_thuc',NULL,'社团竞选落选后，身边朋友会主动安慰鼓励，国内社团氛围看重同伴支持，不会因竞选结果疏远关系。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_01','V927','阮明',1,'刚才竞选演讲你发挥特别好，可惜差几票没能当选部长。','gāng cái jìng xuǎn yǎn jiǎng nǐ fā huī tè bié hǎo， kě xī chà jǐ piào méi néng dāng xuǎn bù zhǎng。','Bài phát biểu tranh cử của cậu vừa nãy phát huy rất tốt, tiếc là thiếu vài phiếu nên không trúng cử chủ nhiệm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_02','V927','小杨',2,'准备了很久还是落选，心里有点失落。','zhǔn bèi le hěn jiǔ hái shì luò xuǎn， xīn lǐ yǒu diǎn shī luò。','Chuẩn bị lâu vậy mà vẫn rớt, trong lòng cũng hơi thất vọng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_03','V927','阮明',3,'你的能力所有人都看得到，明年换届还有机会参选嘛。','nǐ de néng lì suǒ yǒu rén dōu kàn dé dào， míng nián huàn jiè hái yǒu jī huì cān xuǎn ma。','Năng lực của cậu ai cũng thấy rõ cả, sang năm bầu lại vẫn còn cơ hội ứng cử mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_04','V927','小杨',4,'下一年学业压力大，不一定有空参与社团管理。','xià yī nián xué yè yā lì dà， bù yí dìng yǒu kòng cān yù shè tuán guǎn lǐ。','Năm sau áp lực học tập nặng lắm, chưa chắc có thời gian tham gia quản lý câu lạc bộ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_05','V927','阮明',5,'就算不当部长，社团活动依旧可以正常参与组织工作。','jiù suàn bù dàng bù zhǎng， shè tuán huó dòng yī jiù kě yǐ zhèng cháng cān yù zǔ zhī gōng zuò。','Dù không làm chủ nhiệm thì cậu vẫn có thể tham gia bình thường vào công việc tổ chức của câu lạc bộ mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_06','V927','小杨',6,'谢谢你过来为我加油，还特意过来安慰我。','xiè xiè nǐ guò lái wèi wǒ jiā yóu， hái tè yì guò lái ān wèi wǒ。','Cảm ơn cậu đã đến cổ vũ cho mình, còn đặc biệt qua an ủi mình nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L927_07','V927','阮明',7,'我们是朋友，开心、失落都可以一起分担。','wǒ men shì péng yǒu， kāi xīn、 shī luò dōu kě yǐ yì qǐ fēn dān。','Chúng ta là bạn bè mà, vui hay buồn đều có thể chia sẻ cùng nhau.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT928','SXH5','新生向高年级学长学姐请教社交、校园生活避坑经验',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V928','SIT928','P1','suon_se','ban_chinh_thuc',NULL,'高校内新生主动向高年级学长学姐请教校园、社交经验是很普遍的行为，学长学姐一般都会耐心分享实用建议。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_01','V928','阮明',1,'学长，我刚入校不太熟悉校园社交，想请教一些避坑小经验。','xué zhǎng， wǒ gāng rù xiào bù tài shú xī xiào yuán shè jiāo， xiǎng qǐng jiào yī xiē bì kēng xiǎo jīng yàn。','Anh ơi, em mới vào trường chưa quen giao tiếp trong khuôn viên, muốn xin anh vài kinh nghiệm tránh sai lầm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_02','V928','学长',2,'社团不用一次性报名五六个，选一两个真正感兴趣的深耕即可。','shè tuán bù yòng yí cì xìng bào míng wǔ liù gè， xuǎn yī liǎng gè zhēn zhèng gǎn xìng qù de shēn gēng jí kě。','Không cần đăng ký một lúc năm sáu câu lạc bộ đâu, chọn một hai cái thực sự thích rồi đầu tư sâu là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_03','V928','阮明',3,'校外社交、兼职有哪些需要格外留意的陷阱？','xiào wài shè jiāo、 jiān zhí yǒu nǎ xiē xū yào gé wài liú yì de xiàn jǐng？','Vậy giao tiếp bên ngoài, làm thêm thì có những cạm bẫy nào cần đặc biệt chú ý ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_04','V928','学长',4,'陌生线下兼职、陌生网友单独见面一定要选公共场所。','mò shēng xiàn xià jiān zhí、 mò shēng wǎng yǒu dān dú jiàn miàn yí dìng yào xuǎn gōng gòng chǎng suǒ。','Việc làm thêm gặp ngoài đời với người lạ hay hẹn gặp bạn quen qua mạng nhất định phải chọn nơi công cộng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_05','V928','阮明',5,'和本国、中国同学相处，有什么容易产生误会的文化细节？','hé běn guó、 zhōng guó tóng xué xiāng chǔ， yǒu shén me róng yì chǎn shēng wù huì de wén huà xì jié？','Khi giao lưu với bạn cùng nước và bạn Trung Quốc, có chi tiết văn hóa nào dễ gây hiểu lầm không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_06','V928','学长',6,'送礼、借钱、作息边界提前沟通清楚，能减少大部分矛盾。','sòng lǐ、 jiè qián、 zuò xī biān jiè tí qián gōu tōng qīng chǔ， néng jiǎn shǎo dà bù fèn máo dùn。','Chuyện tặng quà, mượn tiền, giờ giấc sinh hoạt nên trao đổi rõ trước, sẽ giảm được phần lớn mâu thuẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L928_07','V928','阮明',7,'记下您的建议，避免社交踩坑吃亏。','jì xià nín de jiàn yì， bì miǎn shè jiāo cǎi kēng chī kuī。','Em ghi nhớ lời khuyên của anh rồi, để tránh vấp phải rắc rối trong giao tiếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT929','SXH5','班级集体短途出游，主动分担采购零食、清点人数的小事',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V929','SIT929','P1','suon_se','tuy_y',NULL,'班级集体活动大家主动分担琐碎工作，是体现集体意识、快速拉近同学关系的社交方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_01','V929','阮明',1,'班长，出游采购零食、清点人数的活我可以帮忙分担。','bān zhǎng， chū yóu cǎi gòu líng shí、 qīng diǎn rén shù de huó wǒ kě yǐ bāng máng fēn dān。','Lớp trưởng ơi, việc mua đồ ăn vặt với điểm danh số người cho chuyến đi chơi thì để mình giúp một tay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_02','V929','班长',2,'太好了，全班三十人，清点人数很耗费精力。','tài hǎo le， quán bān sān shí rén， qīng diǎn rén shù hěn hào fèi jīng lì。','Tốt quá, cả lớp ba mươi người, điểm danh cũng tốn sức lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_03','V929','阮明',3,'我统计所有人忌口，采购零食避开辣椒、坚果过敏原。','wǒ tǒng jì suǒ yǒu rén jì kǒu， cǎi gòu líng shí bì kāi là jiāo、 jiān guǒ guò mǐn yuán。','Mình sẽ thống kê xem ai kiêng món gì, mua đồ ăn vặt tránh ớt với các loại hạt dễ gây dị ứng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_04','V929','班长',4,'采购费用全班AA，我把预算清单发到班级群公示。','cǎi gòu fèi yòng quán bān AA， wǒ bǎ yù suàn qīng dān fā dào bān jí qún gōng shì。','Chi phí mua đồ chia đều cả lớp nhé, mình sẽ đăng bảng dự toán lên nhóm lớp công khai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_05','V929','阮明',5,'集合时我站队伍末尾，确保没有人掉队遗漏。','jí hé shí wǒ zhàn duì wǔ mò wěi， què bǎo méi yǒu rén diào duì yí lòu。','Lúc tập trung mình sẽ đứng cuối hàng, đảm bảo không ai bị lạc hay bỏ sót.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_06','V929','班长',6,'有你分担工作，集体出游组织轻松很多。','yǒu nǐ fēn dān gōng zuò， jí tǐ chū yóu zǔ zhī qīng sōng hěn duō。','Có cậu chia sẻ công việc, tổ chức đi chơi tập thể nhẹ nhàng hơn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L929_07','V929','阮明',7,'班级集体活动大家互相搭把手，出行更顺利。','bān jí jí tǐ huó dòng dà jiā hù xiāng dā bǎ shǒu， chū xíng gèng shùn lì。','Hoạt động tập thể của lớp mà mọi người cùng giúp đỡ nhau thì chuyến đi sẽ suôn sẻ hơn nhiều.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT930','SXH5','社团线下团建，协调时间冲突无法到场，提前说明并托人转达祝福',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V930','SIT930','P1','that_bai_nhe','ban_chinh_thuc',NULL,'社团团建无法到场需要提前说明缘由，准备小礼物托人转交表达心意，体现重视社团集体、不失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_01','V930','阮明',1,'学姐，团建当天我有汉语等级考试，没办法到场参与活动。','xué jiě， tuán jiàn dàng tiān wǒ yǒu hàn yǔ děng jí kǎo shì， méi bàn fǎ dào chǎng cān yù huó dòng。','Chị ơi, hôm team building em có kỳ thi năng lực tiếng Trung nên không thể tham gia được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_02','V930','学姐',2,'团建一年只有一次，错过这次集体聚餐有点可惜。','tuán jiàn yī nián zhǐ yǒu yī cì， cuò guò zhè cì jí tǐ jù cān yǒu diǎn kě xī。','Team building một năm chỉ có một lần, bỏ lỡ bữa tiệc tập thể này cũng hơi tiếc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_03','V930','阮明',3,'我提前买好社团小伴手礼，托到场的同学分给大家，转达我的祝福。','wǒ tí qián mǎi hǎo shè tuán xiǎo bàn shǒu lǐ， tuō dào chǎng de tóng xué fēn gěi dà jiā， zhuǎn dá wǒ de zhù fú。','Em đã mua sẵn chút quà nhỏ của câu lạc bộ, nhờ bạn nào có mặt hôm đó chia cho mọi người, gửi lời chúc của em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_04','V930','学姐',4,'心意我们收下，考试优先，学业比团建重要。','xīn yì wǒ men shōu xià， kǎo shì yōu xiān， xué yè bǐ tuán jiàn zhòng yào。','Tấm lòng của em bọn chị nhận rồi, thi cử ưu tiên trước, học hành quan trọng hơn team building mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_05','V930','阮明',5,'下次社团小型聚会我一定到场，补上这次缺席。','xià cì shè tuán xiǎo xíng jù huì wǒ yí dìng dào chǎng， bǔ shàng zhè cì quē xí。','Lần tụ họp nhỏ tiếp theo của câu lạc bộ em nhất định sẽ có mặt, bù lại lần vắng này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_06','V930','学姐',6,'祝你等级考试顺利，不用惦记团建的事。','zhù nǐ děng jí kǎo shì shùn lì， bù yòng diàn jì tuán jiàn de shì。','Chúc em thi năng lực suôn sẻ nhé, đừng bận tâm chuyện team building nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L930_07','V930','阮明',7,'十分抱歉错过集体团建，麻烦学姐代为向大家致歉。','shí fēn bào qiàn cuò guò jí tǐ tuán jiàn， má fán xué jiě dài wéi xiàng dà jiā zhì qiàn。','Em thật sự rất xin lỗi vì lỡ hẹn team building tập thể, phiền chị thay em xin lỗi mọi người ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT931','SXH6','朋友频繁借大额现金，委婉说明自身开销，拒绝频繁借钱',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V931','SIT931','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内朋友之间小额应急可互相周转，频繁大额借钱会明确划定边界委婉拒绝，避免金钱损耗友情。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_01','V931','阮明',1,'你最近频繁借大额生活费，我每月家里汇款固定，结余不多。','nǐ zuì jìn pín fán jiè dà é shēng huó fèi， wǒ měi yuè jiā lǐ huì kuǎn gù dìng， jié yú bù duō。','Dạo này cậu cứ mượn tiền sinh hoạt số lượng lớn hoài, mỗi tháng nhà gửi cho mình cố định, dư ra chẳng bao nhiêu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_02','V931','小杨',2,'我临时手头周转不开，才一次次找你借钱应急。','wǒ lín shí shǒu tóu zhōu zhuǎn bù kāi， cái yī cì cì zhǎo nǐ jiè qián yìng jí。','Mình nhất thời xoay không kịp nên mới phải tìm cậu mượn tạm nhiều lần vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_03','V931','阮明',3,'小额应急可以帮忙，但大额资金我自身学费、教材开销压力大嘛。','xiǎo é yìng jí kě yǐ bāng máng， dàn dà é zī jīn wǒ zì shēn xué fèi、 jiào cái kāi xiāo yā lì dà ma。','Số tiền nhỏ để ứng cấp thì mình giúp được, nhưng khoản lớn thì bản thân mình còn áp lực học phí, tiền sách vở nữa mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_04','V931','小杨',4,'明白你的难处，之后我尽量自己规划开支不再频繁借钱。','míng bái nǐ de nán chǔ， zhī hòu wǒ jǐn liàng zì jǐ guī huà kāi zhī bù zài pín fán jiè qián。','Mình hiểu khó khăn của cậu rồi, sau này mình sẽ cố tự lên kế hoạch chi tiêu, không mượn nhiều nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_05','V931','阮明',5,'如果是紧急看病这种急事我一定尽力帮忙，日常消费没法长期出借。','rú guǒ shì jǐn jí kàn bìng zhè zhǒng jí shì wǒ yí dìng jìn lì bāng máng， rì cháng xiāo fèi méi fǎ cháng qī chū jiè。','Nếu là việc gấp như đi khám bệnh thì mình nhất định sẽ cố hết sức giúp, còn chi tiêu hàng ngày thì mình không thể cho mượn dài hạn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_06','V931','小杨',6,'我理解你的边界，不会再频繁向你借大额钱款。','wǒ lǐ jiě nǐ de biān jiè， bú huì zài pín fán xiàng nǐ jiè dà é qián kuǎn。','Mình hiểu giới hạn của cậu rồi, sẽ không mượn khoản lớn từ cậu thường xuyên nữa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L931_07','V931','阮明',7,'我们维持轻松的朋友关系，不用因为金钱产生隔阂。','wǒ men wéi chí qīng sōng de péng yǒu guān xì， bù yòng yīn wèi jīn qián chǎn shēng gé hé。','Chúng ta cứ giữ tình bạn thoải mái vậy thôi, đừng để chuyện tiền bạc làm sứt mẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT932','SXH6','他人强行推销商品、邀约兼职，礼貌拉开距离明确拒绝',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V932','SIT932','P1','suon_se','ban_chinh_thuc',NULL,'校园内推销、兼职邀约十分常见，礼貌温和但态度明确拒绝，对方不会持续纠缠。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_01','V932','阮明',1,'不好意思，我没有购买护肤品、参与兼职的打算。','bù hǎo yì sī， wǒ méi yǒu gòu mǎi hù fū pǐn、 cān yù jiān zhí de dǎ suàn。','Xin lỗi, em không có ý định mua mỹ phẩm hay tham gia làm thêm gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_02','V932','推销人员',2,'这款产品留学生用很合适，兼职还能赚取生活费。','zhè kuǎn chǎn pǐn liú xué shēng yòng hěn hé shì， jiān zhí hái néng zhuàn qǔ shēng huó fèi。','Sản phẩm này rất hợp với du học sinh, làm thêm còn kiếm thêm tiền sinh hoạt được nữa đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_03','V932','阮明',3,'我课余全部用来复习汉语考试，没有时间做副业兼职嘛。','wǒ kè yú quán bù yòng lái fù xí hàn yǔ kǎo shì， méi yǒu shí jiān zuò fù yè jiān zhí ma。','Em dành hết thời gian ngoài giờ học để ôn thi tiếng Trung, không có thời gian làm thêm việc tay trái đâu ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_04','V932','推销人员',4,'耽误五分钟简单了解一下，不会占用你太久时间。','dān wù wǔ fēn zhōng jiǎn dān liǎo jiě yī xià， bú huì zhàn yòng nǐ tài jiǔ shí jiān。','Chỉ mất năm phút tìm hiểu sơ qua thôi, sẽ không chiếm nhiều thời gian của em đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_05','V932','阮明',5,'实在没有需求，我要赶回图书馆自习，先失陪了。','shí zài méi yǒu xū qiú， wǒ yào gǎn huí tú shū guǎn zì xí， xiān shī péi le。','Em thật sự không có nhu cầu, em phải chạy về thư viện tự học rồi, xin phép em đi trước ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_06','V932','推销人员',6,'好吧，不打扰你学习，有需要再联系我。','hǎo ba， bù dǎ rǎo nǐ xué xí， yǒu xū yào zài lián xì wǒ。','Thôi được, vậy không làm phiền em học nữa, khi nào cần thì liên hệ lại với anh nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L932_07','V932','阮明',7,'感谢介绍，我确实没有相关需求。','gǎn xiè jiè shào， wǒ què shí méi yǒu xiāng guān xū qiú。','Cảm ơn anh đã giới thiệu, nhưng em thực sự không có nhu cầu này ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT933','SXH6','很久没联系的老友，主动发消息分享日常、维系友谊',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V933','SIT933','P1','suon_se','tuy_y',NULL,'国内友情不会因为许久不联络直接变淡，主动分享日常、约定线上聊天是维系远距离友谊常用方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_01','V933','阮明',1,'好久不见，最近刷到你朋友圈，想起之前我们一起打球的日子。','hǎo jiǔ bú jiàn， zuì jìn shuā dào nǐ péng yǒu quān， xiǎng qǐ zhī qián wǒ men yì qǐ dǎ qiú de rì zi。','Lâu rồi không gặp, lúc nãy lướt thấy story cậu, tự nhiên nhớ lại hồi mình hay đi đánh bóng chung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_02','V933','阿凯',2,'确实很久没聊天，你在中国留学生活还适应吗？','què shí hěn jiǔ méi liáo tiān， nǐ zài zhōng guó liú xué shēng huó hái shì yìng ma？','Đúng là lâu lắm rồi không trò chuyện, cuộc sống du học ở Trung Quốc của cậu ổn chứ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_03','V933','阮明',3,'一切顺利，汉语进步不少，拍了很多校园风景照片。','yī qiè shùn lì， hàn yǔ jìn bù bù shǎo， pāi le hěn duō xiào yuán fēng jǐng zhào piān。','Mọi thứ đều suôn sẻ, tiếng Trung tiến bộ kha khá, còn chụp được cả đống ảnh phong cảnh trường nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_04','V933','阿凯',4,'有空周末线上视频，聊聊各自近期的学习生活。','yǒu kòng zhōu mò xiàn shàng shì pín， liáo liáo gè zì jìn qī de xué xí shēng huó。','Rảnh thì cuối tuần mình gọi video online nhé, kể cho nhau nghe chuyện học hành gần đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_05','V933','阮明',5,'这周日晚上七点我有空，准时线上跟你聊天叙旧。','zhè zhōu rì wǎn shàng qī diǎn wǒ yǒu kòng， zhǔn shí xiàn shàng gēn nǐ liáo tiān xù jiù。','Tối chủ nhật này bảy giờ mình rảnh, đúng giờ đó lên online tám chuyện với cậu luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_06','V933','阿凯',6,'好，到时候线上碰面，多聊聊近况。','hǎo， dào shí hòu xiàn shàng pèng miàn， duō liáo liáo jìn kuàng。','Ok, vậy hẹn online gặp nhau, tám nhiều chuyện gần đây nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L933_07','V933','阮明',7,'许久不联系也要偶尔分享日常，别慢慢疏远。','xǔ jiǔ bù lián xì yě yào ǒu ěr fēn xiǎng rì cháng， bié màn màn shū yuǎn。','Lâu không liên lạc thì cũng phải thỉnh thoảng chia sẻ chuyện thường ngày, đừng để xa nhau dần nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT934','SXH6','朋友过度打探家庭、生活费隐私，温和转移话题守住边界',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V934','SIT934','P1','twist','tuy_y',NULL,'国内社交不会过度追问收入、家庭条件等隐私，若对方过度打探，温和转移话题是委婉守住边界的礼貌方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_01','V934','阮明',1,'生活费够用就行，我们换个话题聊聊周末去哪游玩吧。','shēng huó fèi gòu yòng jiù xíng， wǒ men huàn gè huà tí liáo liáo zhōu mò qù nǎ yóu wán ba。','Tiền sinh hoạt đủ xài là được rồi, mình đổi chủ đề đi, bàn xem cuối tuần đi chơi đâu nè.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_02','V934','小周',2,'只是好奇问问，你家里每月给你汇多少越南盾？','zhǐ shì hào qí wèn wèn， nǐ jiā lǐ měi yuè gěi nǐ huì duō shǎo yuè nán dùn？','Tò mò hỏi vậy thôi, mỗi tháng nhà cậu gửi cho cậu bao nhiêu tiền Việt vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_03','V934','阮明',3,'各国家庭收支习惯不一样，不太习惯细说家庭财务情况嘛。','gè guó jiā tíng shōu zhī xí guàn bù yí yàng， bù tài xí guàn xì shuō jiā tíng cái wù qíng kuàng ma。','Thói quen thu chi mỗi gia đình mỗi nước khác nhau, mình cũng không quen kể chi tiết chuyện tiền bạc trong nhà lắm.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_04','V934','小周',4,'抱歉，我不知道这是你的隐私，我之后不会再追问这类问题。','bào qiàn， wǒ bù zhī dào zhè shì nǐ de yǐn sī， wǒ zhī hòu bú huì zài zhuī wèn zhè lèi wèn tí。','Xin lỗi nha, mình không biết đây là chuyện riêng tư của cậu, sau này mình sẽ không hỏi mấy chuyện này nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_05','V934','阮明',5,'没关系，我们聊聊校园文艺晚会的节目更有意思。','méi guān xì， wǒ men liáo liáo xiào yuán wén yì wǎn huì de jié mù gèng yǒu yì si。','Không sao đâu, mình nói chuyện về tiết mục văn nghệ của trường thú vị hơn nè.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_06','V934','小周',6,'好，我们聊晚会，不聊私人家庭收支话题。','hǎo， wǒ men liáo wǎn huì， bù liáo sī rén jiā tíng shōu zhī huà tí。','Ừ, vậy mình bàn chuyện văn nghệ thôi, không nhắc đến chuyện thu chi riêng tư của gia đình nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L934_07','V934','阮明',7,'感谢理解，各自保留一点私人空间相处更舒服。','gǎn xiè lǐ jiě， gè zì bǎo liú yì diǎn sī rén kōng jiān xiāng chǔ gèng shū fú。','Cảm ơn cậu đã hiểu, mỗi người giữ chút không gian riêng thì chơi với nhau thoải mái hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT935','SXH6','毕业前夕和要好的朋友约定，回国后定期线上联络',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V935','SIT935','P1','suon_se','ban_chinh_thuc',NULL,'毕业分离时好友会主动约定长期联络方式，国内年轻人十分看重长久稳定的友谊，不会因异地轻易断联。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_01','V935','阮明',1,'等我毕业回越南，我们也要保持联系，不能慢慢断了往来。','děng wǒ bì yè huí yuè nán， wǒ men yě yào bǎo chí lián xì， bù néng màn màn duàn le wǎng lái。','Đợi tôi tốt nghiệp về Việt Nam rồi, chúng ta vẫn phải giữ liên lạc, không được để quan hệ nhạt dần đâu đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_02','V935','苏雯',2,'放心，每月固定一次线上视频，分享各自工作、生活近况。','fàng xīn， měi yuè gù dìng yī cì xiàn shàng shì pín， fēn xiǎng gè zì gōng zuò、 shēng huó jìn kuàng。','Yên tâm đi, mỗi tháng cố định gọi video một lần, chia sẻ tình hình công việc và cuộc sống của mỗi người.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_03','V935','阮明',3,'节假日互相寄本国小特产，线上聊天弥补不能线下见面的遗憾。','jié jià rì hù xiāng jì běn guó xiǎo tè chǎn， xiàn shàng liáo tiān mí bǔ bù néng xiàn xià jiàn miàn de yí hàn。','Vào các dịp lễ thì gửi cho nhau chút đặc sản quê mình, trò chuyện online cũng bù đắp phần nào cho việc không gặp trực tiếp được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_04','V935','苏雯',4,'不管距离多远，我们的友谊不会因为回国分开变淡。','bù guǎn jù lí duō yuǎn， wǒ men de yǒu yì bú huì yīn wèi huí guó fēn kāi biàn dàn。','Dù khoảng cách có xa đến đâu, tình bạn của chúng ta cũng sẽ không nhạt đi chỉ vì ai đó về nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_05','V935','阮明',5,'回国之后时差一小时，提前约定双方都空闲的视频时段。','huí guó zhī hòu shí chà yī xiǎo shí， tí qián yuē dìng shuāng fāng dōu kòng xián de shì pín shí duàn。','Sau khi về nước thì lệch múi giờ một tiếng, mình hẹn trước khung giờ mà cả hai đều rảnh để gọi video.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_06','V935','苏雯',6,'我记好约定，毕业之后按时线上叙旧。','wǒ jì hǎo yuē dìng， bì yè zhī hòu àn shí xiàn shàng xù jiù。','Tôi sẽ ghi nhớ lời hẹn này, sau khi tốt nghiệp sẽ đúng giờ lên online ôn lại chuyện xưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L935_07','V935','阮明',7,'很幸运在校期间认识你，长久维持这份跨国友谊。','hěn xìng yùn zài xiào qī jiān rèn shí nǐ， cháng jiǔ wéi chí zhè fèn kuà guó yǒu yì。','Thật may mắn khi quen được cậu trong thời gian học ở trường, mong tình bạn xuyên quốc gia này sẽ bền lâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1001','SKC1','深夜高烧腹泻无校医，求助室友陪同去校外急诊',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1001','SIT1001','P1','twist','tuy_y',NULL,'国内多数高校校医仅白天值班，夜间急症只能前往社区24小时医院，室友之间临时垫付医药费是很常见的互助方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_01','V1001','阮明',1,'晓晓，醒醒、快醒醒……我好难受，撑不住了。','xiǎo xiǎo ， xǐng xǐng 、 kuài xǐng xǐng …… wǒ hǎo nán shòu ， chēng bú zhù le 。','Khánh Hiểu, dậy đi, dậy nhanh đi... tớ khó chịu quá, không chịu nổi nữa rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_02','V1001','林晓',2,'怎么了明哥？这都凌晨两点了，你哪里不舒服啊？','zěn me le míng gē ？ zhè dōu líng chén liǎng diǎn le ， nǐ nǎ lǐ bù shū fú a ？','Sao vậy anh Minh? Giờ là hai giờ sáng rồi đấy, anh thấy khó chịu ở đâu vậy?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_03','V1001','阮明',3,'我突然发高烧，还一直拉肚子，浑身软得不行，站都站不稳。','wǒ tū rán fā gāo shāo ， hái yì zhí lā dù zi ， hún shēn ruǎn dé bù xíng ， zhàn dōu zhàn bù wěn 。','Tớ tự nhiên sốt cao, lại còn bị tiêu chảy liên tục, người mềm nhũn cả ra, đứng cũng không vững.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_04','V1001','林晓',4,'我的天，这么严重！校医室早就关门了，晚上没有医生值班，我陪你去校外的24小时急诊吧！','wǒ de tiān ， zhè me yán zhòng ！ xiào yī shì zǎo jiù guān mén le ， wǎn shàng méi yǒu yī shēng zhí bān ， wǒ péi nǐ qù xiào wài de 24 xiǎo shí jí zhěn ba ！','Trời ơi, nặng vậy sao! Phòng y tế trường đóng cửa từ lâu rồi, ban đêm không có bác sĩ trực, để em đưa anh ra phòng cấp cứu 24 giờ ngoài trường nhé!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_05','V1001','阮明',5,'可以吗？可是我身上没多少现金，手机支付也不太方便……','kě yǐ ma ？ kě shì wǒ shēn shàng méi duō shǎo xiàn jīn ， shǒu jī zhī fù yě bù tài fāng biàn ……','Được không em? Nhưng mà tớ không mang nhiều tiền mặt, thanh toán qua điện thoại cũng không tiện lắm...',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_06','V1001','林晓',6,'没事没事，钱的事你别管，我先帮你垫付，你身体要紧，先去看病！','méi shì méi shì ， qián de shì nǐ bié guǎn ， wǒ xiān bāng nǐ diàn fù ， nǐ shēn tǐ yào jǐn ， xiān qù kàn bìng ！','Không sao không sao, chuyện tiền anh đừng lo, em ứng trước cho, sức khỏe quan trọng hơn, mình đi khám trước đã!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_07','V1001','阮明',7,'真的太谢谢你了……我现在站起来就头晕，得麻烦你扶我一下。','zhēn de tài xiè xiè nǐ le …… wǒ xiàn zài zhàn qǐ lái jiù tóu yūn ， dé má fán nǐ fú wǒ yī xià 。','Thật sự cảm ơn em nhiều lắm... giờ tớ đứng dậy là chóng mặt, phiền em đỡ tớ một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_08','V1001','林晓',8,'别客气，赶紧披上厚外套，夜里风特别大，别再加重了，我们马上走。','bié kè qì ， gǎn jǐn pī shàng hòu wài tào ， yè lǐ fēng tè bié dà ， bié zài jiā zhòng le ， wǒ men mǎ shàng zǒu 。','Anh đừng khách sáo, mau khoác thêm áo khoác dày vào, đêm gió to lắm, đừng để bệnh nặng thêm, mình đi ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1002','SKC1','宿舍水管爆裂积水，紧急联系后勤抢修止损',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1002','SIT1002','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍后勤维修分时段报修，突发漏水这类险情可直接拨打应急专线，不用走线上预约流程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_01','V1002','阮明',1,'张师傅！麻烦您快来一下，我是3栋402的学生，我们宿舍出事了！','zhāng shī fù ！ má fán nín kuài lái yī xià ， wǒ shì 3 dòng 402 de xué shēng ， wǒ men sù shè chū shì le ！','Chú Trương ơi! Phiền chú đến gấp giúp cháu, cháu là sinh viên phòng 402 tòa 3, phòng ký túc xá của bọn cháu gặp sự cố rồi ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_02','V1002','张师傅',2,'同学别急，慢慢说，怎么了？是漏水还是断电了？','tóng xué bié jí ， màn màn shuō ， zěn me le ？ shì lòu shuǐ hái shì duàn diàn le ？','Em đừng vội, từ từ nói, chuyện gì vậy? Bị rò nước hay là mất điện?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_03','V1002','阮明',3,'卫生间的水管突然爆了！水一直往外喷，地上全是积水，马上就要漫到书桌和床铺了！','wèi shēng jiān de shuǐ guǎn tū rán bào le ！ shuǐ yì zhí wǎng wài pēn ， dì shàng quán shì jī shuǐ ， mǎ shàng jiù yào màn dào shū zhuō hé chuáng pù le ！','Ống nước trong nhà vệ sinh tự nhiên bị vỡ ạ! Nước cứ phun ra liên tục, sàn nhà ngập hết nước rồi, sắp tràn tới bàn học với giường ngủ luôn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_04','V1002','张师傅',4,'我知道了，你先试着把卫生间总水阀关掉，先止水，别让水一直流。','wǒ zhī dào le ， nǐ xiān shì zhe bǎ wèi shēng jiān zǒng shuǐ fá guān diào ， xiān zhǐ shuǐ ， bié ràng shuǐ yì zhí liú 。','Chú biết rồi, em thử khóa van nước tổng ở nhà vệ sinh lại trước đã, chặn nước lại, đừng để nước chảy mãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_05','V1002','阮明',5,'我试过了师傅！总水阀拧不动，彻底关不上，积水越积越多，再拖地板就要泡坏了！','wǒ shì guò le shī fù ！ zǒng shuǐ fá níng bù dòng ， chè dǐ guān bù shàng ， jī shuǐ yuè jī yuè duō ， zài tuō dì bǎn jiù yào pào huài le ！','Cháu thử rồi chú ơi! Van nước tổng vặn không được, không thể khóa lại được, nước cứ dâng lên mãi, để lâu nữa là sàn nhà ngâm nước hỏng mất!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_06','V1002','张师傅',6,'行，我立马带工具上楼，十分钟之内到。你先用拖把、脸盆先舀水，尽量控一下积水。','xíng ， wǒ lì mǎ dài gōng jù shàng lóu ， shí fēn zhōng zhī nèi dào 。 nǐ xiān yòng tuō bǎ 、 liǎn pén xiān yǎo shuǐ ， jǐn liàng kòng yī xià jī shuǐ 。','Được, chú mang dụng cụ lên ngay đây, mười phút nữa là tới. Em dùng cây lau nhà với chậu múc bớt nước ra, cố gắng khống chế lượng nước đọng lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_07','V1002','阮明',7,'好好！我现在马上清理，麻烦您快点过来！','hǎo hǎo ！ wǒ xiàn zài mǎ shàng qīng lǐ ， má fán nín kuài diǎn guò lái ！','Vâng vâng! Cháu dọn ngay bây giờ, phiền chú đến nhanh giúp cháu với ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_08','V1002','张师傅',8,'放心，我已经出发了，到楼下给你打电话。','fàng xīn ， wǒ yǐ jīng chū fā le ， dào lóu xià gěi nǐ dǎ diàn huà 。','Yên tâm đi, chú xuất phát rồi, xuống tới tầng dưới chú gọi điện cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1003','SKC1','就餐食物严重过敏无抗过敏药，同学送医急救',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1003','SIT1003','P1','twist','tuy_y',NULL,'国内医院急诊可先救治后补登记证件，留学生就诊出示居留许可即可登记。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_01','V1003','阮明',1,'小雨……我不对劲，身上全是红疹子，呼吸也有点困难，好像过敏了。','xiǎo yǔ …… wǒ bú duì jìn ， shēn shàng quán shì hóng zhěn zi ， hū xī yě yǒu diǎn kùn nán ， hǎo xiàng guò mǐn le 。','Tiểu Vũ... tớ thấy không ổn, người nổi đầy mẩn đỏ, thở cũng hơi khó, hình như bị dị ứng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_02','V1003','陈雨',2,'啊？怎么突然过敏了？你中午吃什么了？宿舍有没有过敏药先吃一点？','a ？ zěn me tū rán guò mǐn le ？ nǐ zhōng wǔ chī shén me le ？ sù shè yǒu méi yǒu guò mǐn yào xiān chī yì diǎn ？','Hả? Sao tự nhiên bị dị ứng vậy? Trưa nay anh ăn gì thế? Trong phòng có thuốc dị ứng không, uống tạm một ít đi?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_03','V1003','阮明',3,'中午在食堂吃的海鲜小炒……我宿舍没备药，现在喉咙越来越肿，好难受。','zhōng wǔ zài shí táng chī de hǎi xiān xiǎo chǎo …… wǒ sù shè méi bèi yào ， xiàn zài hóu lóng yuè lái yuè zhǒng ， hǎo nán shòu 。','Trưa nay tớ ăn món hải sản xào ở căng tin... phòng tớ không có sẵn thuốc, giờ cổ họng cứ sưng lên, khó chịu quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_04','V1003','陈雨',4,'这绝对不行，不能硬扛！我现在骑车带你去校门口的医院急诊！','zhè jué duì bù xíng ， bù néng yìng káng ！ wǒ xiàn zài qí chē dài nǐ qù xiào mén kǒu de yī yuàn jí zhěn ！','Vậy không được đâu, không thể ráng chịu như vậy! Giờ để em chở anh đi cấp cứu ở bệnh viện gần cổng trường luôn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_05','V1003','阮明',5,'可是我的证件都在宿舍柜子里，没带在身上，看病会不会不方便？','kě shì wǒ de zhèng jiàn dōu zài sù shè guì zi lǐ ， méi dài zài shēn shàng ， kàn bìng huì bú huì bù fāng biàn ？','Nhưng giấy tờ tùy thân của tớ để trong tủ ở phòng, không mang theo người, đi khám như vậy có bất tiện không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_06','V1003','陈雨',6,'先去看病，证件的事不急！我等下跟辅导员报备，回头帮你回宿舍拿。','xiān qù kàn bìng ， zhèng jiàn de shì bù jí ！ wǒ děng xià gēn fǔ dǎo yuán bào bèi ， huí tóu bāng nǐ huí sù shè ná 。','Đi khám trước đã, chuyện giấy tờ không gấp đâu! Lát nữa em báo với thầy cô chủ nhiệm, rồi quay về phòng lấy giúp anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_07','V1003','阮明',7,'太麻烦你了……我现在手脚发麻，有点站不住了。','tài má fán nǐ le …… wǒ xiàn zài shǒu jiǎo fā má ， yǒu diǎn zhàn bú zhù le 。','Phiền em quá... giờ tay chân tớ tê hết cả rồi, hơi đứng không vững nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_08','V1003','陈雨',8,'别说话，靠着我！我们现在立刻去医院！','bié shuō huà ， kào zhe wǒ ！ wǒ men xiàn zài lì kè qù yī yuàn ！','Anh đừng nói nữa, dựa vào em đi! Mình đi bệnh viện ngay bây giờ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1004','SKC1','宿舍大功率电器短路冒烟断电，联系宿管排查隐患',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1004','SIT1004','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍严禁大功率电煮锅、电暖锅等电器，违规使用引发电路故障需自行承担维修损失。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_01','V1004','阮明',1,'李阿姨，不好了！我是5栋206的阮明，我们宿舍插座冒烟，直接跳闸断电了！','lǐ ā yí ， bù hǎo le ！ wǒ shì 5 dòng 206 de ruǎn míng ， wǒ men sù shè chā zuò mào yān ， zhí jiē tiào zhá duàn diàn le ！','Cô Lý ơi, nguy rồi ạ! Cháu là Nguyễn Minh phòng 206 tòa 5, ổ cắm điện phòng cháu bốc khói, rồi nhảy cầu dao mất điện luôn ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_02','V1004','李宿管',2,'冒烟了？你可千万别碰插座线路！有没有泼水或者拿手去摸电线？','mào yān le ？ nǐ kě qiān wàn bié pèng chā zuò xiàn lù ！ yǒu méi yǒu pō shuǐ huò zhě ná shǒu qù mō diàn xiàn ？','Bốc khói à? Em tuyệt đối đừng chạm vào ổ cắm hay dây điện nhé! Có tạt nước vào hay lấy tay sờ vào dây điện không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_03','V1004','阮明',3,'没有没有，我第一时间拔掉了所有电器插头，现在房间完全没电，不敢乱动。','méi yǒu méi yǒu ， wǒ dì yī shí jiān bá diào le suǒ yǒu diàn qì chā tóu ， xiàn zài fáng jiān wán quán méi diàn ， bù gǎn luàn dòng 。','Dạ không ạ, cháu rút hết tất cả phích cắm ngay lập tức, giờ phòng hoàn toàn mất điện, cháu không dám động vào gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_04','V1004','李宿管',4,'我问你，是用什么电器的时候出的事？是不是私用的电煮锅？','wǒ wèn nǐ ， shì yòng shén me diàn qì de shí hòu chū de shì ？ shì bú shì sī yòng de diàn zhǔ guō ？','Cô hỏi em, lúc xảy ra chuyện là đang dùng thiết bị điện gì vậy? Có phải là nồi điện tự ý dùng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_05','V1004','阮明',5,'对，我刚用小电锅煮完汤，一拔插头，插座直接冒黑烟，我当时都吓懵了。','duì ， wǒ gāng yòng xiǎo diàn guō zhǔ wán tāng ， yī bá chā tóu ， chā zuò zhí jiē mào hēi yān ， wǒ dāng shí dōu xià měng le 。','Dạ đúng ạ, cháu vừa dùng nồi điện nhỏ nấu canh xong, vừa rút phích cắm ra là ổ cắm bốc khói đen luôn, lúc đó cháu sợ chết khiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_06','V1004','李宿管',6,'我就猜到是大功率违规电器！幸好只是跳闸冒烟，没起火算万幸。我马上带电工过去排查电路。','wǒ jiù cāi dào shì dà gōng lǜ wéi guī diàn qì ！ xìng hǎo zhǐ shì tiào zhá mào yān ， méi qǐ huǒ suàn wàn xìng 。 wǒ mǎ shàng dài diàn gōng guò qù pái chá diàn lù 。','Cô đoán ngay là thiết bị công suất lớn dùng trái quy định mà! May là chỉ nhảy cầu dao với bốc khói thôi, không cháy là còn may đấy. Cô dẫn thợ điện qua kiểm tra đường dây ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_07','V1004','阮明',7,'我知道错了阿姨，我再也不敢私用电锅了，一定等电工检查完确认安全再用电。','wǒ zhī dào cuò le ā yí ， wǒ zài yě bù gǎn sī yòng diàn guō le ， yí dìng děng diàn gōng jiǎn chá wán què rèn ān quán zài yòng diàn 。','Cháu biết sai rồi ạ cô, cháu không dám tự ý dùng nồi điện nữa đâu, nhất định đợi thợ điện kiểm tra xong xác nhận an toàn mới dùng điện lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_08','V1004','李宿管',8,'你们先全部到走廊待着，别待在宿舍，防止电路残留隐患伤人，暂时也别碰任何插座开关。','nǐ men xiān quán bù dào zǒu láng dài zhe ， bié dài zài sù shè ， fáng zhǐ diàn lù cán liú yǐn huàn shāng rén ， zàn shí yě bié pèng rèn hé chā zuò kāi guān 。','Các em ra hành lang đứng chờ hết đi, đừng ở trong phòng, đề phòng đường điện còn sót lại rủi ro gây thương tích, tạm thời cũng đừng đụng vào bất cứ ổ cắm hay công tắc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1005','SKC1','晾晒衣物坠落楼下险些砸伤路人，下楼道歉处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1005','SIT1005','P1','that_bai_nhe','tuy_y',NULL,'国内居民楼、学生公寓高空坠物属于危险行为，一旦伤人需承担全部赔偿责任，物业会对违规住户通报批评。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_01','V1005','阮明',1,'阿姨！真的非常对不起！刚刚我阳台的衣服掉下来，差点砸到您了！','ā yí ！ zhēn de fēi cháng duì bù qǐ ！ gāng gāng wǒ yáng tái de yī fú diào xià lái ， chà diǎn zá dào nín le ！','Cô ơi! Cháu xin lỗi cô thật sự ạ! Vừa nãy quần áo phơi ở ban công nhà cháu rơi xuống, suýt nữa trúng cô rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_02','V1005','王阿姨',2,'哎哟小伙子，你这衣服突然掉下来，吓我一大跳，还好我躲得快！','āi yō xiǎo huǒ zi ， nǐ zhè yī fú tū rán diào xià lái ， xià wǒ yī dà tiào ， hái hǎo wǒ duǒ dé kuài ！','Ôi chàng trai này, quần áo của cháu tự nhiên rơi xuống làm cô giật cả mình, may mà cô né kịp đấy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_03','V1005','阮明',3,'都怪我没固定好晾衣架，太粗心了，我现在马上把衣服捡起来，真的抱歉。','dōu guài wǒ méi gù dìng hǎo liàng yī jià ， tài cū xīn le ， wǒ xiàn zài mǎ shàng bǎ yī fú jiǎn qǐ lái ， zhēn de bào qiàn 。','Tại cháu không cột chắc giá phơi đồ, sơ suất quá, cháu nhặt đồ lên ngay đây, thật sự xin lỗi cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_04','V1005','王阿姨',4,'你这孩子也太不当心了！楼下人来人往的，万一砸到人，那可不是小事！','nǐ zhè hái zi yě tài bù dàng xīn le ！ lóu xià rén lái rén wǎng de ， wàn yī zá dào rén ， nà kě bú shì xiǎo shì ！','Cháu đúng là bất cẩn quá đấy! Dưới này người qua lại nườm nượp, lỡ mà trúng ai đó thì không phải chuyện nhỏ đâu!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_05','V1005','阮明',5,'我知道错了，以后晾晒衣服一定牢牢固定，绝对不会再出现这种情况了。','wǒ zhī dào cuò le ， yǐ hòu liàng shài yī fú yí dìng láo láo gù dìng ， jué duì bú huì zài chū xiàn zhè zhǒng qíng kuàng le 。','Cháu biết lỗi rồi ạ, sau này phơi đồ cháu nhất định sẽ cột thật chắc, tuyệt đối không để xảy ra chuyện này nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_06','V1005','王阿姨',6,'光嘴上说有什么用？刚才楼下还有小朋友在玩，要是砸到小孩，你负担得起吗？','guāng zuǐ shàng shuō yǒu shén me yòng ？ gāng cái lóu xià hái yǒu xiǎo péng yǒu zài wán ， yào shì zá dào xiǎo hái ， nǐ fù dān dé qǐ ma ？','Nói suông thì có ích gì? Vừa nãy dưới này còn có mấy đứa nhỏ đang chơi nữa, nếu trúng phải trẻ con thì cháu gánh nổi trách nhiệm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_07','V1005','阮明',7,'是我考虑太不周全了，完全没注意楼下有小孩，我等下就换个稳固的晾晒架子。','shì wǒ kǎo lǜ tài bù zhōu quán le ， wán quán méi zhù yì lóu xià yǒu xiǎo hái ， wǒ děng xià jiù huàn gè wěn gù de liàng shài jià zi 。','Đúng là cháu suy nghĩ không chu đáo, hoàn toàn không để ý dưới này có trẻ con, lát nữa cháu đổi ngay cái giá phơi chắc chắn hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_08','V1005','王阿姨',8,'行吧，这次我就不跟宿管反映了，下次再敢这样，我直接上报物业！','xíng ba ， zhè cì wǒ jiù bù gēn sù guǎn fǎn yìng le ， xià cì zài gǎn zhè yàng ， wǒ zhí jiē shàng bào wù yè ！','Thôi được rồi, lần này cô không báo với quản lý ký túc xá đâu, lần sau mà còn tái diễn thế này, cô báo thẳng lên ban quản lý đấy!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1006','SKC1','夜间突发眩晕耳鸣无法行走，拨打校内24小时应急电话',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1006','SIT1006','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有24小时学生应急值班专线，仅限夜间突发身体、安全险情使用，日常小事不建议拨打。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_01','V1006','阮明',1,'老师您好，我是留学生公寓6栋301的学生阮明，我现在身体特别不舒服。','lǎo shī nín hǎo ， wǒ shì liú xué shēng gōng yù 6 dòng 301 de xué shēng ruǎn míng ， wǒ xiàn zài shēn tǐ tè bié bù shū fú 。','Thầy ơi, em là Nguyễn Minh, sinh viên phòng 301 tòa 6 khu ký túc xá lưu học sinh, hiện giờ em thấy rất khó chịu trong người ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_02','V1006','王老师',2,'别着急，慢慢说，具体哪里不舒服？是什么症状？','bié zháo jí ， màn màn shuō ， jù tǐ nǎ lǐ bù shū fú ？ shì shén me zhèng zhuàng ？','Em đừng vội, cứ từ từ nói, cụ thể là khó chịu ở đâu? Triệu chứng thế nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_03','V1006','阮明',3,'我突然耳鸣得特别厉害，还天旋地转的，头晕得根本站不起来、走不了路。','wǒ tū rán ěr míng dé tè bié lì hài ， hái tiān xuán dì zhuàn de ， tóu yūn dé gēn běn zhàn bù qǐ lái 、 zǒu bù liǎo lù 。','Em tự nhiên bị ù tai rất nặng, còn thấy trời đất quay cuồng nữa, chóng mặt đến mức không đứng dậy nổi, không đi lại được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_04','V1006','王老师',4,'你宿舍现在有人陪你吗？身边有没有止痛药或者缓解头晕的药？','nǐ sù shè xiàn zài yǒu rén péi nǐ ma ？ shēn biān yǒu méi yǒu zhǐ tòng yào huò zhě huǎn jiě tóu yūn de yào ？','Trong phòng bây giờ có ai ở cùng em không? Bên cạnh có thuốc giảm đau hay thuốc chống chóng mặt gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_05','V1006','阮明',5,'我室友今天回家了，宿舍就我一个人，我也没备任何药品，现在特别难受。','wǒ shì yǒu jīn tiān huí jiā le ， sù shè jiù wǒ yí gè rén ， wǒ yě méi bèi rèn hé yào pǐn ， xiàn zài tè bié nán shòu 。','Bạn cùng phòng em hôm nay về nhà rồi, phòng chỉ có mình em thôi, em cũng không có sẵn thuốc gì cả, giờ khó chịu lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_06','V1006','王老师',6,'明白，你千万别乱动，靠在床边好好坐着或者躺着，我立刻联系校应急医护人员上楼。','míng bái ， nǐ qiān wàn bié luàn dòng ， kào zài chuáng biān hǎo hǎo zuò zhe huò zhě tǎng zhe ， wǒ lì kè lián xì xiào yìng jí yī hù rén yuán shàng lóu 。','Được rồi, em tuyệt đối đừng cử động lung tung, cứ ngồi hoặc nằm yên dựa vào giường, thầy liên hệ ngay nhân viên y tế cấp cứu của trường lên phòng em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_07','V1006','阮明',7,'麻烦您快一点，我闭上眼睛也一直头晕，有点撑不住了。','má fán nín kuài yì diǎn ， wǒ bì shàng yǎn jīng yě yì zhí tóu yūn ， yǒu diǎn chēng bú zhù le 。','Phiền thầy nhanh giúp em với, em nhắm mắt lại vẫn cứ chóng mặt, có vẻ không trụ nổi nữa rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_08','V1006','王老师',8,'放心，医护人员五分钟内就到，电话别挂，有任何不舒服随时跟我说。','fàng xīn ， yī hù rén yuán wǔ fēn zhōng nèi jiù dào ， diàn huà bié guà ， yǒu rèn hé bù shū fú suí shí gēn wǒ shuō 。','Yên tâm đi, nhân viên y tế năm phút nữa sẽ tới, đừng cúp máy nhé, có gì khó chịu cứ nói với thầy ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1007','SKC1','网约车司机恶意绕道加价，拨打平台客服紧急维权',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1007','SIT1007','P1','twist','chinh_thuc',NULL,'国内网约车全程平台计价，司机私下索要现金加价属于违规，乘客可直接留存录音、行程记录投诉全额退款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_01','V1007','阮明',1,'您好，我要投诉刚刚接单的网约车司机，他故意绕路，还私下跟我加价！','nín hǎo ， wǒ yào tóu sù gāng gāng jiē dān de wǎng yuē chē sī jī ， tā gù yì rào lù ， hái sī xià gēn wǒ jiā jià ！','Chào anh/chị, tôi muốn khiếu nại tài xế xe công nghệ vừa nhận chuyến của tôi, anh ta cố tình đi vòng đường, còn tự ý đòi tôi trả thêm tiền!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_02','V1007','客服',2,'您好先生，麻烦提供一下本次出行的订单编号，我调取行程记录帮您核实。','nín hǎo xiān shēng ， má fán tí gōng yī xià běn cì chū xíng de dìng dān biān hào ， wǒ diào qǔ xíng chéng jì lù bāng nín hé shí 。','Chào anh, phiền anh cung cấp mã đơn hàng của chuyến đi này, tôi sẽ tra cứu lịch trình để xác minh giúp anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_03','V1007','阮明',3,'订单编号是724915。明明导航是直达路线，他非要故意绕远，车费凭空多了不少。','dìng dān biān hào shì 724915。 míng míng dǎo háng shì zhí dá lù xiàn ， tā fēi yào gù yì rào yuǎn ， chē fèi píng kōng duō le bù shǎo 。','Mã đơn hàng là 724915. Rõ ràng bản đồ chỉ đường thẳng mà anh ta cứ cố tình đi vòng, tiền cước tự nhiên đội lên không ít.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_04','V1007','客服',4,'您稍等，我查询一下行程轨迹……确实，多条路段偏离了导航路线，非常抱歉给您带来不好的体验。','nín shāo děng ， wǒ chá xún yī xià xíng chéng guǐ jì …… què shí ， duō tiáo lù duàn piān lí le dǎo háng lù xiàn ， fēi cháng bào qiàn gěi nín dài lái bù hǎo de tǐ yàn 。','Anh chờ chút, tôi kiểm tra lộ trình di chuyển... đúng là có nhiều đoạn đường lệch khỏi tuyến chỉ đường, tôi thành thật xin lỗi vì đã mang đến trải nghiệm không tốt cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_05','V1007','阮明',5,'不止绕路，司机态度还特别差，不肯线上结算，非要我额外给他现金。','bù zhǐ rào lù ， sī jī tài dù hái tè bié chà ， bù kěn xiàn shàng jié suàn ， fēi yào wǒ é wài gěi tā xiàn jīn 。','Không chỉ đi vòng đường, thái độ của tài xế còn rất tệ, không chịu thanh toán qua ứng dụng, cứ đòi tôi trả thêm tiền mặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_06','V1007','客服',6,'了解了，这属于司机违规加价行为。我们会对司机进行处罚，多收的费用会原路退回您的账户。','liǎo jiě le ， zhè shǔ yú sī jī wéi guī jiā jià xíng wéi 。 wǒ men huì duì sī jī jìn xíng chǔ fá ， duō shōu de fèi yòng huì yuán lù tuì huí nín de zhàng hù 。','Tôi hiểu rồi, đây là hành vi thu thêm tiền trái quy định của tài xế. Chúng tôi sẽ xử phạt tài xế này, khoản phí thu thêm sẽ được hoàn trả lại đúng vào tài khoản của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_07','V1007','阮明',7,'大概多久能处理完？我之后还要经常打车上学，很怕再遇到这种情况。','dà gài duō jiǔ néng chǔ lǐ wán ？ wǒ zhī hòu hái yào jīng cháng dǎ chē shàng xué ， hěn pà zài yù dào zhè zhǒng qíng kuàng 。','Khoảng bao lâu thì xử lý xong? Sau này tôi vẫn phải thường xuyên đặt xe đi học, tôi rất sợ lại gặp phải tình huống như thế này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_08','V1007','客服',8,'常规退款需要1\-3个工作日，我这边给您加急标记工单，优先处理。','cháng guī tuì kuǎn xū yào 1\-3 gè gōng zuò rì ， wǒ zhè biān gěi nín jiā jí biāo jì gōng dān ， yōu xiān chǔ lǐ 。','Hoàn tiền thông thường cần 1-3 ngày làm việc, tôi sẽ đánh dấu khẩn cho yêu cầu của anh để được xử lý ưu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_09','V1007','阮明',9,'好的，麻烦您尽量快一点。','hǎo de ， má fán nín jǐn liàng kuài yì diǎn 。','Vâng, phiền anh/chị cố gắng xử lý nhanh giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_10','V1007','客服',10,'处理结果会以短信通知您，后续有问题随时联系我们。','chǔ lǐ jié guǒ huì yǐ duǎn xìn tōng zhī nín ， hòu xù yǒu wèn tí suí shí lián xì wǒ men 。','Kết quả xử lý sẽ được thông báo cho anh qua tin nhắn, nếu sau này còn vấn đề gì xin cứ liên hệ với chúng tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1008','SKC1','骑行共享单车摔倒扭伤，向路人求助简单伤口处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1008','SIT1008','P1','suon_se','tuy_y',NULL,'国内很多年轻人会随身备简易消毒用品，路人遇到受伤行人大多愿意主动提供临时帮助。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_01','V1008','阮明',1,'你好，不好意思打扰一下，我骑车摔倒了，膝盖擦伤流血了，你有碘伏吗？','nǐ hǎo ， bù hǎo yì sī dǎ rǎo yī xià ， wǒ qí chē shuāi dǎo le ， xī gài cā shāng liú xiě le ， nǐ yǒu diǎn fú ma ？','Chào chị, xin lỗi làm phiền chị một chút, em bị ngã xe đạp, đầu gối trầy xước chảy máu rồi, chị có cồn i-ốt không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_02','V1008','刘姑娘',2,'天呐，你摔得看着好疼！我刚好带了消毒湿巾和创可贴，我帮你处理一下。','tiān nà ， nǐ shuāi dé kàn zhe hǎo téng ！ wǒ gāng hǎo dài le xiāo dú shī jīn hé chuàng kě tiē ， wǒ bāng nǐ chǔ lǐ yī xià 。','Trời ơi, nhìn em ngã đau vậy! May quá chị có mang theo khăn giấy khử trùng với băng cá nhân đây, để chị xử lý giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_03','V1008','阮明',3,'太谢谢你了！刚刚刹车打滑，直接摔在路边，伤口一直流血，我都不知道怎么办。','tài xiè xiè nǐ le ！ gāng gāng shā chē dǎ huá ， zhí jiē shuāi zài lù biān ， shāng kǒu yì zhí liú xiě ， wǒ dōu bù zhī dào zěn me bàn 。','Cảm ơn chị nhiều lắm! Vừa nãy em phanh gấp bị trượt bánh, ngã ngay ra lề đường luôn, vết thương cứ chảy máu mãi, em không biết phải làm sao nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_04','V1008','刘姑娘',4,'你先坐台阶上别动，别来回蹭，不然伤口容易沾灰尘发炎。','nǐ xiān zuò tái jiē shàng bié dòng ， bié lái huí cèng ， bù rán shāng kǒu róng yì zhān huī chén fā yán 。','Em ngồi yên trên bậc thềm đi, đừng cử động qua lại, không thì vết thương dễ dính bụi bẩn rồi bị viêm đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_05','V1008','阮明',5,'好，辛苦你了。我平时没带急救用品的习惯，这次太疏忽了。','hǎo ， xīn kǔ nǐ le 。 wǒ píng shí méi dài jí jiù yòng pǐn de xí guàn ， zhè cì tài shū hū le 。','Dạ vâng, chị vất vả rồi. Em bình thường không có thói quen mang theo đồ sơ cứu, lần này sơ suất quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_06','V1008','刘姑娘',6,'没事，举手之劳。不过你下次骑车慢点，雨天路面滑，特别容易打滑摔倒。','méi shì ， jǔ shǒu zhī láo 。 bù guò nǐ xià cì qí chē màn diǎn ， yǔ tiān lù miàn huá ， tè bié róng yì dǎ huá shuāi dǎo 。','Không sao đâu, chuyện nhỏ thôi mà. Nhưng lần sau em đi xe chậm lại nhé, trời mưa đường trơn, rất dễ trượt ngã đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_07','V1008','阮明',7,'我记住啦，以后一定注意。处理完我自己慢慢收拾车子，不耽误你赶路。','wǒ jì zhù la ， yǐ hòu yí dìng zhù yì 。 chǔ lǐ wán wǒ zì jǐ màn màn shōu shí chē zi ， bù dān wù nǐ gǎn lù 。','Em nhớ rồi ạ, sau này nhất định sẽ chú ý. Xử lý xong em tự dọn xe từ từ, không làm chậm trễ việc của chị đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1009','SKC1','外出迷路手机没电关机，向商铺店员借手机联系好友',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1009','SIT1009','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内商铺店主出于防骗顾虑，大多不愿外借私人手机，街边共享充电宝是外出应急充电主流方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_01','V1009','阮明',1,'老板您好，打扰一下，我的手机没电关机了，能不能借您手机打个短电话？','lǎo bǎn nín hǎo ， dǎ rǎo yī xià ， wǒ de shǒu jī méi diàn guān jī le ， néng bù néng jiè nín shǒu jī dǎ gè duǎn diàn huà ？','Chào anh chủ, phiền anh chút ạ, điện thoại em hết pin tắt máy rồi, anh cho em mượn điện thoại gọi nhờ một cuộc ngắn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_02','V1009','赵老板',2,'借手机可以，我先问下，你要打给谁？大概打多久？','jiè shǒu jī kě yǐ ， wǒ xiān wèn xià ， nǐ yào dǎ gěi shuí ？ dà gài dǎ duō jiǔ ？','Cho mượn thì được, nhưng để tôi hỏi trước đã, cậu định gọi cho ai? Gọi khoảng bao lâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_03','V1009','阮明',3,'我和同学出门走散迷路了，就两分钟，跟他说下我的位置就行，很快的。','wǒ hé tóng xué chū mén zǒu sàn mí lù le ， jiù liǎng fēn zhōng ， gēn tā shuō xià wǒ de wèi zhì jiù xíng ， hěn kuài de 。','Em với bạn học đi chơi bị lạc nhau, chỉ hai phút thôi ạ, em nói vị trí của em cho bạn ấy là được rồi, nhanh lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_04','V1009','赵老板',4,'哎，实在不好意思，现在外面骗子太多，陌生人借手机的情况很乱，我不太敢直接借你。','āi ， shí zài bù hǎo yì sī ， xiàn zài wài miàn piàn zi tài duō ， mò shēng rén jiè shǒu jī de qíng kuàng hěn luàn ， wǒ bù tài gǎn zhí jiē jiè nǐ 。','Ây, thật ngại quá, giờ ngoài đường lừa đảo nhiều lắm, chuyện người lạ mượn điện thoại cũng phức tạp, tôi không dám cho mượn thẳng như vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_05','V1009','阮明',5,'我不是骗子的！我是旁边大学的留学生，我可以给您看我的居留卡，证明我的身份。','wǒ bú shì piàn zi de ！ wǒ shì páng biān dà xué de liú xué shēng ， wǒ kě yǐ gěi nín kàn wǒ de jū liú kǎ ， zhèng míng wǒ de shēn fèn 。','Em không phải lừa đảo đâu! Em là du học sinh của trường đại học gần đây, em có thể cho anh xem thẻ cư trú để chứng minh thân phận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_06','V1009','赵老板',6,'我理解你着急，但我也不方便仔细核对证件，风险太大了。你可以去对面便利店租个充电宝充电。','wǒ lǐ jiě nǐ zháo jí ， dàn wǒ yě bù fāng biàn zǐ xì hé duì zhèng jiàn ， fēng xiǎn tài dà le 。 nǐ kě yǐ qù duì miàn biàn lì diàn zū gè chōng diàn bǎo chōng diàn 。','Tôi hiểu cậu đang gấp, nhưng tôi cũng không tiện kiểm tra giấy tờ kỹ càng, rủi ro lớn quá. Cậu có thể sang cửa hàng tiện lợi đối diện thuê sạc dự phòng mà sạc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_07','V1009','阮明',7,'啊……好吧，那我现在过去试试，麻烦您了。','a …… hǎo ba ， nà wǒ xiàn zài guò qù shì shì ， má fán nín le 。','À... vâng, vậy em qua bên đó thử xem sao, phiền anh rồi ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_08','V1009','赵老板',8,'多多包涵哈，我们开店也是怕出问题，希望你理解。','duō duō bāo hán hā ， wǒ men kāi diàn yě shì pà chū wèn tí ， xī wàng nǐ lǐ jiě 。','Mong cậu thông cảm nhé, chúng tôi buôn bán cũng sợ xảy ra chuyện, hy vọng cậu hiểu cho.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1010','SKC1','背包在商场被小偷顺手牵羊，前往附近派出所做笔录',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1010','SIT1010','P1','twist','chinh_thuc',NULL,'外国人丢失随身财物报案，需携带护照、居留许可，笔录信息会同步登记出入境系统。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_01','V1010','阮明',1,'警官您好，我要报案，我的背包在商场被人偷走了。','jǐng guān nín hǎo ， wǒ yào bào àn ， wǒ de bēi bāo zài shāng chǎng bèi rén tōu zǒu le 。','Chào anh công an, tôi muốn trình báo, ba lô của tôi bị người ta lấy trộm trong trung tâm thương mại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_02','V1010','周警官',2,'先坐，不用慌。报一下你的姓名、国籍，还有居留许可的相关信息。','xiān zuò ， bù yòng huāng 。 bào yī xià nǐ de xìng míng 、 guó jí ， hái yǒu jū liú xǔ kě de xiāng guān xìn xī 。','Mời ngồi trước đã, không cần hoảng. Anh cho tôi biết họ tên, quốc tịch, và thông tin liên quan đến giấy phép cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_03','V1010','阮明',3,'我叫阮明，是越南留学生。背包里有我的银行卡、耳机，还有上课用的笔记。','wǒ jiào ruǎn míng ， shì yuè nán liú xué shēng 。 bēi bāo lǐ yǒu wǒ de yín háng kǎ 、 ěr jī ， hái yǒu shàng kè yòng de bǐ jì 。','Tôi tên Nguyễn Minh, là du học sinh Việt Nam. Trong ba lô có thẻ ngân hàng, tai nghe, và vở ghi chép đi học của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_04','V1010','周警官',4,'具体是什么时间、商场哪一层、哪个位置丢的？仔细回忆清楚。','jù tǐ shì shén me shí jiān 、 shāng chǎng nǎ yī céng 、 nǎ ge wèi zhì diū de ？ zǐ xì huí yì qīng chǔ 。','Cụ thể là mất vào lúc nào, ở tầng nào, vị trí nào trong trung tâm thương mại? Anh nhớ lại cho kỹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_05','V1010','阮明',5,'大概四十分钟前，我在商场餐饮区取餐，就离开座位几十秒，回头背包就没了。','dà gài sì shí fēn zhōng qián ， wǒ zài shāng chǎng cān yǐn qū qǔ cān ， jiù lí kāi zuò wèi jǐ shí miǎo ， huí tóu bēi bāo jiù méi le 。','Khoảng bốn mươi phút trước, tôi đang lấy đồ ăn ở khu ẩm thực, chỉ rời khỏi chỗ ngồi vài chục giây, quay lại thì ba lô đã biến mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_06','V1010','周警官',6,'我跟你说实话，商场人流量太大，人员混杂，就算调取监控，找回物品的难度也不小。','wǒ gēn nǐ shuō shí huà ， shāng chǎng rén liú liàng tài dà ， rén yuán hùn zá ， jiù suàn diào qǔ jiān kòng ， zhǎo huí wù pǐn de nán dù yě bù xiǎo 。','Tôi nói thật với anh, trung tâm thương mại đông người qua lại, thành phần phức tạp, dù có trích xuất camera thì việc tìm lại đồ cũng không dễ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_07','V1010','阮明',7,'啊？那怎么办……我的银行卡还没挂失，万一被盗刷就麻烦了。请问有银行挂失电话吗？','a ？ nà zěn me bàn …… wǒ de yín háng kǎ hái méi guà shī ， wàn yī bèi dào shuā jiù má fán le 。 qǐng wèn yǒu yín háng guà shī diàn huà ma ？','Hả? Vậy phải làm sao đây... Thẻ ngân hàng của tôi chưa báo mất, lỡ bị quẹt trộm thì phiền lắm. Anh cho tôi hỏi số điện thoại báo mất thẻ ngân hàng được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_08','V1010','周警官',8,'我把挂失电话写纸条给你，你先做完笔录，尽快联系银行冻结卡片，减少损失。','wǒ bǎ guà shī diàn huà xiě zhǐ tiáo gěi nǐ ， nǐ xiān zuò wán bǐ lù ， jǐn kuài lián xì yín háng dòng jié kǎ piàn ， jiǎn shǎo sǔn shī 。','Tôi ghi số điện thoại báo mất ra giấy cho anh, anh làm biên bản xong trước đã, rồi liên hệ ngân hàng khóa thẻ càng sớm càng tốt để giảm thiệt hại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_09','V1010','阮明',9,'好，谢谢警官，我马上配合做笔录。','hǎo ， xiè xiè jǐng guān ， wǒ mǎ shàng pèi hé zuò bǐ lù 。','Vâng, cảm ơn anh công an, tôi sẽ hợp tác làm biên bản ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1011','SKC1','暴雨导致郊区公交全线停运，求助社区工作人员临时安置',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1011','SIT1011','P1','suon_se','ban_chinh_thuc',NULL,'国内社区服务中心对受极端天气滞留的路人提供免费临时休息、热水充电等便民服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_01','V1011','阮明',1,'您好，外面暴雨太大，所有公交都停运了，我回不了学校，能在这边临时待一会吗？','nín hǎo ， wài miàn bào yǔ tài dà ， suǒ yǒu gōng jiāo dōu tíng yùn le ， wǒ huí bù liǎo xué xiào ， néng zài zhè biān lín shí dài yī huì ma ？','Chào chị, ngoài trời mưa to quá, xe buýt dừng chạy hết rồi, em không về trường được, cho em tạm trú ở đây một lát được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_02','V1011','小吴',2,'同学别着急，你是哪个学校的？身上有没有带雨具？','tóng xué bié zháo jí ， nǐ shì nǎ ge xué xiào de ？ shēn shàng yǒu méi yǒu dài yǔ jù ？','Em đừng lo, em học trường nào vậy? Có mang theo áo mưa hay ô gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_03','V1011','阮明',3,'我是外国语大学的留学生，出门没带伞，手机也快没电了，根本打不到车。','wǒ shì wài guó yǔ dà xué de liú xué shēng ， chū mén méi dài sǎn ， shǒu jī yě kuài méi diàn le ， gēn běn dǎ bú dào chē 。','Em là du học sinh trường Đại học Ngoại ngữ, lúc ra ngoài không mang ô, điện thoại cũng sắp hết pin, gọi xe cũng không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_04','V1011','小吴',4,'我懂，现在路面积水太深，网约车也进不来。你可以在我们社区服务站临时休息，等雨小再说。','wǒ dǒng ， xiàn zài lù miàn jī shuǐ tài shēn ， wǎng yuē chē yě jìn bù lái 。 nǐ kě yǐ zài wǒ men shè qū fú wù zhàn lín shí xiū xī ， děng yǔ xiǎo zài shuō 。','Chị hiểu, giờ đường ngập nước sâu quá, xe công nghệ cũng không vào được. Em cứ nghỉ tạm ở trạm dịch vụ cộng đồng của chị đây, đợi mưa nhỏ bớt rồi tính tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_05','V1011','阮明',5,'太感谢您了！我本来还赶着回去上晚自习，这下肯定赶不上了。','tài gǎn xiè nín le ！ wǒ běn lái hái gǎn zhe huí qù shàng wǎn zì xí ， zhè xià kěn dìng gǎn bù shàng le 。','Em cảm ơn chị nhiều lắm! Em vốn định về kịp giờ tự học tối, giờ chắc chắn không kịp rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_06','V1011','小吴',6,'没事，我给你倒杯热水，你抽空跟辅导员说下情况，请假报备一下。','méi shì ， wǒ gěi nǐ dào bēi rè shuǐ ， nǐ chōu kòng gēn fǔ dǎo yuán shuō xià qíng kuàng ， qǐng jià bào bèi yī xià 。','Không sao đâu, để chị rót cho em cốc nước nóng, em tranh thủ báo tình hình cho thầy cô cố vấn, xin nghỉ phép một tiếng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_07','V1011','阮明',7,'好，我借您这边的插座充下电，等雨势变小了再想办法回学校。','hǎo ， wǒ jiè nín zhè biān de chā zuò chōng xià diàn ， děng yǔ shì biàn xiǎo le zài xiǎng bàn fǎ huí xué xiào 。','Vâng, em mượn ổ cắm điện bên chị sạc pin một chút, đợi mưa nhỏ lại em sẽ tìm cách về trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_08','V1011','小吴',8,'安心待着，暴雨天路况危险，千万别强行出门涉水。','ān xīn dài zhe ， bào yǔ tiān lù kuàng wēi xiǎn ， qiān wàn bié qiáng xíng chū mén shè shuǐ 。','Cứ yên tâm ở đây đi, trời mưa to đường sá nguy hiểm lắm, tuyệt đối đừng cố ra ngoài lội nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1012','SKC1','街边小吃食物中毒集体腹痛，拨打市场监管热线投诉',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1012','SIT1012','P1','twist','chinh_thuc',NULL,'餐饮食物中毒维权需要保留消费凭证、医院诊断单据，监管部门会现场抽检食材，属实可要求商家全额赔偿医药费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_01','V1012','阮明',1,'您好，我要举报街边小吃摊！我和两个同学吃完之后，全都腹痛、拉肚子，应该是食物中毒了。','nín hǎo ， wǒ yào jǔ bào jiē biān xiǎo chī tān ！ wǒ hé liǎng gè tóng xué chī wán zhī hòu ， quán dōu fù tòng 、 lā dù zi ， yīng gāi shì shí wù zhòng dú le 。','Chào chị, tôi muốn tố cáo một quán ăn vặt ven đường! Tôi và hai bạn học sau khi ăn xong đều bị đau bụng, tiêu chảy, chắc là ngộ độc thực phẩm rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_02','V1012','接线员',2,'麻烦您提供一下小吃摊的具体地址、摊位名称，还有你们的就餐时间。','má fán nín tí gōng yī xià xiǎo chī tān de jù tǐ dì zhǐ 、 tān wèi míng chēng ， hái yǒu nǐ men de jiù cān shí jiān 。','Phiền anh chị cung cấp địa chỉ cụ thể của quán ăn vặt, tên gian hàng, và thời gian các bạn ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_03','V1012','阮明',3,'就在我们学校南门的小巷子里，是一家无名炸串摊，今天傍晚六点左右我们在那吃的。','jiù zài wǒ men xué xiào nán mén de xiǎo xiàng zi lǐ ， shì yī jiā wú míng zhà chuàn tān ， jīn tiān bàng wǎn liù diǎn zuǒ yòu wǒ men zài nà chī de 。','Ngay trong con hẻm nhỏ ở cổng nam trường tôi, là một quán xiên chiên không có tên, chiều nay khoảng sáu giờ chúng tôi ăn ở đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_04','V1012','接线员',4,'了解了。请问你们现在身体状况怎么样？有没有去医院开具诊断证明？','liǎo jiě le 。 qǐng wèn nǐ men xiàn zài shēn tǐ zhuàng kuàng zěn me yàng ？ yǒu méi yǒu qù yī yuàn kāi jù zhěn duàn zhèng míng ？','Tôi đã rõ. Xin hỏi hiện giờ tình trạng sức khỏe của các bạn thế nào? Đã đi bệnh viện xin giấy chẩn đoán chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_05','V1012','阮明',5,'我们刚从社区诊所看完，医生确诊是不洁食物引发的肠胃不适。','wǒ men gāng cóng shè qū zhěn suǒ kàn wán ， yī shēng què zhěn shì bù jié shí wù yǐn fā de cháng wèi bù shì 。','Chúng tôi vừa khám xong ở phòng khám cộng đồng, bác sĩ chẩn đoán là rối loạn tiêu hóa do thức ăn không sạch gây ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_06','V1012','接线员',6,'需要您携带就诊单据、消费记录，在工作日到辖区监管所现场登记投诉。','xū yào nín xié dài jiù zhěn dān jù 、 xiāo fèi jì lù ， zài gōng zuò rì dào xiá qū jiān guǎn suǒ xiàn chǎng dēng jì tóu sù 。','Anh chị cần mang theo hóa đơn khám bệnh, chứng từ chi tiêu, đến cơ quan quản lý khu vực vào ngày làm việc để đăng ký khiếu nại trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_07','V1012','阮明',7,'我们这周课程很多，下周才能过去登记，万一这几天摊位跑路、关门怎么办？','wǒ men zhè zhōu kè chéng hěn duō ， xià zhōu cái néng guò qù dēng jì ， wàn yī zhè jǐ tiān tān wèi pǎo lù 、 guān mén zěn me bàn ？','Tuần này chúng tôi lịch học dày lắm, tuần sau mới đi đăng ký được, lỡ mấy ngày này quán bỏ trốn hoặc đóng cửa thì sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_08','V1012','接线员',8,'您不用担心，我们会立刻安排工作人员上门核查，暂扣摊位食材留存证据，固定线索。','nín bù yòng dān xīn ， wǒ men huì lì kè ān pái gōng zuò rén yuán shàng mén hé chá ， zàn kòu tān wèi shí cái liú cún zhèng jù ， gù dìng xiàn suǒ 。','Anh chị đừng lo, chúng tôi sẽ cử người đến kiểm tra ngay, tạm giữ nguyên liệu của quán để lưu làm bằng chứng, cố định manh mối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_09','V1012','阮明',9,'那就好，辛苦你们尽快处理。','nà jiù hǎo ， xīn kǔ nǐ men jǐn kuài chǔ lǐ 。','Vậy thì tốt quá, phiền các anh chị xử lý sớm giúp chúng tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1013','SKC1','居留许可卡片断裂损毁，出入境大厅申请临时通行纸质证明',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1013','SIT1013','P1','suon_se','chinh_thuc',NULL,'外国人居留许可损毁、丢失均无法单独出行，临时纸质通行证明仅限国内短期交通出行使用，不能替代正式居留卡。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_01','V1013','阮明',1,'您好，我的外国人居留许可不小心折断损坏了，刷不了卡，想办理临时通行证明。','nín hǎo ， wǒ de wài guó rén jū liú xǔ kě bù xiǎo xīn zhé duàn sǔn huài le ， shuā bù liǎo kǎ ， xiǎng bàn lǐ lín shí tōng xíng zhèng míng 。','Chào chị, thẻ cư trú người nước ngoài của tôi vô tình bị gãy hỏng, không quẹt được nữa, tôi muốn làm giấy chứng nhận thông hành tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_02','V1013','刘柜员',2,'麻烦先出示一下你的护照，还有破损的居留卡，我先帮你核验信息。','má fán xiān chū shì yī xià nǐ de hù zhào ， hái yǒu pò sǔn de jū liú kǎ ， wǒ xiān bāng nǐ hé yàn xìn xī 。','Phiền anh xuất trình hộ chiếu, và cả thẻ cư trú bị hỏng, để tôi kiểm tra thông tin trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_03','V1013','阮明',3,'您看，卡片中间裂开了，所有设备都识别不了。我下周还要坐高铁外出办事，特别着急。','nín kàn ， kǎ piàn zhōng jiān liè kāi le ， suǒ yǒu shè bèi dōu shí bié bù liǎo 。 wǒ xià zhōu hái yào zuò gāo tiě wài chū bàn shì ， tè bié zháo jí 。','Chị xem, thẻ bị nứt ngay giữa, mọi thiết bị đều không nhận diện được. Tuần sau tôi còn phải đi tàu cao tốc để giải quyết việc, gấp lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_04','V1013','刘柜员',4,'我看到了，破损的居留卡已经失效，不能正常使用了。临时纸质证明有效期只有七天，你注意时间。','wǒ kàn dào le ， pò sǔn de jū liú kǎ yǐ jīng shī xiào ， bù néng zhèng cháng shǐ yòng le 。 lín shí zhǐ zhì zhèng míng yǒu xiào qī zhǐ yǒu qī tiān ， nǐ zhù yì shí jiān 。','Tôi thấy rồi, thẻ cư trú bị hỏng đã mất hiệu lực, không dùng được bình thường nữa. Giấy chứng nhận tạm thời chỉ có hiệu lực bảy ngày thôi, anh chú ý thời hạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_05','V1013','阮明',5,'七天完全够我补办新卡了。请问办理这个证明，还需要额外准备其他材料吗？','qī tiān wán quán gòu wǒ bǔ bàn xīn kǎ le 。 qǐng wèn bàn lǐ zhè ge zhèng míng ， hái xū yào é wài zhǔn bèi qí tā cái liào ma ？','Bảy ngày là đủ để tôi làm lại thẻ mới rồi. Cho tôi hỏi làm giấy chứng nhận này có cần chuẩn bị thêm giấy tờ gì khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_06','V1013','刘柜员',6,'只需要准备一张一寸白底证件照，填写补办申请表，现场等待半小时就能出证。','zhǐ xū yào zhǔn bèi yī zhāng yī cùn bái dǐ zhèng jiàn zhào ， tián xiě bǔ bàn shēn qǐng biǎo ， xiàn chǎng děng dài bàn xiǎo shí jiù néng chū zhèng 。','Chỉ cần chuẩn bị một ảnh thẻ nền trắng cỡ 1 inch, điền đơn xin cấp lại, chờ tại chỗ nửa tiếng là có giấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_07','V1013','阮明',7,'还好我今天带齐了证件，不然下周出行肯定要被拦下，太耽误事了。','hái hǎo wǒ jīn tiān dài qí le zhèng jiàn ， bù rán xià zhōu chū xíng kěn dìng yào bèi lán xià ， tài dān wù shì le 。','May mà hôm nay tôi mang đủ giấy tờ, không thì tuần sau đi lại chắc chắn bị chặn lại, lỡ việc quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_08','V1013','刘柜员',8,'拿到临时证明后，近期出门务必同时携带护照，配合查验。','ná dào lín shí zhèng míng hòu ， jìn qī chū mén wù bì tóng shí xié dài hù zhào ， pèi hé chá yàn 。','Sau khi nhận giấy chứng nhận tạm thời, thời gian tới ra ngoài nhất định phải mang theo hộ chiếu để phối hợp kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1014','SKC1','签证线上缴费扣款成功但系统未入账，联系出入境财务加急核对',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1014','SIT1014','P1','that_bai_nhe','chinh_thuc',NULL,'政务线上缴费存在银行、政务系统对账时差，窗口开具纸质临时凭证可临时规避审核拦截。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_01','V1014','阮明',1,'陈会计您好，我想咨询一下，我昨天线上续签签证，银行卡已经扣款成功，但系统一直显示未缴费。','chén kuài jì nín hǎo ， wǒ xiǎng zī xún yī xià ， wǒ zuó tiān xiàn shàng xù qiān qiān zhèng ， yín háng kǎ yǐ jīng kòu kuǎn chéng gōng ， dàn xì tǒng yì zhí xiǎn shì wèi jiǎo fèi 。','Chào kế toán Trần, tôi muốn hỏi một chút, hôm qua tôi gia hạn visa trực tuyến, thẻ ngân hàng đã bị trừ tiền thành công, nhưng hệ thống vẫn hiện chưa nộp phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_02','V1014','陈会计',2,'你把缴费订单号、银行卡扣款截图，统一发到我的办公邮箱。','nǐ bǎ jiǎo fèi dìng dān hào 、 yín háng kǎ kòu kuǎn jié tú ， tǒng yī fā dào wǒ de bàn gōng yóu xiāng 。','Anh gửi mã đơn thanh toán, cùng ảnh chụp màn hình bị trừ tiền, vào email công tác của tôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_03','V1014','阮明',3,'好的，订单号是896421，扣款截图我都保存好了，现在就能发给您。','hǎo de ， dìng dān hào shì 896421， kòu kuǎn jié tú wǒ dōu bǎo cún hǎo le ， xiàn zài jiù néng fā gěi nín 。','Vâng, mã đơn là 896421, ảnh chụp bị trừ tiền tôi đã lưu sẵn rồi, giờ có thể gửi cho chị ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_04','V1014','陈会计',4,'我先跟你说明，这种跨银行缴费延迟入账很常见，需要系统夜间对账，最快明天才能更新状态。','wǒ xiān gēn nǐ shuō míng ， zhè zhǒng kuà yín háng jiǎo fèi yán chí rù zhàng hěn cháng jiàn ， xū yào xì tǒng yè jiān duì zhàng ， zuì kuài míng tiān cái néng gēng xīn zhuàng tài 。','Tôi nói trước với anh, kiểu thanh toán liên ngân hàng bị chậm ghi nhận thế này rất thường gặp, cần hệ thống đối soát vào ban đêm, sớm nhất là ngày mai mới cập nhật được trạng thái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_05','V1014','阮明',5,'可是我后天就要提交续签审核了，系统显示未缴费，申请会直接被驳回，来不及等明天。','kě shì wǒ hòu tiān jiù yào tí jiāo xù qiān shěn hé le ， xì tǒng xiǎn shì wèi jiǎo fèi ， shēn qǐng huì zhí jiē bèi bó huí ， lái bù jí děng míng tiān 。','Nhưng ngày kia tôi đã phải nộp hồ sơ gia hạn xét duyệt rồi, hệ thống hiện chưa nộp phí thì hồ sơ sẽ bị từ chối ngay, không kịp chờ đến ngày mai đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_06','V1014','陈会计',6,'我理解你的紧急情况，我可以给你开具一份临时缴费凭证，窗口可以凭凭证先受理你的申请材料。','wǒ lǐ jiě nǐ de jǐn jí qíng kuàng ， wǒ kě yǐ gěi nǐ kāi jù yī fèn lín shí jiǎo fèi píng zhèng ， chuāng kǒu kě yǐ píng píng zhèng xiān shòu lǐ nǐ de shēn qǐng cái liào 。','Tôi hiểu tình huống gấp của anh, tôi có thể cấp cho anh một giấy chứng nhận thanh toán tạm thời, quầy tiếp nhận có thể dựa vào đó để tiếp nhận hồ sơ của anh trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_07','V1014','阮明',7,'太好了！我现在立刻发送截图，麻烦您尽快帮我核对处理。','tài hǎo le ！ wǒ xiàn zài lì kè fā sòng jié tú ， má fán nín jǐn kuài bāng wǒ hé duì chǔ lǐ 。','Tuyệt quá! Tôi gửi ảnh chụp ngay bây giờ, phiền chị kiểm tra xử lý giúp tôi sớm nhất có thể.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_08','V1014','陈会计',8,'我今天下班前完成对账核对，如果资金还是未同步，你明天上午再来一趟补录信息。','wǒ jīn tiān xià bān qián wán chéng duì zhàng hé duì ， rú guǒ zī jīn hái shì wèi tóng bù ， nǐ míng tiān shàng wǔ zài lái yī tàng bǔ lù xìn xī 。','Tôi sẽ hoàn thành đối soát trước khi tan làm hôm nay, nếu tiền vẫn chưa đồng bộ thì sáng mai anh ghé lại bổ sung thông tin nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1015','SKC1','论文截止日前电脑硬盘崩溃文件丢失，找授课老师申请延期并借用图书馆设备',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1015','SIT1015','P1','twist','ban_chinh_thuc',NULL,'国内高校论文延期需提交书面说明\+客观事故证明，任课老师无权私自延期，必须上报教务审批。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_01','V1015','阮明',1,'周老师，不好意思打扰您，我遇到突发情况，电脑硬盘突然损坏，整篇毕业论文文件全部丢失了。','zhōu lǎo shī ， bù hǎo yì sī dǎ rǎo nín ， wǒ yù dào tū fā qíng kuàng ， diàn nǎo yìng pán tū rán sǔn huài ， zhěng piān bì yè lùn wén wén jiàn quán bù diū shī le 。','Thầy Chu ơi, xin lỗi đã làm phiền thầy, em gặp sự cố đột xuất, ổ cứng máy tính đột nhiên bị hỏng, toàn bộ file luận văn tốt nghiệp của em mất sạch rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_02','V1015','周教授',2,'怎么会出现这种意外？学院论文截止提交日期就在明天中午，时间非常紧张。','zěn me huì chū xiàn zhè zhǒng yì wài ？ xué yuàn lùn wén jié zhǐ tí jiāo rì qī jiù zài míng tiān zhōng wǔ ， shí jiān fēi cháng jǐn zhāng 。','Sao lại xảy ra chuyện bất ngờ thế này? Hạn nộp luận văn của khoa là trưa mai rồi, thời gian gấp lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_03','V1015','阮明',3,'我之前没有备份文件，现在硬盘完全读取不了，维修店说数据恢复的概率很低。','wǒ zhī qián méi yǒu bèi fèn wén jiàn ， xiàn zài yìng pán wán quán dú qǔ bù liǎo ， wéi xiū diàn shuō shù jù huī fù de gài lǜ hěn dī 。','Trước đó em không sao lưu file, giờ ổ cứng hoàn toàn không đọc được, tiệm sửa máy nói khả năng khôi phục dữ liệu rất thấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_04','V1015','周教授',4,'我很理解你的突发状况，但学院的截止时间是统一规定的，我个人没办法直接给你延后。','wǒ hěn lǐ jiě nǐ de tū fā zhuàng kuàng ， dàn xué yuàn de jié zhǐ shí jiān shì tǒng yī guī dìng de ， wǒ gè rén méi bàn fǎ zhí jiē gěi nǐ yán hòu 。','Thầy rất hiểu tình huống bất ngờ của em, nhưng thời hạn của khoa là quy định chung, thầy không thể tự ý cho em gia hạn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_05','V1015','阮明',5,'我知道规则很严格！老师，我能不能申请三天延期？图书馆有备用电脑，我可以通宵重新写完初稿，绝对不拖延太久。','wǒ zhī dào guī zé hěn yán gé ！ lǎo shī ， wǒ néng bù néng shēn qǐng sān tiān yán qī ？ tú shū guǎn yǒu bèi yòng diàn nǎo ， wǒ kě yǐ tōng xiāo chóng xīn xiě wán chū gǎo ， jué duì bù tuō yán tài jiǔ 。','Em biết quy định rất nghiêm ngặt ạ! Thầy ơi, em có thể xin gia hạn ba ngày được không ạ? Thư viện có máy tính dự phòng, em có thể thức trắng đêm viết lại bản nháp, chắc chắn không kéo dài lâu đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_06','V1015','周教授',6,'这样，你先写一份详细的书面情况说明，再附上电脑硬盘损坏的维修单据，我帮你上报教务处申请。','zhè yàng ， nǐ xiān xiě yī fèn xiáng xì de shū miàn qíng kuàng shuō míng ， zài fù shàng diàn nǎo yìng pán sǔn huài de wéi xiū dān jù ， wǒ bāng nǐ shàng bào jiào wù chù shēn qǐng 。','Thế này nhé, em viết một bản trình bày chi tiết bằng văn bản trước, kèm theo hóa đơn sửa chữa ổ cứng bị hỏng, thầy sẽ giúp em báo cáo lên phòng đào tạo xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_07','V1015','阮明',7,'太感谢老师了！我现在就去图书馆借设备，马上开始重新赶写论文。','tài gǎn xiè lǎo shī le ！ wǒ xiàn zài jiù qù tú shū guǎn jiè shè bèi ， mǎ shàng kāi shǐ chóng xīn gǎn xiě lùn wén 。','Em cảm ơn thầy nhiều lắm! Em đi thư viện mượn máy ngay bây giờ, bắt tay viết lại luận văn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_08','V1015','周教授',8,'尽量加快进度，教务最多只能审批三天缓冲期，这是最大限度了，千万别再超时。','jǐn liàng jiā kuài jìn dù ， jiào wù zuì duō zhǐ néng shěn pī sān tiān huǎn chōng qī ， zhè shì zuì dà xiàn dù le ， qiān wàn bié zài chāo shí 。','Cố gắng đẩy nhanh tiến độ nhé, phòng đào tạo nhiều nhất chỉ duyệt cho ba ngày gia hạn thôi, đây là giới hạn tối đa rồi, tuyệt đối đừng để quá hạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1016','SKC1','出入境预约号当日失效，携带齐全材料现场窗口申请加急受理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1016','SIT1016','P1','that_bai_nhe','ban_chinh_thuc',NULL,'出入境线上预约实行分时段限号制度，普通出行、学术活动不纳入紧急加急受理范围，仅重大医疗、亲属变故可走绿色通道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_01','V1016','阮明',1,'你好，我今天预约了签证续签，刚刚扫码显示预约号失效了，我所有办理材料都带齐了。','nǐ hǎo ， wǒ jīn tiān yù yuē le qiān zhèng xù qiān ， gāng gāng sǎo mǎ xiǎn shì yù yuē hào shī xiào le ， wǒ suǒ yǒu bàn lǐ cái liào dōu dài qí le 。','Chào chị, hôm nay em đặt hẹn gia hạn visa, vừa quét mã thì báo số hẹn hết hiệu lực rồi, mà em đã mang đủ hết giấy tờ cần thiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_02','V1016','小徐',2,'失效的话是没办法直接办的哦，系统规定过期预约号作废，只能重新线上抢号排队，我们窗口不能直接受理。','shī xiào de huà shì méi bàn fǎ zhí jiē bàn de ó ， xì tǒng guī dìng guò qī yù yuē hào zuò fèi ， zhǐ néng chóng xīn xiàn shàng qiǎng hào pái duì ， wǒ men chuāng kǒu bù néng zhí jiē shòu lǐ 。','Hết hiệu lực rồi thì không thể xử lý trực tiếp được đâu nhé, hệ thống quy định số hẹn quá hạn sẽ bị hủy, chỉ có thể đặt lại số mới trên mạng thôi, quầy chúng tôi không thể tiếp nhận trực tiếp được.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_03','V1016','阮明',3,'啊？可是我下周就要离校去参加学术会议，真的没时间重新预约排队，能不能通融一下，帮我走个加急？','a ？ kě shì wǒ xià zhōu jiù yào lí xiào qù cān jiā xué shù huì yì ， zhēn de méi shí jiān chóng xīn yù yuē pái duì ， néng bù néng tōng róng yī xià ， bāng wǒ zǒu gè jiā jí ？','Hả? Nhưng tuần sau em phải rời trường đi dự hội nghị học thuật rồi, thật sự không có thời gian đặt hẹn xếp hàng lại nữa, chị có thể linh động giúp em làm nhanh được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_04','V1016','小徐',4,'我理解你着急，但我们加急通道是有严格标准的，只针对紧急就医、亲属病危这种突发特殊情况，普通出行、参会都不算加急范畴。','wǒ lǐ jiě nǐ zháo jí ， dàn wǒ men jiā jí tōng dào shì yǒu yán gé biāo zhǔn de ， zhǐ zhēn duì jǐn jí jiù yī 、 qīn shǔ bìng wēi zhè zhǒng tū fā tè shū qíng kuàng ， pǔ tōng chū xíng 、 cān huì dōu bù suàn jiā jí fàn chóu 。','Tôi hiểu em đang gấp, nhưng kênh xử lý nhanh của chúng tôi có tiêu chuẩn nghiêm ngặt, chỉ áp dụng cho các trường hợp khẩn cấp như cấp cứu y tế, người thân nguy kịch, còn đi lại bình thường hay dự hội nghị đều không thuộc diện ưu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_05','V1016','阮明',5,'不是普通出行！是学校安排的国际学术会议，特别重要，错过的话会影响我的学业成绩，邀请函我都带来了，您看一下。','bú shì pǔ tōng chū xíng ！ shì xué xiào ān pái de guó jì xué shù huì yì ， tè bié zhòng yào ， cuò guò de huà huì yǐng xiǎng wǒ de xué yè chéng jì ， yāo qǐng hán wǒ dōu dài lái le ， nín kàn yī xià 。','Không phải đi lại bình thường đâu ạ! Đây là hội nghị học thuật quốc tế do trường sắp xếp, rất quan trọng, nếu lỡ mất sẽ ảnh hưởng đến kết quả học tập của em, em mang cả thư mời đến rồi, chị xem giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_06','V1016','小徐',6,'行，那我帮你问问主管，看能不能特殊报备，你先在这边稍等，别走开。','xíng ， nà wǒ bāng nǐ wèn wèn zhǔ guǎn ， kàn néng bù néng tè shū bào bèi ， nǐ xiān zài zhè biān shāo děng ， bié zǒu kāi 。','Được rồi, để tôi hỏi giúp em quản lý xem có thể báo cáo trường hợp đặc biệt không, em cứ đợi ở đây một lát, đừng đi đâu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_07','V1016','阮明',7,'麻烦您多帮我说说情！我真的提前准备了很久，没想到预约号会突然失效，实在耽误不起时间。','má fán nín duō bāng wǒ shuō shuō qíng ！ wǒ zhēn de tí qián zhǔn bèi le hěn jiǔ ， méi xiǎng dào yù yuē hào huì tū rán shī xiào ， shí zài dān wù bù qǐ shí jiān 。','Phiền chị nói giúp em nhiều nhé! Em thật sự đã chuẩn bị từ lâu rồi, không ngờ số hẹn lại đột nhiên hết hiệu lực, thực sự không thể chậm trễ thêm được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_08','V1016','小徐',8,'我刚问过主管了，还是不行。不符合加急规定，系统录入不了信息，今天无论如何都办不了。','wǒ gāng wèn guò zhǔ guǎn le ， hái shì bù xíng 。 bù fú hé jiā jí guī dìng ， xì tǒng lù rù bù liǎo xìn xī ， jīn tiān wú lùn rú hé dōu bàn bù liǎo 。','Tôi vừa hỏi quản lý rồi, vẫn không được. Không đúng quy định ưu tiên, hệ thống không nhập được thông tin, hôm nay dù thế nào cũng không xử lý được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_09','V1016','阮明',9,'这样啊……那现在还有别的办法吗？','zhè yàng a …… nà xiàn zài hái yǒu bié de bàn fǎ ma ？','Vậy à... vậy giờ còn cách nào khác không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_10','V1016','小徐',10,'没有别的捷径，只能明天早点自己抢新的预约号，按正常流程办理。','méi yǒu bié de jié jìng ， zhǐ néng míng tiān zǎo diǎn zì jǐ qiǎng xīn de yù yuē hào ， àn zhèng cháng liú chéng bàn lǐ 。','Không còn cách nào khác đâu, chỉ có thể ngày mai dậy sớm tự đặt số hẹn mới, làm theo quy trình bình thường thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1017','SKC1','诈骗来电谎称家人重病要求汇款，冷静核实后联系学院反诈老师',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1017','SIT1017','P1','suon_se','ban_chinh_thuc',NULL,'国内高校会定期开展留学生反诈宣讲，遭遇疑似诈骗可直接联系国际学院辅导员，同步上报公安反诈平台。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_01','V1017','阮明',1,'郑老师，我刚刚接到一个特别奇怪的陌生电话，心里特别慌。','zhèng lǎo shī ， wǒ gāng gāng jiē dào yí gè tè bié qí guài de mò shēng diàn huà ， xīn lǐ tè bié huāng 。','Cô Trịnh ơi, em vừa nhận được một cuộc điện thoại lạ rất kỳ lạ, trong lòng hoảng quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_02','V1017','郑老师',2,'别急，慢慢说，怎么了？','bié jí ， màn màn shuō ， zěn me le ？','Đừng vội, từ từ nói xem, chuyện gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_03','V1017','阮明',3,'对方说我妈妈突发重病住院，情况很危急，让我马上转账医药费过去，不然就来不及了。','duì fāng shuō wǒ mā mā tū fā zhòng bìng zhù yuàn ， qíng kuàng hěn wēi jí ， ràng wǒ mǎ shàng zhuǎn zhàng yī yào fèi guò qù ， bù rán jiù lái bù jí le 。','Đối phương nói mẹ em đột nhiên bị bệnh nặng phải nhập viện, tình hình rất nguy cấp, bảo em chuyển tiền viện phí ngay không thì không kịp nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_04','V1017','郑老师',4,'千万别转钱！第一时间联系家里人核实了吗？打电话或者视频都可以。','qiān wàn bié zhuǎn qián ！ dì yī shí jiān lián xì jiā lǐ rén hé shí le ma ？ dǎ diàn huà huò zhě shì pín dōu kě yǐ 。','Tuyệt đối đừng chuyển tiền! Em đã liên lạc với người nhà để xác minh ngay chưa? Gọi điện hay gọi video đều được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_05','V1017','阮明',5,'我当时差点就信了，赶紧挂了电话打视频给我妈妈，她好好的，身体一点问题都没有，完全是骗人的！','wǒ dāng shí chà diǎn jiù xìn le ， gǎn jǐn guà le diàn huà dǎ shì pín gěi wǒ mā mā ， tā hǎo hǎo de ， shēn tǐ yì diǎn wèn tí dōu méi yǒu ， wán quán shì piàn rén de ！','Lúc đó em suýt tin luôn, em vội cúp máy rồi gọi video cho mẹ, mẹ em vẫn khỏe re, chẳng có vấn đề gì cả, đúng là lừa đảo!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_06','V1017','郑老师',6,'那就好，这是典型的跨境亲属诈骗，专门针对海外、外籍留学生，是很常见的诈骗手段。','nà jiù hǎo ， zhè shì diǎn xíng de kuà jìng qīn shǔ zhà piàn ， zhuān mén zhēn duì hǎi wài 、 wài jí liú xué shēng ， shì hěn cháng jiàn de zhà piàn shǒu duàn 。','Vậy thì tốt rồi, đây là kiểu lừa đảo người thân xuyên biên giới điển hình, chuyên nhắm vào du học sinh nước ngoài, là chiêu lừa rất phổ biến.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_07','V1017','阮明',7,'太吓人了！骗子居然知道我的名字、还有我家里的大致情况，信息特别准，我一开始完全没怀疑。','tài xià rén le ！ piàn zi jū rán zhī dào wǒ de míng zì 、 hái yǒu wǒ jiā lǐ de dà zhì qíng kuàng ， xìn xī tè bié zhǔn ， wǒ yī kāi shǐ wán quán méi huái yí 。','Sợ thật đấy! Kẻ lừa đảo còn biết tên em, biết cả sơ sơ tình hình gia đình em, thông tin chuẩn xác đến mức em lúc đầu chẳng nghi ngờ gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_08','V1017','郑老师',8,'正常的，这类骗子都会提前搜集学生公开信息。你把刚才的来电号码发给我。','zhèng cháng de ， zhè lèi piàn zi dōu huì tí qián sōu jí xué shēng gōng kāi xìn xī 。 nǐ bǎ gāng cái de lái diàn hào mǎ fā gěi wǒ 。','Bình thường thôi, loại lừa đảo này đều thu thập trước thông tin công khai của sinh viên. Em gửi số điện thoại vừa gọi đến cho cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_09','V1017','阮明',9,'好，我马上截图转发给您。','hǎo ， wǒ mǎ shàng jié tú zhuǎn fā gěi nín 。','Dạ, em chụp màn hình gửi cho cô ngay đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_10','V1017','郑老师',10,'我会统一上报给反诈中心，录入拦截名单，避免更多人被骗。你记住，以后但凡有人催你立刻转账、说家里出事的，一律先核实，绝不轻信。','wǒ huì tǒng yī shàng bào gěi fǎn zhà zhōng xīn ， lù rù lán jié míng dān ， bì miǎn gèng duō rén bèi piàn 。 nǐ jì zhù ， yǐ hòu dàn fán yǒu rén cuī nǐ lì kè zhuǎn zhàng 、 shuō jiā lǐ chū shì de ， yī lǜ xiān hé shí ， jué bù qīng xìn 。','Cô sẽ báo cáo lên trung tâm chống lừa đảo, đưa vào danh sách chặn, để tránh nhiều người khác bị lừa. Em nhớ nhé, sau này hễ ai giục em chuyển tiền gấp, nói nhà có chuyện, thì phải xác minh trước, tuyệt đối đừng tin ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_11','V1017','阮明',11,'我记住了！以后遇到这种事，我第一时间找您咨询，绝对不冲动转账。','wǒ jì zhù le ！ yǐ hòu yù dào zhè zhǒng shì ， wǒ dì yī shí jiān zhǎo nín zī xún ， jué duì bù chōng dòng zhuǎn zhàng 。','Em nhớ rồi ạ! Sau này gặp chuyện như vậy, em sẽ hỏi cô ngay, tuyệt đối không chuyển tiền theo cảm tính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1018','SKC1','校园学习账号被盗用登录，联系学校信息中心紧急冻结账号',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1018','SIT1018','P1','twist','ban_chinh_thuc',NULL,'国内高校校园账号绑定学籍、选课、图书馆借阅权限，被盗用可能泄露个人学籍信息，必须线下核验身份永久冻结。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_01','V1018','阮明',1,'您好，麻烦帮我查一下我的校园学习账号，好像被盗用了！系统提示凌晨在外地登录，不是我本人操作。','nín hǎo ， má fán bāng wǒ chá yī xià wǒ de xiào yuán xué xí zhàng hào ， hǎo xiàng bèi dào yòng le ！ xì tǒng tí shì líng chén zài wài dì dēng lù ， bú shì wǒ běn rén cāo zuò 。','Chào anh, phiền anh kiểm tra giúp em tài khoản học tập của trường, hình như bị đánh cắp rồi! Hệ thống báo có người đăng nhập lúc nửa đêm ở nơi khác, không phải em thao tác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_02','V1018','小高',2,'没问题，报一下你的学号和实名姓名，我先调取登录记录核对情况。','méi wèn tí ， bào yī xià nǐ de xué hào hé shí míng xìng míng ， wǒ xiān diào qǔ dēng lù jì lù hé duì qíng kuàng 。','Không vấn đề gì, em cho anh xin mã số sinh viên và họ tên thật, anh kiểm tra lịch sử đăng nhập trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_03','V1018','阮明',3,'学号20230418，名字是阮明。我现在特别担心，账号里有我的选课信息和个人资料，怕被别人乱用。','xué hào 20230418， míng zì shì ruǎn míng 。 wǒ xiàn zài tè bié dān xīn ， zhàng hào lǐ yǒu wǒ de xuǎn kè xìn xī hé gè rén zī liào ， pà bèi bié rén luàn yòng 。','Mã số sinh viên là 20230418, tên là Nguyễn Minh. Em đang lo lắm, trong tài khoản có thông tin đăng ký môn học và tài liệu cá nhân của em, sợ bị người khác lợi dụng lung tung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_04','V1018','小高',4,'查到了，确实有一条异地陌生登录记录。想要彻底锁定账号、杜绝被盗用，需要你本人带学生证来机房线下办理手续。','chá dào le ， què shí yǒu yī tiáo yì dì mò shēng dēng lù jì lù 。 xiǎng yào chè dǐ suǒ dìng zhàng hào 、 dù jué bèi dào yòng ， xū yào nǐ běn rén dài xué shēng zhèng lái jī fáng xiàn xià bàn lǐ shǒu xù 。','Tìm ra rồi, đúng là có một lượt đăng nhập lạ từ nơi khác. Muốn khóa hẳn tài khoản, ngăn chặn triệt để việc bị chiếm dụng, em cần mang thẻ sinh viên đến phòng máy làm thủ tục trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'啊？可是我现在正在教学楼上课，根本走不开，能不能先线上临时冻结一下？我下课马上过去办正式手续。','a ？ kě shì wǒ xiàn zài zhèng zài jiào xué lóu shàng kè ， gēn běn zǒu bù kāi ， néng bù néng xiān xiàn shàng lín shí dòng jié yī xià ？ wǒ xià kè mǎ shàng guò qù bàn zhèng shì shǒu xù 。','Hả? Nhưng giờ em đang học trên giảng đường, không thể rời đi được, anh có thể khóa tạm thời online trước được không ạ? Tan học em chạy qua làm thủ tục chính thức ngay.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'线上只能做临时限制，有效期只有两个小时，时间一到就会自动解除，没办法永久锁定。','xiàn shàng zhǐ néng zuò lín shí xiàn zhì ， yǒu xiào qī zhǐ yǒu liǎng gè xiǎo shí ， shí jiān yī dào jiù huì zì dòng jiě chú ， méi bàn fǎ yǒng jiǔ suǒ dìng 。','Online chỉ có thể giới hạn tạm thời thôi, thời hạn chỉ có hai tiếng, hết giờ là tự động mở lại, không thể khóa vĩnh viễn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时……应该够我下课赶过去了。麻烦您现在先帮我锁上，别让别人继续登录操作。','liǎng xiǎo shí …… yīng gāi gòu wǒ xià kè gǎn guò qù le 。 má fán nín xiàn zài xiān bāng wǒ suǒ shàng ， bié ràng bié rén jì xù dēng lù cāo zuò 。','Hai tiếng... chắc đủ để em tan học chạy qua kịp. Phiền anh khóa tạm giúp em ngay bây giờ, đừng để người khác tiếp tục đăng nhập thao tác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_08','V1018','小高',8,'已经帮你临时限制登录了。记住，下课第一时间带学生证过来，重置密码、完善安全验证，不然超时解锁还是有风险。','yǐ jīng bāng nǐ lín shí xiàn zhì dēng lù le 。 jì zhù ， xià kè dì yī shí jiān dài xué shēng zhèng guò lái ， zhòng zhì mì mǎ 、 wán shàn ān quán yàn zhèng ， bù rán chāo shí jiě suǒ hái shì yǒu fēng xiǎn 。','Anh khóa tạm thời đăng nhập cho em rồi đó. Nhớ nhé, tan học là mang thẻ sinh viên qua ngay, đổi mật khẩu, hoàn thiện xác thực bảo mật, không thì hết hạn khóa lại rủi ro đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_09','V1018','阮明',9,'好的好的，我一下课就过去，太感谢您了！','hǎo de hǎo de ， wǒ yī xià kè jiù guò qù ， tài gǎn xiè nín le ！','Dạ vâng, em tan học là qua liền, cảm ơn anh nhiều lắm ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1019','SKC1','社交平台私人照片被恶意转发骚扰，到学校保卫处寻求介入处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1019','SIT1019','P1','suon_se','chinh_thuc',NULL,'个人肖像被恶意转发骚扰属于侵权行为，学校保卫处可出具证明协助学生向社交平台申请删除内容、封禁侵权账号。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_01','V1019','阮明',1,'李干事您好，我想来报备一个情况，我最近一直被人网络骚扰。','lǐ gàn shì nín hǎo ， wǒ xiǎng lái bào bèi yí gè qíng kuàng ， wǒ zuì jìn yì zhí bèi rén wǎng luò sāo rǎo 。','Chào anh Lý, em muốn đến báo cáo một việc, gần đây em liên tục bị quấy rối trên mạng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_02','V1019','李干事',2,'你具体说一下是什么情况，怎么被骚扰的？','nǐ jù tǐ shuō yī xià shì shén me qíng kuàng ， zěn me bèi sāo rǎo de ？','Em nói cụ thể xem là chuyện gì, bị quấy rối như thế nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_03','V1019','阮明',3,'有人私自保存了我的私人生活照片，转发到社交平台，还一直发私信骚扰我，严重影响我的生活了。','yǒu rén sī zì bǎo cún le wǒ de sī rén shēng huó zhào piàn ， zhuǎn fā dào shè jiāo píng tái ， hái yì zhí fā sī xìn sāo rǎo wǒ ， yán zhòng yǐng xiǎng wǒ de shēng huó le 。','Có người tự ý lưu lại ảnh sinh hoạt riêng tư của em, đăng lên mạng xã hội, còn liên tục nhắn tin riêng quấy rối em, ảnh hưởng nghiêm trọng đến cuộc sống của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_04','V1019','李干事',4,'所有的骚扰私信、对方转发你照片的页面，全部都截图保存了吗？一定要保留完整记录，这是取证关键。','suǒ yǒu de sāo rǎo sī xìn 、 duì fāng zhuǎn fā nǐ zhào piān de yè miàn ， quán bù dōu jié tú bǎo cún le ma ？ yí dìng yào bǎo liú wán zhěng jì lù ， zhè shì qǔ zhèng guān jiàn 。','Tất cả tin nhắn quấy rối, trang đăng ảnh của em mà đối phương chia sẻ, em đã chụp màn hình lưu lại hết chưa? Nhất định phải giữ đầy đủ bằng chứng, đây là điều then chốt để xác minh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_05','V1019','阮明',5,'都保存好了，一张都没漏。而且对方是校外人员，我完全不知道他是谁，查不到任何身份信息。','dōu bǎo cún hǎo le ， yī zhāng dōu méi lòu 。 ér qiě duì fāng shì xiào wài rén yuán ， wǒ wán quán bù zhī dào tā shì shuí ， chá bú dào rèn hé shēn fèn xìn xī 。','Em lưu hết rồi, không sót cái nào. Với lại đối phương là người ngoài trường, em hoàn toàn không biết là ai, không tra ra được thông tin danh tính gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_06','V1019','李干事',6,'没关系，这个我们可以处理。学校可以出具官方证明，协助你联系社交平台客服，调取对方的注册实名信息。','méi guān xì ， zhè ge wǒ men kě yǐ chǔ lǐ 。 xué xiào kě yǐ chū jù guān fāng zhèng míng ， xié zhù nǐ lián xì shè jiāo píng tái kè fú ， diào qǔ duì fāng de zhù cè shí míng xìn xī 。','Không sao, việc này chúng tôi có thể xử lý. Nhà trường có thể xuất trình giấy xác nhận chính thức, hỗ trợ em liên hệ bộ phận chăm sóc khách hàng của nền tảng mạng xã hội, để lấy thông tin đăng ký thực của đối phương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_07','V1019','阮明',7,'太好了！对方每天都在发消息，我上课、休息都被打扰，真的特别困扰，希望能尽快制止他。','tài hǎo le ！ duì fāng měi tiān dōu zài fā xiāo xī ， wǒ shàng kè 、 xiū xī dōu bèi dǎ rǎo ， zhēn de tè bié kùn rǎo ， xī wàng néng jǐn kuài zhì zhǐ tā 。','Tốt quá ạ! Đối phương ngày nào cũng nhắn tin, em học bài, nghỉ ngơi đều bị quấy rầy, thật sự rất phiền toái, mong sớm ngăn chặn được người đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_08','V1019','李干事',8,'我现在先登记你的个人信息和整件事的经过，今天内就发函给平台，要求对方下架所有你的私人照片，停止骚扰行为。','wǒ xiàn zài xiān dēng jì nǐ de gè rén xìn xī hé zhěng jiàn shì de jīng guò ， jīn tiān nèi jiù fā hán gěi píng tái ， yāo qiú duì fāng xià jià suǒ yǒu nǐ de sī rén zhào piān ， tíng zhǐ sāo rǎo xíng wéi 。','Bây giờ tôi sẽ ghi nhận thông tin cá nhân của em và toàn bộ diễn biến sự việc, trong hôm nay sẽ gửi công văn cho nền tảng, yêu cầu gỡ bỏ toàn bộ ảnh riêng tư của em, chấm dứt hành vi quấy rối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_09','V1019','阮明',9,'真的太感谢您了，我之前都不知道学校保卫处还能处理这种网络侵权的问题。','zhēn de tài gǎn xiè nín le ， wǒ zhī qián dōu bù zhī dào xué xiào bǎo wèi chù hái néng chǔ lǐ zhè zhǒng wǎng luò qīn quán de wèn tí 。','Em thật sự rất cảm ơn anh, trước giờ em không biết phòng bảo vệ nhà trường còn có thể xử lý cả vấn đề xâm phạm trên mạng như vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1019_10','V1019','李干事',10,'这是我们的工作范畴，校内师生遭遇网络骚扰、肖像侵权，都可以来报备，我们会全程协助维权。','zhè shì wǒ men de gōng zuò fàn chóu ， xiào nèi shī shēng zāo yù wǎng luò sāo rǎo 、 xiào xiàng qīn quán ， dōu kě yǐ lái bào bèi ， wǒ men huì quán chéng xié zhù wéi quán 。','Đây là phạm vi công việc của chúng tôi, sinh viên và giảng viên trong trường gặp phải quấy rối trên mạng, xâm phạm hình ảnh, đều có thể đến báo cáo, chúng tôi sẽ hỗ trợ bảo vệ quyền lợi trọn vẹn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1020','SKC1','社团活动现场两名同学激烈争吵，上前劝解并通知社团负责人',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1020','SIT1020','P1','twist','tuy_y',NULL,'国内校园社团公共场合发生争吵会影响社团评优，负责人一般会分开双方私下调解，避免当众激化矛盾。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_01','V1020','阮明',1,'小宇！你快过来活动大厅！出事了！','xiǎo yǔ ！ nǐ kuài guò lái huó dòng dà tīng ！ chū shì le ！','Tiểu Vũ ơi! Cậu chạy qua sảnh hoạt động ngay đi! Có chuyện rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_02','V1020','小宇',2,'怎么了？我刚在后台整理物资，外面乱糟糟的。','zěn me le ？ wǒ gāng zài hòu tái zhěng lǐ wù zī ， wài miàn luàn zāo zāo de 。','Sao thế? Tớ đang sắp xếp đồ ở hậu trường, ngoài kia loạn hết cả lên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_03','V1020','阮明',3,'策划部两个同学吵得特别凶，声音特别大，谁也不肯让谁，好多新生都围过来看热闹了。','cè huà bù liǎng gè tóng xué chǎo dé tè bié xiōng ， shēng yīn tè bié dà ， shuí yě bù kěn ràng shuí ， hǎo duō xīn shēng dōu wéi guò lái kàn rè nào le 。','Hai bạn bên ban tổ chức cãi nhau dữ lắm, to tiếng kinh khủng, chẳng ai chịu nhường ai, tân sinh viên xúm lại xem đông luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_04','V1020','小宇',4,'天呐，怎么当众吵架啊！这么多新人在，太影响社团形象了。到底因为什么？','tiān nà ， zěn me dāng zhòng chǎo jià a ！ zhè me duō xīn rén zài ， tài yǐng xiǎng shè tuán xíng xiàng le 。 dào dǐ yīn wèi shén me ？','Trời ơi, sao lại cãi nhau trước mặt mọi người thế! Đông tân sinh viên vậy còn gì hình ảnh câu lạc bộ nữa. Rốt cuộc là vì chuyện gì?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_05','V1020','阮明',5,'好像是对这次活动的预算分配意见不一样，两个人越吵越激动，根本劝不住。','hǎo xiàng shì duì zhè cì huó dòng de yù suàn fēn pèi yì jiàn bù yí yàng ， liǎng gè rén yuè chǎo yuè jī dòng ， gēn běn quàn bú zhù 。','Hình như là bất đồng về cách phân bổ ngân sách cho hoạt động lần này, hai người càng cãi càng nóng, khuyên thế nào cũng không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_06','V1020','小宇',6,'你先试着把他们俩分开，别让他们站在一起对峙，分别拉到两边冷静一下。','nǐ xiān shì zhe bǎ tā men liǎ fēn kāi ， bié ràng tā men zhàn zài yì qǐ duì zhì ， fēn bié lā dào liǎng biān lěng jìng yī xià 。','Cậu thử tách hai người ra trước đi, đừng để họ đứng đối mặt nhau, kéo mỗi người một bên cho bình tĩnh lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_07','V1020','阮明',7,'我试过了！劝了好半天，两个人情绪都特别上头，谁都不愿意听，根本冷静不下来。','wǒ shì guò le ！ quàn le hǎo bàn tiān ， liǎng gè rén qíng xù dōu tè bié shàng tou ， shéi dōu bù yuàn yì tīng ， gēn běn lěng jìng bù xià lái 。','Tớ thử rồi! Khuyên mãi mà cả hai đều đang nóng máu, chẳng ai chịu nghe, không tài nào bình tĩnh lại được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_08','V1020','小宇',8,'行，我马上过去亲自跟他们谈。你先帮忙疏散一下围观的同学，别让大家围着看，场面太尴尬了。','xíng ， wǒ mǎ shàng guò qù qīn zì gēn tā men tán 。 nǐ xiān bāng máng shū sàn yī xià wéi guān de tóng xué ， bié ràng dà jiā wéi zhe kàn ， chǎng miàn tài gān gà le 。','Được rồi, tớ chạy qua nói chuyện trực tiếp với họ ngay. Cậu giúp tớ giải tán đám đông đang xem đi, đừng để mọi người xúm vào xem nữa, ngại lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_09','V1020','阮明',9,'没问题，我来安抚新生，转移一下大家的注意力。','méi wèn tí ， wǒ lái ān fǔ xīn shēng ， zhuǎn yí yī xià dà jiā de zhù yì lì 。','Không vấn đề gì, để tớ trấn an mấy bạn tân sinh viên, hướng sự chú ý của mọi người đi chỗ khác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1020_10','V1020','小宇',10,'辛苦你了。社团有矛盾一定要第一时间告诉我，千万别任由矛盾闹大。','xīn kǔ nǐ le 。 shè tuán yǒu máo dùn yí dìng yào dì yī shí jiān gào sù wǒ ， qiān wàn bié rèn yóu máo dùn nào dà 。','Cậu vất vả rồi. Câu lạc bộ có mâu thuẫn gì phải báo tớ ngay, đừng để mâu thuẫn bùng lên to nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1021','SKC1','自习室同学突发癫痫，疏散人群、联系校医、维持现场秩序',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1021','SIT1021','P1','suon_se','ban_chinh_thuc',NULL,'国内校园普及癫痫急救基础常识，发病时禁止强行束缚患者肢体，保持通风、清理周边硬物是基础急救方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_01','V1021','阮明',1,'思琪学姐！快来这边，有个同学突然倒地抽搐了！','sī qí xué jiě ！ kuài lái zhè biān ， yǒu gè tóng xué tū rán dǎo dì chōu chù le ！','Chị Tư Kỳ ơi! Qua đây nhanh, có bạn đột nhiên ngã lăn ra co giật!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_02','V1021','思琪',2,'别慌！大家全部往后退，不要围挤，留出足够的通风空间！','bié huāng ！ dà jiā quán bù wǎng hòu tuì ， bú yào wéi jǐ ， liú chū zú gòu de tōng fēng kōng jiān ！','Đừng hoảng! Mọi người lùi lại hết đi, đừng chen lấn, để chỗ thoáng khí cho bạn ấy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_03','V1021','阮明',3,'我已经把他身边的桌椅都挪开了，防止他抽搐的时候磕碰受伤，现在要不要立刻打校医电话？','wǒ yǐ jīng bǎ tā shēn biān de zhuō yǐ dōu nuó kāi le ， fáng zhǐ tā chōu chù de shí hòu kē pèng shòu shāng ， xiàn zài yào bù yào lì kè dǎ xiào yī diàn huà ？','Em đã dọn hết bàn ghế xung quanh bạn ấy rồi, để tránh va đập lúc co giật, bây giờ có cần gọi ngay số điện thoại y tế trường không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_04','V1021','思琪',4,'我马上打应急电话！你找件外套或者书本，垫在他头下面，保护好头部。','wǒ mǎ shàng dǎ yìng jí diàn huà ！ nǐ zhǎo jiàn wài tào huò zhě shū běn ， diàn zài tā tóu xià miàn ， bǎo hù hǎo tóu bù 。','Chị gọi cấp cứu ngay đây! Em tìm cái áo khoác hay quyển sách nào đó, kê dưới đầu bạn ấy, để bảo vệ phần đầu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_05','V1021','阮明',5,'好！我马上弄！他现在完全没有意识，一直在不停抽搐。','hǎo ！ wǒ mǎ shàng nòng ！ tā xiàn zài wán quán méi yǒu yì shí ， yì zhí zài bù tíng chōu chù 。','Vâng! Em làm ngay! Bạn ấy giờ hoàn toàn không có ý thức, cứ co giật liên tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_06','V1021','思琪',6,'记住，千万不要伸手去按住他的手脚，也不要掐人中，强行束缚会造成二次损伤，静静等待校医来就行。','jì zhù ， qiān wàn bú yào shēn shǒu qù àn zhù tā de shǒu jiǎo ， yě bú yào qiā rén zhōng ， qiáng xíng shù fù huì zào chéng èr cì sǔn shāng ， jìng jìng děng dài xiào yī lái jiù xíng 。','Nhớ nhé, tuyệt đối đừng đưa tay giữ chặt tay chân bạn ấy, cũng đừng bấm nhân trung, ép giữ mạnh sẽ gây tổn thương thêm, cứ bình tĩnh chờ y tế trường đến là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_07','V1021','阮明',7,'我知道了！我会看好现场，拦住想上前触碰的同学，维持好秩序。','wǒ zhī dào le ！ wǒ huì kàn hǎo xiàn chǎng ， lán zhù xiǎng shàng qián chù pèng de tóng xué ， wéi chí hǎo zhì xù 。','Em biết rồi ạ! Em sẽ trông chừng hiện trường, ngăn các bạn định chạy lại chạm vào, giữ trật tự cho ổn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1021_08','V1021','思琪',8,'做得很好。自习室人多，一旦围观慌乱，很容易加重患者情况，还好你处理得很稳妥。','zuò dé hěn hǎo 。 zì xí shì rén duō ， yí dàn wéi guān huāng luàn ， hěn róng yì jiā zhòng huàn zhě qíng kuàng ， hái hǎo nǐ chǔ lǐ dé hěn wěn tuǒ 。','Em làm tốt lắm. Phòng tự học đông người, nếu để mọi người xúm lại hoảng loạn thì rất dễ làm tình trạng bệnh nhân nặng thêm, may mà em xử lý rất ổn thỏa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1022','SKC1','校外租房房东私自换锁不让进门，拨打社区民警协调房屋纠纷',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1022','SIT1022','P1','that_bai_nhe','chinh_thuc',NULL,'租房纠纷属于民事纠纷，民警仅负责现场调解，无权强制破门，双方无法达成一致需走法院民事诉讼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_01','V1022','阮明',1,'王警官您好，我想求助一下，我租的房子，房东私自把门锁换了，不让我进门。','wáng jǐng guān nín hǎo ， wǒ xiǎng qiú zhù yī xià ， wǒ zū de fáng zi ， fáng dōng sī zì bǎ mén suǒ huàn le ， bù ràng wǒ jìn mén 。','Chào anh công an, em muốn nhờ anh giúp đỡ, nhà em thuê bị chủ nhà tự ý đổi khóa cửa, không cho em vào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_02','V1022','王民警',2,'你先别急，出示一下你的租房合同和身份证件，说清楚房东换锁的具体原因。','nǐ xiān bié jí ， chū shì yī xià nǐ de zū fáng hé tóng hé shēn fèn zhèng jiàn ， shuō qīng chǔ fáng dōng huàn suǒ de jù tǐ yuán yīn 。','Em bình tĩnh đã, cho tôi xem hợp đồng thuê nhà và giấy tờ tùy thân của em, nói rõ lý do chủ nhà đổi khóa là gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_03','V1022','阮明',3,'我房租都是按时全额交的，从来没有拖欠！就是房东突然要涨房租，我没同意，他就直接换锁，不让我进屋了。','wǒ fáng zū dōu shì àn shí quán é jiāo de ， cóng lái méi yǒu tuō qiàn ！ jiù shì fáng dōng tū rán yào zhǎng fáng zū ， wǒ méi tóng yì ， tā jiù zhí jiē huàn suǒ ， bù ràng wǒ jìn wū le 。','Tiền thuê nhà em đều đóng đúng hạn, đủ số, chưa bao giờ nợ cả! Chỉ là chủ nhà đột nhiên đòi tăng tiền thuê, em không đồng ý, thế là ông ấy đổi khóa luôn, không cho em vào nhà nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_04','V1022','王民警',4,'我清楚情况了。房东在租客租期内私自换锁、扣押租客物品，属于违规行为，我现在立刻联系房东过来现场调解。','wǒ qīng chǔ qíng kuàng le 。 fáng dōng zài zū kè zū qī nèi sī zì huàn suǒ 、 kòu yā zū kè wù pǐn ， shǔ yú wéi guī xíng wéi ， wǒ xiàn zài lì kè lián xì fáng dōng guò lái xiàn chǎng tiáo jiě 。','Tôi hiểu tình hình rồi. Chủ nhà tự ý đổi khóa, giữ đồ đạc của người thuê trong thời hạn hợp đồng là hành vi vi phạm, tôi sẽ liên hệ chủ nhà đến hiện trường hòa giải ngay bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_05','V1022','阮明',5,'太谢谢您了！我的笔记本电脑、还有留学生居留卡全都在房间里，都是重要物品，而且我今晚没地方住，能不能先让我进屋拿东西？','tài xiè xiè nín le ！ wǒ de bǐ jì běn diàn nǎo 、 hái yǒu liú xué shēng jū liú kǎ quán dōu zài fáng jiān lǐ ， dōu shì zhòng yào wù pǐn ， ér qiě wǒ jīn wǎn méi dì fāng zhù ， néng bù néng xiān ràng wǒ jìn wū ná dōng xī ？','Em cảm ơn anh nhiều lắm! Laptop của em, với cả thẻ cư trú du học sinh đều để trong phòng, toàn đồ quan trọng cả, mà tối nay em cũng không có chỗ ở, anh có thể cho em vào lấy đồ trước được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_06','V1022','王民警',6,'这个不行，民事租房纠纷我们没有强制破门的权限，必须双方当事人到场才能调解。房东现在在外面，大概半小时才能赶过来。','zhè ge bù xíng ， mín shì zū fáng jiū fēn wǒ men méi yǒu qiáng zhì pò mén de quán xiàn ， bì xū shuāng fāng dāng shì rén dào chǎng cái néng tiáo jiě 。 fáng dōng xiàn zài zài wài miàn ， dà gài bàn xiǎo shí cái néng gǎn guò lái 。','Cái này thì không được, tranh chấp thuê nhà dân sự chúng tôi không có quyền phá cửa cưỡng chế, phải có mặt cả hai bên mới hòa giải được. Chủ nhà giờ đang ở ngoài, khoảng nửa tiếng nữa mới tới được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_07','V1022','阮明',7,'半小时啊……那我今晚只能临时住酒店了。关键证件都在屋里，我心里特别不踏实。','bàn xiǎo shí a …… nà wǒ jīn wǎn zhǐ néng lín shí zhù jiǔ diàn le 。 guān jiàn zhèng jiàn dōu zài wū lǐ ， wǒ xīn lǐ tè bié bù tà shí 。','Nửa tiếng à... vậy tối nay em chỉ đành ở tạm khách sạn thôi. Giấy tờ quan trọng đều ở trong phòng, em thấy bất an quá.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1022_08','V1022','王民警',8,'你放心，我会全程在场等候调解，房东到了之后，我第一时间协调你进屋取出重要证件和随身物品。','nǐ fàng xīn ， wǒ huì quán chéng zài chǎng děng hòu tiáo jiě ， fáng dōng dào le zhī hòu ， wǒ dì yī shí jiān xié tiáo nǐ jìn wū qǔ chū zhòng yào zhèng jiàn hé suí shēn wù pǐn 。','Em yên tâm, tôi sẽ có mặt chờ hòa giải đến cùng, chủ nhà đến rồi tôi sẽ thu xếp để em vào lấy giấy tờ quan trọng và đồ dùng cá nhân ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1023','SKC1','校医院无法处理急症，拨打120同时同步告知国际学院辅导员',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1023','SIT1023','P1','suon_se','ban_chinh_thuc',NULL,'国内高校校医院仅处理轻症，重症统一转送综合医院，留学生可凭留学生医保报销部分急诊费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_01','V1023','阮明',1,'李导，跟您说个紧急情况，我现在在校医院，身体特别不舒服。','lǐ dǎo ， gēn nín shuō gè jǐn jí qíng kuàng ， wǒ xiàn zài zài xiào yī yuàn ， shēn tǐ tè bié bù shū fú 。','Thầy Lý ơi, em báo thầy một việc gấp, em đang ở bệnh viện trường, người khó chịu lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_02','V1023','李辅导员',2,'怎么了？是哪里不舒服，严重吗？','zěn me le ？ shì nǎ lǐ bù shū fú ， yán zhòng ma ？','Sao vậy? Chỗ nào khó chịu, có nghiêm trọng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_03','V1023','阮明',3,'医生说我是急性肠胃炎，伴随严重脱水，校医院的设备处理不了，已经帮我打了120，要送去综合医院急诊。','yī shēng shuō wǒ shì jí xìng cháng wèi yán ， bàn suí yán zhòng tuō shuǐ ， xiào yī yuàn de shè bèi chǔ lǐ bù liǎo ， yǐ jīng bāng wǒ dǎ le 120， yào sòng qù zōng hé yī yuàn jí zhěn 。','Bác sĩ nói em bị viêm dạ dày ruột cấp, kèm mất nước nặng, thiết bị của bệnh viện trường không xử lý được, đã gọi 120 cho em rồi, phải chuyển đến bệnh viện tổng hợp cấp cứu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_04','V1023','李辅导员',4,'明白了，救护车大概多久能到？你身边现在有人陪着吗？','míng bái le ， jiù hù chē dà gài duō jiǔ néng dào ？ nǐ shēn biān xiàn zài yǒu rén péi zhe ma ？','Thầy hiểu rồi, xe cấp cứu khoảng bao lâu nữa thì đến? Giờ bên cạnh em có ai không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_05','V1023','阮明',5,'大概十分钟就到学校门口，我一个人在这边，居留卡、学生证都带在身上了。','dà gài shí fēn zhōng jiù dào xué xiào mén kǒu ， wǒ yí gè rén zài zhè biān ， jū liú kǎ 、 xué shēng zhèng dōu dài zài shēn shàng le 。','Khoảng mười phút nữa là đến cổng trường, em đang ở đây một mình, thẻ cư trú, thẻ sinh viên em đều mang theo người cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_06','V1023','李辅导员',6,'好，我先登记你的就诊信息，等下会提前跟对接医院说明你的留学生身份，方便你就诊。','hǎo ， wǒ xiān dēng jì nǐ de jiù zhěn xìn xī ， děng xià huì tí qián gēn duì jiē yī yuàn shuō míng nǐ de liú xué shēng shēn fèn ， fāng biàn nǐ jiù zhěn 。','Được, thầy ghi nhận thông tin khám bệnh của em trước, lát nữa thầy sẽ báo trước với bệnh viện tiếp nhận về việc em là du học sinh, để thuận tiện cho em khám bệnh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_07','V1023','阮明',7,'辛苦您了！我对这边就医缴费、报销的流程一点都不熟悉，后面还要麻烦您指导我。','xīn kǔ nín le ！ wǒ duì zhè biān jiù yī jiǎo fèi 、 bào xiāo de liú chéng yì diǎn dōu bù shú xī ， hòu miàn hái yào má fán nín zhǐ dǎo wǒ 。','Thầy vất vả rồi ạ! Em chưa quen quy trình đóng viện phí, thanh toán bảo hiểm ở đây chút nào, sau này còn phải nhờ thầy hướng dẫn thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1023_08','V1023','李辅导员',8,'别担心，你安心看病就行。我处理完手头的工作就赶去医院，后续留学生医保报销的材料和流程，我稍后全部发给你。','bié dān xīn ， nǐ ān xīn kàn bìng jiù xíng 。 wǒ chǔ lǐ wán shǒu tóu de gōng zuò jiù gǎn qù yī yuàn ， hòu xù liú xué shēng yī bǎo bào xiāo de cái liào hé liú chéng ， wǒ shāo hòu quán bù fā gěi nǐ 。','Đừng lo, em cứ yên tâm khám bệnh. Thầy giải quyết xong việc đang làm là qua bệnh viện ngay, sau đó tài liệu và quy trình thanh toán bảo hiểm y tế du học sinh thầy sẽ gửi hết cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1024','SKC1','异地就医刷卡银行卡被风控冻结，紧急致电银行客服解锁',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1024','SIT1024','P1','twist','chinh_thuc',NULL,'国内银行卡异地大额消费易触发风控冻结，线上临时解锁额度有限，大额资金解冻必须线下网点核验身份。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_01','V1024','阮明',1,'您好，我的银行卡被冻结了！我现在在外地医院看病缴费，刷卡提示账户风控锁定，急需解锁缴费。','nín hǎo ， wǒ de yín háng kǎ bèi dòng jié le ！ wǒ xiàn zài zài wài dì yī yuàn kàn bìng jiǎo fèi ， shuā kǎ tí shì zhàng hù fēng kòng suǒ dìng ， jí xū jiě suǒ jiǎo fèi 。','Alo, thẻ ngân hàng của tôi bị khóa rồi! Tôi đang ở bệnh viện tại một tỉnh khác để đóng viện phí, quẹt thẻ thì báo tài khoản bị kiểm soát rủi ro, tôi cần mở khóa gấp để thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_02','V1024','客服',2,'您好，麻烦您提供完整银行卡号、手机预留号，以及您开户证件的后四位，我先核验身份。','nín hǎo ， má fán nín tí gōng wán zhěng yín háng kǎ hào 、 shǒu jī yù liú hào ， yǐ jí nín kāi hù zhèng jiàn de hòu sì wèi ， wǒ xiān hé yàn shēn fèn 。','Chào anh, phiền anh cung cấp đầy đủ số thẻ ngân hàng, số điện thoại đăng ký, và 4 số cuối của giấy tờ mở tài khoản, để tôi xác minh danh tính trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_03','V1024','阮明',3,'卡号6217开头，预留手机号138XXXX2741，证件后四位3152。我现在等着付医药费，真的特别着急。','kǎ hào 6217 kāi tóu ， yù liú shǒu jī hào 138XXXX2741， zhèng jiàn hòu sì wèi 3152。 wǒ xiàn zài děng zhe fù yī yào fèi ， zhēn de tè bié zháo jí 。','Số thẻ bắt đầu bằng 6217, số điện thoại đăng ký là 138XXXX2741, 4 số cuối giấy tờ là 3152. Tôi đang chờ đóng viện phí, thật sự rất gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_04','V1024','客服',4,'核验成功。系统检测到您异地大额消费，为了保护账户安全，自动触发了风控冻结。可以线上临时解锁，但有每日支付限额。','hé yàn chéng gōng 。 xì tǒng jiǎn cè dào nín yì dì dà é xiāo fèi ， wèi le bǎo hù zhàng hù ān quán ， zì dòng chù fā le fēng kòng dòng jié 。 kě yǐ xiàn shàng lín shí jiě suǒ ， dàn yǒu měi rì zhī fù xiàn é 。','Xác minh thành công. Hệ thống phát hiện anh có giao dịch lớn ở nơi khác, để bảo vệ an toàn tài khoản nên đã tự động kích hoạt khóa kiểm soát rủi ro. Có thể mở khóa tạm thời online, nhưng sẽ có hạn mức thanh toán trong ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_05','V1024','阮明',5,'临时限额是多少？我这次医药费要两千多。','lín shí xiàn é shì duō shǎo ？ wǒ zhè cì yī yào fèi yào liǎng qiān duō 。','Hạn mức tạm thời là bao nhiêu vậy? Lần này viện phí của tôi hơn hai nghìn tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_06','V1024','客服',6,'本次线上临时解锁单日限额只有一千元，不足以支付你的诊疗费用。','běn cì xiàn shàng lín shí jiě suǒ dān rì xiàn é zhǐ yǒu yī qiān yuán ， bù zú yǐ zhī fù nǐ de zhěn liáo fèi yòng 。','Hạn mức mở khóa tạm thời online lần này chỉ có một nghìn tệ mỗi ngày thôi, không đủ để thanh toán chi phí khám chữa bệnh của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_07','V1024','阮明',7,'那怎么办啊！我人在医院，根本没办法离开，有没有别的办法临时提高一下额度？哪怕暂时解开这次交易也行。','nà zěn me bàn a ！ wǒ rén zài yī yuàn ， gēn běn méi bàn fǎ lí kāi ， yǒu méi yǒu bié de bàn fǎ lín shí tí gāo yī xià é dù ？ nǎ pà zàn shí jiě kāi zhè cì jiāo yì yě xíng 。','Vậy phải làm sao đây! Tôi đang ở bệnh viện, không thể nào rời đi được, có cách nào khác để nâng tạm hạn mức lên không? Hay tạm thời mở riêng cho giao dịch lần này cũng được.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_08','V1024','客服',8,'非常抱歉，银行风控系统规则无法线上更改，大额解冻、解除限额，必须本人携带有效证件到线下网点人工核验办理。','fēi cháng bào qiàn ， yín háng fēng kòng xì tǒng guī zé wú fǎ xiàn shàng gēng gǎi ， dà é jiě dòng 、 jiě chú xiàn é ， bì xū běn rén xié dài yǒu xiào zhèng jiàn dào xiàn xià wǎng diǎn rén gōng hé yàn bàn lǐ 。','Tôi rất xin lỗi, quy định hệ thống kiểm soát rủi ro của ngân hàng không thể thay đổi trực tuyến, việc mở khóa hạn mức lớn bắt buộc phải chính chủ mang giấy tờ hợp lệ đến quầy giao dịch trực tiếp để xác minh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1024_09','V1024','阮明',9,'这样啊……那我现在根本走不开，只能换别的银行卡缴费了。','zhè yàng a …… nà wǒ xiàn zài gēn běn zǒu bù kāi ， zhǐ néng huàn bié de yín háng kǎ jiǎo fèi le 。','Vậy à... giờ tôi không thể rời đi được, đành phải đổi sang thẻ ngân hàng khác để thanh toán vậy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1025','SKC1','长途火车大面积晚点错过签证预约，向出入境窗口说明延误申请补受理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1025','SIT1025','P1','that_bai_nhe','chinh_thuc',NULL,'政务大厅预约号严格分时段管控，交通延误仅可优先预约次日时段，无法直接当日插队办理业务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_01','V1025','阮明',1,'吴主管您好，麻烦您通融一下，我今天预约了签证续签，但是火车大面积晚点，彻底错过预约时间了。','wú zhǔ guǎn nín hǎo ， má fán nín tōng róng yī xià ， wǒ jīn tiān yù yuē le qiān zhèng xù qiān ， dàn shì huǒ chē dà miàn jī wǎn diǎn ， chè dǐ cuò guò yù yuē shí jiān le 。','Chào chú Ngô, phiền chú thông cảm giúp cháu, hôm nay cháu có hẹn gia hạn visa nhưng tàu hỏa bị trễ trên diện rộng nên cháu lỡ mất giờ hẹn rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_02','V1025','吴主管',2,'我先看一下你的延误证明和预约回执，把材料拿出来我核实一下。','wǒ xiān kàn yī xià nǐ de yán wù zhèng míng hé yù yuē huí zhí ， bǎ cái liào ná chū lái wǒ hé shí yī xià 。','Để tôi xem giấy chứng nhận trễ tàu và biên nhận đặt hẹn của em trước, em đưa giấy tờ ra để tôi kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_03','V1025','阮明',3,'这是铁路发的晚点短信，整整延误了三个小时，我赶到大厅的时候已经过号了。','zhè shì tiě lù fā de wǎn diǎn duǎn xìn ， zhěng zhěng yán wù le sān gè xiǎo shí ， wǒ gǎn dào dà tīng de shí hòu yǐ jīng guò hào le 。','Đây là tin nhắn báo trễ tàu của ngành đường sắt gửi ạ, trễ nguyên ba tiếng đồng hồ, lúc cháu chạy đến sảnh thì đã quá số thứ tự mất rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_04','V1025','吴主管',4,'我了解你的情况了。但我们系统的每日预约名额是固定的，当日过号，没有法定特殊事由，不能插队现场办理。','wǒ liǎo jiě nǐ de qíng kuàng le 。 dàn wǒ men xì tǒng de měi rì yù yuē míng é shì gù dìng de ， dāng rì guò hào ， méi yǒu fǎ dìng tè shū shì yóu ， bù néng chā duì xiàn chǎng bàn lǐ 。','Tôi hiểu tình huống của em rồi. Nhưng số lượng suất hẹn mỗi ngày trong hệ thống là cố định, hôm nay đã quá số, nếu không có lý do đặc biệt theo quy định thì không thể chen ngang xử lý tại chỗ được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_05','V1025','阮明',5,'我真的很急！下周我就要出境参加交换项目，要是今天办不了，只能重新预约，最少要等一周，我完全来不及赶流程。','wǒ zhēn de hěn jí ！ xià zhōu wǒ jiù yào chū jìng cān jiā jiāo huàn xiàng mù ， yào shì jīn tiān bàn bù liǎo ， zhǐ néng chóng xīn yù yuē ， zuì shǎo yào děng yī zhōu ， wǒ wán quán lái bù jí gǎn liú chéng 。','Cháu thật sự đang rất gấp ạ! Tuần sau cháu phải xuất cảnh tham gia chương trình trao đổi rồi, nếu hôm nay không xử lý được thì chỉ còn cách đặt lại hẹn, ít nhất phải chờ một tuần, cháu hoàn toàn không kịp làm thủ tục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_06','V1025','吴主管',6,'火车交通延误，不属于政务加急的法定事由，没办法破例当日受理。我最多帮你优先锁定明天最早的预约时段。','huǒ chē jiāo tōng yán wù ， bù shǔ yú zhèng wù jiā jí de fǎ dìng shì yóu ， méi bàn fǎ pò lì dāng rì shòu lǐ 。 wǒ zuì duō bāng nǐ yōu xiān suǒ dìng míng tiān zuì zǎo de yù yuē shí duàn 。','Tàu hỏa bị trễ không thuộc lý do khẩn cấp theo quy định của cơ quan hành chính, nên không thể phá lệ giải quyết ngay trong ngày được. Tôi chỉ có thể giúp em giữ trước khung giờ hẹn sớm nhất của ngày mai thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_07','V1025','阮明',7,'那太好了！明天最早是几点？我明天一定提前很久到，绝对不会再迟到、过号。','nà tài hǎo le ！ míng tiān zuì zǎo shì jǐ diǎn ？ wǒ míng tiān yí dìng tí qián hěn jiǔ dào ， jué duì bú huì zài chí dào 、 guò hào 。','Vậy thì tốt quá ạ! Sớm nhất ngày mai là mấy giờ vậy chú? Mai cháu chắc chắn sẽ đến thật sớm, tuyệt đối không để trễ hay quá số nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1025_08','V1025','吴主管',8,'早上八点是当日第一号，我给你做优先标记，明天直接凭证件取号办理即可，不用抢号排队。','zǎo shàng bā diǎn shì dāng rì dì yī hào ， wǒ gěi nǐ zuò yōu xiān biāo jì ， míng tiān zhí jiē píng zhèng jiàn qǔ hào bàn lǐ jí kě ， bù yòng qiǎng hào pái duì 。','Tám giờ sáng là số đầu tiên của ngày, tôi sẽ đánh dấu ưu tiên cho em, mai em chỉ cần mang giấy tờ đến lấy số làm thủ tục luôn, không cần chen chúc xếp hàng lấy số nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1101','SVL2','向国际学院提交校外兼职用工备案申请，等待学校审批许可',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1101','SIT1101','P1','twist','ban_chinh_thuc',NULL,'国内高校对留学生校外兼职实行备案制度，企业人事公章是备案审核硬性材料，缺少则无法通过审批。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_01','V1101','阮明',1,'张老师您好，我想提交校外兼职备案表，麻烦您帮忙审核一下吧。','zhāng lǎo shī nín hǎo， wǒ xiǎng tí jiāo xiào wài jiān zhí bèi àn biǎo， má fán nín bāng máng shěn hé yī xià ba。','Chào cô Trương, em muốn nộp mẫu đăng ký làm thêm bên ngoài trường, phiền cô kiểm tra giúp em ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_02','V1101','张老师',2,'先把表格和企业用工证明给我，我看看材料齐不齐。','xiān bǎ biǎo gé hé qǐ yè yòng gōng zhèng míng gěi wǒ， wǒ kàn kàn cái liào qí bù qí。','Em đưa cô mẫu đơn với giấy xác nhận sử dụng lao động của công ty trước, để cô xem hồ sơ đã đủ chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_03','V1101','阮明',3,'表格我填好了，可公司那边只盖了业务章，没有人事专用章呢。','biǎo gé wǒ tián hǎo le， kě gōng sī nà biān zhǐ gài le yè wù zhāng， méi yǒu rén shì zhuān yòng zhāng ne。','Mẫu đơn em điền xong rồi, nhưng bên công ty chỉ đóng dấu nghiệp vụ thôi, không có dấu nhân sự riêng đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_04','V1101','张老师',4,'备案必须人事公章，业务章学校这边是不认可的哦。','bèi àn bì xū rén shì gōng zhāng， yè wù zhāng xué xiào zhè biān shì bù rèn kě de ó。','Đăng ký bắt buộc phải có con dấu nhân sự, dấu nghiệp vụ thì nhà trường không công nhận đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_05','V1101','阮明',5,'那我明天再去企业重新盖章，会不会耽误备案审批进度？','nà wǒ míng tiān zài qù qǐ yè chóng xīn gài zhāng， huì bú huì dān wù bèi àn shěn pī jìn dù？','Vậy để mai em quay lại công ty đóng dấu lại, như thế có làm chậm tiến độ xét duyệt đăng ký không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_06','V1101','张老师',6,'没事，你补齐公章后再来，审批一般三个工作日就能出结果。','méi shì， nǐ bǔ qí gōng zhāng hòu zài lái， shěn pī yì bān sān gè gōng zuò rì jiù néng chū jié guǒ。','Không sao đâu, em bổ sung đủ con dấu rồi quay lại là được, thường thì ba ngày làm việc là có kết quả xét duyệt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1101_07','V1101','阮明',7,'好嘞，辛苦老师啦，我明天一早就去公司补盖章。','hǎo lei， xīn kǔ lǎo shī la， wǒ míng tiān yī zǎo jiù qù gōng sī bǔ gài zhāng。','Dạ được ạ, cảm ơn cô nhiều nha, sáng mai em sẽ qua công ty đóng dấu bổ sung ngay.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1102','SVL2','携带企业实习证明前往出入境大厅办理居留许可实习加注',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1102','SIT1102','P1','suon_se','chinh_thuc',NULL,'外籍学生在中国实习、兼职必须完成居留许可实习加注，无证务工会被处罚甚至影响签证续签。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_01','V1102','阮明',1,'您好，我是外籍留学生，来办理实习加注，这是我的材料。','nín hǎo， wǒ shì wài jí liú xué shēng， lái bàn lǐ shí xí jiā zhù， zhè shì wǒ de cái liào。','Chào anh/chị, tôi là du học sinh nước ngoài, đến làm thủ tục ghi chú thực tập, đây là hồ sơ của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_02','V1102','小唐',2,'护照、实习协议、学校备案回执都带齐全了吗？','hù zhào、 shí xí xié yì、 xué xiào bèi àn huí zhí dōu dài qí quán le ma？','Anh đã mang đầy đủ hộ chiếu, thỏa thuận thực tập và phiếu xác nhận đăng ký của trường chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_03','V1102','阮明',3,'全部都准备好了，我下周就要正式到公司上岗啦。','quán bù dōu zhǔn bèi hǎo le， wǒ xià zhōu jiù yào zhèng shì dào gōng sī shàng gǎng la。','Tôi chuẩn bị đầy đủ hết rồi, tuần sau tôi sẽ chính thức đến công ty nhận việc.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_04','V1102','小唐',4,'材料没问题，采集完人像，五个工作日就能办好加注。','cái liào méi wèn tí， cǎi jí wán rén xiàng， wǔ gè gōng zuò rì jiù néng bàn hǎo jiā zhù。','Hồ sơ không có vấn đề gì, sau khi lấy ảnh khuôn mặt xong, năm ngày làm việc là hoàn tất ghi chú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_05','V1102','阮明',5,'办完加注之后，我就可以合法按照规定时长实习了对吧？','bàn wán jiā zhù zhī hòu， wǒ jiù kě yǐ hé fǎ àn zhào guī dìng shí cháng shí xí le duì ba？','Sau khi làm xong ghi chú, tôi có thể thực tập hợp pháp theo đúng thời hạn quy định phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_06','V1102','小唐',6,'没错，没有加注务工属于违规，千万不要提前上岗哦。','méi cuò， méi yǒu jiā zhù wù gōng shǔ yú wéi guī， qiān wàn bú yào tí qián shàng gǎng ó。','Đúng vậy, chưa có ghi chú mà đã đi làm là vi phạm quy định, nhất định đừng nhận việc trước thời hạn nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1102_07','V1102','阮明',7,'明白，我会等证件办好再去公司报到，麻烦您了。','míng bái， wǒ huì děng zhèng jiàn bàn hǎo zài qù gōng sī bào dào， má fán nín le。','Tôi hiểu rồi, tôi sẽ đợi làm xong giấy tờ rồi mới đến công ty trình diện, cảm ơn anh/chị đã giúp đỡ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1103','SVL2','多份兼职叠加工时超每周20小时，和雇主协商调整排班合规',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1103','SIT1103','P1','suon_se','ban_chinh_thuc',NULL,'国内政策限定留学生在校期间每周校外务工总时长不得超过20小时，所有雇主都需要配合遵守。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_01','V1103','阮明',1,'王店长，我算了下我两份兼职加起来每周工时超20小时，不符合留学生打工规定呢。','wáng diàn zhǎng， wǒ suàn le xià wǒ liǎng fèn jiān zhí jiā qǐ lái měi zhōu gōng shí chāo 20 xiǎo shí， bù fú hé liú xué shēng dǎ gōng guī dìng ne。','Anh Vương ơi, em tính thử rồi, tổng giờ làm của hai công việc bán thời gian của em mỗi tuần vượt quá 20 tiếng, không đúng với quy định làm thêm của du học sinh đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_02','V1103','王店长',2,'还有这种限制吗？我之前不太清楚留学生的用工要求啊。','hái yǒu zhè zhǒng xiàn zhì ma？ wǒ zhī qián bù tài qīng chǔ liú xué shēng de yòng gōng yāo qiú a。','Còn có quy định như vậy nữa à? Trước giờ anh không rõ lắm về yêu cầu tuyển dụng đối với du học sinh.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_03','V1103','阮明',3,'教育局规定外籍学生每周校外工作不能超过二十小时，超时会有风险。','jiào yù jú guī dìng wài jí xué shēng měi zhōu xiào wài gōng zuò bù néng chāo guò èr shí xiǎo shí， chāo shí huì yǒu fēng xiǎn。','Sở giáo dục quy định sinh viên nước ngoài mỗi tuần làm việc bên ngoài trường không được quá hai mươi tiếng, làm quá giờ sẽ có rủi ro đấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_04','V1103','王店长',4,'原来是这样，那我把你这边排班每周减少两天，刚好控制工时。','yuán lái shì zhè yàng， nà wǒ bǎ nǐ zhè biān pái bān měi zhōu jiǎn shǎo liǎng tiān， gāng hǎo kòng zhì gōng shí。','Ra là vậy, vậy anh sẽ giảm bớt hai ngày trong lịch làm việc hàng tuần của em, như thế vừa khéo kiểm soát được số giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_05','V1103','阮明',5,'太感谢您理解啦，调整排班之后我两份工作都能安心做。','tài gǎn xiè nín lǐ jiě la， tiáo zhěng pái bān zhī hòu wǒ liǎng fèn gōng zuò dōu néng ān xīn zuò。','Em cảm ơn anh đã thông cảm nhiều lắm ạ, sau khi điều chỉnh lịch làm em có thể yên tâm làm cả hai công việc rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1103_06','V1103','王店长',6,'没事，合规最重要，下周我重新给你排新班次表。','méi shì， hé guī zuì zhòng yào， xià zhōu wǒ chóng xīn gěi nǐ pái xīn bān cì biǎo。','Không sao đâu, quan trọng nhất là làm đúng quy định, tuần sau anh sẽ sắp lại lịch ca mới cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1104','SVL2','企业要求留学生无加注直接上岗，拒绝并解释合法打工规定',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1104','SIT1104','P1','that_bai_nhe','ban_chinh_thuc',NULL,'企业违规聘用未办理实习加注的外籍学生，市场监管与出入境可对企业处以高额罚款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_01','V1104','阮明',1,'李姐，我现在还没办好出入境实习加注，暂时没办法上岗的。','lǐ jiě， wǒ xiàn zài hái méi bàn hǎo chū rù jìng shí xí jiā zhù， zàn shí méi bàn fǎ shàng gǎng de。','Chị Lý ơi, hiện giờ em vẫn chưa làm xong ghi chú thực tập ở cơ quan xuất nhập cảnh, nên tạm thời chưa thể nhận việc được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_02','V1104','李姐',2,'先过来上班嘛，加注后面抽空补办就行，不影响日常工作。','xiān guò lái shàng bān ma， jiā zhù hòu miàn chōu kòng bǔ bàn jiù xíng， bù yǐng xiǎng rì cháng gōng zuò。','Cứ đến làm trước đi mà, ghi chú thì sau này tranh thủ bổ sung là được, không ảnh hưởng gì đến công việc hàng ngày đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_03','V1104','阮明',3,'不行的，如果无证务工，不光我会受处罚，公司也要承担责任呢。','bù xíng de， rú guǒ wú zhèng wù gōng， bù guāng wǒ huì shòu chǔ fá， gōng sī yě yào chéng dān zé rèn ne。','Không được đâu ạ, nếu làm việc không có giấy phép thì không chỉ em bị xử phạt, mà công ty cũng phải chịu trách nhiệm đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_04','V1104','李姐',4,'哪有这么严格，之前有外籍学生没办证也干了很久啦。','nǎ yǒu zhè me yán gé， zhī qián yǒu wài jí xué shēng méi bàn zhèng yě gàn le hěn jiǔ la。','Làm gì mà nghiêm ngặt vậy, trước đây có sinh viên nước ngoài không làm giấy tờ mà vẫn làm được lâu đấy thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_05','V1104','阮明',5,'出入境会不定期核查企业用工，查到违规会罚款企业，我不能冒险。','chū rù jìng huì bù dìng qī hé chá qǐ yè yòng gōng， chá dào wéi guī huì fá kuǎn qǐ yè， wǒ bù néng mào xiǎn。','Cơ quan xuất nhập cảnh sẽ kiểm tra định kỳ việc sử dụng lao động của doanh nghiệp, nếu phát hiện vi phạm thì công ty sẽ bị phạt, em không thể mạo hiểm được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_06','V1104','李姐',6,'行吧，那等你办好加注再来入职，岗位先给你保留三天。','xíng ba， nà děng nǐ bàn hǎo jiā zhù zài lái rù zhí， gǎng wèi xiān gěi nǐ bǎo liú sān tiān。','Thôi được, vậy đợi em làm xong ghi chú rồi hẵng vào làm, vị trí này chị giữ cho em ba ngày trước đã.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1104_07','V1104','阮明',7,'麻烦您多等我几天，我会尽快办完证件过来报到。','má fán nín duō děng wǒ jǐ tiān， wǒ huì jǐn kuài bàn wán zhèng jiàn guò lái bào dào。','Phiền chị chờ em thêm mấy ngày, em sẽ làm giấy tờ xong sớm nhất rồi đến trình diện ngay ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1105','SVL2','实习到期超过6个月，咨询出入境续办实习加注流程',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1105','SIT1105','P1','twist','chinh_thuc',NULL,'单次实习加注有效期一般不超过6个月，延长实习必须重新完成学校备案再办理加注续期。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_01','V1105','阮明',1,'您好，我的实习加注快到期，实习时长超过半年，该怎么续办呀？','nín hǎo， wǒ de shí xí jiā zhù kuài dào qī， shí xí shí cháng chāo guò bàn nián， gāi zěn me xù bàn ya？','Chào anh/chị, ghi chú thực tập của tôi sắp hết hạn, thời gian thực tập đã hơn nửa năm rồi, vậy tôi cần làm thủ tục gia hạn như thế nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_02','V1105','小周',2,'需要提供企业新出具的延长实习证明，还有学校最新备案回执。','xū yào tí gōng qǐ yè xīn chū jù de yán cháng shí xí zhèng míng， hái yǒu xué xiào zuì xīn bèi àn huí zhí。','Anh cần cung cấp giấy xác nhận gia hạn thực tập mới do công ty cấp, cùng với phiếu xác nhận đăng ký mới nhất của trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_03','V1105','阮明',3,'学校备案回执上周刚过期，是不是要重新去学院申请一份？','xué xiào bèi àn huí zhí shàng zhōu gāng guò qī， shì bú shì yào chóng xīn qù xué yuàn shēn qǐng yī fèn？','Phiếu xác nhận đăng ký của trường mới hết hạn tuần trước, vậy có phải tôi cần quay lại khoa xin cấp lại một bản mới không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_04','V1105','小周',4,'是的，备案材料必须是当月有效，过期回执不能用来续办加注。','shì de， bèi àn cái liào bì xū shì dàng yuè yǒu xiào， guò qī huí zhí bù néng yòng lái xù bàn jiā zhù。','Đúng vậy, hồ sơ đăng ký phải còn hiệu lực trong tháng, phiếu đã hết hạn thì không thể dùng để gia hạn ghi chú được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_05','V1105','阮明',5,'那我今天先回学院重新办备案，明天再来窗口提交材料可以吗？','nà wǒ jīn tiān xiān huí xué yuàn chóng xīn bàn bèi àn， míng tiān zài lái chuāng kǒu tí jiāo cái liào kě yǐ ma？','Vậy hôm nay tôi về khoa làm lại thủ tục đăng ký trước, mai quay lại quầy nộp hồ sơ được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_06','V1105','小周',6,'没问题，材料齐全当天就能受理，记得带白底证件照两张。','méi wèn tí， cái liào qí quán dàng tiān jiù néng shòu lǐ， jì de dài bái dǐ zhèng jiàn zhào liǎng zhāng。','Không vấn đề gì, hồ sơ đầy đủ thì ngay trong ngày là được tiếp nhận, nhớ mang theo hai tấm ảnh thẻ nền trắng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1105_07','V1105','阮明',7,'好的，我记下来所有要求，不会再漏带材料啦。','hǎo de， wǒ jì xià lái suǒ yǒu yāo qiú， bú huì zài lòu dài cái liào la。','Vâng, tôi sẽ ghi lại đầy đủ các yêu cầu, sẽ không quên mang thiếu giấy tờ nữa đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1106','SVL2','更换兼职单位，重新向学校与出入境提交用工备案材料',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1106','SIT1106','P1','suon_se','ban_chinh_thuc',NULL,'留学生每更换一家兼职/实习单位，都要单独完成学校备案，不能沿用旧单位备案证明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_01','V1106','阮明',1,'张老师，我换了一份新兼职，需要重新提交备案材料对吧？','zhāng lǎo shī， wǒ huàn le yī fèn xīn jiān zhí， xū yào chóng xīn tí jiāo bèi àn cái liào duì ba？','Cô Trương ơi, em vừa đổi sang một công việc làm thêm mới, cần nộp lại hồ sơ đăng ký đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_02','V1106','张老师',2,'没错，更换用工单位必须重新走备案流程，旧备案自动失效。','méi cuò， gēng huàn yòng gōng dān wèi bì xū chóng xīn zǒu bèi àn liú chéng， jiù bèi àn zì dòng shī xiào。','Đúng vậy, khi đổi nơi làm việc thì bắt buộc phải làm lại quy trình đăng ký, hồ sơ cũ sẽ tự động hết hiệu lực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_03','V1106','阮明',3,'新公司的用工协议、营业执照复印件我都打印带来了。','xīn gōng sī de yòng gōng xié yì、 yíng yè zhí zhào fù yìn jiàn wǒ dōu dǎ yìn dài lái le。','Thỏa thuận lao động và bản photo giấy phép kinh doanh của công ty mới em đều in ra mang theo hết rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_04','V1106','张老师',4,'材料齐全，我今天录入系统，三天后给你出新备案回执。','cái liào qí quán， wǒ jīn tiān lù rù xì tǒng， sān tiān hòu gěi nǐ chū xīn bèi àn huí zhí。','Hồ sơ đầy đủ rồi, hôm nay cô sẽ nhập vào hệ thống, ba ngày nữa sẽ cấp phiếu xác nhận đăng ký mới cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_05','V1106','阮明',5,'拿到回执我就去出入境更新实习加注，不会耽误上班。','ná dào huí zhí wǒ jiù qù chū rù jìng gēng xīn shí xí jiā zhù， bú huì dān wù shàng bān。','Lấy được phiếu xác nhận rồi em sẽ đi cập nhật ghi chú thực tập ở cơ quan xuất nhập cảnh ngay, sẽ không làm chậm việc đi làm đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_06','V1106','张老师',6,'记得旧兼职单位那边也要办好离职交接，避免两边工时叠加超标。','jì de jiù jiān zhí dān wèi nà biān yě yào bàn hǎo lí zhí jiāo jiē， bì miǎn liǎng biān gōng shí dié jiā chāo biāo。','Nhớ là bên công ty làm thêm cũ cũng phải làm xong thủ tục bàn giao thôi việc, để tránh giờ làm hai bên cộng dồn vượt mức quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1106_07','V1106','阮明',7,'我已经和上一家店长沟通好离职，您放心吧。','wǒ yǐ jīng hé shàng yī jiā diàn zhǎng gōu tōng hǎo lí zhí， nín fàng xīn ba。','Em đã trao đổi xong với quản lý cửa hàng cũ về việc nghỉ việc rồi ạ, cô cứ yên tâm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1107','SVL2','参加企业新人岗前安全培训，记录不懂的工作流程提问主管',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1107','SIT1107','P1','suon_se','ban_chinh_thuc',NULL,'国内服务业、制造业上岗前强制安全培训，员工主动提问操作细节会被认为认真负责，雇主很认可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_01','V1107','阮明',1,'陈主管，刚刚安全培训里的设备操作步骤，我还有两处没听懂呢。','chén zhǔ guǎn， gāng gāng ān quán péi xùn lǐ de shè bèi cāo zuò bù zhòu， wǒ hái yǒu liǎng chù méi tīng dǒng ne。','Anh Trần ơi, phần các bước thao tác thiết bị trong buổi tập huấn an toàn vừa rồi em còn hai chỗ chưa hiểu rõ ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_02','V1107','陈主管',2,'哪一部分不清楚，你直接说，我再给你演示一遍。','nǎ yī bù fèn bù qīng chǔ， nǐ zhí jiē shuō， wǒ zài gěi nǐ yǎn shì yī biàn。','Chỗ nào chưa rõ thì em cứ nói thẳng ra, anh sẽ làm mẫu lại cho em xem một lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_03','V1107','阮明',3,'就是清洁机器的断电流程，培训讲得有点快，我没记完整。','jiù shì qīng jié jī qì de duàn diàn liú chéng， péi xùn jiǎng dé yǒu diǎn kuài， wǒ méi jì wán zhěng。','Là quy trình ngắt điện khi vệ sinh máy đó ạ, lúc tập huấn nói hơi nhanh nên em ghi nhớ chưa đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_04','V1107','陈主管',4,'我带你到设备旁实操一遍，记住维修清洁必须先断总电源。','wǒ dài nǐ dào shè bèi páng shí cāo yī biàn， jì zhù wéi xiū qīng jié bì xū xiān duàn zǒng diàn yuán。','Anh sẽ dẫn em ra chỗ máy để thực hành lại một lần, nhớ là khi bảo trì vệ sinh thì bắt buộc phải ngắt nguồn điện tổng trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_05','V1107','阮明',5,'原来是这样，还好主动问清楚，不然操作失误会有安全隐患。','yuán lái shì zhè yàng， hái hǎo zhǔ dòng wèn qīng chǔ， bù rán cāo zuò shī wù huì yǒu ān quán yǐn huàn。','Ra là vậy, may mà em chủ động hỏi cho rõ, không thì thao tác sai sẽ có nguy cơ mất an toàn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_06','V1107','陈主管',6,'有不懂的随时来问，千万不要自己随意操作机器哦。','yǒu bù dǒng de suí shí lái wèn， qiān wàn bú yào zì jǐ suí yì cāo zuò jī qì ó。','Có gì không hiểu thì cứ đến hỏi bất cứ lúc nào, tuyệt đối đừng tự ý thao tác máy móc một mình nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1107_07','V1107','阮明',7,'好的，我会把所有注意事项全部记在笔记本上。','hǎo de， wǒ huì bǎ suǒ yǒu zhù yì shì xiàng quán bù jì zài bǐ jì běn shàng。','Vâng ạ, em sẽ ghi hết tất cả các lưu ý vào sổ tay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1108','SVL2','入职要求提供外国人健康证，咨询办理地点与所需材料',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1108','SIT1108','P1','twist','ban_chinh_thuc',NULL,'外籍从业人员需办理专属外籍健康证明，普通国内健康证无法用于留学生兼职入职。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_01','V1108','阮明',1,'李姐，入职要外国人专用健康证，我不清楚去哪里办理呀？','lǐ jiě， rù zhí yào wài guó rén zhuān yòng jiàn kāng zhèng， wǒ bù qīng chǔ qù nǎ lǐ bàn lǐ ya？','Chị Lý ơi, vào làm cần giấy khám sức khỏe dành riêng cho người nước ngoài, em không rõ đi đâu để làm đây ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_02','V1108','李姐',2,'去市国际旅行卫生保健中心，带上护照和一寸照片就行。','qù shì guó jì lǚ xíng wèi shēng bǎo jiàn zhōng xīn， dài shàng hù zhào hé yī cùn zhào piān jiù xíng。','Đến trung tâm kiểm dịch y tế quốc tế của thành phố, mang theo hộ chiếu với ảnh 1 inch là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_03','V1108','阮明',3,'我今天只有护照，照片落在宿舍，明天过去办理来得及吗？','wǒ jīn tiān zhǐ yǒu hù zhào， zhào piān luò zài sù shè， míng tiān guò qù bàn lǐ lái de jí ma？','Hôm nay em chỉ có hộ chiếu thôi, ảnh để quên ở ký túc xá rồi, mai qua làm có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_04','V1108','李姐',4,'可以，体检当天就能拿临时回执，正式证件三天后领取。','kě yǐ， tǐ jiǎn dàng tiān jiù néng ná lín shí huí zhí， zhèng shì zhèng jiàn sān tiān hòu lǐng qǔ。','Được, hôm khám xong là lấy được biên nhận tạm ngay, còn giấy chính thức thì ba ngày sau lấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_05','V1108','阮明',5,'体检需要空腹吗？我怕早上吃了东西白跑一趟。','tǐ jiǎn xū yào kōng fù ma？ wǒ pà zǎo shàng chī le dōng xī bái pǎo yī tàng。','Khám có cần nhịn ăn không ạ? Em sợ sáng mà ăn gì vào thì lại phải đi lại lần nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_06','V1108','李姐',6,'早上空腹抽血，你明天早点过去，人会少很多。','zǎo shàng kōng fù chōu xuè， nǐ míng tiān zǎo diǎn guò qù， rén huì shǎo hěn duō。','Sáng nhịn ăn để lấy máu, em đi sớm một chút vào ngày mai, người sẽ vắng hơn nhiều đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1108_07','V1108','阮明',7,'多谢提醒，我明天一早空腹过去体检。','duō xiè tí xǐng， wǒ míng tiān yī zǎo kōng fù guò qù tǐ jiǎn。','Cảm ơn chị nhắc nhé, mai em sẽ nhịn ăn đi khám sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1109','SVL2','询问实习/兼职是否提供工作餐、交通补贴、全勤奖励',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1109','SIT1109','P1','suon_se','tuy_y',NULL,'餐饮、零售类兼职普遍设有员工餐、交通补贴、全勤奖，面试入职主动询问福利属于正常沟通。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_01','V1109','阮明',1,'店长，我想问下咱们兼职有没有工作餐和交通补贴呀？','diàn zhǎng， wǒ xiǎng wèn xià zán men jiān zhí yǒu méi yǒu gōng zuò cān hé jiāo tōng bǔ tiē ya？','Quản lý ơi, em muốn hỏi làm bán thời gian ở đây có cơm nhân viên với trợ cấp đi lại không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_02','V1109','王店长',2,'工作日值班提供免费员工餐，交通补贴每月五十块呢。','gōng zuò rì zhí bān tí gōng miǎn fèi yuán gōng cān， jiāo tōng bǔ tiē měi yuè wǔ shí kuài ne。','Ngày làm trực thì có cơm miễn phí cho nhân viên, trợ cấp đi lại mỗi tháng năm chục nghìn nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_03','V1109','阮明',3,'那全勤奖励是什么标准，每月不迟到就能拿到吗？','nà quán qín jiǎng lì shì shén me biāo zhǔn， měi yuè bù chí dào jiù néng ná dào ma？','Vậy thưởng chuyên cần tính theo tiêu chuẩn nào, tháng không đi trễ là được nhận luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_04','V1109','王店长',4,'当月无迟到早退、不临时请假，月底多两百元全勤奖。','dàng yuè wú chí dào zǎo tuì、 bù lín shí qǐng jià， yuè dǐ duō liǎng bǎi yuán quán qín jiǎng。','Tháng đó không đi trễ về sớm, không xin nghỉ đột xuất, cuối tháng được thêm hai trăm tệ thưởng chuyên cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_05','V1109','阮明',5,'福利还挺不错的，我一定会尽量全勤上班。','fú lì hái tǐng bù cuò de， wǒ yí dìng huì jǐn liàng quán qín shàng bān。','Phúc lợi cũng khá ổn đó chứ, em nhất định sẽ cố gắng đi làm đều đặn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_06','V1109','王店长',6,'好好干，后续表现好还能给你调整排班和时薪。','hǎo hǎo gàn， hòu xù biǎo xiàn hǎo hái néng gěi nǐ tiáo zhěng pái bān hé shí xīn。','Cố gắng làm tốt vào, sau này làm tốt còn được điều chỉnh ca làm với lương giờ nữa đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1109_07','V1109','阮明',7,'好嘞，麻烦店长啦！','hǎo lei， má fán diàn zhǎng la！','Dạ được, phiền quản lý nhiều nha!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1110','SVL2','学习公司考勤打卡系统，忘记打卡找人事补录考勤记录',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1110','SIT1110','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内企业考勤补卡普遍需要主管签字佐证，且每月有固定补卡次数上限，超出会扣除全勤奖金。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_01','V1110','阮明',1,'小吴，我今早上班忘记打卡，能不能帮忙补录一下考勤？','xiǎo wú， wǒ jīn zǎo shàng bān wàng jì dǎ kǎ， néng bù néng bāng máng bǔ lù yī xià kǎo qín？','Tiểu Ngô ơi, sáng nay em đi làm quên chấm công, giúp em bổ sung lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_02','V1110','小吴',2,'补打卡需要提交书面说明，还要你的当班主管签字确认。','bǔ dǎ kǎ xū yào tí jiāo shū miàn shuō míng， hái yào nǐ dí dàng bān zhǔ guǎn qiān zì què rèn。','Bổ sung chấm công thì cần nộp bản giải trình bằng văn bản, còn phải có chữ ký xác nhận của quản lý ca em nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_03','V1110','阮明',3,'我现在去找主管签字，签完马上拿过来给你行吗？','wǒ xiàn zài qù zhǎo zhǔ guǎn qiān zì， qiān wán mǎ shàng ná guò lái gěi nǐ xíng ma？','Giờ em đi tìm quản lý ký xong mang qua đưa chị luôn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_04','V1110','小吴',4,'今天下班前提交都可以，超过当日就没办法补录啦。','jīn tiān xià bān qián tí jiāo dōu kě yǐ， chāo guò dāng rì jiù méi bàn fǎ bǔ lù la。','Hôm nay nộp trước giờ tan làm là được, qua ngày là không thể bổ sung được nữa đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_05','V1110','阮明',5,'原来是有时间限制，还好我及时过来咨询，差点错过。','yuán lái shì yǒu shí jiān xiàn zhì， hái hǎo wǒ jí shí guò lái zī xún， chà diǎn cuò guò。','Ra là có giới hạn thời gian, may mà em đến hỏi kịp lúc, suýt nữa lỡ mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_06','V1110','小吴',6,'下次记得上下班及时打卡，每月只有三次补卡机会哦。','xià cì jì de shàng xià bān jí shí dǎ kǎ， měi yuè zhǐ yǒu sān cì bǔ kǎ jī huì ó。','Lần sau nhớ chấm công đúng giờ khi đi làm và tan làm nhé, mỗi tháng chỉ có ba lần được bổ sung công thôi đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1110_07','V1110','阮明',7,'我记住啦，之后一定不会再忘记打卡。','wǒ jì zhù la， zhī hòu yí dìng bú huì zài wàng jì dǎ kǎ。','Em nhớ rồi ạ, sau này nhất định không quên chấm công nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1111','SVL2','企业收取兼职服装押金，协商拒绝并咨询合规收费规则',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1111','SIT1111','P1','suon_se','ban_chinh_thuc',NULL,'中国劳动合同法明确规定，企业不得向劳动者收取押金、保证金，违规收取可向劳动部门投诉。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_01','V1111','阮明',1,'店长，入职要交两百元服装押金吗？劳动法不是不允许收押金吗？','diàn zhǎng， rù zhí yào jiāo liǎng bǎi yuán fú zhuāng yā jīn ma？ láo dòng fǎ bú shì bù yǔn xǔ shōu yā jīn ma？','Quản lý ơi, vào làm phải đóng hai trăm tệ tiền cọc đồng phục hả? Luật lao động không phải cấm thu tiền cọc sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_02','V1111','王店长',2,'很多门店都要收，离职归还服装才会退还押金的。','hěn duō mén diàn dōu yào shōu， lí zhí guī huán fú zhuāng cái huì tuì huán yā jīn de。','Nhiều cửa hàng đều thu vậy đó, khi nghỉ việc trả lại đồng phục thì mới hoàn cọc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_03','V1111','阮明',3,'我了解规定，用人单位不能以服装、工具名义收取员工押金呢。','wǒ liǎo jiě guī dìng， yòng rén dān wèi bù néng yǐ fú zhuāng、 gōng jù míng yì shōu qǔ yuán gōng yā jīn ne。','Em có tìm hiểu quy định rồi, đơn vị sử dụng lao động không được lấy danh nghĩa đồng phục, dụng cụ để thu tiền cọc của nhân viên đâu ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_04','V1111','王店长',4,'行吧，那我给你登记免费领用，离职完好归还服装就行。','xíng ba， nà wǒ gěi nǐ dēng jì miǎn fèi lǐng yòng， lí zhí wán hǎo guī huán fú zhuāng jiù xíng。','Thôi được rồi, vậy chị ghi nhận là cấp phát miễn phí cho em, khi nghỉ việc trả lại đồng phục còn nguyên là được.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_05','V1111','阮明',5,'太感谢您了，我一定会妥善保管工作服，离职完整归还。','tài gǎn xiè nín le， wǒ yí dìng huì tuǒ shàn bǎo guǎn gōng zuò fú， lí zhí wán zhěng guī huán。','Cảm ơn chị nhiều lắm, em nhất định sẽ giữ gìn đồng phục cẩn thận, nghỉ việc sẽ trả lại nguyên vẹn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1111_06','V1111','王店长',6,'没事，合规最重要，之后有任何收费疑问都可以直接问我。','méi shì， hé guī zuì zhòng yào， zhī hòu yǒu rèn hé shōu fèi yí wèn dōu kě yǐ zhí jiē wèn wǒ。','Không sao đâu, đúng quy định là quan trọng nhất, sau này có thắc mắc gì về khoản thu cứ hỏi thẳng chị nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1112','SVL2','工作操作失误损坏客户物品，和主管协商赔偿分摊方案',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1112','SIT1112','P1','twist','ban_chinh_thuc',NULL,'职场新人工作失误造成财物损失，多数中小企业会企业员工分摊赔偿，不会要求员工全额承担。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_01','V1112','阮明',1,'陈主管，实在抱歉，我操作失误把客户的水杯摔碎了啊。','chén zhǔ guǎn， shí zài bào qiàn， wǒ cāo zuò shī wù bǎ kè hù de shuǐ bēi shuāi suì le a。','Chú Trần ơi, thật sự xin lỗi, em thao tác sai làm vỡ mất cốc nước của khách rồi ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_02','V1112','陈主管',2,'客户刚刚已经投诉过来了，这个杯子原价一百八十元。','kè hù gāng gāng yǐ jīng tóu sù guò lái le， zhè ge bēi zi yuán jià yì bǎi bā shí yuán。','Khách vừa mới khiếu nại lên rồi đó, cái cốc này giá gốc một trăm tám mươi tệ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_03','V1112','阮明',3,'全部赔偿我承担吗？还是门店可以分摊一部分损失呢？','quán bù péi cháng wǒ chéng dān ma？ hái shì mén diàn kě yǐ fēn tān yī bù fèn sǔn shī ne？','Em phải bồi thường toàn bộ hay cửa hàng có thể chia sẻ một phần thiệt hại ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_04','V1112','陈主管',4,'新手失误门店承担一半，剩下九十元需要你个人补齐。','xīn shǒu shī wù mén diàn chéng dān yí bàn， shèng xià jiǔ shí yuán xū yào nǐ gè rén bǔ qí。','Nhân viên mới sơ suất thì cửa hàng chịu một nửa, còn chín mươi tệ còn lại thì em phải tự bù vào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_05','V1112','阮明',5,'我可以接受分摊赔偿，现在联系客户道歉再转赔偿款行吗？','wǒ kě yǐ jiē shòu fēn tān péi cháng， xiàn zài lián xì kè hù dào qiàn zài zhuǎn péi cháng kuǎn xíng ma？','Em đồng ý chia sẻ khoản bồi thường, giờ em liên hệ xin lỗi khách rồi chuyển tiền bồi thường luôn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_06','V1112','陈主管',6,'我先和客户沟通安抚，你稍后主动给客户发致歉消息。','wǒ xiān hé kè hù gōu tōng ān fǔ， nǐ shāo hòu zhǔ dòng gěi kè hù fā zhì qiàn xiāo xī。','Chú sẽ trao đổi trấn an khách trước, lát nữa em chủ động nhắn lời xin lỗi khách nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1112_07','V1112','阮明',7,'好，我马上编辑道歉文字，一定注意之后操作小心。','hǎo， wǒ mǎ shàng biān jí dào qiàn wén zì， yí dìng zhù yì zhī hòu cāo zuò xiǎo xīn。','Dạ, em soạn tin nhắn xin lỗi ngay đây, nhất định sau này sẽ chú ý thao tác cẩn thận hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1113','SVL2','上班途中骑车摔伤，向主管申请工伤就医与带薪休养',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1113','SIT1113','P1','suon_se','ban_chinh_thuc',NULL,'上下班合理路线内发生非本人主要责任交通事故，属于工伤范畴，用人单位需正常发放休养期间工资。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_01','V1113','阮明',1,'陈主管，我骑车来上班路上摔倒，膝盖擦伤严重，想请假就医。','chén zhǔ guǎn， wǒ qí chē lái shàng bān lù shàng shuāi dǎo， xī gài cā shāng yán zhòng， xiǎng qǐng jià jiù yī。','Chú Trần ơi, em đi xe đạp đến chỗ làm bị ngã trên đường, đầu gối trầy nặng lắm, em muốn xin nghỉ đi khám ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_02','V1113','陈主管',2,'伤得严重吗？上下班途中非本人主责事故可以走工伤报备。','shāng dé yán zhòng ma？ shàng xià bān tú zhōng fēi běn rén zhǔ zé shì gù kě yǐ zǒu gōng shāng bào bèi。','Bị nặng vậy à? Tai nạn trên đường đi làm mà không phải lỗi chính của em thì có thể làm hồ sơ tai nạn lao động đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_03','V1113','阮明',3,'交警判定对方全责，医院诊断单据我都保存好了。','jiāo jǐng pàn dìng duì fāng quán zé， yī yuàn zhěn duàn dān jù wǒ dōu bǎo cún hǎo le。','Cảnh sát giao thông xác định bên kia hoàn toàn có lỗi, giấy chẩn đoán của bệnh viện em cũng giữ đầy đủ rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_04','V1113','陈主管',4,'你安心去治疗，休养这几天按正常工时发放薪资。','nǐ ān xīn qù zhì liáo， xiū yǎng zhè jǐ tiān àn zhèng cháng gōng shí fā fàng xīn zī。','Em cứ yên tâm đi chữa trị, những ngày nghỉ dưỡng thương này vẫn tính lương theo giờ làm bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_05','V1113','阮明',5,'太感谢您了，我处理完伤口再把病历拍照发给您报备。','tài gǎn xiè nín le， wǒ chǔ lǐ wán shāng kǒu zài bǎ bìng lì pāi zhào fā gěi nín bào bèi。','Cảm ơn chú nhiều lắm, xử lý vết thương xong em sẽ chụp lại bệnh án gửi chú để báo cáo ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1113_06','V1113','陈主管',6,'不用着急上班，养好伤再回来，工作我先安排其他人顶替。','bù yòng zháo jí shàng bān， yǎng hǎo shāng zài huí lái， gōng zuò wǒ xiān ān pái qí tā rén dǐng tì。','Không cần vội đi làm đâu, dưỡng thương khỏe hẳn rồi hãy quay lại, công việc chú sắp người khác thay tạm cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1114','SVL2','客户因语言沟通不畅产生投诉，上前配合主管安抚致歉',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1114','SIT1114','P1','twist','ban_chinh_thuc',NULL,'服务业遇到外籍员工语言沟通纠纷，主管会优先出面沟通，不会将全部责任归咎外籍员工。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_01','V1114','阮明',1,'陈主管，这位客户听不懂我的表达，已经有点生气投诉了。','chén zhǔ guǎn， zhè wèi kè hù tīng bù dǒng wǒ de biǎo dá， yǐ jīng yǒu diǎn shēng qì tóu sù le。','Chú Trần ơi, vị khách này nghe không hiểu em nói gì, có vẻ hơi bực và đã khiếu nại rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_02','V1114','陈主管',2,'你先别着急解释，我来和客户沟通，你在一旁帮忙递单据。','nǐ xiān bié zháo jí jiě shì， wǒ lái hé kè hù gōu tōng， nǐ zài yī páng bāng máng dì dān jù。','Em đừng vội giải thích, để chú nói chuyện với khách, em đứng bên cạnh phụ đưa giấy tờ nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_03','V1114','阮明',3,'都怪我中文表达不够流畅，给门店添麻烦了，实在不好意思。','dōu guài wǒ zhōng wén biǎo dá bù gòu liú chàng， gěi mén diàn tiān má fán le， shí zài bù hǎo yì sī。','Tại em nói tiếng Trung chưa đủ trôi chảy, làm phiền cửa hàng rồi, thật sự xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_04','V1114','陈主管',4,'没事，外籍员工语言沟通有障碍很正常，我来安抚客户。','méi shì， wài jí yuán gōng yǔ yán gōu tōng yǒu zhàng ài hěn zhèng cháng， wǒ lái ān fǔ kè hù。','Không sao đâu, nhân viên nước ngoài giao tiếp có chút trở ngại là chuyện bình thường mà, để chú trấn an khách cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_05','V1114','阮明',5,'等下我要不要主动跟客户道个歉，缓和一下气氛？','děng xià wǒ yào bù yào zhǔ dòng gēn kè hù dào gè qiàn， huǎn hé yī xià qì fēn？','Lát nữa em có nên chủ động xin lỗi khách để làm dịu không khí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_06','V1114','陈主管',6,'等我解释清楚业务问题，你再简单致歉会更合适。','děng wǒ jiě shì qīng chǔ yè wù wèn tí， nǐ zài jiǎn dān zhì qiàn huì gèng hé shì。','Đợi chú giải thích rõ vấn đề nghiệp vụ xong, em xin lỗi ngắn gọn sau sẽ hợp lý hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1114_07','V1114','阮明',7,'好，我听您安排，之后我也会多练习日常服务用语。','hǎo， wǒ tīng nín ān pái， zhī hòu wǒ yě huì duō liàn xí rì cháng fú wù yòng yǔ。','Dạ, em nghe theo sắp xếp của chú, sau này em cũng sẽ luyện tập thêm câu từ phục vụ hàng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1115','SVL2','临近下班临时安排加班，询问加班补贴与下班返程时间',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1115','SIT1115','P1','that_bai_nhe','ban_chinh_thuc',NULL,'法定工作日加班用人单位需支付1.5倍薪资，休息日加班2倍，法定节假日3倍，员工可主动询问加班薪酬标准。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_01','V1115','阮明',1,'陈主管，我原定六点下班，现在临时安排加班，有加班补贴吗？','chén zhǔ guǎn， wǒ yuán dìng liù diǎn xià bān， xiàn zài lín shí ān pái jiā bān， yǒu jiā bān bǔ tiē ma？','Chú Trần ơi, em vốn định sáu giờ tan làm, giờ đột xuất phải làm thêm, vậy có phụ cấp làm thêm giờ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_02','V1115','陈主管',2,'今天临时整理库存，加班两小时，按一点五倍时薪结算补贴。','jīn tiān lín shí zhěng lǐ kù cún， jiā bān liǎng xiǎo shí， àn yì diǎn wǔ bèi shí xīn jié suàn bǔ tiē。','Hôm nay đột xuất kiểm kê kho, làm thêm hai tiếng, tính phụ cấp theo một phẩy năm lần lương giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_03','V1115','阮明',3,'可是我七点有线上语言课，加班会错过上课时间呢。','kě shì wǒ qī diǎn yǒu xiàn shàng yǔ yán kè， jiā bān huì cuò guò shàng kè shí jiān ne。','Nhưng bảy giờ em có lớp học tiếng online, làm thêm thì lỡ mất giờ học rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_04','V1115','陈主管',4,'今晚库存必须清点完成，课程只能你自己调整时间啦。','jīn wǎn kù cún bì xū qīng diǎn wán chéng， kè chéng zhǐ néng nǐ zì jǐ tiáo zhěng shí jiān la。','Tối nay bắt buộc phải kiểm kê xong kho, còn lớp học thì em tự điều chỉnh giờ thôi nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_05','V1115','阮明',5,'那我只能课后回看录播，麻烦您把加班工时记录清楚。','nà wǒ zhǐ néng kè hòu huí kàn lù bō， má fán nín bǎ jiā bān gōng shí jì lù qīng chǔ。','Vậy em đành xem lại video ghi hình sau buổi học, phiền chú ghi rõ giờ làm thêm giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_06','V1115','陈主管',6,'放心，考勤系统会单独标注加班时长，月底统一结算。','fàng xīn， kǎo qín xì tǒng huì dān dú biāo zhù jiā bān shí cháng， yuè dǐ tǒng yī jié suàn。','Yên tâm đi, hệ thống chấm công sẽ ghi riêng thời gian làm thêm, cuối tháng tính chung một lần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1115_07','V1115','阮明',7,'好，我现在留下来清点库存，尽快完成早点下班。','hǎo， wǒ xiàn zài liú xià lái qīng diǎn kù cún， jǐn kuài wán chéng zǎo diǎn xià bān。','Dạ, giờ em ở lại kiểm kê kho, cố gắng làm xong sớm để về sớm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1116','SVL2','电脑里实习重要文件误删，求助同事找回备份资料',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1116','SIT1116','P1','suon_se','tuy_y',NULL,'国内企业办公电脑普遍配备云端自动备份，同事之间互相协助处理办公故障是职场常见互助行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_01','V1116','阮明',1,'小佳，糟糕，我刚不小心把实习报告文件全部删掉了啊。','xiǎo jiā， zāo gāo， wǒ gāng bù xiǎo xīn bǎ shí xí bào gào wén jiàn quán bù shān diào le a。','Tiểu Giai, chết rồi, mình vừa lỡ tay xóa mất hết file báo cáo thực tập rồi.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_02','V1116','小佳',2,'别慌，公司电脑每天自动云端备份，我教你恢复备份就行。','bié huāng， gōng sī diàn nǎo měi tiān zì dòng yún duān bèi fèn， wǒ jiāo nǐ huī fù bèi fèn jiù xíng。','Đừng hoảng, máy công ty ngày nào cũng tự động sao lưu lên cloud mà, để mình chỉ cho cậu cách khôi phục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_03','V1116','阮明',3,'真的吗？我还以为要重新做一整天，快教教我操作步骤吧。','zhēn de ma？ wǒ hái yǐ wéi yào chóng xīn zuò yī zhěng tiān， kuài jiāo jiāo wǒ cāo zuò bù zhòu ba。','Thật hả? Mình còn tưởng phải làm lại từ đầu cả ngày, nhanh chỉ mình cách làm đi.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_04','V1116','小佳',4,'我一步步带你点备份界面，十分钟就能找回全部文档。','wǒ yí bù bù dài nǐ diǎn bèi fèn jiè miàn， shí fēn zhōng jiù néng zhǎo huí quán bù wén dàng。','Mình dẫn cậu bấm từng bước vào giao diện sao lưu, mười phút là lấy lại hết tài liệu thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_05','V1116','阮明',5,'太谢谢你了，要是文件找不回，明天没办法交给导师。','tài xiè xiè nǐ le， yào shì wén jiàn zhǎo bù huí， míng tiān méi bàn fǎ jiāo gěi dǎo shī。','Cảm ơn cậu nhiều lắm, chứ file mà không tìm lại được thì mai không có gì nộp cho giảng viên hướng dẫn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_06','V1116','小佳',6,'小事，以后记得自己手动多存一份，避免再次误删。','xiǎo shì， yǐ hòu jì de zì jǐ shǒu dòng duō cún yī fèn， bì miǎn zài cì wù shān。','Chuyện nhỏ ấy mà, sau này nhớ tự tay lưu thêm một bản nữa để tránh xóa nhầm lần nữa nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1116_07','V1116','阮明',7,'我记住啦，这次多亏有你帮忙！','wǒ jì zhù la， zhè cì duō kuī yǒu nǐ bāng máng！','Mình nhớ rồi, lần này may có cậu giúp đó!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1117','SVL2','工位贵重耳机在工作区丢失，找人事调取监控查找',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1117','SIT1117','P1','twist','ban_chinh_thuc',NULL,'企业办公监控仅覆盖公共走道、前台，独立工位无监控，丢失私人物品只能通过内部群求助同事。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_01','V1117','阮明',1,'小吴，我工位的耳机不见了，能不能调取办公区监控看看？','xiǎo wú， wǒ gōng wèi de ěr jī bú jiàn le， néng bù néng diào qǔ bàn gōng qū jiān kòng kàn kàn？','Tiểu Ngô, tai nghe ở chỗ ngồi của tôi bị mất rồi, cô có thể xin trích xuất camera khu văn phòng giúp tôi xem thử được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_02','V1117','小吴',2,'可以调监控，但只能查看公共区域，私人工位死角拍不到哦。','kě yǐ diào jiān kòng， dàn zhǐ néng chá kàn gōng gòng qū yù， sī rén gōng wèi sǐ jiǎo pāi bú dào ó。','Trích xuất thì được, nhưng chỉ xem được khu vực chung thôi, còn góc khuất chỗ ngồi riêng thì camera không quay tới đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_03','V1117','阮明',3,'我中午外出吃饭忘了收耳机，回来就找不到，大概率被人误拿。','wǒ zhōng wǔ wài chū chī fàn wàng le shōu ěr jī， huí lái jiù zhǎo bú dào， dà gài lǜ bèi rén wù ná。','Trưa tôi ra ngoài ăn cơm quên không cất tai nghe, lúc về thì không thấy đâu nữa, chắc là bị ai đó lấy nhầm rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_04','V1117','小吴',4,'我现在调取中午时段录像，你在这里稍等几分钟。','wǒ xiàn zài diào qǔ zhōng wǔ shí duàn lù xiàng， nǐ zài zhè lǐ shāo děng jǐ fēn zhōng。','Giờ tôi trích xuất camera lúc buổi trưa, anh chờ ở đây vài phút nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_05','V1117','阮明',5,'如果监控找不到，我能不能在公司群里发寻物启事问问同事？','rú guǒ jiān kòng zhǎo bú dào， wǒ néng bù néng zài gōng sī qún lǐ fā xún wù qǐ shì wèn wèn tóng shì？','Nếu xem camera mà không tìm ra, tôi có thể đăng thông báo tìm đồ trong nhóm chung của công ty để hỏi mọi người không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_06','V1117','小吴',6,'可以，我帮你转发公司全员群，方便大家帮忙留意。','kě yǐ， wǒ bāng nǐ zhuǎn fā gōng sī quán yuán qún， fāng biàn dà jiā bāng máng liú yì。','Được chứ, tôi giúp anh đăng lên nhóm toàn công ty, để mọi người tiện để ý giúp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1117_07','V1117','阮明',7,'麻烦你了，耳机对我学习工作都很重要，希望能找回来。','má fán nǐ le， ěr jī duì wǒ xué xí gōng zuò dōu hěn zhòng yào， xī wàng néng zhǎo huí lái。','Phiền cô rồi, tai nghe đó với tôi quan trọng lắm, cả học tập lẫn công việc, mong là tìm lại được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1118','SVL2','发薪日工资少发，找人事核对考勤、扣款明细补发差额',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1118','SIT1118','P1','suon_se','ban_chinh_thuc',NULL,'国内企业每月会发放薪资明细，包含出勤、加班、请假扣款、个税等项目，薪资异议当月可核对更正。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_01','V1118','阮明',1,'小吴，今天发薪到账金额比我核算的少三百，想核对一下明细。','xiǎo wú， jīn tiān fā xīn dào zhàng jīn é bǐ wǒ hé suàn de shǎo sān bǎi， xiǎng hé duì yī xià míng xì。','Tiểu Ngô, lương hôm nay chuyển vào tài khoản ít hơn tôi tính ba trăm, muốn nhờ cô đối chiếu lại chi tiết xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_02','V1118','小吴',2,'我调取你的考勤表，上周有半天临时请假，扣除了当日工时工资。','wǒ diào qǔ nǐ de kǎo qín biǎo， shàng zhōu yǒu bàn tiān lín shí qǐng jià， kòu chú le dāng rì gōng shí gōng zī。','Để tôi lấy bảng chấm công của anh xem, tuần trước anh có xin nghỉ nửa ngày đột xuất, nên bị trừ tiền công ngày hôm đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_03','V1118','阮明',3,'原来是请假扣款，我忘记核算这部分，还以为是计算出错了。','yuán lái shì qǐng jià kòu kuǎn， wǒ wàng jì hé suàn zhè bù fèn， hái yǐ wéi shì jì suàn chū cuò le。','Thì ra là bị trừ do nghỉ phép, tôi quên tính phần này, còn tưởng là tính sai đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_04','V1118','小吴',4,'我把本月薪资明细截图发给你，每一笔扣款都标注清楚啦。','wǒ bǎ běn yuè xīn zī míng xì jié tú fā gěi nǐ， měi yī bǐ kòu kuǎn dōu biāo zhù qīng chǔ la。','Tôi gửi cho anh ảnh chụp bảng lương chi tiết tháng này, từng khoản khấu trừ đều ghi rõ hết rồi đó.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_05','V1118','阮明',5,'我看完明细确认无误，下次我会自己记录好出勤天数。','wǒ kàn wán míng xì què rèn wú wù， xià cì wǒ huì zì jǐ jì lù hǎo chū qín tiān shù。','Tôi xem xong bảng chi tiết thấy đúng rồi, lần sau tôi sẽ tự ghi lại số ngày đi làm cho cẩn thận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_06','V1118','小吴',6,'有薪资疑问随时来找我核对，当月都可以申请补发核对差额。','yǒu xīn zī yí wèn suí shí lái zhǎo wǒ hé duì， dàng yuè dōu kě yǐ shēn qǐng bǔ fā hé duì chā é。','Có thắc mắc gì về lương cứ đến tìm tôi đối chiếu, trong tháng đều có thể xin bù chênh lệch nếu cần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1118_07','V1118','阮明',7,'好的，辛苦你帮忙查明细啦。','hǎo de， xīn kǔ nǐ bāng máng chá míng xì la。','Được rồi, cảm ơn cô đã giúp tôi kiểm tra chi tiết nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1119','SVL2','兼职老板以业绩不达标为由克扣全额底薪，协商维权',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1119','SIT1119','P1','that_bai_nhe','ban_chinh_thuc',NULL,'用人单位无权单方面克扣劳动合同约定的基础底薪，劳动者可拨打全国劳动保障热线12333维权。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_01','V1119','阮明',1,'店长，这个月业绩没达标，您直接扣除全部底薪，这样不符合约定吧？','diàn zhǎng， zhè ge yuè yè jì méi dá biāo， nín zhí jiē kòu chú quán bù dǐ xīn， zhè yàng bù fú hé yuē dìng ba？','Cửa hàng trưởng, tháng này doanh số không đạt mà anh trừ luôn cả lương cơ bản, vậy không đúng với thỏa thuận rồi ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_02','V1119','王店长',2,'店里规定业绩不达标只能拿提成，底薪全部扣除。','diàn lǐ guī dìng yè jì bù dá biāo zhǐ néng ná tí chéng， dǐ xīn quán bù kòu chú。','Quy định của cửa hàng là doanh số không đạt thì chỉ được nhận hoa hồng, lương cơ bản bị trừ hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_03','V1119','阮明',3,'合同里写明底薪是固定发放，业绩只影响提成，不能扣底薪的。','hé tóng lǐ xiě míng dǐ xīn shì gù dìng fā fàng， yè jì zhǐ yǐng xiǎng tí chéng， bù néng kòu dǐ xīn de。','Trong hợp đồng ghi rõ lương cơ bản là khoản cố định, doanh số chỉ ảnh hưởng đến hoa hồng thôi, không được trừ vào lương cơ bản.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_04','V1119','王店长',4,'门店临时调整规则，这个月只能按新规定结算薪资。','mén diàn lín shí diào zhěng guī zé， zhè ge yuè zhǐ néng àn xīn guī dìng jié suàn xīn zī。','Cửa hàng tạm thời điều chỉnh quy định, tháng này chỉ có thể tính lương theo quy định mới thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_05','V1119','阮明',5,'如果协商不一致，我可以拨打12333劳动热线反映情况吗？','rú guǒ xié shāng bù yī zhì， wǒ kě yǐ bō dǎ 12333 láo dòng rè xiàn fǎn yìng qíng kuàng ma？','Nếu không thỏa thuận được, tôi có thể gọi đường dây nóng lao động 12333 để phản ánh việc này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_06','V1119','王店长',6,'别投诉，我折中一下，扣除一半底薪，底薪另一半照常发放。','bié tóu sù， wǒ zhé zhōng yī xià， kòu chú yí bàn dǐ xīn， dǐ xīn lìng yí bàn zhào cháng fā fàng。','Đừng khiếu nại, tôi thỏa hiệp một chút, chỉ trừ một nửa lương cơ bản, nửa còn lại vẫn trả bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1119_07','V1119','阮明',7,'行，我接受这个方案，希望下次调整规则提前和员工沟通。','xíng， wǒ jiē shòu zhè ge fāng àn， xī wàng xià cì tiáo zhěng guī zé tí qián hé yuán gōng gōu tōng。','Được ạ, tôi chấp nhận phương án này, mong lần sau điều chỉnh quy định thì trao đổi trước với nhân viên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1120','SVL2','询问寒暑假全职兼职薪资翻倍、加班薪酬计算标准',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1120','SIT1120','P1','suon_se','ban_chinh_thuc',NULL,'寒暑假、法定节假日兼职薪资上浮有明确计算标准，企业需提前告知员工薪酬核算规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_01','V1120','阮明',1,'小吴，寒暑假我可以全天上班，薪资会按全职标准翻倍吗？','xiǎo wú， hán shǔ jià wǒ kě yǐ quán tiān shàng bān， xīn zī huì àn quán zhí biāo zhǔn fān bèi ma？','Tiểu Ngô, kỳ nghỉ hè đông tôi có thể làm cả ngày, vậy lương có được tính gấp đôi theo chuẩn full-time không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_02','V1120','小吴',2,'寒暑假单日工时不超合规上限，时薪上浮百分之三十，不算翻倍。','hán shǔ jià dān rì gōng shí bù chāo hé guī shàng xiàn， shí xīn shàng fú bǎi fēn zhī sān shí， bù suàn fān bèi。','Kỳ nghỉ hè đông nếu số giờ làm trong ngày không vượt mức quy định thì lương theo giờ tăng thêm ba mươi phần trăm, không tính là gấp đôi đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_03','V1120','阮明',3,'那法定节假日值班，三倍薪资是包含基础时薪在内吗？','nà fǎ dìng jié jià rì zhí bān， sān bèi xīn zī shì bāo hán jī chǔ shí xīn zài nèi ma？','Vậy trực vào ngày lễ pháp định, lương gấp ba đó có bao gồm cả lương giờ cơ bản không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_04','V1120','小吴',4,'三倍薪酬是额外叠加，当天基础工资照常发放，叠加三倍补贴。','sān bèi xīn chóu shì é wài dié jiā， dàng tiān jī chǔ gōng zī zhào cháng fā fàng， dié jiā sān bèi bǔ tiē。','Lương gấp ba là cộng thêm riêng, lương cơ bản ngày hôm đó vẫn trả bình thường, cộng thêm phần phụ cấp gấp ba lên trên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_05','V1120','阮明',5,'我清楚计算规则了，假期排班我可以多报名值班。','wǒ qīng chǔ jì suàn guī zé le， jià qī pái bān wǒ kě yǐ duō bào míng zhí bān。','Tôi hiểu cách tính rồi, đợt xếp ca nghỉ lễ tôi sẽ đăng ký trực nhiều hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_06','V1120','小吴',6,'好，需要假期排班提前一周和我说，我给你预留班次。','hǎo， xū yào jià qī pái bān tí qián yī zhōu hé wǒ shuō， wǒ gěi nǐ yù liú bān cì。','Được, cần xếp ca nghỉ lễ thì báo trước một tuần cho tôi, tôi sẽ giữ ca cho cậu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1120_07','V1120','阮明',7,'没问题，我会提前和你报备排班需求。','méi wèn tí， wǒ huì tí qián hé nǐ bào bèi pái bān xū qiú。','Không vấn đề gì, tôi sẽ báo trước nhu cầu xếp ca với chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1121','SVL2','企业发放现金工资，咨询是否合规、如何留存收入凭证',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1121','SIT1121','P1','twist','ban_chinh_thuc',NULL,'企业现金发薪合法，但外籍学生签证续签需要收入证明，现金发放需企业加盖公章出具纸质薪资证明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_01','V1121','阮明',1,'店长，咱们每月发现金工资，这样发放薪资是合规的吗？','diàn zhǎng， zán men měi yuè fā xiàn jīn gōng zī， zhè yàng fā fàng xīn zī shì hé guī de ma？','Cửa hàng trưởng, hàng tháng bên mình trả lương tiền mặt, vậy phát lương kiểu này có đúng quy định không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_02','V1121','王店长',2,'现金发放没问题，你每次签字领取工资条留存好就行。','xiàn jīn fà fàng méi wèn tí， nǐ měi cì qiān zì lǐng qǔ gōng zī tiáo liú cún hǎo jiù xíng。','Trả tiền mặt không sao cả, mỗi lần em ký nhận và giữ lại phiếu lương là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_03','V1121','阮明',3,'可是我需要薪资流水用来办理签证续签，现金没有转账记录怎么办？','kě shì wǒ xū yào xīn zī liú shuǐ yòng lái bàn lǐ qiān zhèng xù qiān， xiàn jīn méi yǒu zhuǎn zhàng jì lù zěn me bàn？','Nhưng mà em cần sao kê lương để làm thủ tục gia hạn visa, tiền mặt thì không có bản ghi chuyển khoản, vậy phải làm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_04','V1121','王店长',4,'我可以每月给你加盖门店公章的薪资证明，用来替代银行流水。','wǒ kě yǐ měi yuè gěi nǐ jiā gài mén diàn gōng zhāng de xīn zī zhèng míng， yòng lái tì dài yín háng liú shuǐ。','Anh có thể hàng tháng làm cho em giấy xác nhận lương có đóng dấu của cửa hàng, dùng để thay cho sao kê ngân hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_05','V1121','阮明',5,'每月都能开证明吗？出入境需要连续三个月收入凭证呢。','měi yuè dōu néng kāi zhèng míng ma？ chū rù jìng xū yào lián xù sān gè yuè shōu rù píng zhèng ne。','Tháng nào cũng làm được giấy xác nhận ạ? Bên xuất nhập cảnh yêu cầu chứng từ thu nhập liên tục ba tháng đó ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_06','V1121','王店长',6,'没问题，每月发薪当天我同步给你打印盖章薪资证明。','méi wèn tí， měi yuè fā xīn dàng tiān wǒ tóng bù gěi nǐ dǎ yìn gài zhāng xīn zī zhèng míng。','Không vấn đề gì, cứ đến ngày phát lương hàng tháng là anh in và đóng dấu giấy xác nhận lương gửi em luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1121_07','V1121','阮明',7,'太感谢了，这下不用担心签证材料缺少流水凭证。','tài gǎn xiè le， zhè xià bù yòng dān xīn qiān zhèng cái liào quē shǎo liú shuǐ píng zhèng。','Cảm ơn anh nhiều lắm, vậy là khỏi lo hồ sơ visa thiếu chứng từ thu nhập rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1122','SVL2','同事频繁推脱分配给自己的工作，委婉找主管协调分工',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1122','SIT1122','P1','suon_se','ban_chinh_thuc',NULL,'职场遇到同事推诿工作，优先向直属主管客观沟通协调，不直接和同事发生争执是国内职场通用处事方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_01','V1122','阮明',1,'陈主管，想和您沟通一下分工的小事，不知道您现在有空吗？','chén zhǔ guǎn， xiǎng hé nín gōu tōng yī xià fēn gōng de xiǎo shì， bù zhī dào nín xiàn zài yǒu kòng ma？','Chủ nhiệm Trần, em muốn trao đổi với chị một chút về việc phân công công việc, không biết chị có rảnh không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_02','V1122','陈主管',2,'你说，工作上有什么难处都可以直接和我讲。','nǐ shuō， gōng zuò shàng yǒu shén me nán chǔ dōu kě yǐ zhí jiē hé wǒ jiǎng。','Em cứ nói, công việc có khó khăn gì thì cứ nói thẳng với chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_03','V1122','阮明',3,'原本分配给另一位同事的工作，他总推脱交给我来完成。','yuán běn fèn pèi jǐ lìng yī wèi tóng shì de gōng zuò， tā zǒng tuī tuō jiāo gěi wǒ lái wán chéng。','Công việc vốn giao cho một bạn đồng nghiệp khác, nhưng bạn ấy cứ đùn đẩy giao cho em làm hết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_04','V1122','陈主管',4,'我清楚情况，等下我和那位同事单独沟通，明确各自岗位职责。','wǒ qīng chǔ qíng kuàng， děng xià wǒ hé nà wèi tóng shì dān dú gōu tōng， míng què gè zì gǎng wèi zhí zé。','Chị hiểu tình hình rồi, lát nữa chị sẽ nói chuyện riêng với bạn đó, làm rõ trách nhiệm của từng vị trí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_05','V1122','阮明',5,'我不是不愿意帮忙，只是自己手头任务也比较多，兼顾不过来。','wǒ bú shì bù yuàn yì bāng máng， zhǐ shì zì jǐ shǒu tóu rèn wù yě bǐ jiào duō， jiān gù bù guò lái。','Em không phải là không muốn giúp, chỉ là việc trong tay em cũng khá nhiều, không kham nổi thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_06','V1122','陈主管',6,'放心，我会划分清晰分工，不会让你额外承担不属于你的工作。','fàng xīn， wǒ huì huà fēn qīng xī fēn gōng， bú huì ràng nǐ é wài chéng dān bù shǔ yú nǐ de gōng zuò。','Yên tâm đi, chị sẽ phân công rõ ràng, không để em phải gánh thêm việc không thuộc phần của mình đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1122_07','V1122','阮明',7,'麻烦主管帮忙协调，我会做好自己分内所有工作。','má fán zhǔ guǎn bāng máng xié tiáo， wǒ huì zuò hǎo zì jǐ fèn nèi suǒ yǒu gōng zuò。','Phiền chị giúp em điều phối, em sẽ làm tốt hết phần việc của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1123','SVL2','团建聚餐临时无法到场，提前向主管请假说明理由',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1123','SIT1123','P1','suon_se','tuy_y',NULL,'公司团建属于团队集体活动，临时无法参加提前主动请假会被视作懂礼貌，无故缺席容易给领导留下负面印象。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_01','V1123','阮明',1,'陈主管，今晚公司团建聚餐我没办法到场，跟您提前请假啦。','chén zhǔ guǎn， jīn wǎn gōng sī tuán jiàn jù cān wǒ méi bàn fǎ dào chǎng， gēn nín tí qián qǐng jià la。','Chủ nhiệm Trần, tối nay tiệc liên hoan team building của công ty em không tham gia được, xin phép chị trước nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_02','V1123','陈主管',2,'怎么啦？是有什么重要的事情走不开吗？','zěn me la？ shì yǒu shén me zhòng yào de shì qíng zǒu bù kāi ma？','Sao vậy? Có việc gì quan trọng không dứt ra được à?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_03','V1123','阮明',3,'今晚要和国际学院老师沟通实习备案材料，时间刚好冲突了。','jīn wǎn yào hé guó jì xué yuàn lǎo shī gōu tōng shí xí bèi àn cái liào， shí jiān gāng hǎo chōng tū le。','Tối nay em phải trao đổi với thầy cô bên khoa quốc tế về hồ sơ đăng ký thực tập, đúng lúc trùng giờ luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_04','V1123','陈主管',4,'没事，工作要紧，团建不去不会扣全勤，不用有压力。','méi shì， gōng zuò yào jǐn， tuán jiàn bù qù bú huì kòu quán qín， bù yòng yǒu yā lì。','Không sao, công việc quan trọng hơn, không đi team building cũng không bị trừ điểm chuyên cần đâu, đừng lo lắng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_05','V1123','阮明',5,'真不好意思错过团队聚餐，下次团建我一定准时参加。','zhēn bù hǎo yì sī cuò guò tuán duì jù cān， xià cì tuán jiàn wǒ yí dìng zhǔn shí cān jiā。','Thật ngại quá vì lỡ buổi liên hoan của cả nhóm, lần sau team building em nhất định tham gia đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_06','V1123','陈主管',6,'没关系，我让同事帮你打包一份团建点心明天带给你。','méi guān xì， wǒ ràng tóng shì bāng nǐ dǎ bāo yī fèn tuán jiàn diǎn xīn míng tiān dài gěi nǐ。','Không sao đâu, chị nhờ đồng nghiệp gói cho em một phần đồ ăn của buổi team building, mai mang cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1123_07','V1123','阮明',7,'太贴心了，多谢主管体谅！','tài tiē xīn le， duō xiè zhǔ guǎn tǐ liàng！','Chị chu đáo quá, cảm ơn chị đã thông cảm nhiều nha!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1124','SVL2','老员工私下安排额外无偿杂活，礼貌拒绝并说明岗位职责',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1124','SIT1124','P1','that_bai_nhe','tuy_y',NULL,'国内职场可礼貌拒绝不属于自身岗位职责的无偿额外工作，无需勉强自己承担无报酬劳动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_01','V1124','阮明',1,'刘哥，下班之后打扫仓库不在我的岗位工作范围内，实在没办法帮忙啦。','liú gē， xià bān zhī hòu dǎ sǎo cāng kù bù zài wǒ de gǎng wèi gōng zuò fàn wéi nèi， shí zài méi bàn fǎ bāng máng la。','Anh Lưu ơi, dọn kho sau giờ làm không thuộc phạm vi công việc của em, thật sự em không giúp được ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_02','V1124','老刘',2,'大家都是同事，顺手做一下又不麻烦，不用分得这么清楚吧？','dà jiā dōu shì tóng shì， shùn shǒu zuò yī xià yòu bù má fán， bù yòng fēn de zhè me qīng chǔ ba？','Đồng nghiệp với nhau cả, tiện tay làm chút có phiền phức gì đâu, cần phải rạch ròi vậy à?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_03','V1124','阮明',3,'我下班要赶去学校上课，而且额外工作没有工时记录，不符合排班规定。','wǒ xià bān yào gǎn qù xué xiào shàng kè， ér qiě é wài gōng zuò méi yǒu gōng shí jì lù， bù fú hé pái bān guī dìng。','Em tan làm phải chạy đi học, với lại làm thêm ngoài giờ không được tính công, không đúng quy định phân ca ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_04','V1124','老刘',4,'就一小会儿，耽误不了你多长时间，大家平时都互相帮忙的。','jiù yī xiǎo huì er， dān wù bù liǎo nǐ duō zhǎng shí jiān， dà jiā píng shí dōu hù xiāng bāng máng de。','Có chút xíu thôi mà, tốn thời gian của em bao nhiêu đâu, mọi người bình thường vẫn hay giúp nhau mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_05','V1124','阮明',5,'实在抱歉，我今天课程不能迟到，您可以问问当班晚班同事。','shí zài bào qiàn， wǒ jīn tiān kè chéng bù néng chí dào， nín kě yǐ wèn wèn dāng bān wǎn bān tóng shì。','Thật sự xin lỗi anh, hôm nay em không thể trễ học được, anh hỏi mấy bạn ca tối xem sao.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_06','V1124','老刘',6,'行吧，那我自己来收拾，下次有时间再请你搭把手。','xíng ba， nà wǒ zì jǐ lái shōu shí， xià cì yǒu shí jiān zài qǐng nǐ dā bǎ shǒu。','Thôi được, vậy để anh tự dọn, lần sau rảnh thì giúp anh một tay nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1124_07','V1124','阮明',7,'实在不好意思，之后有空我会主动搭把手帮忙。','shí zài bù hǎo yì sī， zhī hòu yǒu kòng wǒ huì zhǔ dòng dā bǎ shǒu bāng máng。','Em thật sự ngại quá, lần sau rảnh em sẽ chủ động phụ giúp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1125','SVL2','中介收取高额兼职介绍费，拒绝付费并向市场监管投诉',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1125','SIT1125','P1','suon_se','chinh_thuc',NULL,'正规人力资源中介禁止提前收取高额介绍费，违规收费可向市场监督管理局举报维权。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_01','V1125','阮明',1,'小郑，还没上岗就要收五百元兼职介绍费，这个收费不合理。','xiǎo zhèng， hái méi shàng gǎng jiù yào shōu wǔ bǎi yuán jiān zhí jiè shào fèi， zhè ge shōu fèi bù hé lǐ。','Chị Trịnh, chưa đi làm mà đã thu năm trăm tệ phí giới thiệu việc làm thêm, mức phí này không hợp lý.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_02','V1125','小郑',2,'我们给你匹配优质岗位，介绍费是行业统一标准哦。','wǒ men gěi nǐ pǐ pèi yōu zhì gǎng wèi， jiè shào fèi shì háng yè tǒng yī biāo zhǔn ó。','Chúng tôi giúp bạn ghép công việc chất lượng, phí giới thiệu là mức chuẩn chung của ngành đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_03','V1125','阮明',3,'正规中介不能提前收取高额介绍费，我不会支付这笔费用。','zhèng guī zhōng jiè bù néng tí qián shōu qǔ gāo é jiè shào fèi， wǒ bú huì zhī fù zhè bǐ fèi yòng。','Trung tâm môi giới chính quy không được thu trước phí giới thiệu cao như vậy, tôi sẽ không trả khoản phí này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_04','V1125','小郑',4,'不交钱就不给你推送岗位信息，你自己很难找到合适兼职。','bù jiāo qián jiù bù gěi nǐ tuī sòng gǎng wèi xìn xī， nǐ zì jǐ hěn nán zhǎo dào hé shì jiān zhí。','Không nộp tiền thì chúng tôi sẽ không gửi thông tin việc làm cho bạn, bạn tự tìm việc phù hợp sẽ rất khó đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_05','V1125','阮明',5,'我会拨打市场监管热线投诉违规收费，再见。','wǒ huì bō dǎ shì chǎng jiān guǎn rè xiàn tóu sù wéi guī shōu fèi， zài jiàn。','Tôi sẽ gọi đường dây nóng quản lý thị trường để khiếu nại việc thu phí trái quy định, chào chị.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_06','V1125','小郑',6,'别投诉，我不收介绍费，直接免费给你推荐岗位行不行？','bié tóu sù， wǒ bù shōu jiè shào fèi， zhí jiē miǎn fèi gěi nǐ tuī jiàn gǎng wèi xíng bù xíng？','Đừng khiếu nại mà, hay là tôi không thu phí giới thiệu nữa, giới thiệu việc miễn phí luôn cho bạn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1125_07','V1125','阮明',7,'不必了，我不信任你们机构，会选择学校官方兼职渠道。','bù bì le， wǒ bù xìn rèn nǐ men jī gòu， huì xuǎn zé xué xiào guān fāng jiān zhí qú dào。','Không cần đâu, tôi không tin tưởng trung tâm của các người, tôi sẽ chọn kênh việc làm thêm chính thức của trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1126','SVL2','兼职老板拖欠工资失联，拨打12333劳动热线求助维权',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1126','SIT1126','P1','twist','chinh_thuc',NULL,'12333是全国统一劳动维权热线，外籍务工人员薪资拖欠纠纷可同等受理维权。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_01','V1126','阮明',1,'您好，我要投诉雇主拖欠我的兼职薪资，老板现在联系不上了。','nín hǎo， wǒ yào tóu sù gù zhǔ tuō qiàn wǒ de jiān zhí xīn zī， lǎo bǎn xiàn zài lián xì bù shàng le。','Chào anh/chị, tôi muốn khiếu nại việc chủ sử dụng lao động nợ lương làm thêm của tôi, giờ liên lạc không được với ông chủ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_02','V1126','接线员',2,'请提供用工门店地址、老板联系方式、你的兼职用工协议。','qǐng tí gōng yòng gōng mén diàn dì zhǐ、 lǎo bǎn lián xì fāng shì、 nǐ de jiān zhí yòng gōng xié yì。','Bạn vui lòng cung cấp địa chỉ cửa hàng sử dụng lao động, cách liên hệ với ông chủ, và hợp đồng làm thêm của bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_03','V1126','阮明',3,'协议纸质版放在宿舍，我只有微信排班记录和聊天截图凭证。','xié yì zhǐ zhì bǎn fàng zài sù shè， wǒ zhǐ yǒu wēi xìn pái bān jì lù hé liáo tiān jié tú píng zhèng。','Bản giấy của hợp đồng để ở ký túc xá, tôi chỉ có bản ghi phân ca trên WeChat và ảnh chụp màn hình tin nhắn làm bằng chứng thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_04','V1126','接线员',4,'截图可以作为辅助证据，下周携带纸质协议到辖区劳动监察大队登记。','jié tú kě yǐ zuò wéi fǔ zhù zhèng jù， xià zhōu xié dài zhǐ zhì xié yì dào xiá qū láo dòng jiān chá dà duì dēng jì。','Ảnh chụp màn hình có thể dùng làm chứng cứ bổ sung, tuần sau bạn mang bản giấy hợp đồng đến đội giám sát lao động khu vực để đăng ký nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_05','V1126','阮明',5,'我是外籍留学生，维权流程和国内学生一样吗？','wǒ shì wài jí liú xué shēng， wéi quán liú chéng hé guó nèi xué shēng yī yàng ma？','Tôi là du học sinh nước ngoài, quy trình bảo vệ quyền lợi có giống với sinh viên trong nước không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_06','V1126','接线员',6,'流程完全相同，携带护照、居留卡一同前往即可受理。','liú chéng wán quán xiāng tóng， xié dài hù zhào、 jū liú kǎ yī tóng qián wǎng jí kě shòu lǐ。','Quy trình hoàn toàn giống nhau, bạn mang theo hộ chiếu, thẻ cư trú đến là được tiếp nhận xử lý ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1126_07','V1126','阮明',7,'好的，我下周准时过去登记，麻烦你们帮忙追回薪资。','hǎo de， wǒ xià zhōu zhǔn shí guò qù dēng jì， má fán nǐ men bāng máng zhuī huí xīn zī。','Vâng ạ, tuần sau tôi sẽ đến đăng ký đúng giờ, phiền anh/chị giúp tôi đòi lại tiền lương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1127','SVL2','实习结束前，和人事确认实习证明盖章、发放时间',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1127','SIT1127','P1','suon_se','ban_chinh_thuc',NULL,'国内企业实习证明必须加盖公司公章，仅业务章、部门章学校不予认可，实习结束前需提前和人事确认开具时间。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_01','V1127','阮明',1,'小吴，我下周实习到期，想确认实习证明什么时候能盖章发放？','xiǎo wú， wǒ xià zhōu shí xí dào qī， xiǎng què rèn shí xí zhèng míng shén me shí hòu néng gài zhāng fā fàng？','Chị Ngô ơi, tuần sau là em hết thời gian thực tập rồi, em muốn xác nhận khi nào giấy chứng nhận thực tập được đóng dấu và phát ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_02','V1127','小吴',2,'你提交实习总结之后，三个工作日就能盖好公章交给你。','nǐ tí jiāo shí xí zǒng jié zhī hòu， sān gè gōng zuò rì jiù néng gài hǎo gōng zhāng jiāo gěi nǐ。','Sau khi em nộp bản tổng kết thực tập, ba ngày làm việc là có con dấu và giao cho em thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_03','V1127','阮明',3,'证明需要写明实习时长和我的岗位内容，方便学校归档对吧？','zhèng míng xū yào xiě míng shí xí shí cháng hé wǒ de gǎng wèi nèi róng， fāng biàn xué xiào guī dàng duì ba？','Giấy chứng nhận cần ghi rõ thời gian thực tập và nội dung công việc của em để trường tiện lưu hồ sơ đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_04','V1127','小吴',4,'标准模板都会标注完整信息，用于留学、学分认定都没问题。','biāo zhǔn mú bǎn dōu huì biāo zhù wán zhěng xìn xī， yòng yú liú xué、 xué fēn rèn dìng dōu méi wèn tí。','Mẫu chuẩn đều ghi đầy đủ thông tin, dùng để du học hay công nhận tín chỉ đều không vấn đề gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_05','V1127','阮明',5,'太好了，我今天写完实习总结马上交给你。','tài hǎo le， wǒ jīn tiān xiě wán shí xí zǒng jié mǎ shàng jiāo gěi nǐ。','Tuyệt quá ạ, hôm nay em viết xong bản tổng kết là nộp cho chị ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_06','V1127','小吴',6,'提交完成后我会优先给你办理，不耽误你交回学院。','tí jiāo wán chéng hòu wǒ huì yōu xiān gěi nǐ bàn lǐ， bù dān wù nǐ jiāo huí xué yuàn。','Sau khi em nộp xong chị sẽ ưu tiên làm cho em, không để trễ hạn nộp về khoa đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1127_07','V1127','阮明',7,'辛苦你啦，这份证明对我的学业履历很重要。','xīn kǔ nǐ la， zhè fèn zhèng míng duì wǒ de xué yè lǚ lì hěn zhòng yào。','Cảm ơn chị nhiều lắm, giấy chứng nhận này quan trọng với hồ sơ học tập của em lắm ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1128','SVL2','收到无薪资"免费实习"招聘邀约，咨询老师判断是否合规',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1128','SIT1128','P1','that_bai_nhe','ban_chinh_thuc',NULL,'留学生自主寻找的校外实习不属于教学必修实习，用人单位必须支付不低于当地最低兼职时薪的劳动报酬。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_01','V1128','阮明',1,'张老师，有家企业招无薪资免费实习，请问这种岗位合规吗？','zhāng lǎo shī， yǒu jiā qǐ yè zhāo wú xīn zī miǎn fèi shí xí， qǐng wèn zhè zhǒng gǎng wèi hé guī ma？','Cô Trương ơi, có một công ty tuyển thực tập không lương, cho em hỏi vị trí này có đúng quy định không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_02','V1128','张老师',2,'仅在校必修教学实习可无薪资，校外自主实习必须发放薪资。','jǐn zài xiào bì xiū jiào xué shí xí kě wú xīn zī， xiào wài zì zhǔ shí xí bì xū fà fàng xīn zī。','Chỉ có thực tập giảng dạy bắt buộc trong trường mới được không lương, thực tập ngoài trường tự nguyện thì bắt buộc phải trả lương.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_03','V1128','阮明',3,'这家企业说能积累履历，所以不支付实习工资，我有点心动。','zhè jiā qǐ yè shuō néng jī lěi lǚ lì， suǒ yǐ bù zhī fù shí xí gōng zī， wǒ yǒu diǎn xīn dòng。','Công ty này nói có thể tích lũy kinh nghiệm nên không trả lương thực tập, em thấy hơi xiêu lòng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_04','V1128','张老师',4,'无偿校外实习违反用工规定，企业会无偿占用你的劳动力。','wú cháng xiào wài shí xí wéi fǎn yòng gōng guī dìng， qǐ yè huì wú cháng zhàn yòng nǐ de láo dòng lì。','Thực tập ngoài trường không lương là vi phạm quy định lao động, công ty sẽ lợi dụng sức lao động của em mà không trả gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_05','V1128','阮明',5,'那我直接拒绝这个邀约，重新找有薪资的正规实习岗位？','nà wǒ zhí jiē jù jué zhè ge yāo yuē， chóng xīn zhǎo yǒu xīn zī de zhèng guī shí xí gǎng wèi？','Vậy em từ chối lời mời này luôn, tìm lại vị trí thực tập chính quy có lương ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_06','V1128','张老师',6,'没错，我可以转发学院正规实习招聘渠道给你参考。','méi cuò， wǒ kě yǐ zhuǎn fā xué yuàn zhèng guī shí xí zhāo pìn qú dào gěi nǐ cān kǎo。','Đúng vậy, cô có thể chuyển cho em kênh tuyển thực tập chính quy của khoa để tham khảo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1128_07','V1128','阮明',7,'多谢老师提醒，差点选择不合规的无偿实习岗位。','duō xiè lǎo shī tí xǐng， chà diǎn xuǎn zé bù hé guī de wú cháng shí xí gǎng wèi。','Em cảm ơn cô nhắc nhở nhiều lắm, suýt nữa em chọn nhầm vị trí thực tập không lương trái quy định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1129','SVL2','兼职结束办理工作交接，核对物品归还清单避免扣款',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1129','SIT1129','P1','suon_se','ban_chinh_thuc',NULL,'离职交接时务必双方共同核对工具、物品清单并签字留存，避免后续企业以物品丢失为由克扣薪资。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_01','V1129','阮明',1,'小吴，我今天办理兼职离职，我们核对一下物品归还清单吧。','xiǎo wú， wǒ jīn tiān bàn lǐ jiān zhí lí zhí， wǒ men hé duì yī xià wù pǐn guī huán qīng dān ba。','Chị Ngô, hôm nay em làm thủ tục nghỉ việc làm thêm, mình cùng đối chiếu danh sách bàn giao đồ đạc nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_02','V1129','小吴',2,'好，工作服、工作平板、储物柜钥匙全部带来了吗？','hǎo， gōng zuò fú、 gōng zuò píng bǎn、 chǔ wù guì yào shi quán bù dài lái le ma？','Ừ, đồng phục, máy tính bảng công việc, chìa khóa tủ đồ em mang theo đủ hết chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_03','V1129','阮明',3,'全部完好无损带来了，没有丢失、损坏任何工具物品。','quán bù wán hǎo wú sǔn dài lái le， méi yǒu diū shī、 sǔn huài rèn hé gōng jù wù pǐn。','Em mang đủ và còn nguyên vẹn hết ạ, không làm mất hay hư hỏng dụng cụ nào cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_04','V1129','小吴',4,'核对完毕，物品齐全，不会产生任何物品扣款。','hé duì wán bì， wù pǐn qí quán， bú huì chǎn shēng rèn hé wù pǐn kòu kuǎn。','Đối chiếu xong rồi, đồ đạc đầy đủ, sẽ không bị trừ tiền vì đồ đạc gì cả đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_05','V1129','阮明',5,'太好了，我还担心弄丢配件会扣除工资呢。','tài hǎo le， wǒ hái dān xīn nòng diū pèi jiàn huì kòu chú gōng zī ne。','May quá, em còn lo làm mất phụ kiện thì bị trừ lương ấy chứ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_06','V1129','小吴',6,'清单我签字一份给你留存，薪资会在当月发薪日正常到账。','qīng dān wǒ qiān zì yī fèn gěi nǐ liú cún， xīn zī huì zài dàng yuè fā xīn rì zhèng cháng dào zhàng。','Danh sách chị ký một bản để em giữ, lương sẽ về đúng ngày trả lương của tháng như bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1129_07','V1129','阮明',7,'多谢这段时间照顾，有需要我随时配合后续核对。','duō xiè zhè duàn shí jiān zhào gù， yǒu xū yào wǒ suí shí pèi hé hòu xù hé duì。','Em cảm ơn chị đã chăm sóc trong thời gian qua, cần gì chị cứ gọi em phối hợp đối chiếu thêm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1130','SVL2','暑期短期实习结束，咨询能否延长实习周期增加履历',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1130','SIT1130','P1','twist','ban_chinh_thuc',NULL,'短期实习延长周期需要企业管理层二次审批，外籍学生延长实习还需同步更新学校备案与出入境实习加注。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_01','V1130','阮明',1,'陈主管，我的暑期短期实习快结束了，想申请延长两个月实习周期。','chén zhǔ guǎn， wǒ de shǔ qī duǎn qī shí xí kuài jié shù le， xiǎng shēn qǐng yán cháng liǎng gè yuè shí xí zhōu qī。','Anh Trần, kỳ thực tập hè ngắn hạn của em sắp kết thúc rồi, em muốn xin gia hạn thêm hai tháng thực tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_02','V1130','陈主管',2,'门店现阶段人手充足，延长岗位我需要向上级申请审批。','mén diàn xiàn jiē duàn rén shǒu chōng zú， yán cháng gǎng wèi wǒ xū yào xiàng shàng jí shēn qǐng shěn pī。','Hiện tại cửa hàng đủ nhân lực rồi, việc gia hạn vị trí anh phải xin phê duyệt từ cấp trên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_03','V1130','阮明',3,'我这段实习的工作表现您也清楚，我愿意继续认真完成工作。','wǒ zhè duàn shí xí de gōng zuò biǎo xiàn nín yě qīng chǔ， wǒ yuàn yì jì xù rèn zhēn wán chéng gōng zuò。','Anh cũng biết kết quả làm việc của em trong đợt thực tập này rồi, em sẵn sàng tiếp tục làm việc nghiêm túc ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_04','V1130','陈主管',4,'我明天向上级提交申请，三天内给你答复消息吧。','wǒ míng tiān xiàng shàng jí tí jiāo shēn qǐng， sān tiān nèi gěi nǐ dá fù xiāo xī ba。','Ngày mai anh sẽ nộp đơn xin lên cấp trên, trong ba ngày sẽ có phản hồi cho em nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_05','V1130','阮明',5,'如果审批不通过，我能不能之后寒暑假再来短期实习？','rú guǒ shěn pī bù tōng guò， wǒ néng bù néng zhī hòu hán shǔ jià zài lái duǎn qī shí xí？','Nếu không được duyệt, sau này em có thể quay lại thực tập ngắn hạn vào kỳ nghỉ hè, nghỉ đông không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_06','V1130','陈主管',6,'当然可以，门店长期接收留学生短期实习，优先录用你。','dāng rán kě yǐ， mén diàn zhǎng qī jiē shōu liú xué shēng duǎn qī shí xí， yōu xiān lù yòng nǐ。','Đương nhiên được, cửa hàng lâu nay vẫn nhận du học sinh thực tập ngắn hạn, sẽ ưu tiên nhận em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1130_07','V1130','阮明',7,'麻烦主管帮忙提交申请，我会耐心等待审批结果。','má fán zhǔ guǎn bāng máng tí jiāo shēn qǐng， wǒ huì nài xīn děng dài shěn pī jié guǒ。','Phiền anh giúp em nộp đơn xin, em sẽ kiên nhẫn chờ kết quả phê duyệt ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1201','SDL1','高铁站自助机取纸质车票，证件识别失败',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1201','SIT1201','P1','twist','ban_chinh_thuc',NULL,'国内高铁站外籍证件自助识别常失灵，人工窗口可优先处理外籍旅客票务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_01','V1201','阮明',1,'您好啊，这台取票机一直识别不了我的护照，该怎么办呢？','nín hǎo a ， zhè tái qǔ piào jī yì zhí shí bié bù liǎo wǒ de hù zhào ， gāi zěn me bàn ne ？','Chào chị ạ, cái máy lấy vé này cứ không nhận diện được hộ chiếu của em, giờ phải làm sao ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_02','V1201','李姐',2,'小伙子别急，先把护照拿给我看看吧，是不是页面折到啦？','xiǎo huǒ zi bié jí ， xiān bǎ hù zhào ná gěi wǒ kàn kàn ba ， shì bú shì yè miàn zhé dào la ？','Cậu đừng vội, đưa hộ chiếu đây chị xem thử, có phải trang bị gấp nếp không?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_03','V1201','阮明',3,'我一路都小心放好的，没有弯折，就是扫了五次都失败啦。','wǒ yī lù dōu xiǎo xīn fàng hǎo de ， méi yǒu wān zhé ， jiù shì sǎo le wǔ cì dōu shī bài la 。','Em cất cẩn thận suốt đường mà, không bị gấp nếp gì cả, chỉ là quét năm lần đều thất bại thôi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_04','V1201','李姐',4,'外籍护照芯片容易受潮，你先用纸巾擦一下护照封面芯片位置。','wài jí hù zhào xīn piàn róng yì shòu cháo ， nǐ xiān yòng zhǐ jīn cā yī xià hù zhào fēng miàn xīn piàn wèi zhì 。','Hộ chiếu nước ngoài chip dễ bị ẩm lắm, cậu lấy khăn giấy lau thử chỗ chip ở bìa hộ chiếu xem.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_05','V1201','阮明',5,'好，我现在擦，擦完再试一次行不行？','hǎo ， wǒ xiàn zài cā ， cā wán zài shì yī cì xíng bù xíng ？','Vâng, em lau ngay đây, lau xong thử lại lần nữa được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_06','V1201','李姐',6,'要是还是不行，咱们就去人工窗口排队取票嘛，不耽误你坐车。','yào shì hái shì bù xíng ， zán men jiù qù rén gōng chuāng kǒu pái duì qǔ piào ma ， bù dān wù nǐ zuò chē 。','Nếu vẫn không được thì mình ra quầy nhân viên xếp hàng lấy vé, không lỡ chuyến tàu của cậu đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1201_07','V1201','阮明',7,'太谢谢您了，要是没有您帮忙，我真要赶不上高铁咯。','tài xiè xiè nín le ， yào shì méi yǒu nín bāng máng ， wǒ zhēn yào gǎn bù shàng gāo tiě gē 。','Em cảm ơn chị nhiều lắm, nếu không có chị giúp chắc em lỡ chuyến tàu cao tốc mất rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1202','SDL1','景区线下窗口买学生优惠票，忘记带留学生证',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1202','SIT1202','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内绝大多数景区学生优惠仅限实体学生证，证件照片一般不认可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_01','V1202','阮明',1,'你好，我想买学生优惠门票，可以便宜一半对吧？','nǐ hǎo ， wǒ xiǎng mǎi xué shēng yōu huì mén piào ， kě yǐ pián yi yí bàn duì ba ？','Chào anh, em muốn mua vé ưu đãi sinh viên, được giảm nửa giá đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_02','V1202','小张',2,'可以的呀，麻烦出示你的有效学生证或者留学生证件吧。','kě yǐ de ya ， má fán chū shì nǐ de yǒu xiào xué shēng zhèng huò zhě liú xué shēng zhèng jiàn ba 。','Được ạ, phiền bạn xuất trình thẻ sinh viên còn hiệu lực hoặc giấy tờ du học sinh nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_03','V1202','阮明',3,'糟糕，我出门只带了护照，留学生证落在宿舍了呢。','zāo gāo ， wǒ chū mén zhǐ dài le hù zhào ， liú xué shēng zhèng luò zài sù shè le ne 。','Chết rồi, em ra ngoài chỉ mang theo hộ chiếu thôi, thẻ du học sinh để quên ở ký túc xá rồi ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_04','V1202','小张',4,'不好意思啦，景区规定必须出示实体学生证件才能享受优惠。','bù hǎo yì sī la ， jǐng qū guī dìng bì xū chū shì shí tǐ xué shēng zhèng jiàn cái néng xiǎng shòu yōu huì 。','Xin lỗi bạn nhé, quy định khu du lịch là phải xuất trình thẻ sinh viên bản gốc mới được hưởng ưu đãi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_05','V1202','阮明',5,'那出示手机里证件照片也不行吗？','nà chū shì shǒu jī lǐ zhèng jiàn zhào piān yě bù xíng ma ？','Vậy cho xem ảnh chụp giấy tờ trong điện thoại cũng không được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_06','V1202','小张',6,'不行哦，照片无法核实原件，只能购买全价成人票咯。','bù xíng ó ， zhào piān wú fǎ hé shí yuán jiàn ， zhǐ néng gòu mǎi quán jià chéng rén piào gē 。','Không được đâu, ảnh chụp không thể xác minh được bản gốc, bạn chỉ có thể mua vé người lớn giá đầy đủ thôi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1202_07','V1202','阮明',7,'好吧，那我买一张全价票，下次出门一定记得带证件。','hǎo ba ， nà wǒ mǎi yī zhāng quán jià piào ， xià cì chū mén yí dìng jì de dài zhèng jiàn 。','Thôi được, vậy em mua một vé giá đầy đủ vậy, lần sau ra ngoài nhất định phải nhớ mang giấy tờ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1203','SDL1','民宿前台办理入住，房东要求登记外籍护照',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1203','SIT1203','P1','suon_se','tuy_y',NULL,'国内民宿、酒店法律规定外籍入住必须实名登记护照，同步上传公安系统。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_01','V1203','王阿姨',1,'小伙子来啦，提前预约好房间了吧？','xiǎo huǒ zi lái la ， tí qián yù yuē hǎo fáng jiān le ba ？','Cháu đến rồi à, đặt phòng trước rồi chứ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_02','V1203','阮明',2,'是的阿姨，我叫阮明，今天过来办理入住啦。','shì de ā yí ， wǒ jiào ruǎn míng ， jīn tiān guò lái bàn lǐ rù zhù la 。','Vâng ạ cô, cháu tên Nguyễn Minh, hôm nay đến làm thủ tục nhận phòng ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_03','V1203','王阿姨',3,'外籍客人要登记护照信息哦，把护照给我复印一下行吗？','wài jí kè rén yào dēng jì hù zhào xìn xī ó ， bǎ hù zhào gěi wǒ fù yìn yī xià xíng ma ？','Khách nước ngoài phải đăng ký thông tin hộ chiếu đó, đưa hộ chiếu cho cô photo một chút nhé?','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_04','V1203','阮明',4,'没问题，护照在这里，登记大概要多久啊？','méi wèn tí ， hù zhào zài zhè lǐ ， dēng jì dà gài yào duō jiǔ a ？','Dạ được, hộ chiếu đây ạ, đăng ký khoảng bao lâu vậy cô?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_05','V1203','王阿姨',5,'几分钟就搞定啦，登记完我把房门钥匙给你。','jǐ fēn zhōng jiù gǎo dìng la ， dēng jì wán wǒ bǎ fáng mén yào shi gěi nǐ 。','Vài phút là xong thôi, đăng ký xong cô đưa chìa khóa phòng cho cháu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_06','V1203','阮明',6,'辛苦您啦，请问房间WiFi密码是多少呢？','xīn kǔ nín la ， qǐng wèn fáng jiān WiFi mì mǎ shì duō shǎo ne ？','Cô vất vả rồi ạ, cho cháu hỏi mật khẩu WiFi phòng là gì ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1203_07','V1203','王阿姨',7,'密码贴在房间门后，有任何事直接微信喊我就行咯。','mì mǎ tiē zài fáng jiān mén hòu ， yǒu rèn hé shì zhí jiē wēi xìn hǎn wǒ jiù xíng gē 。','Mật khẩu dán ở sau cửa phòng đó, có việc gì cứ nhắn WeChat gọi cô là được.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1204','SDL1','旅游景区迷路，向本地中老年路人问路',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1204','SIT1204','P1','suon_se','tuy_y',NULL,'国内中老年路人大多热心指路，聊天时常会主动夸赞外国人中文，拉近距离。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_01','V1204','阮明',1,'大爷您好，打扰一下，请问山顶观景台往哪边走呀？','dà yé nín hǎo ， dǎ rǎo yī xià ， qǐng wèn shān dǐng guān jǐng tái wǎng nǎ biān zǒu ya ？','Chào ông ạ, làm phiền ông một chút, cho cháu hỏi đài ngắm cảnh trên đỉnh núi đi hướng nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_02','V1204','大爷',2,'小伙子是外国来的留学生吧，普通话讲得挺标准嘛！','xiǎo huǒ zi shì wài guó lái de liú xué shēng ba ， pǔ tōng huà jiǎng dé tǐng biāo zhǔn ma ！','Cậu là du học sinh nước ngoài đúng không, nói tiếng phổ thông chuẩn ghê!','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_03','V1204','阮明',3,'谢谢您夸奖，我来中国读书两年啦，今天第一次来这个景区。','xiè xiè nín kuā jiǎng ， wǒ lái zhōng guó dú shū liǎng nián la ， jīn tiān dì yī cì lái zhè ge jǐng qū 。','Cảm ơn ông khen ạ, cháu sang Trung Quốc học đã hai năm rồi, hôm nay là lần đầu cháu đến khu du lịch này.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_04','V1204','大爷',4,'你顺着这条石板路一直往上走，看见红色亭子右转就是咯。','nǐ shùn zhe zhè tiáo shí bǎn lù yì zhí wǎng shàng zǒu ， kàn jiàn hóng sè tíng zi yòu zhuǎn jiù shì gē 。','Cậu cứ theo con đường lát đá này đi thẳng lên, thấy cái đình màu đỏ thì rẽ phải là tới.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_05','V1204','阮明',5,'大概还要走多久才能到呢？','dà gài hái yào zǒu duō jiǔ cái néng dào ne ？','Còn phải đi khoảng bao lâu nữa mới tới ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_06','V1204','大爷',6,'二十分钟左右，路上台阶有点陡，慢慢走别着急哈。','èr shí fēn zhōng zuǒ yòu ， lù shàng tái jiē yǒu diǎn dǒu ， màn màn zǒu bié zháo jí hā 。','Khoảng hai mươi phút, đường có mấy bậc thang hơi dốc, cứ đi từ từ đừng vội nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1204_07','V1204','阮明',7,'太感谢您啦，不然我还要绕好久弯路呢。','tài gǎn xiè nín la ， bù rán wǒ hái yào rào hǎo jiǔ wān lù ne 。','Cháu cảm ơn ông nhiều lắm, không thì cháu còn phải đi vòng vèo lâu lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1205','SDL1','网红小吃店排队点餐，看不懂中文手写菜单',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1205','SIT1205','P1','twist','tuy_y',NULL,'街边小店多用手写毛笔菜单，字体潦草，外国游客看不懂很常见，店员一般会耐心介绍菜品。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_01','V1205','阮明',1,'你好，墙上手写菜单我好多字看不懂，可以给我推荐招牌吗？','nǐ hǎo ， qiáng shàng shǒu xiě cài dān wǒ hǎo duō zì kàn bù dǒng ， kě yǐ gěi wǒ tuī jiàn zhāo pái ma ？','Chào bạn, thực đơn viết tay trên tường mình không hiểu nhiều chữ lắm, bạn giới thiệu giúp mình món đặc trưng được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_02','V1205','小林',2,'当然可以啦，咱们店招牌酸辣粉、红糖糍粑都很好卖的。','dāng rán kě yǐ la ， zán men diàn zhāo pái suān là fěn 、 hóng táng cí bā dōu hěn hǎo mài de 。','Được chứ, quán mình món tủ là mì chua cay và bánh nếp đường đỏ đều bán chạy lắm.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_03','V1205','阮明',3,'酸辣粉会不会特别辣呀，我不太能吃辣呢。','suān là fěn huì bú huì tè bié là ya ， wǒ bù tài néng chī là ne 。','Mì chua cay có cay lắm không, mình không ăn cay giỏi lắm.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_04','V1205','小林',4,'没关系嘛，我可以给你做微辣，几乎没什么辣味。','méi guān xì ma ， wǒ kě yǐ gěi nǐ zuò wēi là ， jī hū méi shén me là wèi 。','Không sao đâu, mình có thể làm cho bạn vị hơi cay thôi, gần như không cay mấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_05','V1205','阮明',5,'那我一份微辣酸辣粉，再加一份糍粑吧。','nà wǒ yī fèn wēi là suān là fěn ， zài jiā yī fèn cí bā ba 。','Vậy cho mình một phần mì chua cay hơi cay, thêm một phần bánh nếp nữa nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_06','V1205','小林',6,'好嘞，一共二十二元，扫码付款就行啦。','hǎo lei ， yī gòng èr shí èr yuán ， sǎo mǎ fù kuǎn jiù xíng la 。','Được luôn, tổng cộng hai mươi hai tệ, quét mã thanh toán là xong.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1205_07','V1205','阮明',7,'麻烦稍微快一点哦，我等下还要去逛隔壁古街。','má fán shāo wēi kuài yì diǎn ó ， wǒ děng xià hái yào qù guàng gé bì gǔ jiē 。','Phiền bạn làm nhanh giúp mình chút nhé, lát nữa mình còn phải đi dạo phố cổ bên cạnh.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1206','SDL1','景区卫生间找不到，询问保洁阿姨',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1206','SIT1206','P1','suon_se','tuy_y',NULL,'国内公立景区公共卫生间全部免费，街边部分私人厕所才会收费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1206_01','V1206','阮明',1,'阿姨不好意思，想问一下洗手间在哪里呀？','ā yí bù hǎo yì sī ， xiǎng wèn yī xià xǐ shǒu jiān zài nǎ lǐ ya ？','Cô ơi cho cháu hỏi, nhà vệ sinh ở đâu vậy ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1206_02','V1206','刘阿姨',2,'往前直走五十米，大树旁边那个小房子就是啦。','wǎng qián zhí zǒu wǔ shí mǐ ， dà shù páng biān nà ge xiǎo fáng zi jiù shì la 。','Đi thẳng về phía trước năm mươi mét, cái nhà nhỏ cạnh cây to đó là đúng rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1206_03','V1206','阮明',3,'是免费使用的卫生间吗，要不要扫码付费呢？','shì miǎn fèi shǐ yòng de wèi shēng jiān ma ， yào bù yào sǎo mǎ fù fèi ne ？','Đây là nhà vệ sinh miễn phí phải không cô, có cần quét mã trả tiền không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1206_04','V1206','刘阿姨',4,'景区里面卫生间全都免费，不用花钱的哈。','jǐng qū lǐ miàn wèi shēng jiān quán dōu miǎn fèi ， bù yòng huā qián de hā 。','Nhà vệ sinh trong khu du lịch đều miễn phí hết, không cần trả tiền đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1206_05','V1206','阮明',5,'太谢谢您啦，我找半天都没看见指示牌呢。','tài xiè xiè nín la ， wǒ zhǎo bàn tiān dōu méi kàn jiàn zhǐ shì pái ne 。','Cháu cảm ơn cô nhiều lắm, cháu tìm mãi mà không thấy biển chỉ dẫn gì cả.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1207','SDL1','乘坐市内旅游公交，不会刷外籍电子乘车码',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1207','SIT1207','P1','twist','ban_chinh_thuc',NULL,'国内公交电子乘车码大多绑定国内手机号、银行卡，外籍游客很难直接开通，现金零钱是备用方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_01','V1207','阮明',1,'师傅您好，我的手机弄不出乘车码，刷不了车怎么办啊？','shī fù nín hǎo ， wǒ de shǒu jī nòng bù chū chéng chē mǎ ， shuā bù liǎo chē zěn me bàn a ？','Chào bác tài, điện thoại em không hiện được mã lên xe, không quẹt được thì phải làm sao ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_02','V1207','陈师傅',2,'小伙子是外国留学生吧，没有国内银行卡办不了乘车码呢。','xiǎo huǒ zi shì wài guó liú xué shēng ba ， méi yǒu guó nèi yín háng kǎ bàn bù liǎo chéng chē mǎ ne 。','Cậu là du học sinh nước ngoài đúng không, không có thẻ ngân hàng trong nước thì không làm được mã lên xe đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_03','V1207','阮明',3,'那我只能投现金吗，我身上只有一百块的纸币，没有零钱。','nà wǒ zhǐ néng tóu xiàn jīn ma ， wǒ shēn shàng zhǐ yǒu yì bǎi kuài de zhǐ bì ， méi yǒu líng qián 。','Vậy em chỉ có thể bỏ tiền mặt thôi ạ, em chỉ có tờ một trăm tệ, không có tiền lẻ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_04','V1207','陈师傅',4,'公交不找零哦，前面站台有便利店，你去换两块零钱再来吧。','gōng jiāo bù zhǎo líng ó ， qián miàn zhàn tái yǒu biàn lì diàn ， nǐ qù huàn liǎng kuài líng qián zài lái ba 。','Xe buýt không thối tiền đâu, phía trước có trạm có cửa hàng tiện lợi, cậu qua đó đổi vài đồng tiền lẻ rồi quay lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_05','V1207','阮明',5,'可是车马上要开了，我赶时间去博物馆呢。','kě shì chē mǎ shàng yào kāi le ， wǒ gǎn shí jiān qù bó wù guǎn ne 。','Nhưng xe sắp chạy rồi ạ, em đang gấp giờ đi bảo tàng.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_06','V1207','陈师傅',6,'没关系，这次你先上车，下次提前备好零钱就行啦。','méi guān xì ， zhè cì nǐ xiān shàng chē ， xià cì tí qián bèi hǎo líng qián jiù xíng la 。','Không sao, lần này cậu cứ lên xe trước đi, lần sau chuẩn bị sẵn tiền lẻ là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1207_07','V1207','阮明',7,'太感谢您了，下次我一定提前换好零钱。','tài gǎn xiè nín le ， xià cì wǒ yí dìng tí qián huàn hǎo líng qián 。','Em cảm ơn bác nhiều lắm, lần sau em nhất định sẽ đổi sẵn tiền lẻ trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1208','SDL1','古镇街边小店想买手工纪念品，和老板砍价',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1208','SIT1208','P1','suon_se','tuy_y',NULL,'古镇小商品店铺都可以议价，明码标价商场不能砍价，街边小店默认对半还价再协商。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_01','V1208','阮明',1,'老板，这个木雕小摆件多少钱一个呀？','lǎo bǎn ， zhè ge mù diāo xiǎo bǎi jiàn duō shǎo qián yí gè ya ？','Anh chủ ơi, cái tượng gỗ chạm nhỏ này bao nhiêu tiền một cái vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_02','V1208','老周',2,'原价八十，喜欢的话给你算七十吧。','yuán jià bā shí ， xǐ huān de huà gěi nǐ suàn qī shí ba 。','Giá gốc tám mươi, nếu thích thì tính cho cậu bảy mươi vậy.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_03','V1208','阮明',3,'七十有点贵咯，五十块我直接拿两个行不行？','qī shí yǒu diǎn guì gē ， wǔ shí kuài wǒ zhí jiē ná liǎng gè xíng bù xíng ？','Bảy mươi hơi đắt đó, năm mươi tệ em lấy luôn hai cái được không anh?','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_04','V1208','老周',4,'小伙子还挺会砍价，五十本钱都不够，六十两个给你啦。','xiǎo huǒ zi hái tǐng huì kǎn jià ， wǔ shí běn qián dōu bù gòu ， liù shí liǎng gè gěi nǐ la 。','Cậu này mặc cả giỏi thật đấy, năm mươi thì không đủ vốn đâu, sáu mươi hai cái tính cho cậu vậy.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_05','V1208','阮明',5,'六十可以，我多拿一个送给国内同学嘛。','liù shí kě yǐ ， wǒ duō ná yí gè sòng gěi guó nèi tóng xué ma 。','Sáu mươi được đó, em lấy thêm một cái để tặng bạn học người Trung Quốc.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_06','V1208','老周',6,'行嘞，我给你包装好看一点，送人有面子哈。','xíng lei ， wǒ gěi nǐ bāo zhuāng hǎo kàn yì diǎn ， sòng rén yǒu miàn zi hā 。','Được luôn, anh gói cho cậu đẹp một chút, tặng người ta cho có mặt mũi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1208_07','V1208','阮明',7,'麻烦您啦，以后我带同学再来光顾您小店。','má fán nín la ， yǐ hòu wǒ dài tóng xué zài lái guāng gù nín xiǎo diàn 。','Cảm ơn anh nhiều ạ, sau này em sẽ dẫn bạn học đến ủng hộ tiệm anh nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1209','SDL1','预约博物馆线上门票，选错参观日期无法入场',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1209','SIT1209','P1','that_bai_nhe','ban_chinh_thuc',NULL,'公立博物馆免费预约票严格限定参观日期，过期作废，不支持改签、退票。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_01','V1209','阮明',1,'您好，我扫码检票怎么显示门票日期不对呢？','nín hǎo ， wǒ sǎo mǎ jiǎn piào zěn me xiǎn shì mén piào rì qī bú duì ne ？','Chào chị, em quét mã kiểm vé sao cứ hiện ngày trên vé không đúng vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_02','V1209','小吴',2,'我帮你看一下，你预约的是昨天的票，今天已经过期啦。','wǒ bāng nǐ kàn yī xià ， nǐ yù yuē de shì zuó tiān de piào ， jīn tiān yǐ jīng guò qī la 。','Để chị xem cho nhé, vé em đặt là của ngày hôm qua, hôm nay hết hạn rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_03','V1209','阮明',3,'哎呀，我昨天记错时间没来，以为门票可以改期呢。','āi yā ， wǒ zuó tiān jì cuò shí jiān méi lái ， yǐ wéi mén piào kě yǐ gǎi qī ne 。','Ôi, hôm qua em nhớ nhầm giờ nên không đến, cứ tưởng vé đổi ngày được cơ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_04','V1209','小吴',4,'博物馆线上预约票一旦选定日期不能更改，过期直接作废咯。','bó wù guǎn xiàn shàng yù yuē piào yí dàn xuǎn dìng rì qī bù néng gēng gǎi ， guò qī zhí jiē zuò fèi gē 。','Vé đặt online của bảo tàng một khi đã chọn ngày là không đổi được đâu, hết hạn là hủy luôn.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_05','V1209','阮明',5,'那我现在能现场重新买票进去参观吗？','nà wǒ xiàn zài néng xiàn chǎng chóng xīn mǎi piào jìn qù cān guān ma ？','Vậy giờ em có thể mua vé tại chỗ để vào tham quan không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_06','V1209','小吴',6,'今天名额已经约满，只能明天再来预约啦。','jīn tiān míng é yǐ jīng yuē mǎn ， zhǐ néng míng tiān zài lái yù yuē la 。','Suất hôm nay kín chỗ hết rồi, em chỉ có thể mai quay lại đặt vé thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1209_07','V1209','阮明',7,'好吧，都怪我自己粗心看错日期，明天我一定记准时间。','hǎo ba ， dōu guài wǒ zì jǐ cū xīn kàn cuò rì qī ， míng tiān wǒ yí dìng jì zhǔn shí jiān 。','Thôi vậy, tại em bất cẩn xem nhầm ngày, mai em sẽ nhớ kỹ giờ giấc.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1210','SDL1','爬山途中下雨，在山顶小卖部临时买雨衣',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1210','SIT1210','P1','suon_se','tuy_y',NULL,'山顶、景区制高点商品运输困难，物价普遍高于市区，属于正常现象。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_01','V1210','阮明',1,'老板娘，外面突然下雨啦，一次性雨衣多少钱一件？','lǎo bǎn niáng ， wài miàn tū rán xià yǔ la ， yí cì xìng yǔ yī duō shǎo qián yī jiàn ？','Cô ơi, bên ngoài trời mưa bất chợt quá, áo mưa dùng một lần bao nhiêu tiền một cái vậy cô?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_02','V1210','老板娘',2,'山上雨水大，雨衣十元一件，质量厚实不容易破哦。','shān shàng yǔ shuǐ dà ， yǔ yī shí yuán yī jiàn ， zhì liàng hòu shí bù róng yì pò ó 。','Trên núi mưa to lắm, áo mưa mười tệ một cái, chất dày dặn không dễ rách đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_03','V1210','阮明',3,'给我来两件吧，等下下山山路滑，怕淋湿手机。','gěi wǒ lái liǎng jiàn ba ， děng xià xià shān shān lù huá ， pà lín shī shǒu jī 。','Cô cho cháu lấy hai cái đi, lát xuống núi đường trơn, cháu sợ ướt điện thoại.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_04','V1210','老板娘',4,'好嘞，两件二十，雨衣口袋还能装手机呢。','hǎo lei ， liǎng jiàn èr shí ， yǔ yī kǒu dài hái néng zhuāng shǒu jī ne 。','Được rồi, hai cái hai mươi tệ, túi áo mưa còn để vừa điện thoại đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_05','V1210','阮明',5,'山顶东西价格比山下贵好多，没办法应急只能买啦。','shān dǐng dōng xī jià gé bǐ shān xià guì hǎo duō ， méi bàn fǎ yìng jí zhǐ néng mǎi la 。','Đồ trên đỉnh núi giá đắt hơn dưới chân núi nhiều thật, nhưng cần gấp nên đành mua thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_06','V1210','老板娘',6,'山上运输不方便，成本高一点，多多理解哈。','shān shàng yùn shū bù fāng biàn ， chéng běn gāo yì diǎn ， duō duō lǐ jiě hā 。','Trên núi vận chuyển bất tiện, chi phí cao hơn một chút, mong cháu thông cảm nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1210_07','V1210','阮明',7,'没关系，谢谢您，这下下山不会淋雨咯。','méi guān xì ， xiè xiè nín ， zhè xià xià shān bú huì lín yǔ gē 。','Không sao đâu cô, cảm ơn cô, lần này xuống núi khỏi lo bị ướt mưa rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1211','SDL1','打车去景点，司机听不懂地名开错路线',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1211','SIT1211','P1','twist','ban_chinh_thuc',NULL,'网约车司机走错路线，多出路费一般由司机自行承担，乘客无需额外付费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_01','V1211','阮明',1,'师傅，我要去城南古戏台景区，导航定位发给您啦。','shī fù ， wǒ yào qù chéng nán gǔ xì tái jǐng qū ， dǎo háng dìng wèi fā gěi nín la 。','Anh ơi, em muốn đến khu du lịch sân khấu cổ ở phía nam thành phố, em gửi định vị chỉ đường cho anh rồi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_02','V1211','赵师傅',2,'我看看，这地方名字有点绕，我刚才开岔路口咯。','wǒ kàn kàn ， zhè dì fāng míng zì yǒu diǎn rào ， wǒ gāng cái kāi chà lù kǒu gē 。','Để anh xem, tên chỗ này hơi rối, vừa nãy anh chạy nhầm ngã rẽ rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_03','V1211','阮明',3,'那现在绕回去会不会耽误很久啊，我预约了下午的讲解。','nà xiàn zài rào huí qù huì bú huì dān wù hěn jiǔ a ， wǒ yù yuē le xià wǔ de jiǎng jiě 。','Vậy giờ vòng lại có mất nhiều thời gian không ạ, em có hẹn giờ nghe thuyết minh buổi chiều.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_04','V1211','赵师傅',4,'放心，绕路不远，十分钟就能到，多出来的路费算我的。','fàng xīn ， rào lù bù yuǎn ， shí fēn zhōng jiù néng dào ， duō chū lái de lù fèi suàn wǒ de 。','Yên tâm đi, đường vòng không xa đâu, mười phút là tới, tiền cước phát sinh anh chịu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_05','V1211','阮明',5,'不用您承担全部，咱们一人一半也行吧？','bù yòng nín chéng dān quán bù ， zán men yī rén yí bàn yě xíng ba ？','Không cần anh chịu hết đâu, hay mình chia đôi vậy được không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_06','V1211','赵师傅',6,'不用不用，是我没看清定位，不能多收你的钱嘛。','bù yòng bù yòng ， shì wǒ méi kàn qīng dìng wèi ， bù néng duō shōu nǐ de qián ma 。','Thôi khỏi khỏi, tại anh xem định vị không kỹ, không thể thu thêm tiền của em được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1211_07','V1211','阮明',7,'您人真好，下次打车我还会选您的车。','nín rén zhēn hǎo ， xià cì dǎ chē wǒ hái huì xuǎn nín de chē 。','Anh tốt bụng quá, lần sau đi taxi em sẽ chọn xe anh nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1212','SDL1','景区文创店商品破损，申请更换新品',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1212','SIT1212','P1','suon_se','ban_chinh_thuc',NULL,'线下实体店当日未使用破损商品，凭购物小票大多支持免费更换，无小票很难售后。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_01','V1212','阮明',1,'你好，我刚买单的陶瓷书签边缘裂了，能换一个吗？','nǐ hǎo ， wǒ gāng mǎi dān de táo cí shū qiān biān yuán liè le ， néng huàn yí gè ma ？','Chào chị, thẻ đánh dấu sách bằng gốm em vừa thanh toán bị nứt ở mép, đổi cái khác được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_02','V1212','小苏',2,'先给我看看破损的地方，还有购物小票带来了吧？','xiān gěi wǒ kàn kàn pò sǔn de dì fāng ， hái yǒu gòu wù xiǎo piào dài lái le ba ？','Em cho chị xem chỗ bị hỏng trước đã, với lại em có mang theo hóa đơn mua hàng không?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_03','V1212','阮明',3,'小票在这里，我刚拆开包装就发现坏掉啦，还没带出店铺呢。','xiǎo piào zài zhè lǐ ， wǒ gāng chāi kāi bāo zhuāng jiù fā xiàn huài diào la ， hái méi dài chū diàn pù ne 。','Hóa đơn đây ạ, em vừa mở gói ra là thấy hỏng rồi, còn chưa mang ra khỏi cửa hàng nữa.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_04','V1212','小苏',4,'原来是运输磕碰造成的，没关系，我给你拿全新的一款吧。','yuán lái shì yùn shū kē pèng zào chéng de ， méi guān xì ， wǒ gěi nǐ ná quán xīn de yī kuǎn ba 。','Thì ra là do va đập lúc vận chuyển, không sao, để chị lấy cho em một cái mới hoàn toàn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_05','V1212','阮明',5,'太好啦，我还担心不能退换，白花钱了呢。','tài hǎo la ， wǒ hái dān xīn bù néng tuì huàn ， bái huā qián le ne 。','May quá, em còn lo không đổi được, phí tiền oan.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_06','V1212','小苏',6,'店内商品当天破损凭小票都能换，放心哈。','diàn nèi shāng pǐn dàng tiān pò sǔn píng xiǎo piào dōu néng huàn ， fàng xīn hā 。','Hàng trong cửa hàng nếu hỏng trong ngày, có hóa đơn là đổi được hết, em yên tâm nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1212_07','V1212','阮明',7,'麻烦你啦，这款文创我特别喜欢，还好能换新。','má fán nǐ la ， zhè kuǎn wén chuàng wǒ tè bié xǐ huān ， hái hǎo néng huàn xīn 。','Phiền chị rồi ạ, món đồ lưu niệm này em thích lắm, may mà đổi được cái mới.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1213','SDL1','街边面馆点餐，不清楚本地面食辣度分级',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1213','SIT1213','P1','twist','tuy_y',NULL,'中式面馆辣度分微辣、中辣、特辣，点餐时可以主动要求少油少辣，老板会按需调整。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_01','V1213','阮明',1,'老板，来一碗牛肉拉面，微辣是放多少辣椒啊？','lǎo bǎn ， lái yī wǎn niú ròu lā miàn ， wēi là shì fàng duō shǎo là jiāo a ？','Chú ơi, cho một tô mì bò kéo tay, cay nhẹ là bỏ bao nhiêu ớt vậy chú?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_02','V1213','李叔',2,'微辣只放一勺辣椒油，中辣三勺，特辣满碗都是哦。','wēi là zhǐ fàng yī sháo là jiāo yóu ， zhōng là sān sháo ， tè là mǎn wǎn dōu shì ó 。','Cay nhẹ chỉ bỏ một muỗng dầu ớt thôi, cay vừa ba muỗng, cay đặc biệt thì đầy tô luôn đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_03','V1213','阮明',3,'我不太能吃辣，那就微辣，一点辣椒都别多放嘛。','wǒ bù tài néng chī là ， nà jiù wēi là ， yì diǎn là jiāo dōu bié duō fàng ma 。','Cháu không ăn cay được mấy, vậy cho cay nhẹ thôi, ớt cũng đừng bỏ nhiều nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_04','V1213','李叔',4,'明白啦，我给你少放，要不要加一份煎蛋呢？','míng bái la ， wǒ gěi nǐ shǎo fàng ， yào bù yào jiā yī fèn jiān dàn ne ？','Được rồi, chú bỏ ít cho, cháu có muốn thêm một quả trứng ốp la không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_05','V1213','阮明',5,'加一个煎蛋，面条煮软一点行不行？','jiā yí gè jiān dàn ， miàn tiáo zhǔ ruǎn yì diǎn xíng bù xíng ？','Cho cháu thêm một quả trứng ốp la, mì luộc mềm hơn chút được không chú?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_06','V1213','李叔',6,'没问题，面煮软一点适合外国朋友吃，马上给你做咯。','méi wèn tí ， miàn zhǔ ruǎn yì diǎn shì hé wài guó péng yǒu chī ， mǎ shàng gěi nǐ zuò gē 。','Không thành vấn đề, mì mềm hơn hợp với người nước ngoài ăn, chú làm ngay cho cháu đây.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1213_07','V1213','阮明',7,'谢谢老板，等下吃完我还要去逛老街。','xiè xiè lǎo bǎn ， děng xià chī wán wǒ hái yào qù guàng lǎo jiē 。','Cảm ơn chú, lát ăn xong cháu còn phải đi dạo phố cổ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1214','SDL1','森林公园徒步，半路丢失随身背包求助保安',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1214','SIT1214','P1','twist','ban_chinh_thuc',NULL,'国内公园、景区保安有巡逻寻物职责，遗失证件优先找安保，比报警处理更快。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_01','V1214','阮明',1,'保安大哥，我徒步丢了背包，里面有护照手机，帮帮我吧！','bǎo ān dà gē ， wǒ tú bù diū le bēi bāo ， lǐ miàn yǒu hù zhào shǒu jī ， bāng bāng wǒ ba ！','Anh bảo vệ ơi, em đi bộ đường dài bị mất balo rồi, trong đó có hộ chiếu với điện thoại, giúp em với!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_02','V1214','老王',2,'别慌，你大概在哪个路段弄丢的，背包是什么颜色呢？','bié huāng ， nǐ dà gài zài nǎ ge lù duàn nòng diū de ， bēi bāo shì shén me yán sè ne ？','Đừng hoảng, em nhớ đại khái là mất ở đoạn đường nào, balo màu gì vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_03','V1214','阮明',3,'十分钟前在木栈道休息区，黑色双肩包，有白色挂饰。','shí fēn zhōng qián zài mù zhàn dào xiū xī qū ， hēi sè shuāng jiān bāo ， yǒu bái sè guà shì 。','Mười phút trước ở khu nghỉ chân trên đường ván gỗ, balo hai quai màu đen, có móc treo màu trắng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_04','V1214','老王',4,'我联系巡逻同事去那段路查找，你在这里等我消息行吗？','wǒ lián xì xún luó tóng shì qù nà duàn lù chá zhǎo ， nǐ zài zhè lǐ děng wǒ xiāo xī xíng ma ？','Anh sẽ liên hệ đồng nghiệp tuần tra đến đoạn đó tìm giúp, em đợi tin ở đây được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_05','V1214','阮明',5,'好，我不敢走远，护照丢了补办特别麻烦呢。','hǎo ， wǒ bù gǎn zǒu yuǎn ， hù zhào diū le bǔ bàn tè bié má fán ne 。','Dạ được, em không dám đi xa, hộ chiếu mất làm lại phiền phức lắm ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_06','V1214','老王',6,'园区游客丢东西很常见，大概率能找到，先别着急哈。','yuán qū yóu kè diū dōng xī hěn cháng jiàn ， dà gài lǜ néng zhǎo dào ， xiān bié zháo jí hā 。','Khách tham quan làm mất đồ ở khu này cũng thường gặp thôi, khả năng cao là tìm lại được, em đừng lo lắng quá.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_07','V1214','阮明',7,'真的拜托您了，如果找回来我一定好好感谢你们。','zhēn de bài tuō nín le ， rú guǒ zhǎo huí lái wǒ yí dìng hǎo hǎo gǎn xiè nǐ men 。','Thật sự cảm ơn anh nhiều, nếu tìm lại được em nhất định sẽ cảm ơn mọi người thật chu đáo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1214_08','V1214','老王',8,'分内工作不用客气，有消息我马上喊你。','fèn nèi gōng zuò bù yòng kè qì ， yǒu xiāo xī wǒ mǎ shàng hǎn nǐ 。','Đây là việc trong trách nhiệm của anh mà, không cần khách sáo, có tin gì anh gọi em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1215','SDL1','景区寄存行李，返程超时产生额外寄存费',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1215','SIT1215','P1','that_bai_nhe','ban_chinh_thuc',NULL,'景区行李寄存分限时基础价，超时会额外收费，寄存前务必留意墙上须知。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_01','V1215','阮明',1,'你好，我取寄存的行李箱，寄存小票在这里。','nǐ hǎo ， wǒ qǔ jì cún de xíng lǐ xiāng ， jì cún xiǎo piào zài zhè lǐ 。','Chào chị, em đến lấy vali đã gửi, phiếu gửi đồ đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_02','V1215','管理员',2,'我扫一下小票，你超时两个小时啦，需要补交十元超时费。','wǒ sǎo yī xià xiǎo piào ， nǐ chāo shí liǎng gè xiǎo shí la ， xū yào bǔ jiāo shí yuán chāo shí fèi 。','Để chị quét phiếu xem, em gửi quá giờ hai tiếng rồi, cần đóng thêm mười tệ phí quá giờ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_03','V1215','阮明',3,'寄存不是全天统一收费吗，怎么还有超时费呢？','jì cún bú shì quán tiān tǒng yī shōu fèi ma ， zěn me hái yǒu chāo shí fèi ne ？','Gửi đồ không phải tính phí trọn ngày sao, sao còn có phí quá giờ vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_04','V1215','管理员',4,'基础费用仅限四小时游览，超出时长按小时计费哦。','jī chǔ fèi yòng jǐn xiàn sì xiǎo shí yóu lǎn ， chāo chū shí cháng àn xiǎo shí jì fèi ó 。','Phí cơ bản chỉ tính cho bốn tiếng tham quan thôi, quá thời gian đó sẽ tính thêm theo giờ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_05','V1215','阮明',5,'我刚才逛景区忘记看时间，没留意时限呢。','wǒ gāng cái guàng jǐng qū wàng jì kàn shí jiān ， méi liú yì shí xiàn ne 。','Em vừa nãy mải đi tham quan quên xem giờ, không để ý đến giới hạn thời gian.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_06','V1215','管理员',6,'规则贴在寄存柜旁边，寄存前都会提醒游客的。','guī zé tiē zài jì cún guì páng biān ， jì cún qián dōu huì tí xǐng yóu kè de 。','Quy định có dán ngay cạnh tủ gửi đồ, lúc gửi đồ đều có nhắc khách rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1215_07','V1215','阮明',7,'好吧，我补交费用，下次一定看好寄存时长。','hǎo ba ， wǒ bǔ jiāo fèi yòng ， xià cì yí dìng kàn hǎo jì cún shí cháng 。','Thôi vậy, em đóng thêm phí, lần sau nhất định sẽ để ý thời gian gửi đồ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1216','SDL1','参加本地一日游小团，集合迟到错过大巴',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1216','SIT1216','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内短途旅行团有固定发车时间，迟到不等人，车费多为打包套餐，迟到一般不予退还。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_01','V1216','阮明',1,'导游不好意思，我路上堵车迟到，大巴车开走了吗？','dǎo yóu bù hǎo yì sī ， wǒ lù shàng dǔ chē chí dào ， dà bā chē kāi zǒu le ma ？','Chị hướng dẫn viên ơi, em xin lỗi, đường tắc nên em đến trễ, xe buýt chạy mất rồi ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_02','V1216','小秦',2,'全车游客等了你二十分钟，按照规定我们不能继续等候啦。','quán chē yóu kè děng le nǐ èr shí fēn zhōng ， àn zhào guī dìng wǒ men bù néng jì xù děng hòu la 。','Cả xe khách đã đợi em hai mươi phút rồi, theo quy định bọn chị không thể tiếp tục chờ nữa.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_03','V1216','阮明',3,'能不能麻烦大巴停下来等我一小会儿，我跑过去很快的？','néng bù néng má fán dà bā tíng xià lái děng wǒ yī xiǎo huì er ， wǒ pǎo guò qù hěn kuài de ？','Chị có thể phiền cho xe dừng lại đợi em một chút được không ạ, em chạy qua rất nhanh thôi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_04','V1216','小秦',4,'景区盘山公路不能随意停车，全车行程会全部延后呢。','jǐng qū pán shān gōng lù bù néng suí yì tíng chē ， quán chē háng chéng huì quán bù yán hòu ne 。','Đường núi trong khu du lịch không được tùy tiện dừng xe, cả đoàn sẽ bị trễ hết lịch trình đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_05','V1216','阮明',5,'那我今天还能跟团游玩吗，报名费可以退一部分吗？','nà wǒ jīn tiān hái néng gēn tuán yóu wán ma ， bào míng fèi kě yǐ tuì yī bù fèn ma ？','Vậy hôm nay em còn theo đoàn tham quan được không ạ, phí đăng ký có thể hoàn lại một phần không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_06','V1216','小秦',6,'团费包含车费和门票，门票可以单独留给你，车费无法退款咯。','tuán fèi bāo hán chē fèi hé mén piào ， mén piào kě yǐ dān dú liú gěi nǐ ， chē fèi wú fǎ tuì kuǎn gē 。','Phí đoàn bao gồm tiền xe và vé vào cửa, vé vào cửa chị có thể để riêng cho em, còn tiền xe thì không hoàn được.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_07','V1216','阮明',7,'都怪我出门晚了，只能自己单独进景区参观啦。','dōu guài wǒ chū mén wǎn le ， zhǐ néng zì jǐ dān dú jìn jǐng qū cān guān la 。','Tại em ra cửa trễ, giờ chỉ còn cách tự mình vào tham quan riêng thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1216_08','V1216','小秦',8,'下次跟团一定要提前半小时抵达集合点，避免错过行程哈。','xià cì gēn tuán yí dìng yào tí qián bàn xiǎo shí dǐ dá jí hé diǎn ， bì miǎn cuò guò xíng chéng hā 。','Lần sau đi theo đoàn nhớ đến điểm tập trung sớm nửa tiếng, tránh bị lỡ lịch trình nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1217','SDL1','寺庙游览，不清楚上香礼仪询问义工',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1217','SIT1217','P1','suon_se','ban_chinh_thuc',NULL,'国内寺庙上香取三支，禁止嘴吹香火、踩踏寺庙门槛，属于传统礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_01','V1217','阮明',1,'姐姐您好，我第一次来寺庙，上香有什么讲究吗？','jiě jiě nín hǎo ， wǒ dì yī cì lái sì miào ， shàng xiāng yǒu shén me jiǎng jiū ma ？','Chị ơi, đây là lần đầu em đến chùa, thắp hương có cần chú ý gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_02','V1217','慧姐',2,'门口可以免费领三支清香，三支代表平安健康，不用多拿。','mén kǒu kě yǐ miǎn fèi lǐng sān zhī qīng xiāng ， sān zhī dài biǎo píng ān jiàn kāng ， bù yòng duō ná 。','Ở cổng có thể lấy miễn phí ba nén hương thơm, ba nén tượng trưng cho bình an và sức khỏe, không cần lấy nhiều đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_03','V1217','阮明',3,'点燃香之后要怎么做呢，可以直接插香炉里吗？','diǎn rán xiāng zhī hòu yào zěn me zuò ne ， kě yǐ zhí jiē chā xiāng lú lǐ ma ？','Sau khi thắp hương thì làm thế nào ạ, có thể cắm thẳng vào lư hương không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_04','V1217','慧姐',4,'点燃后双手举香鞠躬三下，再插进香炉，不要用嘴吹灭香火嘛。','diǎn rán hòu shuāng shǒu jǔ xiāng jū gōng sān xià ， zài chā jìn xiāng lú ， bú yào yòng zuǐ chuī miè xiāng huǒ ma 。','Thắp xong thì hai tay nâng hương cúi lạy ba lần, rồi cắm vào lư hương, không được dùng miệng thổi tắt lửa hương đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_05','V1217','阮明',5,'不能吹，那火苗怎么熄灭呀？','bù néng chuī ， nà huǒ miáo zěn me xī miè ya ？','Không được thổi, vậy ngọn lửa dập tắt bằng cách nào ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_06','V1217','慧姐',6,'轻轻左右晃动香火，火苗自然熄灭就可以啦。','qīng qīng zuǒ yòu huàng dòng xiāng huǒ ， huǒ miáo zì rán xī miè jiù kě yǐ la 。','Nhẹ nhàng lắc qua lắc lại que hương, ngọn lửa sẽ tự tắt thôi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1217_07','V1217','阮明',7,'学到很多规矩，谢谢您耐心跟我讲解咯。','xué dào hěn duō guī jǔ ， xiè xiè nín nài xīn gēn wǒ jiǎng jiě gē 。','Em học được nhiều quy tắc quá, cảm ơn chị đã kiên nhẫn giải thích cho em ạ.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1218','SDL1','夜市买水果，摊主称重计价产生价格误会',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1218','SIT1218','P1','twist','tuy_y',NULL,'国内市场水果统一按斤（500克）计价，不是按盒/个固定标价，购买前问清单价。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_01','V1218','阮明',1,'老板，这个草莓多少钱一斤，我想买一点尝尝。','lǎo bǎn ， zhè ge cǎo méi duō shǎo qián yī jīn ， wǒ xiǎng mǎi yì diǎn cháng cháng 。','Anh ơi, dâu tây này bao nhiêu tiền một cân, tôi muốn mua một ít ăn thử.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_02','V1218','阿明',2,'十五块一斤，你挑一点，我帮你称重算总价哈。','shí wǔ kuài yī jīn ， nǐ tiāo yì diǎn ， wǒ bāng nǐ chēng zhòng suàn zǒng jià hā 。','Mười lăm tệ một cân, cậu chọn đi, tôi cân giúp rồi tính tổng tiền nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_03','V1218','阮明',3,'好，我挑一小盒，大概多少钱呢？','hǎo ， wǒ tiāo yī xiǎo hé ， dà gài duō shǎo qián ne ？','Được, tôi chọn một hộp nhỏ, khoảng bao nhiêu tiền vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_04','V1218','阿明',4,'一共一斤二两，十八块，我给你装盒子里。','yī gòng yī jīn èr liǎng ， shí bā kuài ， wǒ gěi nǐ zhuāng hé zi lǐ 。','Tổng cộng một cân hai lạng, mười tám tệ, tôi cho vào hộp cho cậu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_05','V1218','阮明',5,'我以为按一盒固定价格卖，原来是按斤称重算钱呀。','wǒ yǐ wéi àn yī hé gù dìng jià gé mài ， yuán lái shì àn jīn chēng zhòng suàn qián ya 。','Tôi cứ tưởng bán theo giá cố định một hộp, hóa ra là tính theo cân à.','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_06','V1218','阿明',6,'夜市水果都是现称现卖，没有打包固定价的哦。','yè shì shuǐ guǒ dōu shì xiàn chēng xiàn mài ， méi yǒu dǎ bāo gù dìng jià de ó 。','Trái cây ở chợ đêm đều cân xong mới bán, không có giá cố định đóng gói sẵn đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1218_07','V1218','阮明',7,'明白啦，付款给您，下次再来买别的水果。','míng bái la ， fù kuǎn gěi nín ， xià cì zài lái mǎi bié de shuǐ guǒ 。','Hiểu rồi, gửi tiền cho anh nhé, lần sau tôi lại đến mua trái cây khác.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1219','SDL1','乘坐轮渡观光，分不清普通舱与观景舱票价',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1219','SIT1219','P1','suon_se','ban_chinh_thuc',NULL,'观光轮渡分层定价，顶层观景舱溢价更高，适合拍照游客，预算有限可选底层普通舱。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_01','V1219','阮明',1,'你好，轮渡观光票有两种，普通舱和观景舱差别大吗？','nǐ hǎo ， lún dù guān guāng piào yǒu liǎng zhǒng ， pǔ tōng cāng hé guān jǐng cāng chā bié dà ma ？','Chào anh, vé phà tham quan có hai loại, khoang thường và khoang ngắm cảnh khác nhau nhiều không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_02','V1219','小周',2,'普通舱在底层，观景舱顶层露天，视野好看风景嘛。','pǔ tōng cāng zài dǐ céng ， guān jǐng cāng dǐng céng lù tiān ， shì yě hǎo kàn fēng jǐng ma 。','Khoang thường ở tầng dưới, khoang ngắm cảnh ở tầng trên lộ thiên, tầm nhìn đẹp ngắm cảnh rất tốt ạ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_03','V1219','阮明',3,'两者票价分别是多少，航行时长一样吗？','liǎng zhě piào jià fēn bié shì duō shǎo ， háng xíng shí cháng yī yàng ma ？','Vé hai loại giá bao nhiêu, thời gian di chuyển có giống nhau không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_04','V1219','小周',4,'普通舱三十，观景舱六十，航行时间都是一小时二十分钟。','pǔ tōng cāng sān shí ， guān jǐng cāng liù shí ， háng xíng shí jiān dōu shì yī xiǎo shí èr shí fēn zhōng 。','Khoang thường ba mươi tệ, khoang ngắm cảnh sáu mươi tệ, thời gian di chuyển đều là một tiếng hai mươi phút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_05','V1219','阮明',5,'我想拍照看江景，那我买两张观景舱票吧。','wǒ xiǎng pāi zhào kàn jiāng jǐng ， nà wǒ mǎi liǎng zhāng guān jǐng cāng piào ba 。','Em muốn chụp ảnh ngắm cảnh sông, vậy em mua hai vé khoang ngắm cảnh nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_06','V1219','小周',6,'好嘞，两张一百二十，拿好船票，十分钟后登船啦。','hǎo lei ， liǎng zhāng yì bǎi èr shí ， ná hǎo chuán piào ， shí fēn zhōng hòu dēng chuán la 。','Được ạ, hai vé một trăm hai mươi tệ, cầm vé cẩn thận, mười phút nữa lên tàu ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1219_07','V1219','阮明',7,'顶层视野肯定很棒，还好提前问清楚区别咯。','dǐng céng shì yě kěn dìng hěn bàng ， hái hǎo tí qián wèn qīng chǔ qū bié gē 。','Tầng trên chắc chắn tầm nhìn rất đẹp, may mà em hỏi rõ sự khác biệt trước.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1220','SDL1','酒店早餐结束时间快到，下楼没吃到餐食',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1220','SIT1220','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内酒店自助早餐有固定结束时段，超时不再提供，无临时加餐服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_01','V1220','阮明',1,'你好，我想来吃早餐，怎么餐台都收干净了呀？','nǐ hǎo ， wǒ xiǎng lái chī zǎo cān ， zěn me cān tái dōu shōu gān jìng le ya ？','Chào chị, em muốn ăn sáng, sao bàn ăn dọn sạch hết rồi ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_02','V1220','小兰',2,'酒店早餐九点半结束，现在已经十点十五分啦。','jiǔ diàn zǎo cān jiǔ diǎn bàn jié shù ， xiàn zài yǐ jīng shí diǎn shí wǔ fēn la 。','Bữa sáng khách sạn kết thúc lúc chín rưỡi, bây giờ đã mười giờ mười lăm rồi ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_03','V1220','阮明',3,'我昨天玩到很晚，早上睡过头，不知道结束这么早呢。','wǒ zuó tiān wán dào hěn wǎn ， zǎo shàng shuì guò tóu ， bù zhī dào jié shù zhè me zǎo ne 。','Hôm qua em chơi khuya quá, sáng nay ngủ quên, không biết là kết thúc sớm vậy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_04','V1220','小兰',4,'实在不好意思，厨房已经全部收餐清洗，没有食物咯。','shí zài bù hǎo yì sī ， chú fáng yǐ jīng quán bù shōu cān qīng xǐ ， méi yǒu shí wù gē 。','Thật xin lỗi, nhà bếp đã dọn hết và rửa sạch rồi, không còn đồ ăn nữa ạ.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_05','V1220','阮明',5,'那酒店还有其他付费早餐可以买吗？','nà jiǔ diàn hái yǒu qí tā fù fèi zǎo cān kě yǐ mǎi ma ？','Vậy khách sạn còn bữa sáng trả phí nào khác để mua không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_06','V1220','小兰',6,'餐厅上午只供应自助早餐，中午十二点才有正餐供应。','cān tīng shàng wǔ zhǐ gōng yìng zì zhù zǎo cān ， zhōng wǔ shí èr diǎn cái yǒu zhèng cān gōng yìng 。','Buổi sáng nhà hàng chỉ phục vụ buffet sáng thôi, mười hai giờ trưa mới có bữa chính ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1220_07','V1220','阮明',7,'好吧，只能出门去街边小店吃早饭了，下次一定早起。','hǎo ba ， zhǐ néng chū mén qù jiē biān xiǎo diàn chī zǎo fàn le ， xià cì yí dìng zǎo qǐ 。','Thôi được, đành ra ngoài ăn sáng ở quán vỉa hè vậy, lần sau nhất định dậy sớm.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1221','SDL1','景区扫码讲解器租借，手机无法识别国内小程序',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1221','SIT1221','P1','twist','ban_chinh_thuc',NULL,'国内各类景区小程序大多需要大陆手机号注册，境外手机系统常会加载失败。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_01','V1221','阮明',1,'您好，我想租景区电子讲解器，但是扫二维码打不开小程序。','nín hǎo ， wǒ xiǎng zū jǐng qū diàn zi jiǎng jiě qì ， dàn shì sǎo èr wéi mǎ dǎ bù kāi xiǎo chéng xù 。','Chào anh/chị, em muốn thuê máy thuyết minh điện tử của khu du lịch nhưng quét mã QR không mở được ứng dụng nhỏ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_02','V1221','工作人员',2,'你的手机是境外系统吧，没有国内手机号登录不了呢。','nǐ de shǒu jī shì jìng wài xì tǒng ba ， méi yǒu guó nèi shǒu jī hào dēng lù bù liǎo ne 。','Điện thoại của bạn dùng hệ thống nước ngoài đúng không, không có số điện thoại trong nước thì không đăng nhập được đâu.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_03','V1221','阮明',3,'那我没法线上扫码，能直接租实体手持讲解器吗？','nà wǒ méi fǎ xiàn shàng sǎo mǎ ， néng zhí jiē zū shí tǐ shǒu chí jiǎng jiě qì ma ？','Vậy em không thể quét mã trực tuyến được, có thể thuê trực tiếp máy thuyết minh cầm tay không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_04','V1221','工作人员',4,'可以的，线下登记护照就能租，押金一百元，归还退押金。','kě yǐ de ， xiàn xià dēng jì hù zhào jiù néng zū ， yā jīn yì bǎi yuán ， guī huán tuì yā jīn 。','Được chứ, đăng ký trực tiếp bằng hộ chiếu là thuê được, tiền đặt cọc một trăm tệ, trả máy sẽ hoàn cọc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_05','V1221','阮明',5,'那就租一台，押金微信支付没问题吧？','nà jiù zū yī tái ， yā jīn wēi xìn zhī fù méi wèn tí ba ？','Vậy em thuê một máy, đặt cọc thanh toán qua WeChat được không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_06','V1221','工作人员',6,'支持微信支付宝，拿好讲解器，每个景点会自动讲解咯。','zhī chí wēi xìn zhī fù bǎo ， ná hǎo jiǎng jiě qì ， měi gè jǐng diǎn huì zì dòng jiǎng jiě gē 。','Hỗ trợ cả WeChat Pay và Alipay, cầm máy thuyết minh cẩn thận, đến mỗi điểm tham quan sẽ tự động thuyết minh nhé.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1221_07','V1221','阮明',7,'太好啦，还好有实体设备，不然看不懂景点历史呢。','tài hǎo la ， hái hǎo yǒu shí tǐ shè bèi ， bù rán kàn bù dǒng jǐng diǎn lì shǐ ne 。','Tuyệt quá, may mà có thiết bị thực tế, không thì em chẳng hiểu được lịch sử của các điểm tham quan.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1222','SDL1','高铁站安检，随身携带液体超出规定容量被扣留',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1222','SIT1222','P1','that_bai_nhe','ban_chinh_thuc',NULL,'高铁、地铁随身液体单瓶容积不得超100ml，超标无法随身携带，可邮寄或当场舍弃。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_01','V1222','阮明',1,'安检您好，我的护肤品怎么被机器拦下来了呢？','ān jiǎn nín hǎo ， wǒ de hù fū pǐn zěn me bèi jī qì lán xià lái le ne ？','Chào anh, đồ dưỡng da của em sao lại bị máy giữ lại vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_02','V1222','小林',2,'你这瓶保湿乳液一百五十毫升，高铁单瓶液体不能超过一百毫升哦。','nǐ zhè píng bǎo shī rǔ yè yì bǎi wǔ shí háo shēng ， gāo tiě dān píng yè tǐ bù néng chāo guò yì bǎi háo shēng ó 。','Chai sữa dưỡng ẩm này của bạn một trăm năm mươi ml, tàu cao tốc quy định mỗi chai chất lỏng không được quá một trăm ml đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_03','V1222','阮明',3,'我不知道这个规定，放在行李箱里忘记拿出来啦。','wǒ bù zhī dào zhè ge guī dìng ， fàng zài háng lǐ xiāng lǐ wàng jì ná chū lái la 。','Em không biết quy định này, để trong vali quên lấy ra mất rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_04','V1222','小林',4,'超过容量无法带上高铁，要么现场丢弃，要么快递寄走。','chāo guò róng liàng wú fǎ dài shàng gāo tiě ， yào me xiàn chǎng diū qì ， yào me kuài dì jì zǒu 。','Vượt quá dung tích thì không thể mang lên tàu cao tốc, hoặc là bỏ lại tại chỗ, hoặc là gửi chuyển phát nhanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_05','V1222','阮明',5,'快递邮寄要多少钱，多久能寄到我的学校宿舍？','kuài dì yóu jì yào duō shǎo qián ， duō jiǔ néng jì dào wǒ de xué xiào sù shè ？','Gửi chuyển phát nhanh thì tốn bao nhiêu tiền ạ, bao lâu thì đến ký túc xá trường em?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_06','V1222','小林',6,'同城快递十元，第二天送达，现在登记地址就行咯。','tóng chéng kuài dì shí yuán ， dì èr tiān sòng dá ， xiàn zài dēng jì dì zhǐ jiù xíng gē 。','Chuyển phát nhanh nội thành mười tệ, hôm sau là giao đến, giờ đăng ký địa chỉ là được ạ.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1222_07','V1222','阮明',7,'那我选择寄回去吧，丢掉护肤品太可惜啦。','nà wǒ xuǎn zé jì huí qù ba ， diū diào hù fū pǐn tài kě xī la 。','Vậy em chọn gửi về vậy, vứt bỏ đồ dưỡng da thì tiếc quá.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1223','SDL1','乡村旅游农家乐点菜，不清楚菜品分量大小',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1223','SIT1223','P1','twist','tuy_y',NULL,'农家乐家常菜盘子大、分量足，单人就餐建议少点菜品，避免浪费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_01','V1223','阮明',1,'芳姐，我一个人吃饭，点两个菜会不会太多呢？','fāng jiě ， wǒ yí gè rén chī fàn ， diǎn liǎng gè cài huì bú huì tài duō ne ？','Chị Phương ơi, em ăn một mình, gọi hai món có nhiều quá không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_02','V1223','芳姐',2,'咱们农家乐菜盘分量很大，一个人点一荤一素肯定吃不完的。','zán men nóng jiā lè cài pán fèn liàng hěn dà ， yí gè rén diǎn yī hūn yī sù kěn dìng chī bù wán de 。','Quán nhà mình phần ăn to lắm, một người gọi một món mặn một món rau chắc chắn ăn không hết đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_03','V1223','阮明',3,'那只点一份农家炒土鸡，再加一碗米饭行吗？','nà zhǐ diǎn yī fèn nóng jiā chǎo tǔ jī ， zài jiā yī wǎn mǐ fàn xíng ma ？','Vậy chỉ gọi một đĩa gà ta xào kiểu nhà quê, thêm một bát cơm được không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_04','V1223','芳姐',4,'土鸡一盘够两个人吃，要不换个小份青菜怎么样？','tǔ jī yī pán gòu liǎng gè rén chī ， yào bù huàn gè xiǎo fèn qīng cài zěn me yàng ？','Một đĩa gà ta đủ cho hai người ăn rồi, hay đổi sang phần rau xanh nhỏ hơn nhé?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_05','V1223','阮明',5,'好，那就土鸡加一份清炒青菜，少放一点油吧。','hǎo ， nà jiù tǔ jī jiā yī fèn qīng chǎo qīng cài ， shǎo fàng yì diǎn yóu ba 。','Được, vậy gọi gà ta với một phần rau xào, cho ít dầu thôi nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_06','V1223','芳姐',6,'没问题，清淡做法，十分钟就能上菜哈。','méi wèn tí ， qīng dàn zuò fǎ ， shí fēn zhōng jiù néng shàng cài hā 。','Không vấn đề gì, nấu thanh đạm, mười phút là có món lên rồi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1223_07','V1223','阮明',7,'乡下菜分量实在，还好提前问您，避免浪费食物。','xiāng xià cài fèn liàng shí zài ， hái hǎo tí qián wèn nín ， bì miǎn làng fèi shí wù 。','Món ăn nhà quê thật đầy đặn, may mà em hỏi chị trước, không thì phí đồ ăn quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1224','SDL1','美术馆参观，想拍照被工作人员制止',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1224','SIT1224','P1','twist','ban_chinh_thuc',NULL,'国内美术馆、博物馆馆藏艺术品禁止拍照，闪光灯会加速画作老化，同时保护著作权。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_01','V1224','阮明',1,'不好意思，这幅油画太美了，我拍一张照片留存可以吗？','bù hǎo yì sī ， zhè fú yóu huà tài měi le ， wǒ pāi yī zhāng zhào piān liú cún kě yǐ ma ？','Xin lỗi anh, bức tranh sơn dầu này đẹp quá, em chụp một tấm ảnh lưu niệm được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_02','V1224','老杨',2,'展厅内全部展品禁止拍照，尤其是不能开闪光灯哦。','zhǎn tīng nèi quán bù zhǎn pǐn jìn zhǐ pāi zhào ， yóu qí shì bù néng kāi shǎn guāng dēng ó 。','Tất cả hiện vật trong phòng trưng bày đều cấm chụp ảnh, đặc biệt là không được bật đèn flash ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_03','V1224','阮明',3,'我不开闪光灯，单纯记录画面也不行吗？','wǒ bù kāi shǎn guāng dēng ， dān chún jì lù huà miàn yě bù xíng ma ？','Em không bật đèn flash, chỉ đơn thuần ghi lại hình ảnh thôi cũng không được sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_04','V1224','老杨',4,'这幅画作有版权保护，任何拍摄都会损伤颜料图层的。','zhè fú huà zuò yǒu bǎn quán bǎo hù ， rèn hé pāi shè dōu huì sǔn shāng yán liào tú céng de 。','Bức tranh này có bản quyền bảo vệ, bất kỳ việc chụp ảnh nào cũng sẽ làm hỏng lớp màu đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_05','V1224','阮明',5,'原来是这样，我不了解美术馆的规定，抱歉啦。','yuán lái shì zhè yàng ， wǒ bù liǎo jiě měi shù guǎn de guī dìng ， bào qiàn la 。','Ra là vậy, em không biết quy định của phòng trưng bày, xin lỗi anh ạ.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_06','V1224','老杨',6,'没关系，展厅门口都贴了提示，下次留意一下哈。','méi guān xì ， zhǎn tīng mén kǒu dōu tiē le tí shì ， xià cì liú yì yī xià hā 。','Không sao, ở cửa phòng trưng bày đều có dán thông báo, lần sau chú ý một chút nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1224_07','V1224','阮明',7,'好，我收起手机，安静慢慢欣赏画作。','hǎo ， wǒ shōu qǐ shǒu jī ， ān jìng màn màn xīn shǎng huà zuò 。','Vâng, em cất điện thoại đi, yên lặng từ từ thưởng thức tranh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1225','SDL1','旅游途中肠胃不舒服，在景区药店买中成药',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1225','SIT1225','P1','suon_se','chinh_thuc',NULL,'国内药店中成药无需处方即可购买，药师会根据症状推荐对应药品，购药前说明自身症状。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_01','V1225','阮明',1,'药师您好，我旅游吃坏肚子，一直腹痛腹泻，该买什么药呢？','yào shī nín hǎo ， wǒ lǚ yóu chī huài dǔ zi ， yì zhí fù tòng fù xiè ， gāi mǎi shén me yào ne ？','Dược sĩ ơi, tôi đi du lịch bị đau bụng, cứ đau bụng tiêu chảy suốt, nên mua thuốc gì ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_02','V1225','陈药师',2,'先说说你的症状，一天大概拉肚子几次，有没有胃痛？','xiān shuō shuō nǐ de zhèng zhuàng ， yī tiān dà gài lā dù zi jǐ cì ， yǒu méi yǒu wèi tòng ？','Anh nói qua triệu chứng xem, một ngày đi ngoài khoảng mấy lần, có đau dạ dày không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_03','V1225','阮明',3,'已经跑厕所四次，肚子隐隐作痛，浑身没力气啦。','yǐ jīng pǎo cè suǒ sì cì ， dǔ zi yǐn yǐn zuò tòng ， hún shēn méi lì qì la 。','Tôi đã chạy vào nhà vệ sinh bốn lần rồi, bụng cứ âm ỉ đau, người mệt lả luôn.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_04','V1225','陈药师',4,'那给你拿一盒肠胃中成药，饭后温水服用，一天三次。','nà gěi nǐ ná yī hé cháng wèi zhōng chéng yào ， fàn hòu wēn shuǐ fú yòng ， yī tiān sān cì 。','Vậy tôi lấy cho anh một hộp thuốc đông y trị dạ dày, uống với nước ấm sau khi ăn, ngày ba lần.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_05','V1225','阮明',5,'这个药外国人服用有没有禁忌，会不会过敏啊？','zhè ge yào wài guó rén fú yòng yǒu méi yǒu jìn jì ， huì bú huì guò mǐn a ？','Thuốc này người nước ngoài dùng có kiêng kỵ gì không, có bị dị ứng không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_06','V1225','陈药师',6,'药性温和，很少过敏，服药期间别吃生冷辛辣食物嘛。','yào xìng wēn hé ， hěn shǎo guò mǐn ， fú yào qī jiān bié chī shēng lěng xīn là shí wù ma 。','Thuốc này tính ôn hòa, ít khi gây dị ứng, trong thời gian uống thuốc thì đừng ăn đồ sống lạnh cay nóng nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_07','V1225','阮明',7,'好，麻烦给我一盒，请问一次吃几粒呢？','hǎo ， má fán gěi wǒ yī hé ， qǐng wèn yī cì chī jǐ lì ne ？','Vâng, phiền anh lấy cho tôi một hộp, cho tôi hỏi mỗi lần uống mấy viên ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1225_08','V1225','陈药师',8,'盒子上面有详细说明书，看不懂随时回来问我就行咯。','hé zi shàng miàn yǒu xiáng xì shuō míng shū ， kàn bù dǒng suí shí huí lái wèn wǒ jiù xíng gē 。','Trên hộp có hướng dẫn sử dụng chi tiết, không hiểu thì cứ quay lại hỏi tôi là được.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1226','SDL1','共享单车骑行游览古城，停车超出运营区被扣车',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1226','SIT1226','P1','that_bai_nhe','ban_chinh_thuc',NULL,'城市共享单车划定专属停车运营区，越区停车会收取高额调度费，路边白色/蓝色框才合规停车点。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_01','V1226','阮明',1,'你好，我的共享单车被锁在城外，提示超出运营区域怎么办？','nǐ hǎo ， wǒ de gòng xiǎng dān chē bèi suǒ zài chéng wài ， tí shì chāo chū yùn yíng qū yù zěn me bàn ？','Chào chị, xe đạp chia sẻ của tôi bị khóa ở ngoài thành, báo là vượt quá khu vực hoạt động, giờ phải làm sao ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_02','V1226','接线员',2,'您好先生，车辆驶出古城运营区会自动上锁，需要支付二十元调度费。','nín hǎo xiān shēng ， chē liàng shǐ chū gǔ chéng yùn yíng qū huì zì dòng shàng suǒ ， xū yào zhī fù èr shí yuán diào dù fèi 。','Chào anh, xe đi ra khỏi khu vực hoạt động của phố cổ sẽ tự động khóa lại, anh cần thanh toán phí điều phối 20 tệ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_03','V1226','阮明',3,'我不知道古城有停车范围，随便停路边就被扣车了呢。','wǒ bù zhī dào gǔ chéng yǒu tíng chē fàn wéi ， suí biàn tíng lù biān jiù bèi kòu chē le ne 。','Tôi không biết phố cổ có giới hạn khu vực đỗ xe, chỉ đỗ đại ở lề đường thôi mà bị khóa xe luôn.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_04','V1226','接线员',4,'古城出入口都有提示牌，超出区域必须支付调度费解锁车辆。','gǔ chéng chū rù kǒu dōu yǒu tí shì pái ， chāo chū qū yù bì xū zhī fù diào dù fèi jiě suǒ chē liàng 。','Ở các lối ra vào phố cổ đều có biển báo, vượt khu vực thì bắt buộc phải trả phí điều phối mới mở khóa được xe ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_05','V1226','阮明',5,'支付完费用之后，我还能继续骑行回市区吗？','zhī fù wán fèi yòng zhī hòu ， wǒ hái néng jì xù qí xíng huí shì qū ma ？','Sau khi thanh toán xong phí, tôi có thể tiếp tục đạp xe về trung tâm thành phố không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_06','V1226','接线员',6,'缴费解锁后可以正常骑行，记得停在蓝色停车框内哦。','jiǎo fèi jiě suǒ hòu kě yǐ zhèng cháng qí xíng ， jì de tíng zài lán sè tíng chē kuāng nèi ó 。','Sau khi nộp phí mở khóa thì anh đạp bình thường được, nhớ đỗ trong khung màu xanh nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1226_07','V1226','阮明',7,'好吧，我马上缴费，下次一定看清停车范围再停放。','hǎo ba ， wǒ mǎ shàng jiǎo fèi ， xià cì yí dìng kàn qīng tíng chē fàn wéi zài tíng fàng 。','Vâng, tôi thanh toán ngay đây, lần sau nhất định sẽ xem kỹ khu vực đỗ xe rồi mới đỗ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1227','SDL1','景区停车场找不到自己停放的车辆，求助管理员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1227','SIT1227','P1','suon_se','tuy_y',NULL,'大型景区停车场分A/B/C区域，分区标识偏小，找不到车可直接找管理员协助查找。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_01','V1227','阮明',1,'周叔，我找不到租的电动车了，停车场太大分不清区域呢。','zhōu shū ， wǒ zhǎo bú dào zū de diàn dòng chē le ， tíng chē chǎng tài dà fēn bù qīng qū yù ne 。','Chú Chu ơi, cháu tìm không ra xe điện thuê rồi, bãi đỗ xe rộng quá không phân biệt được khu vực.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_02','V1227','周叔',2,'你大概几点停进来的，车身是什么颜色呀？','nǐ dà gài jǐ diǎn tíng jìn lái de ， chē shēn shì shén me yán sè ya ？','Cháu đỗ vào khoảng mấy giờ, xe màu gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_03','V1227','阮明',3,'半小时前停的，白色小电驴，车把挂着蓝色布袋。','bàn xiǎo shí qián tíng de ， bái sè xiǎo diàn lǘ ， chē bǎ guà zhe lán sè bù dài 。','Cháu đỗ nửa tiếng trước, xe điện nhỏ màu trắng, tay lái có treo túi vải màu xanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_04','V1227','周叔',4,'那是B区停放区，跟着我走，这片都是白色电动车咯。','nà shì B qū tíng fàng qū ， gēn zhe wǒ zǒu ， zhè piàn dōu shì bái sè diàn dòng chē gē 。','Đó là khu đỗ xe B, đi theo chú, khu này toàn xe điện màu trắng.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_05','V1227','阮明',5,'太感谢您了，我绕三圈都没找到分区指示牌。','tài gǎn xiè nín le ， wǒ rào sān quān dōu méi zhǎo dào fēn qū zhǐ shì pái 。','Cảm ơn chú nhiều lắm, cháu đi vòng ba lần rồi mà vẫn không tìm thấy biển chỉ dẫn khu vực.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_06','V1227','周叔',6,'停车场分区牌子有点小，游客经常迷路，不用客气哈。','tíng chē chǎng fēn qū pái zi yǒu diǎn xiǎo ， yóu kè jīng cháng mí lù ， bù yòng kè qì hā 。','Biển chia khu ở bãi đỗ hơi nhỏ, khách du lịch hay bị lạc lắm, không cần khách sáo đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1227_07','V1227','阮明',7,'还好有您带路，不然我要耽误下午的行程啦。','hái hǎo yǒu nín dài lù ， bù rán wǒ yào dān wù xià wǔ de xíng chéng la 。','May mà có chú dẫn đường, không thì cháu lỡ mất lịch trình buổi chiều rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1228','SDL1','本地茶馆体验喝茶，不懂点茶流程询问茶艺师',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1228','SIT1228','P1','suon_se','ban_chinh_thuc',NULL,'中式茶馆讲究先选茶、温杯、洗茶再饮用，洗茶第一遍茶水不喝，直接倒掉。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_01','V1228','阮明',1,'小姐姐，我第一次来中式茶馆，点茶有什么讲究吗？','xiǎo jiě jiě ， wǒ dì yī cì lái zhōng shì chá guǎn ， diǎn chá yǒu shén me jiǎng jiū ma ？','Chị ơi, đây là lần đầu em đến trà quán kiểu Trung, gọi trà có gì cần lưu ý không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_02','V1228','小雯',2,'咱们可以先选茶叶，绿茶、红茶、乌龙茶口感差别很大呢。','zán men kě yǐ xiān xuǎn chá yè ， lǜ chá 、 hóng chá 、 wū lóng chá kǒu gǎn chā bié hěn dà ne 。','Mình có thể chọn loại trà trước, trà xanh, hồng trà, trà ô long hương vị khác nhau nhiều lắm đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_03','V1228','阮明',3,'乌龙茶味道清淡吗，适合新手喝吗？','wū lóng chá wèi dào qīng dàn ma ， shì hé xīn shǒu hē ma ？','Trà ô long vị có nhạt không, có hợp với người mới uống không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_04','V1228','小雯',4,'乌龙茶香气足，不苦涩，很适合外国游客尝试嘛。','wū lóng chá xiāng qì zú ， bù kǔ sè ， hěn shì hé wài guó yóu kè cháng shì ma 。','Trà ô long thơm đậm, không đắng chát, rất hợp để khách du lịch nước ngoài thử đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_05','V1228','阮明',5,'那就点一壶乌龙，整套泡茶流程可以教我看看吗？','nà jiù diǎn yī hú wū lóng ， zhěng tào pào chá liú chéng kě yǐ jiāo wǒ kàn kàn ma ？','Vậy thì gọi một ấm ô long, chị có thể dạy em cả quy trình pha trà được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_06','V1228','小雯',6,'当然可以，我泡茶的时候慢慢给你讲解每一步操作咯。','dāng rán kě yǐ ， wǒ pào chá de shí hòu màn màn gěi nǐ jiǎng jiě měi yī bù cāo zuò gē 。','Được chứ, lúc pha trà chị sẽ từ từ giải thích cho em từng bước một.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1228_07','V1228','阮明',7,'太期待啦，一直想体验正宗中式茶文化。','tài qī dài la ， yì zhí xiǎng tǐ yàn zhèng zōng zhōng shì chá wén huà 。','Em mong quá, em cứ muốn trải nghiệm văn hóa trà Trung Hoa chính gốc mãi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1229','SDL1','线上订景区门票，证件姓名拼音和护照不一致无法核销',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1229','SIT1229','P1','twist','chinh_thuc',NULL,'国内景区外籍实名票务要求拼音与护照完全一致，字母大小写、拼写错误均无法检票入园。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_01','V1229','阮明',1,'您好，我线上预约门票检票失败，系统提示姓名不符呢。','nín hǎo ， wǒ xiàn shàng yù yuē mén piào jiǎn piào shī bài ， xì tǒng tí shì xìng míng bù fú ne 。','Chào chị, tôi đặt vé trực tuyến nhưng quét vé không được, hệ thống báo tên không khớp ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_02','V1229','工作人员',2,'我核对一下，你购票填写的拼音和护照拼音差一个字母。','wǒ hé duì yī xià ， nǐ gòu piào tián xiě de pīn yīn hé hù zhào pīn yīn chà yí gè zì mǔ 。','Để tôi kiểm tra lại, phiên âm pinyin anh điền lúc mua vé sai lệch một chữ cái so với hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_03','V1229','阮明',3,'我输入的时候不小心打错字母，没想到会无法入园啊。','wǒ shū rù de shí hòu bù xiǎo xīn dǎ cuò zì mǔ ， méi xiǎng dào huì wú fǎ rù yuán a 。','Lúc nhập tôi lỡ gõ nhầm một chữ, không ngờ lại không vào được cổng ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_04','V1229','工作人员',4,'外籍游客门票实名严格匹配护照拼音，错一个字都不能核销。','wài jí yóu kè mén piào shí míng yán gé pǐ pèi hù zhào pīn yīn ， cuò yí gè zì dōu bù néng hé xiāo 。','Vé của khách nước ngoài phải khớp chính xác tuyệt đối với phiên âm hộ chiếu, sai một chữ cũng không xác nhận được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_05','V1229','阮明',5,'那现在能现场修改订单信息，重新核销入园吗？','nà xiàn zài néng xiàn chǎng xiū gǎi dìng dān xìn xī ， chóng xīn hé xiāo rù yuán ma ？','Vậy bây giờ có thể sửa lại thông tin đơn hàng tại chỗ rồi xác nhận vào cổng lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_06','V1229','工作人员',6,'可以，出示护照原件，我后台帮你修改订单拼音信息。','kě yǐ ， chū shì hù zhào yuán jiàn ， wǒ hòu tái bāng nǐ xiū gǎi dìng dān pīn yīn xìn xī 。','Được, anh cho tôi xem hộ chiếu gốc, tôi sẽ sửa lại thông tin phiên âm trong hệ thống giúp anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_07','V1229','阮明',7,'辛苦您帮忙操作，下次订票我一定仔细核对护照拼音。','xīn kǔ nín bāng máng cāo zuò ， xià cì dìng piào wǒ yí dìng zǐ xì hé duì hù zhào pīn yīn 。','Cảm ơn chị đã giúp đỡ, lần sau đặt vé tôi nhất định sẽ kiểm tra kỹ phiên âm hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1229_08','V1229','工作人员',8,'没关系，很多外国游客都会输错拼音，修改很快的哈。','méi guān xì ， hěn duō wài guó yóu kè dōu huì shū cuò pīn yīn ， xiū gǎi hěn kuài de hā 。','Không sao đâu, nhiều khách nước ngoài cũng hay gõ nhầm phiên âm lắm, sửa nhanh thôi ạ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1230','SDL1','长途旅游大巴中途服务区休息，错过发车时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1230','SIT1230','P1','that_bai_nhe','ban_chinh_thuc',NULL,'长途旅游大巴服务区休息有固定时限，超时直接发车，不会原地等候迟到游客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_01','V1230','阮明',1,'导游！大巴车是不是开走了，我去洗手间回来车不见了？','dǎo yóu ！ dà bā chē shì bú shì kāi zǒu le ， wǒ qù xǐ shǒu jiān huí lái chē bú jiàn le ？','Hướng dẫn viên ơi! Xe buýt chạy mất rồi phải không, em đi vệ sinh xong quay lại không thấy xe đâu cả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_02','V1230','阿凯',2,'全车游客十分钟前就准时发车，我在车上清点人数少了你。','quán chē yóu kè shí fēn zhōng qián jiù zhǔn shí fā chē ， wǒ zài chē shàng qīng diǎn rén shù shǎo le nǐ 。','Cả xe khách đã khởi hành đúng giờ từ mười phút trước rồi, tôi kiểm đếm trên xe thấy thiếu mỗi bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_03','V1230','阮明',3,'服务区太大，我走错洗手间，回来晚了几分钟而已。','fú wù qū tài dà ， wǒ zǒu cuò xǐ shǒu jiān ， huí lái wǎn le jǐ fēn zhōng ér yǐ 。','Trạm dừng chân rộng quá, em đi nhầm nhà vệ sinh, chỉ về trễ có mấy phút thôi mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_04','V1230','阿凯',4,'大巴有固定休息时长，不能全车人等单独一位游客哦。','dà bā yǒu gù dìng xiū xī shí cháng ， bù néng quán chē rén děng dān dú yī wèi yóu kè ó 。','Xe buýt có thời gian nghỉ cố định, không thể để cả xe chờ một mình bạn được đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_05','V1230','阮明',5,'那我现在怎么前往下一个景点，车费能退一部分吗？','nà wǒ xiàn zài zěn me qián wǎng xià yí gè jǐng diǎn ， chē fèi néng tuì yī bù fèn ma ？','Vậy bây giờ em đi tới điểm tham quan tiếp theo bằng cách nào, tiền vé có được hoàn lại một phần không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_06','V1230','阿凯',6,'车费包含全程交通，无法退款，我帮你联系下一班顺路大巴。','chē fèi bāo hán quán chéng jiāo tōng ， wú fǎ tuì kuǎn ， wǒ bāng nǐ lián xì xià yī bān shùn lù dà bā 。','Tiền vé đã bao gồm cả hành trình rồi, không hoàn lại được đâu, để tôi liên hệ chuyến xe buýt tiện đường tiếp theo giúp bạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_07','V1230','阮明',7,'麻烦您帮忙协调，实在不好意思耽误大家行程啦。','má fán nín bāng máng xié tiáo ， shí zài bù hǎo yì sī dān wù dà jiā xíng chéng la 。','Phiền anh sắp xếp giúp em, thật sự xin lỗi vì đã làm chậm trễ hành trình của mọi người.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1230_08','V1230','阿凯',8,'下次休息记得定好闹钟，准时回到大巴集合点哈。','xià cì xiū xī jì de dìng hǎo nào zhōng ， zhǔn shí huí dào dà bā jí hé diǎn hā 。','Lần sau nghỉ nhớ đặt báo thức, quay lại điểm tập trung xe buýt đúng giờ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1301','SHTN1','咨询校内留学生全额奖学金申请材料与截止时间',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1301','SIT1301','P1','suon_se','ban_chinh_thuc',NULL,'国内高校留学生奖学金区分学业、科研两类，科研竞赛成果是重要加分项，逾期一律关闭申报通道不接受补交。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_01','V1301','阮明',1,'张老师您好，我想来问问全额留学生奖学金的申请要求啊。','zhāng lǎo shī nín hǎo ， wǒ xiǎng lái wèn wèn quán é liú xué shēng jiǎng xué jīn de shēn qǐng yāo qiú a 。','Chào thầy Trương, em muốn hỏi về yêu cầu xin học bổng toàn phần dành cho lưu học sinh ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_02','V1301','张老师',2,'坐吧，今年申请截止下周五下午五点，材料可得提前备齐呢。','zuò ba ， jīn nián shēn qǐng jié zhǐ xià zhōu wǔ xià wǔ wǔ diǎn ， cái liào kě dé tí qián bèi qí ne 。','Ngồi đi, năm nay hạn nộp hồ sơ là 5 giờ chiều thứ Sáu tuần sau, hồ sơ phải chuẩn bị đầy đủ trước đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_03','V1301','阮明',3,'除了成绩单和护照，还需要额外提交科研证明吗？','chú le chéng jì dān hé hù zhào ， hái xū yào é wài tí jiāo kē yán zhèng míng ma ？','Ngoài bảng điểm và hộ chiếu ra, có cần nộp thêm giấy chứng nhận nghiên cứu khoa học không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_04','V1301','张老师',4,'有论文、竞赛获奖材料都可以附上，能加分不少嘛。','yǒu lùn wén 、 jìng sài huò jiǎng cái liào dōu kě yǐ fù shàng ， néng jiā fēn bù shǎo ma 。','Nếu có bài báo khoa học hay giấy khen thi đấu thì đều đính kèm được, sẽ cộng điểm kha khá đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_05','V1301','阮明',5,'纸质材料是线下交到您办公室，还是直接线上上传系统？','zhǐ zhì cái liào shì xiàn xià jiāo dào nín bàn gōng shì ， hái shì zhí jiē xiàn shàng shàng chuán xì tǒng ？','Hồ sơ giấy thì nộp trực tiếp tại văn phòng thầy hay là tải trực tuyến lên hệ thống luôn ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_06','V1301','张老师',6,'先线上填报，再打印签字送过来，缺一份都不能初审通过哦。','xiān xiàn shàng tián bào ， zài dǎ yìn qiān zì sòng guò lái ， quē yī fèn dōu bù néng chū shěn tōng guò ó 。','Điền trực tuyến trước, rồi in ra ký tên mang đến, thiếu một bản cũng không qua được vòng sơ duyệt đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1301_07','V1301','阮明',7,'好嘞，我记好时间，这周就把所有材料整理完整。','hǎo lei ， wǒ jì hǎo shí jiān ， zhè zhōu jiù bǎ suǒ yǒu cái liào zhěng lǐ wán zhěng 。','Vâng ạ, em ghi nhớ thời gian rồi, tuần này em sẽ chuẩn bị đầy đủ hết hồ sơ.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1302','SHTN1','撰写硕士保研申请文书，找专业课李教授修改个人陈述',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1302','SIT1302','P1','suon_se','ban_chinh_thuc',NULL,'国内硕博申请个人陈述重点突出科研规划，拜访导师修改文书属于学生常见礼貌求助，事后简单致谢更得体。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_01','V1302','阮明',1,'李教授，打扰您啦，这是我的保研个人陈述，想请您帮忙看看。','lǐ jiào shòu ， dǎ rǎo nín la ， zhè shì wǒ de bǎo yán gè rén chén shù ， xiǎng qǐng nín bāng máng kàn kàn 。','Thưa giáo sư Lý, làm phiền thầy chút ạ, đây là bài trình bày cá nhân xin bảo lưu học thẳng lên thạc sĩ của em, em muốn nhờ thầy xem giúp.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_02','V1302','李教授',2,'我简单翻一下，整体科研经历写得还算清晰，有两处逻辑可以调整。','wǒ jiǎn dān fān yī xià ， zhěng tǐ kē yán jīng lì xiě dé hái suàn qīng xī ， yǒu liǎng chù luó jí kě yǐ tiáo zhěng 。','Để thầy xem qua nhé, phần kinh nghiệm nghiên cứu nhìn chung viết khá rõ ràng, có hai chỗ về logic có thể điều chỉnh lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_03','V1302','阮明',3,'是不是我写实验成果那段太笼统，看不出研究价值呢？','shì bú shì wǒ xiě shí yàn chéng guǒ nà duàn tài lǒng tǒng ， kàn bù chū yán jiū jià zhí ne ？','Có phải đoạn em viết về kết quả thí nghiệm quá chung chung, không thấy rõ giá trị nghiên cứu không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_04','V1302','李教授',4,'没错，补充一组实验数据会更有说服力，我给你标出来吧。','méi cuò ， bǔ chōng yī zǔ shí yàn shù jù huì gèng yǒu shuō fú lì ， wǒ gěi nǐ biāo chū lái ba 。','Đúng vậy, bổ sung thêm một bộ số liệu thí nghiệm sẽ thuyết phục hơn, để thầy đánh dấu ra cho em.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_05','V1302','阮明',5,'太感谢您了，留学生申请国内硕士，文书是不是特别看重科研规划？','tài gǎn xiè nín le ， liú xué shēng shēn qǐng guó nèi shuò shì ， wén shū shì bú shì tè bié kàn zhòng kē yán guī huà ？','Em cảm ơn thầy nhiều ạ, lưu học sinh xin học thạc sĩ trong nước thì hồ sơ có đặc biệt coi trọng kế hoạch nghiên cứu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_06','V1302','李教授',6,'对，导师更在意你未来的研究方向，别只堆砌奖项就行啦。','duì ， dǎo shī gèng zài yì nǐ wèi lái de yán jiū fāng xiàng ， bié zhǐ duī qì jiǎng xiàng jiù xíng la 。','Đúng vậy, giáo viên hướng dẫn quan tâm hơn đến hướng nghiên cứu tương lai của em, đừng chỉ liệt kê giải thưởng là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1302_07','V1302','阮明',7,'我今晚按照您的批注修改，明天再来给您过目行吗？','wǒ jīn wǎn àn zhào nín de pī zhù xiū gǎi ， míng tiān zài lái gěi nín guò mù xíng ma ？','Tối nay em sẽ sửa theo góp ý của thầy, mai em mang lại cho thầy xem lại được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1303','SHTN1','邮件联系校外博导申请科研实习，对方迟迟未回复，找辅导员请教补救方法',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1303','SIT1303','P1','twist','ban_chinh_thuc',NULL,'国内高校教授日常邮件量大，联系导师邮件标题必须标注姓名、院校、事由，短时间重复发送邮件会被视作失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_01','V1303','阮明',1,'杨辅导员，我上周给校外博导发实习申请邮件，到现在都没回信呢。','yáng fǔ dǎo yuán ， wǒ shàng zhōu gěi xiào wài bó dǎo fā shí xí shēn qǐng yóu jiàn ， dào xiàn zài dōu méi huí xìn ne 。','Chị Dương ơi, tuần trước em gửi email xin thực tập nghiên cứu cho thầy hướng dẫn bên ngoài trường, mà đến giờ vẫn chưa thấy trả lời ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_02','V1303','小杨',2,'别着急，很多教授邮件太多容易遗漏，先看看你的邮件标题规范不？','bié zháo jí ， hěn duō jiào shòu yóu jiàn tài duō róng yì yí lòu ， xiān kàn kàn nǐ de yóu jiàn biāo tí guī fàn bù ？','Đừng lo, nhiều giáo sư nhận email nhiều quá nên dễ bị sót lắm, em xem lại tiêu đề email đã đúng chuẩn chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_03','V1303','阮明',3,'标题只写了"实习申请"，没有标注我的学校和专业，是不是太简单啦？','biāo tí zhǐ xiě le " shí xí shēn qǐng "， méi yǒu biāo zhù wǒ de xué xiào hé zhuān yè ， shì bú shì tài jiǎn dān la ？','Tiêu đề em chỉ ghi "Đơn xin thực tập" thôi, không ghi trường và chuyên ngành của em, vậy có phải là quá sơ sài không ạ?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_04','V1303','小杨',4,'国内教授习惯清晰标题，建议重发一封，开头简单自我介绍一下。','guó nèi jiào shòu xí guàn qīng xī biāo tí ， jiàn yì zhòng fā yī fēng ， kāi tóu jiǎn dān zì wǒ jiè shào yī xià 。','Giáo sư trong nước thường quen với tiêu đề rõ ràng, em nên gửi lại một email khác, mở đầu giới thiệu bản thân ngắn gọn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_05','V1303','阮明',5,'那间隔多久重发比较合适，会不会显得打扰人家呀？','nà jiàn gé duō jiǔ zhòng fā bǐ jiào hé shì ， huì bú huì xiǎn de dǎ rǎo rén jiā ya ？','Vậy cách bao lâu thì gửi lại là hợp lý ạ, có sợ làm phiền người ta không?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_06','V1303','小杨',6,'间隔七天最合适，措辞客气简洁，不要长篇大论嘛。','jiàn gé qī tiān zuì hé shì ， cuò cí kè qì jiǎn jié ， bú yào cháng piān dà lùn ma 。','Cách bảy ngày là hợp lý nhất, lời lẽ lịch sự ngắn gọn thôi, đừng viết dài dòng nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1303_07','V1303','阮明',7,'好，我重新整理邮件内容，今天傍晚重新发送试试看。','hǎo ， wǒ chóng xīn zhěng lǐ yóu jiàn nèi róng ， jīn tiān bàng wǎn chóng xīn fā sòng shì shì kàn 。','Vâng, em sẽ chỉnh lại nội dung email, chiều nay gửi lại thử xem sao ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1304','SHTN1','投递国际学术会议摘要，英文摘要翻译存在专业术语错误，被会务退回修改',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1304','SIT1304','P1','twist','chinh_thuc',NULL,'国内学术会议对专业术语有统一国标表述，留学生直译外文词汇极易出现错误，投稿前最好请国内同学校对。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_01','V1304','阮明',1,'您好，会务这边通知我的摘要初审驳回了，想知道具体哪里出错啦？','nín hǎo ， huì wù zhè biān tōng zhī wǒ de zhāi yào chū shěn bó huí le ， xiǎng zhī dào jù tǐ nǎ lǐ chū cuò la ？','Xin chào, bên ban tổ chức thông báo bài tóm tắt của em bị trả lại ở vòng sơ duyệt, em muốn biết cụ thể là sai ở đâu ạ?','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_02','V1304','小徐',2,'系统标注三处专业术语翻译偏差，和行业通用表述不一致呢。','xì tǒng biāo zhù sān chù zhuān yè shù yǔ fān yì piān chā ， hé háng yè tōng yòng biǎo shù bù yī zhì ne 。','Hệ thống đánh dấu ba chỗ dịch thuật ngữ chuyên ngành bị lệch, không khớp với cách dùng phổ biến trong ngành ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_03','V1304','阮明',3,'原来是我自行直译词汇，没有对照国内标准术语库对吧？','yuán lái shì wǒ zì xíng zhí yì cí huì ， méi yǒu duì zhào guó nèi biāo zhǔn shù yǔ kù duì ba ？','Thì ra là do em tự dịch trực tiếp, không đối chiếu với kho thuật ngữ chuẩn trong nước phải không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_04','V1304','小徐',4,'国际会议接收中文、英文稿件，专业名词一定要统一规范哦。','guó jì huì yì jiē shōu zhōng wén 、 yīng wén gǎo jiàn ， zhuān yè míng cí yí dìng yào tǒng yī guī fàn ó 。','Hội nghị quốc tế nhận cả bản thảo tiếng Trung lẫn tiếng Anh, thuật ngữ chuyên ngành nhất định phải thống nhất và chuẩn xác ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_05','V1304','阮明',5,'距离修改截止还有三天，我找实验室师兄帮忙校对来得及吗？','jù lí xiū gǎi jié zhǐ hái yǒu sān tiān ， wǒ zhǎo shí yàn shì shī xiōng bāng máng jiào duì lái de jí ma ？','Còn ba ngày nữa là hết hạn sửa, em nhờ anh khóa trên trong phòng thí nghiệm giúp hiệu đính thì có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_06','V1304','小徐',6,'完全来得及，修改完成重新上传，记得保存修改记录备查哈。','wán quán lái de jí ， xiū gǎi wán chéng chóng xīn shàng chuán ， jì de bǎo cún xiū gǎi jì lù bèi chá hā 。','Hoàn toàn kịp, sửa xong tải lên lại là được, nhớ lưu lại bản ghi chỉnh sửa để đối chiếu sau này nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1304_07','V1304','阮明',7,'太谢谢您提醒，不然我直接错过本次会议投稿机会咯。','tài xiè xiè nín tí xǐng ， bù rán wǒ zhí jiē cuò guò běn cì huì yì tóu gǎo jī huì gē 。','Em cảm ơn chị rất nhiều vì đã nhắc, không thì em đã bỏ lỡ cơ hội gửi bài lần này rồi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1305','SHTN1','组队参加全国留学生创新竞赛，队内分工产生分歧找指导老师调解',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1305','SIT1305','P1','suon_se','ban_chinh_thuc',NULL,'国内学科竞赛看重团队协作均衡分工，只争抢展示环节、回避基础工作会被评委扣分，指导老师常介入协调团队矛盾。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_01','V1305','阮明',1,'王老师，我们小组做竞赛项目，大家对分工意见不太统一，想请您协调下。','wáng lǎo shī ， wǒ men xiǎo zǔ zuò jìng sài xiàng mù ， dà jiā duì fēn gōng yì jiàn bù tài tǒng yī ， xiǎng qǐng nín xié tiáo xià 。','Thầy Vương, nhóm em làm dự án thi đấu mà mọi người bất đồng ý kiến về phân công, em muốn nhờ thầy điều phối giúp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_02','V1305','王老师',2,'先说说分歧在哪，是实验部分还是申报材料撰写这块呀？','xiān shuō shuō fēn qí zài nǎ ， shì shí yàn bù fèn hái shì shēn bào cái liào zhuàn xiě zhè kuài ya ？','Em nói xem bất đồng ở chỗ nào, là phần thí nghiệm hay phần viết hồ sơ đăng ký vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_03','V1305','阮明',3,'两位国内同学都想做答辩汇报，没人愿意整理调研数据呢。','liǎng wèi guó nèi tóng xué dōu xiǎng zuò dá biàn huì bào ， méi rén yuàn yì zhěng lǐ diào yán shù jù ne 。','Hai bạn trong nước đều muốn làm phần thuyết trình bảo vệ, không ai chịu tổng hợp số liệu khảo sát cả ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_04','V1305','王老师',4,'答辩只有一人上台，数据整理是基础工作，咱们重新分配任务吧。','dá biàn zhǐ yǒu yī rén shàng tái ， shù jù zhěng lǐ shì jī chǔ gōng zuò ， zán men chóng xīn fēn pèi rèn wù ba 。','Bảo vệ thì chỉ có một người lên thuyết trình thôi, tổng hợp số liệu là công việc nền tảng, để thầy phân công lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_05','V1305','阮明',5,'我可以负责外文文献翻译，数据整理交给其中一位同学行不行？','wǒ kě yǐ fù zé wài wén wén xiàn fān yì ， shù jù zhěng lǐ jiāo gěi qí zhōng yī wèi tóng xué xíng bù xíng ？','Em có thể phụ trách dịch tài liệu nước ngoài, còn phần tổng hợp số liệu giao cho một bạn khác được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_06','V1305','王老师',6,'这个分配很合理，大家优势互补，今晚开会统一一下分工哈。','zhè ge fēn pèi hěn hé lǐ ， dà jiā yōu shì hù bǔ ， jīn wǎn kāi huì tǒng yī yī xià fēn gōng hā 。','Phân công vậy hợp lý đấy, mọi người bổ sung thế mạnh cho nhau, tối nay họp thống nhất lại phân công nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1305_07','V1305','阮明',7,'太好了，有您帮忙调解，团队就能专心推进项目啦。','tài hǎo le ， yǒu nín bāng máng tiáo jiě ， tuán duì jiù néng zhuān xīn tuī jìn xiàng mù la 。','Tuyệt quá ạ, có thầy giúp điều phối thì cả nhóm có thể tập trung đẩy nhanh dự án rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1306','SHTN1','准备研究生复试面试，向同专业往届越南留学生请教面试流程与问答要点',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1306','SIT1306','P1','suon_se','tuy_y',NULL,'国内研究生复试注重礼貌礼仪，外籍考生语言表达存在短板时主动说明，面试官会适当降低语言要求，重点考察科研思维。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_01','V1306','阮明',1,'清哥，你去年硕士复试难不难呀，老师一般会问什么问题呢？','qīng gē ， nǐ qù nián shuò shì fù shì nán bù nán ya ， lǎo shī yì bān huì wèn shén me wèn tí ne ？','Anh Thanh ơi, năm ngoái anh phỏng vấn phúc khảo thạc sĩ có khó không, thầy cô thường hỏi gì vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_02','V1306','阮清',2,'不会刻意为难留学生，大多围绕你的本科实验、未来研究计划提问嘛。','bú huì kè yì wéi nán liú xué shēng ， dà duō wéi rào nǐ de běn kē shí yàn 、 wèi lái yán jiū jì huà tí wèn ma 。','Không cố tình làm khó lưu học sinh đâu, chủ yếu xoay quanh thí nghiệm hồi đại học và kế hoạch nghiên cứu tương lai của mình thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_03','V1306','阮明',3,'我普通话不算特别流利，面试可以适当使用英文回答专业问题吗？','wǒ pǔ tōng huà bù suàn tè bié liú lì ， miàn shì kě yǐ shì dàng shǐ yòng yīng wén huí dá zhuān yè wèn tí ma ？','Tiếng phổ thông của em nói chưa lưu loát lắm, phỏng vấn có được trả lời câu hỏi chuyên môn bằng tiếng Anh không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_04','V1306','阮清',4,'完全可以，遇到表达困难直接跟老师说明，老师们都能理解的。','wán quán kě yǐ ， yù dào biǎo dá kùn nán zhí jiē gēn lǎo shī shuō míng ， lǎo shī men dōu néng lǐ jiě de 。','Được chứ, gặp lúc diễn đạt khó khăn thì cứ nói thẳng với thầy cô, thầy cô đều hiểu mà.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_05','V1306','阮明',5,'复试有没有需要格外注意的礼仪，比如进门、离场这些细节？','fù shì yǒu méi yǒu xū yào gé wài zhù yì de lǐ yí ， bǐ rú jìn mén 、 lí chǎng zhè xiē xì jié ？','Phỏng vấn có cần chú ý lễ nghi gì đặc biệt không, kiểu như lúc vào phòng, lúc ra về ấy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_06','V1306','阮清',6,'进门先鞠躬问好，结束致谢再离场，简单大方就没问题啦。','jìn mén xiān jū gōng wèn hǎo ， jié shù zhì xiè zài lí chǎng ， jiǎn dān dà fāng jiù méi wèn tí la 。','Vào phòng thì cúi chào trước, kết thúc thì cảm ơn rồi ra về, đơn giản tự nhiên là không sao đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1306_07','V1306','阮明',7,'太感谢你分享经验，我这下心里踏实多咯。','tài gǎn xiè nǐ fēn xiǎng jīng yàn ， wǒ zhè xià xīn lǐ tà shí duō gē 。','Cảm ơn anh nhiều đã chia sẻ kinh nghiệm, giờ em thấy yên tâm hơn hẳn luôn.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1307','SHTN1','学术期刊投稿初审被拒，咨询期刊编辑拒稿原因、返修方向',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1307','SIT1307','P1','twist','chinh_thuc',NULL,'国内核心期刊初审拒稿后不支持即时返修，需补充完整实验数据、间隔周期重新投稿，一稿多投属于学术不端行为。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_01','V1307','阮明',1,'陈编辑您好，我的稿件初审被退回，想详细了解拒稿的核心原因。','chén biān jí nín hǎo ， wǒ de gǎo jiàn chū shěn bèi tuì huí ， xiǎng xiáng xì liǎo jiě jù gǎo de hé xīn yuán yīn 。','Chào biên tập viên Trần, bài của em bị trả lại ở vòng sơ duyệt, em muốn tìm hiểu kỹ lý do chính bị từ chối ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_02','V1307','陈编辑',2,'你的实验样本量偏少，论证支撑不足，达不到本刊收录标准呢。','nǐ de shí yàn yàng běn liàng piān shǎo ， lùn zhèng zhī chēng bù zú ， dá bú dào běn kān shōu lù biāo zhǔn ne 。','Mẫu thí nghiệm của em hơi ít, luận cứ chưa đủ thuyết phục, chưa đạt tiêu chuẩn đăng bài của tạp chí ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_03','V1307','阮明',3,'那我补充一组对照实验数据后，还能重新投稿这本期刊吗？','nà wǒ bǔ chōng yī zǔ duì zhào shí yàn shù jù hòu ， hái néng chóng xīn tóu gǎo zhè běn qī kān ma ？','Vậy nếu em bổ sung thêm một bộ số liệu thí nghiệm đối chứng, thì có thể gửi lại bài cho tạp chí này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_04','V1307','陈编辑',4,'可以返修重投，但需要间隔一个投稿周期，不能立刻重复投递哦。','kě yǐ fǎn xiū zhòng tóu ， dàn xū yào jiàn gé yí gè tóu gǎo zhōu qī ， bù néng lì kè chóng fù tóu dì ó 。','Có thể sửa và gửi lại, nhưng cần cách một chu kỳ nộp bài, không được nộp lại ngay lập tức ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_05','V1307','阮明',5,'参考文献格式我也按照模板调整，会不会增加录用概率呢？','cān kǎo wén xiàn gé shì wǒ yě àn zhào mú bǎn tiáo zhěng ， huì bú huì zēng jiā lù yòng gài lǜ ne ？','Em cũng chỉnh định dạng tài liệu tham khảo theo đúng mẫu, như vậy có tăng khả năng được nhận không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_06','V1307','陈编辑',6,'格式规范是基础，核心还是完善实验内容，你好好修改吧。','gé shì guī fàn shì jī chǔ ， hé xīn hái shì wán shàn shí yàn nèi róng ， nǐ hǎo hǎo xiū gǎi ba 。','Định dạng chuẩn chỉ là điều kiện cơ bản thôi, quan trọng nhất vẫn là hoàn thiện nội dung thí nghiệm, em cố gắng sửa lại nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1307_07','V1307','阮明',7,'明白啦，我重新完善实验内容，过段时间再投递过来。','míng bái la ， wǒ chóng xīn wán shàn shí yàn nèi róng ， guò duàn shí jiān zài tóu dì guò lái 。','Em hiểu rồi ạ, em sẽ hoàn thiện lại nội dung thí nghiệm, một thời gian nữa sẽ gửi lại bài.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1308','SHTN1','线下参加高校学术论坛，不会中文PPT汇报，求助会务志愿者调整设备',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1308','SIT1308','P1','twist','ban_chinh_thuc',NULL,'国内高校学术论坛鼓励外籍参会者使用英文PPT，会场一般配备翻译辅助设备，汇报时放慢语速是基本礼貌。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_01','V1308','阮明',1,'同学你好，我等下上台汇报，PPT只有英文，会场投影能切换中英字幕吗？','tóng xué nǐ hǎo ， wǒ děng xià shàng tái huì bào ，PPT zhǐ yǒu yīng wén ， huì chǎng tóu yǐng néng qiè huàn zhōng yīng zì mù ma ？','Chào bạn, lát nữa mình lên thuyết trình, PPT chỉ có tiếng Anh thôi, máy chiếu ở đây có chuyển được phụ đề tiếng Trung không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_02','V1308','小林',2,'会场设备自带字幕插件，我帮你调出中文翻译界面好不好？','huì chǎng shè bèi zì dài zì mù chā jiàn ， wǒ bāng nǐ diào chū zhōng wén fān yì jiè miàn hǎo bù hǎo ？','Thiết bị ở hội trường có sẵn plugin phụ đề, để mình bật giao diện dịch tiếng Trung giúp bạn nhé?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_03','V1308','阮明',3,'太好啦，我担心台下老师看不懂英文图表，听不懂我的讲解呢。','tài hǎo la ， wǒ dān xīn tái xià lǎo shī kàn bù dǒng yīng wén tú biǎo ， tīng bù dǒng wǒ de jiǎng jiě ne 。','Tuyệt quá, mình lo là thầy cô bên dưới không hiểu biểu đồ tiếng Anh, không nghe hiểu phần trình bày của mình.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_04','V1308','小林',4,'没关系，汇报时语速放慢一点，有听不懂的地方评委可以现场提问嘛。','méi guān xì ， huì bào shí yǔ sù fàng màn yì diǎn ， yǒu tīng bù dǒng de dì fāng píng wěi kě yǐ xiàn chǎng tí wèn ma 。','Không sao đâu, lúc trình bày bạn nói chậm lại một chút, chỗ nào không hiểu thì ban giám khảo có thể hỏi trực tiếp mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_05','V1308','阮明',5,'上台前还有五分钟调试时间，我现在能先试播一遍PPT吗？','shàng tái qián hái yǒu wǔ fēn zhōng tiáo shì shí jiān ， wǒ xiàn zài néng xiān shì bō yī biàn PPT ma ？','Trước khi lên còn năm phút để chỉnh máy, giờ mình có thể chạy thử PPT một lượt được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_06','V1308','小林',6,'可以，这边电脑你直接操作，有故障随时喊我就行咯。','kě yǐ ， zhè biān diàn nǎo nǐ zhí jiē cāo zuò ， yǒu gù zhàng suí shí hǎn wǒ jiù xíng gē 。','Được, máy tính bên này bạn cứ thao tác trực tiếp, có trục trặc gì thì gọi mình bất cứ lúc nào nhé.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1308_07','V1308','阮明',7,'辛苦你帮忙调试，这下汇报不会手忙脚乱啦。','xīn kǔ nǐ bāng máng tiáo shì ， zhè xià huì bào bú huì shǒu máng jiǎo luàn la 。','Cảm ơn bạn đã giúp chỉnh máy, giờ thì mình trình bày sẽ không bị luống cuống nữa rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1309','SHTN1','申请实验室长期科研助研岗位，面试时不懂国内科研项目申报基础流程',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1309','SIT1309','P1','that_bai_nhe','chinh_thuc',NULL,'国内实验室助研岗除基础实验外，常需协助申报各类科研项目，有项目申报经验的学生会优先录用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_01','V1309','阮明',1,'周老师您好，我特别希望留在实验室做长期助研，愿意配合所有科研工作。','zhōu lǎo shī nín hǎo ， wǒ tè bié xī wàng liú zài shí yàn shì zuò cháng qī zhù yán ， yuàn yì pèi hé suǒ yǒu kē yán gōng zuò 。','Chào thầy Chu, em rất mong được ở lại phòng thí nghiệm làm trợ lý nghiên cứu lâu dài, em sẵn sàng phối hợp mọi công việc nghiên cứu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_02','V1309','周老师',2,'那简单问一下，你了解校内大学生创新项目的申报流程吗？','nà jiǎn dān wèn yī xià ， nǐ liǎo jiě xiào nèi dà xué shēng chuàng xīn xiàng mù dì shēn bào liú chéng ma ？','Vậy thầy hỏi đơn giản nhé, em có hiểu quy trình đăng ký dự án sáng tạo sinh viên trong trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_03','V1309','阮明',3,'抱歉老师，我之前只做基础实验，完全没接触项目申报这块呢。','bào qiàn lǎo shī ， wǒ zhī qián zhǐ zuò jī chǔ shí yàn ， wán quán méi jiē chù xiàng mù shēn bào zhè kuài ne 。','Em xin lỗi thầy, trước giờ em chỉ làm thí nghiệm cơ bản thôi, hoàn toàn chưa tiếp xúc với phần đăng ký dự án này ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_04','V1309','周老师',4,'助研需要协助整理申报材料，不懂流程的话前期要花很多时间学习。','zhù yán xū yào xié zhù zhěng lǐ shēn bào cái liào ， bù dǒng liú chéng de huà qián qī yào huā hěn duō shí jiān xué xí 。','Trợ lý nghiên cứu cần hỗ trợ chuẩn bị hồ sơ đăng ký, nếu không hiểu quy trình thì giai đoạn đầu sẽ phải mất nhiều thời gian học hỏi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_05','V1309','阮明',5,'我可以快速自学申报规则，每周多花两小时熟悉流程行不行？','wǒ kě yǐ kuài sù zì xué shēn bào guī zé ， měi zhōu duō huā liǎng xiǎo shí shú xī liú chéng xíng bù xíng ？','Em có thể nhanh chóng tự học quy tắc đăng ký, mỗi tuần dành thêm hai tiếng để làm quen quy trình được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_06','V1309','周老师',6,'这次岗位名额有限，优先录取有申报经验的学生，你下次再来申请吧。','zhè cì gǎng wèi míng é yǒu xiàn ， yōu xiān lù qǔ yǒu shēn bào jīng yàn de xué shēng ， nǐ xià cì zài lái shēn qǐng ba 。','Lần này chỉ tiêu có hạn, thầy ưu tiên nhận sinh viên đã có kinh nghiệm đăng ký dự án, lần sau em quay lại nộp đơn nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1309_07','V1309','阮明',7,'好的老师，我先跟着师兄学习项目申报，明年再来投递岗位。','hǎo de lǎo shī ， wǒ xiān gēn zhe shī xiōng xué xí xiàng mù shēn bào ， míng nián zài lái tóu dì gǎng wèi 。','Vâng thưa thầy, em sẽ theo các anh chị khóa trên học cách đăng ký dự án trước, sang năm em sẽ nộp đơn lại ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1310','SHTN1','申报省级留学生科研创新项目，材料缺少中方导师签字无法提交系统',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1310','SIT1310','P1','twist','ban_chinh_thuc',NULL,'国内所有省级、校级科研项目申报均要求导师手写签字，电子签名、后期补签均无效，系统到期自动关闭通道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_01','V1310','阮明',1,'何秘书，我申报省级留学生创新项目，系统一直提示材料不通过啊。','hé mì shū ， wǒ shēn bào shěng jí liú xué shēng chuàng xīn xiàng mù ， xì tǒng yì zhí tí shì cái liào bù tōng guò a 。','Chị Hà ơi, em đăng ký dự án sáng tạo nghiên cứu cấp tỉnh cho lưu học sinh, mà hệ thống cứ báo hồ sơ không đạt ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_02','V1310','小何',2,'我帮你查看一下，项目申报书缺少指导老师手写签字页呢。','wǒ bāng nǐ chá kàn yī xià ， xiàng mù shēn bào shū quē shǎo zhǐ dǎo lǎo shī shǒu xiě qiān zì yè ne 。','Để chị kiểm tra giúp em, hồ sơ đăng ký dự án đang thiếu trang chữ ký tay của thầy hướng dẫn đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_03','V1310','阮明',3,'导师今天外出开会，我能不能先线上提交，之后补签字吗？','dǎo shī jīn tiān wài chū kāi huì ， wǒ néng bù néng xiān xiàn shàng tí jiāo ， zhī hòu bǔ qiān zì ma ？','Hôm nay thầy hướng dẫn đi họp bên ngoài, em có thể nộp trực tuyến trước rồi bổ sung chữ ký sau được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_04','V1310','小何',4,'系统关闭前必须上传带签字扫描件，不支持后期补交材料的。','xì tǒng guān bì qián bì xū shàng chuán dài qiān zì sǎo miáo jiàn ， bù zhī chí hòu qī bǔ jiāo cái liào de 。','Trước khi hệ thống đóng bắt buộc phải tải lên bản scan có chữ ký, không hỗ trợ bổ sung tài liệu sau đâu em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_05','V1310','阮明',5,'申报截止明天中午，我晚上联系导师签字再扫描来得及吗？','shēn bào jié zhǐ míng tiān zhōng wǔ ， wǒ wǎn shàng lián xì dǎo shī qiān zì zài sǎo miáo lái de jí ma ？','Hạn nộp là trưa mai, tối nay em liên hệ thầy ký rồi scan lại thì có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_06','V1310','小何',6,'抓紧时间没问题，签字一定要手写，电子签名系统不认哦。','zhuā jǐn shí jiān méi wèn tí ， qiān zì yí dìng yào shǒu xiě ， diàn zi qiān míng xì tǒng bù rèn ó 。','Tranh thủ thời gian thì không thành vấn đề, nhưng chữ ký nhất định phải viết tay, hệ thống không chấp nhận chữ ký điện tử đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1310_07','V1310','阮明',7,'我现在立刻联系导师，今晚一定补齐签字材料。','wǒ xiàn zài lì kè lián xì dǎo shī ， jīn wǎn yí dìng bǔ qí qiān zì cái liào 。','Em liên hệ thầy hướng dẫn ngay bây giờ, tối nay nhất định sẽ bổ sung đủ tài liệu có chữ ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1311','SHTN1','竞赛决赛现场答辩设备故障，PPT文件U盘损坏，和现场工作人员协商应急方案',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1311','SIT1311','P1','twist','ban_chinh_thuc',NULL,'国内竞赛答辩要求提前备份电子材料，U盘、云端双备份是通用习惯，设备故障可申请口述答辩作为应急方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_01','V1311','阮明',1,'吴师傅不好了，我的U盘读不出来，竞赛答辩马上轮到我上场啦！','wú shī fù bù hǎo le ， wǒ de U pán dú bù chū lái ， jìng sài dá biàn mǎ shàng lún dào wǒ shàng chǎng la ！','Thầy Ngô ơi, không xong rồi, USB của em không đọc được, sắp tới lượt em thuyết trình chung kết rồi!','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_02','V1311','老吴',2,'别慌，你云端有没有备份PPT？手机登录网盘直接调取也行嘛。','bié huāng ， nǐ yún duān yǒu méi yǒu bèi fèn PPT？ shǒu jī dēng lù wǎng pán zhí jiē diào qǔ yě xíng ma 。','Đừng hoảng, em có sao lưu PPT trên mây không? Đăng nhập ổ đám mây bằng điện thoại lấy trực tiếp cũng được mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_03','V1311','阮明',3,'我只存在U盘里，忘记云端备份，这下该怎么补救呢？','wǒ zhǐ cún zài U pán lǐ ， wàng jì yún duān bèi fèn ， zhè xià gāi zěn me bǔ jiù ne ？','Em chỉ lưu trong USB thôi, quên mất sao lưu lên mây, giờ phải khắc phục thế nào đây ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_04','V1311','老吴',4,'我给你十分钟，你口述项目核心内容，配合黑板手绘简图讲解。','wǒ gěi nǐ shí fēn zhōng ， nǐ kǒu shù xiàng mù hé xīn nèi róng ， pèi hé hēi bǎn shǒu huì jiǎn tú jiǎng jiě 。','Thầy cho em mười phút, em trình bày miệng nội dung cốt lõi của đề tài, kết hợp vẽ tay sơ đồ minh họa lên bảng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_05','V1311','阮明',5,'十分钟梳理全部研究内容有点紧张，能给我一张草稿纸整理思路吗？','shí fēn zhōng shū lǐ quán bù yán jiū nèi róng yǒu diǎn jǐn zhāng ， néng gěi wǒ yī zhāng cǎo gǎo zhǐ zhěng lǐ sī lù ma ？','Mười phút mà sắp xếp lại hết nội dung nghiên cứu thì hơi căng, thầy cho em xin một tờ giấy nháp để sắp ý được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_06','V1311','老吴',6,'没问题，这边纸笔你拿好，评委那边我帮你说明设备突发故障。','méi wèn tí ， zhè biān zhǐ bǐ nǐ ná hǎo ， píng wěi nà biān wǒ bāng nǐ shuō míng shè bèi tū fā gù zhàng 。','Không vấn đề gì, giấy bút đây em cầm lấy, còn phía ban giám khảo để thầy giải thích giúp em là thiết bị gặp sự cố bất ngờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1311_07','V1311','阮明',7,'太感谢您，不然我直接没法完成本次决赛答辩咯。','tài gǎn xiè nín ， bù rán wǒ zhí jiē méi fǎ wán chéng běn cì jué sài dá biàn gē 。','Em cảm ơn thầy nhiều lắm, không thì em không cách nào hoàn thành phần thuyết trình chung kết lần này đâu.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1312','SHTN1','拜访意向硕导办公室，不清楚国内师生拜访礼仪，被同门学姐提醒注意事项',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1312','SIT1312','P1','suon_se','tuy_y',NULL,'国内拜访高校导师有固定礼仪，控制谈话时长、不随意打断发言、进门敲门是师生相处基本规矩。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_01','V1312','阮明',1,'学姐，我下午要去拜访硕导，不知道有什么需要留意的礼仪吗？','xué jiě ， wǒ xià wǔ yào qù bài fǎng shuò dǎo ， bù zhī dào yǒu shén me xū yào liú yì de lǐ yí ma ？','Chị ơi, chiều nay em phải đi gặp thầy hướng dẫn thạc sĩ, không biết có phép tắc gì cần chú ý không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_02','V1312','苏学姐',2,'进办公室先轻轻敲门，得到允许再进去，别直接推门啦。','jìn bàn gōng shì xiān qīng qīng qiāo mén ， dé dào yǔn xǔ zài jìn qù ， bié zhí jiē tuī mén la 。','Vào phòng thì gõ cửa nhẹ trước, được phép rồi mới vào, đừng đẩy cửa vào thẳng nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_03','V1312','阮明',3,'沟通科研问题的时候，能不能打断老师讲话提出疑问呢？','gōu tōng kē yán wèn tí de shí hòu ， néng bù néng dǎ duàn lǎo shī jiǎng huà tí chū yí wèn ne ？','Lúc trao đổi vấn đề nghiên cứu, em có được ngắt lời thầy để hỏi luôn không chị?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_04','V1312','苏学姐',4,'等老师说完一段再提问，中途打断会显得不够尊重嘛。','děng lǎo shī shuō wán yī duàn zài tí wèn ， zhōng tú dǎ duàn huì xiǎn de bù gòu zūn zhòng ma 。','Đợi thầy nói xong một đoạn rồi mới hỏi, ngắt lời giữa chừng sẽ có vẻ thiếu tôn trọng đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_05','V1312','阮明',5,'离开的时候需要主动收拾座椅，简单道谢再出门对吧？','lí kāi de shí hòu xū yào zhǔ dòng shōu shí zuò yǐ ， jiǎn dān dào xiè zài chū mén duì ba ？','Lúc ra về em có cần chủ động dọn lại ghế, chào cảm ơn rồi mới ra ngoài đúng không chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_06','V1312','苏学姐',6,'没错，谈话控制在二十分钟以内，不要占用老师太久时间哈。','méi cuò ， tán huà kòng zhì zài èr shí fēn zhōng yǐ nèi ， bú yào zhàn yòng lǎo shī tài jiǔ shí jiān hā 。','Đúng rồi, buổi nói chuyện thì giữ trong khoảng hai mươi phút thôi, đừng chiếm quá nhiều thời gian của thầy nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1312_07','V1312','阮明',7,'多谢学姐提醒，我记住所有细节，下午礼貌拜访导师。','duō xiè xué jiě tí xǐng ， wǒ jì zhù suǒ yǒu xì jié ， xià wǔ lǐ mào bài fǎng dǎo shī 。','Em cảm ơn chị đã nhắc, em ghi nhớ hết mọi chi tiết rồi, chiều nay sẽ đến gặp thầy thật lễ phép.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1313','SHTN1','学术会议海报展示环节，听不懂国内学者提问，请求主持人帮忙转述通俗中文',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1313','SIT1313','P1','twist','ban_chinh_thuc',NULL,'国内学术会议包容外籍参会者语言短板，主持人可协助转述问题，允许中英文混合讲解海报内容。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_01','V1313','阮明',1,'刘学长，刚才那位老师提问语速太快，很多专业词汇我没听懂呢。','liú xué zhǎng ， gāng cái nà wèi lǎo shī tí wèn yǔ sù tài kuài ， hěn duō zhuān yè cí huì wǒ méi tīng dǒng ne 。','Anh Lưu ơi, thầy vừa hỏi nói nhanh quá, nhiều từ chuyên môn em không nghe kịp.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_02','V1313','刘学长',2,'没关系，我把他的问题用简单词汇重新跟你复述一遍吧。','méi guān xì ， wǒ bǎ tā de wèn tí yòng jiǎn dān cí huì chóng xīn gēn nǐ fù shù yī biàn ba 。','Không sao, để anh dùng từ đơn giản diễn đạt lại câu hỏi của thầy cho em nghe nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_03','V1313','阮明',3,'实在不好意思，我的中文听力应对快速专业对话还有点吃力。','shí zài bù hǎo yì sī ， wǒ de zhōng wén tīng lì yìng duì kuài sù zhuān yè duì huà hái yǒu diǎn chī lì 。','Em thật sự ngại quá, khả năng nghe tiếng Trung của em với những đoạn hội thoại chuyên môn nhanh vẫn còn hơi khó khăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_04','V1313','刘学长',4,'参会老师都能理解留学生语言情况，不用觉得尴尬的。','cān huì lǎo shī dōu néng lǐ jiě liú xué shēng yǔ yán qíng kuàng ， bù yòng jué de gān gà de 。','Các thầy dự hội thảo đều hiểu tình hình ngôn ngữ của lưu học sinh mà, em không cần thấy ngại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_05','V1313','阮明',5,'麻烦你转述完，我可以结合英文辅助说明我的实验结论吗？','má fán nǐ zhuǎn shù wán ， wǒ kě yǐ jié hé yīng wén fǔ zhù shuō míng wǒ de shí yàn jié lùn ma ？','Anh diễn đạt lại xong, em có thể dùng thêm tiếng Anh để giải thích rõ hơn kết luận thực nghiệm của mình được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_06','V1313','刘学长',6,'完全没问题，中英结合讲解大家更容易听懂你的研究。','wán quán méi wèn tí ， zhōng yīng jié hé jiǎng jiě dà jiā gèng róng yì tīng dǒng nǐ de yán jiū 。','Hoàn toàn được, kết hợp cả tiếng Trung lẫn tiếng Anh thì mọi người sẽ dễ hiểu nghiên cứu của em hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1313_07','V1313','阮明',7,'太感谢你帮忙，不然我没办法完整回应老师的提问啦。','tài gǎn xiè nǐ bāng máng ， bù rán wǒ méi bàn fǎ wán zhěng huí yìng lǎo shī de tí wèn la 。','Em cảm ơn anh giúp đỡ nhiều lắm, không thì em không cách nào trả lời trọn vẹn câu hỏi của thầy được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1314','SHTN1','申请公派联合培养硕士项目，公证护照学历材料时遗漏中英文翻译件',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1314','SIT1314','P1','that_bai_nhe','chinh_thuc',NULL,'国内公派留学、联合培养项目所有外籍学历、护照公证，必须搭配公证处出具标准双语翻译件，缺一不可。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_01','V1314','阮明',1,'王老师，我提交公派联合培养材料，系统提示公证材料审核失败了。','wáng lǎo shī ， wǒ tí jiāo gōng pài lián hé péi yǎng cái liào ， xì tǒng tí shì gōng zhèng cái liào shěn hé shī bài le 。','Thưa cô Vương, em vừa nộp hồ sơ chương trình đào tạo liên kết công phái, hệ thống báo là hồ sơ công chứng không qua được thẩm định ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_02','V1314','王老师',2,'你的学历公证只有中文原件，缺少正规机构出具的英文翻译件呢。','nǐ de xué lì gōng zhèng zhǐ yǒu zhōng wén yuán jiàn ， quē shǎo zhèng guī jī gòu chū jù de yīng wén fān yì jiàn ne 。','Bản công chứng học vị của em chỉ có bản gốc tiếng Trung, thiếu bản dịch tiếng Anh do cơ quan chính quy cấp.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_03','V1314','阮明',3,'我以为只需要公证纸质证件，没想到还要配套翻译文件啊。','wǒ yǐ wéi zhǐ xū yào gōng zhèng zhǐ zhì zhèng jiàn ， méi xiǎng dào hái yào pèi tào fān yì wén jiàn a 。','Em cứ nghĩ chỉ cần công chứng bản giấy tờ gốc thôi, không ngờ còn phải có thêm bản dịch kèm theo.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_04','V1314','王老师',4,'公派项目要求所有外籍证件、学历都附带官方双语翻译公证件。','gōng pài xiàng mù yāo qiú suǒ yǒu wài jí zhèng jiàn 、 xué lì dōu fù dài guān fāng shuāng yǔ fān yì gōng zhèng jiàn 。','Chương trình công phái yêu cầu mọi giấy tờ và văn bằng của người nước ngoài đều phải kèm bản dịch song ngữ đã được công chứng chính thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_05','V1314','阮明',5,'公证机构今天下班了，是不是赶不上本周申报批次了？','gōng zhèng jī gòu jīn tiān xià bān le ， shì bú shì gǎn bù shàng běn zhōu shēn bào pī cì le ？','Cơ quan công chứng hôm nay đã đóng cửa rồi, liệu em có kịp nộp trong đợt xét duyệt tuần này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_06','V1314','王老师',6,'是的，这批申报今天截止，你只能等下一批开放再提交咯。','shì de ， zhè pī shēn bào jīn tiān jié zhǐ ， nǐ zhǐ néng děng xià yī pī kāi fàng zài tí jiāo gē 。','Đúng vậy, đợt nộp hồ sơ này chốt hạn hôm nay rồi, em chỉ có thể chờ đợt tiếp theo mở ra mới nộp được thôi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1314_07','V1314','阮明',7,'都怪我没有仔细阅读申报须知，只能下次再申请项目了。','dōu guài wǒ méi yǒu zǐ xì yuè dú shēn bào xū zhī ， zhǐ néng xià cì zài shēn qǐng xiàng mù le 。','Đều tại em không đọc kỹ hướng dẫn nộp hồ sơ, thôi thì em đành đợi đợt sau nộp lại vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1315','SHTN1','竞赛申报系统填报外籍证件拼音，和护照拼写不一致导致提交失败',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1315','SIT1315','P1','twist','ban_chinh_thuc',NULL,'国内所有面向留学生的竞赛、科研申报系统实名核验严格，姓名拼音大小写、字母拼写必须与护照完全统一。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_01','V1315','阮明',1,'你好，我提交竞赛申报表单一直失败，提示证件信息不匹配呢。','nǐ hǎo ， wǒ tí jiāo jìng sài shēn bào biǎo dān yī zhí shī bài ， tí shì zhèng jiàn xìn xī bù pǐ pèi ne 。','Chào chị, em nộp biểu mẫu đăng ký cuộc thi mãi không được, hệ thống báo thông tin giấy tờ không khớp ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_02','V1315','小唐',2,'我后台核对一下，你填写的姓名拼音和护照上拼写有一处字母不同。','wǒ hòu tái hé duì yī xià ， nǐ tián xiě de xìng míng pīn yīn hé hù zhào shàng pīn xiě yǒu yī chù zì mǔ bù tóng 。','Để chị kiểm tra lại trên hệ thống xem, tên phiên âm em điền và trên hộ chiếu có một chữ cái không trùng khớp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_03','V1315','阮明',3,'我输入时手滑打错字母，没想到系统会严格比对每一个字符啊。','wǒ shū rù shí shǒu huá dǎ cuò zì mǔ ， méi xiǎng dào xì tǒng huì yán gé bǐ duì měi yí gè zì fú a 。','Lúc nhập em bấm nhầm tay gõ sai chữ cái, không ngờ hệ thống lại so khớp chặt chẽ từng ký tự như vậy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_04','V1315','小唐',4,'留学生参赛实行实名核验，拼音必须和护照完全一致才行。','liú xué shēng cān sài shí xíng shí míng hé yàn ， pīn yīn bì xū hé hù zhào wán quán yí zhì cái xíng 。','Lưu học sinh dự thi phải thực hiện xác thực danh tính thật, nên phiên âm bắt buộc phải khớp hoàn toàn với hộ chiếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_05','V1315','阮明',5,'那我直接修改表单拼音，刷新页面就能重新提交吗？','nà wǒ zhí jiē xiū gǎi biǎo dān pīn yīn ， shuā xīn yè miàn jiù néng chóng xīn tí jiāo ma ？','Vậy em sửa lại phần phiên âm trên biểu mẫu, rồi tải lại trang là có thể nộp lại được luôn phải không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_06','V1315','小唐',6,'是的，修改完成保存，五分钟后再提交系统就能核验通过哈。','shì de ， xiū gǎi wán chéng bǎo cún ， wǔ fēn zhōng hòu zài tí jiāo xì tǒng jiù néng hé yàn tōng guò hā 。','Đúng rồi, sửa xong lưu lại, khoảng năm phút sau nộp lại thì hệ thống sẽ xác thực qua thôi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1315_07','V1315','阮明',7,'好嘞，我马上修正拼写，尽快完成申报。','hǎo lei ， wǒ mǎ shàng xiū zhèng pīn xiě ， jǐn kuài wán chéng shēn bào 。','Dạ được, em sửa lại chính tả ngay đây, cố gắng hoàn thành đăng ký sớm nhất có thể.','AM08') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1316','SHTN1','完成实验论文数据，想挂国内导师一作、自己二作，和导师沟通署名规范',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1316','SIT1316','P1','suon_se','ban_chinh_thuc',NULL,'国内学术论文署名遵循实际贡献排序，学生独立完成核心实验可列为一作，导师通常担任通讯作者，强行争抢一作不符合学术规范。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_01','V1316','阮明',1,'张老师，论文数据全部整理完毕，想跟您沟通一下作者署名顺序。','zhāng lǎo shī ， lùn wén shù jù quán bù zhěng lǐ wán bì ， xiǎng gēn nín gōu tōng yī xià zuò zhě shǔ míng shùn xù 。','Thưa thầy Trương, dữ liệu bài báo em đã xử lý xong hết rồi, em muốn trao đổi với thầy về thứ tự tác giả ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_02','V1316','张导师',2,'你全程主导实验设计与数据采集，按惯例你放第一作者就行啦。','nǐ quán chéng zhǔ dǎo shí yàn shè jì yǔ shù jù cǎi jí ， àn guàn lì nǐ fàng dì yī zuò zhě jiù xíng la 。','Em là người chủ trì toàn bộ thiết kế thí nghiệm và thu thập dữ liệu, theo thông lệ thì em đứng tên tác giả thứ nhất là được rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_03','V1316','阮明',3,'可是国内期刊是不是更看重导师一作，对论文影响力更好呢？','kě shì guó nèi qī kān shì bú shì gèng kàn zhòng dǎo shī yī zuò ， duì lùn wén yǐng xiǎng lì gèng hǎo ne ？','Nhưng tạp chí trong nước có phải là coi trọng tên thầy đứng đầu hơn không ạ, vậy sẽ tốt cho sức ảnh hưởng của bài báo hơn?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_04','V1316','张导师',4,'留学生独立完成实验，学生一作完全符合期刊署名规范，不用谦让嘛。','liú xué shēng dú lì wán chéng shí yàn ， xué shēng yī zuò wán quán fú hé qī kān shǔ míng guī fàn ， bù yòng qiān ràng ma 。','Lưu học sinh tự mình hoàn thành thí nghiệm thì em đứng tên tác giả thứ nhất hoàn toàn đúng quy định của tạp chí, không cần nhường đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_05','V1316','阮明',5,'那我二作标注您，感谢您全程指导实验设计可以吗？','nà wǒ èr zuò biāo zhù nín ， gǎn xiè nín quán chéng zhǐ dǎo shí yàn shè jì kě yǐ ma ？','Vậy em ghi tên thầy là đồng tác giả thứ hai, để cảm ơn thầy đã hướng dẫn toàn bộ thiết kế thí nghiệm, được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_06','V1316','张导师',6,'当然，通讯作者留我的名字，后续期刊对接由我处理哈。','dāng rán ， tōng xùn zuò zhě liú wǒ de míng zì ， hòu xù qī kān duì jiē yóu wǒ chǔ lǐ hā 。','Được chứ, còn tác giả liên hệ thì cứ để tên thầy, việc liên hệ với tạp chí sau này thầy lo cho.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1316_07','V1316','阮明',7,'太感谢您体谅留学生，我现在就调整论文作者信息。','tài gǎn xiè nín tǐ liàng liú xué shēng ， wǒ xiàn zài jiù tiáo zhěng lùn wén zuò zhě xìn xī 。','Em cảm ơn thầy đã thông cảm cho lưu học sinh nhiều lắm, để em điều chỉnh lại thông tin tác giả bài báo ngay bây giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1317','SHTN1','受邀做校内留学生学术分享，不知道汇报时长、评分标准咨询学院教务老师',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1317','SIT1317','P1','suon_se','ban_chinh_thuc',NULL,'校内留学生学术分享会对语言表达包容度高，评审核心考察科研创新内容，不会因普通话不流利压低分数。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_01','V1317','阮明',1,'李老师您好，学院邀请我做留学生学术分享，想确认汇报相关要求啊。','lǐ lǎo shī nín hǎo ， xué yuàn yāo qǐng wǒ zuò liú xué shēng xué shù fēn xiǎng ， xiǎng què rèn huì bào xiāng guān yāo qiú a 。','Thưa cô Lý, khoa mời em làm buổi chia sẻ học thuật cho lưu học sinh, em muốn xác nhận lại các yêu cầu liên quan đến bài báo cáo ạ.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_02','V1317','李老师',2,'单人汇报严格控制在十五分钟，之后五分钟留给台下师生提问呢。','dān rén huì bào yán gé kòng zhì zài shí wǔ fēn zhōng ， zhī hòu wǔ fēn zhōng liú gěi tái xià shī shēng tí wèn ne 。','Mỗi người báo cáo được khống chế nghiêm ngặt trong mười lăm phút, sau đó dành năm phút cho thầy cô và sinh viên phía dưới đặt câu hỏi.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_03','V1317','阮明',3,'评分重点看研究成果，还是我的中文表达流畅程度呀？','píng fēn zhòng diǎn kàn yán jiū chéng guǒ ， hái shì wǒ de zhōng wén biǎo dá liú chàng chéng dù ya ？','Việc chấm điểm chủ yếu xem trọng kết quả nghiên cứu, hay là mức độ trôi chảy trong cách diễn đạt tiếng Trung của em ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_04','V1317','李老师',4,'更看重科研内容，语言表达只做参考，外籍学生不会刻意扣分的。','gèng kàn zhòng kē yán nèi róng ， yǔ yán biǎo dá zhǐ zuò cān kǎo ， wài jí xué shēng bú huì kè yì kòu fēn de 。','Chủ yếu xem trọng nội dung nghiên cứu, phần diễn đạt ngôn ngữ chỉ mang tính tham khảo thôi, sinh viên nước ngoài sẽ không bị trừ điểm cố ý đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_05','V1317','阮明',5,'PPT页面数量有没有限制，多放几张实验图可以吗？','PPT yè miàn shù liàng yǒu méi yǒu xiàn zhì ， duō fàng jǐ zhāng shí yàn tú kě yǐ ma ？','Số trang PPT có bị giới hạn không ạ, em cho thêm vài trang hình ảnh thực nghiệm được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_06','V1317','李老师',6,'没有页数限制，简洁清晰为主，不用堆砌大量文字哦。','méi yǒu yè shù xiàn zhì ， jiǎn jié qīng xī wéi zhǔ ， bù yòng duī qì dà liàng wén zì ó 。','Không giới hạn số trang, chủ yếu là ngắn gọn rõ ràng, không cần nhồi nhét quá nhiều chữ đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1317_07','V1317','阮明',7,'清楚啦，我按照十五分钟时长准备分享内容。','qīng chǔ la ， wǒ àn zhào shí wǔ fēn zhōng shí cháng zhǔn bèi fēn xiǎng nèi róng 。','Em rõ rồi ạ, em sẽ chuẩn bị nội dung chia sẻ theo đúng thời lượng mười lăm phút.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1318','SHTN1','申报校级海外交流科研基金，过往竞赛获奖证书无中文翻译无法通过初审',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1318','SIT1318','P1','twist','ban_chinh_thuc',NULL,'国内各类科研基金申报，境外获奖证明必须校内官方翻译机构出具中文译本，个人手写翻译不具备审核效力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_01','V1318','阮明',1,'赵老师，我的海外科研基金初审被驳回，能告知具体问题在哪吗？','zhào lǎo shī ， wǒ de hǎi wài kē yán jī jīn chū shěn bèi bó huí ， néng gào zhī jù tǐ wèn tí zài nǎ ma ？','Thưa thầy Triệu, hồ sơ quỹ nghiên cứu khoa học ở nước ngoài của em bị trả lại ở vòng sơ khảo, thầy có thể cho em biết vấn đề cụ thể ở đâu không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_02','V1318','赵老师',2,'你提交的海外竞赛证书全是越南语，没有中文翻译无法核实奖项等级。','nǐ tí jiāo de hǎi wài jìng sài zhèng shū quán shì yuè nán yǔ ， méi yǒu zhōng wén fān yì wú fǎ hé shí jiǎng xiàng děng jí 。','Chứng chỉ giải thưởng các cuộc thi nước ngoài em nộp toàn bằng tiếng Việt, không có bản dịch tiếng Trung nên không thể xác minh hạng giải.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_03','V1318','阮明',3,'我自己手写翻译一份证书内容，能不能临时上传凑合用呢？','wǒ zì jǐ shǒu xiě fān yì yī fèn zhèng shū nèi róng ， néng bù néng lín shí shàng chuán còu hé yòng ne ？','Em tự tay dịch một bản nội dung chứng chỉ, liệu có thể tạm thời tải lên dùng tạm được không ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_04','V1318','赵老师',4,'不行哦，基金申报只认可学校翻译中心出具的正规翻译件嘛。','bù xíng ó ， jī jīn shēn bào zhǐ rèn kě xué xiào fān yì zhōng xīn chū jù de zhèng guī fān yì jiàn ma 。','Không được đâu, hồ sơ quỹ chỉ công nhận bản dịch chính quy do trung tâm dịch thuật của trường cấp thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_05','V1318','阮明',5,'翻译中心明天上午开门，我明天一早去办理翻译来得及吗？','fān yì zhōng xīn míng tiān shàng wǔ kāi mén ， wǒ míng tiān yī zǎo qù bàn lǐ fān yì lái de jí ma ？','Trung tâm dịch thuật sáng mai mở cửa, em đến làm dịch thuật sáng sớm mai thì có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_06','V1318','赵老师',6,'申报还有四天截止，完全来得及，办好立刻上传系统就行。','shēn bào hái yǒu sì tiān jié zhǐ ， wán quán lái de jí ， bàn hǎo lì kè shàng chuán xì tǒng jiù xíng 。','Hồ sơ còn bốn ngày nữa mới hết hạn, hoàn toàn kịp, làm xong tải lên hệ thống ngay là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1318_07','V1318','阮明',7,'好，我明天第一时间去翻译中心处理证书。','hǎo ， wǒ míng tiān dì yī shí jiān qù fān yì zhōng xīn chǔ lǐ zhèng shū 。','Dạ vâng, sáng mai em sẽ đến trung tâm dịch thuật xử lý chứng chỉ ngay đầu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1319','SHTN1','研究生预报名系统无法识别外籍身份证，找研究生院办公室人工核验信息',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1319','SIT1319','P1','suon_se','chinh_thuc',NULL,'国内研究生报名系统默认适配内地身份证，外籍留学生均需前往研究生院线下人工备案护照信息。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_01','V1319','阮明',1,'刘老师您好，硕士预报名系统识别不了我的外籍护照，一直提交失败。','liú lǎo shī nín hǎo ， shuò shì yù bào míng xì tǒng shí bié bù liǎo wǒ de wài jí hù zhào ， yì zhí tí jiāo shī bài 。','Chào thầy Lưu, hệ thống đăng ký sơ bộ thạc sĩ không nhận diện được hộ chiếu nước ngoài của em, cứ nộp là báo lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_02','V1319','刘老师',2,'境外证件系统数据库匹配有限，你带护照原件来做人工核验吧。','jìng wài zhèng jiàn xì tǒng shù jù kù pǐ pèi yǒu xiàn ， nǐ dài hù zhào yuán jiàn lái zuò rén gōng hé yàn ba 。','Cơ sở dữ liệu hệ thống với giấy tờ nước ngoài khớp còn hạn chế, em mang hộ chiếu gốc đến để đối chiếu thủ công nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_03','V1319','阮明',3,'人工核验需要填写额外表格吗，流程会不会很繁琐呢？','rén gōng hé yàn xū yào tián xiě é wài biǎo gé ma ， liú chéng huì bú huì hěn fán suǒ ne ？','Đối chiếu thủ công có phải điền thêm mẫu gì không ạ, thủ tục có rườm rà lắm không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_04','V1319','刘老师',4,'只填一张外籍考生信息备案表，十分钟就能完成全部手续啦。','zhǐ tián yī zhāng wài jí kǎo shēng xìn xī bèi àn biǎo ， shí fēn zhōng jiù néng wán chéng quán bù shǒu xù la 。','Chỉ cần điền một tờ đăng ký thông tin thí sinh nước ngoài thôi, mười phút là xong hết thủ tục.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_05','V1319','阮明',5,'核验完成后，我返回线上系统就能正常填报志愿了对吧？','hé yàn wán chéng hòu ， wǒ fǎn huí xiàn shàng xì tǒng jiù néng zhèng cháng tián bào zhì yuàn le duì ba ？','Sau khi đối chiếu xong, em quay lại hệ thống online là điền được nguyện vọng bình thường đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_06','V1319','刘老师',6,'没错，后台同步信息之后，你直接正常报名即可。','méi cuò ， hòu tái tóng bù xìn xī zhī hòu ， nǐ zhí jiē zhèng cháng bào míng jí kě 。','Đúng rồi, sau khi hệ thống đồng bộ thông tin thì em đăng ký bình thường là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1319_07','V1319','阮明',7,'辛苦老师帮忙人工处理，不然我没法按时完成预报名咯。','xīn kǔ lǎo shī bāng máng rén gōng chǔ lǐ ， bù rán wǒ méi fǎ àn shí wán chéng yù bào míng gē 。','Cảm ơn thầy đã giúp em xử lý thủ công, không thì em không kịp hoàn thành đăng ký sơ bộ đúng hạn mất ạ.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1320','SHTN1','跨校联合科研交流会，不会主动上前和国内教授交换名片，请教带队老师社交方式',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1320','SIT1320','P1','suon_se','ban_chinh_thuc',NULL,'国内学术社交递名片讲究双手递送，自我介绍简洁得体，交流会主动结识导师是拓展科研资源的常规方式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_01','V1320','阮明',1,'陈老师，交流会好多教授，我不知道怎么主动上前交流交换名片呢。','chén lǎo shī ， jiāo liú huì hǎo duō jiào shòu ， wǒ bù zhī dào zěn me zhǔ dòng shàng qián jiāo liú jiāo huàn míng piàn ne 。','Thầy Trần ơi, buổi giao lưu có nhiều giáo sư quá, em không biết chủ động lại gần trao đổi và trao danh thiếp thế nào ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_02','V1320','陈老师',2,'等教授休息空档再上前，先简单自我介绍，再双手递出名片吧。','děng jiào shòu xiū xī kōng dàng zài shàng qián ， xiān jiǎn dān zì wǒ jiè shào ， zài shuāng shǒu dì chū míng piàn ba 。','Đợi lúc giáo sư rảnh thì lại gần, trước tiên giới thiệu bản thân ngắn gọn, rồi hai tay đưa danh thiếp nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_03','V1320','阮明',3,'自我介绍需要先说学校姓名，还是直接讲我的研究方向呀？','zì wǒ jiè shào xū yào xiān shuō xué xiào xìng míng ， hái shì zhí jiē jiǎng wǒ de yán jiū fāng xiàng ya ？','Giới thiệu bản thân thì nên nói tên trường trước, hay là nói luôn hướng nghiên cứu của em ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_04','V1320','陈老师',4,'先报院校姓名，再简单说明研究课题，简短两三句就好嘛。','xiān bào yuàn xiào xìng míng ， zài jiǎn dān shuō míng yán jiū kè tí ， jiǎn duǎn liǎng sān jù jiù hǎo ma 。','Nói tên trường trước, rồi nói ngắn gọn đề tài nghiên cứu, khoảng hai ba câu là được rồi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_05','V1320','阮明',5,'交换名片之后，要不要主动记下教授的研究方向方便后续联系？','jiāo huàn míng piàn zhī hòu ， yào bù yào zhǔ dòng jì xià jiào shòu de yán jiū fāng xiàng fāng biàn hòu xù lián xì ？','Sau khi trao danh thiếp, em có nên chủ động ghi lại hướng nghiên cứu của giáo sư để tiện liên hệ sau này không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_06','V1320','陈老师',6,'最好简单记录，后续邮件沟通时提及本次交流会更有礼貌哈。','zuì hǎo jiǎn dān jì lù ， hòu xù yóu jiàn gōu tōng shí tí jí běn cì jiāo liú huì gèng yǒu lǐ mào hā 。','Tốt nhất nên ghi chú ngắn gọn, sau này gửi email nhắc đến buổi giao lưu này thì sẽ lịch sự hơn.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1320_07','V1320','阮明',7,'学到很多社交细节，我等下主动和各位老师交流。','xué dào hěn duō shè jiāo xì jié ， wǒ děng xià zhǔ dòng hé gè wèi lǎo shī jiāo liú 。','Em học được nhiều điều về giao tiếp quá, lát nữa em sẽ chủ động qua chào các thầy cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1321','SHTN1','创新竞赛结题答辩，评委指出项目落地可行性不足，现场简短答辩补救',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1321','SIT1321','P1','twist','chinh_thuc',NULL,'国内创新创业类竞赛不只看重实验创新，项目产业落地可行性是评委重点评分板块，缺少落地规划会大幅扣分。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_01','V1321','周教授',1,'你的项目实验效果很好，但缺少落地实践方案，实用性偏弱。','nǐ de xiàng mù shí yàn xiào guǒ hěn hǎo ， dàn quē shǎo luò dì shí jiàn fāng àn ， shí yòng xìng piān ruò 。','Kết quả thí nghiệm của em rất tốt, nhưng thiếu phương án triển khai thực tế, tính ứng dụng còn yếu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_02','V1321','阮明',2,'周教授，我前期侧重实验室研究，忽略产业落地这块，实在抱歉。','zhōu jiào shòu ， wǒ qián qī cè zhòng shí yàn shì yán jiū ， hū lüè chǎn yè luò dì zhè kuài ， shí zài bào qiàn 。','Thưa giáo sư Chu, giai đoạn đầu em chú trọng nghiên cứu trong phòng thí nghiệm, có bỏ qua phần triển khai thực tế, em thật sự xin lỗi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_03','V1321','周教授',3,'那你简单说说，如果落地推广，打算怎么优化现有方案呢？','nà nǐ jiǎn dān shuō shuō ， rú guǒ luò dì tuī guǎng ， dǎ suàn zěn me yōu huà xiàn yǒu fāng àn ne ？','Vậy em nói ngắn gọn xem, nếu triển khai thực tế thì em định tối ưu phương án hiện tại như thế nào?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_04','V1321','阮明',4,'我后续计划和本地小微企业合作，小规模试点测试产品性能。','wǒ hòu xù jì huà hé běn dì xiǎo wēi qǐ yè hé zuò ， xiǎo guī mó shì diǎn cè shì chǎn pǐn xìng néng 。','Sau này em dự định hợp tác với các doanh nghiệp nhỏ tại địa phương, thử nghiệm quy mô nhỏ để kiểm tra hiệu năng sản phẩm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_05','V1321','周教授',5,'这个思路可行，下次结题材料补充一份落地实施规划吧。','zhè ge sī lù kě xíng ， xià cì jié tí cái liào bǔ chōng yī fèn luò dì shí shī guī huà ba 。','Hướng này khả thi đấy, lần kết đề tài sau em bổ sung thêm một bản kế hoạch triển khai thực tế nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_06','V1321','阮明',6,'好的，答辩结束我立刻完善落地方案，补充进结题报告。','hǎo de ， dá biàn jié shù wǒ lì kè wán shàn luò dì fāng àn ， bǔ chōng jìn jié tí bào gào 。','Vâng ạ, sau buổi bảo vệ em sẽ hoàn thiện ngay phương án triển khai và bổ sung vào báo cáo kết đề tài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_07','V1321','周教授',7,'整体创新点突出，补齐落地规划不影响本次项目结项哈。','zhěng tǐ chuàng xīn diǎn tū chū ， bǔ qí luò dì guī huà bù yǐng xiǎng běn cì xiàng mù jié xiàng hā 。','Nhìn chung điểm sáng tạo của đề tài rất nổi bật, bổ sung kế hoạch triển khai không ảnh hưởng đến việc kết đề tài lần này đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1321_08','V1321','阮明',8,'感谢教授给出改进建议，我会完整完善项目材料。','gǎn xiè jiào shòu gěi chū gǎi jìn jiàn yì ， wǒ huì wán zhěng wán shàn xiàng mù cái liào 。','Em cảm ơn giáo sư đã góp ý, em sẽ hoàn thiện đầy đủ tài liệu đề tài ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1322','SHTN1','申请导师名下横向科研项目，不清楚学生劳务补贴发放标准咨询师兄',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1322','SIT1322','P1','suon_se','tuy_y',NULL,'国内高校横向科研项目学生劳务补贴统一标准，不区分中外学生，凭工时记录按月发放，无特殊差异化待遇。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_01','V1322','阮明',1,'峰师兄，我想加入导师横向项目，学生劳务补贴是怎么计算的呀？','fēng shī xiōng ， wǒ xiǎng jiā rù dǎo shī héng xiàng xiàng mù ， xué shēng láo wù bǔ tiē shì zěn me jì suàn de ya ？','Anh Phong ơi, em muốn tham gia dự án ngang của thầy hướng dẫn, trợ cấp lao động cho sinh viên tính thế nào vậy anh?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_02','V1322','林峰',2,'按每月实际参与工时核算，基础标准校内统一规定好啦。','àn měi yuè shí jì cān yù gōng shí hé suàn ， jī chǔ biāo zhǔn xiào nèi tǒng yī guī dìng hǎo la 。','Tính theo số giờ tham gia thực tế mỗi tháng, mức cơ bản thì trường quy định thống nhất rồi.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_03','V1322','阮明',3,'留学生和国内学生补贴标准是一样的，还是会有差别呢？','liú xué shēng hé guó nèi xué shēng bǔ tiē biāo zhǔn shì yī yàng de ， hái shì huì yǒu chā bié ne ？','Mức trợ cấp cho du học sinh với sinh viên trong nước có giống nhau không, hay có khác biệt gì không anh?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_04','V1322','林峰',4,'完全统一标准，只看你的实验工作量，不分国籍嘛。','wán quán tǒng yī biāo zhǔn ， zhǐ kàn nǐ de shí yàn gōng zuò liàng ， bù fēn guó jí ma 。','Hoàn toàn thống nhất một mức, chỉ tính theo khối lượng công việc thí nghiệm thôi, không phân biệt quốc tịch đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_05','V1322','阮明',5,'补贴每月什么时候发放，需要自己提交工时记录表吗？','bǔ tiē měi yuè shén me shí hòu fā fàng ， xū yào zì jǐ tí jiāo gōng shí jì lù biǎo ma ？','Trợ cấp phát hàng tháng vào lúc nào vậy anh, em có cần tự nộp bảng ghi giờ làm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_06','V1322','林峰',6,'每月底上交工时表，次月中旬财务统一发放到校园卡。','měi yuè dǐ shàng jiāo gōng shí biǎo ， cì yuè zhōng xún cái wù tǒng yī fā fàng dào xiào yuán kǎ 。','Cuối mỗi tháng nộp bảng giờ làm, giữa tháng sau phòng tài vụ sẽ phát thống nhất vào thẻ sinh viên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1322_07','V1322','阮明',7,'明白了，工作量我会认真记录，好好参与项目研究。','míng bái le ， gōng zuò liàng wǒ huì rèn zhēn jì lù ， hǎo hǎo cān yù xiàng mù yán jiū 。','Em hiểu rồi, em sẽ ghi chép khối lượng công việc cẩn thận và tham gia dự án nghiêm túc ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1323','SHTN1','国际学术会议线下注册，忘记携带纸质接收函，会务处不允许入场',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1323','SIT1323','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内线下学术会议注册优先核验纸质录用证明，手机电子版仅作备用，临近截止时间无法临时补办入场资格。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_01','V1323','阮明',1,'小郑你好，我来办理会议注册，忘记打印纸质摘要接收函了怎么办？','xiǎo zhèng nǐ hǎo ， wǒ lái bàn lǐ huì yì zhù cè ， wàng jì dǎ yìn zhǐ zhì zhāi yào jiē shōu hán le zěn me bàn ？','Chào bạn Tiểu Trịnh, mình đến làm thủ tục đăng ký hội nghị, mình quên in thư xác nhận nhận bài bản giấy rồi, giờ phải làm sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_02','V1323','小郑',2,'线下注册必须核验纸质接收函，电子版图片暂时不能作为凭证哦。','xiàn xià zhù cè bì xū hé yàn zhǐ zhì jiē shōu hán ， diàn zi bǎn tú piàn zàn shí bù néng zuò wéi píng zhèng ó 。','Đăng ký trực tiếp bắt buộc phải kiểm tra thư xác nhận bản giấy, ảnh chụp bản điện tử tạm thời không dùng làm bằng chứng được ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_03','V1323','阮明',3,'附近有没有打印店，我现在去打印还来得及入场吗？','fù jìn yǒu méi yǒu dǎ yìn diàn ， wǒ xiàn zài qù dǎ yìn hái lái de jí rù chǎng ma ？','Gần đây có tiệm in nào không, mình đi in ngay bây giờ thì có kịp vào không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_04','V1323','小郑',4,'校门口打印店距离这里十分钟路程，注册通道一小时后关闭。','xiào mén kǒu dǎ yìn diàn jù lí zhè lǐ shí fēn zhōng lù chéng ， zhù cè tōng dào yī xiǎo shí hòu guān bì 。','Tiệm in ở cổng trường cách đây mười phút đi bộ, quầy đăng ký đóng cửa sau một tiếng nữa thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_05','V1323','阮明',5,'来回路上要二十分钟，赶不上本次上午分会场的汇报了吗？','lái huí lù shàng yào èr shí fēn zhōng ， gǎn bù shàng běn cì shàng wǔ fēn huì chǎng de huì bào le ma ？','Đi về mất khoảng hai mươi phút, vậy là không kịp phần báo cáo ở phân ban buổi sáng nay rồi phải không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_06','V1323','小郑',6,'是的，上午场次注册即将截止，你只能参加下午的论坛活动咯。','shì de ， shàng wǔ chǎng cì zhù cè jí jiāng jié zhǐ ， nǐ zhǐ néng cān jiā xià wǔ de lùn tán huó dòng gē 。','Đúng vậy, đăng ký cho buổi sáng sắp hết hạn rồi, bạn chỉ có thể tham gia diễn đàn buổi chiều thôi.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1323_07','V1323','阮明',7,'都怪我出门疏忽忘记打印，只能错过上午汇报环节。','dōu guài wǒ chū mén shū hū wàng jì dǎ yìn ， zhǐ néng cuò guò shàng wǔ huì bào huán jié 。','Đúng là tại mình sơ suất quên in trước khi ra khỏi nhà, đành phải lỡ mất phần báo cáo buổi sáng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1324','SHTN1','撰写硕士调剂申请邮件，不清楚国内调剂规则，找留学生办公室老师指导措辞',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1324','SIT1324','P1','suon_se','ban_chinh_thuc',NULL,'国内研究生调剂邮件讲究客观务实，过度客套吹捧容易让导师反感，附件材料齐全、正文简短是最优格式。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_01','V1324','阮明',1,'孙老师，我一志愿复试未通过，想写调剂申请邮件，不懂国内调剂规则呢。','sūn lǎo shī ， wǒ yī zhì yuàn fù shì wèi tōng guò ， xiǎng xiě tiáo jì shēn qǐng yóu jiàn ， bù dǒng guó nèi tiáo jì guī zé ne 。','Thầy Tôn ơi, em thi vào nguyện vọng một không qua phỏng vấn, em muốn viết email xin điều chỉnh nguyện vọng nhưng không rõ quy tắc điều chỉnh trong nước ạ.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_02','V1324','孙老师',2,'调剂只能选择有空缺名额的专业，不能跨相差过大的学科门类哦。','tiáo jì zhǐ néng xuǎn zé yǒu kòng quē míng é de zhuān yè ， bù néng kuà xiāng chà guò dà de xué kē mén lèi ó 。','Điều chỉnh nguyện vọng chỉ được chọn ngành còn chỉ tiêu trống, không được chuyển sang nhóm ngành khác biệt quá lớn đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_03','V1324','阮明',3,'邮件里需要附上哪些材料，简历和成绩单都要粘贴附件吗？','yóu jiàn lǐ xū yào fù shàng nǎ xiē cái liào ， jiǎn lì hé chéng jì dān dōu yào zhān tiē fù jiàn ma ？','Trong email cần đính kèm những tài liệu gì ạ, sơ yếu lý lịch và bảng điểm có cần dán làm file đính kèm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_04','V1324','孙老师',4,'简历、成绩单、护照扫描件全部作为附件，正文简洁说明调剂诉求。','jiǎn lì 、 chéng jì dān 、 hù zhào sǎo miáo jiàn quán bù zuò wéi fù jiàn ， zhèng wén jiǎn jié shuō míng tiáo jì sù qiú 。','Sơ yếu lý lịch, bảng điểm, bản scan hộ chiếu đều đính kèm hết, phần nội dung chính thì trình bày ngắn gọn nguyện vọng điều chỉnh thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_05','V1324','阮明',5,'发给导师的邮件，要不要过度夸赞对方课题组，会不会显得浮夸？','fā gěi dǎo shī de yóu jiàn ， yào bù yào guò dù kuā zàn duì fāng kè tí zǔ ， huì bú huì xiǎn de fú kuā ？','Gửi email cho thầy hướng dẫn thì có nên khen ngợi quá nhóm nghiên cứu của họ không ạ, sợ nghe sáo rỗng quá?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_06','V1324','孙老师',6,'客观说明自身科研经历即可，真诚简洁比刻意吹捧更受认可嘛。','kè guān shuō míng zì shēn kē yán jīng lì jí kě ， zhēn chéng jiǎn jié bǐ kè yì chuī pěng gèng shòu rèn kě ma 。','Cứ trình bày khách quan kinh nghiệm nghiên cứu của bản thân là được, chân thành ngắn gọn còn được đánh giá cao hơn là tâng bốc.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1324_07','V1324','阮明',7,'我按照您说的规范撰写邮件，写完请您帮忙再把关一下。','wǒ àn zhào nín shuō de guī fàn zhuàn xiě yóu jiàn ， xiě wán qǐng nín bāng máng zài bǎ guān yī xià 。','Em sẽ viết email theo đúng chuẩn thầy nói, viết xong nhờ thầy xem giúp em lại một lượt ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1325','SHTN1','科研成果申报评奖，不清楚国内学生成果署名排序加分规则，咨询学院科研秘书',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1325','SIT1325','P1','suon_se','ban_chinh_thuc',NULL,'国内高校科研评奖规则统一面向全体在校学生，中外学生成果加分、评奖标准无任何区别，公平统一核算分值。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_01','V1325','阮明',1,'小秦秘书，我申报校级科研成果奖，署名顺序加分标准我不太清楚。','xiǎo qín mì shū ， wǒ shēn bào xiào jí kē yán chéng guǒ jiǎng ， shǔ míng shùn xù jiā fēn biāo zhǔn wǒ bù tài qīng chǔ 。','Chị Tần thư ký ơi, em đăng ký giải thưởng nghiên cứu khoa học cấp trường, nhưng chưa rõ tiêu chuẩn cộng điểm theo thứ tự tác giả lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_02','V1325','小秦',2,'第一作者加分最高，第二、第三作者分值依次递减，通讯作者单独加分。','dì yī zuò zhě jiā fēn zuì gāo ， dì èr 、 dì sān zuò zhě fēn zhí yī cì dì jiǎn ， tōng xùn zuò zhě dān dú jiā fēn 。','Tác giả thứ nhất được cộng điểm cao nhất, tác giả thứ hai, thứ ba giảm dần, tác giả liên hệ được cộng điểm riêng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_03','V1325','阮明',3,'留学生作为一作，和国内学生的加分标准完全一样吗？','liú xué shēng zuò wéi yī zuò ， hé guó nèi xué shēng de jiā fēn biāo zhǔn wán quán yī yàng ma ？','Nếu du học sinh là tác giả chính thì tiêu chuẩn cộng điểm có hoàn toàn giống sinh viên trong nước không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_04','V1325','小秦',4,'评奖规则统一，不分中外学生，只看作者排序与期刊级别嘛。','píng jiǎng guī zé tǒng yī ， bù fēn zhōng wài xué shēng ， zhǐ kàn zuò zhě pái xù yǔ qī kān jí bié ma 。','Quy định xét giải là thống nhất, không phân biệt sinh viên trong hay ngoài nước, chỉ xét thứ tự tác giả và cấp bậc tạp chí thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_05','V1325','阮明',5,'多篇论文一起申报，是不是取分值最高的一篇计算奖项等级？','duō piān lùn wén yì qǐ shēn bào ， shì bú shì qǔ fēn zhí zuì gāo de yī piān jì suàn jiǎng xiàng děng jí ？','Nếu nộp nhiều bài cùng lúc thì có phải lấy bài có điểm cao nhất để tính hạng giải không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_06','V1325','小秦',6,'没错，系统自动核算最高分成果，其余论文作为辅助加分项。','méi cuò ， xì tǒng zì dòng hé suàn zuì gāo fēn chéng guǒ ， qí yú lùn wén zuò wéi fǔ zhù jiā fēn xiàng 。','Đúng vậy, hệ thống sẽ tự động tính bài có điểm cao nhất, các bài còn lại chỉ là điểm cộng phụ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1325_07','V1325','阮明',7,'清楚加分规则了，我整理好论文材料提交申报。','qīng chǔ jiā fēn guī zé le ， wǒ zhěng lǐ hǎo lùn wén cái liào tí jiāo shēn bào 。','Em rõ quy tắc cộng điểm rồi, em sẽ chuẩn bị đầy đủ tài liệu bài báo rồi nộp đăng ký ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1401','SATN1','本地正宗川菜馆线下点餐，分不清微辣、中辣、特辣，询问服务员辣度区别',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1401','SIT1401','P1','twist','tuy_y',NULL,'川菜辣、麻分开调整，食客可自由增减花椒辣椒，店家都会按口味定制菜品。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_01','V1401','阮明',1,'你好，水煮鱼辣度分三档，微辣会不会也很呛呢？','nǐ hǎo ， shuǐ zhǔ yú là dù fēn sān dàng ， wēi là huì bú huì yě hěn qiāng ne ？','Cho hỏi, món cá om cay chia ba mức độ cay, vị cay nhẹ có bị tê quá không vậy?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_02','V1401','小琳',2,'微辣只放少量干辣椒，中辣加花椒，特辣铺满红油很刺激哦。','wēi là zhǐ fàng shǎo liàng gàn là jiāo ， zhōng là jiā huā jiāo ， tè là pù mǎn hóng yóu hěn cì jī ó 。','Cay nhẹ chỉ cho ít ớt khô thôi, cay vừa thêm hạt tiêu, còn cay đặc biệt thì phủ đầy dầu ớt, ăn kích thích lắm luôn.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_03','V1401','阮明',3,'我肠胃不耐辣，所有菜都做成微辣，再少放花椒行吗？','wǒ cháng wèi bù nài là ， suǒ yǒu cài dōu zuò chéng wēi là ， zài shǎo fàng huā jiāo xíng ma ？','Bụng mình không chịu được cay lắm, cho tất cả các món làm cay nhẹ, với lại bớt hạt tiêu lại được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_04','V1401','小琳',4,'没问题，我给后厨备注少麻少辣，不吃麻椒也能直接去掉嘛。','méi wèn tí ， wǒ gěi hòu chú bèi zhù shǎo má shǎo là ， bù chī má jiāo yě néng zhí jiē qù diào ma 。','Không vấn đề gì, mình ghi chú cho bếp là ít tê ít cay, không ăn hạt tiêu thì bỏ luôn cũng được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_05','V1401','阮明',5,'除了水煮鱼，再来一份不辣的清炒时蔬均衡一下。','chú le shuǐ zhǔ yú ， zài lái yī fèn bù là de qīng chǎo shí shū jūn héng yī xià 。','Ngoài cá om cay, cho thêm một đĩa rau xào không cay nữa để cân bằng lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_06','V1401','小琳',6,'好嘞，主食要米饭还是红糖糍粑，糍粑是甜口不辣的哈。','hǎo lei ， zhǔ shí yào mǐ fàn hái shì hóng táng cí bā ， cí bā shì tián kǒu bù là de hā 。','Được luôn, món chính lấy cơm hay bánh nếp đường đỏ, bánh nếp là vị ngọt không cay đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1401_07','V1401','阮明',7,'一碗米饭就够，麻烦上菜速度快一点啦。','yī wǎn mǐ fàn jiù gòu ， má fán shàng cài sù dù kuài yì diǎn la 。','Một bát cơm là đủ rồi, phiền lên món nhanh giúp mình với nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1402','SATN1','高端中式酒楼提前电话订包厢，咨询最低消费、包厢服务费规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1402','SIT1402','P1','suon_se','ban_chinh_thuc',NULL,'中式酒楼包厢常设最低消费，茶位费、开瓶费是国内餐饮通用附加收费项目。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_01','V1402','阮明',1,'静姐您好，我想订周六六人包厢，想问下有没有最低消费呀？','jìng jiě nín hǎo ， wǒ xiǎng dìng zhōu liù liù rén bāo xiāng ， xiǎng wèn xià yǒu méi yǒu zuì dī xiāo fèi ya ？','Chị Tĩnh ơi, em muốn đặt phòng VIP cho sáu người vào thứ Bảy, cho em hỏi có mức chi tiêu tối thiểu không ạ?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_02','V1402','静姐',2,'小包厢最低消费三百八，不额外收包厢服务费，茶水另算哦。','xiǎo bāo xiāng zuì dī xiāo fèi sān bǎi bā ， bù é wài shōu bāo xiāng fú wù fèi ， chá shuǐ lìng suàn ó 。','Phòng nhỏ mức chi tiêu tối thiểu là ba trăm tám, không tính thêm phí phục vụ phòng đâu, còn trà nước tính riêng nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_03','V1402','阮明',3,'茶水是按人头收取茶位费吗？','chá shuǐ shì àn rén tóu shōu qǔ chá wèi fèi ma ？','Trà nước là tính phí trà theo đầu người đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_04','V1402','静姐',4,'对，每人十元茶位，包含免费续茶、餐前小碟凉菜嘛。','duì ， měi rén shí yuán chá wèi ， bāo hán miǎn fèi xù chá 、 cān qián xiǎo dié liáng cài ma 。','Đúng rồi, mỗi người mười tệ phí trà, bao gồm châm trà miễn phí và món khai vị nguội nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_05','V1402','阮明',5,'如果自带酒水，酒楼会收取开瓶费吗？','rú guǒ zì dài jiǔ shuǐ ， jiǔ lóu huì shōu qǔ kāi píng fèi ma ？','Nếu tự mang rượu vào thì nhà hàng có tính phí mở nắp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_06','V1402','静姐',6,'自带白酒、红酒收取五十元开瓶费，啤酒不用收费哈。','zì dài bái jiǔ 、 hóng jiǔ shōu qǔ wǔ shí yuán kāi píng fèi ， pí jiǔ bù yòng shōu fèi hā 。','Tự mang rượu trắng, rượu vang thì tính năm mươi tệ phí mở nắp, còn bia thì không tính phí đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1402_07','V1402','阮明',7,'清楚所有收费项目，现在预留周六晚上六点的包厢。','qīng chǔ suǒ yǒu shōu fèi xiàng mù ， xiàn zài yù liú zhōu liù wǎn shàng liù diǎn de bāo xiāng 。','Em rõ hết các khoản phí rồi, giờ em đặt giữ phòng lúc sáu giờ tối thứ Bảy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1403','SATN1','使用国内外卖平台点餐，境外手机号无法注册，找同学帮忙代点外卖',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1403','SIT1403','P1','suon_se','tuy_y',NULL,'美团、饿了么等外卖平台实名注册仅支持大陆手机号，外籍留学生大多委托本土同学代下单。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_01','V1403','阮明',1,'浩宇，外卖软件必须大陆手机号注册，你能帮我代点一份家常菜吗？','hào yǔ ， wài mài ruǎn jiàn bì xū dà lù shǒu jī hào zhù cè ， nǐ néng bāng wǒ dài diǎn yī fèn jiā cháng cài ma ？','Hạo Vũ ơi, app đặt đồ ăn bắt buộc phải đăng ký bằng số điện thoại Trung Quốc đại lục, cậu đặt giúp tớ một suất cơm nhà được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_02','V1403','浩宇',2,'没问题，把想吃的店铺、菜品和宿舍地址发给我就行啦。','méi wèn tí ， bǎ xiǎng chī de diàn pù 、 cài pǐn hé sù shè dì zhǐ fā gěi wǒ jiù xíng la 。','Không vấn đề gì, cậu gửi tên quán, món ăn muốn ăn với địa chỉ ký túc xá cho tớ là được.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_03','V1403','阮明',3,'备注少辣少油，配送放宿舍楼下驿站不用打电话。','bèi zhù shǎo là shǎo yóu ， pèi sòng fàng sù shè lóu xià yì zhàn bù yòng dǎ diàn huà 。','Nhớ ghi chú ít cay ít dầu giúp tớ nhé, giao xuống trạm dưới tòa ký túc xá không cần gọi điện đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_04','V1403','浩宇',4,'我直接备注好，外卖超时还能申请商家小额补偿嘛。','wǒ zhí jiē bèi zhù hǎo ， wài mài chāo shí hái néng shēn qǐng shāng jiā xiǎo é bǔ cháng ma 。','Tớ ghi chú luôn cho, đồ ăn giao trễ còn có thể xin quán bồi thường chút tiền nữa đấy.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_05','V1403','阮明',5,'等下单完成，我立刻微信把餐费转给你。','děng xià dān wán chéng ， wǒ lì kè wēi xìn bǎ cān fèi zhuǎn gěi nǐ 。','Đợi đặt xong tớ chuyển tiền ăn cho cậu qua WeChat ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_06','V1403','浩宇',6,'小事而已，下次想吃外卖随时跟我说哈。','xiǎo shì ér yǐ ， xià cì xiǎng chī wài mài suí shí gēn wǒ shuō hā 。','Chuyện nhỏ thôi mà, lần sau muốn ăn gì cứ nói với tớ nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1403_07','V1403','阮明',7,'太感谢，境外号码连点外卖都不方便咯。','tài gǎn xiè ， jìng wài hào mǎ lián diǎn wài mài dōu bù fāng biàn gē 。','Cảm ơn cậu nhiều lắm, số điện thoại nước ngoài đến đặt đồ ăn cũng bất tiện thật.','AM11') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1404','SATN1','寻找清真风味菜馆聚餐，和店主确认菜品不含猪肉、猪油食材',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1404','SIT1404','P1','suon_se','ban_chinh_thuc',NULL,'国内清真餐馆严格规避猪肉及猪油制品，食客可直接向店主确认食材，店家会如实说明。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_01','V1404','阮明',1,'马老板，我们几位同学饮食忌口猪肉，店里所有菜都不含猪油吗？','mǎ lǎo bǎn ， wǒ men jǐ wèi tóng xué yǐn shí jì kǒu zhū ròu ， diàn lǐ suǒ yǒu cài dōu bù hán zhū yóu ma ？','Chú Mã ơi, tụi cháu mấy đứa kiêng ăn thịt heo, quán mình các món có dùng mỡ heo không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_02','V1404','马老板',2,'本店是正宗清真店，全部食材牛羊肉，烹饪只用清油，放心点哦。','běn diàn shì zhèng zōng qīng zhēn diàn ， quán bù shí cái niú yáng ròu ， pēng rèn zhǐ yòng qīng yóu ， fàng xīn diǎn ó 。','Quán này là quán Hồi chính gốc, nguyên liệu toàn là thịt bò thịt cừu, nấu chỉ dùng dầu thực vật thôi, cứ yên tâm gọi món nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_03','V1404','阮明',3,'红烧菜的酱料会不会混入动物油脂，需要单独调整做法吗？','hóng shāo cài de jiàng liào huì bú huì hùn rù dòng wù yóu zhī ， xū yào dān dú tiáo zhěng zuò fǎ ma ？','Nước sốt kho đỏ có bị lẫn mỡ động vật không ạ, có cần điều chỉnh cách chế biến riêng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_04','V1404','马老板',4,'酱料都是植物调配，没有荤油，不用额外修改做法嘛。','jiàng liào dōu shì zhí wù diào pèi ， méi yǒu hūn yóu ， bù yòng é wài xiū gǎi zuò fǎ ma 。','Nước sốt toàn pha từ nguyên liệu thực vật, không có mỡ động vật, không cần chỉnh cách làm gì đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_05','V1404','阮明',5,'那点一份大盘鸡、烤包子和两份素菜，六个人够吃吗？','nà diǎn yī fèn dà pán jī 、 kǎo bāo zi hé liǎng fèn sù cài ， liù gè rén gòu chī ma ？','Vậy cho cháu gọi một phần đại bàn kê, bánh nướng kẹp và hai phần rau xào, sáu người ăn đủ không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_06','V1404','马老板',6,'再加一碗手擀面，分量刚好，不会不够也不浪费哈。','zài jiā yī wǎn shǒu gǎn miàn ， fèn liàng gāng hǎo ， bú huì bù gòu yě bù làng fèi hā 。','Gọi thêm một tô mì tự cán nữa là vừa đủ, không thiếu mà cũng không thừa đâu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1404_07','V1404','阮明',7,'好，那就按这个菜单下单，辛苦老板了。','hǎo ， nà jiù àn zhè ge cài dān xià dān ， xīn kǔ lǎo bǎn le 。','Vâng, vậy cứ theo thực đơn này mà đặt cho cháu, cảm ơn chú nhiều ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1405','SATN1','探访本地老字号淮扬菜馆，看不懂古风纸质菜单，请店员讲解招牌名菜',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1405','SIT1405','P1','twist','tuy_y',NULL,'老字号中式菜馆多使用传统雅致菜名，无配图，不熟悉中餐的游客需要店员通俗讲解菜品内容。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_01','V1405','阮明',1,'小哥，菜单上很多古风菜名我看不懂，能推荐两道淮扬招牌吗？','xiǎo gē ， cài dān shàng hěn duō gǔ fēng cài míng wǒ kàn bù dǒng ， néng tuī jiàn liǎng dào huái yáng zhāo pái ma ？','Anh ơi, thực đơn có nhiều tên món kiểu cổ em không hiểu, anh gợi ý giúp em hai món đặc sản Hoài Dương được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_02','V1405','阿泽',2,'狮子头、文思豆腐是本店必点，都是清淡不辣的经典菜品呢。','shī zi tóu 、 wén sī dòu fǔ shì běn diàn bì diǎn ， dōu shì qīng dàn bù là de jīng diǎn cài pǐn ne 。','Sư tử đầu với đậu hũ Văn Tư là hai món phải gọi của quán, đều là món kinh điển thanh đạm không cay đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_03','V1405','阮明',3,'狮子头是肥肉多还是瘦肉多，会不会很油腻呀？','shī zi tóu shì féi ròu duō hái shì shòu ròu duō ， huì bú huì hěn yóu nì ya ？','Sư tử đầu là mỡ nhiều hay nạc nhiều vậy, có bị ngấy lắm không anh?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_04','V1405','阿泽',4,'肥瘦三七配比，炖得软烂，搭配青菜吃完全不腻嘛。','féi shòu sān qī pèi bǐ ， dùn dé ruǎn làn ， dā pèi qīng cài chī wán quán bù nì ma 。','Tỷ lệ mỡ nạc ba bảy thôi, hầm mềm nhừ, ăn kèm rau xanh là không thấy ngấy tí nào đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_05','V1405','阮明',5,'文思豆腐切得特别细，吃起来是什么口感？','wén sī dòu fǔ qiè dé tè bié xì ， chī qǐ lái shì shén me kǒu gǎn ？','Đậu hũ Văn Tư thái sợi mảnh vậy, ăn vào có vị thế nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_06','V1405','阿泽',6,'豆腐丝入口即化，汤汁鲜，很适合口味清淡的客人哈。','dòu fǔ sī rù kǒu jí huà ， tāng zhī xiān ， hěn shì hé kǒu wèi qīng dàn de kè rén hā 。','Sợi đậu hũ tan ngay trong miệng, nước dùng ngọt thanh, rất hợp với khách khẩu vị nhẹ đấy.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1405_07','V1405','阮明',7,'那就这两道，再加一碗米饭尝尝本地口味。','nà jiù zhè liǎng dào ， zài jiā yī wǎn mǐ fàn cháng cháng běn dì kǒu wèi 。','Vậy cho em hai món này, thêm một bát cơm để nếm thử hương vị địa phương nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1406','SATN1','组队留学生聚餐，主动做东请客，和同行同学商量点菜数量与预算',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1406','SIT1406','P1','suon_se','tuy_y',NULL,'国内请客吃饭讲究荤素冷热搭配，点单数量一般比人数多一到两道，避免菜品不够显得失礼。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_01','V1406','阮明',1,'今天我请客，咱们四个人点菜控制在三百以内，够吃就行别浪费啦。','jīn tiān wǒ qǐng kè ， zán men sì gè rén diǎn cài kòng zhì zài sān bǎi yǐ nèi ， gòu chī jiù xíng bié làng fèi la 。','Hôm nay tớ mời, bốn đứa mình gọi món trong khoảng ba trăm thôi, đủ ăn là được đừng phí phạm nhé.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_02','V1406','阿凯',2,'你做东不用太节省，四菜一汤搭配荤素，差不多刚好两百多。','nǐ zuò dōng bù yòng tài jié shěng ， sì cài yī tāng dā pèi hūn sù ， chà bu duō gāng hǎo liǎng bǎi duō 。','Cậu làm chủ chi không cần tiết kiệm quá đâu, bốn món một canh có mặn có rau là khoảng hơn hai trăm thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_03','V1406','阮明',3,'那两道肉菜两道素菜，再加一份甜品均衡口味可以吗？','nà liǎng dào ròu cài liǎng dào sù cài ， zài jiā yī fèn tián pǐn jūn héng kǒu wèi kě yǐ ma ？','Vậy hai món mặn hai món rau, thêm một phần tráng miệng cho cân bằng khẩu vị được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_04','V1406','阿凯',4,'这个搭配很合适，冷热菜分开，吃着不会腻嘛。','zhè ge dā pèi hěn hé shì ， lěng rè cài fēn kāi ， chī zhe bú huì nì ma 。','Kết hợp vậy hợp lý đấy, món nóng món lạnh tách riêng ra, ăn sẽ không bị ngấy đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_05','V1406','阮明',5,'有没有大家都爱吃的本地菜，优先点大家熟悉的口味。','yǒu méi yǒu dà jiā dōu ài chī de běn dì cài ， yōu xiān diǎn dà jiā shú xī de kǒu wèi 。','Có món địa phương nào ai cũng thích ăn không, ưu tiên gọi món quen thuộc với mọi người nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_06','V1406','阿凯',6,'大家都爱吃糖醋里脊，直接放进菜单里哈。','dà jiā dōu ài chī táng cù lǐ jí ， zhí jiē fàng jìn cài dān lǐ hā 。','Ai cũng thích ăn sườn chua ngọt đấy, cứ cho luôn vào danh sách gọi món đi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1406_07','V1406','阮明',7,'行，我现在喊服务员过来下单。','xíng ， wǒ xiàn zài hǎn fú wù yuán guò lái xià dān 。','Được, giờ tớ gọi phục vụ qua để đặt món luôn đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1407','SATN1','粤式早茶酒楼自助点茶，分不清点心蒸笼大小份、茶位费收费规则',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1407','SIT1407','P1','twist','ban_chinh_thuc',NULL,'粤式早茶固定收取人头茶位费，蒸笼点心分大小份，多人就餐多选小份方便多尝几种口味。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_01','V1407','阮明',1,'你好，点心分大笼小笼，四人用餐选哪种分量合适呢？','nǐ hǎo ， diǎn xīn fēn dà lóng xiǎo lóng ， sì rén yòng cān xuǎn nǎ zhǒng fèn liàng hé shì ne ？','Chào chị, điểm tâm có lồng lớn lồng nhỏ, bốn người ăn thì chọn phần nào cho hợp ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_02','V1407','阿芳',2,'小笼三四只，大笼六只，四个人每种点心选小笼就够分哦。','xiǎo lóng sān sì zhǐ ， dà lóng liù zhǐ ， sì gè rén měi zhǒng diǎn xīn xuǎn xiǎo lóng jiù gòu fēn ó 。','Lồng nhỏ có ba bốn cái, lồng lớn có sáu cái, bốn người thì mỗi món chọn lồng nhỏ là đủ chia rồi đấy.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_03','V1407','阮明',3,'进门收的茶位费，是按人头一次性收取吗？','jìn mén shōu de chá wèi fèi ， shì àn rén tóu yí cì xìng shōu qǔ ma ？','Phí trà thu lúc vào cửa là tính một lần theo đầu người đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_04','V1407','阿芳',4,'没错，一人八元，不限续茶水，餐前小食也免费提供嘛。','méi cuò ， yī rén bā yuán ， bù xiàn xù chá shuǐ ， cān qián xiǎo shí yě miǎn fèi tí gōng ma 。','Đúng vậy, mỗi người tám tệ, châm trà thoải mái không giới hạn, món khai vị cũng miễn phí luôn nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_05','V1407','阮明',5,'点心现蒸需要等很久，还是几分钟就能上桌？','diǎn xīn xiàn zhēng xū yào děng hěn jiǔ ， hái shì jǐ fēn zhōng jiù néng shàng zhuō ？','Điểm tâm hấp tại chỗ có phải đợi lâu không, hay vài phút là lên bàn được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_06','V1407','阿芳',6,'现蒸十到十五分钟，着急可以先选蒸好的点心哈。','xiàn zhēng shí dào shí wǔ fēn zhōng ， zháo jí kě yǐ xiān xuǎn zhēng hǎo de diǎn xīn hā 。','Hấp mới mất mười đến mười lăm phút, nếu gấp thì có thể chọn trước món đã hấp sẵn nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1407_07','V1407','阮明',7,'懂了，每种点心各点一笼小笼慢慢品尝。','dǒng le ， měi zhǒng diǎn xīn gè diǎn yī lóng xiǎo lóng màn màn pǐn cháng 。','Em hiểu rồi, mỗi loại điểm tâm gọi một lồng nhỏ để từ từ thưởng thức.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1408','SATN1','点特色地方臭美食螺蛳粉，同桌朋友接受不了气味产生小分歧',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1408','SIT1408','P1','twist','tuy_y',NULL,'螺蛳粉、臭豆腐这类气味浓烈食物，很多餐厅区分堂食区域，顾及其他食客体验，多人聚餐可选择打包食用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_01','V1408','阮明',1,'这家螺蛳粉评价很高，我想点一份试试本地特色可以吗？','zhè jiā luó sī fěn píng jià hěn gāo ， wǒ xiǎng diǎn yī fèn shì shì běn dì tè sè kě yǐ ma ？','Quán ốc lê phấn này đánh giá cao lắm, tớ muốn gọi một suất thử đặc sản địa phương được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_02','V1408','子轩',2,'我闻不了酸笋的味道，整个包厢都会飘臭味，实在接受不了。','wǒ wén bù liǎo suān sǔn de wèi dào ， zhěng gè bāo xiāng dōu huì piāo chòu wèi ， shí zài jiē shòu bù liǎo 。','Tớ ngửi không nổi mùi măng chua đâu, cả phòng sẽ bị ám mùi hôi mất, thật sự không chịu nổi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_03','V1408','阮明',3,'那我单独打包一份，到外面走廊吃，不影响包厢里的你行吗？','nà wǒ dān dú dǎ bāo yī fèn ， dào wài miàn zǒu láng chī ， bù yǐng xiǎng bāo xiāng lǐ de nǐ xíng ma ？','Vậy để tớ gói riêng một phần, ra ngoài hành lang ăn, không ảnh hưởng đến cậu trong phòng, được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_04','V1408','子轩',4,'这样最好，等下咱们再点几份无异味小炒一起在包厢吃。','zhè yàng zuì hǎo ， děng xià zán men zài diǎn jǐ fèn wú yì wèi xiǎo chǎo yì qǐ zài bāo xiāng chī 。','Vậy là tốt nhất rồi, lát nữa mình gọi thêm mấy món xào không mùi ăn chung trong phòng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_05','V1408','阮明',5,'没问题，我分开打包，不会让气味熏到大家嘛。','méi wèn tí ， wǒ fēn kāi dǎ bāo ， bú huì ràng qì wèi xūn dào dà jiā ma 。','Không vấn đề gì, tớ gói riêng ra, sẽ không để mùi ảnh hưởng đến mọi người đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_06','V1408','子轩',6,'多谢体谅，等下我请你喝奶茶补偿一下哈。','duō xiè tǐ liàng ， děng xià wǒ qǐng nǐ hē nǎi chá bǔ cháng yī xià hā 。','Cảm ơn cậu đã thông cảm nhé, lát nữa tớ mời cậu ly trà sữa để đền bù nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1408_07','V1408','阮明',7,'小事，主要是不想让大家用餐不舒服。','xiǎo shì ， zhǔ yào shì bù xiǎng ràng dà jiā yòng cān bù shū fú 。','Chuyện nhỏ mà, chủ yếu là không muốn để mọi người ăn uống khó chịu thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1409','SATN1','素食全素餐厅用餐，询问店员菜品是否含有葱蒜、蛋奶这类素食禁忌食材',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1409','SIT1409','P1','suon_se','ban_chinh_thuc',NULL,'中式纯素餐饮分净素、蛋奶素，食客可提前告知店家剔除五辛（葱蒜韭菜等），店家会单独调整烹饪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_01','V1409','阮明',1,'芳姐，纯素菜品能不放葱蒜、鸡蛋吗，我饮食避开这类食材。','fāng jiě ， chún sù cài pǐn néng bù fàng cōng suàn 、 jī dàn ma ， wǒ yǐn shí bì kāi zhè lèi shí cái 。','Chị Phương ơi, món chay thuần có thể không cho hành tỏi, trứng gà được không ạ, em kiêng mấy loại nguyên liệu này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_02','V1409','芳姐',2,'没问题，本店全素无蛋奶，葱姜蒜也可以完全剔除不加哦。','méi wèn tí ， běn diàn quán sù wú dàn nǎi ， cōng jiāng suàn yě kě yǐ wán quán tī chú bù jiā ó 。','Không vấn đề gì, quán chị hoàn toàn chay không trứng sữa, hành gừng tỏi cũng có thể bỏ hết ra không cho vào nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_03','V1409','阮明',3,'仿肉菜品是豆制品做的，没有动物成分对吧？','fǎng ròu cài pǐn shì dòu zhì pǐn zuò de ， méi yǒu dòng wù chéng fèn duì ba ？','Món giả mặn là làm từ đậu, không có thành phần động vật đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_04','V1409','芳姐',4,'全部大豆、菌菇制作，口感像肉，本质都是素食食材嘛。','quán bù dà dòu 、 jūn gū zhì zuò ， kǒu gǎn xiàng ròu ， běn zhì dōu shì sù shí shí cái ma 。','Toàn làm từ đậu nành, nấm các loại, ăn có vị như thịt nhưng bản chất vẫn là nguyên liệu chay hết nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_05','V1409','阮明',5,'那点两道仿荤素菜，再加一份清炒时蔬。','nà diǎn liǎng dào fǎng hūn sù cài ， zài jiā yī fèn qīng chǎo shí shū 。','Vậy cho em gọi hai món chay giả mặn, thêm một phần rau xào tươi nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_06','V1409','芳姐',6,'马上给后厨备注无葱蒜，十分钟就能上菜哈。','mǎ shàng gěi hòu chú bèi zhù wú cōng suàn ， shí fēn zhōng jiù néng shàng cài hā 。','Chị ghi chú ngay cho bếp là không cho hành tỏi, mười phút là có món lên nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1409_07','V1409','阮明',7,'太贴心，终于找到适配我饮食习惯的餐馆。','tài tiē xīn ， zhōng yú zhǎo dào shì pèi wǒ yǐn shí xí guàn de cān guǎn 。','Chu đáo quá, cuối cùng cũng tìm được quán hợp với thói quen ăn uống của em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1410','SATN1','线上团购餐厅双人套餐，到店核销时发现团购仅限工作日，周末不可用',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1410','SIT1410','P1','that_bai_nhe','ban_chinh_thuc',NULL,'餐饮团购普遍设置工作日、节假日使用限制，下单前需看清规则，节假日大多无法使用低价套餐。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_01','V1410','阮明',1,'你好，我线上团购双人套餐，今天周六能直接核销使用吗？','nǐ hǎo ， wǒ xiàn shàng tuán gòu shuāng rén tào cān ， jīn tiān zhōu liù néng zhí jiē hé xiāo shǐ yòng ma ？','Chào chị, em đặt combo cặp đôi qua nhóm mua online, hôm nay thứ Bảy có dùng trực tiếp được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_02','V1410','小雯',2,'团购页面标注仅限周一至周五工作日，周末无法兑换套餐哦。','tuán gòu yè miàn biāo zhù jǐn xiàn zhōu yī zhì zhōu wǔ gōng zuò rì ， zhōu mò wú fǎ duì huàn tào cān ó 。','Trang nhóm mua ghi rõ chỉ áp dụng từ thứ Hai đến thứ Sáu thôi ạ, cuối tuần không đổi được combo đâu.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_03','V1410','阮明',3,'我下单时没仔细看使用时间，现在有别的解决办法吗？','wǒ xià dān shí méi zǐ xì kàn shǐ yòng shí jiān ， xiàn zài yǒu bié de jiě jué bàn fǎ ma ？','Lúc đặt em không để ý kỹ thời gian sử dụng, giờ có cách nào khác không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_04','V1410','小雯',4,'套餐可申请全额退款，或者按原价单点店内菜品就餐。','tào cān kě shēn qǐng quán é tuì kuǎn ， huò zhě àn yuán jià dān diǎn diàn nèi cài pǐn jiù cān 。','Combo có thể xin hoàn tiền toàn bộ, hoặc gọi món lẻ theo giá gốc trong nhà hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_05','V1410','阮明',5,'退款多久能到支付账户，会不会扣除手续费？','tuì kuǎn duō jiǔ néng dào zhī fù zhàng hù ， huì bú huì kòu chú shǒu xù fèi ？','Vậy hoàn tiền bao lâu thì vào tài khoản thanh toán, có bị trừ phí gì không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_06','V1410','小雯',6,'退款实时到账，无任何扣费，现在就能操作嘛。','tuì kuǎn shí shí dào zhàng ， wú rèn hé kòu fèi ， xiàn zài jiù néng cāo zuò ma 。','Hoàn tiền là về ngay lập tức, không bị trừ phí gì cả, giờ làm luôn cũng được.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1410_07','V1410','阮明',7,'那我申请退款，直接单点菜品吃饭好了。','nà wǒ shēn qǐng tuì kuǎn ， zhí jiē dān diǎn cài pǐn chī fàn hǎo le 。','Vậy em xin hoàn tiền, rồi gọi món lẻ ăn luôn cho tiện.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1411','SATN1','去农家土菜馆体验本地农家菜，不清楚菜量大小，咨询老板娘避免点多浪费',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1411','SIT1411','P1','suon_se','tuy_y',NULL,'乡村农家乐菜品分量远大于市区餐馆，点菜前咨询店家可避免过量点餐，节约食材符合国内节约粮食理念。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_01','V1411','阮明',1,'桂婶，我们两个人吃饭，点三道菜会不会分量太多吃不完？','guì shěn ， wǒ men liǎng gè rén chī fàn ， diǎn sān dào cài huì bú huì fèn liàng tài duō chī bù wán ？','Thím Quế ơi, tụi con hai người thôi mà gọi ba món thì có nhiều quá ăn không hết không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_02','V1411','桂婶',2,'农家菜盘子超大，两个人两菜一汤刚好，三道容易浪费粮食呢。','nóng jiā cài pán zi chāo dà ， liǎng gè rén liǎng cài yī tāng gāng hǎo ， sān dào róng yì làng fèi liáng shí ne 。','Món nhà quê đĩa to lắm, hai người ăn hai món một canh là vừa đủ rồi, gọi ba món dễ phí đồ ăn lắm đấy.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_03','V1411','阮明',3,'土鸡锅分量很大吗，一份够两人吃饱？','tǔ jī guō fèn liàng hěn dà ma ， yī fèn gòu liǎng rén chī bǎo ？','Nồi gà thả vườn phần có nhiều không thím, một phần hai người ăn no được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_04','V1411','桂婶',4,'土鸡锅搭配米饭刚好，不用再加其他荤菜嘛。','tǔ jī guō dā pèi mǐ fàn gāng hǎo ， bù yòng zài jiā qí tā hūn cài ma 。','Nồi gà ăn kèm cơm là vừa đủ rồi, không cần gọi thêm món mặn khác đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_05','V1411','阮明',5,'那就土鸡锅加一盘青菜，一碗例汤就行。','nà jiù tǔ jī guō jiā yī pán qīng cài ， yī wǎn lì tāng jiù xíng 。','Vậy con gọi nồi gà, thêm một đĩa rau xanh với một bát canh suông là được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_06','V1411','桂婶',6,'好嘞，食材都是自家菜园种的，新鲜实惠哈。','hǎo lei ， shí cái dōu shì zì jiā cài yuán zhǒng de ， xīn xiān shí huì hā 。','Được rồi con, nguyên liệu toàn là rau vườn nhà trồng, tươi mà lại rẻ nữa.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1411_07','V1411','阮明',7,'还好提前问您，不然点一堆菜白白浪费。','hái hǎo tí qián wèn nín ， bù rán diǎn yī duī cài bái bái làng fèi 。','May mà hỏi thím trước, không thì gọi cả đống món rồi lại lãng phí thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1412','SATN1','商务中式简餐宴请导师，请教本土同学中式餐桌入座、敬酒基础礼仪',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1412','SIT1412','P1','suon_se','ban_chinh_thuc',NULL,'中式宴请讲究主客座位尊卑、敬酒杯沿高低，晚辈主动照顾长辈是传统餐桌礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_01','V1412','阮明',1,'峰学长，今晚我请导师吃饭，中式餐桌入座顺序有讲究吗？','fēng xué zhǎng ， jīn wǎn wǒ qǐng dǎo shī chī fàn ， zhōng shì cān zhuō rù zuò shùn xù yǒu jiǎng jiū ma ？','Anh Phong ơi, tối nay em mời thầy hướng dẫn ăn cơm, chỗ ngồi ở bàn ăn kiểu Trung Quốc có gì cần chú ý không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_02','V1412','林峰',2,'正对大门的主位留给老师，你坐在靠近门口方便叫服务员的位置。','zhèng duì dà mén de zhǔ wèi liú gěi lǎo shī ， nǐ zuò zài kào jìn mén kǒu fāng biàn jiào fú wù yuán de wèi zhì 。','Vị trí chính đối diện cửa ra vào để dành cho thầy, em ngồi gần cửa để tiện gọi nhân viên phục vụ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_03','V1412','阮明',3,'倒茶敬酒的时候，杯子高低有什么规矩呢？','dào chá jìng jiǔ de shí hòu ， bēi zi gāo dī yǒu shén me guī jǔ ne ？','Lúc rót trà mời rượu, chuyện cầm ly cao thấp có quy tắc gì không anh?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_04','V1412','林峰',4,'你的杯沿低于老师的杯子，表示尊重，敬酒只浅抿一口不用喝完嘛。','nǐ de bēi yán dī yú lǎo shī de bēi zi ， biǎo shì zūn zhòng ， jìng jiǔ zhǐ qiǎn mǐn yī kǒu bù yòng hē wán ma 。','Miệng ly của em phải thấp hơn ly của thầy, thể hiện sự tôn trọng, còn khi mời rượu chỉ cần nhấp một ngụm nhỏ thôi, không cần uống hết đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_05','V1412','阮明',5,'点菜要优先点老师爱吃的清淡菜品，少点辛辣重油对不对？','diǎn cài yào yōu xiān diǎn lǎo shī ài chī de qīng dàn cài pǐn ， shǎo diǎn xīn là zhòng yóu duì bú duì ？','Gọi món thì nên ưu tiên món thanh đạm thầy thích ăn, hạn chế món cay và nhiều dầu mỡ đúng không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_06','V1412','林峰',6,'没错，兼顾长辈口味，冷热荤素均衡搭配最合适哈。','méi cuò ， jiān gù zhǎng bèi kǒu wèi ， lěng rè hūn sù jūn héng dā pèi zuì hé shì hā 。','Đúng rồi, phải để ý khẩu vị của người lớn tuổi, kết hợp cân bằng giữa món nóng lạnh, mặn chay là hợp lý nhất.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1412_07','V1412','阮明',7,'记住这些礼仪，今晚宴请不会失礼了。','jì zhù zhè xiē lǐ yí ， jīn wǎn yàn qǐng bú huì shī lǐ le 。','Nhớ hết mấy điều này rồi, tối nay mời cơm chắc không sợ thất lễ nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1413','SATN1','海鲜大排档挑选鲜活水产，分不清时价称重计价，担心缺斤少两询问老板',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1413','SIT1413','P1','twist','tuy_y',NULL,'海鲜大排档鲜活水产实时时价，行业默认沥干水分称重，游客可全程监督称重避免虚重。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_01','V1413','阮明',1,'老板，皮皮虾是按当天市价称重，价格写在门口黑板上吗？','lǎo bǎn ， pí pí xiā shì àn dàng tiān shì jià chēng zhòng ， jià gé xiě zài mén kǒu hēi bǎn shàng ma ？','Chú ơi, con tôm tít này tính theo giá thị trường hàng ngày, giá ghi trên bảng đen ở cửa đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_02','V1413','老杨',2,'对，每日海鲜时价更新，称重前会把筐里的水沥干再称哦。','duì ， měi rì hǎi xiān shí jià gēng xīn ， chēng zhòng qián huì bǎ kuāng lǐ de shuǐ lì gàn zài chēng ó 。','Đúng vậy, giá hải sản mỗi ngày mỗi cập nhật, trước khi cân sẽ để ráo nước trong rổ rồi mới cân nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_03','V1413','阮明',3,'称重能让我看着吗，担心带水分多算重量。','chēng zhòng néng ràng wǒ kàn zhe ma ， dān xīn dài shuǐ fèn duō suàn zhòng liàng 。','Lúc cân chú cho con xem được không, con sợ nước còn đọng lại làm tăng cân nặng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_04','V1413','老杨',4,'完全可以，每一份海鲜当着客人面称重，不会缺斤少两嘛。','wán quán kě yǐ ， měi yī fèn hǎi xiān dāng zhe kè rén miàn chēng zhòng ， bú huì quē jīn shǎo liǎng ma 。','Được chứ, mỗi phần hải sản đều cân ngay trước mặt khách, không có chuyện thiếu cân đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_05','V1413','阮明',5,'加工费另外算，清蒸和爆炒收费一样吗？','jiā gōng fèi lìng wài suàn ， qīng zhēng hé bào chǎo shōu fèi yī yàng ma ？','Phí chế biến tính riêng, hấp và xào cay giá có giống nhau không chú?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_06','V1413','老杨',6,'清蒸加工最便宜，香辣爆炒会多收十块加工费哈。','qīng zhēng jiā gōng zuì pián yi ， xiāng là bào chǎo huì duō shōu shí kuài jiā gōng fèi hā 。','Hấp là rẻ nhất, còn xào cay thì tính thêm mười tệ phí chế biến đấy.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1413_07','V1413','阮明',7,'那选一斤皮皮虾清蒸，少放辣椒。','nà xuǎn yī jīn pí pí xiā qīng zhēng ， shǎo fàng là jiāo 。','Vậy con lấy một cân tôm tít hấp, cho ít ớt thôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1414','SATN1','外卖送达餐品撒漏、变凉，联系商家客服协商补发、退款补偿',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1414','SIT1414','P1','suon_se','ban_chinh_thuc',NULL,'国内外卖商家对撒漏、变质餐品售后包容，支持全额退款或免费重送，常额外发放优惠券补偿顾客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_01','V1414','阮明',1,'你好，外卖汤品全部撒漏，饭菜已经凉透没法食用，拍图发给您了。','nǐ hǎo ， wài mài tāng pǐn quán bù sā lòu ， fàn cài yǐ jīng liáng tòu méi fǎ shí yòng ， pāi tú fā gěi nín le 。','Chào chị, phần canh trong đơn giao hàng bị đổ hết, đồ ăn cũng nguội lạnh không dùng được nữa, em chụp ảnh gửi chị rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_02','V1414','客服',2,'实在抱歉，配送途中颠簸导致漏汤，给你两种处理方案任选哦。','shí zài bào qiàn ， pèi sòng tú zhōng diān bǒ dǎo zhì lòu tāng ， gěi nǐ liǎng zhǒng chǔ lǐ fāng àn rèn xuǎn ó 。','Thành thật xin lỗi bạn, do lúc vận chuyển xóc quá nên canh bị đổ, bên mình có hai phương án xử lý, bạn chọn nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_03','V1414','阮明',3,'方案一是全额退款，二是重新配送一份新餐对吗？','fāng àn yī shì quán é tuì kuǎn ， èr shì chóng xīn pèi sòng yī fèn xīn cān duì ma ？','Phương án một là hoàn tiền toàn bộ, phương án hai là giao lại một phần đồ ăn mới, đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_04','V1414','客服',4,'没错，重新配送半小时送到，退款立刻原路返还，还附赠五元无门槛券嘛。','méi cuò ， chóng xīn pèi sòng bàn xiǎo shí sòng dào ， tuì kuǎn lì kè yuán lù fǎn huán ， hái fù zèng wǔ yuán wú mén kǎn quàn ma 。','Đúng vậy, giao lại thì nửa tiếng là tới nơi, còn hoàn tiền thì về ngay theo đường thanh toán cũ, kèm thêm voucher năm tệ không điều kiện luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_05','V1414','阮明',5,'我等下还有课，直接全额退款加上优惠券吧。','wǒ děng xià hái yǒu kè ， zhí jiē quán é tuì kuǎn jiā shàng yōu huì quàn ba 。','Em lát nữa còn phải đi học nên hoàn tiền toàn bộ với voucher luôn giúp em nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_06','V1414','客服',6,'好，现在登记退款，优惠券五分钟自动发放到账户哈。','hǎo ， xiàn zài dēng jì tuì kuǎn ， yōu huì quàn wǔ fēn zhōng zì dòng fā fàng dào zhàng hù hā 。','Được rồi, bây giờ đăng ký hoàn tiền cho bạn, voucher trong năm phút sẽ tự động vào tài khoản nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1414_07','V1414','阮明',7,'多谢快速处理，下次还会光顾本店。','duō xiè kuài sù chǔ lǐ ， xià cì hái huì guāng gù běn diàn 。','Cảm ơn chị xử lý nhanh, lần sau em sẽ ủng hộ quán tiếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1415','SATN1','北方饺子馆点手工水饺，分不清荤素馅料，询问店员每种馅料食材构成',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1415','SIT1415','P1','suon_se','tuy_y',NULL,'北方水饺荤素馅料区分清晰，店家会直白说明食材，忌口肉类、海鲜的食客可直接挑选素馅。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_01','V1415','阮明',1,'小丽，饺子猪肉白菜、韭菜鸡蛋两种馅料，食材分别是什么呀？','xiǎo lì ， jiǎo zi zhū ròu bái cài 、 jiǔ cài jī dàn liǎng zhǒng xiàn liào ， shí cái fēn bié shì shén me ya ？','Lệ ơi, sủi cảo nhân thịt heo cải thảo với nhân hẹ trứng, hai loại này nguyên liệu là gì vậy?','AM01') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_02','V1415','小丽',2,'猪肉白菜是鲜肉搭配白菜，韭菜鸡蛋全素，不吃肉可以选这款哦。','zhū ròu bái cài shì xiān ròu dā pèi bái cài ， jiǔ cài jī dàn quán sù ， bù chī ròu kě yǐ xuǎn zhè kuǎn ó 。','Nhân thịt heo cải thảo là thịt tươi kết hợp với cải thảo, còn nhân hẹ trứng là chay hoàn toàn, không ăn thịt thì chọn loại này nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_03','V1415','阮明',3,'素饺子里面有没有放虾皮、猪油调味呢？','sù jiǎo zi lǐ miàn yǒu méi yǒu fàng xiā pí 、 zhū yóu tiáo wèi ne ？','Sủi cảo chay có cho tôm khô hay mỡ heo để nêm nếm không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_04','V1415','小丽',4,'纯素韭菜鸡蛋只放青菜鸡蛋，没有任何肉类辅料嘛。','chún sù jiǔ cài jī dàn zhǐ fàng qīng cài jī dàn ， méi yǒu rèn hé ròu lèi fǔ liào ma 。','Nhân hẹ trứng thuần chay chỉ cho rau và trứng thôi, không có bất kỳ nguyên liệu thịt nào cả.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_05','V1415','阮明',5,'二十个饺子一人份，我一份素饺子配醋碟。','èr shí gè jiǎo zi yī rén fèn ， wǒ yī fèn sù jiǎo zi pèi cù dié 。','Hai mươi cái sủi cảo là một phần cho một người, cho mình một phần sủi cảo chay kèm chén giấm nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_06','V1415','小丽',6,'好嘞，现包现煮，十分钟就能端上桌哈。','hǎo lei ， xiàn bāo xiàn zhǔ ， shí fēn zhōng jiù néng duān shàng zhuō hā 。','Được rồi bạn, gói xong nấu ngay, mười phút là bưng ra bàn liền.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1415_07','V1415','阮明',7,'谢谢讲解，第一次吃北方水饺怕选错馅料。','xiè xiè jiǎng jiě ， dì yī cì chī běi fāng shuǐ jiǎo pà xuǎn cuò xiàn liào 。','Cảm ơn bạn giải thích nhé, lần đầu ăn sủi cảo miền Bắc mình sợ chọn nhầm nhân lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1416','SATN1','多人聚餐轮流买单，国内同学坚持AA制，讲解国内年轻人聚餐付款习惯',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1416','SIT1416','P1','twist','tuy_y',NULL,'当代国内青年朋友日常聚餐普遍AA制，仅节日、生日等特殊场合才会有人主动做东请客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_01','V1416','阮明',1,'这顿饭我来结账，上次聚餐都是你们买单，这次我请客吧。','zhè dùn fàn wǒ lái jié zhàng ， shàng cì jù cān dōu shì nǐ men mǎi dān ， zhè cì wǒ qǐng kè ba 。','Bữa này để tớ trả nhé, lần trước tụ tập toàn các cậu trả tiền rồi, lần này tớ mời.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_02','V1416','晓雨',2,'不用单独请客，我们年轻人聚餐大多AA，分摊更公平不用互相亏欠。','bù yòng dān dú qǐng kè ， wǒ men nián qīng rén jù cān dà duō AA， fēn tān gèng gōng píng bù yòng hù xiāng kuī qiàn 。','Không cần mời riêng đâu, tụi mình trẻ tuổi ăn uống với nhau đa số là chia đều, chia ra thì công bằng hơn, khỏi ai nợ ai.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_03','V1416','阮明',3,'国内朋友之间，不流行轮流做东请客吃饭吗？','guó nèi péng yǒu zhī jiān ， bù liú xíng lún liú zuò dōng qǐng kè chī fàn ma ？','Giữa bạn bè trong nước, không thịnh hành thay phiên nhau mời cơm à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_04','V1416','晓雨',4,'关系很好的好友偶尔请客，日常聚餐一律AA，大家都没有负担嘛。','guān xì hěn hǎo de hǎo yǒu ǒu ěr qǐng kè ， rì cháng jù cān yī lǜ AA， dà jiā dōu méi yǒu fù dān ma 。','Bạn bè thân thiết thì thỉnh thoảng mời nhau, còn tụ tập ngày thường thì đều chia đều hết, ai cũng không thấy áp lực gì cả.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_05','V1416','阮明',5,'那吃完饭我把我的那份钱微信转给你。','nà chī wán fàn wǒ bǎ wǒ de nà fèn qián wēi xìn zhuǎn gěi nǐ 。','Vậy ăn xong tớ chuyển khoản phần tiền của mình cho cậu qua WeChat nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_06','V1416','晓雨',6,'我等下发账单明细，每个人平分总额就行哈。','wǒ děng xià fā zhàng dān míng xì ， měi gè rén píng fēn zǒng é jiù xíng hā 。','Lát nữa tớ gửi chi tiết hóa đơn, mỗi người chia đều tổng số tiền là được rồi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1416_07','V1416','阮明',7,'原来年轻人流行AA，和我家乡聚餐习惯不太一样。','yuán lái nián qīng rén liú xíng AA， hé wǒ jiā xiāng jù cān xí guàn bù tài yī yàng 。','Hóa ra giới trẻ ở đây quen chia đều, khác với thói quen tụ tập ở quê mình ghê.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1417','SATN1','云南风味野生菌火锅店用餐，店员提醒菌类必须完全煮熟，不可生食',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1417','SIT1417','P1','twist','ban_chinh_thuc',NULL,'云南野生食用菌存在天然毒素，当地餐饮强制要求长时间烹煮，店家有义务提醒食客禁止生食。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_01','V1417','阮明',1,'阿明，野生菌下锅煮多久才能吃，看起来很快就熟了呢？','ā míng ， yě shēng jūn xià guō zhǔ duō jiǔ cái néng chī ， kàn qǐ lái hěn kuài jiù shú le ne ？','Minh ơi, nấm rừng nấu bao lâu mới ăn được, nhìn thấy chín nhanh vậy đó?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_02','V1417','阿明',2,'所有野生菌必须煮满二十分钟，半生食用容易中毒，千万不能提前夹哦。','suǒ yǒu yě shēng jūn bì xū zhǔ mǎn èr shí fēn zhōng ， bàn shēng shí yòng róng yì zhòng dú ， qiān wàn bù néng tí qián jiā ó 。','Tất cả nấm rừng phải nấu đủ hai mươi phút, ăn tái dễ bị ngộ độc lắm, tuyệt đối không được gắp trước đâu nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_03','V1417','阮明',3,'要是提前捞出误食，会出现什么不适症状？','yào shì tí qián lāo chū wù shí ， huì chū xiàn shén me bù shì zhèng zhuàng ？','Nếu lỡ gắp ra ăn sớm quá thì sẽ có triệu chứng khó chịu gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_04','V1417','阿明',4,'会头晕恶心产生幻觉，本店全程定时提醒，还会把控下锅时间嘛。','huì tóu yūn ě xīn chǎn shēng huàn jué ， běn diàn quán chéng dìng shí tí xǐng ， hái huì bǎ kòng xià guō shí jiān ma 。','Sẽ bị chóng mặt buồn nôn, thậm chí ảo giác, quán mình sẽ nhắc giờ liên tục và canh thời gian nấu cho khách luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_05','V1417','阮明',5,'好，我严格等够二十分钟再吃，不会着急夹取。','hǎo ， wǒ yán gé děng gòu èr shí fēn zhōng zài chī ， bú huì zháo jí jiā qǔ 。','Được rồi, em sẽ đợi đủ hai mươi phút mới ăn, không vội gắp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_06','V1417','阿明',6,'我定时提醒大家，菌汤也要多煮一会儿再喝哈。','wǒ dìng shí tí xǐng dà jiā ， jūn tāng yě yào duō zhǔ yī huì er zài hē hā 。','Anh sẽ nhắc giờ cho mọi người, nước canh nấm cũng phải nấu thêm một lát nữa mới uống nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1417_07','V1417','阮明',7,'感谢提醒，野生菌类饮食安全不能马虎。','gǎn xiè tí xǐng ， yě shēng jūn lèi yǐn shí ān quán bù néng mǎ hǔ 。','Cảm ơn anh nhắc nhở, chuyện an toàn khi ăn nấm rừng không thể lơ là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1418','SATN1','网红特色私房菜无线下门店，只能微信预约订位，阮明不会操作预约流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1418','SIT1418','P1','that_bai_nhe','ban_chinh_thuc',NULL,'小众网红私房菜多依靠微信线上预约控流，无线下现场排号机制，境外微信常无法正常加载小程序。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_01','V1418','阮明',1,'陈姐，我想到店直接吃饭，为什么前台说必须提前微信预约呢？','chén jiě ， wǒ xiǎng dào diàn zhí jiē chī fàn ， wèi shén me qián tái shuō bì xū tí qián wēi xìn yù yuē ne ？','Chị Trần ơi, em muốn đến quán ăn trực tiếp, sao lễ tân bảo phải đặt bàn qua WeChat trước vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_02','V1418','陈姐',2,'本店位置少，不接待临时到店客人，只能微信小程序提前订位哦。','běn diàn wèi zhì shǎo ， bù jiē dài lín shí dào diàn kè rén ， zhǐ néng wēi xìn xiǎo chéng xù tí qián dìng wèi ó 。','Quán mình ít chỗ, không nhận khách đến đột xuất đâu, chỉ có thể đặt bàn trước qua mini app WeChat thôi ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_03','V1418','阮明',3,'我的境外微信打不开预约小程序，没有别的预约渠道吗？','wǒ de jìng wài wēi xìn dǎ bù kāi yù yuē xiǎo chéng xù ， méi yǒu bié de yù yuē qú dào ma ？','WeChat nước ngoài của em không mở được mini app đặt bàn, có cách nào khác để đặt không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_04','V1418','陈姐',4,'唯一预约渠道就是小程序，没有电话、线下登记通道的。','wéi yī yù yuē qú dào jiù shì xiǎo chéng xù ， méi yǒu diàn huà 、 xiàn xià dēng jì tōng dào de 。','Kênh đặt bàn duy nhất là mini app thôi, không có gọi điện hay đăng ký trực tiếp tại quán đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_05','V1418','阮明',5,'我找国内同学帮忙预约，明天晚上还有空位吗？','wǒ zhǎo guó nèi tóng xué bāng máng yù yuē ， míng tiān wǎn shàng hái yǒu kòng wèi ma ？','Em nhờ bạn học người trong nước đặt giúp, tối mai còn chỗ trống không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_06','V1418','陈姐',6,'明天晚间座位还有，让同学填写你的到店人数和时间就行哈。','míng tiān wǎn jiān zuò wèi hái yǒu ， ràng tóng xué tián xiě nǐ de dào diàn rén shù hé shí jiān jiù xíng hā 。','Tối mai vẫn còn chỗ, chỉ cần bạn đó điền số người và giờ đến của em là được rồi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1418_07','V1418','阮明',7,'只能拜托室友帮忙预约，今天没法就餐了。','zhǐ néng bài tuō shì yǒu bāng máng yù yuē ， jīn tiān méi fǎ jiù cān le 。','Vậy chỉ còn cách nhờ bạn cùng phòng đặt giúp thôi, hôm nay đành chịu không ăn được rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1419','SATN1','江浙甜食菜馆点菜，菜品甜度太高吃不惯，联系服务员更换清淡口味菜品',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1419','SIT1419','P1','twist','tuy_y',NULL,'江浙菜系普遍偏甜，食客可提前备注减糖，菜品未大量食用前多数店家支持免费更换。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_01','V1419','阮明',1,'小琪，这道糖醋排骨甜度太高，我实在吃不惯能换一道咸鲜菜品吗？','xiǎo qí ， zhè dào táng cù pái gǔ tián dù tài gāo ， wǒ shí zài chī bù guàn néng huàn yī dào xián xiān cài pǐn ma ？','Tiểu Kỳ ơi, món sườn xào chua ngọt này ngọt quá, mình thật sự không quen ăn được, đổi sang món mặn mặn được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_02','V1419','小琪',2,'刚上桌十分钟还没动几口，可以免费更换其他咸口菜品哦。','gāng shàng zhuō shí fēn zhōng hái méi dòng jǐ kǒu ， kě yǐ miǎn fèi gēng huàn qí tā xián kǒu cài pǐn ó 。','Món vừa lên bàn mười phút, chưa đụng mấy đũa, có thể đổi miễn phí sang món mặn khác nha.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_03','V1419','阮明',3,'江浙菜默认甜度都这么高吗，点菜前可以提前备注少糖？','jiāng zhè cài mò rèn tián dù dōu zhè me gāo ma ， diǎn cài qián kě yǐ tí qián bèi zhù shǎo táng ？','Mấy món Giang Chiết mặc định đều ngọt như vậy à, gọi món trước có thể ghi chú ít đường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_04','V1419','小琪',4,'没错，下单时备注少糖，后厨会减少冰糖调味，口感清淡很多嘛。','méi cuò ， xià dān shí bèi zhù shǎo táng ， hòu chú huì jiǎn shǎo bīng táng tiáo wèi ， kǒu gǎn qīng dàn hěn duō ma 。','Đúng rồi, lúc gọi món ghi chú ít đường thì bếp sẽ giảm đường phèn nêm nếm, vị sẽ nhạt hơn nhiều đó.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_05','V1419','阮明',5,'换成清炒虾仁，全程少放糖，麻烦后厨调整口味。','huàn chéng qīng chǎo xiā rén ， quán chéng shǎo fàng táng ， má fán hòu chú tiáo zhěng kǒu wèi 。','Đổi sang tôm xào thanh đạm nhé, cho ít đường thôi, phiền bếp điều chỉnh khẩu vị giúp mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_06','V1419','小琪',6,'我马上通知后厨重做，十分钟新菜就能上桌哈。','wǒ mǎ shàng tōng zhī hòu chú zhòng zuò ， shí fēn zhōng xīn cài jiù néng shàng zhuō hā 。','Mình báo bếp làm lại ngay, mười phút nữa món mới sẽ lên bàn thôi.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1419_07','V1419','阮明',7,'多谢允许更换菜品，下次点菜一定提前备注少糖。','duō xiè yǔn xǔ gēng huàn cài pǐn ， xià cì diǎn cài yí dìng tí qián bèi zhù shǎo táng 。','Cảm ơn đã cho đổi món nha, lần sau gọi món mình sẽ ghi chú ít đường trước luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1420','SATN1','跨城市特色小吃探店，分不清堂食、打包价格差异，询问摊主打包收费标准',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1420','SIT1420','P1','suon_se','tuy_y',NULL,'街边小吃堂食免费提供餐具，打包塑料餐盒单独收取少量打包费，是国内小吃通用收费规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_01','V1420','阮明',1,'李叔，这份特色粉堂食和打包带走，价格是一样的吗？','lǐ shū ， zhè fèn tè sè fěn táng shí hé dǎ bāo dài zǒu ， jià gé shì yī yàng de ma ？','Chú Lý ơi, phần bún đặc sản này ăn tại chỗ với gói mang về giá có giống nhau không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_02','V1420','李叔',2,'价格相同，打包需要额外收取一元打包盒费用哦。','jià gé xiāng tóng ， dǎ bāo xū yào é wài shōu qǔ yī yuán dǎ bāo hé fèi yòng ó 。','Giá như nhau, chỉ là gói mang về thì tính thêm một tệ tiền hộp thôi.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_03','V1420','阮明',3,'打包盒密封性好不好，路上二十分钟汤会不会洒出来？','dǎ bāo hé mì fēng xìng hǎo bù hǎo ， lù shàng èr shí fēn zhōng tāng huì bú huì sǎ chū lái ？','Hộp gói có kín không chú, để hai mươi phút trên đường nước canh có bị đổ ra không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_04','V1420','李叔',4,'加厚密封餐盒，盖子扣紧，短途携带不会漏汤嘛。','jiā hòu mì fēng cān hé ， gài zi kòu jǐn ， duǎn tú xié dài bú huì lòu tāng ma 。','Hộp đựng loại dày, kín, đậy nắp chặt rồi thì đi đường ngắn không lo chảy nước đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_05','V1420','阮明',5,'那打包一份，少放本地秘制甜辣酱。','nà dǎ bāo yī fèn ， shǎo fàng běn dì mì zhì tián là jiàng 。','Vậy gói cho cháu một phần, cho ít tương ớt ngọt đặc sản ở đây thôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_06','V1420','李叔',6,'好嘞，打包盒装好，给你多套一层袋子防漏哈。','hǎo lei ， dǎ bāo hé zhuāng hǎo ， gěi nǐ duō tào yī céng dài zi fáng lòu hā 。','Được rồi, hộp gói xong, chú lồng thêm một lớp túi cho khỏi rò nước nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1420_07','V1420','阮明',7,'清楚打包收费，打包带走回宿舍慢慢吃。','qīng chǔ dǎ bāo shōu fèi ， dǎ bāo dài zǒu huí sù shè màn màn chī 。','Rõ giá gói mang về rồi, cháu mang về ký túc xá ăn từ từ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1421','SATN1','朝鲜族烤肉店自助烤肉，不懂炭火控温、烤肉类熟度，店员上前帮忙指导',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1421','SIT1421','P1','suon_se','ban_chinh_thuc',NULL,'朝鲜族烤肉有专属搭配吃法（生菜包肉），店员会主动指导火候、熟度区分，帮助新手食客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_01','V1421','阮明',1,'善姬，炭火太旺肉一下子烤焦，怎么调节火力大小呢？','shàn jī ， tàn huǒ tài wàng ròu yī xià zi kǎo jiāo ， zěn me tiáo jié huǒ lì dà xiǎo ne ？','Seon-hui ơi, lửa than mạnh quá thịt bị cháy liền, làm sao chỉnh lửa nhỏ lại vậy ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_02','V1421','善姬',2,'把炭火挡板拉开一点散热，五花肉中火慢烤才不会发苦哦。','bǎ tàn huǒ dǎng bǎn lā kāi yì diǎn sàn rè ， wǔ huā ròu zhōng huǒ màn kǎo cái bú huì fā kǔ ó 。','Kéo tấm chắn than ra một chút cho tản nhiệt, thịt ba chỉ nướng lửa vừa mới không bị đắng đâu ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_03','V1421','阮明',3,'牛肉烤到几分熟最合适，全熟会不会肉质发硬？','niú ròu kǎo dào jǐ fēn shú zuì hé shì ， quán shú huì bú huì ròu zhì fā yìng ？','Thịt bò nướng tới mấy phần chín là hợp nhất ạ, chín hẳn thì thịt có bị dai không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_04','V1421','善姬',4,'牛肉烤到七分熟嫩度最好，猪肉必须完全烤熟才能食用嘛。','niú ròu kǎo dào qī fēn shú nèn dù zuì hǎo ， zhū ròu bì xū wán quán kǎo shú cái néng shí yòng ma 。','Thịt bò nướng bảy phần chín là mềm ngon nhất, còn thịt heo thì bắt buộc phải chín hẳn mới ăn được nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_05','V1421','阮明',5,'生菜包肉搭配泡菜一起吃，是本地特色吃法对吧？','shēng cài bāo ròu dā pèi pào cài yì qǐ chī ， shì běn dì tè sè chī fǎ duì ba ？','Cuốn thịt với xà lách ăn kèm kim chi, đây là cách ăn đặc trưng ở đây đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_06','V1421','善姬',6,'没错，搭配蒜片泡菜解腻，很多外国游客都喜欢这种吃法哈。','méi cuò ， dā pèi suàn piàn pào cài jiě nì ， hěn duō wài guó yóu kè dōu xǐ huān zhè zhǒng chī fǎ hā 。','Đúng vậy, ăn kèm kim chi tỏi lát để đỡ ngán, nhiều khách nước ngoài rất thích cách ăn này ạ.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1421_07','V1421','阮明',7,'学会控温技巧，自己烤肉不会烤糊了。','xué huì kòng wēn jì qiǎo ， zì jǐ kǎo ròu bú huì kǎo hú le 。','Học được cách canh lửa rồi, tự nướng thịt sẽ không bị cháy khét nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1422','SATN1','餐厅结账索要纸质发票，留学生不懂发票用途，前台服务员简单解释',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1422','SIT1422','P1','suon_se','ban_chinh_thuc',NULL,'国内消费餐饮可免费开具增值税发票，作为消费维权、单位报销法定凭证，每单仅可开具一次。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_01','V1422','阮明',1,'小周，我结账想要纸质发票，请问发票有什么用处呢？','xiǎo zhōu ， wǒ jié zhàng xiǎng yào zhǐ zhì fā piào ， qǐng wèn fā piào yǒu shén me yòng chǔ ne ？','Tiểu Chu ơi, em thanh toán muốn lấy hóa đơn giấy, cho em hỏi hóa đơn dùng để làm gì ạ?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_02','V1422','小周',2,'国内企业报销、个人维权都需要发票，是消费凭证哦。','guó nèi qǐ yè bào xiāo 、 gè rén wéi quán dōu xū yào fā piào ， shì xiāo fèi píng zhèng ó 。','Trong nước doanh nghiệp thanh toán chi phí hay cá nhân bảo vệ quyền lợi đều cần hóa đơn, đó là chứng từ tiêu dùng ạ.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_03','V1422','阮明',3,'留学生个人就餐，不开公司抬头也能开具发票吗？','liú xué shēng gè rén jiù cān ， bù kāi gōng sī tái tóu yě néng kāi jù fā piào ma ？','Du học sinh ăn cá nhân, không xuất tên công ty thì vẫn xuất được hóa đơn chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_04','V1422','小周',4,'可以直接开个人抬头，纸质发票当场打印交给你嘛。','kě yǐ zhí jiē kāi gè rén tái tóu ， zhǐ zhì fā piào dāng chǎng dǎ yìn jiāo gěi nǐ ma 。','Có thể xuất trực tiếp tên cá nhân, hóa đơn giấy in ngay tại chỗ và đưa cho em luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_05','V1422','阮明',5,'发票丢失之后，还能回来重新打印一份吗？','fā piào diū shī zhī hòu ， hái néng huí lái chóng xīn dǎ yìn yī fèn ma ？','Nếu hóa đơn bị mất rồi, em quay lại xin in lại một bản được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_06','V1422','小周',6,'本店只能打印一次，丢失无法补打，妥善保管票据哈。','běn diàn zhǐ néng dǎ yìn yī cì ， diū shī wú fǎ bǔ dǎ ， tuǒ shàn bǎo guǎn piào jù hā 。','Quán chỉ in được một lần thôi, mất rồi không in bù được đâu, em giữ kỹ hóa đơn nhé.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1422_07','V1422','阮明',7,'明白了，开个人纸质发票留作消费凭证。','míng bái le ， kāi gè rén zhǐ zhì fā piào liú zuò xiāo fèi píng zhèng 。','Em hiểu rồi, xuất hóa đơn giấy tên cá nhân để giữ làm chứng từ tiêu dùng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1423','SATN1','药膳养生菜馆吃饭，分不清药膳食材药性，咨询店长适配自身体质菜品',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1423','SIT1423','P1','twist','chinh_thuc',NULL,'中式药膳讲究体质匹配，热性体质少食温补药材，药膳馆店员会根据食客身体状况推荐适配菜品。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_01','V1423','阮明',1,'王叔，我容易上火长痘，药膳菜品里人参、枸杞这类温补食材能吃吗？','wáng shū ， wǒ róng yì shàng huǒ zhǎng dòu ， yào shàn cài pǐn lǐ rén shēn 、 gǒu qǐ zhè lèi wēn bǔ shí cái néng chī ma ？','Chú Vương ơi, cháu dễ bị nóng trong nổi mụn, những món dược thiện có nhân sâm, kỷ tử loại ôn bổ này cháu ăn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_02','V1423','王叔',2,'人参温补容易加重上火，给你推荐清热的冬瓜百合药膳汤更适配。','rén shēn wēn bǔ róng yì jiā zhòng shàng huǒ ， gěi nǐ tuī jiàn qīng rè de dōng guā bǎi hé yào shàn tāng gèng shì pèi 。','Nhân sâm ôn bổ dễ làm nặng thêm nóng trong, chú gợi ý cháu dùng canh dược thiện đông qua bách hợp thanh nhiệt sẽ hợp hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_03','V1423','阮明',3,'药膳菜都带有中药苦味吗，会不会很难入口？','yào shàn cài dōu dài yǒu zhōng yào kǔ wèi ma ， huì bú huì hěn nán rù kǒu ？','Các món dược thiện đều có vị đắng của thuốc bắc phải không ạ, có khó ăn lắm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_04','V1423','王叔',4,'搭配肉类中和药味，口感鲜香，不会有浓重苦涩感嘛。','dā pèi ròu lèi zhōng hé yào wèi ， kǒu gǎn xiān xiāng ， bú huì yǒu nóng zhòng kǔ sè gǎn ma 。','Kết hợp với thịt để trung hòa vị thuốc, ăn sẽ thơm ngon, không bị đắng chát nồng đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_05','V1423','阮明',5,'那就点一份百合老鸭汤，搭配两道清淡素菜。','nà jiù diǎn yī fèn bǎi hé lǎo yā tāng ， dā pèi liǎng dào qīng dàn sù cài 。','Vậy cháu gọi một phần canh vịt già bách hợp, kèm hai món chay thanh đạm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_06','V1423','王叔',6,'好，后厨减少温补药材，多放清热食材适配你的体质哈。','hǎo ， hòu chú jiǎn shǎo wēn bǔ yào cái ， duō fàng qīng rè shí cái shì pèi nǐ de tǐ zhì hā 。','Được, bếp sẽ giảm bớt dược liệu ôn bổ, cho thêm nguyên liệu thanh nhiệt để hợp thể trạng của cháu.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1423_07','V1423','阮明',7,'多亏专业讲解，选到适合自己体质的养生菜品。','duō kuī zhuān yè jiǎng jiě ， xuǎn dào shì hé zì jǐ tǐ zhì de yǎng shēng cài pǐn 。','Nhờ chú giải thích tận tình mà cháu chọn được món dưỡng sinh hợp với thể trạng của mình.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1424','SATN1','多人宴席包间点菜，服务员提醒冷热荤素搭配，均衡点菜符合中式宴席习惯',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1424','SIT1424','P1','suon_se','ban_chinh_thuc',NULL,'中式多人宴席点菜讲究凉菜、热荤、热素、汤、甜品完整搭配，菜品均衡是宴席待客基本礼仪。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_01','V1424','阮明',1,'阿豪，我们八个人只点四道荤菜，是不是素菜凉菜太少了？','ā háo ， wǒ men bā gè rén zhǐ diǎn sì dào hūn cài ， shì bú shì sù cài liáng cài tài shǎo le ？','A Hào ơi, tám người tụi mình chỉ gọi bốn món mặn, có phải món chay và món nguội hơi ít không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_02','V1424','阿豪',2,'中式宴席讲究冷热、荤素均衡，再加两道凉菜两道素菜搭配更好哦。','zhōng shì yàn xí jiǎng jiū lěng rè 、 hūn sù jūn héng ， zài jiā liǎng dào liáng cài liǎng dào sù cài dā pèi gèng hǎo ó 。','Tiệc kiểu Trung chú trọng cân bằng nóng lạnh, mặn chay, gọi thêm hai món nguội hai món chay nữa sẽ hợp hơn đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_03','V1424','阮明',3,'甜品和汤品需要单独再加吗？','tián pǐn hé tāng pǐn xū yào dān dú zài jiā ma ？','Món tráng miệng với món canh có cần gọi thêm riêng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_04','V1424','阿豪',4,'宴席标配一汤一甜品，饭后解腻，整套菜品结构更完整嘛。','yàn xí biāo pèi yī tāng yī tián pǐn ， fàn hòu jiě nì ， zhěng tào cài pǐn jié gòu gèng wán zhěng ma 。','Tiệc chuẩn phải có một canh một tráng miệng, ăn xong đỡ ngán, cả set món mới đầy đủ.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_05','V1424','阮明',5,'那按你的建议补充凉菜、素菜和甜汤。','nà àn nǐ de jiàn yì bǔ chōng liáng cài 、 sù cài hé tián tāng 。','Vậy theo gợi ý của cậu thì mình bổ sung thêm món nguội, món chay với canh ngọt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_06','V1424','阿豪',6,'这样搭配兼顾所有人口味，冷热交替吃起来更舒服哈。','zhè yàng dā pèi jiān gù suǒ yǒu rén kǒu wèi ， lěng rè jiāo tì chī qǐ lái gèng shū fú hā 。','Như vậy sẽ hợp khẩu vị mọi người, ăn xen kẽ nóng lạnh sẽ thấy dễ chịu hơn đó.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1424_07','V1424','阮明',7,'感谢提醒，不然点菜结构单一不够体面。','gǎn xiè tí xǐng ， bù rán diǎn cài jié gòu dān yī bù gòu tǐ miàn 。','Cảm ơn cậu nhắc nhở, không thì gọi món kiểu này nhìn đơn điệu quá không đẹp mắt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1425','SATN1','异国风味融合中餐厅打卡，想搭配本地黄酒，询问黄酒饮用方式与酒精度',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1425','SIT1425','P1','twist','tuy_y',NULL,'黄酒是中式传统佐餐酒，温热饮用是千年饮食习惯，适配红烧、卤味等重口味中式菜肴。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_01','V1425','阮明',1,'阿远，搭配中餐的黄酒酒精度高吗，直接常温喝还是加热饮用？','ā yuǎn ， dā pèi zhōng cān de huáng jiǔ jiǔ jīng dù gāo ma ， zhí jiē cháng wēn hē hái shì jiā rè yǐn yòng ？','A Viễn ơi, rượu vàng ăn kèm món Trung độ cồn cao không, uống nguội bình thường hay phải hâm nóng lên?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_02','V1425','阿远',2,'黄酒十二度左右，国内习惯温热饮用，暖胃口感更柔和哦。','huáng jiǔ shí èr dù zuǒ yòu ， guó nèi xí guàn wēn rè yǐn yòng ， nuǎn wèi kǒu gǎn gèng róu hé ó 。','Rượu vàng khoảng mười hai độ, trong nước thường uống ấm, ấm bụng vị cũng dịu hơn nhiều đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_03','V1425','阮明',3,'不加任何配料直接温酒，还是要搭配枸杞红枣一起煮？','bù jiā rèn hé pèi liào zhí jiē wēn jiǔ ， hái shì yào dā pèi gǒu qǐ hóng zǎo yì qǐ zhǔ ？','Không cho thêm gì hâm ấm trực tiếp, hay phải nấu kèm kỷ tử táo đỏ vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_04','V1425','阿远',4,'纯黄酒温煮即可，想甜一点再加几颗红枣，不强制搭配辅料嘛。','chún huáng jiǔ wēn zhǔ jí kě ， xiǎng tián yì diǎn zài jiā jǐ kē hóng zǎo ， bù qiáng zhì dā pèi fǔ liào ma 。','Rượu vàng nguyên chất hâm ấm là được rồi, muốn ngọt hơn thì cho thêm mấy trái táo đỏ, không bắt buộc phải kèm gì cả.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_05','V1425','阮明',5,'一杯黄酒搭配什么菜品食用风味更协调？','yī bēi huáng jiǔ dā pèi shén me cài pǐn shí yòng fēng wèi gèng xié tiáo ？','Một ly rượu vàng ăn kèm món gì thì vị hợp nhất vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_06','V1425','阿远',6,'红烧肉类、菌菇菜适配黄酒，清淡海鲜搭配会掩盖酒香哈。','hóng shāo ròu lèi 、 jūn gū cài shì pèi huáng jiǔ ， qīng dàn hǎi xiān dā pèi huì yǎn gài jiǔ xiāng hā 。','Thịt kho tàu, món nấm hợp với rượu vàng, còn hải sản thanh đạm ăn kèm sẽ át mất hương rượu đó.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1425_07','V1425','阮明',7,'那就温一小壶黄酒，配桌上红烧牛肉品尝。','nà jiù wēn yī xiǎo hú huáng jiǔ ， pèi zhuō shàng hóng shāo niú ròu pǐn cháng 。','Vậy hâm một bình nhỏ rượu vàng, ăn kèm với thịt bò kho trên bàn thử xem sao.',NULL) ON CONFLICT DO NOTHING;
