INSERT INTO journeys (id,name,target_persona,description) VALUES ('J1','Đến nơi & ổn định ban đầu','P1','Từ lúc lên máy bay đến khi ổn định chỗ ở, mở tài khoản, có SIM/thanh toán điện tử') ON CONFLICT DO NOTHING;
