-- ============================================================
-- SCHEMA 15 BẢNG + 2 CỘT MỞ RỘNG CHO NỘI DUNG TIẾNG TRUNG
-- FILE FINAL: 459 situations, dựa trên full_379_scenes_v3_final.sql (0 dòng đổi/xóa,
-- chỉ thêm 564 dòng hội thoại mới). pinyin + text_vi đã điền đầy đủ,
-- attitude_marker_id đã rà soát theo rightmost-marker heuristic. Mọi INSERT có ON CONFLICT DO NOTHING.
-- ============================================================

CREATE TABLE IF NOT EXISTS domains (id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT);
CREATE TABLE IF NOT EXISTS subdomains (id TEXT PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES domains(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS situations (id TEXT PRIMARY KEY, subdomain_id TEXT NOT NULL REFERENCES subdomains(id), name TEXT NOT NULL, description TEXT, difficulty_level TEXT);
CREATE TABLE IF NOT EXISTS personas (id TEXT PRIMARY KEY, name TEXT NOT NULL, age INTEGER, background TEXT, personality_traits TEXT);
CREATE TABLE IF NOT EXISTS attitude_markers (id TEXT PRIMARY KEY, marker TEXT NOT NULL, meaning TEXT);
CREATE TABLE IF NOT EXISTS dialogue_variants (
  id TEXT PRIMARY KEY,
  situation_id TEXT NOT NULL REFERENCES situations(id),
  persona_id TEXT NOT NULL REFERENCES personas(id),
  outcome_type TEXT NOT NULL,
  register_level TEXT NOT NULL,
  context_note TEXT,
  cultural_note TEXT
);
CREATE TABLE IF NOT EXISTS dialogue_lines (
  id TEXT PRIMARY KEY,
  variant_id TEXT NOT NULL REFERENCES dialogue_variants(id),
  speaker TEXT NOT NULL,
  order_index INTEGER NOT NULL,
  text_zh TEXT NOT NULL,
  pinyin TEXT,
  text_vi TEXT,
  attitude_marker_id TEXT REFERENCES attitude_markers(id)
);
CREATE TABLE IF NOT EXISTS functions (id TEXT PRIMARY KEY, group_name TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS situation_function (situation_id TEXT NOT NULL REFERENCES situations(id), function_id TEXT NOT NULL REFERENCES functions(id), PRIMARY KEY (situation_id, function_id));
CREATE TABLE IF NOT EXISTS cultural_patterns (id TEXT PRIMARY KEY, pattern_name TEXT NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS situation_cultural_pattern (situation_id TEXT NOT NULL REFERENCES situations(id), cultural_pattern_id TEXT NOT NULL REFERENCES cultural_patterns(id), PRIMARY KEY (situation_id, cultural_pattern_id));
CREATE TABLE IF NOT EXISTS grammar_points (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS situation_grammar (situation_id TEXT NOT NULL REFERENCES situations(id), grammar_id TEXT NOT NULL REFERENCES grammar_points(id), PRIMARY KEY (situation_id, grammar_id));
CREATE TABLE IF NOT EXISTS journeys (id TEXT PRIMARY KEY, name TEXT NOT NULL, target_persona TEXT, description TEXT);
CREATE TABLE IF NOT EXISTS journey_steps (id TEXT PRIMARY KEY, journey_id TEXT NOT NULL REFERENCES journeys(id), situation_id TEXT NOT NULL REFERENCES situations(id), step_order INTEGER NOT NULL);























































































































































































































































































































































































































































































